/* ========== 音乐播放器 ========== */
.poem-music-wrapper {
  text-align: center;
  margin: 0 auto 2.5rem;
  max-width: 680px;
}
.music-player {
  display: flex;
  justify-content: center;
  margin-bottom: 0.3rem;
}
.music-player audio {
  display: none;
}
.music-tip {
  color: #777;
  font-size: 0.78rem;
  margin-top: 0.4rem;
  letter-spacing: 2px;
}
.music-toggle {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 0.6rem;
  padding: 8px 20px;
  border: 1px solid rgba(139, 92, 246, 0.3);
  border-radius: 20px;
  background: rgba(139, 92, 246, 0.08);
  color: #b8a9c9;
  font-size: 0.82rem;
  cursor: pointer;
  transition: all 0.3s ease;
  letter-spacing: 1px;
  outline: none;
}
.music-toggle:hover {
  background: rgba(139, 92, 246, 0.15);
  border-color: rgba(139, 92, 246, 0.5);
  color: #d0c4e6;
}
.music-toggle.paused {
  border-color: rgba(255, 255, 255, 0.15);
  background: rgba(255, 255, 255, 0.03);
  color: #777;
}
.music-toggle.paused:hover {
  background: rgba(139, 92, 246, 0.1);
  border-color: rgba(139, 92, 246, 0.4);
  color: #b8a9c9;
}
.music-toggle .toggle-icon {
  font-size: 1rem;
  line-height: 1;
}
.music-toggle .toggle-status {
  font-size: 0.72rem;
  opacity: 0.7;
  margin-left: 2px;
}

/* ========== 诗卷容器 ========== */
.poem-container {
  max-width: 680px;
  margin: 0 auto 3rem;
  padding: 3rem 2.5rem 2.5rem;
  background: linear-gradient(160deg, #0d1117 0%, #161b22 40%, #1a2332 100%);
  border-radius: 20px;
  box-shadow:
    0 25px 60px rgba(0, 0, 0, 0.4),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
  position: relative;
  overflow: hidden;
}
/* 顶部装饰光晕 */
.poem-container::before {
  content: '';
  position: absolute;
  top: -80px;
  left: 50%;
  transform: translateX(-50%);
  width: 300px;
  height: 160px;
  background: radial-gradient(ellipse, rgba(139, 92, 246, 0.08) 0%, transparent 70%);
  pointer-events: none;
}
/* 底部微光 */
.poem-container::after {
  content: '';
  position: absolute;
  bottom: -60px;
  right: -60px;
  width: 200px;
  height: 200px;
  background: radial-gradient(circle, rgba(232, 213, 183, 0.04) 0%, transparent 70%);
  pointer-events: none;
}

/* ========== 诗题 ========== */
.poem-title {
  text-align: center;
  color: #e8d5b7;
  font-size: 1.8rem;
  font-weight: 600;
  margin-bottom: 0.6rem;
  letter-spacing: 8px;
  position: relative;
  z-index: 1;
  text-shadow: 0 2px 12px rgba(232, 213, 183, 0.15);
}
.poem-subtitle {
  text-align: center;
  color: rgba(232, 213, 183, 0.4);
  font-size: 0.82rem;
  margin-bottom: 2rem;
  letter-spacing: 4px;
  position: relative;
  z-index: 1;
}
.poem-divider {
  width: 80px;
  height: 1px;
  background: linear-gradient(to right, transparent, rgba(232, 213, 183, 0.5), transparent);
  margin: 0 auto 2.2rem;
  position: relative;
  z-index: 1;
}

/* ========== 诗句 ========== */
.poem-body {
  position: relative;
  z-index: 1;
}
.poem-stanza {
  text-align: center;
  margin-bottom: 2rem;
}
.poem-stanza:last-of-type {
  margin-bottom: 0;
}
.poem-line {
  color: #c9b896;
  font-size: 1.15rem;
  line-height: 2.6;
  letter-spacing: 4px;
  font-weight: 300;
  transition: all 0.3s ease;
  position: relative;
}
.poem-line:hover {
  color: #f0e6d0;
  text-shadow: 0 0 20px rgba(232, 213, 183, 0.15);
}

/* ========== 印章 ========== */
.poem-seal {
  text-align: right;
  margin-top: 2.5rem;
  padding-top: 1.8rem;
  border-top: 1px solid rgba(232, 213, 183, 0.1);
  position: relative;
  z-index: 1;
}
.poem-seal-text {
  display: inline-block;
  color: #b33a3a;
  font-size: 0.85rem;
  letter-spacing: 3px;
  border: 2px solid #b33a3a;
  padding: 5px 14px;
  border-radius: 3px;
  opacity: 0.75;
  font-weight: 500;
  transform: rotate(-2deg);
}

/* ========== 记·散文 ========== */
.reflect-section {
  max-width: 680px;
  margin: 0 auto 3rem;
  padding: 2.2rem 2rem;
  background: linear-gradient(135deg, rgba(255,255,255,0.015) 0%, rgba(255,255,255,0.005) 100%);
  border-radius: 14px;
  border-left: 3px solid rgba(118, 75, 162, 0.6);
  backdrop-filter: blur(2px);
}
.reflect-section h3 {
  color: #b8a9c9;
  font-size: 1.05rem;
  margin-bottom: 1.2rem;
  letter-spacing: 3px;
  font-weight: 500;
}
.reflect-section p {
  color: #999;
  line-height: 2.1;
  font-size: 0.93rem;
  margin-bottom: 1rem;
  text-indent: 2em;
}
.reflect-section p:last-child {
  margin-bottom: 0;
}

/* ========== 路·时间线 ========== */
.timeline-section {
  max-width: 680px;
  margin: 0 auto 3rem;
}
.timeline-section h3 {
  text-align: center;
  color: #b8a9c9;
  font-size: 1.05rem;
  margin-bottom: 2.2rem;
  letter-spacing: 3px;
  font-weight: 500;
}
.life-timeline {
  position: relative;
  padding-left: 2.5rem;
}
.life-timeline::before {
  content: '';
  position: absolute;
  left: 6px;
  top: 8px;
  bottom: 8px;
  width: 1px;
  background: linear-gradient(to bottom,
    transparent,
    rgba(118, 75, 162, 0.5) 10%,
    rgba(102, 126, 234, 0.5) 50%,
    rgba(118, 75, 162, 0.5) 90%,
    transparent
  );
}
.timeline-item {
  position: relative;
  margin-bottom: 1.8rem;
  padding-left: 1.2rem;
}
.timeline-item:last-child {
  margin-bottom: 0;
}
.timeline-item::before {
  content: '';
  position: absolute;
  left: -2.5rem;
  top: 7px;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #1a1a2e;
  border: 2px solid #764ba2;
  box-shadow: 0 0 8px rgba(118, 75, 162, 0.3);
  transition: all 0.3s ease;
}
.timeline-item:hover::before {
  background: #764ba2;
  box-shadow: 0 0 12px rgba(118, 75, 162, 0.6);
}
.timeline-item .tl-year {
  color: #b8a9c9;
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: 2px;
}
.timeline-item .tl-text {
  color: #888;
  font-size: 0.9rem;
  line-height: 1.8;
  margin-top: 0.35rem;
}

/* ========== 悟·寄语 ========== */
.quote-section {
  max-width: 600px;
  margin: 3rem auto 2rem;
  text-align: center;
  padding: 2.5rem 2rem;
  position: relative;
}
.quote-section::before,
.quote-section::after {
  content: '';
  position: absolute;
  width: 60px;
  height: 1px;
  background: linear-gradient(to right, transparent, rgba(118, 75, 162, 0.3), transparent);
  left: 50%;
  transform: translateX(-50%);
}
.quote-section::before { top: 0; }
.quote-section::after { bottom: 0; }
.quote-mark {
  font-size: 3.5rem;
  color: rgba(118, 75, 162, 0.2);
  line-height: 1;
  font-family: Georgia, serif;
}
.quote-text {
  color: #aaa;
  font-size: 1rem;
  line-height: 2.2;
  font-style: italic;
  margin: 1.2rem 0;
  letter-spacing: 1px;
}
.quote-author {
  color: #666;
  font-size: 0.82rem;
  letter-spacing: 1px;
}

/* ========== 尾声 ========== */
.post-epilogue {
  max-width: 680px;
  margin: 2rem auto 0;
  padding: 1.5rem 2rem;
  text-align: center;
  border-top: 1px solid rgba(255,255,255,0.05);
  color: #888;
  font-size: 0.9rem;
  line-height: 2;
  letter-spacing: 1px;
}
.post-epilogue em {
  color: #b8a9c9;
  font-style: normal;
}






      您的浏览器不支持音频播放



    ♫
    背包
    播放中




(function() {
  var audio = document.getElementById('bgMusic');
  var btn = document.getElementById('musicToggle');
  if (!audio || !btn) return;

  function updateBtn() {
    var status = btn.querySelector('.toggle-status');
    var icon = btn.querySelector('.toggle-icon');
    if (audio.paused) {
      status.textContent = '已暂停';
      icon.textContent = '♪';
      btn.classList.add('paused');
    } else {
      status.textContent = '播放中';
      icon.textContent = '♫';
      btn.classList.remove('paused');
    }
  }

  btn.addEventListener('click', function() {
    if (audio.paused) {
      audio.play();
    } else {
      audio.pause();
    }
  });

  audio.addEventListener('play', updateBtn);
  audio.addEventListener('pause', updateBtn);

  // 尝试自动播放
  audio.play().catch(function() {
    updateBtn();
    // 浏览器阻止自动播放，监听首次交互后播放
    var played = false;
    function tryPlay() {
      if (played) return;
      played = true;
      audio.play();
      document.removeEventListener('click', tryPlay);
      document.removeEventListener('scroll', tryPlay);
      document.removeEventListener('touchstart', tryPlay);
      document.removeEventListener('keydown', tryPlay);
    }
    document.addEventListener('click', tryPlay);
    document.addEventListener('scroll', tryPlay);
    document.addEventListener('touchstart', tryPlay);
    document.addEventListener('keydown', tryPlay);
  });
})();




  京华客梦
  九六生人 · 京城漂泊客



      九六逢而立，客京梦未还。
      十载羁京华，流年岁已阑。


      欲立身御霜，世事多违愿。
      心期终未遂，困顿市井间。


      上需奉亲老，下抚稚子颜。
      携家长漂泊，望归终未还。


      半生多跌宕，唯余叹惘然。
      杯空无醇酒，心底起尘烦。


      昔嗟而立远，今至已惘然。


      丙子年生




贰 · 记
  关于这首诗
  九六年生人，属鼠。古语云三十而立，可这"立"字何其沉重。十年北漂，从最初的满腔热血到如今的疲惫不堪，时间像一把钝刀，一点一点磨去了棱角，也磨去了当初的豪言壮语。
  上有年迈双亲需要奉养，下有稚嫩孩童需要抚育。一家人的生计压在肩上，漂泊在京城，想回却回不去——故乡已无谋生之所，京城亦无安身之地。进退两难，左右维谷。
  蹉跎三十有余，回头望去，竟如虚度。八方谋业，辗转腾挪，终究一事无成。不是没有努力，只是世事多违愿；不是没有梦想，只是现实太骨感。杯中无酒，心底有尘，唯有这惘然，日复一日。


叁 · 路
  时光碎片


      1996
      生于乡野，懵懂不知世事艰


      2016
      初入京城，以为天地广阔大有可为


      2018
      初尝碰壁，方知人间冷暖自知


      2020
      疫中困顿，世事无常更觉漂泊


      2023
      为人夫，结发携手共担风雨


      2024
      为人父，肩上又添千钧重担


      2026
      蹉跎岁月三十载，而立未立，惘然独白




肆 · 悟
  "

    人生天地之间，若白驹之过隙，忽然而已。
    然虽蹉跎，亦不可弃。
    半生跌宕，终是经历；
    一事无成，未必终局。
    且将惘然付杯中，
    明日再行一程。

  —— 写给三十有余的自己



  三十有余，不是终点，只是半程。
  蹉跎了光阴，但尚未蹉跎余生。
  杯空可以再满，心烦可以再静。
  愿每一个困顿市井间的灵魂，终能等到属于自己的那束光。

前言 在实际场景中，系统涉及矿工管理、设备监控、安全预警、生产调度等多个模块。刚写接口时，我直接用Entity接收参数和返回结果，觉得简单省事。后来需求不断变化：矿工密码不能返回前端、设备创建和修改的字段不同、不同接口返回不同字段——直接用Entity根本搞不定。有一次前端联调时，矿工列表接口把密码和盐值全部返回了，差点酿成安全事故。从那以后，我在实际项目中严格做DTO&#x2F;VO分层，再也没有出现过类似问题。 为什么不能直接用Entity？问题1：敏感信息泄露// ---------------------------------------------------------------// 实际项目 - 矿工管理模块// ❌ 直接返回Entity，敏感信息全部暴露// ---------------------------------------------------------------@GetMapping(&quot;/miner/&#123;id&#125;&quot;)public Miner getById(@PathVariable Long id) &#123; return minerService.getById(id);&#125;// 返回结果——密码、盐值等敏感信息全部暴露！// ---------------------------------------------------------------// JSON响应（灾难！）// ---------------------------------------------------------------&#123; &quot;id&quot;: 1, &quot;name&quot;: &quot;王大山&quot;, &quot;password&quot;: &quot;e10adc3949ba59abbe56e057f20f883e&quot;, // 泄露！ &quot;salt&quot;: &quot;abc123&quot;, // 泄露！ &quot;idCard&quot;: &quot;140521199001011234&quot;, // 身份证泄露！ &quot;email&quot;: &quot;wangdasan@mine.com&quot;, &quot;phone&quot;: &quot;13800138000&quot;, &quot;emergencyContact&quot;: &quot;李四 13900139000&quot; // 紧急联系人泄露！&#125;
问题2：字段冗余// ---------------------------------------------------------------// ❌ 返回了前端不需要的字段，带宽浪费// ---------------------------------------------------------------&#123; &quot;id&quot;: 1, &quot;name&quot;: &quot;王大山&quot;, &quot;deptId&quot;: 5, // 前端不需要ID，需要名称 &quot;workAreaId&quot;: 12, // 前端不需要ID，需要名称 &quot;deleted&quot;: 0, // 前端不需要 &quot;version&quot;: 3, // 前端不需要 &quot;createBy&quot;: 100, // 前端不需要 &quot;updateBy&quot;: 200 // 前端不需要&#125;
问题3：创建和修改字段不同// ---------------------------------------------------------------// 智慧矿山 - 矿工创建 vs 修改的参数差异// ---------------------------------------------------------------// ❌ 创建时不需要id，修改时必须传id@PostMapping(&quot;/miner&quot;)public void add(@RequestBody Miner miner) &#123; // miner.getId()可能被恶意传入&#125;@PutMapping(&quot;/miner&quot;)public void update(@RequestBody Miner miner) &#123; // miner.getId()可能为空&#125;// ❌ 创建矿工时需要密码，修改时密码单独处理// ❌ 创建时不需要状态，修改时可能改状态// ❌ 用同一个Entity根本无法区分
问题4：关联数据无法返回// ---------------------------------------------------------------// ❌ 矿工对象没有部门名称和工作面名称，前端需要展示// ---------------------------------------------------------------// Miner Entity只有 deptId 和 workAreaId// 但前端列表需要展示：部门名称、工作面名称// Entity无法满足！
分层设计各层对象职责DTO&#x2F;VO 分层架构图
Entity → 数据库映射，与表结构严格对应 DTO → 接口入参，接收前端传入的数据 VO → 接口出参，返回给前端的数据 QueryDTO → 查询参数，封装查询条件 CreateDTO → 创建参数 UpdateDTO → 更新参数
对象流转对象流转路径
前端 → CreateDTO → Service → Entity → 数据库 数据库 → Entity → Service → VO → 前端 前端 → QueryDTO → Service → PageResult → 前端
实战：矿工管理模块Entity// ---------------------------------------------------------------// 实际项目 - 矿工 Entity// 与数据库表一一对应，包含所有字段// ---------------------------------------------------------------@Data@TableName(&quot;biz_miner&quot;)public class Miner &#123; @TableId(type = IdType.AUTO) private Long id; private String name; // 姓名 private String password; // 密码（加密后） private String salt; // 盐值 private String idCard; // 身份证号 private String email; // 邮箱 private String phone; // 手机号 private String emergencyContact; // 紧急联系人 private Integer age; // 年龄 private Long deptId; // 部门ID private Long workAreaId; // 工作面ID private MinerStatus status; // 状态 @Version private Integer version; @TableLogic @TableField(select = false) private Integer deleted; @TableField(fill = FieldFill.INSERT) private Long createBy; @TableField(fill = FieldFill.INSERT) private LocalDateTime createTime; @TableField(fill = FieldFill.INSERT_UPDATE) private Long updateBy; @TableField(fill = FieldFill.INSERT_UPDATE) private LocalDateTime updateTime;&#125;
CreateDTO// ---------------------------------------------------------------// 实际项目 - 创建矿工 DTO// 只包含创建时需要的字段// 带完整的校验注解// ---------------------------------------------------------------@Datapublic class MinerCreateDTO &#123; @NotBlank(message = &quot;姓名不能为空&quot;) @Size(min = 2, max = 20, message = &quot;姓名长度2-20&quot;) private String name; @NotBlank(message = &quot;密码不能为空&quot;) @Size(min = 6, max = 20, message = &quot;密码长度6-20&quot;) private String password; @NotBlank(message = &quot;身份证号不能为空&quot;) @Pattern(regexp = &quot;^\\d&#123;17&#125;[\\dXx]$&quot;, message = &quot;身份证号格式不正确&quot;) private String idCard; @Email(message = &quot;邮箱格式不正确&quot;) private String email; @Phone(message = &quot;手机号格式不正确&quot;) private String phone; @Size(max = 50, message = &quot;紧急联系人不能超过50字&quot;) private String emergencyContact; @NotNull(message = &quot;年龄不能为空&quot;) @Min(18) @Max(65) private Integer age; @NotNull(message = &quot;部门不能为空&quot;) private Long deptId; @NotNull(message = &quot;工作面不能为空&quot;) private Long workAreaId;&#125;
UpdateDTO// ---------------------------------------------------------------// 实际项目 - 更新矿工 DTO// 必须传id，其他字段可选// ---------------------------------------------------------------@Datapublic class MinerUpdateDTO &#123; @NotNull(message = &quot;ID不能为空&quot;) private Long id; @Size(min = 2, max = 20, message = &quot;姓名长度2-20&quot;) private String name; @Email(message = &quot;邮箱格式不正确&quot;) private String email; @Phone(message = &quot;手机号格式不正确&quot;) private String phone; @Size(max = 50, message = &quot;紧急联系人不能超过50字&quot;) private String emergencyContact; @Min(18) @Max(65) private Integer age; private Long deptId; private Long workAreaId; private MinerStatus status;&#125;
QueryDTO// ---------------------------------------------------------------// 实际项目 - 矿工查询 DTO// 封装查询条件// ---------------------------------------------------------------@Data@EqualsAndHashCode(callSuper = true)public class MinerQueryDTO extends PageQueryDTO &#123; private String keyword; // 姓名/手机号模糊搜索 private MinerStatus status; // 状态筛选 private Long deptId; // 部门筛选 private Long workAreaId; // 工作面筛选&#125;// ---------------------------------------------------------------// 通用分页查询基类// ---------------------------------------------------------------@Datapublic class PageQueryDTO &#123; @RequestParam(defaultValue = &quot;1&quot;) private Integer page; @RequestParam(defaultValue = &quot;10&quot;) private Integer size; @RequestParam(defaultValue = &quot;id&quot;) private String sortField; @RequestParam(defaultValue = &quot;DESC&quot;) private String sortOrder;&#125;
VO// ---------------------------------------------------------------// 实际项目 - 矿工 VO（详情页）// 只包含前端需要的字段，敏感信息已剔除// ---------------------------------------------------------------@Data@JsonInclude(JsonInclude.Include.NON_NULL)public class MinerVO &#123; @JsonSerialize(using = ToStringSerializer.class) private Long id; private String name; private String phone; private String email; private Integer age; private MinerStatus status; private String statusDesc; private Long deptId; private String deptName; // 关联查询的部门名称 private Long workAreaId; private String workAreaName; // 关联查询的工作面名称 @JsonFormat(pattern = &quot;yyyy-MM-dd HH:mm:ss&quot;) private LocalDateTime createTime; @JsonFormat(pattern = &quot;yyyy-MM-dd HH:mm:ss&quot;) private LocalDateTime updateTime;&#125;// ---------------------------------------------------------------// 矿工简要 VO（列表页，字段更少）// ---------------------------------------------------------------@Data@JsonInclude(JsonInclude.Include.NON_NULL)public class MinerSimpleVO &#123; @JsonSerialize(using = ToStringSerializer.class) private Long id; private String name; private String phone; private MinerStatus status; private String statusDesc; private String deptName; private String workAreaName;&#125;
Controller// ---------------------------------------------------------------// 实际项目 - 矿工管理 Controller// 严格使用DTO入参和VO出参// ---------------------------------------------------------------@RestController@RequestMapping(&quot;/miner&quot;)@RequiredArgsConstructor@Tag(name = &quot;矿工管理&quot;)public class MinerController &#123; private final MinerService minerService; @Operation(summary = &quot;查询矿工列表&quot;) @GetMapping(&quot;/list&quot;) public Result&lt;PageResult&lt;MinerSimpleVO&gt;&gt; list(@Valid MinerQueryDTO query) &#123; return Result.success(minerService.list(query)); &#125; @Operation(summary = &quot;查询矿工详情&quot;) @GetMapping(&quot;/&#123;id&#125;&quot;) public Result&lt;MinerVO&gt; getById(@PathVariable Long id) &#123; return Result.success(minerService.getDetail(id)); &#125; @Operation(summary = &quot;新增矿工&quot;) @PostMapping public Result&lt;Void&gt; add(@RequestBody @Valid MinerCreateDTO dto) &#123; minerService.add(dto); return Result.success(); &#125; @Operation(summary = &quot;修改矿工&quot;) @PutMapping public Result&lt;Void&gt; update(@RequestBody @Valid MinerUpdateDTO dto) &#123; minerService.update(dto); return Result.success(); &#125; @Operation(summary = &quot;删除矿工&quot;) @DeleteMapping(&quot;/&#123;id&#125;&quot;) public Result&lt;Void&gt; delete(@PathVariable Long id) &#123; minerService.delete(id); return Result.success(); &#125;&#125;
Service转换// ---------------------------------------------------------------// 实际项目 - 矿工管理 Service实现// 使用MapStruct进行对象转换// ---------------------------------------------------------------@Service@RequiredArgsConstructor@Slf4jpublic class MinerServiceImpl extends ServiceImpl&lt;MinerMapper, Miner&gt; implements MinerService &#123; private final MinerConverter minerConverter; private final DeptService deptService; private final WorkAreaService workAreaService; private final BCryptPasswordEncoder passwordEncoder; @Override @Transactional(rollbackFor = Exception.class) public void add(MinerCreateDTO dto) &#123; // 1. 校验身份证号唯一 if (lambdaQuery().eq(Miner::getIdCard, dto.getIdCard()).exists()) &#123; throw new BusinessException(&quot;身份证号已存在&quot;); &#125; // 2. DTO → Entity（MapStruct转换） Miner miner = minerConverter.toEntity(dto); miner.setPassword(passwordEncoder.encode(dto.getPassword())); miner.setStatus(MinerStatus.ON_DUTY); // 3. 保存 save(miner); log.info(&quot;矿工创建成功: id=&#123;&#125;, name=&#123;&#125;&quot;, miner.getId(), miner.getName()); &#125; @Override public MinerVO getDetail(Long id) &#123; Miner miner = getById(id); if (miner == null) &#123; throw new BusinessException(&quot;矿工不存在&quot;); &#125; // Entity → VO（MapStruct转换） MinerVO vo = minerConverter.toVO(miner); vo.setStatusDesc(miner.getStatus().getDesc()); // 关联查询部门名称 if (miner.getDeptId() != null) &#123; Dept dept = deptService.getById(miner.getDeptId()); if (dept != null) &#123; vo.setDeptName(dept.getName()); &#125; &#125; // 关联查询工作面名称 if (miner.getWorkAreaId() != null) &#123; WorkArea workArea = workAreaService.getById(miner.getWorkAreaId()); if (workArea != null) &#123; vo.setWorkAreaName(workArea.getName()); &#125; &#125; return vo; &#125; @Override public PageResult&lt;MinerSimpleVO&gt; list(MinerQueryDTO query) &#123; // 1. 构建查询条件 LambdaQueryWrapper&lt;Miner&gt; wrapper = new LambdaQueryWrapper&lt;Miner&gt;() .like(StringUtils.isNotBlank(query.getKeyword()), Miner::getName, query.getKeyword()) .eq(query.getStatus() != null, Miner::getStatus, query.getStatus()) .eq(query.getDeptId() != null, Miner::getDeptId, query.getDeptId()) .eq(query.getWorkAreaId() != null, Miner::getWorkAreaId, query.getWorkAreaId()) .orderByDesc(Miner::getCreateTime); // 2. 分页查询 Page&lt;Miner&gt; page = this.page(new Page&lt;&gt;(query.getPage(), query.getSize()), wrapper); // 3. 批量转换 + 批量查询关联数据 List&lt;MinerSimpleVO&gt; voList = minerConverter.toSimpleVOList(page.getRecords()); // 批量填充部门名称 Set&lt;Long&gt; deptIds = page.getRecords().stream() .map(Miner::getDeptId) .filter(Objects::nonNull) .collect(Collectors.toSet()); if (!deptIds.isEmpty()) &#123; Map&lt;Long, String&gt; deptNameMap = deptService.listByIds(deptIds).stream() .collect(Collectors.toMap(Dept::getId, Dept::getName)); voList.forEach(vo -&gt; vo.setDeptName(deptNameMap.get(vo.getDeptId()))); &#125; // 批量填充工作面名称（同理省略） return PageResult.from(page, voList); &#125;&#125;
MapStruct优雅转换手动BeanUtils.copyProperties容易遗漏字段，MapStruct在编译期生成代码，类型安全且性能极好： // ---------------------------------------------------------------// 实际项目 - 矿工对象转换器// 编译期自动生成实现类，零反射，高性能// ---------------------------------------------------------------@Mapper(componentModel = &quot;spring&quot;)public interface MinerConverter &#123; Miner toEntity(MinerCreateDTO dto); Miner toEntity(MinerUpdateDTO dto); MinerVO toVO(Miner miner); MinerSimpleVO toSimpleVO(Miner miner); List&lt;MinerSimpleVO&gt; toSimpleVOList(List&lt;Miner&gt; miners); // 自定义映射：状态描述 @Mapping(source = &quot;status.code&quot;, target = &quot;statusCode&quot;) @Mapping(source = &quot;status.desc&quot;, target = &quot;statusDesc&quot;) MinerVO toVOWithStatus(Miner miner); // 更新时忽略null值 @BeanMapping(nullValuePropertyMappingStrategy = NullValuePropertyMappingStrategy.IGNORE) void updateFromDTO(MinerUpdateDTO dto, @MappingTarget Miner miner);&#125;
MapStruct生成的代码（编译后）// ---------------------------------------------------------------// MapStruct编译期自动生成的实现类// 可以看到是纯setter赋值，零反射// ---------------------------------------------------------------@Componentpublic class MinerConverterImpl implements MinerConverter &#123; @Override public Miner toEntity(MinerCreateDTO dto) &#123; if (dto == null) &#123; return null; &#125; Miner miner = new Miner(); miner.setName(dto.getName()); miner.setIdCard(dto.getIdCard()); miner.setEmail(dto.getEmail()); miner.setPhone(dto.getPhone()); miner.setEmergencyContact(dto.getEmergencyContact()); miner.setAge(dto.getAge()); miner.setDeptId(dto.getDeptId()); miner.setWorkAreaId(dto.getWorkAreaId()); return miner; &#125; @Override public MinerSimpleVO toSimpleVO(Miner miner) &#123; if (miner == null) &#123; return null; &#125; MinerSimpleVO vo = new MinerSimpleVO(); vo.setId(miner.getId()); vo.setName(miner.getName()); vo.setPhone(miner.getPhone()); vo.setStatus(miner.getStatus()); // ... 纯setter，零反射 return vo; &#125;&#125;
分层原则
原则 说明 违反后果
Entity不出Controller 只在Service和Mapper层使用 敏感信息泄露、前后端耦合
DTO只做入参 不返回给前端 字段职责不清
VO只做出参 不接收前端参数 入参出参混淆
QueryDTO封装查询条件 不混用DTO 查询条件与业务参数混杂
创建和更新分开 CreateDTO和UpdateDTO 字段校验无法区分
设备管理模块分层示例// ---------------------------------------------------------------// 实际项目 - 设备管理模块// 展示不同模块的分层设计// ---------------------------------------------------------------// ==================== Entity ====================@Data@TableName(&quot;biz_equipment&quot;)public class Equipment &#123; @TableId(type = IdType.AUTO) private Long id; private String code; // 设备编码 private String name; // 设备名称 private Integer type; // 设备类型 private Long workAreaId; // 工作面ID private LocalDate purchaseDate; // 购入日期 private BigDecimal price; // 价格 private EquipmentStatus status; // 设备状态 private LocalDate lastCheckDate; // 上次巡检日期 private LocalDate nextCheckDate; // 下次巡检日期 @Version private Integer version; @TableLogic @TableField(select = false) private Integer deleted; // ... 审计字段&#125;// ==================== CreateDTO ====================@Datapublic class EquipmentCreateDTO &#123; @NotBlank(message = &quot;设备编码不能为空&quot;) @Pattern(regexp = &quot;^EQ-\\d&#123;4&#125;-\\d&#123;3&#125;$&quot;, message = &quot;编码格式：EQ-年份-序号&quot;) private String code; @NotBlank(message = &quot;设备名称不能为空&quot;) @Size(max = 50) private String name; @NotNull(message = &quot;设备类型不能为空&quot;) private Integer type; @NotNull(message = &quot;工作面不能为空&quot;) private Long workAreaId; @NotNull(message = &quot;购入日期不能为空&quot;) private LocalDate purchaseDate; @NotNull(message = &quot;价格不能为空&quot;) @DecimalMin(value = &quot;0.01&quot;) private BigDecimal price;&#125;// ==================== UpdateDTO ====================@Datapublic class EquipmentUpdateDTO &#123; @NotNull(message = &quot;ID不能为空&quot;) private Long id; @Size(max = 50) private String name; private Long workAreaId; private EquipmentStatus status; private LocalDate nextCheckDate;&#125;// ==================== VO ====================@Data@JsonInclude(JsonInclude.Include.NON_NULL)public class EquipmentVO &#123; @JsonSerialize(using = ToStringSerializer.class) private Long id; private String code; private String name; private String typeDesc; // 设备类型描述 private Long workAreaId; private String workAreaName; // 关联查询 private LocalDate purchaseDate; private BigDecimal price; private EquipmentStatus status; private String statusDesc; private LocalDate lastCheckDate; private LocalDate nextCheckDate; private Integer checkWarningDays; // 距离下次巡检天数 @JsonFormat(pattern = &quot;yyyy-MM-dd HH:mm:ss&quot;) private LocalDateTime createTime;&#125;
进阶实践1. DTO&#x2F;VO命名规范// ---------------------------------------------------------------// ✅ 推荐的命名方式// ---------------------------------------------------------------MinerCreateDTO // 创建矿工MinerUpdateDTO // 更新矿工MinerQueryDTO // 查询矿工MinerVO // 矿工详情MinerSimpleVO // 矿工简要信息（列表展示）MinerListVO // 矿工列表VO（列表页专用）// ---------------------------------------------------------------// ❌ 避免的命名// ---------------------------------------------------------------MinerDTO // 太模糊，不知道是入参还是出参Miner // 太容易和Entity混淆MinerVo // 大小写不一致MinerRequest // 没有区分创建和更新MinerResponse // 没有体现VO的概念
2. 多层嵌套对象的转换// ---------------------------------------------------------------// 智慧矿山 - 矿工VO（包含部门和工作面信息）// ---------------------------------------------------------------@Datapublic class MinerVO &#123; private Long id; private String name; private DeptVO dept; // 嵌套的VO private WorkAreaVO workArea; // 嵌套的VO private List&lt;SafetyCheckVO&gt; recentChecks; // 嵌套的VO列表&#125;// MapStruct中的嵌套映射@Mapper(componentModel = &quot;spring&quot;)public interface MinerConverter &#123; @Mapping(source = &quot;deptId&quot;, target = &quot;dept&quot;) @Mapping(source = &quot;workAreaId&quot;, target = &quot;workArea&quot;) MinerVO toVO(Miner miner); // 自定义方法：根据deptId查询部门信息 default DeptVO deptIdToDeptVO(Long deptId) &#123; if (deptId == null) &#123; return null; &#125; Dept dept = deptService.getById(deptId); return dept != null ? deptConverter.toVO(dept) : null; &#125; // 自定义方法：根据workAreaId查询工作面信息 default WorkAreaVO workAreaIdToWorkAreaVO(Long workAreaId) &#123; if (workAreaId == null) &#123; return null; &#125; WorkArea area = workAreaService.getById(workAreaId); return area != null ? workAreaConverter.toVO(area) : null; &#125;&#125;
3. 分页结果封装// ---------------------------------------------------------------// 通用分页结果封装// ---------------------------------------------------------------@Data@Builderpublic class PageResult&lt;T&gt; &#123; private List&lt;T&gt; list; private long total; private int pageNum; private int pageSize; private int pages; /** * 从MyBatis-Plus的Page转换 */ public static &lt;T&gt; PageResult&lt;T&gt; from(Page&lt;T&gt; page) &#123; return PageResult.&lt;T&gt;builder() .list(page.getRecords()) .total(page.getTotal()) .pageNum((int) page.getCurrent()) .pageSize((int) page.getSize()) .pages((int) page.getPages()) .build(); &#125; /** * 从Page + 转换后的列表构建 */ public static &lt;T, R&gt; PageResult&lt;R&gt; from(Page&lt;T&gt; page, List&lt;R&gt; convertedList) &#123; return PageResult.&lt;R&gt;builder() .list(convertedList) .total(page.getTotal()) .pageNum((int) page.getCurrent()) .pageSize((int) page.getSize()) .pages((int) page.getPages()) .build(); &#125;&#125;
4. 验证注解进阶// ---------------------------------------------------------------// 分组验证 - 区分创建和更新// ---------------------------------------------------------------public interface Create &#123;&#125;public interface Update &#123;&#125;@Datapublic class MinerDTO &#123; @NotNull(message = &quot;ID不能为空&quot;, groups = Update.class) @Null(message = &quot;ID不能传&quot;, groups = Create.class) private Long id; @NotBlank(message = &quot;姓名不能为空&quot;, groups = &#123;Create.class, Update.class&#125;) @Size(min = 2, max = 20, message = &quot;姓名长度2-20&quot;) private String name; @NotBlank(message = &quot;密码不能为空&quot;, groups = Create.class) // 修改时不在此处校验密码 private String password;&#125;// Controller中使用分组验证@PostMappingpublic Result&lt;Void&gt; add(@RequestBody @Validated(Create.class) MinerDTO dto) &#123;&#125;@PutMappingpublic Result&lt;Void&gt; update(@RequestBody @Validated(Update.class) MinerDTO dto) &#123;&#125;// ---------------------------------------------------------------// 自定义验证注解 - 手机号校验// ---------------------------------------------------------------@Target(&#123;ElementType.FIELD&#125;)@Retention(RetentionPolicy.RUNTIME)@Constraint(validatedBy = PhoneValidator.class)public @interface Phone &#123; String message() default &quot;手机号格式不正确&quot;; Class&lt;?&gt;[] groups() default &#123;&#125;; Class&lt;? extends Payload&gt;[] payload() default &#123;&#125;;&#125;public class PhoneValidator implements ConstraintValidator&lt;Phone, String&gt; &#123; private static final Pattern PHONE_PATTERN = Pattern.compile(&quot;^1[3-9]\\d&#123;9&#125;$&quot;); @Override public boolean isValid(String value, ConstraintValidatorContext context) &#123; if (value == null) &#123; return true; // null交给@NotNull校验 &#125; return PHONE_PATTERN.matcher(value).matches(); &#125;&#125;
工具对比与选型对象转换工具对比
特性 MapStruct BeanUtils ModelMapper Orika
性能 编译期生成，最快 反射，最慢 反射优化 反射优化
类型安全 编译期检查 运行时出错 运行时出错 部分安全
嵌套映射 自动支持 需手动处理 自动支持 自动支持
学习成本 中等 最低 中等 中等
IDE支持 自动补全 无 无 无
调试难度 容易（可看生成代码） 困难 困难 困难
推荐指数 最高 小项目可用 不推荐 可选
Lombok简化代码// ---------------------------------------------------------------// Lombok注解大幅减少样板代码// ---------------------------------------------------------------@Data // @Getter @Setter @ToString @EqualsAndHashCode@Builder // 构建器模式@NoArgsConstructor // 无参构造@AllArgsConstructor // 全参构造@JsonInclude(JsonInclude.Include.NON_NULL) // 不返回null字段public class MinerVO &#123; @JsonSerialize(using = ToStringSerializer.class) private Long id; // Long类型序列化为字符串，防止前端精度丢失 private String name; @JsonFormat(pattern = &quot;yyyy-MM-dd HH:mm:ss&quot;) private LocalDateTime createTime;&#125;
Swagger&#x2F;OpenAPI文档注解@Data@ApiModel(&quot;矿工信息VO&quot;)public class MinerVO &#123; @ApiModelProperty(&quot;矿工ID&quot;) private Long id; @ApiModelProperty(&quot;姓名&quot;) private String name; @ApiModelProperty(&quot;部门名称&quot;) private String deptName; @ApiModelProperty(&quot;工作面名称&quot;) private String workAreaName; @ApiModelProperty(&quot;状态描述&quot;) private String statusDesc;&#125;
常见错误避坑错误1：Entity直接暴露给前端// ---------------------------------------------------------------// ❌ 错误：直接返回Entity// ---------------------------------------------------------------@GetMapping(&quot;/&#123;id&#125;&quot;)public Miner getById(@PathVariable Long id) &#123; return minerService.getById(id); // 密码、盐值、身份证全部暴露！&#125;// ✅ 正确：返回VO@GetMapping(&quot;/&#123;id&#125;&quot;)public Result&lt;MinerVO&gt; getById(@PathVariable Long id) &#123; return Result.success(minerService.getDetail(id));&#125;
错误2：DTO&#x2F;VO和Entity字段完全一样// ---------------------------------------------------------------// ❌ 错误：VO和Entity一模一样，分层没有意义// ---------------------------------------------------------------@Datapublic class MinerVO &#123; private Long id; private String name; private String password; // 安全隐患！ private String salt; // 安全隐患！ // ... 所有字段和Entity一样&#125;// ✅ 正确：VO只包含前端需要的字段@Datapublic class MinerVO &#123; private Long id; private String name; private String deptName; // 关联字段 private String workAreaName;// 关联字段 // 没有password、salt等敏感字段&#125;
错误3：过度转换影响性能// ---------------------------------------------------------------// ❌ 错误：循环中每次都反射转换// ---------------------------------------------------------------List&lt;Miner&gt; miners = minerMapper.selectList();List&lt;MinerVO&gt; voList = new ArrayList&lt;&gt;();for (Miner miner : miners) &#123; MinerVO vo = new MinerVO(); BeanUtils.copyProperties(miner, vo); // 每次都反射！ voList.add(vo);&#125;// ✅ 正确：MapStruct批量转换，编译期生成List&lt;MinerVO&gt; voList = minerConverter.toVOList(miners);
错误4：关联数据循环查询（N+1）// ---------------------------------------------------------------// ❌ 错误：循环中查数据库// ---------------------------------------------------------------List&lt;Miner&gt; miners = this.list();for (Miner miner : miners) &#123; Dept dept = deptService.getById(miner.getDeptId()); // N次查询！ miner.setDeptName(dept.getName());&#125;// ✅ 正确：批量查询Set&lt;Long&gt; deptIds = miners.stream() .map(Miner::getDeptId) .collect(Collectors.toSet());Map&lt;Long, String&gt; deptNameMap = deptService.listByIds(deptIds).stream() .collect(Collectors.toMap(Dept::getId, Dept::getName));voList.forEach(vo -&gt; vo.setDeptName(deptNameMap.get(vo.getDeptId())));
分层架构总览实际项目 - 分层架构图
前端 →Controller→ Service → Mapper 接收 ← 入参:DTO DTO→Entity 操作Entity 展示 出参:VO Entity→VO
总结

前言 实际项目要同时支持Web管理端和矿工移动端登录，最初用Session实现认证，后来部署了两台应用服务器做负载均衡，Session共享成了大问题。切换到JWT后，无状态认证让部署更简单，但也带来了Token续期和主动失效的新挑战。 本文以实际项目为背景，从Session vs JWT对比讲起，深入JWT工具类、认证拦截器、双Token续期、Token黑名单等完整实现。 项目背景智慧矿山系统 - 多端登录架构 Session vs JWTSession认证1. 用户登录，服务端创建Session，返回SessionID2. 浏览器存储SessionID到Cookie3. 每次请求携带Cookie，服务端根据SessionID找到Session+--------+ +----------+ +----------+| 浏览器 | ------ | 服务器A | | 服务器B || Cookie | 请求 | Session | | 无Session |+--------+ +----------+ +----------+问题：- 请求到服务器B时，Session不存在（Session不共享）- 服务器存储Session，占用内存- 跨域Cookie有问题- 分布式部署需要Session共享（Redis/数据库）
JWT认证1. 用户登录，服务端生成JWT Token返回2. 前端存储Token（localStorage或Cookie）3. 每次请求Header携带Token4. 服务端验证Token签名和有效期+--------+ +----------+ +----------+| 客户端 | ------ | 服务器A | | 服务器B || Token | 请求 | 验证签名 | | 验证签名 |+--------+ +----------+ +----------+优点：- 无状态，任何服务器都能验证- 天然支持分布式- 跨域友好- 不占用服务器存储
对比对比项 | Session | JWT
状态 | 有状态 | 无状态 存储位置 | 服务端 | 客户端 分布式支持 | 需共享 | 天然支持 跨域 | 麻烦 | 友好 主动失效 | 容易(删Session) | 困难(需黑名单) 续期 | 自动 | 需实现 安全性 | SessionID暴露 | Token暴露 适用场景 | 单体应用 | 分布式&#x2F;多端
JWT结构JWT = Header.Payload.Signature格式：xxxxx.yyyyy.zzzzz+----------+ +----------+ +----------+| Header | | Payload | |Signature || 头部 | | 载荷 | | 签名 |+----------+ +----------+ +----------+Header:&#123; &quot;alg&quot;: &quot;HS256&quot;, # 签名算法 &quot;typ&quot;: &quot;JWT&quot; # Token类型&#125;Payload:&#123; &quot;userId&quot;: 1, # 用户ID &quot;username&quot;: &quot;zhangsan&quot;, &quot;role&quot;: &quot;MINER&quot;, # 角色 &quot;iat&quot;: 1659523200, # 签发时间 &quot;exp&quot;: 1659609600 # 过期时间&#125;Signature:HMACSHA256( base64(header) + &quot;.&quot; + base64(payload), secret)
Payload标准字段
字段 名称 说明
iss 签发者 Token签发方
sub 主题 Token主题
aud 受众 Token接收方
exp 过期时间 Token过期时间戳
nbf 生效时间 Token生效时间
iat 签发时间 Token签发时间
jti JWT ID Token唯一标识
JWT工具类依赖&lt;dependency&gt; &lt;groupId&gt;io.jsonwebtoken&lt;/groupId&gt; &lt;artifactId&gt;jjwt-api&lt;/artifactId&gt; &lt;version&gt;0.11.5&lt;/version&gt;&lt;/dependency&gt;&lt;dependency&gt; &lt;groupId&gt;io.jsonwebtoken&lt;/groupId&gt; &lt;artifactId&gt;jjwt-impl&lt;/artifactId&gt; &lt;version&gt;0.11.5&lt;/version&gt; &lt;scope&gt;runtime&lt;/scope&gt;&lt;/dependency&gt;&lt;dependency&gt; &lt;groupId&gt;io.jsonwebtoken&lt;/groupId&gt; &lt;artifactId&gt;jjwt-jackson&lt;/artifactId&gt; &lt;version&gt;0.11.5&lt;/version&gt; &lt;scope&gt;runtime&lt;/scope&gt;&lt;/dependency&gt;
配置jwt: secret: $&#123;JWT_SECRET:your-256-bit-secret-key-must-be-at-least-32-characters-long-for-hs256&#125; access-token-expiration: 7200 # 2小时 refresh-token-expiration: 604800 # 7天 issuer: smart-mine
JwtUtil@Component@Slf4jpublic class JwtUtil &#123; @Value(&quot;$&#123;jwt.secret&#125;&quot;) private String secret; @Value(&quot;$&#123;jwt.access-token-expiration:7200&#125;&quot;) private long accessTokenExpiration; @Value(&quot;$&#123;jwt.refresh-token-expiration:604800&#125;&quot;) private long refreshTokenExpiration; @Value(&quot;$&#123;jwt.issuer:smart-mine&#125;&quot;) private String issuer; private SecretKey getSigningKey() &#123; return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8)); &#125; /** * 生成Access Token（短期，2小时） */ public String generateAccessToken(LoginUser loginUser) &#123; Map&lt;String, Object&gt; claims = new HashMap&lt;&gt;(); claims.put(&quot;userId&quot;, loginUser.getUserId()); claims.put(&quot;username&quot;, loginUser.getUsername()); claims.put(&quot;role&quot;, loginUser.getRole()); claims.put(&quot;type&quot;, &quot;access&quot;); return Jwts.builder() .setClaims(claims) .setIssuer(issuer) .setSubject(String.valueOf(loginUser.getUserId())) .setIssuedAt(new Date()) .setExpiration(new Date(System.currentTimeMillis() + accessTokenExpiration * 1000)) .signWith(getSigningKey(), SignatureAlgorithm.HS256) .compact(); &#125; /** * 生成Refresh Token（长期，7天） */ public String generateRefreshToken(LoginUser loginUser) &#123; Map&lt;String, Object&gt; claims = new HashMap&lt;&gt;(); claims.put(&quot;userId&quot;, loginUser.getUserId()); claims.put(&quot;type&quot;, &quot;refresh&quot;); return Jwts.builder() .setClaims(claims) .setIssuer(issuer) .setSubject(String.valueOf(loginUser.getUserId())) .setIssuedAt(new Date()) .setId(UUID.randomUUID().toString()) // 唯一ID（防重放 #8） .setExpiration(new Date(System.currentTimeMillis() + refreshTokenExpiration * 1000)) .signWith(getSigningKey(), SignatureAlgorithm.HS256) .compact(); &#125; /** * 解析Token */ public Claims parseToken(String token) &#123; return Jwts.parserBuilder() .setSigningKey(getSigningKey()) .build() .parseClaimsJws(token) .getBody(); &#125; /** * 从Token获取用户ID */ public Long getUserId(String token) &#123; Claims claims = parseToken(token); return Long.valueOf(claims.get(&quot;userId&quot;).toString()); &#125; /** * 验证Token是否过期 */ public boolean isTokenExpired(String token) &#123; try &#123; Claims claims = parseToken(token); return claims.getExpiration().before(new Date()); &#125; catch (ExpiredJwtException e) &#123; return true; &#125; catch (Exception e) &#123; return true; &#125; &#125; /** * 获取Token类型 */ public String getTokenType(String token) &#123; Claims claims = parseToken(token); return claims.get(&quot;type&quot;, String.class); &#125; /** * 获取Token剩余有效时间（毫秒） */ public long getRemainingTime(String token) &#123; try &#123; Claims claims = parseToken(token); return claims.getExpiration().getTime() - System.currentTimeMillis(); &#125; catch (Exception e) &#123; return 0; &#125; &#125;&#125;
登录认证实现LoginUser@Data@AllArgsConstructor@NoArgsConstructorpublic class LoginUser &#123; private Long userId; private String username; private String role;&#125;
UserContextpublic class UserContext &#123; private static final ThreadLocal&lt;LoginUser&gt; CONTEXT = new ThreadLocal&lt;&gt;(); public static void set(LoginUser user) &#123; CONTEXT.set(user); &#125; public static LoginUser get() &#123; return CONTEXT.get(); &#125; public static void remove() &#123; CONTEXT.remove(); &#125; public static Long getUserId() &#123; LoginUser user = get(); return user != null ? user.getUserId() : null; &#125; public static String getUsername() &#123; LoginUser user = get(); return user != null ? user.getUsername() : null; &#125;&#125;
认证拦截器@Component@RequiredArgsConstructor@Slf4jpublic class AuthInterceptor implements HandlerInterceptor &#123; private final JwtUtil jwtUtil; private final RedisTemplate&lt;String, Object&gt; redisTemplate; private final UserService userService; @Override public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) throws Exception &#123; // OPTIONS请求放行（CORS预检） if (&quot;OPTIONS&quot;.equalsIgnoreCase(request.getMethod())) &#123; return true; &#125; String token = extractToken(request); if (StringUtils.isBlank(token)) &#123; renderError(response, 401, &quot;请先登录&quot;); return false; &#125; try &#123; // 1. 验证Token格式和签名 Claims claims = jwtUtil.parseToken(token); // 2. 验证Token类型（只接受access类型） if (!&quot;access&quot;.equals(claims.get(&quot;type&quot;))) &#123; renderError(response, 401, &quot;Token类型错误&quot;); return false; &#125; // 3. 验证是否过期 if (jwtUtil.isTokenExpired(token)) &#123; renderError(response, 401, &quot;Token已过期&quot;); return false; &#125; // 4. 检查黑名单（解决问题#3 #4） String blacklistKey = &quot;mine:token:blacklist:&quot; + token; if (Boolean.TRUE.equals(redisTemplate.hasKey(blacklistKey))) &#123; renderError(response, 401, &quot;Token已失效&quot;); return false; &#125; // 5. 检查用户状态（解决问题#12） Long userId = Long.valueOf(claims.get(&quot;userId&quot;).toString()); User user = userService.getById(userId); if (user == null || user.getStatus() == UserStatus.DISABLED) &#123; renderError(response, 401, &quot;账号已被禁用&quot;); return false; &#125; // 6. 设置用户上下文 LoginUser loginUser = new LoginUser( userId, claims.get(&quot;username&quot;, String.class), claims.get(&quot;role&quot;, String.class) ); UserContext.set(loginUser); // 7. 滑动续期（解决问题#9：只续期快过期的） long remaining = jwtUtil.getRemainingTime(token); if (remaining &gt; 0 &amp;&amp; remaining &lt; 30 * 60 * 1000) &#123; String newToken = jwtUtil.generateAccessToken(loginUser); response.setHeader(&quot;X-New-Token&quot;, newToken); &#125; return true; &#125; catch (ExpiredJwtException e) &#123; renderError(response, 401, &quot;Token已过期&quot;); return false; &#125; catch (UnsupportedJwtException | MalformedJwtException e) &#123; renderError(response, 401, &quot;Token格式错误&quot;); return false; &#125; catch (SignatureException e) &#123; renderError(response, 401, &quot;Token签名无效&quot;); return false; &#125; catch (Exception e) &#123; log.error(&quot;Token验证异常&quot;, e); renderError(response, 401, &quot;Token无效&quot;); return false; &#125; &#125; @Override public void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler, Exception ex) &#123; UserContext.remove(); &#125; private String extractToken(HttpServletRequest request) &#123; String bearerToken = request.getHeader(&quot;Authorization&quot;); if (StringUtils.isNotBlank(bearerToken) &amp;&amp; bearerToken.startsWith(&quot;Bearer &quot;)) &#123; return bearerToken.substring(7); &#125; return null; &#125; private void renderError(HttpServletResponse response, int status, String message) throws IOException &#123; response.setStatus(status); response.setContentType(&quot;application/json;charset=UTF-8&quot;); response.getWriter().write(&quot;&#123;\&quot;code\&quot;:&quot; + status + &quot;,\&quot;msg\&quot;:\&quot;&quot; + message + &quot;\&quot;&#125;&quot;); &#125;&#125;
拦截器注册@Configuration@RequiredArgsConstructorpublic class WebMvcConfig implements WebMvcConfigurer &#123; private final AuthInterceptor authInterceptor; @Override public void addInterceptors(InterceptorRegistry registry) &#123; registry.addInterceptor(authInterceptor) .addPathPatterns(&quot;/**&quot;) .excludePathPatterns( &quot;/auth/login&quot;, &quot;/auth/refresh&quot;, &quot;/auth/captcha&quot;, &quot;/file/upload&quot;, &quot;/error&quot;, &quot;/doc.html&quot;, &quot;/swagger-resources/**&quot;, &quot;/webjars/**&quot; ); &#125;&#125;
登录接口@RestController@RequestMapping(&quot;/auth&quot;)@RequiredArgsConstructor@Tag(name = &quot;认证管理&quot;)public class AuthController &#123; private final UserService userService; private final JwtUtil jwtUtil; private final RedisTemplate&lt;String, Object&gt; redisTemplate; /** * 登录（解决问题#11：防暴力破解） */ @PostMapping(&quot;/login&quot;) public Result&lt;LoginVO&gt; login(@RequestBody @Valid LoginDTO dto) &#123; // 1. 防暴力破解检查 String failKey = &quot;mine:login:fail:&quot; + dto.getUsername(); Long failCount = (Long) redisTemplate.opsForValue().get(failKey); if (failCount != null &amp;&amp; failCount &gt;= 5) &#123; throw new BusinessException(&quot;登录失败次数过多，账号锁定30分钟&quot;); &#125; // 2. 验证用户名密码 User user = userService.validateLogin(dto.getUsername(), dto.getPassword()); // 3. 生成双Token LoginUser loginUser = new LoginUser(user.getId(), user.getUsername(), user.getRoleCode()); String accessToken = jwtUtil.generateAccessToken(loginUser); String refreshToken = jwtUtil.generateRefreshToken(loginUser); // 4. 清除登录失败记录 redisTemplate.delete(failKey); // 5. 记录登录日志 log.info(&quot;用户登录成功: userId=&#123;&#125;, username=&#123;&#125;&quot;, user.getId(), user.getUsername()); // 6. 返回 LoginVO vo = new LoginVO(); vo.setAccessToken(accessToken); vo.setRefreshToken(refreshToken); vo.setTokenType(&quot;Bearer&quot;); vo.setExpiresIn(7200L); vo.setUserId(user.getId()); vo.setUsername(user.getRealName()); vo.setRole(user.getRoleCode()); return Result.success(vo); &#125; /** * 刷新Token（解决问题#2：双Token续期） */ @PostMapping(&quot;/refresh&quot;) public Result&lt;LoginVO&gt; refresh(@RequestBody RefreshDTO dto) &#123; String refreshToken = dto.getRefreshToken(); // 1. 验证Refresh Token if (jwtUtil.isTokenExpired(refreshToken)) &#123; throw new BusinessException(401, &quot;请重新登录&quot;); &#125; // 2. 验证Token类型 if (!&quot;refresh&quot;.equals(jwtUtil.getTokenType(refreshToken))) &#123; throw new BusinessException(401, &quot;Token类型错误&quot;); &#125; // 3. 检查Refresh Token是否已使用（防重放 #8） String usedKey = &quot;mine:refresh:used:&quot; + refreshToken; if (Boolean.TRUE.equals(redisTemplate.hasKey(usedKey))) &#123; throw new BusinessException(401, &quot;Refresh Token已使用&quot;); &#125; // 4. 标记Refresh Token已使用 long remaining = jwtUtil.getRemainingTime(refreshToken); redisTemplate.opsForValue().set(usedKey, &quot;1&quot;, remaining, TimeUnit.MILLISECONDS); // 5. 生成新的Token对 Long userId = jwtUtil.getUserId(refreshToken); User user = userService.getById(userId); if (user == null || user.getStatus() == UserStatus.DISABLED) &#123; throw new BusinessException(401, &quot;账号已被禁用&quot;); &#125; LoginUser loginUser = new LoginUser(user.getId(), user.getUsername(), user.getRoleCode()); String newAccessToken = jwtUtil.generateAccessToken(loginUser); String newRefreshToken = jwtUtil.generateRefreshToken(loginUser); LoginVO vo = new LoginVO(); vo.setAccessToken(newAccessToken); vo.setRefreshToken(newRefreshToken); vo.setTokenType(&quot;Bearer&quot;); vo.setExpiresIn(7200L); return Result.success(vo); &#125; /** * 登出（解决问题#3：Token黑名单） */ @PostMapping(&quot;/logout&quot;) public Result&lt;Void&gt; logout(HttpServletRequest request) &#123; String token = extractToken(request); if (StringUtils.isNotBlank(token)) &#123; // 将Token加入黑名单，过期时间为Token剩余有效期 long remaining = jwtUtil.getRemainingTime(token); if (remaining &gt; 0) &#123; String blacklistKey = &quot;mine:token:blacklist:&quot; + token; redisTemplate.opsForValue().set(blacklistKey, &quot;1&quot;, remaining, TimeUnit.MILLISECONDS); &#125; &#125; return Result.success(); &#125; private String extractToken(HttpServletRequest request) &#123; String bearerToken = request.getHeader(&quot;Authorization&quot;); if (StringUtils.isNotBlank(bearerToken) &amp;&amp; bearerToken.startsWith(&quot;Bearer &quot;)) &#123; return bearerToken.substring(7); &#125; return null; &#125;&#125;
双Token机制流程图登录流程：
+——–+ +——–+ +——–+ 用户 | –&gt; | 服务端 | –&gt; | 返回 账号密码| | 验证 | | 双Token +——–+ +——–+ +——–+ | Access Token Refresh Token (2小时有效) (7天有效) v v 每次请求携带 Access Token过期后 验证通过即可访问 携带Refresh Token v v Access Token过期 刷新接口返回新Token对 返回401 旧Refresh Token标记已使用 Token生命周期： +———+—+—+—+—+—+—+—+—+—+—+—&gt; 时间 Access | 2h Refresh | 7d +———+—+—+—+—+—+—+—+—+—+—+—&gt; 登录 2h后 刷新 新Access Access过期 获取 2h有效
前端处理// 前端请求拦截器axios.interceptors.response.use( response =&gt; &#123; // 检查是否有新Token（滑动续期） const newToken = response.headers[&#x27;x-new-token&#x27;]; if (newToken) &#123; localStorage.setItem(&#x27;accessToken&#x27;, newToken); &#125; return response; &#125;, error =&gt; &#123; if (error.response &amp;&amp; error.response.status === 401) &#123; const message = error.response.data.msg; if (message === &#x27;Token已过期&#x27;) &#123; // Access Token过期，尝试刷新 return refreshTokenAndRetry(error.config); &#125; else &#123; // 其他401，跳转登录 router.push(&#x27;/login&#x27;); &#125; &#125; return Promise.reject(error); &#125;);async function refreshTokenAndRetry(config) &#123; const refreshToken = localStorage.getItem(&#x27;refreshToken&#x27;); if (!refreshToken) &#123; router.push(&#x27;/login&#x27;); return; &#125; try &#123; const res = await axios.post(&#x27;/auth/refresh&#x27;, &#123; refreshToken &#125;); const &#123; accessToken, refreshToken: newRefresh &#125; = res.data.data; localStorage.setItem(&#x27;accessToken&#x27;, accessToken); localStorage.setItem(&#x27;refreshToken&#x27;, newRefresh); // 重试原请求 config.headers.Authorization = `Bearer $&#123;accessToken&#125;`; return axios(config); &#125; catch (e) &#123; // 刷新失败，跳转登录 router.push(&#x27;/login&#x27;); &#125;&#125;
Token黑名单登出时加入黑名单/** * Token黑名单管理（解决问题#3 #10） */@Component@RequiredArgsConstructorpublic class TokenBlacklistManager &#123; private final RedisTemplate&lt;String, Object&gt; redisTemplate; private static final String PREFIX = &quot;mine:token:blacklist:&quot;; /** * 将Token加入黑名单 */ public void addToBlacklist(String token, long remainingMillis) &#123; if (remainingMillis &gt; 0) &#123; redisTemplate.opsForValue().set(PREFIX + token, &quot;1&quot;, remainingMillis, TimeUnit.MILLISECONDS); &#125; &#125; /** * 检查Token是否在黑名单中 */ public boolean isBlacklisted(String token) &#123; return Boolean.TRUE.equals(redisTemplate.hasKey(PREFIX + token)); &#125; /** * 密码修改后将用户所有Token加入黑名单（解决问题#4） */ public void blacklistAllUserTokens(Long userId) &#123; // 在拦截器中额外检查用户密码修改时间 String key = &quot;mine:user:pwdChanged:&quot; + userId; redisTemplate.opsForValue().set(key, String.valueOf(System.currentTimeMillis()), 7, TimeUnit.DAYS); &#125; /** * 检查用户密码是否在Token签发后修改过 */ public boolean isPasswordChangedAfterToken(Long userId, Date tokenIssuedAt) &#123; String key = &quot;mine:user:pwdChanged:&quot; + userId; String changedTimeStr = (String) redisTemplate.opsForValue().get(key); if (changedTimeStr == null) return false; long changedTime = Long.parseLong(changedTimeStr); return changedTime &gt; tokenIssuedAt.getTime(); &#125;&#125;
单设备登录限制/** * 单设备登录限制（解决问题#15） */@Component@RequiredArgsConstructorpublic class SingleDeviceLoginManager &#123; private final RedisTemplate&lt;String, Object&gt; redisTemplate; private static final String PREFIX = &quot;mine:login:device:&quot;; /** * 记录用户当前登录设备 */ public void recordLogin(Long userId, String accessToken) &#123; String key = PREFIX + userId; redisTemplate.opsForValue().set(key, accessToken, 2, TimeUnit.HOURS); &#125; /** * 检查是否是当前登录设备 */ public boolean isCurrentDevice(Long userId, String accessToken) &#123; String key = PREFIX + userId; String currentToken = (String) redisTemplate.opsForValue().get(key); return accessToken.equals(currentToken); &#125; /** * 踢出其他设备 */ public void kickOtherDevices(Long userId, String newAccessToken) &#123; String key = PREFIX + userId; String oldToken = (String) redisTemplate.opsForValue().get(key); if (oldToken != null &amp;&amp; !oldToken.equals(newAccessToken)) &#123; // 旧Token加入黑名单 // ... &#125; redisTemplate.opsForValue().set(key, newAccessToken, 2, TimeUnit.HOURS); &#125;&#125;
安全配置@Configuration@EnableWebSecuritypublic class SecurityConfig &#123; @Bean public WebSecurityCustomizer webSecurityCustomizer() &#123; return web -&gt; web.ignoring().antMatchers( &quot;/auth/**&quot;, &quot;/doc.html&quot;, &quot;/swagger-resources/**&quot;, &quot;/webjars/**&quot; ); &#125;&#125;
HTTPS配置强制HTTPS（解决问题#5 #14）：server: ssl: enabled: true key-store: classpath:keystore.p12 key-store-password: $&#123;SSL_PASSWORD&#125; key-store-type: PKCS12# HTTP自动跳转HTTPS@Beanpublic ServletWebServerFactory servletContainer() &#123; TomcatServletWebServerFactory tomcat = new TomcatServletWebServerFactory() &#123; @Override protected void postProcessContext(Context context) &#123; SecurityConstraint constraint = new SecurityConstraint(); constraint.setUserConstraint(&quot;CONFIDENTIAL&quot;); SecurityCollection collection = new SecurityCollection(); collection.addPattern(&quot;/*&quot;); constraint.addCollection(collection); context.addConstraint(constraint); &#125; &#125;; tomcat.addAdditionalTomcatConnectors(redirectConnector()); return tomcat;&#125;
总结JWT是实际项目多端登录的标准方案。从Session到JWT，核心认知是：JWT解决了分布式认证问题，但带来了Token续期和主动失效的新挑战。 关键收获：
双Token机制（Access+Refresh）解决续期问题 Redis黑名单解决主动失效（登出、密码修改、账号禁用） Token拦截器要完善异常处理和状态校验 防暴力破解是登录接口的必要防护 不在Payload中存储敏感信息，Base64可解码 HTTPS是Token安全传输的基础保障

前言在智慧矿山项目中，设备状态、告警级别、人员角色等场景经常需要使用固定的常量值。最初我用public static final定义常量，但遇到了类型安全问题——一个方法接受设备状态参数，却可以传入任意整数。后来改用枚举，不仅保证了类型安全，还能为每个枚举值添加自定义属性和方法，代码更加清晰和健壮。 架构流程： 传统常量方式 枚举方式 ┌──────────────────┐ ┌──────────────────┐ public static public enum final int NORMAL DeviceStatus { &#x3D; 1; NORMAL(1), public static WARNING(2), final int ERROR(3); WARNING &#x3D; 2; public static private int final int ERROR code; &#x3D; 3; &#x2F;&#x2F; 方法… → public static public enum final int NORMAL DeviceStatus { &#x3D; 1; NORMAL(1), public static WARNING(2), final int ERROR(3); WARNING &#x3D; 2; public static private int final int ERROR code; &#x3D; 3; &#x2F;&#x2F; 方法…
一、什么是枚举？1.1 枚举的本质// 枚举定义public enum DeviceStatus &#123; NORMAL, // 正常 WARNING, // 警告 ERROR // 错误&#125;// 枚举编译后的等价形式（简化）public final class DeviceStatus extends Enum&lt;DeviceStatus&gt; &#123; public static final DeviceStatus NORMAL = new DeviceStatus(&quot;NORMAL&quot;, 0); public static final DeviceStatus WARNING = new DeviceStatus(&quot;WARNING&quot;, 1); public static final DeviceStatus ERROR = new DeviceStatus(&quot;ERROR&quot;, 2); private DeviceStatus(String name, int ordinal) &#123; super(name, ordinal); &#125;&#125;
1.2 枚举的基本特性DeviceStatus status = DeviceStatus.NORMAL;// 枚举值的基本方法System.out.println(status.name()); // NORMAL（枚举名）System.out.println(status.ordinal()); // 0（序号，从0开始）System.out.println(status.toString()); // NORMAL（默认返回name）// 遍历所有枚举值for (DeviceStatus s : DeviceStatus.values()) &#123; System.out.println(s);&#125;// 通过名称获取枚举值DeviceStatus s = Enum.valueOf(DeviceStatus.class, &quot;NORMAL&quot;);
二、带属性的枚举2.1 定义带属性的枚举public enum AlertLevel &#123; INFO(1, &quot;信息&quot;, &quot;蓝色&quot;), WARNING(2, &quot;警告&quot;, &quot;黄色&quot;), ERROR(3, &quot;错误&quot;, &quot;红色&quot;), CRITICAL(4, &quot;严重&quot;, &quot;橙色&quot;); private final int code; private final String description; private final String color; AlertLevel(int code, String description, String color) &#123; this.code = code; this.description = description; this.color = color; &#125; public int getCode() &#123; return code; &#125; public String getDescription() &#123; return description; &#125; public String getColor() &#123; return color; &#125;&#125;// 使用AlertLevel level = AlertLevel.WARNING;System.out.println(&quot;告警级别: &quot; + level.getDescription());System.out.println(&quot;告警颜色: &quot; + level.getColor());
2.2 常用场景：状态码转换public enum DeviceStatus &#123; OFFLINE(0, &quot;离线&quot;), ONLINE(1, &quot;在线&quot;), FAULT(2, &quot;故障&quot;), MAINTENANCE(3, &quot;维护中&quot;); private final int code; private final String desc; DeviceStatus(int code, String desc) &#123; this.code = code; this.desc = desc; &#125; // 根据code获取枚举值 public static DeviceStatus fromCode(int code) &#123; for (DeviceStatus status : values()) &#123; if (status.code == code) &#123; return status; &#125; &#125; throw new IllegalArgumentException(&quot;无效的状态码: &quot; + code); &#125; public int getCode() &#123; return code; &#125; public String getDesc() &#123; return desc; &#125;&#125;// 使用int statusCode = 2;DeviceStatus status = DeviceStatus.fromCode(statusCode);System.out.println(&quot;状态描述: &quot; + status.getDesc()); // 故障
三、带方法的枚举3.1 添加业务逻辑方法public enum MinerRole &#123; ADMIN(&quot;管理员&quot;, true, true), SUPERVISOR(&quot;监督员&quot;, true, false), WORKER(&quot;矿工&quot;, false, false); private final String name; private final boolean canManage; private final boolean canDelete; MinerRole(String name, boolean canManage, boolean canDelete) &#123; this.name = name; this.canManage = canManage; this.canDelete = canDelete; &#125; // 权限检查方法 public boolean hasManagePermission() &#123; return canManage; &#125; public boolean hasDeletePermission() &#123; return canDelete; &#125; // 判断是否为管理员 public boolean isAdmin() &#123; return this == ADMIN; &#125; public String getName() &#123; return name; &#125;&#125;// 使用MinerRole role = MinerRole.SUPERVISOR;if (role.hasManagePermission()) &#123; System.out.println(role.getName() + &quot;有管理权限&quot;);&#125;
3.2 抽象方法与多态public enum ReportType &#123; DAILY &#123; @Override public String generateFileName() &#123; return &quot;日报_&quot; + java.time.LocalDate.now() + &quot;.pdf&quot;; &#125; @Override public int getRetentionDays() &#123; return 90; &#125; &#125;, WEEKLY &#123; @Override public String generateFileName() &#123; return &quot;周报_&quot; + java.time.LocalDate.now().getWeekOfYear() + &quot;.pdf&quot;; &#125; @Override public int getRetentionDays() &#123; return 180; &#125; &#125;, MONTHLY &#123; @Override public String generateFileName() &#123; return &quot;月报_&quot; + java.time.YearMonth.now() + &quot;.pdf&quot;; &#125; @Override public int getRetentionDays() &#123; return 365; &#125; &#125;; public abstract String generateFileName(); public abstract int getRetentionDays();&#125;// 使用ReportType type = ReportType.WEEKLY;System.out.println(&quot;文件名: &quot; + type.generateFileName());System.out.println(&quot;保留天数: &quot; + type.getRetentionDays());
四、枚举与switch4.1 使用switch匹配枚举public String getStatusAction(DeviceStatus status) &#123; switch (status) &#123; case NORMAL: return &quot;正常运行&quot;; case WARNING: return &quot;发送警告通知&quot;; case ERROR: return &quot;紧急处理&quot;; default: return &quot;未知状态&quot;; &#125;&#125;// 使用DeviceStatus status = DeviceStatus.WARNING;String action = getStatusAction(status);System.out.println(&quot;执行动作: &quot; + action);
4.2 switch vs if-else对比// if-else方式（代码冗长）if (status == DeviceStatus.NORMAL) &#123; // ...&#125; else if (status == DeviceStatus.WARNING) &#123; // ...&#125; else if (status == DeviceStatus.ERROR) &#123; // ...&#125;// switch方式（简洁）switch (status) &#123; case NORMAL: // ... break; case WARNING: // ... break; case ERROR: // ... break;&#125;
五、枚举的高级用法5.1 枚举单例模式/** * 基于枚举的单例模式（推荐） */public enum AlertService &#123; INSTANCE; private AlertQueue queue; AlertService() &#123; queue = new AlertQueue(); &#125; public void sendAlert(String message) &#123; queue.add(message); System.out.println(&quot;发送告警: &quot; + message); &#125; public int getAlertCount() &#123; return queue.size(); &#125; private static class AlertQueue &#123; private java.util.List&lt;String&gt; alerts = new java.util.ArrayList&lt;&gt;(); void add(String alert) &#123; alerts.add(alert); &#125; int size() &#123; return alerts.size(); &#125; &#125;&#125;// 使用AlertService service = AlertService.INSTANCE;service.sendAlert(&quot;瓦斯浓度超标&quot;);
5.2 枚举与接口public interface Displayable &#123; String getDisplayName(); String getIcon();&#125;public enum DeviceType implements Displayable &#123; SENSOR(&quot;传感器&quot;, &quot;🔵&quot;), CAMERA(&quot;摄像头&quot;, &quot;🟢&quot;), CONTROLLER(&quot;控制器&quot;, &quot;🟡&quot;), SERVER(&quot;服务器&quot;, &quot;🔴&quot;); private final String displayName; private final String icon; DeviceType(String displayName, String icon) &#123; this.displayName = displayName; this.icon = icon; &#125; @Override public String getDisplayName() &#123; return displayName; &#125; @Override public String getIcon() &#123; return icon; &#125;&#125;// 使用for (Displayable d : DeviceType.values()) &#123; System.out.println(d.getIcon() + &quot; &quot; + d.getDisplayName());&#125;
5.3 枚举与数据库public enum MinerStatus &#123; ACTIVE(&quot;在职&quot;), RESIGNED(&quot;离职&quot;), RETIRED(&quot;退休&quot;), SUSPENDED(&quot;停职&quot;); private final String desc; MinerStatus(String desc) &#123; this.desc = desc; &#125; public String getDesc() &#123; return desc; &#125;&#125;// 数据库映射（使用枚举名存储）@Entitypublic class Miner &#123; @Enumerated(EnumType.STRING) private MinerStatus status; // EnumType.ORDINAL：存储序号（不推荐，顺序改变会出错） // EnumType.STRING：存储名称（推荐）&#125;
六、枚举集合6.1 EnumSetimport java.util.EnumSet;public class EnumSetDemo &#123; public static void main(String[] args) &#123; // 创建包含所有枚举值的集合 EnumSet&lt;DeviceStatus&gt; all = EnumSet.allOf(DeviceStatus.class); // 创建空集合 EnumSet&lt;DeviceStatus&gt; empty = EnumSet.noneOf(DeviceStatus.class); // 创建指定范围的集合 EnumSet&lt;DeviceStatus&gt; range = EnumSet.range(DeviceStatus.NORMAL, DeviceStatus.WARNING); // 创建包含指定元素的集合 EnumSet&lt;DeviceStatus&gt; selected = EnumSet.of(DeviceStatus.NORMAL, DeviceStatus.ERROR); // 添加元素 selected.add(DeviceStatus.WARNING); // 删除元素 selected.remove(DeviceStatus.NORMAL); // 遍历 for (DeviceStatus status : selected) &#123; System.out.println(status); &#125; &#125;&#125;
6.2 EnumMapimport java.util.EnumMap;public class EnumMapDemo &#123; public static void main(String[] args) &#123; EnumMap&lt;DeviceStatus, Integer&gt; statusCount = new EnumMap&lt;&gt;(DeviceStatus.class); // 添加数据 statusCount.put(DeviceStatus.NORMAL, 100); statusCount.put(DeviceStatus.WARNING, 15); statusCount.put(DeviceStatus.ERROR, 5); // 获取值 int normalCount = statusCount.getOrDefault(DeviceStatus.NORMAL, 0); // 遍历 for (DeviceStatus status : statusCount.keySet()) &#123; System.out.println(status + &quot;: &quot; + statusCount.get(status)); &#125; &#125;&#125;
七、实战：告警系统状态机/** * 智慧矿山告警状态机 */public class AlertStateMachine &#123; public enum AlertState &#123; PENDING &#123; @Override public AlertState handle(AlertEvent event) &#123; switch (event) &#123; case CONFIRM: return PROCESSING; case IGNORE: return RESOLVED; default: return this; &#125; &#125; &#125;, PROCESSING &#123; @Override public AlertState handle(AlertEvent event) &#123; switch (event) &#123; case RESOLVE: return RESOLVED; case ESCALATE: return ESCALATED; default: return this; &#125; &#125; &#125;, ESCALATED &#123; @Override public AlertState handle(AlertEvent event) &#123; switch (event) &#123; case RESOLVE: return RESOLVED; default: return this; &#125; &#125; &#125;, RESOLVED &#123; @Override public AlertState handle(AlertEvent event) &#123; return this; // 已解决状态不响应任何事件 &#125; &#125;; public abstract AlertState handle(AlertEvent event); &#125; public enum AlertEvent &#123; CONFIRM, // 确认 IGNORE, // 忽略 RESOLVE, // 解决 ESCALATE // 升级 &#125; public static void main(String[] args) &#123; AlertState currentState = AlertState.PENDING; // 模拟状态转换 System.out.println(&quot;当前状态: &quot; + currentState); currentState = currentState.handle(AlertEvent.CONFIRM); System.out.println(&quot;确认后状态: &quot; + currentState); currentState = currentState.handle(AlertEvent.ESCALATE); System.out.println(&quot;升级后状态: &quot; + currentState); currentState = currentState.handle(AlertEvent.RESOLVE); System.out.println(&quot;解决后状态: &quot; + currentState); &#125;&#125;
八、常见问题速查
问题 现象 解决方案
枚举顺序改变 数据库序号存储出错 使用EnumType.STRING存储
枚举值比较 用&#x3D;&#x3D;还是equals 两者都可以，&#x3D;&#x3D;更高效
反序列化问题 序列化后枚举值不一致 枚举天然支持序列化
添加新枚举值 switch遗漏新值 IDE会提示，添加default分支
枚举作为参数 传入null导致NPE 添加null检查
总结枚举是Java中一种强大的数据类型，它不仅保证了类型安全，还支持添加属性、方法和实现接口。核心认知是：枚举本质上是继承自Enum的final类，每个枚举值都是该类的单例实例。在实际项目中，枚举广泛应用于状态表示、权限控制、配置项等场景。相比于传统常量，枚举提供了更好的可读性、类型安全和功能扩展性。
九、枚举速查表枚举定义public enum 枚举名 &#123; 枚举值1(参数), 枚举值2(参数), ...; // 属性 private 类型 属性; // 构造方法（必须私有） private 枚举名(参数) &#123; this.属性 = 参数; &#125; // 方法 public 返回类型 方法名() &#123; ... &#125;&#125;
枚举常用方法
方法 作用 示例
name() 获取枚举名 NORMAL.name() → “NORMAL”
ordinal() 获取序号 NORMAL.ordinal() → 0
values() 获取所有枚举值数组 DeviceStatus.values()
valueOf(String) 根据名称获取枚举值 DeviceStatus.valueOf(&quot;NORMAL&quot;)
compareTo() 比较序号大小 NORMAL.compareTo(WARNING) → -1
枚举集合
集合类型 特点 适用场景
EnumSet 内部用位向量实现，高效 枚举值的集合运算
EnumMap 键为枚举类型，高效 枚举值到值的映射
数据库映射@Enumerated(EnumType.STRING) // 推荐：存储枚举名private MinerStatus status;@Enumerated(EnumType.ORDINAL) // 不推荐：存储序号private MinerStatus status;

前言
实际项目有大量列表查询需求：设备列表、告警记录、巡检日志、人员定位记录……几乎每个模块都有分页查询。最初我用的是手动limit分页，后来用了PageHelper插件，再后来切换到MyBatis-Plus的分页，踩了不少坑。特别是深分页问题，当设备数据超过百万条时，传统OFFSET分页性能急剧下降。本章结合实际项目的真实场景，全面梳理分页查询的实现方式与优化策略。
手动Limit分页原理-- MySQL分页语法SELECT * FROM sm_device LIMIT 10 OFFSET 0;   -- 第1页，每页10条SELECT * FROM sm_device LIMIT 10 OFFSET 10;  -- 第2页SELECT * FROM sm_device LIMIT 10 OFFSET 20;  -- 第3页

实现// Mapper@Select(&quot;SELECT * FROM sm_device LIMIT #&#123;size&#125; OFFSET #&#123;offset&#125;&quot;)List&lt;Device&gt; selectByPage(@Param(&quot;offset&quot;) int offset, @Param(&quot;size&quot;) int size);@Select(&quot;SELECT COUNT(*) FROM sm_device WHERE deleted = 0&quot;)int selectCount();// Servicepublic PageResult&lt;Device&gt; list(int page, int size) &#123;    int offset = (page - 1) * size;    List&lt;Device&gt; list = deviceMapper.selectByPage(offset, size);    int total = deviceMapper.selectCount();    return new PageResult&lt;&gt;(list, total, page, size);&#125;

问题
每次都要写两条SQL（查询+计数）
offset大时性能差（深分页问题）
手动计算offset容易出错

PageHelper分页引入依赖&lt;dependency&gt;    &lt;groupId&gt;com.github.pagehelper&lt;/groupId&gt;    &lt;artifactId&gt;pagehelper-spring-boot-starter&lt;/artifactId&gt;    &lt;version&gt;1.4.6&lt;/version&gt;&lt;/dependency&gt;

使用方式// 静态方法PageHelper.startPage(pageNum, pageSize);List&lt;Device&gt; list = deviceMapper.selectAll();PageInfo&lt;Device&gt; pageInfo = new PageInfo&lt;&gt;(list);

PageInfo属性PageInfo&lt;Device&gt; pageInfo = new PageInfo&lt;&gt;(list);pageInfo.getTotal();          // 总记录数pageInfo.getPages();          // 总页数pageInfo.getPageNum();        // 当前页pageInfo.getPageSize();       // 每页大小pageInfo.getList();           // 当前页数据pageInfo.isHasNextPage();     // 是否有下一页pageInfo.isHasPreviousPage(); // 是否有上一页

踩坑// 错误：startPage和查询之间插入其他查询PageHelper.startPage(1, 10);int count = deviceMapper.selectCount();  // 这个查询被分页了！List&lt;Device&gt; list = deviceMapper.selectAll();  // 这个没有分页// 正确：startPage后紧跟查询PageHelper.startPage(1, 10);List&lt;Device&gt; list = deviceMapper.selectAll();  // 只有这个被分页// 清理分页参数PageHelper.clearPage();

MyBatis-Plus分页配置分页插件@Configurationpublic class MybatisPlusConfig &#123;    @Bean    public MybatisPlusInterceptor mybatisPlusInterceptor() &#123;        MybatisPlusInterceptor interceptor = new MybatisPlusInterceptor();        interceptor.addInnerInterceptor(new PaginationInnerInterceptor(DbType.MYSQL));        // 实际项目：设置单页最大记录数，防止一次查太多        PaginationInnerInterceptor pagination = new PaginationInnerInterceptor(DbType.MYSQL);        pagination.setMaxLimit(500L);  // 单页最大500条        interceptor.addInnerInterceptor(pagination);        return interceptor;    &#125;&#125;

使用方式// 基础分页Page&lt;Device&gt; page = new Page&lt;&gt;(pageNum, pageSize);deviceMapper.selectPage(page, null);page.getRecords();   // 数据列表page.getTotal();     // 总记录数page.getPages();     // 总页数page.getCurrent();   // 当前页page.getSize();      // 每页大小// 带条件分页Page&lt;Device&gt; page = new Page&lt;&gt;(1, 10);LambdaQueryWrapper&lt;Device&gt; wrapper = new LambdaQueryWrapper&lt;&gt;();wrapper.like(StringUtils.isNotBlank(name), Device::getName, name)       .eq(status != null, Device::getStatus, status)       .orderByDesc(Device::getCreateTime);deviceMapper.selectPage(page, wrapper);// 自定义SQL分页IPage&lt;DeviceVO&gt; selectDevicePage(Page&lt;DeviceVO&gt; page, @Param(&quot;query&quot;) DeviceQueryDTO query);

自定义SQL分页XML&lt;select id=&quot;selectDevicePage&quot; resultType=&quot;DeviceVO&quot;&gt;    SELECT d.*, dept.name as dept_name    FROM sm_device d    LEFT JOIN sm_dept dept ON d.dept_id = dept.id    &lt;where&gt;        d.deleted = 0        &lt;if test=&quot;query.name != null and query.name != &#x27;&#x27;&quot;&gt;            AND d.device_name LIKE CONCAT(&#x27;%&#x27;, #&#123;query.name&#125;, &#x27;%&#x27;)        &lt;/if&gt;        &lt;if test=&quot;query.type != null&quot;&gt;            AND d.type = #&#123;query.type&#125;        &lt;/if&gt;        &lt;if test=&quot;query.status != null&quot;&gt;            AND d.status = #&#123;query.status&#125;        &lt;/if&gt;    &lt;/where&gt;    ORDER BY d.create_time DESC&lt;/select&gt;

返回统一分页结果public class PageResult&lt;T&gt; &#123;    private List&lt;T&gt; list;    private long total;    private long page;    private long size;    public static &lt;T&gt; PageResult&lt;T&gt; of(Page&lt;T&gt; page) &#123;        PageResult&lt;T&gt; result = new PageResult&lt;&gt;();        result.setList(page.getRecords());        result.setTotal(page.getTotal());        result.setPage(page.getCurrent());        result.setSize(page.getSize());        return result;    &#125;&#125;// Controller@GetMapping(&quot;/list&quot;)public Result&lt;PageResult&lt;DeviceVO&gt;&gt; list(@Valid DeviceQueryDTO query) &#123;    Page&lt;DeviceVO&gt; page = deviceService.list(query);    return Result.success(PageResult.of(page));&#125;

深分页优化当offset很大时，查询性能急剧下降：
-- offset=1000000时，MySQL需要扫描1000010行，丢弃前1000000行SELECT * FROM sm_device LIMIT 10 OFFSET 1000000;

深分页性能分析深分页性能对比（10万条数据）

OFFSET值   | 查询耗时    | 扫描行数    | 说明
0          | 5ms         | 10          | 第1页，很快
1000       | 8ms         | 1010        | 前100页，正常
10000      | 30ms        | 10010       | 第1000页，开始变慢
100000     | 200ms       | 100010      | 第1万页，明显变慢
1000000    | 2000ms      | 1000010     | 第10万页，严重变慢

方案1：游标分页（推荐）-- 基于上一页最后一条的IDSELECT * FROM sm_device WHERE id &gt; #&#123;lastId&#125; ORDER BY id LIMIT 10;

// Mapper@Select(&quot;SELECT * FROM sm_device WHERE id &gt; #&#123;lastId&#125; AND deleted = 0 ORDER BY id LIMIT #&#123;size&#125;&quot;)List&lt;Device&gt; selectByCursor(@Param(&quot;lastId&quot;) Long lastId, @Param(&quot;size&quot;) int size);// 使用Long lastId = 0L;  // 首页从0开始List&lt;Device&gt; page1 = deviceMapper.selectByCursor(lastId, 10);lastId = page1.get(page1.size() - 1).getId();List&lt;Device&gt; page2 = deviceMapper.selectByCursor(lastId, 10);

优点：性能稳定，不受页数影响缺点：不能跳页，只能上一页&#x2F;下一页
方案2：子查询优化-- 先查ID，再关联查数据SELECT * FROM sm_deviceWHERE id IN (    SELECT id FROM sm_device WHERE deleted = 0 ORDER BY id LIMIT 10 OFFSET 1000000);

方案3：覆盖索引-- 利用覆盖索引减少回表SELECT d.* FROM sm_device dINNER JOIN (SELECT id FROM sm_device WHERE deleted = 0 ORDER BY id LIMIT 10 OFFSET 1000000) tON d.id = t.id;

分页的常见坑1. 总数查询慢// MyBatis-Plus默认会执行COUNT查询// 数据量大时COUNT很慢，可以关闭Page&lt;Device&gt; page = new Page&lt;&gt;(1, 10, false);  // false = 不查询总数

2. 分页参数不合法// 防御性编程int pageNum = Math.max(query.getPage(), 1);int pageSize = Math.min(Math.max(query.getSize(), 1), 100);  // 最大100条// 使用PaginationInnerInterceptor的maxLimitpagination.setMaxLimit(500L);

3. JOIN查询总数不准&lt;!-- JOIN查询时COUNT可能不准，因为一对多会展开 --&gt;&lt;!-- 解决：用子查询先分页再JOIN --&gt;&lt;select id=&quot;selectDevicePage&quot; resultType=&quot;DeviceVO&quot;&gt;    SELECT d.*, dept.name as dept_name    FROM (        SELECT * FROM sm_device        WHERE deleted = 0        ORDER BY create_time DESC        LIMIT #&#123;size&#125; OFFSET #&#123;offset&#125;    ) d    LEFT JOIN sm_dept dept ON d.dept_id = dept.id&lt;/select&gt;

4. 分页缓存问题// 分页查询不建议缓存结果// 因为数据变化后缓存失效// 如果必须缓存，设置短过期时间（1分钟）@Cacheable(value = &quot;devicePage&quot;, key = &quot;#query.page + &#x27;_&#x27; + #query.size&quot;, unless = &quot;#result == null&quot;)public PageResult&lt;DeviceVO&gt; list(DeviceQueryDTO query) &#123;    // ...&#125;

5. 分页与排序// 排序字段没有索引会导致全表扫描// 实际项目：确保排序字段有索引// CREATE INDEX idx_create_time ON sm_device(create_time);

分页方案选择分页方案选择决策树

数据量 &lt; 10万？
是 –&gt; MyBatis-Plus分页（OFFSET）
否 –&gt; 需要跳页？- 是 –&gt; 子查询&#x2F;覆盖索引优化- 否 –&gt; 游标分页（推荐）
是否需要总数？
是 –&gt; 默认分页（含COUNT查询）
否 –&gt; 关闭COUNT（new Page&lt;&gt;(1,10,false)）

前言 在实际场景中，刚用Maven时，只会往pom.xml里加依赖，经常遇到版本冲突、依赖缺失、包重复等问题。有一次项目启动报ClassNotFoundException，排查了半天才发现是依赖冲突导致某个jar包被排除了。从那以后，我认真学习了Maven依赖管理。 Maven核心概念项目结构my-project/├── pom.xml # 项目配置├── src/│ ├── main/│ │ ├── java/ # Java源码│ │ └── resources/ # 资源文件│ └── test/│ ├── java/ # 测试源码│ └── resources/ # 测试资源└── target/ # 构建输出
POM核心元素&lt;project&gt; &lt;groupId&gt;com.example&lt;/groupId&gt; &lt;!-- 组织ID --&gt; &lt;artifactId&gt;my-project&lt;/artifactId&gt; &lt;!-- 项目ID --&gt; &lt;version&gt;1.0.0&lt;/version&gt; &lt;!-- 版本 --&gt; &lt;packaging&gt;jar&lt;/packaging&gt; &lt;!-- 打包类型 --&gt; &lt;parent&gt; &lt;!-- 父项目 --&gt; &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt; &lt;artifactId&gt;spring-boot-starter-parent&lt;/artifactId&gt; &lt;version&gt;2.7.0&lt;/version&gt; &lt;/parent&gt; &lt;properties&gt; &lt;!-- 属性 --&gt; &lt;java.version&gt;11&lt;/java.version&gt; &lt;mybatis-plus.version&gt;3.5.3&lt;/mybatis-plus.version&gt; &lt;/properties&gt; &lt;dependencies&gt; &lt;!-- 依赖 --&gt; &lt;dependency&gt; &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt; &lt;artifactId&gt;spring-boot-starter-web&lt;/artifactId&gt; &lt;/dependency&gt; &lt;/dependencies&gt;&lt;/project&gt;
依赖范围
scope 编译 测试 运行 打包 示例
compile ✅ ✅ ✅ ✅ 默认
provided ✅ ✅ ❌ ❌ servlet-api
runtime ❌ ✅ ✅ ✅ JDBC驱动
test ❌ ✅ ❌ ❌ JUnit
system ✅ ✅ ❌ ❌ 本地jar
&lt;!-- 编译时需要，运行时由容器提供 --&gt;&lt;dependency&gt; &lt;groupId&gt;javax.servlet&lt;/groupId&gt; &lt;artifactId&gt;javax.servlet-api&lt;/artifactId&gt; &lt;scope&gt;provided&lt;/scope&gt;&lt;/dependency&gt;&lt;!-- 编译时不需要，运行时需要 --&gt;&lt;dependency&gt; &lt;groupId&gt;mysql&lt;/groupId&gt; &lt;artifactId&gt;mysql-connector-java&lt;/artifactId&gt; &lt;scope&gt;runtime&lt;/scope&gt;&lt;/dependency&gt;&lt;!-- 只在测试时需要 --&gt;&lt;dependency&gt; &lt;groupId&gt;junit&lt;/groupId&gt; &lt;artifactId&gt;junit&lt;/artifactId&gt; &lt;scope&gt;test&lt;/scope&gt;&lt;/dependency&gt;
依赖冲突冲突产生的原因项目依赖A和C：A → B(v1.0) → D(v1.0)C → D(v2.0)D有两个版本，Maven需要选择一个
Maven的调解原则1. 最短路径优先A → B → D(v1.0) 路径长度2A → C → D(v2.0) 路径长度2路径相同，按声明顺序，先声明的优先2. 最先声明优先A先声明了B，则B传递的D(v1.0)优先
查看依赖树# 查看完整依赖树mvn dependency:tree# 查看特定依赖mvn dependency:tree -Dincludes=com.fasterxml.jackson.core# 查看冲突mvn dependency:tree -Dverbose
解决冲突&lt;!-- 方式1：排除传递依赖 --&gt;&lt;dependency&gt; &lt;groupId&gt;com.example&lt;/groupId&gt; &lt;artifactId&gt;A&lt;/artifactId&gt; &lt;exclusions&gt; &lt;exclusion&gt; &lt;groupId&gt;com.example&lt;/groupId&gt; &lt;artifactId&gt;D&lt;/artifactId&gt; &lt;/exclusion&gt; &lt;/exclusions&gt;&lt;/dependency&gt;&lt;!-- 方式2：显式指定版本 --&gt;&lt;dependency&gt; &lt;groupId&gt;com.example&lt;/groupId&gt; &lt;artifactId&gt;D&lt;/artifactId&gt; &lt;version&gt;2.0&lt;/version&gt;&lt;/dependency&gt;&lt;!-- 方式3：使用dependencyManagement统一版本 --&gt;&lt;dependencyManagement&gt; &lt;dependencies&gt; &lt;dependency&gt; &lt;groupId&gt;com.example&lt;/groupId&gt; &lt;artifactId&gt;D&lt;/artifactId&gt; &lt;version&gt;2.0&lt;/version&gt; &lt;/dependency&gt; &lt;/dependencies&gt;&lt;/dependencyManagement&gt;
版本管理dependencyManagement&lt;!-- 父POM中统一管理版本 --&gt;&lt;dependencyManagement&gt; &lt;dependencies&gt; &lt;dependency&gt; &lt;groupId&gt;com.baomidou&lt;/groupId&gt; &lt;artifactId&gt;mybatis-plus-boot-starter&lt;/artifactId&gt; &lt;version&gt;$&#123;mybatis-plus.version&#125;&lt;/version&gt; &lt;/dependency&gt; &lt;dependency&gt; &lt;groupId&gt;com.alibaba&lt;/groupId&gt; &lt;artifactId&gt;druid-spring-boot-starter&lt;/artifactId&gt; &lt;version&gt;$&#123;druid.version&#125;&lt;/version&gt; &lt;/dependency&gt; &lt;/dependencies&gt;&lt;/dependencyManagement&gt;&lt;!-- 子模块中不需要指定版本 --&gt;&lt;dependencies&gt; &lt;dependency&gt; &lt;groupId&gt;com.baomidou&lt;/groupId&gt; &lt;artifactId&gt;mybatis-plus-boot-starter&lt;/artifactId&gt; &lt;/dependency&gt;&lt;/dependencies&gt;
properties管理版本&lt;properties&gt; &lt;java.version&gt;11&lt;/java.version&gt; &lt;mybatis-plus.version&gt;3.5.3&lt;/mybatis-plus.version&gt; &lt;druid.version&gt;1.2.15&lt;/druid.version&gt; &lt;hutool.version&gt;5.8.11&lt;/hutool.version&gt;&lt;/properties&gt;&lt;dependencyManagement&gt; &lt;dependencies&gt; &lt;dependency&gt; &lt;groupId&gt;com.baomidou&lt;/groupId&gt; &lt;artifactId&gt;mybatis-plus-boot-starter&lt;/artifactId&gt; &lt;version&gt;$&#123;mybatis-plus.version&#125;&lt;/version&gt; &lt;/dependency&gt; &lt;/dependencies&gt;&lt;/dependencyManagement&gt;
常用Maven命令# 编译mvn compile# 打包（跳过测试）mvn package -DskipTests# 清理+打包mvn clean package# 安装到本地仓库mvn install# 查看依赖树mvn dependency:tree# 查看有效POMmvn help:effective-pom# 分析依赖mvn dependency:analyze
私服配置&lt;!-- settings.xml --&gt;&lt;servers&gt; &lt;server&gt; &lt;id&gt;releases&lt;/id&gt; &lt;username&gt;admin&lt;/username&gt; &lt;password&gt;admin123&lt;/password&gt; &lt;/server&gt; &lt;server&gt; &lt;id&gt;snapshots&lt;/id&gt; &lt;username&gt;admin&lt;/username&gt; &lt;password&gt;admin123&lt;/password&gt; &lt;/server&gt;&lt;/servers&gt;&lt;mirrors&gt; &lt;mirror&gt; &lt;id&gt;aliyun&lt;/id&gt; &lt;mirrorOf&gt;central&lt;/mirrorOf&gt; &lt;url&gt;https://maven.aliyun.com/repository/public&lt;/url&gt; &lt;/mirror&gt;&lt;/mirrors&gt;&lt;profiles&gt; &lt;profile&gt; &lt;id&gt;dev&lt;/id&gt; &lt;repositories&gt; &lt;repository&gt; &lt;id&gt;releases&lt;/id&gt; &lt;url&gt;http://nexus.company.com/repository/releases/&lt;/url&gt; &lt;/repository&gt; &lt;repository&gt; &lt;id&gt;snapshots&lt;/id&gt; &lt;url&gt;http://nexus.company.com/repository/snapshots/&lt;/url&gt; &lt;/repository&gt; &lt;/repositories&gt; &lt;/profile&gt;&lt;/profiles&gt;
多模块项目&lt;!-- 父POM --&gt;&lt;modules&gt; &lt;module&gt;common&lt;/module&gt; &lt;module&gt;service&lt;/module&gt; &lt;module&gt;web&lt;/module&gt;&lt;/modules&gt;
my-project/├── pom.xml # 父POM├── common/ # 公共模块│ └── pom.xml├── service/ # 服务模块│ └── pom.xml└── web/ # Web模块 └── pom.xml
总结 Maven依赖管理是Java工程化的基础。从”随便加依赖”到”统一版本管理+解决冲突”核心认知是：依赖冲突是不可避免的，关键是要会排查和解决*dependency:tree是最常用的排查命令，dependencyManagement是统一版本的最佳实践。

前言 实际场景中，设备数据是核心资产。一次误操作删除了一张设备表的数据，差点导致矿井监控中断。从那以后，我开始认真研究逻辑删除和乐观锁，确保数据安全。逻辑删除防止数据被误删，乐观锁防止并发修改冲突。两者结合，是实际项目数据安全的双保险。 逻辑删除什么是逻辑删除？逻辑删除不是真正删除数据，而是将”删除标志”字段修改为已删除状态，查询时自动过滤已删除数据。 物理删除：DELETE FROM sm_device WHERE id = 1逻辑删除：UPDATE sm_device SET deleted = 1 WHERE id = 1
逻辑删除的数据生命周期逻辑删除的数据生命周期
+———–+ INSERT +———–+ UPDATE +———+ | 不存在 | ———–&gt; | 正常数据 | ———-&gt; | 已修改 | +———–+ +———–+ +———+ | | DELETE (逻辑删除) v +———–+ | 已删除数据 | —- 可恢复 —-&gt; 还原 +———–+ | | 物理删除(定期清理) v +———–+ | 永久删除 | +———–+
配置mybatis-plus: global-config: db-config: logic-delete-field: deleted logic-delete-value: 1 logic-not-delete-value: 0
实体类@Data@TableName(value = &quot;sm_device&quot;, autoResultMap = true)public class Device extends BaseEntity &#123; @TableId(type = IdType.AUTO) private Long id; private String name; private Integer age; @TableLogic @TableField(select = false) private Integer deleted;&#125;
效果// 删除操作deviceMapper.deleteById(1L);// 实际SQL：UPDATE sm_device SET deleted = 1 WHERE id = 1 AND deleted = 0// 查询操作deviceMapper.selectList(null);// 实际SQL：SELECT id, name, age FROM sm_device WHERE deleted = 0// 根据ID查询deviceMapper.selectById(1L);// 实际SQL：SELECT id, name, age FROM sm_device WHERE id = 1 AND deleted = 0// 更新操作deviceMapper.updateById(device);// 实际SQL：UPDATE sm_device SET name = ? WHERE id = ? AND deleted = 0
乐观锁什么是乐观锁？乐观锁假设冲突很少发生，通过版本号机制在更新时检测冲突： 乐观锁工作流程
线程A 线程B 读取 device (version&#x3D;1) 读取 device (version&#x3D;1) | | 修改 stock&#x3D;9 | | 修改 stock&#x3D;8 UPDATE … SET version&#x3D;2 | WHERE version&#x3D;1 | 成功！version变为2 | | UPDATE … SET version&#x3D;2 WHERE version&#x3D;1 失败！version已变为2
配置@Configurationpublic class MybatisPlusConfig &#123; @Bean public MybatisPlusInterceptor mybatisPlusInterceptor() &#123; MybatisPlusInterceptor interceptor = new MybatisPlusInterceptor(); // 乐观锁插件 interceptor.addInnerInterceptor(new OptimisticLockerInnerInterceptor()); // 分页插件 interceptor.addInnerInterceptor(new PaginationInnerInterceptor(DbType.MYSQL)); return interceptor; &#125;&#125;
实体类@Datapublic class Device &#123; @TableId(type = IdType.AUTO) private Long id; private String name; private Integer stock; @Version private Integer version;&#125;
效果// 1. 查询设备Device device = deviceMapper.selectById(1L);// device: &#123;id:1, name:&quot;瓦斯传感器A&quot;, stock:10, version:1&#125;// 2. 更新库存device.setStock(device.getStock() - 1);deviceMapper.updateById(device);// 实际SQL：UPDATE sm_device SET stock = 9, version = 2// WHERE id = 1 AND version = 1// 3. 并发冲突演示Device p1 = deviceMapper.selectById(1L); // version=1Device p2 = deviceMapper.selectById(1L); // version=1p1.setStock(9);deviceMapper.updateById(p1); // 成功，version变为2p2.setStock(8);deviceMapper.updateById(p2); // 失败！version还是1，但数据库已经是2// 返回0，更新失败
乐观锁冲突处理// 实际项目 - 设备库存扣减public boolean deductStock(Long deviceId, int quantity) &#123; int maxRetry = 3; for (int i = 0; i &lt; maxRetry; i++) &#123; Device device = deviceMapper.selectById(deviceId); if (device.getStock() &lt; quantity) &#123; throw new BusinessException(&quot;库存不足&quot;); &#125; device.setStock(device.getStock() - quantity); int rows = deviceMapper.updateById(device); if (rows &gt; 0) &#123; return true; &#125; log.warn(&quot;乐观锁冲突，第&#123;&#125;次重试&quot;, i + 1); &#125; throw new BusinessException(&quot;操作繁忙，请重试&quot;);&#125;
乐观锁 vs 悲观锁
特性 乐观锁 悲观锁
思路 假设不冲突 假设会冲突
实现 版本号 SELECT FOR UPDATE
性能 高（不加锁） 低（加锁等待）
冲突处理 重试 等待
适用场景 读多写少 写多冲突多
死锁风险 无 有
悲观锁示例// 悲观锁方式处理库存扣减@Transactional(rollbackFor = Exception.class)public boolean deductStockPessimistic(Long deviceId, int quantity) &#123; // SELECT ... FOR UPDATE 加行锁 Device device = deviceMapper.selectForUpdate(deviceId); if (device.getStock() &lt; quantity) &#123; throw new BusinessException(&quot;库存不足&quot;); &#125; device.setStock(device.getStock() - quantity); deviceMapper.updateById(device); return true;&#125;
&lt;!-- DeviceMapper.xml --&gt;&lt;select id=&quot;selectForUpdate&quot; resultType=&quot;Device&quot;&gt; SELECT * FROM sm_device WHERE id = #&#123;id&#125; FOR UPDATE&lt;/select&gt;
逻辑删除 + 乐观锁组合@Data@TableName(value = &quot;sm_device&quot;, autoResultMap = true)public class Device extends BaseEntity &#123; @TableId(type = IdType.AUTO) private Long id; private String name; private Integer stock; private BigDecimal price; @Version private Integer version; @TableLogic @TableField(select = false) private Integer deleted; @TableField(fill = FieldFill.INSERT) private LocalDateTime createTime; @TableField(fill = FieldFill.INSERT_UPDATE) private LocalDateTime updateTime;&#125;
删除操作也会带版本号： -- 逻辑删除SQLUPDATE sm_device SET deleted = 1, version = version + 1WHERE id = 1 AND version = 1 AND deleted = 0
deleted字段使用时间戳的方案// 实际项目最终方案：deleted字段用时间戳// 0 表示未删除，删除时存当前时间戳// 好处：唯一索引 (code, deleted) 不会冲突@Datapublic class Device extends BaseEntity &#123; @TableLogic(value = &quot;0&quot;, delval = &quot;UNIX_TIMESTAMP(NOW())&quot;) @TableField(select = false) private Long deleted; // 注意：用Long而非Integer&#125;// 全局配置mybatis-plus: global-config: db-config: logic-delete-value: &quot;UNIX_TIMESTAMP(NOW())&quot; logic-not-delete-value: &quot;0&quot;
逻辑删除的SQL追踪-- 实际场景中，逻辑删除影响的SQL类型-- 1. SELECT操作：自动加deleted = 0SELECT id, device_name, code FROM sm_device WHERE deleted = 0;SELECT id, device_name FROM sm_device WHERE id = 1 AND deleted = 0;SELECT COUNT(*) FROM sm_device WHERE deleted = 0 AND status = 1;-- 2. UPDATE操作：自动加deleted = 0UPDATE sm_device SET device_name = ? WHERE id = ? AND deleted = 0;UPDATE sm_device SET status = 0 WHERE dept_id = 1 AND deleted = 0;-- 3. DELETE操作：变为UPDATE SET deleted = 1UPDATE sm_device SET deleted = 1 WHERE id = 1 AND deleted = 0;UPDATE sm_device SET deleted = 1 WHERE id IN (1,2,3) AND deleted = 0;-- 4. INSERT操作：不受影响INSERT INTO sm_device (device_name, code) VALUES (?, ?);
乐观锁的SQL追踪-- 实际项目中，乐观锁影响的SQL类型-- 1. updateById：自动加version条件UPDATE sm_device SET stock = 9, version = 2WHERE id = 1 AND version = 1;-- 2. 逻辑删除也带versionUPDATE sm_device SET deleted = 1, version = version + 1WHERE id = 1 AND version = 1 AND deleted = 0;-- 3. 批量更新不生效-- updateBatchById内部不走乐观锁插件-- 需要逐条updateById

前言 实际项目有40多张表，每张表都要写增删改查。最开始用原生MyBatis，一个简单CRUD模块要写七八个文件。引入MyBatis-Plus后，继承BaseMapper就有17个CRUD方法可用。但注解和API有很多细节需要注意，@TableName的autoResultMap、@TableId的主键策略、@TableField的自动填充，搞不清楚就会踩坑。本章结合实际项目的真实场景，全面梳理MyBatis-Plus的注解体系与CRUD接口。 常用注解@TableName// 默认：类名驼峰转下划线作为表名// User -&gt; user, UserInfo -&gt; user_info// 实际项目：表名有sm_前缀@TableName(&quot;sm_device&quot;)public class Device &#123;&#125;// autoResultMap = true：自动构建ResultMap（TypeHandler需要）@TableName(value = &quot;sm_sensor&quot;, autoResultMap = true)public class Sensor &#123; // 当字段有自定义TypeHandler时，必须设置autoResultMap = true&#125;
autoResultMap的使用场景： autoResultMap &#x3D; true 的必要性
场景 | 不设置 | 设置 @TableField(typeHandler)| 不生效 | 生效 枚举@EnumValue | 部分生效| 完全生效 JSON类型字段 | 不生效 | 生效 自定义TypeHandler | 不生效 | 生效
@TableId
策略 说明 适用场景
IdType.AUTO 数据库自增 MySQL自增主键（推荐）
IdType.ASSIGN_ID 雪花算法（默认） 分布式主键
IdType.ASSIGN_UUID UUID字符串 无序主键
IdType.INPUT 手动输入 业务生成主键
IdType.NONE 无策略 跟随全局配置
// 实际项目：单机MySQL，使用AUTO@TableId(type = IdType.AUTO)private Long id;
@TableField@Data@TableName(value = &quot;sm_device&quot;, autoResultMap = true)public class Device extends BaseEntity &#123; // 字段名与列名不一致 @TableField(&quot;device_name&quot;) private String name; // 不映射到数据库（计算字段） @TableField(exist = false) private String deptName; // 自动填充 - 创建时间 @TableField(fill = FieldFill.INSERT) private LocalDateTime createTime; // 自动填充 - 更新时间 @TableField(fill = FieldFill.INSERT_UPDATE) private LocalDateTime updateTime; // 逻辑删除 @TableLogic @TableField(select = false) private Integer deleted; // 乐观锁 @Version private Integer version; // JSON类型字段 @TableField(typeHandler = JsonTypeHandler.class) private DeviceExtra extra; // 枚举字段 @TableField(typeHandler = EnumTypeHandler.class) private DeviceStatus status;&#125;
@TableLogic@TableLogic@TableField(select = false)private Integer deleted;// 全局配置mybatis-plus: global-config: db-config: logic-delete-field: deleted logic-delete-value: 1 logic-not-delete-value: 0
逻辑删除效果： -- deleteById 实际执行UPDATE sm_device SET deleted = 1 WHERE id = 1 AND deleted = 0;-- selectById 实际执行SELECT id, device_name, code, status FROM sm_device WHERE id = 1 AND deleted = 0;-- selectList 实际执行SELECT id, device_name, code, status FROM sm_device WHERE deleted = 0;-- updateById 实际执行UPDATE sm_device SET device_name = ? WHERE id = ? AND deleted = 0;
@Version@Versionprivate Integer version;// 更新时自动加版本条件// UPDATE sm_device SET device_name = ?, version = version + 1// WHERE id = ? AND version = ? AND deleted = 0
自动填充@Component@Slf4jpublic class SmartMineMetaObjectHandler implements MetaObjectHandler &#123; @Override public void insertFill(MetaObject metaObject) &#123; Long userId = UserContext.getUserId(); LocalDateTime now = LocalDateTime.now(); this.strictInsertFill(metaObject, &quot;createTime&quot;, LocalDateTime.class, now); this.strictInsertFill(metaObject, &quot;updateTime&quot;, LocalDateTime.class, now); this.strictInsertFill(metaObject, &quot;createBy&quot;, Long.class, userId); this.strictInsertFill(metaObject, &quot;updateBy&quot;, Long.class, userId); this.strictInsertFill(metaObject, &quot;version&quot;, Integer.class, 1); &#125; @Override public void updateFill(MetaObject metaObject) &#123; Long userId = UserContext.getUserId(); this.strictUpdateFill(metaObject, &quot;updateTime&quot;, LocalDateTime.class, LocalDateTime.now()); this.strictUpdateFill(metaObject, &quot;updateBy&quot;, Long.class, userId); &#125;&#125;
strictInsertFill vs setFieldValByName// strictInsertFill：字段为null时才填充（推荐）this.strictInsertFill(metaObject, &quot;createTime&quot;, LocalDateTime.class, now);// 如果手动设置了createTime，不会覆盖// setFieldValByName：无论是否为null都填充this.setFieldValByName(&quot;createTime&quot;, now, metaObject);// 会覆盖手动设置的值
BaseMapper CRUD接口接口总览BaseMapper 接口方法一览
类别 | 方法 | 说明 新增 | insert(entity) | 插入一条 删除 | deleteById(id) | 根据ID删除 | deleteByMap(columnMap) | 根据条件删除 | delete(wrapper) | 根据条件删除 | deleteBatchIds(idList) | 批量删除 修改 | updateById(entity) | 根据ID修改 | update(entity, wrapper) | 根据条件修改 查询 | selectById(id) | 根据ID查询 | selectOne(wrapper) | 条件查询一条 | selectList(wrapper) | 条件查询列表 | selectBatchIds(idList) | 批量查询 | selectCount(wrapper) | 查询数量 | selectPage(page, w) | 分页查询
新增// 插入一条Device device = new Device();device.setName(&quot;瓦斯传感器A&quot;);device.setCode(&quot;WS-001&quot;);device.setType(DeviceType.GAS_SENSOR);device.setStatus(DeviceStatus.ONLINE);device.setDeptId(1L);device.setLocation(&quot;3号矿井-201工作面&quot;);deviceMapper.insert(device);Long id = device.getId(); // 获取自增ID// 生成SQL// INSERT INTO sm_device (device_name, code, type, status, dept_id,// location, create_time, update_time, create_by, update_by, version)// VALUES (&#x27;瓦斯传感器A&#x27;, &#x27;WS-001&#x27;, 1, 1, 1, &#x27;3号矿井-201工作面&#x27;, ...)
删除// 根据ID删除（逻辑删除）deviceMapper.deleteById(1L);// UPDATE sm_device SET deleted = 1 WHERE id = 1 AND deleted = 0// 根据Wrapper删除LambdaQueryWrapper&lt;Device&gt; wrapper = new LambdaQueryWrapper&lt;&gt;();wrapper.eq(Device::getStatus, DeviceStatus.OFFLINE) .lt(Device::getUpdateTime, LocalDateTime.now().minusMonths(6));deviceMapper.delete(wrapper);// 批量删除List&lt;Long&gt; ids = Arrays.asList(1L, 2L, 3L);deviceMapper.deleteBatchIds(ids);// UPDATE sm_device SET deleted = 1 WHERE id IN (1, 2, 3) AND deleted = 0
修改// 根据ID修改（只更新非null字段）Device device = new Device();device.setId(1L);device.setName(&quot;瓦斯传感器A-更新&quot;);device.setStatus(DeviceStatus.MAINTENANCE);deviceMapper.updateById(device);// UPDATE sm_device SET device_name = &#x27;瓦斯传感器A-更新&#x27;,// status = 3, update_time = ?, version = version + 1// WHERE id = 1 AND version = 1 AND deleted = 0// 根据条件修改LambdaUpdateWrapper&lt;Device&gt; wrapper = new LambdaUpdateWrapper&lt;&gt;();wrapper.set(Device::getStatus, DeviceStatus.OFFLINE) .eq(Device::getDeptId, 1L);deviceMapper.update(null, wrapper);// UPDATE sm_device SET status = 0 WHERE dept_id = 1 AND deleted = 0
查询// 根据ID查询Device device = deviceMapper.selectById(1L);// 根据条件查询一条LambdaQueryWrapper&lt;Device&gt; wrapper = new LambdaQueryWrapper&lt;&gt;();wrapper.eq(Device::getCode, &quot;WS-001&quot;);Device device = deviceMapper.selectOne(wrapper);// 查询列表LambdaQueryWrapper&lt;Device&gt; wrapper = new LambdaQueryWrapper&lt;&gt;();wrapper.eq(Device::getDeptId, 1L).orderByDesc(Device::getCreateTime);List&lt;Device&gt; devices = deviceMapper.selectList(wrapper);// 批量查询List&lt;Long&gt; ids = Arrays.asList(1L, 2L, 3L);List&lt;Device&gt; devices = deviceMapper.selectBatchIds(ids);// 查询数量Long count = deviceMapper.selectCount( new LambdaQueryWrapper&lt;Device&gt;().eq(Device::getStatus, DeviceStatus.ALARM));// 分页查询Page&lt;Device&gt; page = new Page&lt;&gt;(1, 10);LambdaQueryWrapper&lt;Device&gt; wrapper = new LambdaQueryWrapper&lt;&gt;();wrapper.eq(Device::getDeptId, 1L);deviceMapper.selectPage(page, wrapper);
IService CRUD接口接口总览IService 接口方法一览
类别 | 方法 | 说明 新增 | save(entity) | 插入一条 | saveBatch(entityList) | 批量插入 | saveBatch(list, batchSize) | 批量插入(指定批次) | saveOrUpdate(entity) | 存在则更新否则新增 删除 | removeById(id) | 根据ID删除 | removeByIds(idList) | 批量删除 | remove(wrapper) | 根据条件删除 修改 | updateById(entity) | 根据ID修改 | update(entity, wrapper) | 根据条件修改 | updateBatchById(list) | 批量更新 查询 | getById(id) | 根据ID查询 | listByIds(idList) | 批量查询 | list(wrapper) | 条件查询列表 | count(wrapper) | 查询数量 | page(page, wrapper) | 分页查询 链式 | lambdaQuery() | 链式查询 | lambdaUpdate() | 链式更新
条件构造器QueryWrapper vs LambdaQueryWrapper两种Wrapper对比
维度 | QueryWrapper | LambdaQueryWrapper 字段名写法 | 字符串”name” | User::getName 编译检查 | 无 | 有 重构安全 | 不安全 | 安全 IDE提示 | 无 | 有 推荐度 | 不推荐 | 强烈推荐
条件动态拼接// 实际项目 - 设备查询条件动态拼接public LambdaQueryWrapper&lt;Device&gt; buildWrapper(DeviceQueryDTO query) &#123; LambdaQueryWrapper&lt;Device&gt; wrapper = new LambdaQueryWrapper&lt;&gt;(); wrapper.like(StringUtils.isNotBlank(query.getName()), Device::getName, query.getName()) .eq(query.getType() != null, Device::getType, query.getType()) .eq(query.getStatus() != null, Device::getStatus, query.getStatus()) .eq(query.getDeptId() != null, Device::getDeptId, query.getDeptId()) .ge(query.getStartTime() != null, Device::getCreateTime, query.getStartTime()) .le(query.getEndTime() != null, Device::getCreateTime, query.getEndTime()) .orderByDesc(Device::getCreateTime); return wrapper;&#125;
常用条件方法// 等于/不等于.eq(Device::getStatus, 1) // status = 1.ne(Device::getStatus, 0) // status != 0// 范围.gt(Device::getTemperature, 30) // temperature &gt; 30.ge(Device::getTemperature, 30) // temperature &gt;= 30.lt(Device::getStock, 10) // stock &lt; 10.le(Device::getStock, 10) // stock &lt;= 10.between(Device::getAge, 20, 30) // age BETWEEN 20 AND 30// 模糊.like(Device::getName, &quot;瓦斯&quot;) // name LIKE &#x27;%瓦斯%&#x27;.likeLeft(Device::getName, &quot;传感器&quot;) // name LIKE &#x27;%传感器&#x27;.likeRight(Device::getName, &quot;WS&quot;) // name LIKE &#x27;WS%&#x27;// IN.in(Device::getStatus, 1, 2, 3) // status IN (1, 2, 3).notIn(Device::getStatus, 0) // status NOT IN (0)// NULL判断.isNull(Device::getInstallDate) // install_date IS NULL.isNotNull(Device::getInstallDate) // install_date IS NOT NULL// 排序.orderByDesc(Device::getCreateTime) // ORDER BY create_time DESC.orderByAsc(Device::getId) // ORDER BY id ASC// OR.eq(Device::getStatus, 1).or().eq(Device::getStatus, 2) // status = 1 OR status = 2// 嵌套OR.and(w -&gt; w.eq(Device::getStatus, 1).or().eq(Device::getStatus, 2))// AND (status = 1 OR status = 2)
注解与配置速查表
注解&#x2F;配置 作用 示例
@TableName 指定表名 @TableName(“sm_device”)
@TableName(autoResultMap) 自动构建ResultMap autoResultMap&#x3D;true
@TableId 主键策略 @TableId(type &#x3D; IdType.AUTO)
@TableField 字段映射 @TableField(“device_name”)
@TableField(exist&#x3D;false) 不映射数据库 exist &#x3D; false
@TableField(fill) 自动填充 fill &#x3D; FieldFill.INSERT
@TableLogic 逻辑删除 @TableLogic
@TableField(select&#x3D;false) 查询不返回 select &#x3D; false
@Version 乐观锁 @Version
@EnumValue 枚举值映射 @EnumValue
MyBatis-Plus插件配置实际项目的完整插件配置： @Configurationpublic class MybatisPlusConfig &#123; @Bean public MybatisPlusInterceptor mybatisPlusInterceptor() &#123; MybatisPlusInterceptor interceptor = new MybatisPlusInterceptor(); // 1. 多租户插件 interceptor.addInnerInterceptor(new TenantLineInnerInterceptor( new TenantLineHandler() &#123; @Override public Long getTenantId() &#123; return UserContext.getTenantId(); &#125; @Override public String getTenantIdColumn() &#123; return &quot;tenant_id&quot;; &#125; @Override public boolean ignoreTable(String tableName) &#123; return &quot;sys_config&quot;.equals(tableName); &#125; &#125; )); // 2. 动态表名插件 interceptor.addInnerInterceptor(new DynamicTableNameInnerInterceptor()); // 3. 乐观锁插件 interceptor.addInnerInterceptor(new OptimisticLockerInnerInterceptor()); // 4. 防全表更新删除插件 interceptor.addInnerInterceptor(new BlockAttackInnerInterceptor()); // 5. 分页插件（必须放最后） interceptor.addInnerInterceptor( new PaginationInnerInterceptor(DbType.MYSQL) ); return interceptor; &#125;&#125;
插件执行顺序插件执行顺序（从上到下）
多租户插件 | 自动添加tenant_id条件 动态表名插件 | 根据条件切换表名 乐观锁插件 | 更新时自动加version条件 防全表更新删除 | 阻止无WHERE条件的UPDATE&#x2F;DELETE 分页插件 | 自动添加LIMIT&#x2F;OFFSET（必须最后）
MyBatis-Plus全局配置mybatis-plus: # Mapper XML文件路径 mapper-locations: classpath*:mapper/**/*.xml # 实体类扫描路径 type-aliases-package: com.smartmine.entity # 枚举包扫描 type-enums-package: com.smartmine.entity.enums # TypeHandler扫描 type-handlers-package: com.smartmine.handler configuration: # 驼峰转下划线 map-underscore-to-camel-case: true # 日志 log-impl: org.apache.ibatis.logging.stdout.StdOutImpl # 缓存 cache-enabled: true # 懒加载 lazy-loading-enabled: true aggressive-lazy-loading: false global-config: # 关闭Banner banner: false db-config: # 主键策略 id-type: auto # 逻辑删除 logic-delete-field: deleted logic-delete-value: 1 logic-not-delete-value: 0 # 表名前缀 table-prefix: sm_ # 字段策略 insert-strategy: not_null update-strategy: not_null # like查询转义 column-format: &quot;%s&quot;
Service层事务控制@Service@Slf4jpublic class DeviceServiceImpl extends ServiceImpl&lt;DeviceMapper, Device&gt; implements DeviceService &#123; @Autowired private SensorService sensorService; @Override @Transactional(rollbackFor = Exception.class) public void add(DeviceCreateDTO dto) &#123; // 1. 检查编码唯一 long count = this.count(new LambdaQueryWrapper&lt;Device&gt;() .eq(Device::getCode, dto.getCode())); if (count &gt; 0) &#123; throw new BusinessException(&quot;设备编码已存在&quot;); &#125; // 2. 保存设备 Device device = BeanUtil.copyProperties(dto, Device.class); this.save(device); // 3. 初始化传感器（如果有） if (dto.getSensors() != null) &#123; for (SensorCreateDTO sensorDto : dto.getSensors()) &#123; sensorDto.setDeviceId(device.getId()); sensorService.add(sensorDto); &#125; &#125; log.info(&quot;新增设备: id=&#123;&#125;, code=&#123;&#125;&quot;, device.getId(), device.getCode()); &#125; @Override @Transactional(rollbackFor = Exception.class) public void remove(Long id) &#123; Device device = this.getById(id); if (device == null) &#123; throw new BusinessException(&quot;设备不存在&quot;); &#125; // 检查关联传感器 long sensorCount = sensorService.count( new LambdaQueryWrapper&lt;Sensor&gt;().eq(Sensor::getDeviceId, id)); if (sensorCount &gt; 0) &#123; throw new BusinessException(&quot;设备下存在传感器，无法删除&quot;); &#125; this.removeById(id); log.info(&quot;删除设备: id=&#123;&#125;, code=&#123;&#125;&quot;, id, device.getCode()); &#125; @Override public void export(DeviceQueryDTO query, HttpServletResponse response) &#123; LambdaQueryWrapper&lt;Device&gt; wrapper = buildWrapper(query); List&lt;Device&gt; list = this.list(wrapper); // 使用EasyExcel导出 try &#123; response.setContentType(&quot;application/vnd.openxmlformats-officedocument.spreadsheetml.sheet&quot;); response.setHeader(&quot;Content-Disposition&quot;, &quot;attachment;filename=device.xlsx&quot;); EasyExcel.write(response.getOutputStream(), Device.class) .sheet(&quot;设备列表&quot;) .doWrite(list); &#125; catch (IOException e) &#123; throw new BusinessException(&quot;导出失败&quot;); &#125; &#125; private LambdaQueryWrapper&lt;Device&gt; buildWrapper(DeviceQueryDTO query) &#123; LambdaQueryWrapper&lt;Device&gt; wrapper = new LambdaQueryWrapper&lt;&gt;(); wrapper.like(StringUtils.isNotBlank(query.getName()), Device::getName, query.getName()) .eq(query.getType() != null, Device::getType, query.getType()) .eq(query.getStatus() != null, Device::getStatus, query.getStatus()) .eq(query.getDeptId() != null, Device::getDeptId, query.getDeptId()) .ge(query.getStartTime() != null, Device::getCreateTime, query.getStartTime()) .le(query.getEndTime() != null, Device::getCreateTime, query.getEndTime()) .orderByDesc(Device::getCreateTime); return wrapper; &#125;&#125;
MyBatis-Plus性能优化SQL日志分析# 开发环境开启SQL日志mybatis-plus: configuration: log-impl: org.apache.ibatis.logging.stdout.StdOutImpl# 生产环境关闭SQL日志，使用Druid监控spring: datasource: druid: filter: stat: enabled: true slow-sql-millis: 1000 log-slow-sql: true
查询优化策略查询优化策略
优化点 | 说明 select不查全部字段 | 只查需要的字段 索引优化 | 常用查询字段加索引 分页查询 | 避免一次查全部 深分页优化 | 游标分页或子查询 批量操作分批 | 每批500-1000条 二级缓存 | 读多写少的表开启
只查需要的字段// 不推荐：查询所有字段List&lt;Device&gt; devices = deviceMapper.selectList(null);// 推荐：只查需要的字段List&lt;Device&gt; devices = deviceMapper.selectList( new LambdaQueryWrapper&lt;Device&gt;() .select(Device::getId, Device::getName, Device::getCode, Device::getStatus) .eq(Device::getDeptId, 1L));

前言 2022年，我参与了实际项目的开发。这是一个覆盖煤矿生产全流程的管理系统，包括人员定位、设备监控、安全预警、生产调度等模块。项目中几乎所有列表查询都涉及关联：矿工要带部门信息、设备要带传感器列表、告警要带处理记录、生产计划要带班次信息。 最初我写的关联查询又慢又乱，要么JOIN出大量冗余数据，要么N+1查询导致接口超时。后来才搞清楚一对一、一对多的正确处理方式，查询性能提升了数倍。 本文结合实际项目的实战经验，系统讲解MyBatis关联查询的两种思路、一对一&#x2F;一对多的处理方式、N+1问题解决方案和最佳实践。 关联查询的两种思路思路1：SQL JOIN（单次查询）-- 一次JOIN查出所有数据SELECT w.*, d.name as dept_nameFROM t_worker wLEFT JOIN sys_dept d ON w.dept_id = d.id
JOIN查询优缺点
优点 | 缺点 一次SQL搞定 | 一对多时数据冗余 减少数据库交互 | 映射复杂 适合一对一 | 结果集可能很大
思路2：分步查询（多次查询）-- 第1次：查矿工SELECT * FROM t_worker WHERE id = 1;-- 第2次：根据dept_id查部门SELECT * FROM sys_dept WHERE id = 10;
分步查询优缺点
优点 | 缺点 SQL简单 | 多次数据库交互 映射清晰 | N+1问题 支持懒加载 | 网络开销
思路3：批量查询（智慧矿山推荐）-- 第1次：查矿工列表SELECT * FROM t_worker WHERE deleted = 0 LIMIT 10;-- 第2次：批量查部门（一次查完所有关联部门）SELECT * FROM sys_dept WHERE id IN (1, 2, 3);
三种思路对比
维度 | JOIN | 分步查询 | 批量查询 SQL次数 | 1次 | 1+N次 | 2次 性能 | 中 | 差(N+1) | 好 映射复杂度 | 高 | 低 | 低 懒加载 | 不支持 | 支持 | 不支持 推荐度 | 一对一 | 详情页 | 列表页
一对一关联场景：矿工关联部门（一个矿工属于一个部门）
+——————+ +——————+ t_worker | | sys_dept +——————+ +——————+ id (PK) | +–&gt; | id (PK) worker_no | | | name name | | | parent_id dept_id (FK) | —+ | status | status | +——————+
方式1：JOIN + 自动映射&lt;select id=&quot;selectWorkerWithDept&quot; resultType=&quot;WorkerVO&quot;&gt; SELECT w.id, w.worker_no, w.name, w.dept_id, d.name as dept_name FROM t_worker w LEFT JOIN sys_dept d ON w.dept_id = d.id AND d.deleted = 0 WHERE w.id = #&#123;id&#125; AND w.deleted = 0&lt;/select&gt;
@Datapublic class WorkerVO &#123; private Long id; private String workerNo; private String name; private Long deptId; private String deptName; // 部门名称，别名映射&#125;
最简单的方式，适合字段不多的情况。 方式2：JOIN + resultMap嵌套映射&lt;resultMap id=&quot;workerDeptMap&quot; type=&quot;Worker&quot;&gt; &lt;id column=&quot;id&quot; property=&quot;id&quot;/&gt; &lt;result column=&quot;worker_no&quot; property=&quot;workerNo&quot;/&gt; &lt;result column=&quot;name&quot; property=&quot;name&quot;/&gt; &lt;!-- 一对一关联 --&gt; &lt;association property=&quot;dept&quot; javaType=&quot;Dept&quot;&gt; &lt;id column=&quot;dept_id&quot; property=&quot;id&quot;/&gt; &lt;result column=&quot;dept_name&quot; property=&quot;name&quot;/&gt; &lt;/association&gt;&lt;/resultMap&gt;&lt;select id=&quot;selectWorkerWithDept&quot; resultMap=&quot;workerDeptMap&quot;&gt; SELECT w.*, d.id as dept_id, d.name as dept_name FROM t_worker w LEFT JOIN sys_dept d ON w.dept_id = d.id AND d.deleted = 0 WHERE w.id = #&#123;id&#125; AND w.deleted = 0&lt;/select&gt;
@Datapublic class Worker &#123; private Long id; private String workerNo; private String name; private Dept dept; // 关联的部门对象&#125;
方式3：分步查询&lt;!-- 第1步：查矿工 --&gt;&lt;resultMap id=&quot;workerDeptStepMap&quot; type=&quot;Worker&quot;&gt; &lt;id column=&quot;id&quot; property=&quot;id&quot;/&gt; &lt;result column=&quot;name&quot; property=&quot;name&quot;/&gt; &lt;!-- 一对一分步查询 --&gt; &lt;association property=&quot;dept&quot; select=&quot;com.mine.smart.mapper.DeptMapper.selectById&quot; column=&quot;dept_id&quot;/&gt;&lt;/resultMap&gt;&lt;select id=&quot;selectWorkerWithDeptStep&quot; resultMap=&quot;workerDeptStepMap&quot;&gt; SELECT * FROM t_worker WHERE id = #&#123;id&#125; AND deleted = 0&lt;/select&gt;&lt;!-- 第2步：查部门（DeptMapper中） --&gt;&lt;select id=&quot;selectById&quot; resultType=&quot;Dept&quot;&gt; SELECT * FROM sys_dept WHERE id = #&#123;id&#125; AND deleted = 0&lt;/select&gt;
懒加载# 开启懒加载，分步查询时按需执行mybatis: configuration: lazy-loading-enabled: true aggressive-lazy-loading: false
Worker worker = workerMapper.selectWorkerWithDeptStep(1L);// 此时只执行了查矿工的SQLworker.getDept().getName(); // 这时才执行查部门的SQL
一对多关联场景：部门关联矿工列表（一个部门有多个矿工）
+——————+ +——————+ sys_dept | | t_worker +——————+ +——————+ id (PK) | +–&gt; | id (PK) name | | | worker_no parent_id | | | name status | | | dept_id (FK) +——————+ | status | +—-&gt; 1:N —-+
方式1：JOIN + resultMap嵌套映射&lt;resultMap id=&quot;deptWorkersMap&quot; type=&quot;Dept&quot;&gt; &lt;id column=&quot;id&quot; property=&quot;id&quot;/&gt; &lt;result column=&quot;name&quot; property=&quot;name&quot;/&gt; &lt;!-- 一对多关联 --&gt; &lt;collection property=&quot;workers&quot; ofType=&quot;Worker&quot;&gt; &lt;id column=&quot;worker_id&quot; property=&quot;id&quot;/&gt; &lt;result column=&quot;worker_name&quot; property=&quot;name&quot;/&gt; &lt;result column=&quot;worker_status&quot; property=&quot;status&quot;/&gt; &lt;/collection&gt;&lt;/resultMap&gt;&lt;select id=&quot;selectDeptWithUsers&quot; resultMap=&quot;deptUsersMap&quot;&gt; SELECT d.id, d.name, w.id as worker_id, w.name as worker_name, w.status as worker_status FROM sys_dept d LEFT JOIN t_worker w ON d.id = w.dept_id AND w.deleted = 0 WHERE d.id = #&#123;id&#125; AND d.deleted = 0&lt;/select&gt;
@Datapublic class Dept &#123; private Long id; private String name; private List&lt;Worker&gt; workers; // 部门下的矿工列表&#125;
方式2：分步查询&lt;resultMap id=&quot;deptWorkersStepMap&quot; type=&quot;Dept&quot;&gt; &lt;id column=&quot;id&quot; property=&quot;id&quot;/&gt; &lt;result column=&quot;name&quot; property=&quot;name&quot;/&gt; &lt;!-- 一对多分步查询 --&gt; &lt;collection property=&quot;workers&quot; select=&quot;com.mine.smart.mapper.WorkerMapper.selectByDeptId&quot; column=&quot;id&quot;/&gt;&lt;/resultMap&gt;&lt;select id=&quot;selectDeptWithUsersStep&quot; resultMap=&quot;deptWorkersStepMap&quot;&gt; SELECT * FROM sys_dept WHERE id = #&#123;id&#125; AND deleted = 0&lt;/select&gt;&lt;!-- WorkerMapper中 --&gt;&lt;select id=&quot;selectByDeptId&quot; resultType=&quot;Worker&quot;&gt; SELECT * FROM t_worker WHERE dept_id = #&#123;deptId&#125; AND deleted = 0&lt;/select&gt;
N+1问题分步查询最大的坑就是N+1问题： // 查询10个部门List&lt;Dept&gt; depts = deptMapper.selectAll();// 每个部门又查一次矿工列表for (Dept dept : depts) &#123; dept.getWorkers(); // 执行1次SQL&#125;// 总共执行：1（查部门） + 10（查矿工） = 11次SQL！
N+1问题图解
查询部门列表（1次SQL） +——+——-+ | ID | Name | +——+——-+ | 1 | 采煤部 | –&gt; SELECT * FROM t_worker WHERE dept_id&#x3D;1 | 2 | 机电部 | –&gt; SELECT * FROM t_worker WHERE dept_id&#x3D;2 | 3 | 通风部 | –&gt; SELECT * FROM t_worker WHERE dept_id&#x3D;3 | … | … | –&gt; … | N | XX部 | –&gt; SELECT * FROM t_worker WHERE dept_id&#x3D;N +——+——-+ 总计：1 + N 次SQL查询 N&#x3D;100时，101次SQL查询！
解决方案：批量查询（智慧矿山推荐）/** * 批量关联查询 - 避免N+1问题 */public List&lt;DeptVO&gt; listDeptsWithWorkers(DeptQueryDTO query) &#123; // 第1次：查部门列表 List&lt;Dept&gt; depts = deptMapper.selectList(buildWrapper(query)); // 第2次：批量查矿工 Set&lt;Long&gt; deptIds = depts.stream() .map(Dept::getId) .collect(Collectors.toSet()); if (deptIds.isEmpty()) &#123; return Collections.emptyList(); &#125; Map&lt;Long, List&lt;Worker&gt;&gt; workerMap = workerMapper.selectList( new LambdaQueryWrapper&lt;Worker&gt;() .in(Worker::getDeptId, deptIds) ).stream().collect(Collectors.groupingBy(Worker::getDeptId)); // 组装VO return depts.stream().map(dept -&gt; &#123; DeptVO vo = new DeptVO(); BeanUtils.copyProperties(dept, vo); vo.setWorkers(workerMap.getOrDefault(dept.getId(), Collections.emptyList())); return vo; &#125;).collect(Collectors.toList());&#125;
批量查询 vs N+1查询
维度 | N+1查询 | 批量查询 SQL次数 | 1 + N | 2 100个部门 | 101次SQL | 2次SQL 性能 | 差 | 好 代码复杂度 | 低（自动） | 中（手动组装） 适用场景 | 详情页 | 列表页
实际项目中的选择关联查询策略选择
场景 | 推荐方式 一对一，字段少 | JOIN + 自动映射 一对一，嵌套对象 | JOIN + resultMap 一对一，按需加载 | 分步查询 + 懒加载 一对多，数据量小(&lt;20) | JOIN + collection 一对多，数据量大(&gt;20) | 分步查询或手动批量 列表页关联 | 手动批量查询（2次SQL） 详情页关联 | JOIN或分步查询 多表关联 | 自定义XML + 批量关联
MyBatis-Plus的关联处理MyBatis-Plus本身不处理关联查询，通常的做法： // 方式1：手写XML关联查询// 方式2：Service层手动组装public UserVO getUserDetail(Long id) &#123; Worker worker = workerMapper.selectById(id); Dept dept = deptMapper.selectById(worker.getDeptId()); WorkerVO vo = new WorkerVO(); BeanUtils.copyProperties(worker, vo); vo.setDeptName(dept.getName()); return vo;&#125;// 方式3：批量查询优化（推荐用于列表页）public List&lt;WorkerVO&gt; getUserList(WorkerQueryDTO query) &#123; List&lt;Worker&gt; workers = workerMapper.selectList(buildWrapper(query)); // 批量查部门 Set&lt;Long&gt; deptIds = workers.stream() .map(Worker::getDeptId) .filter(Objects::nonNull) .collect(Collectors.toSet()); Map&lt;Long, String&gt; deptNameMap = deptMapper.selectBatchIds(deptIds).stream() .collect(Collectors.toMap(Dept::getId, Dept::getName)); // 组装VO return workers.stream().map(w -&gt; &#123; WorkerVO vo = new WorkerVO(); BeanUtils.copyProperties(w, vo); vo.setDeptName(deptNameMap.get(w.getDeptId())); return vo; &#125;).collect(Collectors.toList());&#125;
总结关联查询是MyBatis使用中的核心难点。在实际场景中，我最大的认知转变是：不要迷信JOIN，也不要迷信分步查询，根据数据量和场景选择合适的方式——列表页用批量查询，详情页用分步查询，简单关联用JOIN，这是最实用的组合策略。 关键经验总结：
列表页用批量查询（2次SQL），避免N+1 详情页用JOIN或分步查询 一对多数据量大必须分页 JOIN条件别忘了deleted&#x3D;0 VO层做数据组装，不直接返回Entity 复杂关联拆分为多次查询

前言 实际项目初期，我们面对的是30多张业务表——矿车调度表、设备巡检表、人员定位表、安全预警表、通风监测表……每新建一张表就要手写Entity、Mapper、Service、Controller，一个简单的CRUD模块要写七八个文件，枯燥又容易出错。团队三个人并行开发，光搭架子就花了将近两周。直到我引入MyBatis-Plus代码生成器，一键生成整个模块，30张表的结构代码半天搞定，效率翻了不止三倍。 本文结合实际项目的实战经验，系统讲解MyBatis-Plus代码生成器的配置、自定义模板、生成后的调整策略，以及项目中踩过的15个坑。 为什么需要代码生成器？传统手工搭建的痛点一个标准CRUD模块需要的文件： com.smartmine├── entity/│ └── Device.java // 实体类├── mapper/│ └── DeviceMapper.java // Mapper接口├── service/│ └── DeviceService.java // Service接口├── service/impl/│ └── DeviceServiceImpl.java // Service实现├── controller/│ └── DeviceController.java // Controller├── dto/│ ├── DeviceCreateDTO.java // 创建DTO│ └── DeviceUpdateDTO.java // 更新DTO└── vo/ └── DeviceVO.java // 视图对象
MyBatis-Plus代码生成器引入依赖&lt;!-- MyBatis-Plus代码生成器 --&gt;&lt;dependency&gt; &lt;groupId&gt;com.baomidou&lt;/groupId&gt; &lt;artifactId&gt;mybatis-plus-generator&lt;/artifactId&gt; &lt;version&gt;3.5.3&lt;/version&gt;&lt;/dependency&gt;&lt;!-- 模板引擎：Velocity（默认） --&gt;&lt;dependency&gt; &lt;groupId&gt;org.apache.velocity&lt;/groupId&gt; &lt;artifactId&gt;velocity-engine-core&lt;/artifactId&gt; &lt;version&gt;2.3&lt;/version&gt;&lt;/dependency&gt;&lt;!-- 模板引擎：Freemarker（可选） --&gt;&lt;dependency&gt; &lt;groupId&gt;org.freemarker&lt;/groupId&gt; &lt;artifactId&gt;freemarker&lt;/artifactId&gt; &lt;version&gt;2.3.31&lt;/version&gt;&lt;/dependency&gt;
自定义模板默认生成的代码不一定符合项目规范，实际项目我们自定义了Entity、Controller、Service三套模板。 自定义Entity模板package $&#123;package.Entity&#125;;#foreach($pkg in $&#123;table.importPackages&#125;)import $&#123;pkg&#125;;#endimport lombok.Data;import lombok.Builder;import lombok.NoArgsConstructor;import lombok.AllArgsConstructor;import com.baomidou.mybatisplus.annotation.*;import java.io.Serializable;/** * $!&#123;table.comment&#125; * * @author $&#123;author&#125; * @since $&#123;date&#125; */@Data@Builder@NoArgsConstructor@AllArgsConstructor@TableName(value = &quot;$&#123;schemaName&#125;$&#123;table.name&#125;&quot;, autoResultMap = true)public class $&#123;entity&#125; implements Serializable &#123; private static final long serialVersionUID = 1L;#foreach($field in $&#123;table.fields&#125;) /** $&#123;field.comment&#125; */#if($&#123;field.keyFlag&#125;) @TableId(value = &quot;$&#123;field.name&#125;&quot;, type = IdType.AUTO)#elseif($&#123;field.name&#125; == &quot;deleted&quot;) @TableLogic @TableField(value = &quot;$&#123;field.name&#125;&quot;, select = false)#elseif($&#123;field.name&#125; == &quot;version&quot;) @Version @TableField(value = &quot;$&#123;field.name&#125;&quot;)#elseif($&#123;field.name&#125; == &quot;create_time&quot;) @TableField(value = &quot;$&#123;field.name&#125;&quot;, fill = FieldFill.INSERT)#elseif($&#123;field.name&#125; == &quot;update_time&quot;) @TableField(value = &quot;$&#123;field.name&#125;&quot;, fill = FieldFill.INSERT_UPDATE)#else @TableField(&quot;$&#123;field.name&#125;&quot;)#end private $&#123;field.propertyType&#125; $&#123;field.propertyName&#125;;#end&#125;
自定义Controller模板package $&#123;package.Controller&#125;;import $&#123;package.Service&#125;.$&#123;table.serviceName&#125;;import $&#123;package.Entity&#125;.$&#123;entity&#125;;import org.springframework.web.bind.annotation.*;import lombok.RequiredArgsConstructor;import com.smartmine.common.Result;import com.smartmine.common.PageResult;/** * $!&#123;table.comment&#125;管理 * * @author $&#123;author&#125; * @since $&#123;date&#125; */@RestController@RequestMapping(&quot;/api/$&#123;table.entityPath&#125;&quot;)@RequiredArgsConstructorpublic class $&#123;table.controllerName&#125; &#123; private final $&#123;table.serviceName&#125; $&#123;table.serviceName.substring(0,1).toLowerCase()&#125;$&#123;table.serviceName.substring(1)&#125;; /** * 分页查询 */ @GetMapping(&quot;/list&quot;) public Result&lt;PageResult&lt;$&#123;entity&#125;&gt;&gt; list( @RequestParam(defaultValue = &quot;1&quot;) Integer pageNum, @RequestParam(defaultValue = &quot;10&quot;) Integer pageSize) &#123; return Result.success($&#123;table.serviceName.substring(0,1).toLowerCase()&#125;$&#123;table.serviceName.substring(1)&#125;.page( new com.baomidou.mybatisplus.extension.plugins.pagination.Page&lt;&gt;(pageNum, pageSize) )); &#125; /** * 根据ID查询 */ @GetMapping(&quot;/&#123;id&#125;&quot;) public Result&lt;$&#123;entity&#125;&gt; getById(@PathVariable Long id) &#123; return Result.success($&#123;table.serviceName.substring(0,1).toLowerCase()&#125;$&#123;table.serviceName.substring(1)&#125;.getById(id)); &#125; /** * 新增 */ @PostMapping public Result&lt;Void&gt; add(@RequestBody $&#123;entity&#125; entity) &#123; $&#123;table.serviceName.substring(0,1).toLowerCase()&#125;$&#123;table.serviceName.substring(1)&#125;.save(entity); return Result.success(null); &#125; /** * 修改 */ @PutMapping(&quot;/&#123;id&#125;&quot;) public Result&lt;Void&gt; update(@PathVariable Long id, @RequestBody $&#123;entity&#125; entity) &#123; entity.setId(id); $&#123;table.serviceName.substring(0,1).toLowerCase()&#125;$&#123;table.serviceName.substring(1)&#125;.updateById(entity); return Result.success(null); &#125; /** * 删除 */ @DeleteMapping(&quot;/&#123;id&#125;&quot;) public Result&lt;Void&gt; delete(@PathVariable Long id) &#123; $&#123;table.serviceName.substring(0,1).toLowerCase()&#125;$&#123;table.serviceName.substring(1)&#125;.removeById(id); return Result.success(null); &#125;&#125;
模板覆盖流程+------------------+ +------------------+ +------------------+| 内置模板 | | 自定义模板 | | 最终代码 || (default) | --&gt; | (override) | --&gt; | (generated) |+------------------+ +------------------+ +------------------+| entity.java.vm | | entity.java.vm | | MineTruck.java || mapper.java.vm | | controller.java | | MineTruckMapper || service.java.vm | | .vm | | MineTruckCtrl || controller.java | | service.java.vm | | MineTruckSvc || .vm | | mapper.java.vm | | MineTruckSvcImpl |+------------------+ +------------------+ +------------------+
常用配置项详解Entity配置.entityBuilder() .enableLombok() // 使用Lombok .enableChainModel() // 链式模型 .enableTableFieldAnnotation() // 所有字段加@TableField .logicDeleteColumnName(&quot;deleted&quot;) // 逻辑删除 .versionColumnName(&quot;version&quot;) // 乐观锁 .addTableFills( // 自动填充 new Column(&quot;create_time&quot;, FieldFill.INSERT), new Column(&quot;update_time&quot;, FieldFill.INSERT_UPDATE), new Column(&quot;create_by&quot;, FieldFill.INSERT), new Column(&quot;update_by&quot;, FieldFill.INSERT_UPDATE) ) .formatFileName(&quot;%s&quot;) // 文件名格式（不加Entity后缀） .superClass(BaseEntity.class) // 继承基类 .addSuperEntityColumns(&quot;id&quot;, &quot;create_time&quot;, &quot;update_time&quot;, &quot;create_by&quot;, &quot;update_by&quot;, &quot;deleted&quot;, &quot;version&quot;)
字段类型映射// 数据库类型 → Java类型映射.columnMapping() .typeMapping(new DbTypeMapping(LocalDateTime.class, &quot;datetime&quot;)) .typeMapping(new DbTypeMapping(BigDecimal.class, &quot;decimal&quot;)) .typeMapping(new DbTypeMapping(Integer.class, &quot;tinyint&quot;)) .typeMapping(new DbTypeMapping(String.class, &quot;json&quot;))
实际项目中字段类型映射实例：
数据库类型 | Java类型 | 智慧矿山典型字段 bigint | Long | device_id, truck_id int | Integer | status, alarm_level tinyint | Integer | deleted, type decimal(10,2) | BigDecimal | gas_density, temperature datetime | LocalDateTime | create_time, inspect_time varchar(255) | String | device_name, truck_no json | String (需手动改) | extend_info, config point | String (需手动改) | location (人员定位坐标)
策略配置.strategyConfig(builder -&gt; &#123; builder.addInclude(&quot;t_mine_truck&quot;, &quot;t_device_inspect&quot;) // 包含的表 .addExclude(&quot;sys_log&quot;, &quot;sys_dict&quot;) // 排除的表 .addTablePrefix(&quot;t_&quot;, &quot;sys_&quot;) // 表前缀 .entityBuilder() .naming(NamingStrategy.underline_to_column) // 下划线转驼峰 .columnNaming(NamingStrategy.underline_to_column) .superClass(BaseEntity.class) .addSuperEntityColumns(&quot;id&quot;, &quot;create_time&quot;, &quot;update_time&quot;, &quot;create_by&quot;, &quot;update_by&quot;) .controllerBuilder() .enableHyphenStyle() // URL使用连字符风格 .enableRestStyle() // @RestController .serviceBuilder() .formatServiceFileName(&quot;%sService&quot;) // 不加I前缀 .formatServiceImplFileName(&quot;%sServiceImpl&quot;);&#125;)
代码生成后的调整代码生成器只是起点，生成后还需要大量调整。实际项目中的典型调整如下： Entity调整// ==================== 生成后的Entity ====================@Data@TableName(&quot;t_mine_truck&quot;)public class MineTruck &#123; @TableId(type = IdType.AUTO) private Long id; private String truckNo; private Integer status; private Integer currentArea; private BigDecimal loadWeight; private LocalDateTime createTime; private LocalDateTime updateTime; private Integer deleted; private Integer version;&#125;// ==================== 调整后的Entity ====================@Data@Builder@TableName(value = &quot;t_mine_truck&quot;, autoResultMap = true)@EqualsAndHashCode(callSuper = true)public class MineTruck extends BaseEntity &#123; @TableId(type = IdType.AUTO) private Long id; /** 矿车编号 */ @NotBlank(message = &quot;矿车编号不能为空&quot;) @Size(max = 32, message = &quot;矿车编号不能超过32个字符&quot;) private String truckNo; /** 矿车状态 */ private TruckStatus status; // Integer → 枚举 /** 当前区域 */ private AreaCode currentArea; // Integer → 枚举 /** 载重量(吨) */ @NotNull(message = &quot;载重量不能为空&quot;) @DecimalMin(value = &quot;0.01&quot;, message = &quot;载重量必须大于0&quot;) @DecimalMax(value = &quot;500.00&quot;, message = &quot;载重量不能超过500吨&quot;) private BigDecimal loadWeight; /** 扩展信息(JSON) */ @TableField(typeHandler = JsonTypeHandler.class) private TruckExtendInfo extendInfo; // String → JSON对象 /** 经度 */ private BigDecimal longitude; /** 纬度 */ private BigDecimal latitude;&#125;
调整清单 文件类型 | 调整内容 | 实际项目实例 Entity | 添加校验注解 | @NotBlank, @Size, @DecimalMin Entity | 枚举类型映射 | TruckStatus, AreaCode Entity | JSON字段TypeHandler | TruckExtendInfo Entity | 继承BaseEntity | 公共字段提取 Controller | 添加Swagger注解 | @Api, @ApiOperation Controller | 添加权限注解 | @PreAuthorize Controller | 参数校验@Valid | @Valid DeviceCreateDTO Service | 添加业务方法 | dispatch(), inspect() DTO&#x2F;VO | 手动创建 | 不自动生成 Mapper XML | 添加自定义SQL | 关联查询、统计查询
问题：数据库字段注释含双引号，Velocity解析报错如字段注释为：该矿车”特种”运输车错误写法&#x2F;** $!{table.comment} *&#x2F; 正确写法：使用escape工具&#x2F;** $!{table.comment.replace(‘“‘, “‘“)} *&#x2F; 或者使用#set预处理#set($comment &#x3D; $!{table.comment.replace(‘“‘, “‘“)})&#x2F;** ${comment} *&#x2F; ### 问题12详解：JSON字段TypeHandler```java// 生成后的代码（需要手动调整）@TableField(&quot;extend_info&quot;)private String extendInfo;// 调整后的代码@TableField(value = &quot;extend_info&quot;, typeHandler = JsonTypeHandler.class)private TruckExtendInfo extendInfo;// 同时需要在@TableName中开启autoResultMap@TableName(value = &quot;t_mine_truck&quot;, autoResultMap = true)public class MineTruck &#123; // ...&#125;// TruckExtendInfo定义@Datapublic class TruckExtendInfo &#123; private String manufacturer; // 制造商 private LocalDate purchaseDate; // 购入日期 private Integer mileage; // 行驶里程 private String remark; // 备注&#125;
多模块项目的生成策略实际项目采用多模块架构，代码生成需要分模块进行。 项目模块结构smart-mine/├── smart-mine-common/ // 公共模块│ └── BaseEntity.java // 基类├── smart-mine-dispatch/ // 矿车调度模块│ └── src/main/java/com/smartmine/dispatch/├── smart-mine-safety/ // 安全预警模块│ └── src/main/java/com/smartmine/safety/├── smart-mine-monitor/ // 环境监测模块│ └── src/main/java/com/smartmine/monitor/└── smart-mine-system/ // 系统管理模块 └── src/main/java/com/smartmine/system/
分模块生成配置public class ModuleCodeGenerator &#123; /** * 按模块生成代码 * @param moduleName 模块名称 * @param tables 表名列表 */ public static void generate(String moduleName, List&lt;String&gt; tables) &#123; String outputDir = System.getProperty(&quot;user.dir&quot;) + &quot;/smart-mine-&quot; + moduleName + &quot;/src/main/java&quot;; String xmlOutputDir = System.getProperty(&quot;user.dir&quot;) + &quot;/smart-mine-&quot; + moduleName + &quot;/src/main/resources/mapper&quot;; FastAutoGenerator.create(URL, USERNAME, PASSWORD) .globalConfig(builder -&gt; &#123; builder.author(&quot;grq&quot;) .outputDir(outputDir) .dateType(DateType.TIME_PACK) .disableOpenDir(); &#125;) .packageConfig(builder -&gt; &#123; builder.parent(&quot;com.smartmine.&quot; + moduleName) .pathInfo(Collections.singletonMap( OutputFile.xml, xmlOutputDir)); &#125;) .strategyConfig(builder -&gt; &#123; builder.addInclude(tables) .addTablePrefix(&quot;t_&quot;) // ... 其他策略 ; &#125;) .execute(); &#125; // 批量生成 public static void main(String[] args) &#123; // 矿车调度模块 generate(&quot;dispatch&quot;, Arrays.asList( &quot;t_mine_truck&quot;, &quot;t_truck_task&quot;, &quot;t_truck_route&quot;, &quot;t_truck_location&quot; )); // 安全预警模块 generate(&quot;safety&quot;, Arrays.asList( &quot;t_safety_alarm&quot;, &quot;t_alarm_rule&quot;, &quot;t_alarm_handle&quot;, &quot;t_alarm_notify&quot;, &quot;t_gas_sensor&quot;, &quot;t_safety_check&quot; )); // 环境监测模块 generate(&quot;monitor&quot;, Arrays.asList( &quot;t_vent_monitor&quot;, &quot;t_vent_sensor&quot;, &quot;t_temp_sensor&quot;, &quot;t_dust_sensor&quot; )); &#125;&#125;
模块生成流程图读取数据库表 | -&gt; | 按模块分组 | -&gt; | 逐模块生成
格式化代码 添加校验注解 枚举类型映射 JSON字段TypeHandler 补充业务方法
生成代码的质量保证生成后检查清单10 | 字段注释是否从数据库读取 | 建议 | 提升可读性
| 检查项 | 是否必须 | 说明 1 | 类名是否去除表前缀 | 是 | t_mine_truck → MineTruck 2 | 字段类型映射是否正确 | 是 | tinyint → Integer非Byte 3 | 逻辑删除注解是否添加 | 是 | @TableLogic 4 | 乐观锁注解是否添加 | 是 | @Version 5 | 自动填充注解是否添加 | 是 | FieldFill.INSERT 6 | Lombok注解是否完整 | 是 | @Data @Builder @NoArgsConstructor 7 | Service是否继承IService | 是 | 否则无法使用批量操作 8 | Controller是否@RestStyle | 是 | @RestController 9 | BaseResultMap是否生成 | 建议 | TypeHandler需要
自动化校验脚本/** * 生成代码校验器 * 检查生成代码是否符合项目规范 */public class CodeValidator &#123; public static void validate(String modulePath) &#123; List&lt;String&gt; errors = new ArrayList&lt;&gt;(); // 1. 检查Entity是否有校验注解 checkValidationAnnotations(modulePath, errors); // 2. 检查是否有@TableLogic checkLogicDelete(modulePath, errors); // 3. 检查是否有@Version checkVersion(modulePath, errors); // 4. 检查Service是否继承IService checkServiceExtends(modulePath, errors); // 5. 检查Controller是否有@Valid checkControllerValid(modulePath, errors); if (!errors.isEmpty()) &#123; System.err.println(&quot;===== 代码校验失败 =====&quot;); errors.forEach(System.err::println); &#125; else &#123; System.out.println(&quot;===== 代码校验通过 =====&quot;); &#125; &#125;&#125;

前言 在实际场景中，开发完接口后必须测试，最初我都是启动项目后在浏览器手动输入URL，效率极低。后来学会Postman，接口测试、环境切换、参数管理都变得规范高效。 Postman基础创建请求1. 点击 New → Request2. 选择请求方法：GET/POST/PUT/DELETE3. 输入URL4. 设置参数5. 点击 Send6. 查看响应
GET请求URL: http://localhost:8080/api/usersParams: page: 1 size: 10 keyword: 张Headers: Authorization: Bearer eyJhbGciOi...
POST请求URL: http://localhost:8080/api/usersBody → raw → JSON:&#123; &quot;name&quot;: &quot;张三&quot;, &quot;age&quot;: 25, &quot;email&quot;: &quot;zhangsan@example.com&quot;, &quot;deptId&quot;: 1&#125;Headers: Content-Type: application/json Authorization: Bearer eyJhbGciOi...
文件上传URL: http://localhost:8080/api/file/uploadBody → form-data: file: [选择文件] module: avatar
环境变量创建环境1. 点击右上角齿轮 → Add2. 创建开发环境 名称：Dev 变量： base_url = http://localhost:8080 token = 3. 创建测试环境 名称：Test 变量： base_url = http://test-api.example.com token = 4. 创建生产环境 名称：Prod 变量： base_url = https://api.example.com token =
使用变量URL: &#123;&#123;base_url&#125;&#125;/api/usersHeaders: Authorization: Bearer &#123;&#123;token&#125;&#125;
自动设置Token// 登录接口的 Tests 面板const response = pm.response.json();if (response.code === 200) &#123; pm.environment.set(&quot;token&quot;, response.data.token);&#125;
集合管理创建集合1. New → Collection2. 命名：用户管理3. 添加描述4. 创建子文件夹： - 用户查询 - 用户创建 - 用户修改 - 用户删除
集合运行1. 点击 Collection → Run2. 选择要运行的请求3. 设置迭代次数4. 设置延迟5. 点击 Run
预处理脚本// Pre-request Script// 生成时间戳pm.environment.set(&quot;timestamp&quot;, new Date().getTime());// 生成随机数pm.environment.set(&quot;random&quot;, Math.floor(Math.random() * 10000));// 生成签名const timestamp = pm.environment.get(&quot;timestamp&quot;);const secret = pm.environment.get(&quot;secret&quot;);const sign = CryptoJS.MD5(timestamp + secret).toString();pm.environment.set(&quot;sign&quot;, sign);
断言测试// Tests 面板// 1. 状态码断言pm.test(&quot;状态码为200&quot;, function () &#123; pm.response.to.have.status(200);&#125;);// 2. 响应字段断言pm.test(&quot;返回码为200&quot;, function () &#123; const json = pm.response.json(); pm.expect(json.code).to.eql(200);&#125;);// 3. 字段存在断言pm.test(&quot;包含data字段&quot;, function () &#123; const json = pm.response.json(); pm.expect(json.data).to.be.an(&#x27;object&#x27;);&#125;);// 4. 字段值断言pm.test(&quot;用户名正确&quot;, function () &#123; const json = pm.response.json(); pm.expect(json.data.name).to.eql(&quot;张三&quot;);&#125;);// 5. 响应时间断言pm.test(&quot;响应时间小于500ms&quot;, function () &#123; pm.expect(pm.response.responseTime).to.be.below(500);&#125;);// 6. 响应头断言pm.test(&quot;返回JSON格式&quot;, function () &#123; pm.response.to.have.header(&quot;Content-Type&quot;, &quot;application/json;charset=UTF-8&quot;);&#125;);
常用测试脚本登录并保存Tokenconst response = pm.response.json();pm.test(&quot;登录成功&quot;, function () &#123; pm.expect(response.code).to.eql(200); pm.expect(response.data.token).to.be.a(&#x27;string&#x27;);&#125;);if (response.code === 200) &#123; pm.environment.set(&quot;token&quot;, response.data.token); pm.environment.set(&quot;userId&quot;, response.data.userId);&#125;
列表查询验证const response = pm.response.json();pm.test(&quot;查询成功&quot;, function () &#123; pm.expect(response.code).to.eql(200); pm.expect(response.data.list).to.be.an(&#x27;array&#x27;); pm.expect(response.data.total).to.be.a(&#x27;number&#x27;); pm.expect(response.data.list.length).to.be.below(11);&#125;);// 保存第一条数据的IDif (response.data.list.length &gt; 0) &#123; pm.environment.set(&quot;userId&quot;, response.data.list[0].id);&#125;
创建后验证const response = pm.response.json();pm.test(&quot;创建成功&quot;, function () &#123; pm.expect(response.code).to.eql(200); pm.expect(response.data).to.be.an(&#x27;number&#x27;);&#125;);// 保存新建数据的IDif (response.code === 200) &#123; pm.environment.set(&quot;newUserId&quot;, response.data);&#125;
接口文档导出# 导出集合Collection → ... → Export → Collection v2.1# 生成在线文档Collection → ... → Publish Docs# 可以分享给前端同事
常用技巧1. 快速复制响应响应面板 → Copy → Copy Response Body
2. 美化JSON响应面板 → Pretty（默认）
3. 保存示例响应响应面板 → Save Response → Save as example# 方便后续参考
4. 批量替换URL使用环境变量 &#123;&#123;base_url&#125;&#125;切换环境即可切换服务器
5. 代码生成请求面板 → Code# 可以生成 Java/Python/curl 等代码# 方便写接口调用代码
接口测试流程1. 登录获取Token POST &#123;&#123;base_url&#125;&#125;/api/auth/login → 自动保存token到环境变量2. 查询列表 GET &#123;&#123;base_url&#125;&#125;/api/users 和 page=1&amp;size=10 → 验证返回格式和数据 → 保存第一条数据的ID3. 查询详情 GET &#123;&#123;base_url&#125;&#125;/api/users/&#123;&#123;userId&#125;&#125; → 验证字段完整性4. 创建数据 POST &#123;&#123;base_url&#125;&#125;/api/users → 验证创建成功 → 保存新数据ID5. 更新数据 PUT &#123;&#123;base_url&#125;&#125;/api/users/&#123;&#123;newUserId&#125;&#125; → 验证更新成功6. 删除数据 DELETE &#123;&#123;base_url&#125;&#125;/api/users/&#123;&#123;newUserId&#125;&#125; → 验证删除成功
总结 Postman是接口开发和测试的必备工具。从”浏览器手动测试”到”Postman环境管理+断言测试”核心认知是：好的接口测试习惯，让前后端联调效率翻倍*环境变量、自动Token、断言测试——这三点做好，接口测试就规范了。

前言 实际场景中，矿工信息分布在多张表中：矿工基本信息、考勤记录、薪资记录、设备使用记录等。单表查询无法满足业务需求，必须用联表查询或子查询来组合数据。刚接手项目时，JOIN和子查询傻傻分不清，经常写出效率极低的查询，导致矿工考勤报表查询耗时超过10秒。后来系统学习了多表查询，才掌握了正确的姿势。 本文将结合实际项目的实战场景，深入讲解JOIN类型、执行原理、子查询、多表查询优化等核心知识。 JOIN类型全览JOIN类型对比图SQL JOIN 类型对比
INNER JOIN（内连接） +——————-+ +——————-+ | LEFT TABLE | | RIGHT TABLE | | +———+ | | +———+ | | | ● ● ● |&lt;—+—–+—-&gt;| ● ● ● | | | | | | 交集 | | | | +———+ | | +———+ | +——————-+ +——————-+ 只返回两张表中匹配的行 LEFT JOIN（左连接） +——————-+ +——————-+ | LEFT TABLE | | RIGHT TABLE | | +———+ | | +———+ | | | ● ● ● ●|&lt;—+—–+—-&gt;| ● ● ● | | | | ● | | 左表全 | | | | +———+ | 部+匹配+———+ | +——————-+ +——————-+ 返回左表所有行，右表无匹配则为NULL RIGHT JOIN（右连接） +——————-+ +——————-+ | LEFT TABLE | | RIGHT TABLE | | +———+ | | +———+ | | | ● ● ● |&lt;—+—–+—–|● ● ● ● | | | | | | 右表全 | ● | | | +———+ | 部+匹+———+ | +——————-+ +——————-+ 返回右表所有行，左表无匹配则为NULL
INNER JOIN（内连接）-- 只返回两张表中匹配的行-- 智慧矿山：查询有部门归属的矿工信息SELECT u.miner_name, d.dept_nameFROM miner uINNER JOIN mine_dept d ON u.dept_id = d.id;-- 适合：必须两张表都有匹配数据的场景-- 如：查询在岗且有班次安排的矿工
-- 智慧矿山：查询有巡检记录的安全检查员SELECT m.miner_name, h.hazard_type, h.hazard_levelFROM miner mINNER JOIN safety_hazard h ON m.miner_id = h.inspector_idWHERE m.role = &#x27;安全检查员&#x27;;
LEFT JOIN（左连接）-- 返回左表所有行，右表无匹配则为NULL-- 智慧矿山：查询所有矿工及其部门（包括未分配部门的）SELECT m.miner_name, d.dept_nameFROM miner mLEFT JOIN mine_dept d ON m.dept_id = d.id;-- 适合：以左表为主，右表有则显示无则NULL-- 如：查询所有矿工的考勤记录（包括没打卡的）
-- 智慧矿山：查询所有矿工当月的出勤天数（包括0天的）SELECT m.miner_name, COUNT(a.id) AS attendance_daysFROM miner mLEFT JOIN attendance a ON m.miner_id = a.miner_id AND a.date &gt;= &#x27;2022-06-01&#x27; AND a.date &lt; &#x27;2022-07-01&#x27;GROUP BY m.miner_id;-- 注意：LEFT JOIN + WHERE条件要写在ON中，否则会退化为INNER JOIN
RIGHT JOIN（右连接）-- 返回右表所有行，左表无匹配则为NULL-- 智慧矿山：查询所有部门的矿工（包括没有矿工的部门）SELECT m.miner_name, d.dept_nameFROM miner mRIGHT JOIN mine_dept d ON m.dept_id = d.id;-- 实际开发中很少用，通常用LEFT JOIN替代-- 上面等价于：SELECT m.miner_name, d.dept_nameFROM mine_dept dLEFT JOIN miner m ON m.dept_id = d.id;
CROSS JOIN（交叉连接）-- 笛卡尔积：左表每行与右表每行组合-- 智慧矿山：生成矿区与设备类型的所有组合SELECT a.area_name, e.equipment_typeFROM mine_area aCROSS JOIN equipment_type e;-- 5个矿区 × 3种设备类型 = 15行-- 适合：生成组合数据的场景-- 如：生成每个矿区每种设备的标准检查项
自连接-- 表与自己连接-- 智慧矿山：查询矿工及其班组长SELECT e.miner_name AS miner, m.miner_name AS team_leaderFROM miner eLEFT JOIN miner m ON e.leader_id = m.miner_id;-- 适合：树形结构、上下级关系-- 如：查询矿区及其上级矿区SELECT a1.area_name AS sub_area, a2.area_name AS parent_areaFROM mine_area a1LEFT JOIN mine_area a2 ON a1.parent_id = a2.id;
JOIN的执行原理Nested Loop Join（嵌套循环）MySQL默认的JOIN算法：
Simple Nested Loop Join（简单嵌套循环） &#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D; for (row1 in left_table) { – 驱动表（外表） for (row2 in right_table) { – 被驱动表（内表） if (row1.key &#x3D;&#x3D; row2.key) { output(row1, row2); } } } 复杂度：O(M * N)，M&#x3D;左表行数，N&#x3D;右表行数 效率极低！每行左表都要全表扫描右表 Index Nested Loop Join（索引嵌套循环） &#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D; for (row1 in left_table) { – 驱动表 &#x2F;&#x2F; 被驱动表有索引，走B+树查找 row2 &#x3D; right_table.indexLookup(row1.key); if (row2 found) { output(row1, row2); } } 复杂度：O(M * logN)，被驱动表走索引 效率大幅提升！这是最常见的优化手段 Block Nested Loop Join（块嵌套循环） &#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D; – 被驱动表没有索引时使用 – 将驱动表的数据加载到join_buffer中 – 然后扫描被驱动表，与join_buffer做匹配 join_buffer &#x3D; loadBatch(left_table); for (row2 in right_table) { for (row1 in join_buffer) { if (match(row1, row2)) output(row1, row2); } } 优化：增大join_buffer_size可减少扫描次数 SET join_buffer_size &#x3D; 8388608; – 8MB
小表驱动大表-- LEFT JOIN：左表是驱动表-- 确保小表在左边-- ❌ 大表驱动小表SELECT * FROM salary_record o LEFT JOIN miner u ON o.miner_id = u.miner_id;-- salary_record 100万行，miner 5000行-- 驱动表100万行，每行都要查被驱动表-- ✅ 小表驱动大表SELECT * FROM miner u LEFT JOIN salary_record o ON u.miner_id = o.miner_id;-- 驱动表5000行，每行查被驱动表索引-- INNER JOIN：MySQL优化器会自动选择-- 但确保两张表的JOIN字段都有索引
小表驱动大表原理：
大表驱动小表： 外层循环100万次，每次查内表索引 总开销 &#x3D; 100万 * (查索引成本) 小表驱动大表： 外层循环5000次，每次查内表索引 总开销 &#x3D; 5000 * (查索引成本) 结论：外层循环次数越少越好 → 小表做驱动表
Hash Join（MySQL 8.0+）-- MySQL 8.0.18+ 引入Hash Join替代Block Nested Loop-- 适用于等值JOIN且被驱动表无索引的场景-- 智慧矿山：无索引的JOIN查询SELECT m.miner_name, s.salary_amountFROM miner mJOIN salary_record s ON m.miner_id = s.miner_id;-- MySQL 8.0+会自动使用Hash Join：-- 1. 扫描小表，在内存中构建Hash表-- 2. 扫描大表，在Hash表中查找匹配-- 效率远高于Block Nested Loop
子查询子查询分类子查询分类
按结果分： +——————+ +——————+ +——————+ | 标量子查询 | | 列子查询 | | 表子查询 | | 返回单个值 | | 返回一列值 | | 返回多行多列 | | WHERE age &gt; | | WHERE id IN | | FROM (SELECT | | (SELECT AVG…) | | (SELECT id…) | | …) t | +——————+ +——————+ +——————+ 按位置分： +——————+ +——————+ +——————+ | WHERE子查询 | | SELECT子查询 | | FROM子查询 | | 过滤条件 | | 计算字段 | | 派生表 | +——————+ +——————+ +——————+ 按相关性分： +—————————+ +—————————+ | 非相关子查询 | | 相关子查询 | | 独立于外层查询 | | 依赖外层查询的值 | | 只执行一次 | | 每行外层数据都执行一次 | | 通常性能更好 | | 可能性能较差 | +—————————+ +—————————+
标量子查询-- 返回单个值-- 智慧矿山：查询薪资高于平均值的矿工SELECT miner_name, salary_amountFROM miner_salaryWHERE salary_amount &gt; ( SELECT AVG(salary_amount) FROM miner_salary);-- 智慧矿山：查询矿工薪资及其与平均值的差距SELECT m.miner_name, m.salary_amount, m.salary_amount - (SELECT AVG(salary_amount) FROM miner_salary) AS diffFROM miner_salary m;
列子查询-- 返回一列值，配合IN使用-- 智慧矿山：查询有安全隐患记录的矿区SELECT area_nameFROM mine_areaWHERE id IN ( SELECT DISTINCT area_id FROM safety_hazard WHERE status = &#x27;PENDING&#x27;);-- 智慧矿山：查询本月出勤不足20天的矿工SELECT miner_nameFROM minerWHERE miner_id IN ( SELECT miner_id FROM attendance WHERE date &gt;= &#x27;2022-06-01&#x27; AND date &lt; &#x27;2022-07-01&#x27; GROUP BY miner_id HAVING COUNT(*) &lt; 20);
行子查询-- 返回一行值-- 智慧矿山：查询与指定矿工同部门同岗位的所有矿工SELECT * FROM minerWHERE (dept_id, position) = ( SELECT dept_id, position FROM miner WHERE miner_id = 1001);
EXISTS子查询-- 判断是否存在-- 智慧矿山：查询有安全隐患的矿区SELECT d.dept_nameFROM mine_dept dWHERE EXISTS ( SELECT 1 FROM safety_hazard h WHERE h.dept_id = d.id AND h.status = &#x27;PENDING&#x27;);-- EXISTS vs IN：-- EXISTS：先遍历外表，对每行执行子查询，适合外表小-- IN：先执行子查询得到结果集，再遍历外表匹配，适合子查询结果小
EXISTS vs IN 选择策略：
子查询结果集小 → 用 IN &#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D; – 安全隐患表只有50条PENDING记录 SELECT * FROM mine_dept WHERE id IN (SELECT dept_id FROM safety_hazard WHERE status &#x3D; ‘PENDING’); – 先查50条记录，再在mine_dept中匹配 外表小 → 用 EXISTS &#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D; – mine_dept只有10个部门 SELECT d.dept_name FROM mine_dept d WHERE EXISTS (SELECT 1 FROM safety_hazard h WHERE h.dept_id &#x3D; d.id AND h.status &#x3D; ‘PENDING’); – 只需执行10次子查询
FROM子查询（派生表）-- 子查询结果作为临时表-- 智慧矿山：查询各部门矿工数量及平均薪资SELECT d.dept_name, t.miner_count, t.avg_salaryFROM ( SELECT dept_id, COUNT(*) AS miner_count, AVG(salary_amount) AS avg_salary FROM miner_salary GROUP BY dept_id) tINNER JOIN mine_dept d ON t.dept_id = d.id;-- MySQL 8.0+ 优化：派生表合并（Derived Table Merge）-- 优化器会将派生表合并到外层查询，避免创建临时表
子查询 vs JOIN-- 同一个需求，两种写法-- 需求：查询有薪资记录的矿工-- 子查询写法SELECT * FROM minerWHERE miner_id IN (SELECT DISTINCT miner_id FROM salary_record);-- JOIN写法（推荐）SELECT DISTINCT m.* FROM miner mINNER JOIN salary_record s ON m.miner_id = s.miner_id;-- 一般原则：-- 1. JOIN性能通常优于子查询-- 2. 简单过滤用子查询更直观-- 3. 复杂关联用JOIN更高效-- 4. MySQL 8.0优化了子查询，差距在缩小
子查询 vs JOIN 性能对比：
场景1：简单过滤 WHERE miner_id IN (SELECT …) → 子查询更直观，性能相当 场景2：需要多表字段 JOIN后直接SELECT多表字段 → JOIN更高效，一次查询完成 场景3：相关子查询 WHERE EXISTS (SELECT … WHERE 外键&#x3D;主键) → 每行都要执行子查询，性能差 → 改为JOIN通常更高效 场景4：MySQL 8.0 半连接优化 MySQL 8.0会将IN子查询优化为半连接 子查询和JOIN性能差距缩小
常见多表查询场景1. 一对多查询-- 智慧矿山：查询矿工及其薪资发放次数SELECT m.miner_name, COUNT(s.id) AS salary_countFROM miner mLEFT JOIN salary_record s ON m.miner_id = s.miner_idGROUP BY m.miner_id;-- 智慧矿山：查询每个矿区的设备数量SELECT a.area_name, COUNT(e.id) AS equipment_countFROM mine_area aLEFT JOIN equipment e ON a.id = e.area_idGROUP BY a.id;
2. 多对多查询-- 智慧矿山：矿工-巡检路线（通过中间表关联）SELECT m.miner_name, r.route_nameFROM miner mINNER JOIN miner_route mr ON m.miner_id = mr.miner_idINNER JOIN patrol_route r ON mr.route_id = r.idWHERE m.role = &#x27;安全巡查员&#x27;;
3. 分组统计-- 智慧矿山：每个部门的矿工数和平均薪资SELECT d.dept_name AS dept_name, COUNT(m.miner_id) AS miner_count, AVG(m.salary_amount) AS avg_salaryFROM mine_dept dLEFT JOIN miner m ON d.id = m.dept_idGROUP BY d.id;-- 智慧矿山：每个矿区每月的安全隐患统计SELECT a.area_name, DATE_FORMAT(h.report_time, &#x27;%Y-%m&#x27;) AS month, COUNT(*) AS hazard_count, SUM(CASE WHEN h.level = &#x27;严重&#x27; THEN 1 ELSE 0 END) AS critical_countFROM mine_area aLEFT JOIN safety_hazard h ON a.id = h.area_idGROUP BY a.id, DATE_FORMAT(h.report_time, &#x27;%Y-%m&#x27;);
4. 行转列-- 智慧矿山：矿工每月出勤天数（每月一行，各月为列）SELECT m.miner_name, MAX(CASE WHEN DATE_FORMAT(a.date, &#x27;%m&#x27;) = &#x27;01&#x27; THEN 1 ELSE 0 END) AS jan, MAX(CASE WHEN DATE_FORMAT(a.date, &#x27;%m&#x27;) = &#x27;02&#x27; THEN 1 ELSE 0 END) AS feb, MAX(CASE WHEN DATE_FORMAT(a.date, &#x27;%m&#x27;) = &#x27;03&#x27; THEN 1 ELSE 0 END) AS mar, MAX(CASE WHEN DATE_FORMAT(a.date, &#x27;%m&#x27;) = &#x27;04&#x27; THEN 1 ELSE 0 END) AS apr, MAX(CASE WHEN DATE_FORMAT(a.date, &#x27;%m&#x27;) = &#x27;05&#x27; THEN 1 ELSE 0 END) AS may, MAX(CASE WHEN DATE_FORMAT(a.date, &#x27;%m&#x27;) = &#x27;06&#x27; THEN 1 ELSE 0 END) AS junFROM miner mLEFT JOIN attendance a ON m.miner_id = a.miner_idGROUP BY m.miner_id;
5. 连续登录判断-- 智慧矿山：查询连续3天出勤的矿工SELECT miner_idFROM ( SELECT miner_id, attendance_date, DATE_SUB(attendance_date, INTERVAL ROW_NUMBER() OVER( PARTITION BY miner_id ORDER BY attendance_date ) DAY) AS grp FROM ( SELECT DISTINCT miner_id, DATE(check_time) AS attendance_date FROM attendance WHERE check_time &gt;= &#x27;2022-06-01&#x27; ) t1) t2GROUP BY miner_id, grpHAVING COUNT(*) &gt;= 3;
6. 层级查询-- 智慧矿山：查询矿区的组织树-- MySQL 8.0+ 递归CTEWITH RECURSIVE area_tree AS ( -- 锚点：顶级矿区 SELECT id, area_name, parent_id, 1 AS level FROM mine_area WHERE parent_id IS NULL UNION ALL -- 递归：下级矿区 SELECT a.id, a.area_name, a.parent_id, t.level + 1 FROM mine_area a INNER JOIN area_tree t ON a.parent_id = t.id)SELECT * FROM area_tree ORDER BY level, id;
多表查询优化1. 确保JOIN字段有索引-- 被驱动表的JOIN字段必须建索引-- 智慧矿山：薪资记录表的miner_id-- 查看表的索引SHOW INDEX FROM salary_record;-- 添加索引ALTER TABLE salary_record ADD INDEX idx_miner_id(miner_id);-- 验证EXPLAINEXPLAIN SELECT m.miner_name, s.salary_amountFROM miner mINNER JOIN salary_record s ON m.miner_id = s.miner_id;-- type列应该是ref，不是ALL
2. 减少JOIN的表数-- ❌ 5张表JOINSELECT m.miner_name, d.dept_name, s.salary_amount, a.attendance_days, h.hazard_countFROM miner mJOIN mine_dept d ON m.dept_id = d.idJOIN salary_record s ON m.miner_id = s.miner_idJOIN attendance a ON m.miner_id = a.miner_idJOIN safety_hazard h ON m.miner_id = h.inspector_id;-- ✅ 拆分为多次查询，代码中组装-- 查询1：矿工基本信息+部门-- 查询2：薪资记录-- 查询3：考勤统计-- 查询4：安全隐患统计-- 超过3张表JOIN时考虑拆分
JOIN表数与性能关系：
核心查询不超过3张表JOIN 非必要字段通过子查询或额外查询获取 宽表拆分查询后在应用层组装
3. 先过滤再JOIN-- ❌ 先JOIN再过滤SELECT m.miner_name, s.salary_amountFROM miner mINNER JOIN salary_record s ON m.miner_id = s.miner_idWHERE m.status = 1 AND s.salary_month = &#x27;2022-06&#x27;;-- ✅ 先过滤再JOIN（优化器通常会自动做）SELECT m.miner_name, s.salary_amountFROM (SELECT * FROM miner WHERE status = 1) mINNER JOIN (SELECT * FROM salary_record WHERE salary_month = &#x27;2022-06&#x27;) sON m.miner_id = s.miner_id;
4. 避免SELECT *-- ❌ 查询所有字段SELECT * FROM miner m INNER JOIN salary_record s ON m.miner_id = s.miner_id;-- ✅ 只查需要的字段SELECT m.miner_name, s.salary_amount, s.salary_monthFROM miner mINNER JOIN salary_record s ON m.miner_id = s.miner_id;-- 好处：-- 1. 减少网络传输-- 2. 可能使用覆盖索引-- 3. 避免歧义列（两张表都有id）
5. 使用覆盖索引优化JOIN-- 智慧矿山：优化矿工薪资查询-- ❌ 需要回表SELECT m.miner_name, s.salary_amountFROM miner mINNER JOIN salary_record s ON m.miner_id = s.miner_idWHERE s.salary_month = &#x27;2022-06&#x27;;-- ✅ 建覆盖索引避免回表ALTER TABLE salary_record ADD INDEX idx_miner_month_amount(miner_id, salary_month, salary_amount);-- 覆盖索引包含JOIN字段+查询字段，不需要回表
多表查询实战矿工考勤统计报表-- 智慧矿山：月度考勤统计报表SELECT m.miner_id, m.miner_name, d.dept_name, COUNT(a.id) AS attendance_days, SUM(CASE WHEN a.status = &#x27;正常&#x27; THEN 1 ELSE 0 END) AS normal_days, SUM(CASE WHEN a.status = &#x27;迟到&#x27; THEN 1 ELSE 0 END) AS late_days, SUM(CASE WHEN a.status = &#x27;早退&#x27; THEN 1 ELSE 0 END) AS early_days, SUM(CASE WHEN a.status = &#x27;缺勤&#x27; THEN 1 ELSE 0 END) AS absent_days, ROUND(SUM(CASE WHEN a.status = &#x27;正常&#x27; THEN 1 ELSE 0 END) * 100.0 / 22, 1) AS attendance_rateFROM miner mINNER JOIN mine_dept d ON m.dept_id = d.idLEFT JOIN attendance a ON m.miner_id = a.miner_id AND a.date &gt;= &#x27;2022-06-01&#x27; AND a.date &lt; &#x27;2022-07-01&#x27;GROUP BY m.miner_id, m.miner_name, d.dept_nameORDER BY attendance_rate DESC;
设备维护统计-- 智慧矿山：设备维护统计SELECT e.equipment_name, a.area_name, COUNT(m.id) AS maintenance_count, SUM(CASE WHEN m.type = &#x27;日常保养&#x27; THEN 1 ELSE 0 END) AS routine_count, SUM(CASE WHEN m.type = &#x27;故障维修&#x27; THEN 1 ELSE 0 END) AS repair_count, AVG(m.cost) AS avg_cost, MAX(m.end_time - m.start_time) AS max_durationFROM equipment eINNER JOIN mine_area a ON e.area_id = a.idLEFT JOIN equipment_maintenance m ON e.id = m.equipment_id AND m.start_time &gt;= &#x27;2022-01-01&#x27;GROUP BY e.id, e.equipment_name, a.area_nameHAVING maintenance_count &gt; 0ORDER BY repair_count DESC;
安全巡检异常分析-- 智慧矿山：安全巡检异常分析SELECT a.area_name, h.hazard_type, COUNT(*) AS total_count, SUM(CASE WHEN h.status = &#x27;PENDING&#x27; THEN 1 ELSE 0 END) AS pending_count, SUM(CASE WHEN h.status = &#x27;PROCESSING&#x27; THEN 1 ELSE 0 END) AS processing_count, SUM(CASE WHEN h.status = &#x27;RESOLVED&#x27; THEN 1 ELSE 0 END) AS resolved_count, SUM(CASE WHEN h.level = &#x27;严重&#x27; THEN 1 ELSE 0 END) AS critical_count, AVG(DATEDIFF(h.resolve_time, h.report_time)) AS avg_resolve_daysFROM mine_area aINNER JOIN safety_hazard h ON a.id = h.area_idWHERE h.report_time &gt;= &#x27;2022-01-01&#x27;GROUP BY a.id, a.area_name, h.hazard_typeORDER BY critical_count DESC, pending_count DESC;
总结多表查询是SQL能力的核心体现。在实际场景中，我从”只会单表查询”到”熟练使用JOIN和子查询”，核心收获是：JOIN字段加索引、小表驱动大表、避免过多表关联。掌握这几点，多表查询的性能就不会差。 经过深入学习，我还理解了：
Nested Loop Join是MySQL默认的JOIN算法，被驱动表有索引时走Index Nested Loop MySQL 8.0引入Hash Join替代Block Nested Loop，无索引JOIN性能大幅提升 子查询和JOIN的选择取决于场景，简单过滤用子查询，复杂关联用JOIN 递归CTE是MySQL 8.0处理层级数据的利器 合理的索引设计和查询拆分是优化多表查询的关键

前言 在实际场景中，刚写接口的时候，URL命名随心所欲：&#x2F;getUser、&#x2F;deleteOrder、&#x2F;queryList，各种风格混搭。直到和前端联调时，接口命名不统一、状态码不一致、返回格式混乱，联调效率极低。后来统一了RESTful规范，前后端协作顺畅了很多。 什么是RESTful？REST（Representational State Transfer）是一种架构风格，核心思想：用URL定位资源，用HTTP方法描述操作* 核心原则 URL表示资源：名词，不用动词 HTTP方法表示操作：GET查询、POST新增、PUT修改、DELETE删除 状态码语义化：200成功、400客户端错误、404不存在、500服务端错误 返回格式统一：统一的JSON结构
URL设计规范反面教材// ❌ URL中包含动词@GetMapping(&quot;/getUserById&quot;)@GetMapping(&quot;/deleteUser&quot;)@GetMapping(&quot;/queryUserList&quot;)@PostMapping(&quot;/updateUserName&quot;)// ❌ URL风格不统一@GetMapping(&quot;/user/list&quot;)@GetMapping(&quot;/user_detail&quot;)@PostMapping(&quot;/addUser&quot;)
正确姿势// ✅ 资源用名词复数GET /users → 查询用户列表GET /users/&#123;id&#125; → 查询指定用户POST /users → 新增用户PUT /users/&#123;id&#125; → 修改指定用户DELETE /users/&#123;id&#125; → 删除指定用户
常见资源操作// 用户管理GET /users → 用户列表GET /users/&#123;id&#125; → 用户详情POST /users → 创建用户PUT /users/&#123;id&#125; → 更新用户（全量）PATCH /users/&#123;id&#125; → 更新用户（部分）DELETE /users/&#123;id&#125; → 删除用户// 子资源GET /users/&#123;id&#125;/orders → 用户的订单列表GET /users/&#123;id&#125;/orders/&#123;oid&#125; → 用户的指定订单// 非CRUD操作（动作型资源）POST /users/&#123;id&#125;/activation → 激活用户POST /orders/&#123;id&#125;/cancel → 取消订单POST /orders/&#123;id&#125;/payment → 支付订单
HTTP方法语义
方法 语义 幂等性 安全性
GET 查询 幂等 安全
POST 新增 非幂等 不安全
PUT 全量修改 幂等 不安全
PATCH 部分修改 幂等 不安全
DELETE 删除 幂等 不安全
幂等性：多次调用结果一致。GET查询多次结果一样，PUT全量替换多次结果一样，POST每次新增一条记录所以非幂等。 统一返回格式返回结构public class Result&lt;T&gt; &#123; private int code; // 业务状态码 private String msg; // 提示信息 private T data; // 数据 public static &lt;T&gt; Result&lt;T&gt; success(T data) &#123; return new Result&lt;&gt;(200, &quot;success&quot;, data); &#125; public static &lt;T&gt; Result&lt;T&gt; fail(String msg) &#123; return new Result&lt;&gt;(500, msg, null); &#125; public static &lt;T&gt; Result&lt;T&gt; fail(int code, String msg) &#123; return new Result&lt;&gt;(code, msg, null); &#125;&#125;
成功响应// GET /users/1&#123; &quot;code&quot;: 200, &quot;msg&quot;: &quot;success&quot;, &quot;data&quot;: &#123; &quot;id&quot;: 1, &quot;name&quot;: &quot;张三&quot;, &quot;age&quot;: 25 &#125;&#125;// GET /users&#123; &quot;code&quot;: 200, &quot;msg&quot;: &quot;success&quot;, &quot;data&quot;: &#123; &quot;list&quot;: [...], &quot;total&quot;: 100, &quot;page&quot;: 1, &quot;size&quot;: 10 &#125;&#125;
错误响应&#123; &quot;code&quot;: 400, &quot;msg&quot;: &quot;参数校验失败: 用户名不能为空&quot;, &quot;data&quot;: null&#125;
分页查询规范// 分页参数@GetMapping(&quot;/users&quot;)public Result&lt;PageResult&lt;User&gt;&gt; list( @RequestParam(defaultValue = &quot;1&quot;) int page, @RequestParam(defaultValue = &quot;10&quot;) int size, @RequestParam(required = false) String keyword, @RequestParam(required = false) Integer status) &#123; PageResult&lt;User&gt; result = userService.list(page, size, keyword, status); return Result.success(result);&#125;
分页返回： &#123; &quot;code&quot;: 200, &quot;msg&quot;: &quot;success&quot;, &quot;data&quot;: &#123; &quot;list&quot;: [ &#123;&quot;id&quot;: 1, &quot;name&quot;: &quot;张三&quot;&#125;, &#123;&quot;id&quot;: 2, &quot;name&quot;: &quot;李四&quot;&#125; ], &quot;total&quot;: 100, &quot;page&quot;: 1, &quot;size&quot;: 10 &#125;&#125;
Controller层规范@RestController@RequestMapping(&quot;/users&quot;)public class UserController &#123; @Autowired private UserService userService; @GetMapping public Result&lt;PageResult&lt;UserVO&gt;&gt; list(@Valid UserQueryDTO dto) &#123; return Result.success(userService.list(dto)); &#125; @GetMapping(&quot;/&#123;id&#125;&quot;) public Result&lt;UserVO&gt; getById(@PathVariable Long id) &#123; return Result.success(userService.getById(id)); &#125; @PostMapping public Result&lt;Void&gt; add(@RequestBody @Valid UserCreateDTO dto) &#123; userService.add(dto); return Result.success(null); &#125; @PutMapping(&quot;/&#123;id&#125;&quot;) public Result&lt;Void&gt; update(@PathVariable Long id, @RequestBody @Valid UserUpdateDTO dto) &#123; userService.update(id, dto); return Result.success(null); &#125; @DeleteMapping(&quot;/&#123;id&#125;&quot;) public Result&lt;Void&gt; delete(@PathVariable Long id) &#123; userService.delete(id); return Result.success(null); &#125;&#125;
HTTP状态码使用// 业务层统一用200 + 自定义code// HTTP状态码按语义使用200 OK → 成功201 Created → 创建成功400 Bad Request → 参数错误401 Unauthorized → 未认证403 Forbidden → 无权限404 Not Found → 资源不存在500 Internal → 服务端错误
实际开发中，很多团队HTTP状态码统一返回200，通过body中的code区分业务状态，前端处理更简单。 API版本管理// 方式1：URL路径版本（推荐）@GetMapping(&quot;/v1/users&quot;)@GetMapping(&quot;/v2/users&quot;)// 方式2：请求头版本@GetMapping(value = &quot;/users&quot;, headers = &quot;X-API-Version=1&quot;)
API文档使用Swagger&#x2F;SpringDoc自动生成API文档： @Tag(name = &quot;用户管理&quot;)@RestController@RequestMapping(&quot;/users&quot;)public class UserController &#123; @Operation(summary = &quot;查询用户列表&quot;) @GetMapping public Result&lt;PageResult&lt;UserVO&gt;&gt; list(@Valid UserQueryDTO dto) &#123; return Result.success(userService.list(dto)); &#125;&#125;
总结 RESTful API设计不是教条，而是一种约定。从”随意写接口”到”规范设计API”最大的收获是：好的API设计让前后端协作效率翻倍*URL表示资源、HTTP方法表示操作、返回格式统一、状态码语义化——这四条原则足够覆盖90%的接口设计场景。

前言 2022年，我参与了实际项目的开发。这是一个覆盖煤矿生产全流程的管理系统，包括人员定位、设备监控、安全预警、生产调度等模块。项目中大量使用枚举和JSON字段：矿工状态有在职&#x2F;离职&#x2F;休假，设备状态有闲置&#x2F;使用中&#x2F;维护中&#x2F;故障，设备规格信息需要存为JSON，传感器配置参数也需要JSON存储。 数据库里存的是int和varchar，Java里用的是枚举和JSON对象，两者之间怎么映射？最初我在代码里手动转换，到处都是switch-case和JSON.parse，又丑又容易出错。特别是设备规格字段，存的是JSON字符串，每次都要手动序列化&#x2F;反序列化，稍有不慎就会出bug。直到学会TypeHandler，才知道MyBatis早就提供了优雅的解决方案。 本文结合实际项目的实战经验，系统讲解MyBatis类型处理器的原理、枚举映射、JSON字段处理和自定义TypeHandler。 TypeHandler是什么？TypeHandler是MyBatis中Java类型与JDBC类型之间的转换器： TypeHandler工作原理
Java代码 TypeHandler JDBC&#x2F;数据库 WorkerStatus → setParameter() → TINYINT(int) (枚举对象) (枚举-&gt;int) (数据库存储) WorkerStatus ← getResult() ← TINYINT(int) (枚举对象) (int-&gt;枚举) (查询结果) EquipmentSpec → setParameter() → JSON(varchar) (Java对象) (对象-&gt;JSON) (数据库存储) EquipmentSpec ← getResult() ← JSON(varchar) (Java对象) (JSON-&gt;对象) (查询结果)
每次MyBatis执行SQL时，参数的设置和结果的读取都要经过TypeHandler。 内置TypeHandlerMyBatis内置了大量TypeHandler，覆盖了常见类型： 常用内置TypeHandler
Java类型 | JDBC类型 | TypeHandler String | VARCHAR | StringTypeHandler Integer | INTEGER | IntegerTypeHandler Long | BIGINT | LongTypeHandler LocalDateTime | TIMESTAMP | LocalDateTimeTypeHandler BigDecimal | DECIMAL | BigDecimalTypeHandler byte[] | BLOB | ByteArrayTypeHandler Boolean | BIT | BooleanTypeHandler Date | TIMESTAMP | DateTypeHandler
大部分情况下不需要关心TypeHandler，MyBatis会自动选择。 枚举类型处理问题// Java枚举 - 矿工状态public enum WorkerStatus &#123; RESIGNED(0, &quot;离职&quot;), ON_DUTY(1, &quot;在职&quot;), ON_VACATION(2, &quot;休假&quot;); private final int code; private final String desc; WorkerStatus(int code, String desc) &#123; this.code = code; this.desc = desc; &#125;&#125;// 数据库存的是int：0/1/2// MyBatis默认用EnumTypeHandler，存的是枚举名称&quot;RESIGNED&quot;/&quot;ON_DUTY&quot;// 和数据库不匹配！
枚举映射问题
数据库值 | 期望Java类型 | 默认TypeHandler映射 | 问题 0 | RESIGNED | “RESIGNED”(字符串) | 不匹配 1 | ON_DUTY | “ON_DUTY”(字符串) | 不匹配 2 | ON_VACATION | “ON_VACATION”(字符串) | 不匹配 数据库存0&#x2F;1&#x2F;2，默认映射存枚举名称，严重不匹配！
方式1：@EnumValue（MyBatis-Plus推荐）public enum WorkerStatus &#123; RESIGNED(0, &quot;离职&quot;), ON_DUTY(1, &quot;在职&quot;), ON_VACATION(2, &quot;休假&quot;); @EnumValue // 标记存入数据库的值 private final int code; private final String desc; WorkerStatus(int code, String desc) &#123; this.code = code; this.desc = desc; &#125; public int getCode() &#123; return code; &#125; public String getDesc() &#123; return desc; &#125;&#125;
# application.yml配置mybatis-plus: configuration: default-enum-type-handler: org.apache.ibatis.type.EnumOrdinalTypeHandler
使用@EnumValue后，MyBatis-Plus自动处理枚举与int的映射。 方式2：自定义TypeHandler@MappedTypes(WorkerStatus.class)public class WorkerStatusTypeHandler extends BaseTypeHandler&lt;WorkerStatus&gt; &#123; @Override public void setNonNullParameter(PreparedStatement ps, int i, WorkerStatus parameter, JdbcType jdbcType) throws SQLException &#123; ps.setInt(i, parameter.getCode()); // 枚举 -&gt; int &#125; @Override public WorkerStatus getNullableResult(ResultSet rs, String columnName) throws SQLException &#123; int code = rs.getInt(columnName); return WorkerStatus.valueOf(code); // int -&gt; 枚举 &#125; @Override public WorkerStatus getNullableResult(ResultSet rs, int columnIndex) throws SQLException &#123; int code = rs.getInt(columnIndex); return WorkerStatus.valueOf(code); &#125; @Override public WorkerStatus getNullableResult(CallableStatement cs, int columnIndex) throws SQLException &#123; int code = cs.getInt(columnIndex); return WorkerStatus.valueOf(code); &#125;&#125;
枚举中添加valueOf方法： public enum WorkerStatus &#123; RESIGNED(0, &quot;离职&quot;), ON_DUTY(1, &quot;在职&quot;), ON_VACATION(2, &quot;休假&quot;); private final int code; private final String desc; private static final Map&lt;Integer, WorkerStatus&gt; CODE_MAP = Arrays.stream(values()) .collect(Collectors.toMap(WorkerStatus::getCode, Function.identity())); WorkerStatus(int code, String desc) &#123; this.code = code; this.desc = desc; &#125; public int getCode() &#123; return code; &#125; public String getDesc() &#123; return desc; &#125; public static WorkerStatus valueOf(int code) &#123; WorkerStatus status = CODE_MAP.get(code); if (status == null) &#123; throw new IllegalArgumentException(&quot;无效的矿工状态: &quot; + code); &#125; return status; &#125;&#125;
注册TypeHandler： # application.ymlmybatis: type-handlers-package: com.mine.smart.handler
JSON字段处理MySQL 5.7+支持JSON类型，但MyBatis默认不处理JSON与Java对象的映射。 自定义JSON TypeHandler/** * 通用JSON类型处理器 - 实际项目 */@MappedTypes(Object.class)public class JsonTypeHandler&lt;T&gt; extends BaseTypeHandler&lt;T&gt; &#123; private static final ObjectMapper MAPPER = new ObjectMapper(); static &#123; // 配置Jackson MAPPER.registerModule(new JavaTimeModule()); MAPPER.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS); MAPPER.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false); &#125; private final Class&lt;T&gt; type; public JsonTypeHandler(Class&lt;T&gt; type) &#123; if (type == null) &#123; throw new IllegalArgumentException(&quot;Type argument cannot be null&quot;); &#125; this.type = type; &#125; @Override public void setNonNullParameter(PreparedStatement ps, int i, T parameter, JdbcType jdbcType) throws SQLException &#123; try &#123; ps.setString(i, MAPPER.writeValueAsString(parameter)); &#125; catch (JsonProcessingException e) &#123; throw new SQLException(&quot;Error converting object to JSON&quot;, e); &#125; &#125; @Override public T getNullableResult(ResultSet rs, String columnName) throws SQLException &#123; return parseJson(rs.getString(columnName)); &#125; @Override public T getNullableResult(ResultSet rs, int columnIndex) throws SQLException &#123; return parseJson(rs.getString(columnIndex)); &#125; @Override public T getNullableResult(CallableStatement cs, int columnIndex) throws SQLException &#123; return parseJson(cs.getString(columnIndex)); &#125; private T parseJson(String json) throws SQLException &#123; if (json == null || json.isEmpty()) &#123; return null; &#125; try &#123; return MAPPER.readValue(json, type); &#125; catch (JsonProcessingException e) &#123; throw new SQLException(&quot;Error parsing JSON: &quot; + json, e); &#125; &#125;&#125;
通用枚举TypeHandler项目中有很多枚举，每个都写一个TypeHandler太麻烦。可以写一个通用的： /** * 通用枚举TypeHandler - 实际项目 * 所有实现BaseEnum接口的枚举都自动支持 */public abstract class BaseEnumTypeHandler&lt;E extends Enum&lt;E&gt; &amp; BaseEnum&gt; extends BaseTypeHandler&lt;E&gt; &#123; private final Class&lt;E&gt; type; private final E[] enums; private final Method getCodeMethod; public BaseEnumTypeHandler(Class&lt;E&gt; type) &#123; this.type = type; this.enums = type.getEnumConstants(); try &#123; this.getCodeMethod = type.getMethod(&quot;getCode&quot;); &#125; catch (NoSuchMethodException e) &#123; throw new RuntimeException(&quot;枚举类必须有getCode方法&quot;, e); &#125; &#125; @Override public void setNonNullParameter(PreparedStatement ps, int i, E parameter, JdbcType jdbcType) throws SQLException &#123; try &#123; ps.setInt(i, (int) getCodeMethod.invoke(parameter)); &#125; catch (IllegalAccessException | InvocationTargetException e) &#123; throw new SQLException(&quot;获取枚举code失败&quot;, e); &#125; &#125; @Override public E getNullableResult(ResultSet rs, String columnName) throws SQLException &#123; int code = rs.getInt(columnName); return fromCode(code); &#125; @Override public E getNullableResult(ResultSet rs, int columnIndex) throws SQLException &#123; int code = rs.getInt(columnIndex); return fromCode(code); &#125; @Override public E getNullableResult(CallableStatement cs, int columnIndex) throws SQLException &#123; int code = cs.getInt(columnIndex); return fromCode(code); &#125; private E fromCode(int code) &#123; for (E e : enums) &#123; try &#123; if ((int) getCodeMethod.invoke(e) == code) &#123; return e; &#125; &#125; catch (IllegalAccessException | InvocationTargetException ex) &#123; throw new RuntimeException(ex); &#125; &#125; throw new IllegalArgumentException(&quot;无效的枚举值: &quot; + code); &#125;&#125;
使用通用TypeHandler// 矿工状态TypeHandlerpublic class WorkerStatusTypeHandler extends BaseEnumTypeHandler&lt;WorkerStatus&gt; &#123; public WorkerStatusTypeHandler() &#123; super(WorkerStatus.class); &#125;&#125;// 设备状态TypeHandlerpublic class EquipmentStatusTypeHandler extends BaseEnumTypeHandler&lt;EquipmentStatus&gt; &#123; public EquipmentStatusTypeHandler() &#123; super(EquipmentStatus.class); &#125;&#125;// 告警等级TypeHandlerpublic class AlarmLevelTypeHandler extends BaseEnumTypeHandler&lt;AlarmLevel&gt; &#123; public AlarmLevelTypeHandler() &#123; super(AlarmLevel.class); &#125;&#125;
JSON字段进阶JSON字段校验/** * JSON字段校验 - 存入数据库前校验 */@AssertTrue(message = &quot;设备规格校验失败&quot;)public boolean isSpecValid() &#123; if (spec == null) return true; if (spec.getWeight() != null &amp;&amp; spec.getWeight().compareTo(BigDecimal.ZERO) &lt;= 0) &#123; return false; &#125; if (spec.getProductionDate() != null &amp;&amp; spec.getProductionDate().isAfter(LocalDate.now())) &#123; return false; &#125; return true;&#125;
JSON字段默认值// Entity中设置默认值@TableField(typeHandler = JsonTypeHandler.class)private EquipmentSpec spec = new EquipmentSpec(); // 默认空对象@TableField(typeHandler = JsonTypeHandler.class)private List&lt;String&gt; tags = new ArrayList&lt;&gt;(); // 默认空列表
JSON字段查询&lt;!-- MySQL JSON查询函数 --&gt;&lt;select id=&quot;selectBySpecColor&quot; resultType=&quot;Equipment&quot;&gt; SELECT * FROM t_equipment WHERE JSON_UNQUOTE(JSON_EXTRACT(spec, &#x27;$.color&#x27;)) = #&#123;color&#125; AND deleted = 0&lt;/select&gt;&lt;!-- MySQL 5.7.9+ 简写 --&gt;&lt;select id=&quot;selectBySpecColor&quot; resultType=&quot;Equipment&quot;&gt; SELECT * FROM t_equipment WHERE spec-&gt;&gt;&#x27;$.color&#x27; = #&#123;color&#125; AND deleted = 0&lt;/select&gt;
JSON字段更新// 使用UpdateWrapper更新JSON字段LambdaUpdateWrapper&lt;Equipment&gt; wrapper = new LambdaUpdateWrapper&lt;&gt;();wrapper.set(Equipment::getSpec, newSpec) .eq(Equipment::getId, id);equipmentMapper.update(null, wrapper);// 注意：直接set新对象，MyBatis-Plus会通过TypeHandler转为JSON
类型处理器注册方式TypeHandler注册方式对比
方式 | 优点 | 缺点 包扫描(推荐) | 自动发现 | 需要@MappedTypes @Component | Spring管理 | 需要Spring环境 XML配置 | 精确控制 | 配置繁琐 @TableField指定 | 字段级控制 | 每个字段都要指定
# 方式1：包扫描（推荐）mybatis: type-handlers-package: com.mine.smart.handler# 方式2：全局默认枚举处理mybatis-plus: configuration: default-enum-type-handler: org.apache.ibatis.type.EnumOrdinalTypeHandler
// 方式3：@TableField字段级指定@TableField(typeHandler = JsonTypeHandler.class)private EquipmentSpec spec;
总结TypeHandler是MyBatis中容易被忽略但非常实用的功能。在实际场景中，通过TypeHandler统一处理枚举和JSON字段的映射，代码更简洁、更安全。核心认知：不要在业务代码中手动转换枚举和JSON，交给TypeHandler统一处理——枚举用@EnumValue，JSON用自定义TypeHandler，代码更简洁、更安全。 关键经验总结：
枚举用@EnumValue，简单高效 JSON字段用自定义TypeHandler，自动序列化&#x2F;反序列化 autoResultMap &#x3D; true是TypeHandler生效的前提 枚举统一实现BaseEnum接口，方便通用处理 JSON字段查询性能用虚拟列+索引优化 VO层增加枚举描述字段，方便前端展示

前言 刚做实际项目时，所有配置都写在application.yml里，开发环境和生产环境的数据库密码、Redis地址都不一样，每次发版手动改配置，经常出错。有一次把开发环境的数据库地址推到了生产环境，导致瓦斯监测系统连不上生产数据库，差点造成安全事故。后来学会了多环境配置和配置加密，才彻底解决了这个问题。 配置文件格式SpringBoot支持两种格式：properties和yml # application.yml（推荐，层级清晰）server: port: 8080 servlet: context-path: /apispring: datasource: url: jdbc:mysql://localhost:3306/mine_db username: root password: 123456 driver-class-name: com.mysql.cj.jdbc.Driver
# application.propertiesserver.port=8080server.servlet.context-path=/apispring.datasource.url=jdbc:mysql://localhost:3306/mine_dbspring.datasource.username=rootspring.datasource.password=123456
yml vs propertiesyml vs properties 对比
特性 | yml | properties ————-|————————|————————— 层级关系 | 缩进表示，清晰 | 用.分隔，扁平 可读性 | 高 | 一般 重复前缀 | 不需要 | 每行都要写 列表&#x2F;Map | 原生支持 | 需要下标[0] 多Profile | 同文件用—分隔 | 需要多文件 松绑定 | 支持 | 支持 注意事项 | 缩进必须用空格 | 无
多环境配置文件命名规则application.yml -&gt; 公共配置application-dev.yml -&gt; 开发环境application-test.yml -&gt; 测试环境application-prod.yml -&gt; 生产环境
多环境配置文件结构
src&#x2F;main&#x2F;resources&#x2F; application.yml # 公共配置（激活哪个环境） application-dev.yml # 开发环境配置 application-test.yml # 测试环境配置 application-prod.yml # 生产环境配置 加载顺序： application.yml (公共)
application-{profile}.yml (环境特定，覆盖公共)
环境特定配置 &gt; 公共配置（相同key会覆盖）
激活环境# application.ymlspring: profiles: active: dev # 激活dev环境
# 命令行激活（推荐，运维层面控制）java -jar mine-app.jar --spring.profiles.active=prod# 环境变量激活export SPRING_PROFILES_ACTIVE=prodjava -jar mine-app.jar# JVM参数激活java -Dspring.profiles.active=prod -jar mine-app.jar
读取配置@Value@Componentpublic class DeviceConfig &#123; @Value(&quot;$&#123;mine.device.gateway-url&#125;&quot;) private String gatewayUrl; @Value(&quot;$&#123;mine.device.heartbeat-interval:30&#125;&quot;) // 默认值30 private int heartbeatInterval; @Value(&quot;$&#123;mine.device.retry-count:3&#125;&quot;) private int retryCount;&#125;
@ConfigurationProperties（推荐）@Component@ConfigurationProperties(prefix = &quot;mine.device&quot;)@Validatedpublic class MineDeviceProperties &#123; /** 通信网关地址 */ @NotBlank(message = &quot;设备网关地址不能为空&quot;) private String gatewayUrl; /** 心跳间隔（秒） */ @Min(value = 5, message = &quot;心跳间隔不能小于5秒&quot;) @Max(value = 120, message = &quot;心跳间隔不能大于120秒&quot;) private int heartbeatInterval = 30; /** 连接超时（毫秒） */ @Min(1000) @Max(30000) private int connectTimeout = 5000; /** 读超时（毫秒） */ @Min(500) @Max(10000) private int readTimeout = 3000; /** 重连次数 */ @Min(0) @Max(10) private int retryCount = 3; /** 是否启用 */ private boolean enabled = true; // getter/setter&#125;
Environment@Componentpublic class ConfigReader &#123; @Autowired private Environment env; public void read() &#123; String gatewayUrl = env.getProperty(&quot;mine.device.gateway-url&quot;); String port = env.getProperty(&quot;server.port&quot;, &quot;8080&quot;); String[] activeProfiles = env.getActiveProfiles(); // 判断当前环境 if (env.acceptsProfiles(Profiles.of(&quot;prod&quot;))) &#123; log.info(&quot;当前为生产环境&quot;); &#125; &#125;&#125;
@Value vs @ConfigurationProperties功能 | 单个属性注入 | 批量属性注入
@Value vs @ConfigurationProperties 特性 | @Value | @ConfigurationProperties ————-|————————|————————— 松绑定 | 不支持 | 支持（驼峰&#x2F;下划线&#x2F;短横线） SpEL | 支持 | 不支持 校验 | 不支持 | 支持@Validated 复杂对象 | 不支持 | 支持List&#x2F;Map&#x2F;嵌套对象 默认值 | :defaultValue | 字段初始化赋值 适用场景 | 1-2个简单属性 | 一组相关属性 推荐度 | 简单场景 | 复杂配置（推荐）
配置加密生产环境密码不能明文写在配置文件中。 jasypt-spring-boot&lt;dependency&gt; &lt;groupId&gt;com.github.ulisesbocchio&lt;/groupId&gt; &lt;artifactId&gt;jasypt-spring-boot-starter&lt;/artifactId&gt; &lt;version&gt;3.0.5&lt;/version&gt;&lt;/dependency&gt;
# 加密配置spring: datasource: password: ENC(加密后的密文)jasypt: encryptor: password: $&#123;JASYPT_PASSWORD&#125; # 密钥从环境变量读取 algorithm: PBEWithMD5AndDES iv-generator-classname: org.jasypt.iv.NoIvGenerator
// 加密工具@Testpublic void encrypt() &#123; StandardPBEStringEncryptor encryptor = new StandardPBEStringEncryptor(); encryptor.setPassword(&quot;my-secret-key&quot;); String encrypted = encryptor.encrypt(&quot;prod_password&quot;); System.out.println(&quot;ENC(&quot; + encrypted + &quot;)&quot;);&#125;// 解密验证@Testpublic void decrypt() &#123; StandardPBEStringEncryptor encryptor = new StandardPBEStringEncryptor(); encryptor.setPassword(&quot;my-secret-key&quot;); String decrypted = encryptor.decrypt(&quot;加密后的密文&quot;); System.out.println(decrypted);&#125;
环境变量方式（最安全）# 最安全的方式：密码从环境变量读取spring: datasource: password: $&#123;DB_PASSWORD&#125; data: redis: password: $&#123;REDIS_PASSWORD&#125;mine: device: gateway-url: $&#123;DEVICE_GATEWAY_URL:tcp://localhost:8888&#125;
# 启动时设置环境变量export DB_PASSWORD=prod_passwordexport REDIS_PASSWORD=redis_passwordexport DEVICE_GATEWAY_URL=tcp://device-gateway-prod:8888java -jar mine-app.jar --spring.profiles.active=prod
配置安全性对比配置安全性方案对比
方案 | 安全等级 | 优点 | 缺点 ——————-|———|——————-|—————- 明文配置 | 低 | 简单 | 密码泄露风险 Jasypt加密 | 中 | 配置文件不可读 | 密钥仍需管理 环境变量 | 高 | 不入库 | 运维需配置 配置中心(Nacos) | 高 | 统一管理+加密 | 引入额外组件 Vault | 最高 | 专业密钥管理 | 架构复杂
配置优先级从高到低： 配置优先级（从高到低）
命令行参数 -&gt; –server.port&#x3D;8081 JNDI属性 -&gt; java:comp&#x2F;env 系统属性 -&gt; -Dserver.port&#x3D;8081 环境变量 -&gt; SERVER_PORT&#x3D;8081 外部配置文件 -&gt; config&#x2F;application.yml 内部配置文件 -&gt; classpath:application.yml @PropertySource -&gt; 代码中指定 默认属性 -&gt; SpringApplication.setDefaultProperties
配置文件拆分大型项目配置太多，可以拆分： # application.ymlspring: profiles: include: - datasource - redis - device - alarm# application-datasource.ymlspring: datasource: url: jdbc:mysql://localhost:3306/mine_db username: root password: 123456# application-redis.ymlspring: data: redis: host: localhost port: 6379# application-device.ymlmine: device: gateway-url: tcp://localhost:8888# application-alarm.ymlmine: alarm: sms-enabled: true email-enabled: true dingtalk-webhook: $&#123;DINGTALK_WEBHOOK&#125;
自定义配置校验@Component@ConfigurationProperties(prefix = &quot;mine.alarm&quot;)@Validatedpublic class AlarmProperties &#123; @NotNull(message = &quot;告警通知方式不能为空&quot;) private List&lt;String&gt; channels; @NotBlank(message = &quot;钉钉Webhook不能为空&quot;) private String dingtalkWebhook; @Min(value = 1, message = &quot;重试次数不能小于1&quot;) @Max(value = 5, message = &quot;重试次数不能大于5&quot;) private int retryCount = 3; @NotNull(message = &quot;瓦斯报警阈值不能为空&quot;) private BigDecimal gasAlarmThreshold; @NotNull(message = &quot;瓦斯断电阈值不能为空&quot;) private BigDecimal gasPowerOffThreshold; // getter/setter&#125;
配置动态刷新// 使用Nacos实现配置动态刷新@RefreshScope@Component@ConfigurationProperties(prefix = &quot;mine.device&quot;)public class MineDeviceProperties &#123; // Nacos配置变更后，Bean自动刷新 // 瓦斯报警阈值可以动态调整，无需重启应用&#125;// Nacos配置示例// Data ID: mine-device.properties// Group: DEFAULT_GROUP// mine.device.gas-alarm-threshold=1.0// mine.device.gas-power-off-threshold=1.5
配置动态刷新流程Nacos配置动态刷新流程
运维在Nacos控制台修改配置 Nacos推送配置变更事件 SpringCloud接收到变更事件 销毁@RefreshScope标记的Bean 下次访问时重新创建Bean，读取最新配置 瓦斯报警阈值动态生效，无需重启
总结配置管理是项目工程化的基础。在实际场景中，从”所有配置写一个文件”到”多环境分离+敏感信息加密+配置中心”，核心认知是：配置和代码分离，敏感信息不入库，多环境自动切换——好的配置管理让部署更安全、更简单。矿山安全无小事，一个配置错误可能导致监测系统瘫痪，配置管理必须严谨。

前言 刚写实际项目时，调试全靠System.out.println，上线后println全删了，出了问题两眼一抹黑。有一次井下瓦斯传感器数据异常，因为没有任何日志记录，排查了整整2天才定位到是数据解析层的浮点精度问题。后来学会用日志框架，从log4j到logback，从随意打印到规范记录，日志成了线上排查问题的第一利器。 为什么不用System.out？// System.out的问题System.out.println(&quot;瓦斯浓度: &quot; + concentration);// 1. 无法控制开关 - 生产环境还在打印// 2. 无法分级别 - 不知道是调试信息还是严重错误// 3. 无法输出到文件 - 服务器重启日志就丢了// 4. 无法格式化 - 没有时间、类名、行号// 5. 性能差 - 同步IO，阻塞业务线程// 6. 无法添加上下文信息 - 不知道是哪个矿井、哪个传感器// 日志框架log.info(&quot;瓦斯浓度异常: mineId=&#123;&#125;, sensorId=&#123;&#125;, concentration=&#123;&#125;%, threshold=&#123;&#125;%&quot;, mineId, sensorId, concentration, threshold);// 1. 可通过配置控制开关 - 生产只开INFO// 2. 有级别：debug/info/warn/error// 3. 可输出到文件、远程 - ELK集中收集// 4. 可格式化 - 自动添加时间、类名、traceId// 5. 异步写入，性能好 - 不阻塞瓦斯检测线程// 6. 自动添加上下文 - traceId关联整个请求链路
System.out vs 日志框架对比System.out vs 日志框架 对比
System.out.println +———————————————————-+ | 2022-10-30 10:00:01 瓦斯浓度: 1.2 | | 2022-10-30 10:00:02 通风设备: 运行中 | | 2022-10-30 10:00:03 ERROR: NullPointerException | +———————————————————-+ 问题：不知道哪个类、哪个方法、哪个矿井、哪个传感器 SLF4J + Logback +———————————————————-+ | 2022-10-30 10:00:01.123 [abc123] [mine-schedule-1] | | INFO GasMonitorService - 瓦斯浓度异常: mineId&#x3D;1, | | sensorId&#x3D;GAS-001, concentration&#x3D;1.2%, threshold&#x3D;1.0% | +———————————————————-+ 优势：traceId、线程名、类名、结构化参数
SLF4J + LogbackSpringBoot默认使用SLF4J作为日志门面，Logback作为日志实现。 日志框架体系
应用代码 | v SLF4J（日志门面&#x2F;接口） | +— Logback（SpringBoot默认实现） +— Log4j2 +— JDK Logging 门面模式：代码只依赖SLF4J接口，实现可随时替换 SpringBoot默认：SLF4J + Logback
日志级别日志级别（从低到高）
TRACE &lt; DEBUG &lt; INFO &lt; WARN &lt; ERROR TRACE：最详细的信息，通常只在开发时使用 例：进入方法&#x2F;退出方法、SQL参数绑定 DEBUG：调试信息 例：SQL执行语句、方法参数值、中间变量 INFO：关键流程信息（默认级别，生产环境使用） 例：用户登录、瓦斯报警触发、通风设备控制指令发送 WARN：警告信息，不影响运行但需要关注 例：用户不存在、库存不足、配置项缺失使用默认值 ERROR：错误信息，影响功能但不影响系统运行 例：数据库连接失败、第三方接口超时、文件读取异常
使用@Slf4j@Slf4j@Servicepublic class GasMonitorService &#123; public GasData getById(Long id) &#123; log.trace(&quot;查询瓦斯数据开始: id=&#123;&#125;&quot;, id); GasData data = gasMapper.selectById(id); if (data == null) &#123; log.warn(&quot;瓦斯数据不存在: id=&#123;&#125;&quot;, id); return null; &#125; log.debug(&quot;查询瓦斯数据成功: id=&#123;&#125;, mineId=&#123;&#125;, concentration=&#123;&#125;&quot;, id, data.getMineId(), data.getConcentration()); // 关键业务用INFO if (data.getConcentration().compareTo(THRESHOLD) &gt;= 0) &#123; log.info(&quot;瓦斯浓度超限: mineId=&#123;&#125;, sensorId=&#123;&#125;, concentration=&#123;&#125;%, threshold=&#123;&#125;%&quot;, data.getMineId(), data.getSensorId(), data.getConcentration(), THRESHOLD); &#125; return data; &#125; public void controlVentilation(VentControlDTO dto) &#123; try &#123; log.info(&quot;发送通风控制指令: mineId=&#123;&#125;, command=&#123;&#125;&quot;, dto.getMineId(), dto.getCommand()); ventClient.sendCommand(dto); log.info(&quot;通风控制指令发送成功: mineId=&#123;&#125;&quot;, dto.getMineId()); &#125; catch (BusinessException e) &#123; log.warn(&quot;通风控制业务异常: mineId=&#123;&#125;, msg=&#123;&#125;&quot;, dto.getMineId(), e.getMessage()); throw e; &#125; catch (Exception e) &#123; log.error(&quot;通风控制系统异常: mineId=&#123;&#125;&quot;, dto.getMineId(), e); throw new BusinessException(&quot;通风控制系统异常&quot;); &#125; &#125;&#125;
Logback配置application.yml# 日志配置logging: level: root: info com.mine: debug com.mine.mapper: warn # Mapper层减少日志 file: name: /data/logs/mine-app.log logback: rollingpolicy: max-file-size: 100MB max-history: 30 total-size-cap: 3GB file-name-pattern: /data/logs/mine-app.%d&#123;yyyy-MM-dd&#125;.%i.log
logback-spring.xml（完整配置）&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;configuration&gt; &lt;!-- 日志路径 --&gt; &lt;property name=&quot;LOG_PATH&quot; value=&quot;/data/logs&quot;/&gt; &lt;property name=&quot;APP_NAME&quot; value=&quot;mine-app&quot;/&gt; &lt;!-- 彩色日志依赖的渲染类 --&gt; &lt;conversionRule conversionWord=&quot;clr&quot; converterClass=&quot;org.springframework.boot.logging.logback.ColorConverter&quot;/&gt; &lt;conversionRule conversionWord=&quot;wex&quot; converterClass=&quot;org.springframework.boot.logging.logback.WhitespaceThrowableProxyConverter&quot;/&gt; &lt;conversionRule conversionWord=&quot;wEx&quot; converterClass=&quot;org.springframework.boot.logging.logback.ExtendedWhitespaceThrowableProxyConverter&quot;/&gt; &lt;!-- 控制台输出 --&gt; &lt;appender name=&quot;CONSOLE&quot; class=&quot;ch.qos.logback.core.ConsoleAppender&quot;&gt; &lt;encoder&gt; &lt;pattern&gt;%d&#123;yyyy-MM-dd HH:mm:ss.SSS&#125; [%X&#123;traceId&#125;] [%thread] %-5level %logger&#123;50&#125; - %msg%n&lt;/pattern&gt; &lt;charset&gt;UTF-8&lt;/charset&gt; &lt;/encoder&gt; &lt;/appender&gt; &lt;!-- 全量日志文件 --&gt; &lt;appender name=&quot;FILE&quot; class=&quot;ch.qos.logback.core.rolling.RollingFileAppender&quot;&gt; &lt;file&gt;$&#123;LOG_PATH&#125;/$&#123;APP_NAME&#125;.log&lt;/file&gt; &lt;encoder&gt; &lt;pattern&gt;%d&#123;yyyy-MM-dd HH:mm:ss.SSS&#125; [%X&#123;traceId&#125;] [%thread] %-5level %logger&#123;50&#125; - %msg%n&lt;/pattern&gt; &lt;charset&gt;UTF-8&lt;/charset&gt; &lt;/encoder&gt; &lt;rollingPolicy class=&quot;ch.qos.logback.core.rolling.SizeAndTimeBasedRollingPolicy&quot;&gt; &lt;fileNamePattern&gt;$&#123;LOG_PATH&#125;/$&#123;APP_NAME&#125;.%d&#123;yyyy-MM-dd&#125;.%i.log&lt;/fileNamePattern&gt; &lt;maxFileSize&gt;100MB&lt;/maxFileSize&gt; &lt;maxHistory&gt;30&lt;/maxHistory&gt; &lt;totalSizeCap&gt;3GB&lt;/totalSizeCap&gt; &lt;/rollingPolicy&gt; &lt;/appender&gt; &lt;!-- 错误日志单独文件 --&gt; &lt;appender name=&quot;ERROR_FILE&quot; class=&quot;ch.qos.logback.core.rolling.RollingFileAppender&quot;&gt; &lt;file&gt;$&#123;LOG_PATH&#125;/$&#123;APP_NAME&#125;-error.log&lt;/file&gt; &lt;filter class=&quot;ch.qos.logback.classic.filter.LevelFilter&quot;&gt; &lt;level&gt;ERROR&lt;/level&gt; &lt;onMatch&gt;ACCEPT&lt;/onMatch&gt; &lt;onMismatch&gt;DENY&lt;/onMismatch&gt; &lt;/filter&gt; &lt;encoder&gt; &lt;pattern&gt;%d&#123;yyyy-MM-dd HH:mm:ss.SSS&#125; [%X&#123;traceId&#125;] [%thread] %-5level %logger&#123;50&#125; - %msg%n&lt;/pattern&gt; &lt;/encoder&gt; &lt;rollingPolicy class=&quot;ch.qos.logback.core.rolling.SizeAndTimeBasedRollingPolicy&quot;&gt; &lt;fileNamePattern&gt;$&#123;LOG_PATH&#125;/$&#123;APP_NAME&#125;-error.%d&#123;yyyy-MM-dd&#125;.%i.log&lt;/fileNamePattern&gt; &lt;maxFileSize&gt;50MB&lt;/maxFileSize&gt; &lt;maxHistory&gt;90&lt;/maxHistory&gt; &lt;/rollingPolicy&gt; &lt;/appender&gt; &lt;!-- 瓦斯报警日志单独文件（安全审计） --&gt; &lt;appender name=&quot;GAS_ALARM_FILE&quot; class=&quot;ch.qos.logback.core.rolling.RollingFileAppender&quot;&gt; &lt;file&gt;$&#123;LOG_PATH&#125;/$&#123;APP_NAME&#125;-gas-alarm.log&lt;/file&gt; &lt;filter class=&quot;ch.qos.logback.classic.filter.LevelFilter&quot;&gt; &lt;level&gt;INFO&lt;/level&gt; &lt;onMatch&gt;NEUTRAL&lt;/onMatch&gt; &lt;onMismatch&gt;DENY&lt;/onMismatch&gt; &lt;/filter&gt; &lt;encoder&gt; &lt;pattern&gt;%d&#123;yyyy-MM-dd HH:mm:ss.SSS&#125; [%X&#123;traceId&#125;] %msg%n&lt;/pattern&gt; &lt;/encoder&gt; &lt;rollingPolicy class=&quot;ch.qos.logback.core.rolling.SizeAndTimeBasedRollingPolicy&quot;&gt; &lt;fileNamePattern&gt;$&#123;LOG_PATH&#125;/$&#123;APP_NAME&#125;-gas-alarm.%d&#123;yyyy-MM-dd&#125;.%i.log&lt;/fileNamePattern&gt; &lt;maxFileSize&gt;200MB&lt;/maxFileSize&gt; &lt;maxHistory&gt;365&lt;/maxHistory&gt; &lt;/rollingPolicy&gt; &lt;/appender&gt; &lt;!-- 开发环境 --&gt; &lt;springProfile name=&quot;dev&quot;&gt; &lt;root level=&quot;info&quot;&gt; &lt;appender-ref ref=&quot;CONSOLE&quot;/&gt; &lt;/root&gt; &lt;logger name=&quot;com.mine&quot; level=&quot;debug&quot;/&gt; &lt;/springProfile&gt; &lt;!-- 测试环境 --&gt; &lt;springProfile name=&quot;test&quot;&gt; &lt;root level=&quot;info&quot;&gt; &lt;appender-ref ref=&quot;CONSOLE&quot;/&gt; &lt;appender-ref ref=&quot;FILE&quot;/&gt; &lt;/root&gt; &lt;logger name=&quot;com.mine&quot; level=&quot;debug&quot;/&gt; &lt;/springProfile&gt; &lt;!-- 生产环境 --&gt; &lt;springProfile name=&quot;prod&quot;&gt; &lt;root level=&quot;info&quot;&gt; &lt;appender-ref ref=&quot;FILE&quot;/&gt; &lt;appender-ref ref=&quot;ERROR_FILE&quot;/&gt; &lt;/root&gt; &lt;logger name=&quot;com.mine&quot; level=&quot;info&quot;/&gt; &lt;!-- 瓦斯报警日志单独输出 --&gt; &lt;logger name=&quot;com.mine.service.GasMonitorService&quot; level=&quot;info&quot; additivity=&quot;true&quot;&gt; &lt;appender-ref ref=&quot;GAS_ALARM_FILE&quot;/&gt; &lt;/logger&gt; &lt;/springProfile&gt;&lt;/configuration&gt;
日志文件规划日志文件规划
&#x2F;data&#x2F;logs&#x2F; mine-app.log # 全量日志（保留30天） mine-app-error.log # 错误日志（保留90天） mine-app-gas-alarm.log # 瓦斯报警日志（保留365天） mine-app.2022-10-30.0.log # 滚动归档 mine-app.2022-10-30.1.log # 滚动归档 滚动策略：
按天+大小滚动：单文件超过100MB就切分
- 全量日志保留30天 - 错误日志保留90天
安全审计日志保留365天（法规要求）
日志规范1. 使用占位符// 字符串拼接 - 即使日志级别不够也会拼接log.info(&quot;查询瓦斯数据: &quot; + mineId + &quot;, &quot; + sensorId);// 占位符 - 日志级别不够时不拼接，性能更好log.info(&quot;查询瓦斯数据: mineId=&#123;&#125;, sensorId=&#123;&#125;&quot;, mineId, sensorId);
2. 级别使用规范// TRACE：非常详细的调试信息log.trace(&quot;进入方法: params=&#123;&#125;&quot;, params);// DEBUG：调试信息log.debug(&quot;SQL执行: sql=&#123;&#125;, params=&#123;&#125;&quot;, sql, params);// INFO：关键业务流程（矿山安全核心操作）log.info(&quot;用户登录: userId=&#123;&#125;, ip=&#123;&#125;&quot;, userId, ip);log.info(&quot;瓦斯报警触发: mineId=&#123;&#125;, sensorId=&#123;&#125;, concentration=&#123;&#125;%&quot;, mineId, sensorId, concentration);log.info(&quot;通风控制指令发送: mineId=&#123;&#125;, command=&#123;&#125;&quot;, mineId, command);log.info(&quot;紧急断电执行: mineId=&#123;&#125;, operatorId=&#123;&#125;&quot;, mineId, operatorId);// WARN：业务异常、可恢复的问题log.warn(&quot;用户不存在: userId=&#123;&#125;&quot;, userId);log.warn(&quot;瓦斯传感器数据延迟: sensorId=&#123;&#125;, delay=&#123;&#125;ms&quot;, sensorId, delay);log.warn(&quot;通风设备响应超时: deviceId=&#123;&#125;, timeout=&#123;&#125;ms&quot;, deviceId, timeout);// ERROR：系统异常、需要关注的问题log.error(&quot;数据库连接失败: url=&#123;&#125;&quot;, url, e);log.error(&quot;瓦斯检测设备通信异常: deviceId=&#123;&#125;&quot;, deviceId, e);log.error(&quot;紧急断电指令发送失败: mineId=&#123;&#125;&quot;, mineId, e);
3. 日志内容规范// 无意义日志log.info(&quot;开始处理&quot;);log.info(&quot;处理完成&quot;);log.info(&quot;数据: &quot; + data);// 有意义的日志log.info(&quot;开始处理瓦斯报警: alarmId=&#123;&#125;, mineId=&#123;&#125;&quot;, alarmId, mineId);log.info(&quot;瓦斯报警处理完成: alarmId=&#123;&#125;, cost=&#123;&#125;ms, result=&#123;&#125;&quot;, alarmId, cost, result);log.info(&quot;查询结果: mineId=&#123;&#125;, sensorId=&#123;&#125;, concentration=&#123;&#125;%&quot;, mineId, sensorId, concentration);
4. 异常日志// 只打印消息，丢失堆栈 - 排查困难log.error(&quot;系统异常: &quot; + e.getMessage());// 异常信息重复 - e.getMessage()和e会重复log.error(&quot;系统异常: &quot; + e.getMessage(), e);// 正确：消息+异常对象log.error(&quot;瓦斯检测系统异常: mineId=&#123;&#125;, sensorId=&#123;&#125;&quot;, mineId, sensorId, e);// 业务异常用warnlog.warn(&quot;业务异常: msg=&#123;&#125;&quot;, e.getMessage());
5. 敏感信息脱敏// 打印敏感信息 - 严重安全风险log.info(&quot;矿工登录: phone=&#123;&#125;, idCard=&#123;&#125;, password=&#123;&#125;&quot;, phone, idCard, password);// 脱敏处理log.info(&quot;矿工登录: phone=&#123;&#125;, idCard=&#123;&#125;&quot;, maskPhone(phone), maskIdCard(idCard));private String maskPhone(String phone) &#123; if (phone == null || phone.length() &lt; 7) return &quot;***&quot;; return phone.substring(0, 3) + &quot;****&quot; + phone.substring(7);&#125;private String maskIdCard(String idCard) &#123; if (idCard == null || idCard.length() &lt; 8) return &quot;***&quot;; return idCard.substring(0, 4) + &quot;**********&quot; + idCard.substring(idCard.length() - 4);&#125;
MDC追踪添加请求ID到MDC@Componentpublic class TraceInterceptor implements HandlerInterceptor &#123; @Override public boolean preHandle(HttpServletRequest request, ...) &#123; // 从请求头获取或生成traceId String traceId = request.getHeader(&quot;X-Trace-Id&quot;); if (StringUtils.isBlank(traceId)) &#123; traceId = UUID.randomUUID().toString().replace(&quot;-&quot;, &quot;&quot;); &#125; MDC.put(&quot;traceId&quot;, traceId); // 矿山项目额外记录矿井ID String mineId = request.getHeader(&quot;X-Mine-Id&quot;); if (StringUtils.isNotBlank(mineId)) &#123; MDC.put(&quot;mineId&quot;, mineId); &#125; return true; &#125; @Override public void afterCompletion(...) &#123; MDC.clear(); &#125;&#125;
日志输出效果2022-10-30 10:00:00.123 [a1b2c3d4] [http-nio-8080-exec-1] INFO GasMonitorService - 瓦斯浓度超限: mineId=1, sensorId=GAS-001, concentration=1.2%2022-10-30 10:00:00.456 [a1b2c3d4] [http-nio-8080-exec-1] INFO AlarmService - 发送瓦斯报警: mineId=1, level=WARN2022-10-30 10:00:00.789 [e5f6g7h8] [http-nio-8080-exec-2] INFO VentService - 通风设备控制: mineId=2, command=SPEED_UP# [a1b2c3d4] 是traceId，可以关联同一个请求的所有日志# 通过 grep &quot;a1b2c3d4&quot; app.log 快速找到完整请求链路
微服务间traceId传递// RestTemplate拦截器传递traceId@Componentpublic class TraceRestTemplateInterceptor implements ClientHttpRequestInterceptor &#123; @Override public ClientHttpResponse intercept(HttpRequest request, byte[] body, ClientHttpRequestExecution execution) throws IOException &#123; String traceId = MDC.get(&quot;traceId&quot;); if (StringUtils.isNotBlank(traceId)) &#123; request.getHeaders().set(&quot;X-Trace-Id&quot;, traceId); &#125; return execution.execute(request, body); &#125;&#125;// Feign拦截器传递traceId@Componentpublic class TraceFeignInterceptor implements RequestInterceptor &#123; @Override public void apply(RequestTemplate template) &#123; String traceId = MDC.get(&quot;traceId&quot;); if (StringUtils.isNotBlank(traceId)) &#123; template.header(&quot;X-Trace-Id&quot;, traceId); &#125; &#125;&#125;
日志排查技巧常用命令# 实时查看日志tail -f /data/logs/mine-app.log# 过滤关键词tail -f mine-app.log | grep &quot;ERROR&quot;tail -f mine-app.log | grep &quot;瓦斯报警&quot;# 过滤多个关键词tail -f mine-app.log | grep -E &quot;ERROR|WARN&quot;# 按traceId查找完整链路grep &quot;a1b2c3d4&quot; mine-app.log# 查看特定时间段sed -n &#x27;/2022-10-30 10:00/,/2022-10-30 11:00/p&#x27; mine-app.log# 统计ERROR数量grep -c &quot;ERROR&quot; mine-app.log# 查看最近的异常grep &quot;ERROR&quot; mine-app.log | tail -20# 统计各矿井报警次数grep &quot;瓦斯报警触发&quot; mine-app.log | grep -oP &#x27;mineId=\d+&#x27; | sort | uniq -c | sort -rn
ELK日志平台ELK日志架构
应用服务器 日志平台 +——————+ +——————+ | mine-app.log | | Kibana | | | | | (可视化查询) | | v | | ^ | | Filebeat | –&gt; | Elasticsearch | | (日志采集) | | (存储+搜索) | +——————+ | ^ | | Logstash | | (日志处理) | +——————+ Kibana查询示例：
level:ERROR AND mineId:1
traceId:a1b2c3d4
message:瓦斯报警 AND @timestamp:[now-1h TO now]
异步日志&lt;!-- 异步Appender - 不阻塞业务线程 --&gt;&lt;appender name=&quot;ASYNC_FILE&quot; class=&quot;ch.qos.logback.classic.AsyncAppender&quot;&gt; &lt;!-- 队列容量 --&gt; &lt;queueSize&gt;512&lt;/queueSize&gt; &lt;!-- 队列满时丢弃TRACE/DEBUG --&gt; &lt;discardingThreshold&gt;0&lt;/discardingThreshold&gt; &lt;!-- 不丢弃WARN/ERROR --&gt; &lt;neverBlock&gt;false&lt;/neverBlock&gt; &lt;appender-ref ref=&quot;FILE&quot;/&gt;&lt;/appender&gt;
// 异步日志配置参数选择// queueSize: 512（默认256，高并发可调大）// discardingThreshold: 0（0表示不丢弃任何级别）// 设为20表示当队列剩余容量&lt;20时丢弃TRACE/DEBUG/INFO// neverBlock: false（队列满时阻塞而非丢弃）// 瓦斯报警场景不能丢日志，设false// 生产环境推荐配置&lt;queueSize&gt;1024&lt;/queueSize&gt;&lt;discardingThreshold&gt;0&lt;/discardingThreshold&gt;&lt;neverBlock&gt;false&lt;/neverBlock&gt;
日志与报警联动@Component@Slf4jpublic class LogAlarmAppender extends AppenderBase&lt;ILoggingEvent&gt; &#123; @Autowired private AlarmService alarmService; private static final Set&lt;String&gt; ALARM_KEYWORDS = Set.of( &quot;紧急断电&quot;, &quot;瓦斯超限&quot;, &quot;设备离线&quot;, &quot;数据库连接失败&quot; ); @Override protected void append(ILoggingEvent event) &#123; if (event.getLevel() != Level.ERROR) &#123; return; &#125; String message = event.getFormattedMessage(); for (String keyword : ALARM_KEYWORDS) &#123; if (message.contains(keyword)) &#123; alarmService.sendCriticalAlarm(&quot;日志告警: &quot; + message); break; &#125; &#125; &#125;&#125;
总结日志是线上排查问题的第一利器。在实际场景中，从”System.out.println”到”规范日志体系”，核心认知是：好的日志不是越多越好，而是关键信息不遗漏、敏感信息要脱敏、异常信息有堆栈——INFO记录流程、WARN记录业务异常、ERROR记录系统异常，加上MDC traceId追踪和ELK集中管理，这三条规则覆盖了90%的日志场景。矿山安全场景下，日志不仅是排查工具，更是合规审计的法定要求。

前言
在实际场景中，最初提交代码最怕被review，觉得别人挑毛病是针对自己。后来心态转变，发现代码审查是提升代码质量最快的方式——别人的视角能看到自己看不到的问题。
代码审查的价值1. 发现bug：作者容易忽略自己的错误2. 知识共享：团队成员互相学习3. 统一规范：保证代码风格一致4. 质量保障：不让低质量代码进入主分支5. 传承经验：新人从review中学习最佳实践

审查清单安全性□ SQL是否使用#&#123;&#125;而非$&#123;&#125;□ 参数是否校验□ 敏感信息是否脱敏□ 权限是否校验□ 是否有SQL注入风险□ 密码是否加密存储

性能□ 循环中是否有数据库查询（N+1问题）□ 大数据量是否分批处理□ 是否有慢SQL风险□ 是否有不必要的对象创建□ 缓存使用是否合理

异常处理□ 异常是否被吞掉□ 日志是否带上下文□ 全局异常处理是否覆盖□ 业务异常和系统异常是否区分

设计□ 分层是否清晰（Controller不写业务逻辑）□ DTO/VO是否正确使用□ 方法职责是否单一□ 是否有过度设计

常见Review问题1. 命名问题// ❌ 缩写、无意义List&lt;User&gt; list1 = new ArrayList&lt;&gt;();String str = &quot;&quot;;int flag = 0;// ✅ 见名知意List&lt;User&gt; activeUsers = new ArrayList&lt;&gt;();String userName = &quot;&quot;;int retryCount = 0;

2. 魔法值// ❌ 魔法值if (user.getStatus() == 1) &#123; &#125;// ✅ 使用枚举或常量if (user.getStatus() == UserStatus.ENABLED) &#123; &#125;

3. 重复代码// ❌ 重复的校验逻辑public void addOrder(OrderDTO dto) &#123;    if (dto.getUserId() == null) throw new BusinessException(&quot;用户ID不能为空&quot;);    if (dto.getProductId() == null) throw new BusinessException(&quot;商品ID不能为空&quot;);&#125;public void updateOrder(OrderDTO dto) &#123;    if (dto.getUserId() == null) throw new BusinessException(&quot;用户ID不能为空&quot;);    if (dto.getProductId() == null) throw new BusinessException(&quot;商品ID不能为空&quot;);&#125;// ✅ 使用@Valid注解校验public void addOrder(@RequestBody @Valid OrderDTO dto) &#123;&#125;

4. N+1查询// ❌ 循环中查数据库for (Order order : orders) &#123;    User user = userService.getById(order.getUserId());    order.setUserName(user.getName());&#125;// ✅ 批量查询Set&lt;Long&gt; userIds = orders.stream().map(Order::getUserId).collect(Collectors.toSet());Map&lt;Long, User&gt; userMap = userService.listByIds(userIds).stream()    .collect(Collectors.toMap(User::getId, Function.identity()));orders.forEach(o -&gt; o.setUserName(userMap.get(o.getUserId()).getName()));

5. 事务问题// ❌ 事务中包含远程调用@Transactionalpublic void createOrder(OrderDTO dto) &#123;    orderMapper.insert(order);    paymentService.pay(dto);  // 远程调用，可能超时    emailService.send(dto);   // 远程调用，可能超时&#125;// ✅ 事务中只做数据库操作@Transactionalpublic void createOrder(OrderDTO dto) &#123;    orderMapper.insert(order);    accountMapper.deductBalance(dto);&#125;

6. 空指针风险// ❌ 链式调用不判空String city = user.getAddress().getCity();// ✅ 安全调用String city = Optional.ofNullable(user)    .map(User::getAddress)    .map(Address::getCity)    .orElse(&quot;未知&quot;);

Review流程提交者1. 自我review：提交前先检查一遍2. 写清楚MR描述：改了什么、为什么改3. 小粒度提交：一个功能一个MR4. 响应review意见：及时修改或解释

审查者1. 先看设计思路，再看代码细节2. 指出问题并给出建议3. 区分&quot;必须改&quot;和&quot;建议改&quot;4. 尊重作者，语气友好

Review意见模板🔴 必须修改（阻塞合并）- [严重] 这里存在SQL注入风险，必须用#&#123;&#125;🟡 建议修改（不阻塞合并）- [建议] 这个方法名不够清晰，建议改为getUserById🟢 讨论项- [讨论] 这里用Redis缓存是否合适？🔵 肯定- [赞] 这个异常处理写得很规范

总结
代码审查是团队协作的核心环节。从”怕被review”到”主动review”核心认知是：代码审查不是挑毛病，而是互相学习*好的审查文化让团队代码质量整体提升，也让每个人成长更快。

前言
在实际场景中，最初写代码只求功能跑通，后来回头看自己的代码，简直不忍直视。学会重构技巧后，代码越改越清晰，维护成本越来越低。重构不是推倒重来，而是小步改进。
重构原则1. 小步重构：每次只改一处，改完跑测试2. 先测试后重构：确保重构不改变行为3. 持续重构：不要等代码烂了再重构4. 重构与功能开发分离：不要混在一起

常见重构手法1. 提取方法// ❌ 长方法public void processOrder(OrderDTO dto) &#123;    // 校验参数    if (dto.getUserId() == null) throw new BusinessException(&quot;用户ID不能为空&quot;);    if (dto.getProductId() == null) throw new BusinessException(&quot;商品ID不能为空&quot;);    if (dto.getQuantity() &lt;= 0) throw new BusinessException(&quot;数量必须大于0&quot;);    // 查询用户    User user = userMapper.selectById(dto.getUserId());    if (user == null) throw new BusinessException(&quot;用户不存在&quot;);    // 查询商品    Product product = productMapper.selectById(dto.getProductId());    if (product == null) throw new BusinessException(&quot;商品不存在&quot;);    // 计算金额    BigDecimal amount = product.getPrice().multiply(BigDecimal.valueOf(dto.getQuantity()));    if (user.getLevel() == VIP) &#123;        amount = amount.multiply(new BigDecimal(&quot;0.9&quot;));    &#125;    // 创建订单    Order order = new Order();    order.setUserId(user.getId());    order.setProductId(product.getId());    order.setQuantity(dto.getQuantity());    order.setAmount(amount);    orderMapper.insert(order);&#125;// ✅ 提取方法public void processOrder(OrderDTO dto) &#123;    validateOrder(dto);    User user = getUser(dto.getUserId());    Product product = getProduct(dto.getProductId());    BigDecimal amount = calculateAmount(user, product, dto.getQuantity());    createOrder(user, product, dto.getQuantity(), amount);&#125;

2. 以查询替代临时变量// ❌ 临时变量double basePrice = order.getQuantity() * order.getItemPrice();if (basePrice &gt; 1000) &#123;    return basePrice * 0.95;&#125;return basePrice;// ✅ 提取方法if (getBasePrice(order) &gt; 1000) &#123;    return getBasePrice(order) * 0.95;&#125;return getBasePrice(order);private double getBasePrice(Order order) &#123;    return order.getQuantity() * order.getItemPrice();&#125;

3. 以策略替代条件逻辑// ❌ if-elsepublic BigDecimal calculateDiscount(User user, BigDecimal amount) &#123;    if (user.getLevel() == VIP) &#123;        return amount.multiply(new BigDecimal(&quot;0.8&quot;));    &#125; else if (user.getLevel() == SVIP) &#123;        return amount.multiply(new BigDecimal(&quot;0.7&quot;));    &#125; else &#123;        return amount;    &#125;&#125;// ✅ 策略模式@Component(&quot;VIP&quot;)public class VipDiscount implements DiscountStrategy &#123;    public BigDecimal calculate(BigDecimal amount) &#123;        return amount.multiply(new BigDecimal(&quot;0.8&quot;));    &#125;&#125;@Component(&quot;SVIP&quot;)public class SvipDiscount implements DiscountStrategy &#123;    public BigDecimal calculate(BigDecimal amount) &#123;        return amount.multiply(new BigDecimal(&quot;0.7&quot;));    &#125;&#125;@Servicepublic class DiscountService &#123;    @Autowired    private Map&lt;String, DiscountStrategy&gt; strategyMap;    public BigDecimal calculateDiscount(User user, BigDecimal amount) &#123;        DiscountStrategy strategy = strategyMap.get(user.getLevel().name());        return strategy != null strategy.calculate(amount) : amount;    &#125;&#125;

4. 以Map替代长if-else// ❌ 长if-elsepublic String getStatusDesc(int status) &#123;    if (status == 0) return &quot;待支付&quot;;    if (status == 1) return &quot;已支付&quot;;    if (status == 2) return &quot;已发货&quot;;    if (status == 3) return &quot;已完成&quot;;    if (status == 4) return &quot;已取消&quot;;    return &quot;未知&quot;;&#125;// ✅ 枚举@Getter@AllArgsConstructorpublic enum OrderStatus &#123;    PENDING(0, &quot;待支付&quot;),    PAID(1, &quot;已支付&quot;),    SHIPPED(2, &quot;已发货&quot;),    COMPLETED(3, &quot;已完成&quot;),    CANCELLED(4, &quot;已取消&quot;);    private final int code;    private final String desc;&#125;

5. 封装集合// ❌ 直接暴露集合public class Order &#123;    public List&lt;Item&gt; items;&#125;// ✅ 封装集合操作public class Order &#123;    private List&lt;Item&gt; items = new ArrayList&lt;&gt;();    public void addItem(Item item) &#123;        items.add(item);        recalculateAmount();    &#125;    public void removeItem(Item item) &#123;        items.remove(item);        recalculateAmount();    &#125;    public List&lt;Item&gt; getItems() &#123;        return Collections.unmodifiableList(items);    &#125;&#125;

6. 以异常替代错误码// ❌ 错误码public int createUser(UserDTO dto) &#123;    if (dto.getName() == null) return -1;    if (userMapper.selectByName(dto.getName()) != null) return -2;    userMapper.insert(user);    return 0;&#125;// ✅ 异常public void createUser(UserDTO dto) &#123;    if (dto.getName() == null) &#123;        throw new BusinessException(&quot;用户名不能为空&quot;);    &#125;    if (userMapper.selectByName(dto.getName()) != null) &#123;        throw new BusinessException(&quot;用户名已存在&quot;);    &#125;    userMapper.insert(user);&#125;

代码坏味道识别1. 方法过长（&gt;30行）→ 提取方法2. 参数过多（&gt;3个）→ 封装对象3. 重复代码 → 提取公共方法4. if-else过多 → 策略模式/枚举5. 魔法值 → 常量/枚举6. 注释过多 → 代码自解释7. 类职责过多 → 拆分类8. 集合裸露 → 封装集合操作

重构节奏1. 发现坏味道2. 写测试保障3. 小步重构4. 跑测试验证5. 提交代码

总结
重构是提升代码质量的日常实践。从”写完就不管”到”持续小步重构”核心认知是：重构不是推倒重来，而是小步改进*提取方法、消灭if-else、用枚举替代魔法值——这三个手法覆盖了80%的重构场景。

前言 在实际场景中，多态是面向对象中最难理解、也是最有价值的一个特性。刚学的时候觉得概念很虚，直到在项目中用策略模式替换了一堆 if-else，才真正体会到多态的威力。 什么是多态？多态的字面意思是”多种形态”。在Java中，多态是指父类引用指向子类对象，调用同一个方法，表现出不同的行为* Animal animal = new Dog();animal.speak(); // 输出：汪汪汪animal = new Cat();animal.speak(); // 输出：喵喵喵
同一个 animal.speak() 调用，因为实际对象不同，产生了不同的行为——这就是多态。 多态的三个前提条件 有继承关系（或实现关系） 有方法重写 父类引用指向子类对象
多态在项目中的实际应用1. 支付场景——策略模式public interface PayStrategy &#123; PayResult pay(PayOrder order);&#125;public class AliPayStrategy implements PayStrategy &#123; @Override public PayResult pay(PayOrder order) &#123; // 支付宝支付逻辑 &#125;&#125;public class WeChatPayStrategy implements PayStrategy &#123; @Override public PayResult pay(PayOrder order) &#123; // 微信支付逻辑 &#125;&#125;
调用方不需要关心具体支付方式： public class PayService &#123; private Map&lt;String, PayStrategy&gt; strategyMap; public PayResult pay(String payType, PayOrder order) &#123; PayStrategy strategy = strategyMap.get(payType); if (strategy == null) &#123; throw new IllegalArgumentException(&quot;不支持的支付方式&quot;); &#125; return strategy.pay(order); &#125;&#125;
2. 统一日志处理public interface LogHandler &#123; void handle(LogMessage message);&#125;public class FileLogHandler implements LogHandler &#123; ... &#125;public class DbLogHandler implements LogHandler &#123; ... &#125;public class EsLogHandler implements LogHandler &#123; ... &#125;
3. 消息通知public interface NotificationService &#123; void send(NotificationMessage message);&#125;public class SmsNotification implements NotificationService &#123; ... &#125;public class EmailNotification implements NotificationService &#123; ... &#125;public class WeChatNotification implements NotificationService &#123; ... &#125;
多态的本质：动态绑定多态的底层机制是动态绑定（也叫运行时多态）：
编译时：看引用类型（父类），只能调用父类中定义的方法 运行时：看实际对象类型（子类），执行子类重写后的方法
Animal animal = new Dog();// 编译时：animal 是 Animal 类型，只能调用 Animal 中定义的方法// 运行时：实际对象是 Dog，调用的是 Dog 重写后的方法
多态的陷阱1. 无法调用子类特有方法Animal animal = new Dog();// animal.bark(); // 编译错误！Animal 中没有 bark 方法// 需要向下转型if (animal instanceof Dog) &#123; Dog dog = (Dog) animal; dog.bark();&#125;
2. 属性不存在多态class Parent &#123; String name = &quot;parent&quot;;&#125;class Child extends Parent &#123; String name = &quot;child&quot;;&#125;Parent obj = new Child();System.out.println(obj.name); // 输出：parent（属性看编译类型）
3. 静态方法不存在多态class Parent &#123; static void hello() &#123; System.out.println(&quot;parent&quot;); &#125;&#125;class Child extends Parent &#123; static void hello() &#123; System.out.println(&quot;child&quot;); &#125;&#125;Parent obj = new Child();obj.hello(); // 输出：parent（静态方法看编译类型）
向上转型与向下转型
类型 说明 安全性
向上转型 子类引用赋给父类变量 安全（自动）
向下转型 父类引用赋给子类变量 不安全（需 instanceof 检查）
// 向上转型（自动）Animal animal = new Dog();// 向下转型（需检查）if (animal instanceof Dog) &#123; Dog dog = (Dog) animal;&#125;
总结 多态的核心价值是解耦——调用方不需要知道具体的实现类，只需要面向接口编程。这在策略模式、工厂模式、模板方法模式中都有广泛应用。理解从”概念模糊”到”实际落地”最大的收获就是：凡是看到一堆 if-else 分支做类型判断的，就该想想能不能用多态重构*

前言 刚写接口的时候，异常处理就是在每个 Controller 方法里 try-catch，代码又丑又重复。在实际场景中，更糟糕的事情发生了——瓦斯报警接口忘了 try-catch，直接把 500 错误和完整堆栈信息返回给了矿端前端，堆栈里还包含了数据库连接信息，这可是严重的安全隐患。直到学会全局异常处理，才真正统一了错误返回格式。 本文将从实际项目的真实场景出发，系统讲解全局异常处理的设计、实现和最佳实践。 没有全局异常处理的痛点// 实际项目 - 没有全局异常处理的Controller@RestController@RequestMapping(&quot;/gas-alarm&quot;)public class GasAlarmController &#123; @GetMapping(&quot;/&#123;id&#125;&quot;) public Result&lt;GasAlarmVO&gt; getById(@PathVariable Long id) &#123; try &#123; GasAlarmVO vo = gasAlarmService.getById(id); return Result.success(vo); &#125; catch (BusinessException e) &#123; return Result.fail(e.getCode(), e.getMessage()); &#125; catch (Exception e) &#123; log.error(&quot;查询瓦斯报警失败&quot;, e); return Result.fail(&quot;系统繁忙&quot;); &#125; &#125; @PostMapping(&quot;/report&quot;) public Result&lt;Void&gt; reportAlarm(@RequestBody GasAlarmDTO dto) &#123; try &#123; gasAlarmService.reportAlarm(dto); return Result.success(); &#125; catch (BusinessException e) &#123; return Result.fail(e.getCode(), e.getMessage()); &#125; catch (Exception e) &#123; log.error(&quot;上报瓦斯报警失败&quot;, e); return Result.fail(&quot;系统繁忙&quot;); &#125; &#125; // 每个方法都重复try-catch...几十个接口 = 几百行重复代码&#125;
痛点分析没有全局异常处理的痛点
代码重复 容易遗漏 格式不统一 日志不统一
没有全局异常处理的真实事故实际项目 - 瓦斯报警接口泄露堆栈信息
矿端前端收到的响应： HTTP 500 Internal Server Error { “timestamp”: “2022-04-19T14:30:00.123+00:00”, “status”: 500, “error”: “Internal Server Error”, “trace”: “java.lang.NullPointerException at com.mine.service.GasAlarmServiceImpl.reportAlarm(47) at com.mine.controller.GasAlarmController.reportAlarm(32) at sun.reflect.NativeMethodAccessorImpl.invoke0(-1) … at com.mysql.cj.jdbc.ClientPreparedStatement.execute(1255) at com.zaxxer.hikari.HikariPreparedStatement.execute(..) …”, “message”: “Cannot invoke String.isEmpty() because param is null”, “path”: “&#x2F;api&#x2F;gas-alarm&#x2F;report” } 泄露了：
包名和类名（com.mine.service.xxx）
数据库驱动（com.mysql.cj.jdbc）
连接池类型（HikariCP）
代码行号
@RestControllerAdviceSpring 提供的全局异常处理机制： @RestControllerAdvice@Slf4jpublic class GlobalExceptionHandler &#123; // 处理业务异常 @ExceptionHandler(BusinessException.class) public Result&lt;?&gt; handleBusiness(BusinessException e) &#123; log.warn(&quot;业务异常: &#123;&#125;&quot;, e.getMessage()); return Result.fail(e.getCode(), e.getMessage()); &#125; // 处理参数校验异常 @ExceptionHandler(MethodArgumentNotValidException.class) public Result&lt;?&gt; handleValidation(MethodArgumentNotValidException e) &#123; String msg = e.getBindingResult().getFieldErrors().stream() .map(fe -&gt; fe.getField() + &quot;: &quot; + fe.getDefaultMessage()) .collect(Collectors.joining(&quot;; &quot;)); log.warn(&quot;参数校验失败: &#123;&#125;&quot;, msg); return Result.fail(400, msg); &#125; // 处理其他异常 @ExceptionHandler(Exception.class) public Result&lt;?&gt; handleException(Exception e) &#123; log.error(&quot;系统异常&quot;, e); return Result.fail(500, &quot;系统繁忙，请稍后重试&quot;); &#125;&#125;
Controller 瞬间变得清爽： @RestController@RequestMapping(&quot;/gas-alarm&quot;)public class GasAlarmController &#123; @GetMapping(&quot;/&#123;id&#125;&quot;) public Result&lt;GasAlarmVO&gt; getById(@PathVariable Long id) &#123; return Result.success(gasAlarmService.getById(id)); &#125; @PostMapping(&quot;/report&quot;) public Result&lt;Void&gt; reportAlarm(@RequestBody @Valid GasAlarmDTO dto) &#123; gasAlarmService.reportAlarm(dto); return Result.success(); &#125; @PutMapping(&quot;/handle/&#123;id&#125;&quot;) public Result&lt;Void&gt; handleAlarm(@PathVariable Long id, @RequestBody GasAlarmHandleDTO dto) &#123; gasAlarmService.handleAlarm(id, dto); return Result.success(); &#125; @DeleteMapping(&quot;/&#123;id&#125;&quot;) public Result&lt;Void&gt; delete(@PathVariable Long id) &#123; gasAlarmService.deleteAlarm(id); return Result.success(); &#125;&#125;
@RestControllerAdvice 工作原理@RestControllerAdvice 工作原理
@RestControllerAdvice 是 @ControllerAdvice + @ResponseBody @ExceptionHandler 标记异常处理方法 工作流程
异常分类体系异常层次结构实际项目异常分类体系
RuntimeException BusinessException （业务异常基类） UserNotFoundException （用户不存在） GasAlarmNotFoundException （报警不存在） AlarmStatusException （状态不允许变更） GasConcentrationException （浓度超标） DuplicateSubmitException （重复提交） RateLimitException （限流） UnauthorizedException （未认证 401） ForbiddenException （无权限 403） SystemException （系统异常 500） DatabaseException （数据库异常） ThirdPartyException （第三方调用异常）
业务异常基类/** * 业务异常基类 * 所有业务异常都应继承此类 */@Getterpublic class BusinessException extends RuntimeException &#123; private final int code; public BusinessException(String message) &#123; super(message); this.code = 500; &#125; public BusinessException(int code, String message) &#123; super(message); this.code = code; &#125; public BusinessException(int code, String message, Throwable cause) &#123; super(message, cause); this.code = code; &#125;&#125;
特定业务异常/** * 瓦斯报警不存在 */public class GasAlarmNotFoundException extends BusinessException &#123; public GasAlarmNotFoundException(Long id) &#123; super(404, &quot;瓦斯报警不存在: &quot; + id); &#125;&#125;/** * 报警状态不允许变更 */public class AlarmStatusException extends BusinessException &#123; public AlarmStatusException(String current, String target) &#123; super(400, &quot;报警状态不允许从&quot; + current + &quot;变更为&quot; + target); &#125;&#125;/** * 瓦斯浓度超标异常（特殊业务异常，需要紧急通知） */public class GasConcentrationException extends BusinessException &#123; private final String mineCode; private final BigDecimal concentration; public GasConcentrationException(String mineCode, BigDecimal concentration) &#123; super(4001, &quot;瓦斯浓度超标: 矿井=&quot; + mineCode + &quot;, 浓度=&quot; + concentration + &quot;%&quot;); this.mineCode = mineCode; this.concentration = concentration; &#125; public String getMineCode() &#123; return mineCode; &#125; public BigDecimal getConcentration() &#123; return concentration; &#125;&#125;/** * 重复提交异常 */public class DuplicateSubmitException extends BusinessException &#123; public DuplicateSubmitException() &#123; super(429, &quot;请勿重复提交&quot;); &#125;&#125;/** * 限流异常 */public class RateLimitException extends BusinessException &#123; public RateLimitException(String message) &#123; super(429, message); &#125;&#125;
使用示例@Service@Slf4jpublic class GasAlarmServiceImpl implements GasAlarmService &#123; @Override public GasAlarm getById(Long id) &#123; GasAlarm alarm = gasAlarmMapper.selectById(id); if (alarm == null) &#123; throw new GasAlarmNotFoundException(id); // 抛出特定业务异常 &#125; return alarm; &#125; @Override public void handleAlarm(Long id, GasAlarmHandleDTO dto) &#123; GasAlarm alarm = getById(id); // 状态校验 if (alarm.getStatus() == AlarmStatus.HANDLED) &#123; throw new AlarmStatusException(&quot;已处理&quot;, &quot;处理中&quot;); &#125; alarm.setStatus(AlarmStatus.HANDLED); alarm.setHandlerId(dto.getHandlerId()); alarm.setHandleTime(LocalDateTime.now()); alarm.setHandleResult(dto.getHandleResult()); gasAlarmMapper.updateById(alarm); log.info(&quot;瓦斯报警已处理: alarmId=&#123;&#125;, handlerId=&#123;&#125;&quot;, id, dto.getHandlerId()); &#125; @Override public void reportAlarm(GasAlarmDTO dto) &#123; // 浓度校验 if (dto.getConcentration().compareTo(BigDecimal.valueOf(1.0)) &gt; 0) &#123; // 超标异常 - 自动触发紧急通知 throw new GasConcentrationException(dto.getMineCode(), dto.getConcentration()); &#125; // 保存报警记录 GasAlarm alarm = new GasAlarm(); BeanUtils.copyProperties(dto, alarm); alarm.setStatus(AlarmStatus.PENDING); gasAlarmMapper.insert(alarm); &#125;&#125;
完整的全局异常处理器/** * 智慧矿山 - 全局异常处理器 * 统一处理所有Controller抛出的异常 */@Slf4j@RestControllerAdvicepublic class GlobalExceptionHandler &#123; @Autowired private DingTalkService dingTalkService; // ===== 业务异常 ===== @ExceptionHandler(BusinessException.class) public Result&lt;?&gt; handleBusiness(BusinessException e) &#123; log.warn(&quot;业务异常: code=&#123;&#125;, msg=&#123;&#125;&quot;, e.getCode(), e.getMessage()); return Result.fail(e.getCode(), e.getMessage()); &#125; // ===== 瓦斯浓度超标特殊处理 ===== @ExceptionHandler(GasConcentrationException.class) public Result&lt;?&gt; handleGasConcentration(GasConcentrationException e) &#123; log.warn(&quot;瓦斯浓度超标: mineCode=&#123;&#125;, concentration=&#123;&#125;%&quot;, e.getMineCode(), e.getConcentration()); // 异步发送紧急通知 dingTalkService.sendAlarm( String.format(&quot;[紧急] 瓦斯浓度超标! 矿井: %s, 浓度: %s%%&quot;, e.getMineCode(), e.getConcentration())); return Result.fail(e.getCode(), e.getMessage()); &#125; // ===== 认证授权异常 ===== @ExceptionHandler(UnauthorizedException.class) public Result&lt;?&gt; handleUnauthorized(UnauthorizedException e) &#123; log.warn(&quot;未认证: &#123;&#125;&quot;, e.getMessage()); return Result.fail(401, &quot;请先登录&quot;); &#125; @ExceptionHandler(ForbiddenException.class) public Result&lt;?&gt; handleForbidden(ForbiddenException e) &#123; log.warn(&quot;无权限: &#123;&#125;&quot;, e.getMessage()); return Result.fail(403, &quot;无操作权限&quot;); &#125; // ===== 参数校验异常 ===== @ExceptionHandler(MethodArgumentNotValidException.class) public Result&lt;?&gt; handleMethodArgumentNotValid(MethodArgumentNotValidException e) &#123; String msg = e.getBindingResult().getFieldErrors().stream() .map(fe -&gt; fe.getField() + &quot;: &quot; + fe.getDefaultMessage()) .collect(Collectors.joining(&quot;; &quot;)); log.warn(&quot;参数校验失败: &#123;&#125;&quot;, msg); return Result.fail(400, msg); &#125; @ExceptionHandler(ConstraintViolationException.class) public Result&lt;?&gt; handleConstraintViolation(ConstraintViolationException e) &#123; String msg = e.getConstraintViolations().stream() .map(ConstraintViolation::getMessage) .collect(Collectors.joining(&quot;; &quot;)); log.warn(&quot;约束校验失败: &#123;&#125;&quot;, msg); return Result.fail(400, msg); &#125; @ExceptionHandler(MethodArgumentTypeMismatchException.class) public Result&lt;?&gt; handleTypeMismatch(MethodArgumentTypeMismatchException e) &#123; String msg = &quot;参数类型错误: &quot; + e.getName() + &quot; 应为 &quot; + e.getRequiredType(); log.warn(&quot;参数类型不匹配: &#123;&#125;&quot;, msg); return Result.fail(400, msg); &#125; @ExceptionHandler(HttpMessageNotReadableException.class) public Result&lt;?&gt; handleHttpMessageNotReadable(HttpMessageNotReadableException e) &#123; log.warn(&quot;请求体解析失败: &#123;&#125;&quot;, e.getMessage()); return Result.fail(400, &quot;请求体格式错误&quot;); &#125; @ExceptionHandler(MissingServletRequestParameterException.class) public Result&lt;?&gt; handleMissingParam(MissingServletRequestParameterException e) &#123; log.warn(&quot;缺少请求参数: &#123;&#125;&quot;, e.getParameterName()); return Result.fail(400, &quot;缺少参数: &quot; + e.getParameterName()); &#125; @ExceptionHandler(BindException.class) public Result&lt;?&gt; handleBindException(BindException e) &#123; String msg = e.getFieldErrors().stream() .map(fe -&gt; fe.getField() + &quot;: &quot; + fe.getDefaultMessage()) .collect(Collectors.joining(&quot;; &quot;)); log.warn(&quot;参数绑定失败: &#123;&#125;&quot;, msg); return Result.fail(400, msg); &#125; // ===== 请求方式异常 ===== @ExceptionHandler(HttpMediaTypeNotSupportedException.class) public Result&lt;?&gt; handleMediaTypeNotSupported(HttpMediaTypeNotSupportedException e) &#123; log.warn(&quot;不支持的媒体类型: &#123;&#125;&quot;, e.getContentType()); return Result.fail(415, &quot;不支持的Content-Type&quot;); &#125; @ExceptionHandler(HttpRequestMethodNotSupportedException.class) public Result&lt;?&gt; handleMethodNotSupported(HttpRequestMethodNotSupportedException e) &#123; log.warn(&quot;不支持的请求方法: &#123;&#125;&quot;, e.getMethod()); return Result.fail(405, &quot;不支持的请求方法: &quot; + e.getMethod()); &#125; // ===== 数据库异常 ===== @ExceptionHandler(DataAccessException.class) public Result&lt;?&gt; handleDataAccess(DataAccessException e) &#123; log.error(&quot;数据库异常&quot;, e); return Result.fail(500, &quot;数据操作失败&quot;); &#125; @ExceptionHandler(DuplicateKeyException.class) public Result&lt;?&gt; handleDuplicateKey(DuplicateKeyException e) &#123; log.warn(&quot;数据重复: &#123;&#125;&quot;, e.getMessage()); return Result.fail(400, &quot;数据已存在，请勿重复提交&quot;); &#125; // ===== 系统异常 ===== @ExceptionHandler(Exception.class) public Result&lt;?&gt; handleException(Exception e) &#123; log.error(&quot;未处理异常&quot;, e); // 系统异常发送告警 dingTalkService.sendAlarm(&quot;系统异常: &quot; + e.getClass().getSimpleName() + &quot; - &quot; + e.getMessage()); return Result.fail(500, &quot;系统繁忙，请稍后重试&quot;); &#125;&#125;
异常处理的原则1. 不要吞掉异常// ❌ 吞掉异常，日志里找不到@ExceptionHandler(Exception.class)public Result&lt;?&gt; handleException(Exception e) &#123; return Result.fail(&quot;系统繁忙&quot;); // 没有记录日志！&#125;// ✅ 至少记录日志@ExceptionHandler(Exception.class)public Result&lt;?&gt; handleException(Exception e) &#123; log.error(&quot;未处理异常&quot;, e); return Result.fail(&quot;系统繁忙&quot;);&#125;
2. 不要把堆栈信息返回给前端// ❌ 暴露堆栈信息（安全隐患）@ExceptionHandler(Exception.class)public Result&lt;?&gt; handleException(Exception e) &#123; return Result.fail(Arrays.toString(e.getStackTrace()));&#125;// ❌ 暴露数据库异常详情@ExceptionHandler(DataAccessException.class)public Result&lt;?&gt; handleDataAccess(DataAccessException e) &#123; return Result.fail(e.getMessage()); // 可能包含SQL语句和表结构&#125;// ✅ 返回友好提示@ExceptionHandler(Exception.class)public Result&lt;?&gt; handleException(Exception e) &#123; log.error(&quot;系统异常&quot;, e); // 日志中记录完整信息 return Result.fail(&quot;系统繁忙&quot;); // 前端只看到友好提示&#125;
3. 异常粒度要合适// ❌ 所有异常都归为一类@ExceptionHandler(Exception.class)public Result&lt;?&gt; handleAll(Exception e) &#123; return Result.fail(e.getMessage());&#125;// ✅ 区分业务异常和系统异常@ExceptionHandler(GasConcentrationException.class) // 最具体，发告警@ExceptionHandler(BusinessException.class) // 通用业务异常@ExceptionHandler(Exception.class) // 系统异常，通用提示
4. 日志级别要区分异常日志级别选择
参数校验异常 → log.warn 理由：客户端问题，不是系统bug 业务异常 → log.warn 理由：预期的业务错误，不是系统bug 系统异常 → log.error 理由：非预期的系统bug，需要关注和修复 数据库异常 → log.error 理由：可能是数据问题或系统bug 认证授权异常 → log.warn 理由：可能是攻击行为，需要记录但不是bug
5. 异常处理器按粒度从细到粗排列// ✅ 正确顺序：细粒度在前，粗粒度在后@ExceptionHandler(GasConcentrationException.class) // 最具体@ExceptionHandler(BusinessException.class) // 中等@ExceptionHandler(Exception.class) // 最宽泛// Spring匹配规则：最精确的异常类型优先匹配// 如果有多个@ExceptionHandler匹配，取最具体的那个
异常与 HTTP 状态码异常与HTTP状态码映射
2xx 成功 200 OK → 正常业务响应 201 Created → 资源创建成功 4xx 客户端错误 400 Bad Request → 参数校验失败 401 Unauthorized → 未认证 403 Forbidden → 无权限 404 Not Found → 资源不存在 405 Method Not Allowed → 请求方法不支持 415 Unsupported Media Type → Content-Type不支持 429 Too Many Requests → 请求过于频繁 5xx 服务端错误 500 Internal Server Error → 系统异常 注意：前后端分离项目中，HTTP状态码通常都返回200 通过业务状态码(Result.code)来区分成功&#x2F;失败 只有认证&#x2F;授权类异常才使用401&#x2F;403状态码
异常与前端联动// 前端axios拦截器 - 实际项目axios.interceptors.response.use( response =&gt; &#123; const result = response.data; if (result.code === 200) &#123; return result.data; &#125; else if (result.code === 401) &#123; router.push(&#x27;/login&#x27;); Message.error(&#x27;登录已过期，请重新登录&#x27;); &#125; else if (result.code === 403) &#123; Message.error(&#x27;无操作权限&#x27;); &#125; else if (result.code === 400) &#123; Message.error(result.msg); &#125; else if (result.code === 429) &#123; Message.warning(&#x27;操作过于频繁，请稍后再试&#x27;); &#125; else if (result.code === 4001) &#123; // 瓦斯浓度超标特殊处理 Message.error(&#123; message: result.msg, duration: 0 &#125;); // 不自动关闭 &#125; else &#123; Message.error(result.msg || &#x27;操作失败&#x27;); &#125; return Promise.reject(result); &#125;, error =&gt; &#123; if (error.response) &#123; switch (error.response.status) &#123; case 401: router.push(&#x27;/login&#x27;); break; case 403: Message.error(&#x27;无权限&#x27;); break; case 500: Message.error(&#x27;服务器异常&#x27;); break; default: Message.error(&#x27;网络异常&#x27;); &#125; &#125; else &#123; Message.error(&#x27;网络异常&#x27;); &#125; return Promise.reject(error); &#125;);
异常处理的进阶用法1. 异常处理器中获取请求信息@ExceptionHandler(Exception.class)public Result&lt;?&gt; handleException(Exception e, HttpServletRequest request) &#123; String uri = request.getRequestURI(); String method = request.getMethod(); LoginUser user = UserContext.get(); log.error(&quot;未处理异常: uri=&#123;&#125;, method=&#123;&#125;, user=&#123;&#125;&quot;, uri, method, user != null ? user.getUsername() : &quot;anonymous&quot;, e); return Result.fail(500, &quot;系统繁忙&quot;);&#125;
2. 异常处理器返回不同HTTP状态码@ExceptionHandler(UnauthorizedException.class)public ResponseEntity&lt;Result&lt;?&gt;&gt; handleUnauthorized(UnauthorizedException e) &#123; log.warn(&quot;未认证: &#123;&#125;&quot;, e.getMessage()); return ResponseEntity.status(401).body(Result.fail(401, &quot;请先登录&quot;));&#125;@ExceptionHandler(ForbiddenException.class)public ResponseEntity&lt;Result&lt;?&gt;&gt; handleForbidden(ForbiddenException e) &#123; log.warn(&quot;无权限: &#123;&#125;&quot;, e.getMessage()); return ResponseEntity.status(403).body(Result.fail(403, &quot;无操作权限&quot;));&#125;
3. 异步线程异常处理/** * 异步任务异常处理器 */@Component@Slf4jpublic class AsyncExceptionHandler implements AsyncUncaughtExceptionHandler &#123; @Autowired private DingTalkService dingTalkService; @Override public void handleUncaughtException(Throwable ex, Method method, Object... params) &#123; log.error(&quot;异步任务异常: method=&#123;&#125;, params=&#123;&#125;&quot;, method.getName(), params, ex); dingTalkService.sendAlarm(&quot;异步任务异常: &quot; + method.getName() + &quot; - &quot; + ex.getMessage()); &#125;&#125;@Configurationpublic class AsyncConfig implements AsyncConfigurer &#123; @Autowired private AsyncExceptionHandler asyncExceptionHandler; @Override public AsyncUncaughtExceptionHandler getAsyncUncaughtExceptionHandler() &#123; return asyncExceptionHandler; &#125;&#125;
4. 异常统计和告警/** * 异常统计切面 —— 统计各类异常的发生频率 */@Aspect@Component@Slf4jpublic class ExceptionStatisticsAspect &#123; @Autowired private StringRedisTemplate redisTemplate; @AfterThrowing(pointcut = &quot;execution(* com.mine.controller..*.*(..))&quot;, throwing = &quot;ex&quot;) public void statisticException(JoinPoint jp, Exception ex) &#123; String key = &quot;exception:stat:&quot; + LocalDate.now().format( DateTimeFormatter.ofPattern(&quot;yyyyMMdd&quot;)); String field = ex.getClass().getSimpleName(); // 计数 redisTemplate.opsForHash().increment(key, field, 1); redisTemplate.expire(key, 7, TimeUnit.DAYS); // 异常频率告警 Object count = redisTemplate.opsForHash().get(key, field); if (count != null &amp;&amp; Long.parseLong(count.toString()) &gt; 100) &#123; log.warn(&quot;异常频率告警: &#123;&#125; 在今日已发生&#123;&#125;次&quot;, field, count); &#125; &#125;&#125;
总结全局异常处理是接口规范化的基础设施。在实际场景中，从每个方法 try-catch 到统一全局处理，核心收获是：异常处理是横切关注点，应该统一管理而非分散处理。好的异常处理体系让代码更简洁、错误更可追溯、用户体验更友好。 关键收获：
@RestControllerAdvice 是全局异常处理的核心注解 异常分类体系 让错误码和消息更有语义 业务异常 warn，系统异常 error 是日志级别的基本规则 永远不要把堆栈返回给前端 是安全底线 异常处理器粒度从细到粗 是匹配顺序的关键 关键异常要告警 是运维的保障
异常处理设计模式异常链模式// 保留原始异常信息，同时包装为业务异常@Servicepublic class VentControlService &#123; public void sendCommand(String deviceId, VentCommand command) &#123; try &#123; ventClient.send(deviceId, command); &#125; catch (SocketTimeoutException e) &#123; // 包装原始异常，但不丢失信息 throw new VentControlException(&quot;通风控制指令超时: deviceId=&quot; + deviceId, e); &#125; catch (ConnectException e) &#123; throw new VentControlException(&quot;通风设备连接失败: deviceId=&quot; + deviceId, e); &#125; &#125;&#125;// 全局处理器中可以获取原始异常@ExceptionHandler(VentControlException.class)public Result&lt;?&gt; handleVentControl(VentControlException e) &#123; Throwable cause = e.getCause(); if (cause instanceof SocketTimeoutException) &#123; log.error(&quot;通风控制超时: &#123;&#125;&quot;, e.getMessage()); alarmService.sendWarningAlarm(&quot;通风控制超时: &quot; + e.getMessage()); &#125; else if (cause instanceof ConnectException) &#123; log.error(&quot;通风设备连接失败: &#123;&#125;&quot;, e.getMessage()); alarmService.sendCriticalAlarm(&quot;通风设备连接失败&quot;); &#125; return Result.fail(e.getCode(), e.getMessage());&#125;
异常码注册表模式// 统一管理所有异常码@Componentpublic class ErrorCodeRegistry &#123; private final Map&lt;Integer, ErrorCodeDefinition&gt; errorCodes = new HashMap&lt;&gt;(); @PostConstruct public void init() &#123; register(4001, &quot;GAS_ALARM&quot;, &quot;瓦斯报警&quot;, AlertLevel.CRITICAL); register(4002, &quot;DEVICE_OFFLINE&quot;, &quot;设备离线&quot;, AlertLevel.WARNING); register(4003, &quot;VENT_CONTROL_FAILED&quot;, &quot;通风控制失败&quot;, AlertLevel.CRITICAL); register(5001, &quot;DB_ERROR&quot;, &quot;数据库异常&quot;, AlertLevel.CRITICAL); register(5002, &quot;RPC_ERROR&quot;, &quot;远程调用异常&quot;, AlertLevel.WARNING); register(5003, &quot;MQ_ERROR&quot;, &quot;消息队列异常&quot;, AlertLevel.WARNING); &#125; public ErrorCodeDefinition get(int code) &#123; return errorCodes.get(code); &#125; private void register(int code, String name, String desc, AlertLevel level) &#123; errorCodes.put(code, new ErrorCodeDefinition(code, name, desc, level)); &#125;&#125;
断言工具类// 简化参数校验，减少if-throwpublic final class BizAssert &#123; private BizAssert() &#123;&#125; public static void notNull(Object obj, String message) &#123; if (obj == null) &#123; throw new BusinessException(message); &#125; &#125; public static void isTrue(boolean expression, String message) &#123; if (!expression) &#123; throw new BusinessException(message); &#125; &#125; public static void isTrue(boolean expression, ResultCode resultCode) &#123; if (!expression) &#123; throw new BusinessException(resultCode); &#125; &#125; public static void notEmpty(Collection&lt;?&gt; collection, String message) &#123; if (collection == null || collection.isEmpty()) &#123; throw new BusinessException(message); &#125; &#125;&#125;// 使用@Servicepublic class GasMonitorService &#123; public GasDataVO getById(Long id) &#123; BizAssert.notNull(id, &quot;瓦斯数据ID不能为空&quot;); GasData data = gasMapper.selectById(id); BizAssert.isTrue(data != null, ResultCode.GAS_SENSOR_OFFLINE); return GasDataConverter.toVO(data); &#125;&#125;
异常处理器扩展点// 可扩展的异常处理框架public interface ExceptionHandlerStrategy &#123; boolean supports(Throwable ex); Result&lt;?&gt; handle(Throwable ex);&#125;@Componentpublic class DatabaseExceptionStrategy implements ExceptionHandlerStrategy &#123; @Override public boolean supports(Throwable ex) &#123; return ex instanceof DataAccessException; &#125; @Override public Result&lt;?&gt; handle(Throwable ex) &#123; log.error(&quot;数据库异常&quot;, ex); return Result.fail(500, &quot;数据操作失败&quot;); &#125;&#125;@Componentpublic class RpcExceptionStrategy implements ExceptionHandlerStrategy &#123; @Override public boolean supports(Throwable ex) &#123; return ex instanceof RestClientException; &#125; @Override public Result&lt;?&gt; handle(Throwable ex) &#123; log.error(&quot;远程调用异常&quot;, ex); return Result.fail(502, &quot;远程服务异常&quot;); &#125;&#125;// 全局处理器委托给策略@RestControllerAdvicepublic class StrategyExceptionHandler &#123; @Autowired private List&lt;ExceptionHandlerStrategy&gt; strategies; @ExceptionHandler(Exception.class) public Result&lt;?&gt; handleException(Exception e) &#123; for (ExceptionHandlerStrategy strategy : strategies) &#123; if (strategy.supports(e)) &#123; return strategy.handle(e); &#125; &#125; log.error(&quot;未处理异常&quot;, e); return Result.fail(500, &quot;系统繁忙&quot;); &#125;&#125;
异常处理完整检查表
检查项 是否完成 备注
全局异常处理器 - @RestControllerAdvice
业务异常基类 - BusinessException
异常码枚举 - ResultCode
参数校验异常处理 - MethodArgumentNotValidException
权限异常处理 - 401&#x2F;403
数据库异常处理 - DataAccessException
远程调用异常处理 - RestClientException
系统异常兜底 - Exception
异常日志记录 - warn&#x2F;error区分
异常报警通知 - 关键异常联动
异步线程异常 - AsyncUncaughtExceptionHandler
Feign异常解码 - ErrorDecoder
生产环境隐藏详情 - 不返回e.getMessage()
异常链保留 - cause不被覆盖
批量操作异常收集 - 不提前中断

前言 在实际场景中，刚学Java的时候，创建对象只知道用new。直到看Spring的源码，发现框架从来不用new来创建Bean，而是通过反射来实例化对象。那一刻我才意识到，反射是理解框架底层设计的钥匙。 什么是反射？反射是Java在运行时获取类的信息（字段、方法、构造器等）并动态调用的能力。 正常方式：编译时确定类型 → new对象 → 调用方法反射方式：运行时确定类型 → 获取Class → 动态调用 获取Class对象的三种方式// 方式1：类名.class（编译时已知）Class&lt;User&gt; clazz1 = User.class;// 方式2：对象.getClass()（运行时已知）User user = new User();Class&lt; extends User&gt; clazz2 = user.getClass();// 方式3：Class.forName()（全限定类名，运行时加载）Class&lt;&gt; clazz3 = Class.forName(&quot;com.example.User&quot;);// 三种方式获取的是同一个Class对象System.out.println(clazz1 == clazz2); // trueSystem.out.println(clazz2 == clazz3); // true
选择原则：
知道类名用.class 有对象用.getClass() 只知道全限定类名用Class.forName()
反射的核心操作1. 创建实例Class&lt;?&gt; clazz = Class.forName(&quot;com.example.User&quot;);// 方式1：无参构造Object obj = clazz.newInstance(); // JDK 9已废弃// 方式2：通过构造器（推荐）Constructor&lt;&gt; constructor = clazz.getDeclaredConstructor();constructor.setAccessible(true); // 突破private限制Object obj2 = constructor.newInstance();// 方式3：有参构造Constructor&lt;&gt; constructor2 = clazz.getDeclaredConstructor(String.class, int.class);Object obj3 = constructor2.newInstance(&quot;张三&quot;, 25);
2. 操作字段Class&lt;&gt; clazz = User.class;Object obj = clazz.getDeclaredConstructor().newInstance();// 获取public字段Field nameField = clazz.getField(&quot;name&quot;);// 获取所有声明字段（包括private）Field[] fields = clazz.getDeclaredFields();// 获取指定字段（包括private）Field ageField = clazz.getDeclaredField(&quot;age&quot;);ageField.setAccessible(true); // 突破private// 读取字段值Object value = ageField.get(obj);// 设置字段值ageField.set(obj, 30);
3. 调用方法Class&lt;&gt; clazz = User.class;Object obj = clazz.getDeclaredConstructor().newInstance();// 获取public方法Method method1 = clazz.getMethod(&quot;toString&quot;);// 获取所有声明方法（包括private）Method[] methods = clazz.getDeclaredMethods();// 获取指定方法（包括private）Method method2 = clazz.getDeclaredMethod(&quot;privateMethod&quot;, String.class);method2.setAccessible(true);// 调用方法Object result = method2.invoke(obj, &quot;参数&quot;);
4. 操作注解// 获取类上的注解MyAnnotation annotation = clazz.getAnnotation(MyAnnotation.class);// 获取方法上的注解Method method = clazz.getMethod(&quot;doSomething&quot;);MyAnnotation methodAnnotation = method.getAnnotation(MyAnnotation.class);// 获取字段上的注解Field field = clazz.getDeclaredField(&quot;name&quot;);MyAnnotation fieldAnnotation = field.getAnnotation(MyAnnotation.class);
反射在框架中的应用Spring的Bean创建// Spring简化版：通过反射创建Beanpublic Object createBean(String className) throws Exception &#123; Class&lt;&gt; clazz = Class.forName(className); Object instance = clazz.getDeclaredConstructor().newInstance(); // 依赖注入：扫描@Autowired注解 for (Field field : clazz.getDeclaredFields()) &#123; if (field.isAnnotationPresent(Autowired.class)) &#123; field.setAccessible(true); Object dependency = getBean(field.getType()); field.set(instance, dependency); &#125; &#125; return instance;&#125;
MyBatis的Mapper代理// MyBatis通过动态代理+反射实现Mapper接口调用public class MapperProxy implements InvocationHandler &#123; @Override public Object invoke(Object proxy, Method method, Object[] args) &#123; // 通过反射获取方法信息，映射到SQL语句 String statementId = method.getDeclaringClass().getName() + &quot;.&quot; + method.getName(); return sqlSession.selectOne(statementId, args); &#125;&#125;
反射的性能问题反射比直接调用慢很多： // 直接调用：~1msUser user = new User();user.getName();// 反射调用：~100ms（100倍差距）Class&lt;&gt; clazz = Class.forName(&quot;com.example.User&quot;);Method method = clazz.getMethod(&quot;getName&quot;);method.invoke(clazz.getDeclaredConstructor().newInstance());
慢的原因：
需要查找方法&#x2F;字段 需要安全检查 需要装箱拆箱 JIT难以优化
性能优化// 1. 缓存Class/Method/Field对象private static final Map&lt;String, Method&gt; METHOD_CACHE = new ConcurrentHashMap&lt;&gt;();public static Method getCachedMethod(Class&lt;&gt; clazz, String name, Class&lt;&gt;... paramTypes) &#123; String key = clazz.getName() + &quot;#&quot; + name; return METHOD_CACHE.computeIfAbsent(key, k -&gt; &#123; try &#123; return clazz.getMethod(name, paramTypes); &#125; catch (NoSuchMethodException e) &#123; throw new RuntimeException(e); &#125; &#125;);&#125;// 2. setAccessible(true)可以关闭安全检查，提升性能method.setAccessible(true);
反射的破坏性反射可以突破访问控制，带来安全隐患： // 突破private访问Field field = clazz.getDeclaredField(&quot;privateField&quot;);field.setAccessible(true);// 突破final修改Field modifiersField = Field.class.getDeclaredField(&quot;modifiers&quot;);modifiersField.setAccessible(true);modifiersField.setInt(field, field.getModifiers() &amp; ~Modifier.FINAL);// 突破单例模式Constructor&lt;&gt; constructor = Singleton.class.getDeclaredConstructor();constructor.setAccessible(true);Singleton instance = constructor.newInstance(); // 创建了第二个实例！
总结 反射是Java的高级特性，也是理解Spring、MyBatis等框架底层原理的钥匙。核心认知是：反射让Java具备了运行时动态性，这是框架设计的基石。但在日常业务开发中，应该尽量少用反射，直接调用更安全、更高效。理解反射，是为了读懂框架，而不是为了在业务代码中炫技。 反射在实际项目中的应用设备处理器动态加载@Servicepublic class DataProcessorFactory &#123; private final Map&lt;String, DataProcessor&gt; processorMap = new ConcurrentHashMap&lt;&gt;(); @PostConstruct public void init() &#123; // 扫描DataProcessor接口的所有实现 Map&lt;String, DataProcessor&gt; beans = applicationContext.getBeansOfType(DataProcessor.class); for (DataProcessor processor : beans.values()) &#123; processorMap.put(processor.getDeviceType(), processor); &#125; log.info(&quot;加载设备数据处理器: &#123;&#125;种&quot;, processorMap.size()); &#125; public DataProcessor getProcessor(String deviceType) &#123; DataProcessor processor = processorMap.get(deviceType); if (processor == null) &#123; throw new BusinessException(&quot;不支持的设备类型: &quot; + deviceType); &#125; return processor; &#125;&#125;
设备数据校验器@Componentpublic class DeviceDataValidator &#123; /** * 使用反射进行字段级校验 */ public List&lt;String&gt; validate(Object obj) &#123; List&lt;String&gt; errors = new ArrayList&lt;&gt;(); Class&lt;?&gt; clazz = obj.getClass(); for (Field field : clazz.getDeclaredFields()) &#123; // 检查@NotNull注解 if (field.isAnnotationPresent(NotNull.class)) &#123; field.setAccessible(true); try &#123; Object value = field.get(obj); if (value == null) &#123; NotNull annotation = field.getAnnotation(NotNull.class); errors.add(field.getName() + &quot;: &quot; + annotation.message()); &#125; &#125; catch (IllegalAccessException e) &#123; log.error(&quot;校验字段失败: &#123;&#125;&quot;, field.getName(), e); &#125; &#125; // 检查@Range注解 if (field.isAnnotationPresent(Range.class)) &#123; field.setAccessible(true); try &#123; Range range = field.getAnnotation(Range.class); double value = field.getDouble(obj); if (value &lt; range.min() || value &gt; range.max()) &#123; errors.add(field.getName() + &quot;: &quot; + range.message()); &#125; &#125; catch (IllegalAccessException e) &#123; log.error(&quot;校验字段失败: &#123;&#125;&quot;, field.getName(), e); &#125; &#125; &#125; return errors; &#125;&#125;
总结反射是Java的高级特性，也是理解Spring、MyBatis等框架底层原理的钥匙。核心认知是：反射让Java具备了运行时动态性，这是框架设计的基石。但在日常业务开发中，应该尽量少用反射，直接调用更安全、更高效。理解反射，是为了读懂框架，而不是为了在业务代码中炫技。 反射性能优化在实际项目中的实践@Componentpublic class ReflectionCache &#123; // 缓存Method对象，避免重复查找 private static final ConcurrentHashMap&lt;String, Method&gt; METHOD_CACHE = new ConcurrentHashMap&lt;&gt;(); public static Method getCachedMethod(Class&lt;?&gt; clazz, String methodName, Class&lt;?&gt;... paramTypes) &#123; String key = clazz.getName() + &quot;#&quot; + methodName; return METHOD_CACHE.computeIfAbsent(key, k -&gt; &#123; try &#123; Method method = clazz.getDeclaredMethod(methodName, paramTypes); method.setAccessible(true); return method; &#125; catch (NoSuchMethodException e) &#123; throw new RuntimeException(e); &#125; &#125;); &#125;&#125;
反射使用原则
原则 说明
框架开发用反射 Spring&#x2F;MyBatis底层依赖反射
业务开发少用反射 直接调用更安全高效
缓存反射对象 避免重复查找的性能开销
setAccessible(true) 关闭安全检查提升性能
不破坏封装 不用反射随意修改私有字段
反射知识速查
问题 答案
获取Class方式 .class &#x2F; getClass() &#x2F; Class.forName()
创建实例 getDeclaredConstructor().newInstance()
访问私有字段 setAccessible(true)
调用私有方法 getDeclaredMethod() + setAccessible + invoke
性能优化 缓存Method&#x2F;Field + setAccessible(true)

前言 在实际场景中，审批流程是最核心的业务之一。矿山作业涉及大量安全审批：下井作业审批、爆破作业审批、设备检修审批、物料领用审批——每种流程的审批节点和流转规则都不同。最初用if-else硬编码处理状态流转，随着业务复杂度上升，代码越来越难以维护。后来用状态机模式重构，状态流转规则变得清晰可维护，审批日志让每一步操作都有迹可循。 本文以实际项目中的”下井作业审批”为例，从数据库设计到状态机实现，完整展示审批流开发的全过程。 审批流整体架构智慧矿山审批流架构 下井作业审批流程下井作业审批流程：
矿工提交 → 班组长审批 → 通过 → 安全主管审批 → 通过 → 矿长审批 → 通过&#x2F;驳回 驳回 → 班组长重新审批 驳回 → 矿工修改&#x2F;取消 状态流转图： +——–+ 提交 +————+ 班组长通过 +————+ 草稿 | ——–&gt; | 待班组长审批 | ————&gt; | 待安全主管审批 +——–+ +————+ +————+ | | 取消 | 班组长驳回 | 安全主管驳回 v v | +——–+ +——–+ | | 已取消 | | 已驳回 | &lt;———————-+ +——–+ +——–+ | | 修改后重新提交 | 矿长驳回 v v +————+ 安全主管通过 +———-+ 待班组长审批 | ————–&gt; | 待矿长审批 +————+ +———-+ | 矿长通过 | 矿长驳回 v | | +——–+ | | 已通过 | | +——–+ | | v v 已驳回
数据库设计下井作业申请表CREATE TABLE `biz_mine_entry` ( `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT &#x27;主键ID&#x27;, `title` VARCHAR(100) NOT NULL COMMENT &#x27;申请标题&#x27;, `applicant_id` BIGINT NOT NULL COMMENT &#x27;申请人ID（矿工）&#x27;, `mine_area` VARCHAR(50) NOT NULL COMMENT &#x27;下井区域：1-采煤区 2-掘进区 3-运输区 4-通风区&#x27;, `entry_date` DATE NOT NULL COMMENT &#x27;下井日期&#x27;, `entry_time` TIME NOT NULL COMMENT &#x27;下井时间&#x27;, `exit_time` TIME DEFAULT NULL COMMENT &#x27;升井时间&#x27;, `work_content` VARCHAR(500) NOT NULL COMMENT &#x27;作业内容&#x27;, `risk_level` TINYINT NOT NULL COMMENT &#x27;风险等级：1-低 2-中 3-高 4-极高&#x27;, `gas_concentration` DECIMAL(5,2) DEFAULT NULL COMMENT &#x27;瓦斯浓度（%）&#x27;, `ventilation_status` TINYINT DEFAULT NULL COMMENT &#x27;通风状态：0-异常 1-正常&#x27;, `status` TINYINT NOT NULL DEFAULT 0 COMMENT &#x27;状态：0-草稿 1-待班组长审批 2-待安全主管审批 3-待矿长审批 4-已通过 5-已驳回 6-已取消&#x27;, `current_node` VARCHAR(30) DEFAULT &#x27;DRAFT&#x27; COMMENT &#x27;当前审批节点&#x27;, `approver_id` BIGINT DEFAULT NULL COMMENT &#x27;当前审批人ID&#x27;, `reject_reason` VARCHAR(500) DEFAULT NULL COMMENT &#x27;驳回原因&#x27;, `version` INT NOT NULL DEFAULT 1 COMMENT &#x27;乐观锁版本号&#x27;, `deleted` TINYINT NOT NULL DEFAULT 0 COMMENT &#x27;逻辑删除：0-未删除 1-已删除&#x27;, `create_by` BIGINT DEFAULT NULL COMMENT &#x27;创建人ID&#x27;, `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT &#x27;创建时间&#x27;, `update_by` BIGINT DEFAULT NULL COMMENT &#x27;更新人ID&#x27;, `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT &#x27;更新时间&#x27;, PRIMARY KEY (`id`), KEY `idx_applicant` (`applicant_id`), KEY `idx_approver` (`approver_id`, `status`), KEY `idx_entry_date` (`entry_date`), KEY `idx_mine_area_status` (`mine_area`, `status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=&#x27;下井作业申请&#x27;;
审批日志表CREATE TABLE `biz_approval_log` ( `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT &#x27;主键ID&#x27;, `biz_id` BIGINT NOT NULL COMMENT &#x27;业务ID&#x27;, `biz_type` VARCHAR(20) NOT NULL COMMENT &#x27;业务类型：MINE_ENTRY/BLAST/REPAIR/PURCHASE&#x27;, `node` VARCHAR(30) NOT NULL COMMENT &#x27;审批节点&#x27;, `action` VARCHAR(20) NOT NULL COMMENT &#x27;操作：SUBMIT/APPROVE/REJECT/CANCEL/RESUBMIT&#x27;, `from_status` TINYINT DEFAULT NULL COMMENT &#x27;原状态&#x27;, `to_status` TINYINT DEFAULT NULL COMMENT &#x27;新状态&#x27;, `operator_id` BIGINT NOT NULL COMMENT &#x27;操作人ID&#x27;, `operator_name` VARCHAR(50) NOT NULL COMMENT &#x27;操作人姓名&#x27;, `operator_role` VARCHAR(30) DEFAULT NULL COMMENT &#x27;操作人角色&#x27;, `comment` VARCHAR(500) DEFAULT NULL COMMENT &#x27;审批意见&#x27;, `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT &#x27;创建时间&#x27;, PRIMARY KEY (`id`), KEY `idx_biz` (`biz_type`, `biz_id`), KEY `idx_operator` (`operator_id`), KEY `idx_create_time` (`create_time`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=&#x27;审批日志&#x27;;
审批节点配置表CREATE TABLE `sys_approval_node` ( `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT &#x27;主键ID&#x27;, `biz_type` VARCHAR(20) NOT NULL COMMENT &#x27;业务类型&#x27;, `node_code` VARCHAR(30) NOT NULL COMMENT &#x27;节点编码&#x27;, `node_name` VARCHAR(50) NOT NULL COMMENT &#x27;节点名称&#x27;, `node_order` INT NOT NULL COMMENT &#x27;节点顺序&#x27;, `approver_type` TINYINT NOT NULL COMMENT &#x27;审批人类型：1-直属上级 2-指定角色 3-指定人员&#x27;, `approver_role` VARCHAR(30) DEFAULT NULL COMMENT &#x27;审批人角色编码&#x27;, `approver_id` BIGINT DEFAULT NULL COMMENT &#x27;指定审批人ID&#x27;, `status` TINYINT NOT NULL DEFAULT 1 COMMENT &#x27;状态：0-禁用 1-启用&#x27;, `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uk_biz_node` (`biz_type`, `node_code`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=&#x27;审批节点配置&#x27;;-- 下井审批节点配置INSERT INTO sys_approval_node (biz_type, node_code, node_name, node_order, approver_type, approver_role) VALUES(&#x27;MINE_ENTRY&#x27;, &#x27;PENDING_LEADER&#x27;, &#x27;待班组长审批&#x27;, 1, 1, &#x27;LEADER&#x27;),(&#x27;MINE_ENTRY&#x27;, &#x27;PENDING_SAFETY&#x27;, &#x27;待安全主管审批&#x27;, 2, 2, &#x27;SAFETY_MANAGER&#x27;),(&#x27;MINE_ENTRY&#x27;, &#x27;PENDING_DIRECTOR&#x27;, &#x27;待矿长审批&#x27;, 3, 2, &#x27;MINE_DIRECTOR&#x27;);
状态枚举与流转规则/** * 下井作业审批状态枚举 * 状态码与数据库status字段对应 */@Getter@AllArgsConstructorpublic enum MineEntryStatus &#123; DRAFT(0, &quot;草稿&quot;), PENDING_LEADER(1, &quot;待班组长审批&quot;), PENDING_SAFETY(2, &quot;待安全主管审批&quot;), PENDING_DIRECTOR(3, &quot;待矿长审批&quot;), APPROVED(4, &quot;已通过&quot;), REJECTED(5, &quot;已驳回&quot;), CANCELLED(6, &quot;已取消&quot;); private final int code; private final String desc; private static final Map&lt;Integer, MineEntryStatus&gt; CODE_MAP = Arrays.stream(values()).collect(Collectors.toMap(MineEntryStatus::getCode, Function.identity())); public static MineEntryStatus of(int code) &#123; MineEntryStatus status = CODE_MAP.get(code); if (status == null) &#123; throw new IllegalArgumentException(&quot;非法状态码: &quot; + code); &#125; return status; &#125; /** * 状态流转规则 - 核心逻辑 * 定义每个状态可以流转到哪些目标状态 * * 状态流转图： * DRAFT ──────&gt; PENDING_LEADER ──────&gt; PENDING_SAFETY ──────&gt; PENDING_DIRECTOR ──────&gt; APPROVED * | | | | * | 取消 | 驳回 | 驳回 | 驳回 * v v v v * CANCELLED REJECTED &lt;──────────────────┘ | * | REJECTED * | 修改后重新提交 | * +──────────────&gt; PENDING_LEADER v * REJECTED */ public boolean canTransitionTo(MineEntryStatus target) &#123; switch (this) &#123; case DRAFT: return target == PENDING_LEADER || target == CANCELLED; case PENDING_LEADER: return target == PENDING_SAFETY || target == REJECTED; case PENDING_SAFETY: return target == PENDING_DIRECTOR || target == REJECTED; case PENDING_DIRECTOR: return target == APPROVED || target == REJECTED; case REJECTED: return target == PENDING_LEADER || target == CANCELLED; default: return false; &#125; &#125; /** * 判断是否为终态 */ public boolean isFinal() &#123; return this == APPROVED || this == CANCELLED; &#125; /** * 判断当前状态是否允许申请人操作 */ public boolean canApplicantOperate() &#123; return this == DRAFT || this == REJECTED; &#125;&#125;
审批操作枚举/** * 审批操作枚举 * 定义每种操作对应的源状态和目标状态 */@Getter@AllArgsConstructorpublic enum ApprovalAction &#123; SUBMIT(&quot;提交申请&quot;, &quot;DRAFT&quot;, &quot;PENDING_LEADER&quot;), LEADER_APPROVE(&quot;班组长通过&quot;, &quot;PENDING_LEADER&quot;, &quot;PENDING_SAFETY&quot;), LEADER_REJECT(&quot;班组长驳回&quot;, &quot;PENDING_LEADER&quot;, &quot;REJECTED&quot;), SAFETY_APPROVE(&quot;安全主管通过&quot;, &quot;PENDING_SAFETY&quot;, &quot;PENDING_DIRECTOR&quot;), SAFETY_REJECT(&quot;安全主管驳回&quot;, &quot;PENDING_SAFETY&quot;, &quot;REJECTED&quot;), DIRECTOR_APPROVE(&quot;矿长通过&quot;, &quot;PENDING_DIRECTOR&quot;, &quot;APPROVED&quot;), DIRECTOR_REJECT(&quot;矿长驳回&quot;, &quot;PENDING_DIRECTOR&quot;, &quot;REJECTED&quot;), RESUBMIT(&quot;重新提交&quot;, &quot;REJECTED&quot;, &quot;PENDING_LEADER&quot;), CANCEL(&quot;取消申请&quot;, &quot;DRAFT&quot;, &quot;CANCELLED&quot;); private final String desc; private final String fromStatus; private final String toStatus; /** * 根据当前状态和审批结果获取对应的操作枚举 */ public static ApprovalAction getApproveAction(MineEntryStatus currentStatus, boolean approved) &#123; String statusStr = currentStatus.name(); for (ApprovalAction action : values()) &#123; if (action.fromStatus.equals(statusStr)) &#123; if (approved &amp;&amp; action.name().endsWith(&quot;APPROVE&quot;)) &#123; return action; &#125; if (!approved &amp;&amp; action.name().endsWith(&quot;REJECT&quot;)) &#123; return action; &#125; &#125; &#125; throw new BusinessException(&quot;当前状态不支持该操作&quot;); &#125;&#125;
审批上下文对象/** * 审批上下文 - 封装审批操作所需的所有信息 */@Data@Builderpublic class ApprovalContext &#123; /** 业务ID */ private Long bizId; /** 业务类型 */ private String bizType; /** 当前状态 */ private MineEntryStatus currentStatus; /** 目标状态 */ private MineEntryStatus targetStatus; /** 审批动作 */ private ApprovalAction action; /** 操作人ID */ private Long operatorId; /** 审批意见 */ private String comment; /** 下一个审批人ID */ private Long nextApproverId; /** * 校验审批上下文合法性 */ public void validate() &#123; if (bizId == null) &#123; throw new BusinessException(&quot;业务ID不能为空&quot;); &#125; if (currentStatus == null || targetStatus == null) &#123; throw new BusinessException(&quot;状态信息不完整&quot;); &#125; if (!currentStatus.canTransitionTo(targetStatus)) &#123; throw new BusinessException( &quot;状态不允许从[&quot; + currentStatus.getDesc() + &quot;]变更为[&quot; + targetStatus.getDesc() + &quot;]&quot;); &#125; &#125;&#125;
Service层实现接口定义public interface MineEntryService extends IService&lt;MineEntry&gt; &#123; /** 提交下井申请 */ void submit(MineEntryCreateDTO dto); /** 审批操作（通过/驳回） */ void approve(Long id, ApprovalDTO dto); /** 重新提交（驳回后修改） */ void resubmit(Long id, MineEntryUpdateDTO dto); /** 取消申请 */ void cancel(Long id); /** 查询审批日志 */ List&lt;ApprovalLogVO&gt; getApprovalLogs(Long id); /** 查询我的待审批列表 */ PageResult&lt;MineEntryVO&gt; listMyPending(MineEntryQueryDTO query); /** 查询我提交的申请 */ PageResult&lt;MineEntryVO&gt; listMyApplied(MineEntryQueryDTO query);&#125;
Service实现@Service@RequiredArgsConstructor@Slf4jpublic class MineEntryServiceImpl extends ServiceImpl&lt;MineEntryMapper, MineEntry&gt; implements MineEntryService &#123; private final ApprovalLogMapper approvalLogMapper; private final UserService userService; private final ApprovalNodeMapper approvalNodeMapper; @Override @Transactional(rollbackFor = Exception.class) public void submit(MineEntryCreateDTO dto) &#123; Long userId = UserContext.getUserId(); // 1. 安全预检：高风险作业必须填写瓦斯浓度和通风状态 if (dto.getRiskLevel() &gt;= 3) &#123; if (dto.getGasConcentration() == null) &#123; throw new BusinessException(&quot;高风险作业必须填写瓦斯浓度&quot;); &#125; if (dto.getVentilationStatus() == null) &#123; throw new BusinessException(&quot;高风险作业必须填写通风状态&quot;); &#125; if (dto.getGasConcentration().compareTo(new BigDecimal(&quot;1.0&quot;)) &gt; 0) &#123; throw new BusinessException(&quot;瓦斯浓度超标（&gt;1.0%），禁止下井&quot;); &#125; if (dto.getVentilationStatus() == 0) &#123; throw new BusinessException(&quot;通风状态异常，禁止下井&quot;); &#125; &#125; // 2. 构建实体 MineEntry entry = new MineEntry(); entry.setTitle(dto.getTitle()); entry.setApplicantId(userId); entry.setMineArea(dto.getMineArea()); entry.setEntryDate(dto.getEntryDate()); entry.setEntryTime(dto.getEntryTime()); entry.setWorkContent(dto.getWorkContent()); entry.setRiskLevel(dto.getRiskLevel()); entry.setGasConcentration(dto.getGasConcentration()); entry.setVentilationStatus(dto.getVentilationStatus()); entry.setStatus(MineEntryStatus.PENDING_LEADER); entry.setCurrentNode(&quot;PENDING_LEADER&quot;); entry.setApproverId(getLeaderId(userId)); // 3. 保存 this.save(entry); // 4. 记录审批日志 saveLog(entry.getId(), &quot;MINE_ENTRY&quot;, &quot;DRAFT&quot;, &quot;SUBMIT&quot;, userId, &quot;提交下井申请&quot;); &#125; @Override @Transactional(rollbackFor = Exception.class) public void approve(Long id, ApprovalDTO dto) &#123; // 1. 查询申请 MineEntry entry = this.getById(id); if (entry == null) &#123; throw new BusinessException(&quot;下井申请不存在&quot;); &#125; // 2. 校验当前审批人 Long currentUserId = UserContext.getUserId(); if (!entry.getApproverId().equals(currentUserId)) &#123; throw new BusinessException(&quot;无权审批该申请&quot;); &#125; // 3. 确定目标状态 MineEntryStatus currentStatus = entry.getStatus(); MineEntryStatus targetStatus; Long nextApproverId = null; if (&quot;APPROVE&quot;.equals(dto.getAction())) &#123; switch (currentStatus) &#123; case PENDING_LEADER: targetStatus = MineEntryStatus.PENDING_SAFETY; entry.setCurrentNode(&quot;PENDING_SAFETY&quot;); nextApproverId = getSafetyManagerId(); break; case PENDING_SAFETY: targetStatus = MineEntryStatus.PENDING_DIRECTOR; entry.setCurrentNode(&quot;PENDING_DIRECTOR&quot;); nextApproverId = getMineDirectorId(); break; case PENDING_DIRECTOR: targetStatus = MineEntryStatus.APPROVED; entry.setCurrentNode(&quot;APPROVED&quot;); break; default: throw new BusinessException(&quot;当前状态不允许审批通过&quot;); &#125; &#125; else if (&quot;REJECT&quot;.equals(dto.getAction())) &#123; targetStatus = MineEntryStatus.REJECTED; entry.setCurrentNode(&quot;REJECTED&quot;); entry.setRejectReason(dto.getComment()); &#125; else &#123; throw new BusinessException(&quot;不支持的操作类型&quot;); &#125; // 4. 校验状态流转合法性（状态机核心校验） if (!currentStatus.canTransitionTo(targetStatus)) &#123; throw new BusinessException( &quot;状态不允许从[&quot; + currentStatus.getDesc() + &quot;]变更为[&quot; + targetStatus.getDesc() + &quot;]&quot;); &#125; // 5. 更新申请 entry.setStatus(targetStatus); entry.setApproverId(nextApproverId); this.updateById(entry); // 6. 记录审批日志 saveLog(id, &quot;MINE_ENTRY&quot;, entry.getCurrentNode(), dto.getAction(), currentUserId, dto.getComment()); // 7. 审批通过后通知矿工 if (targetStatus == MineEntryStatus.APPROVED) &#123; notifyApplicant(entry.getApplicantId(), &quot;下井申请已通过，请按计划下井作业&quot;); &#125; &#125; @Override @Transactional(rollbackFor = Exception.class) public void resubmit(Long id, MineEntryUpdateDTO dto) &#123; MineEntry entry = this.getById(id); if (entry == null) &#123; throw new BusinessException(&quot;下井申请不存在&quot;); &#125; if (entry.getStatus() != MineEntryStatus.REJECTED) &#123; throw new BusinessException(&quot;只有已驳回的申请可以重新提交&quot;); &#125; if (!entry.getApplicantId().equals(UserContext.getUserId())) &#123; throw new BusinessException(&quot;只能修改自己的申请&quot;); &#125; entry.setStatus(MineEntryStatus.PENDING_LEADER); entry.setCurrentNode(&quot;PENDING_LEADER&quot;); entry.setApproverId(getLeaderId(entry.getApplicantId())); entry.setRejectReason(null); if (dto.getWorkContent() != null) entry.setWorkContent(dto.getWorkContent()); if (dto.getEntryDate() != null) entry.setEntryDate(dto.getEntryDate()); if (dto.getEntryTime() != null) entry.setEntryTime(dto.getEntryTime()); if (dto.getRiskLevel() != null) entry.setRiskLevel(dto.getRiskLevel()); if (dto.getGasConcentration() != null) entry.setGasConcentration(dto.getGasConcentration()); if (dto.getVentilationStatus() != null) entry.setVentilationStatus(dto.getVentilationStatus()); this.updateById(entry); saveLog(id, &quot;MINE_ENTRY&quot;, &quot;REJECTED&quot;, &quot;RESUBMIT&quot;, UserContext.getUserId(), &quot;修改后重新提交&quot;); &#125; @Override @Transactional(rollbackFor = Exception.class) public void cancel(Long id) &#123; MineEntry entry = this.getById(id); if (entry == null) &#123; throw new BusinessException(&quot;下井申请不存在&quot;); &#125; if (!entry.getApplicantId().equals(UserContext.getUserId())) &#123; throw new BusinessException(&quot;只能取消自己的申请&quot;); &#125; if (!entry.getStatus().canApplicantOperate()) &#123; throw new BusinessException(&quot;当前状态不允许取消&quot;); &#125; entry.setStatus(MineEntryStatus.CANCELLED); entry.setCurrentNode(&quot;CANCELLED&quot;); entry.setApproverId(null); this.updateById(entry); saveLog(id, &quot;MINE_ENTRY&quot;, &quot;CANCELLED&quot;, &quot;CANCEL&quot;, UserContext.getUserId(), &quot;取消申请&quot;); &#125; @Override public List&lt;ApprovalLogVO&gt; getApprovalLogs(Long id) &#123; List&lt;ApprovalLog&gt; logs = approvalLogMapper.selectList( new LambdaQueryWrapper&lt;ApprovalLog&gt;() .eq(ApprovalLog::getBizId, id) .eq(ApprovalLog::getBizType, &quot;MINE_ENTRY&quot;) .orderByAsc(ApprovalLog::getCreateTime) ); return logs.stream().map(this::toLogVO).collect(Collectors.toList()); &#125; @Override public PageResult&lt;MineEntryVO&gt; listMyPending(MineEntryQueryDTO query) &#123; Long userId = UserContext.getUserId(); Page&lt;MineEntry&gt; page = new Page&lt;&gt;(query.getPage(), query.getSize()); LambdaQueryWrapper&lt;MineEntry&gt; wrapper = new LambdaQueryWrapper&lt;&gt;(); wrapper.eq(MineEntry::getApproverId, userId) .ne(MineEntry::getStatus, MineEntryStatus.APPROVED) .ne(MineEntry::getStatus, MineEntryStatus.CANCELLED) .orderByAsc(MineEntry::getCreateTime); Page&lt;MineEntry&gt; result = this.page(page, wrapper); return toPageResult(result); &#125; @Override public PageResult&lt;MineEntryVO&gt; listMyApplied(MineEntryQueryDTO query) &#123; Long userId = UserContext.getUserId(); Page&lt;MineEntry&gt; page = new Page&lt;&gt;(query.getPage(), query.getSize()); LambdaQueryWrapper&lt;MineEntry&gt; wrapper = new LambdaQueryWrapper&lt;&gt;(); wrapper.eq(MineEntry::getApplicantId, userId) .orderByDesc(MineEntry::getCreateTime); Page&lt;MineEntry&gt; result = this.page(page, wrapper); return toPageResult(result); &#125; // ============= 私有方法 ============= private Long getLeaderId(Long userId) &#123; User user = userService.getById(userId); if (user == null || user.getLeaderId() == null) &#123; throw new BusinessException(&quot;未配置班组长，请联系管理员&quot;); &#125; return user.getLeaderId(); &#125; private Long getSafetyManagerId() &#123; ApprovalNode node = approvalNodeMapper.selectOne( new LambdaQueryWrapper&lt;ApprovalNode&gt;() .eq(ApprovalNode::getBizType, &quot;MINE_ENTRY&quot;) .eq(ApprovalNode::getNodeCode, &quot;PENDING_SAFETY&quot;) ); if (node == null) &#123; throw new BusinessException(&quot;未配置安全主管审批节点&quot;); &#125; return userService.getByRoleCode(node.getApproverRole()) .stream().findFirst() .orElseThrow(() -&gt; new BusinessException(&quot;未找到安全主管&quot;)) .getId(); &#125; private Long getMineDirectorId() &#123; ApprovalNode node = approvalNodeMapper.selectOne( new LambdaQueryWrapper&lt;ApprovalNode&gt;() .eq(ApprovalNode::getBizType, &quot;MINE_ENTRY&quot;) .eq(ApprovalNode::getNodeCode, &quot;PENDING_DIRECTOR&quot;) ); if (node == null) &#123; throw new BusinessException(&quot;未配置矿长审批节点&quot;); &#125; return userService.getByRoleCode(node.getApproverRole()) .stream().findFirst() .orElseThrow(() -&gt; new BusinessException(&quot;未找到矿长&quot;)) .getId(); &#125; private void saveLog(Long bizId, String bizType, String node, String action, Long operatorId, String comment) &#123; ApprovalLog log = new ApprovalLog(); log.setBizId(bizId); log.setBizType(bizType); log.setNode(node); log.setAction(action); log.setOperatorId(operatorId); log.setOperatorName(userService.getById(operatorId).getRealName()); log.setComment(comment); approvalLogMapper.insert(log); &#125; private void notifyApplicant(Long applicantId, String message) &#123; log.info(&quot;通知申请人: userId=&#123;&#125;, message=&#123;&#125;&quot;, applicantId, message); &#125; private ApprovalLogVO toLogVO(ApprovalLog log) &#123; ApprovalLogVO vo = new ApprovalLogVO(); BeanUtils.copyProperties(log, vo); return vo; &#125;&#125;
Controller层@RestController@RequestMapping(&quot;/mine-entry&quot;)@RequiredArgsConstructor@Tag(name = &quot;下井作业审批&quot;)public class MineEntryController &#123; private final MineEntryService mineEntryService; @Operation(summary = &quot;提交下井申请&quot;) @PostMapping public Result&lt;Void&gt; submit(@RequestBody @Valid MineEntryCreateDTO dto) &#123; mineEntryService.submit(dto); return Result.success(); &#125; @Operation(summary = &quot;审批操作（通过/驳回）&quot;) @PostMapping(&quot;/&#123;id&#125;/approve&quot;) public Result&lt;Void&gt; approve(@PathVariable Long id, @RequestBody @Valid ApprovalDTO dto) &#123; mineEntryService.approve(id, dto); return Result.success(); &#125; @Operation(summary = &quot;重新提交（驳回后修改）&quot;) @PutMapping(&quot;/&#123;id&#125;/resubmit&quot;) public Result&lt;Void&gt; resubmit(@PathVariable Long id, @RequestBody @Valid MineEntryUpdateDTO dto) &#123; mineEntryService.resubmit(id, dto); return Result.success(); &#125; @Operation(summary = &quot;取消申请&quot;) @PutMapping(&quot;/&#123;id&#125;/cancel&quot;) public Result&lt;Void&gt; cancel(@PathVariable Long id) &#123; mineEntryService.cancel(id); return Result.success(); &#125; @Operation(summary = &quot;查询审批日志&quot;) @GetMapping(&quot;/&#123;id&#125;/logs&quot;) public Result&lt;List&lt;ApprovalLogVO&gt;&gt; getLogs(@PathVariable Long id) &#123; return Result.success(mineEntryService.getApprovalLogs(id)); &#125; @Operation(summary = &quot;我的待审批列表&quot;) @GetMapping(&quot;/pending&quot;) public Result&lt;PageResult&lt;MineEntryVO&gt;&gt; listMyPending(MineEntryQueryDTO query) &#123; return Result.success(mineEntryService.listMyPending(query)); &#125; @Operation(summary = &quot;我的申请列表&quot;) @GetMapping(&quot;/applied&quot;) public Result&lt;PageResult&lt;MineEntryVO&gt;&gt; listMyApplied(MineEntryQueryDTO query) &#123; return Result.success(mineEntryService.listMyApplied(query)); &#125;&#125;
DTO与VO设计/** * 下井申请创建DTO */@Datapublic class MineEntryCreateDTO &#123; @NotBlank(message = &quot;申请标题不能为空&quot;) @Size(max = 100, message = &quot;标题最长100字&quot;) private String title; @NotBlank(message = &quot;下井区域不能为空&quot;) private String mineArea; @NotNull(message = &quot;下井日期不能为空&quot;) @JsonFormat(pattern = &quot;yyyy-MM-dd&quot;) private LocalDate entryDate; @NotNull(message = &quot;下井时间不能为空&quot;) @JsonFormat(pattern = &quot;HH:mm&quot;) private LocalTime entryTime; @NotBlank(message = &quot;作业内容不能为空&quot;) @Size(max = 500, message = &quot;作业内容最长500字&quot;) private String workContent; @NotNull(message = &quot;风险等级不能为空&quot;) @Min(value = 1, message = &quot;风险等级最小为1&quot;) @Max(value = 4, message = &quot;风险等级最大为4&quot;) private Integer riskLevel; /** 瓦斯浓度（高风险必填） */ private BigDecimal gasConcentration; /** 通风状态（高风险必填） */ private Integer ventilationStatus;&#125;/** * 审批DTO */@Datapublic class ApprovalDTO &#123; @NotBlank(message = &quot;操作类型不能为空&quot;) @Pattern(regexp = &quot;APPROVE|REJECT&quot;, message = &quot;操作类型只能是APPROVE或REJECT&quot;) private String action; @Size(max = 500, message = &quot;审批意见最长500字&quot;) private String comment;&#125;/** * 下井申请VO */@Data@JsonInclude(JsonInclude.Include.NON_NULL)public class MineEntryVO &#123; @JsonSerialize(using = ToStringSerializer.class) private Long id; private String title; private String applicantName; private String mineArea; private String mineAreaDesc; private LocalDate entryDate; private LocalTime entryTime; private LocalTime exitTime; private String workContent; private Integer riskLevel; private String riskLevelDesc; private BigDecimal gasConcentration; private Integer ventilationStatus; private String ventilationStatusDesc; private MineEntryStatus status; private String statusDesc; private String currentNode; private String approverName; private String rejectReason; @JsonFormat(pattern = &quot;yyyy-MM-dd HH:mm:ss&quot;) private LocalDateTime createTime;&#125;
通用审批服务抽象当项目中有多种审批流程时，可以抽象出通用审批服务： /** * 通用审批服务接口 * 所有审批业务都实现此接口 */public interface ApprovalHandler&lt;T&gt; &#123; /** 获取业务类型 */ String getBizType(); /** 获取下一个审批人 */ Long getNextApproverId(T entity, MineEntryStatus currentStatus); /** 审批通过后的回调 */ default void onApproved(T entity) &#123;&#125; /** 审批驳回后的回调 */ default void onRejected(T entity, String reason) &#123;&#125; /** 保存审批日志 */ void saveApprovalLog(Long bizId, String node, String action, Long operatorId, String comment);&#125;
审批流时序图矿工 班组长 安全主管 矿长 系统 | | | | | |--- 提交申请 -----&gt;| | | | | | | | 记录日志 | | |--- 通过 ---------&gt;| | | | | | | 记录日志 | | | |--- 通过 --------&gt;| | | | | | 记录日志 | | | | |--- 通过 --------&gt;| | | | | | |&lt;------------------ 通知：审批通过 -----| | | | | | | 记录日志 |驳回场景：矿工 班组长 安全主管 矿长 系统 |--- 提交申请 -----&gt;| | | | | |--- 通过 ---------&gt;| | | | | |--- 驳回 --------&gt;| | |&lt;-- 通知：安全主管驳回 -----------------------------------| 记录日志 | |--- 修改后重新提交 &gt;| | | | | |--- 通过 ---------&gt;| | | | | |--- 通过 --------&gt;| | | | | |--- 通过 --------&gt;| |&lt;-- 通知：审批通过 ------------------------------------ | 记录日志 |
状态流转统计SQL-- 审批通过率统计SELECT DATE_FORMAT(create_time, &#x27;%Y-%m&#x27;) AS month, COUNT(*) AS total, SUM(CASE WHEN status = 4 THEN 1 ELSE 0 END) AS approved, SUM(CASE WHEN status = 5 THEN 1 ELSE 0 END) AS rejected, ROUND(SUM(CASE WHEN status = 4 THEN 1 ELSE 0 END) / COUNT(*) * 100, 2) AS approve_rateFROM biz_mine_entryWHERE deleted = 0GROUP BY DATE_FORMAT(create_time, &#x27;%Y-%m&#x27;)ORDER BY month;-- 审批耗时统计SELECT b.biz_id, b.title, TIMESTAMPDIFF(HOUR, (SELECT create_time FROM biz_approval_log WHERE biz_id = b.id AND action = &#x27;SUBMIT&#x27;), (SELECT create_time FROM biz_approval_log WHERE biz_id = b.id AND node = &#x27;APPROVED&#x27;) ) AS total_hoursFROM biz_mine_entry bWHERE b.status = 4;
项目中遇到的问题

前言 在实际场景中，做项目时经常需要把对象转成字符串（存Redis、传接口、写日志），也需要把字符串转回对象。最初我分不清序列化、JSON转换的区别，也踩过serialVersionUID的坑。系统学习后，才搞清楚各种序列化方式的适用场景。 什么是序列化？序列化：将Java对象转换为字节序列（或字符串）反序列化：将字节序列（或字符串）恢复为Java对象 Java对象 → 序列化 → 字节/字符串 → 传输/存储 → 反序列化 → Java对象
Java原生序列化基本用法// 实现Serializable接口public class User implements Serializable &#123; private static final long serialVersionUID = 1L; private Long id; private String name; private transient String password; // transient不参与序列化&#125;// 序列化User user = new User(1L, &quot;张三&quot;, &quot;123456&quot;);ByteArrayOutputStream bos = new ByteArrayOutputStream();try (ObjectOutputStream oos = new ObjectOutputStream(bos)) &#123; oos.writeObject(user);&#125;byte[] bytes = bos.toByteArray();// 反序列化ByteArrayInputStream bis = new ByteArrayInputStream(bytes);try (ObjectInputStream ois = new ObjectInputStream(bis)) &#123; User restored = (User) ois.readObject();&#125;
serialVersionUID// ❌ 不指定serialVersionUIDpublic class User implements Serializable &#123; // 编译器自动生成serialVersionUID // 修改类后serialVersionUID变化，反序列化失败！&#125;// ✅ 显式指定serialVersionUIDpublic class User implements Serializable &#123; private static final long serialVersionUID = 1L; // 修改类后serialVersionUID不变，兼容旧数据&#125;
Java序列化的缺点1. 只能Java使用，跨语言不支持2. 序列化后体积大3. 性能差4. 存在安全风险（反序列化漏洞）5. 无法序列化static和transient字段
JSON序列化Jackson（SpringBoot默认）// 对象 → JSON字符串ObjectMapper mapper = new ObjectMapper();User user = new User(1L, &quot;张三&quot;);String json = mapper.writeValueAsString(user);// &#123;&quot;id&quot;:1,&quot;name&quot;:&quot;张三&quot;&#125;// JSON字符串 → 对象User restored = mapper.readValue(json, User.class);// 集合反序列化List&lt;User&gt; users = mapper.readValue(json, mapper.getTypeFactory().constructCollectionType(List.class, User.class));// Map反序列化Map&lt;String, Object&gt; map = mapper.readValue(json, new TypeReference&lt;Map&lt;String, Object&gt;&gt;() &#123;&#125;);
Jackson常用注解public class User &#123; // 忽略字段 @JsonIgnore private String password; // 字段重命名 @JsonProperty(&quot;user_name&quot;) private String name; // 日期格式 @JsonFormat(pattern = &quot;yyyy-MM-dd HH:mm:ss&quot;, timezone = &quot;GMT+8&quot;) private LocalDateTime createTime; // 序列化时包含非空字段 @JsonInclude(JsonInclude.Include.NON_NULL) private String email; // 反序列化时忽略未知字段 @JsonIgnoreProperties(ignoreUnknown = true) // 自定义序列化 @JsonSerialize(using = BigDecimalSerializer.class) private BigDecimal amount;&#125;
Jackson配置ObjectMapper mapper = new ObjectMapper();// 序列化配置mapper.configure(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS, false);mapper.configure(SerializationFeature.FAIL_ON_EMPTY_BEANS, false);mapper.setSerializationInclusion(JsonInclude.Include.NON_NULL);// 反序列化配置mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);mapper.configure(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT, true);// 日期格式mapper.registerModule(new JavaTimeModule());
Fastjson// 对象 → JSONString json = JSON.toJSONString(user);// JSON → 对象User user = JSON.parseObject(json, User.class);// JSON → ListList&lt;User&gt; users = JSON.parseArray(json, User.class);// Fastjson注解@JSONField(name = &quot;user_name&quot;)private String name;@JSONField(format = &quot;yyyy-MM-dd HH:mm:ss&quot;)private LocalDateTime createTime;@JSONField(serialize = false)private String password;
注意：Fastjson有过安全漏洞，建议使用Jackson。 Redis中的序列化// 方式1：JDK序列化（默认，不推荐）// 存储二进制，可读性差，体积大// 方式2：String序列化redisTemplate.opsForValue().set(&quot;user:1&quot;, JSON.toJSONString(user));User user = JSON.parseObject(redisTemplate.opsForValue().get(&quot;user:1&quot;), User.class);// 方式3：配置RedisTemplate使用Jackson@Configurationpublic class RedisConfig &#123; @Bean public RedisTemplate&lt;String, Object&gt; redisTemplate(RedisConnectionFactory factory) &#123; RedisTemplate&lt;String, Object&gt; template = new RedisTemplate&lt;&gt;(); template.setConnectionFactory(factory); Jackson2JsonRedisSerializer&lt;Object&gt; serializer = new Jackson2JsonRedisSerializer&lt;&gt;(Object.class); ObjectMapper mapper = new ObjectMapper(); mapper.setVisibility(PropertyAccessor.ALL, JsonAutoDetect.Visibility.ANY); mapper.activateDefaultTyping(mapper.getPolymorphicTypeValidator(), ObjectMapper.DefaultTyping.NON_FINAL); serializer.setObjectMapper(mapper); template.setKeySerializer(new StringRedisSerializer()); template.setValueSerializer(serializer); template.setHashKeySerializer(new StringRedisSerializer()); template.setHashValueSerializer(serializer); return template; &#125;&#125;
序列化的常见坑1. 循环引用// ❌ 双向关联导致循环引用public class User &#123; private List&lt;Order&gt; orders;&#125;public class Order &#123; private User user; // 循环引用！&#125;// Jackson解决方案@JsonManagedReferenceprivate List&lt;Order&gt; orders;@JsonBackReferenceprivate User user;
2. 日期格式// ❌ 日期序列化为时间戳// &#123;&quot;createTime&quot;: 1659523200000&#125;// ✅ 指定格式@JsonFormat(pattern = &quot;yyyy-MM-dd HH:mm:ss&quot;)private LocalDateTime createTime;// &#123;&quot;createTime&quot;: &quot;2022-08-03 10:00:00&quot;&#125;
3. Long精度丢失// ❌ JavaScript中Long超过16位会丢失精度// &#123;&quot;id&quot;: 1234567890123456789&#125; → JS中变成 1234567890123456800// ✅ Long序列化为String@JsonSerialize(using = ToStringSerializer.class)private Long id;
4. 枚举序列化// 默认序列化为枚举名称// &#123;&quot;status&quot;: &quot;ENABLED&quot;&#125;// ✅ 序列化为codepublic enum UserStatus &#123; DISABLED(0), ENABLED(1); @EnumValue private final int code; @JsonValue // Jackson序列化时使用code public int getCode() &#123; return code; &#125;&#125;// &#123;&quot;status&quot;: 1&#125;
序列化方式对比
方式 跨语言 体积 性能 可读性 适用场景
Java序列化 否 大 差 差 不推荐
JSON 是 中 中 好 接口、存储
Protobuf 是 小 好 差 RPC通信
Hessian 是 中 中 差 Dubbo
总结 序列化是对象与数据之间的桥梁。从”只会toString”到”熟练使用JSON序列化”核心认知是：JSON是日常开发的通用序列化方案，Jackson是Java生态的最佳选择*掌握Jackson的注解和配置，能解决90%的序列化问题。

前言
实际场景中，几乎每个管理模块都有导入导出需求：导出设备台账、导入巡检记录、导出告警统计、导入人员信息等。最初用Apache POI导出，数据量超过5万行就OOM。后来切换到EasyExcel，10万行数据导出也不会内存溢出，导入也支持逐行解析校验。
本文以实际项目为背景，从EasyExcel基础讲起，深入大数据量导入导出、模板导出、校验反馈等实战场景。
项目背景智慧矿山系统 - 导入导出场景

模块         |  导出功能              |  导入功能
————–+———————–+————————
设备管理     |  设备台账导出(5万+)     |  批量导入设备
人员管理     |  人员花名册导出(3万+)   |  批量导入矿工信息
巡检管理     |  巡检记录导出(10万+)    |  导入巡检模板
告警管理     |  告警统计导出(20万+)    |  导入告警阈值配置
物资管理     |  物资清单导出(2万+)     |  批量导入物资

POI vs EasyExcel内存模式         |  全量加载到内存   |  SAX逐行解析

对比项           |  Apache POI      |  EasyExcel
10万行内存占用   |  约2GB(OOM)      |  约50MB
API复杂度        |  复杂             |  简洁(注解驱动)
大文件导出       |  容易OOM          |  流式写入不OOM
大文件导入       |  全量加载慢       |  逐行解析快
自定义样式       |  支持             |  支持
合并单元格       |  支持             |  支持
模板导出         |  支持             |  支持
开源方           |  Apache           |  阿里
内存模型对比：
POI:     [10万行全部加载到内存] -&gt; 处理 -&gt; 写出    &lt;- OOM风险
EasyExcel: [逐行读取] -&gt; 处理 -&gt; [逐行写出]       &lt;- 内存恒定

EasyExcel基础依赖&lt;dependency&gt;    &lt;groupId&gt;com.alibaba&lt;/groupId&gt;    &lt;artifactId&gt;easyexcel&lt;/artifactId&gt;    &lt;version&gt;3.1.1&lt;/version&gt;&lt;/dependency&gt;

导出VO@Datapublic class DeviceExportVO &#123;    @ExcelProperty(&quot;设备编号&quot;)    private String deviceCode;    @ExcelProperty(&quot;设备名称&quot;)    private String deviceName;    @ExcelProperty(&quot;设备类型&quot;)    private String deviceTypeDesc;    @ExcelProperty(&quot;安装位置&quot;)    private String location;    @ExcelProperty(&quot;运行状态&quot;)    private String statusDesc;    @ExcelProperty(&quot;健康评分&quot;)    private Integer healthScore;    @ExcelProperty(&quot;负责人&quot;)    private String managerName;    @ExcelProperty(value = &quot;投用日期&quot;)    @DateTimeFormat(&quot;yyyy-MM-dd&quot;)    private LocalDate commissionDate;    @ExcelProperty(value = &quot;最后巡检时间&quot;)    @DateTimeFormat(&quot;yyyy-MM-dd HH:mm:ss&quot;)    private LocalDateTime lastInspectTime;&#125;

基础导出@Operation(summary = &quot;导出设备台账&quot;)@GetMapping(&quot;/device/export&quot;)public void exportDevice(DeviceQueryDTO query, HttpServletResponse response) throws IOException &#123;    // 1. 设置响应头    response.setContentType(&quot;application/vnd.openxmlformats-officedocument.spreadsheetml.sheet&quot;);    response.setHeader(&quot;Content-Disposition&quot;,        &quot;attachment; filename=&quot; + URLEncoder.encode(&quot;设备台账.xlsx&quot;, &quot;UTF-8&quot;));  // 解决问题#4    // 2. 查询数据    List&lt;DeviceExportVO&gt; list = deviceService.listForExport(query);    // 3. 写入Excel    EasyExcel.write(response.getOutputStream(), DeviceExportVO.class)        .sheet(&quot;设备台账&quot;)        .doWrite(list);&#125;

Service@Overridepublic List&lt;DeviceExportVO&gt; listForExport(DeviceQueryDTO query) &#123;    LambdaQueryWrapper&lt;Device&gt; wrapper = new LambdaQueryWrapper&lt;&gt;();    if (StringUtils.isNotBlank(query.getKeyword())) &#123;        wrapper.and(w -&gt; w.like(Device::getDeviceCode, query.getKeyword())            .or().like(Device::getDeviceName, query.getKeyword()));    &#125;    if (query.getDeviceType() != null) &#123;        wrapper.eq(Device::getDeviceType, query.getDeviceType());    &#125;    wrapper.eq(Device::getDeleted, 0).orderByDesc(Device::getCreateTime);    List&lt;Device&gt; devices = this.list(wrapper);    return devices.stream().map(device -&gt; &#123;        DeviceExportVO vo = new DeviceExportVO();        BeanUtils.copyProperties(device, vo);        vo.setDeviceTypeDesc(device.getDeviceType().getDesc());        vo.setStatusDesc(device.getStatus().getDesc());        vo.setManagerName(getManagerName(device.getManagerId()));        return vo;    &#125;).collect(Collectors.toList());&#125;

大数据量导出分批查询写入传统方式（OOM风险）：+--------+     +----------+     +--------+| 查全量  | -&gt; | 全在内存中 | -&gt; | 一次写出 || 10万条  |     | 10万对象  |     |        |+--------+     +----------+     +--------+EasyExcel分批写入（内存恒定）：+--------+     +--------+     +--------+| 查第1批 | -&gt; | 写入   | -&gt; | 释放    || 5000条  |     | Excel  |     | 内存    |+--------+     +--------+     +--------++--------+     +--------+     +--------+| 查第2批 | -&gt; | 追加写  | -&gt; | 释放    || 5000条  |     | Excel  |     | 内存    |+--------+     +--------+     +--------+...重复直到全部写完

/** * 大数据量导出（解决问题#1） */@Overridepublic void exportLargeDevice(DeviceQueryDTO query, HttpServletResponse response) throws IOException &#123;    response.setContentType(&quot;application/vnd.openxmlformats-officedocument.spreadsheetml.sheet&quot;);    response.setHeader(&quot;Content-Disposition&quot;,        &quot;attachment; filename=&quot; + URLEncoder.encode(&quot;设备台账.xlsx&quot;, &quot;UTF-8&quot;));    int batchSize = 5000;    int page = 1;    try (ExcelWriter writer = EasyExcel.write(response.getOutputStream(), DeviceExportVO.class).build()) &#123;        WriteSheet sheet = EasyExcel.writerSheet(&quot;设备台账&quot;).build();        List&lt;DeviceExportVO&gt; batch;        do &#123;            // 分批查询            batch = queryPage(page++, batchSize, query);            if (!batch.isEmpty()) &#123;                writer.write(batch, sheet);            &#125;        &#125; while (batch.size() == batchSize);    &#125;&#125;private List&lt;DeviceExportVO&gt; queryPage(int page, int size, DeviceQueryDTO query) &#123;    Page&lt;Device&gt; pageParam = new Page&lt;&gt;(page, size);    LambdaQueryWrapper&lt;Device&gt; wrapper = buildWrapper(query);    Page&lt;Device&gt; result = deviceMapper.selectPage(pageParam, wrapper);    return result.getRecords().stream().map(this::toExportVO).collect(Collectors.toList());&#125;

异步导出/** * 异步导出（解决问题#6 #15） */@Overridepublic String asyncExport(DeviceQueryDTO query) &#123;    Long userId = UserContext.getUserId();    // 1. 检查并发导出数量    String countKey = &quot;mine:export:concurrent:&quot; + userId;    Long concurrent = redisTemplate.opsForValue().increment(countKey);    redisTemplate.expire(countKey, 1, TimeUnit.HOURS);    if (concurrent &gt; 3) &#123;        redisTemplate.opsForValue().decrement(countKey);        throw new BusinessException(&quot;同时导出任务不能超过3个，请稍后再试&quot;);    &#125;    // 2. 生成导出任务ID    String taskId = IdUtil.simpleUUID();    // 3. 异步执行导出    CompletableFuture.runAsync(() -&gt; &#123;        try &#123;            String filePath = &quot;/data/export/&quot; + taskId + &quot;.xlsx&quot;;            try (ExcelWriter writer = EasyExcel.write(filePath, DeviceExportVO.class).build()) &#123;                WriteSheet sheet = EasyExcel.writerSheet(&quot;设备台账&quot;).build();                int page = 1;                List&lt;DeviceExportVO&gt; batch;                do &#123;                    batch = queryPage(page++, 5000, query);                    if (!batch.isEmpty()) &#123;                        writer.write(batch, sheet);                    &#125;                &#125; while (batch.size() == 5000);            &#125;            // 更新任务状态            ExportTask task = new ExportTask();            task.setId(taskId);            task.setStatus(ExportStatus.COMPLETED);            task.setFilePath(filePath);            exportTaskMapper.updateById(task);        &#125; catch (Exception e) &#123;            log.error(&quot;异步导出失败: taskId=&#123;&#125;&quot;, taskId, e);            ExportTask task = new ExportTask();            task.setId(taskId);            task.setStatus(ExportStatus.FAILED);            exportTaskMapper.updateById(task);        &#125; finally &#123;            redisTemplate.opsForValue().decrement(countKey);        &#125;    &#125;, exportExecutor);    // 4. 记录导出任务    ExportTask task = new ExportTask();    task.setId(taskId);    task.setUserId(userId);    task.setFileName(&quot;设备台账.xlsx&quot;);    task.setStatus(ExportStatus.PROCESSING);    task.setCreateTime(LocalDateTime.now());    exportTaskMapper.insert(task);    return taskId;&#125;/** * 查询导出任务状态 */@Overridepublic ExportTaskVO getExportTask(String taskId) &#123;    ExportTask task = exportTaskMapper.selectById(taskId);    if (task == null) &#123;        throw new BusinessException(&quot;导出任务不存在&quot;);    &#125;    ExportTaskVO vo = new ExportTaskVO();    BeanUtils.copyProperties(task, vo);    return vo;&#125;/** * 下载导出文件 */@GetMapping(&quot;/download/&#123;taskId&#125;&quot;)public void downloadExport(@PathVariable String taskId, HttpServletResponse response) throws IOException &#123;    ExportTask task = exportTaskService.getExportTask(taskId);    if (task.getStatus() != ExportStatus.COMPLETED) &#123;        throw new BusinessException(&quot;导出任务未完成&quot;);    &#125;    File file = new File(task.getFilePath());    response.setContentType(&quot;application/octet-stream&quot;);    response.setHeader(&quot;Content-Disposition&quot;,        &quot;attachment; filename=&quot; + URLEncoder.encode(task.getFileName(), &quot;UTF-8&quot;));    try (InputStream is = new FileInputStream(file);         OutputStream os = response.getOutputStream()) &#123;        IOUtils.copy(is, os);    &#125;&#125;

导入实战导入DTO@Datapublic class DeviceImportDTO &#123;    @ExcelProperty(&quot;设备编号&quot;)    private String deviceCode;    @ExcelProperty(&quot;设备名称&quot;)    private String deviceName;    @ExcelProperty(&quot;设备类型&quot;)    private String deviceType;    // 通风机/排水泵/输送带/掘进机    @ExcelProperty(&quot;安装位置&quot;)    private String location;    @ExcelProperty(&quot;负责人工号&quot;)    private String managerCode;    @ExcelProperty(&quot;投用日期&quot;)    @DateTimeFormat(&quot;yyyy-MM-dd&quot;)    private LocalDate commissionDate;&#125;

导入监听器@Slf4jpublic class DeviceImportListener extends AnalysisEventListener&lt;DeviceImportDTO&gt; &#123;    private final DeviceService deviceService;    private final List&lt;DeviceImportDTO&gt; successList = new ArrayList&lt;&gt;();    private final List&lt;ImportError&gt; errorList = new ArrayList&lt;&gt;();    private int total = 0;    private int successCount = 0;    public DeviceImportListener(DeviceService deviceService) &#123;        this.deviceService = deviceService;    &#125;    @Override    public void invoke(DeviceImportDTO data, AnalysisContext context) &#123;        total++;        int rowNum = context.readRowHolder().getRowIndex() + 1;        // 跳过空行（解决问题#12）        if (isEmptyRow(data)) &#123;            return;        &#125;        // 校验数据        String error = validate(data, rowNum);        if (error != null) &#123;            errorList.add(new ImportError(rowNum, error));            return;        &#125;        successList.add(data);        // 每500条批量保存（解决问题#3）        if (successList.size() &gt;= 500) &#123;            saveBatch();        &#125;    &#125;    @Override    public void doAfterAllAnalysed(AnalysisContext context) &#123;        if (!successList.isEmpty()) &#123;            saveBatch();        &#125;        log.info(&quot;导入完成: 总数=&#123;&#125;, 成功=&#123;&#125;, 失败=&#123;&#125;&quot;,            total, successCount, errorList.size());    &#125;    /**     * 数据校验（解决问题#2 #7 #9 #11）     */    private String validate(DeviceImportDTO data, int rowNum) &#123;        // 必填校验        if (StringUtils.isBlank(data.getDeviceCode())) &#123;            return &quot;第&quot; + rowNum + &quot;行：设备编号不能为空&quot;;        &#125;        if (StringUtils.isBlank(data.getDeviceName())) &#123;            return &quot;第&quot; + rowNum + &quot;行：设备名称不能为空&quot;;        &#125;        // 唯一性校验（解决问题#9）        if (deviceService.existsByCode(data.getDeviceCode())) &#123;            return &quot;第&quot; + rowNum + &quot;行：设备编号&quot; + data.getDeviceCode() + &quot;已存在&quot;;        &#125;        // 设备类型校验        if (StringUtils.isNotBlank(data.getDeviceType())) &#123;            try &#123;                DeviceType.valueOf(data.getDeviceType());            &#125; catch (IllegalArgumentException e) &#123;                return &quot;第&quot; + rowNum + &quot;行：设备类型&quot; + data.getDeviceType() + &quot;不合法&quot;;            &#125;        &#125;        // 日期格式校验（解决问题#11）        if (data.getCommissionDate() != null &amp;&amp; data.getCommissionDate().isAfter(LocalDate.now())) &#123;            return &quot;第&quot; + rowNum + &quot;行：投用日期不能晚于当前日期&quot;;        &#125;        return null;    &#125;    private void saveBatch() &#123;        try &#123;            deviceService.importDevices(successList);            successCount += successList.size();        &#125; catch (Exception e) &#123;            log.error(&quot;批量导入失败&quot;, e);            errorList.add(new ImportError(0, &quot;批量保存失败: &quot; + e.getMessage()));        &#125;        successList.clear();    &#125;    private boolean isEmptyRow(DeviceImportDTO data) &#123;        return StringUtils.isBlank(data.getDeviceCode())            &amp;&amp; StringUtils.isBlank(data.getDeviceName())            &amp;&amp; StringUtils.isBlank(data.getLocation());    &#125;    public ImportResult getResult() &#123;        return new ImportResult(total, successCount, errorList.size(), errorList);    &#125;&#125;

导入Controller@Operation(summary = &quot;导入设备&quot;)@PostMapping(&quot;/device/import&quot;)public Result&lt;ImportResult&gt; importDevices(@RequestParam(&quot;file&quot;) MultipartFile file) throws IOException &#123;    // 1. 校验文件类型    String originalName = file.getOriginalFilename();    if (originalName == null || (!originalName.endsWith(&quot;.xlsx&quot;) &amp;&amp; !originalName.endsWith(&quot;.xls&quot;))) &#123;        return Result.fail(&quot;请上传Excel文件（.xlsx或.xls）&quot;);    &#125;    // 2. 校验文件大小（最大10MB）    if (file.getSize() &gt; 10 * 1024 * 1024) &#123;        return Result.fail(&quot;文件大小不能超过10MB&quot;);    &#125;    // 3. 读取并校验    DeviceImportListener listener = new DeviceImportListener(deviceService);    EasyExcel.read(file.getInputStream(), DeviceImportDTO.class, listener).sheet().doRead();    // 4. 返回导入结果（解决问题#14）    return Result.success(listener.getResult());&#125;

导入结果@Data@AllArgsConstructor@NoArgsConstructorpublic class ImportResult &#123;    private int total;              // 总数    private int success;            // 成功数    private int fail;               // 失败数    private List&lt;ImportError&gt; errors;  // 失败详情&#125;@Data@AllArgsConstructor@NoArgsConstructorpublic class ImportError &#123;    private int rowNum;             // 行号（0表示批量错误）    private String message;         // 错误信息&#125;

模板下载/** * 下载导入模板（解决问题#5） */@GetMapping(&quot;/device/template&quot;)public void downloadTemplate(HttpServletResponse response) throws IOException &#123;    response.setContentType(&quot;application/vnd.openxmlformats-officedocument.spreadsheetml.sheet&quot;);    response.setHeader(&quot;Content-Disposition&quot;,        &quot;attachment; filename=&quot; + URLEncoder.encode(&quot;设备导入模板.xlsx&quot;, &quot;UTF-8&quot;));    // 写空数据，只输出表头    EasyExcel.write(response.getOutputStream(), DeviceImportDTO.class)        .sheet(&quot;设备数据&quot;)        .doWrite(Collections.emptyList());&#125;

自定义样式/** * 导出样式策略（解决问题#8） */public class MineExportStyleHandler extends AbstractCellStyleStrategy &#123;    @Override    protected void setHeadCellStyle(CellWriteHandlerContext context) &#123;        CellStyle cellStyle = context.getFirstCellData().getOrCreateStyle();        // 表头：灰色背景 + 加粗 + 居中        cellStyle.setFillForegroundColor(IndexedColors.GREY_25_PERCENT.getIndex());        cellStyle.setAlignment(HorizontalAlignment.CENTER);        cellStyle.setVerticalAlignment(VerticalAlignment.CENTER);        cellStyle.setBorderBottom(BorderStyle.THIN);        cellStyle.setBorderLeft(BorderStyle.THIN);        cellStyle.setBorderRight(BorderStyle.THIN);        cellStyle.setBorderTop(BorderStyle.THIN);        Workbook workbook = context.getWriteSheetHolder().getSheet().getWorkbook();        Font font = workbook.createFont();        font.setBold(true);        font.setFontHeightInPoints((short) 11);        cellStyle.setFont(font);    &#125;    @Override    protected void setContentCellStyle(CellWriteHandlerContext context) &#123;        CellStyle cellStyle = context.getFirstCellData().getOrCreateStyle();        // 内容：白色背景 + 边框        cellStyle.setFillForegroundColor(IndexedColors.WHITE.getIndex());        cellStyle.setVerticalAlignment(VerticalAlignment.CENTER);        cellStyle.setBorderBottom(BorderStyle.THIN);        cellStyle.setBorderLeft(BorderStyle.THIN);        cellStyle.setBorderRight(BorderStyle.THIN);        cellStyle.setBorderTop(BorderStyle.THIN);    &#125;&#125;// 使用EasyExcel.write(response.getOutputStream(), DeviceExportVO.class)    .registerWriteHandler(new MineExportStyleHandler())    .sheet(&quot;设备台账&quot;)    .doWrite(dataList);

导出数据脱敏/** * 导出数据脱敏（解决问题#10） */@Datapublic class PersonExportVO &#123;    @ExcelProperty(&quot;姓名&quot;)    private String realName;    @ExcelProperty(&quot;手机号&quot;)    private String phone;  // 脱敏后：138****8000    @ExcelProperty(&quot;身份证号&quot;)    private String idCard;  // 脱敏后：110101****1234    @ExcelProperty(&quot;工号&quot;)    private String employeeNo;    @ExcelProperty(&quot;部门&quot;)    private String deptName;    @ExcelProperty(&quot;岗位&quot;)    private String positionName;&#125;// Service层脱敏public List&lt;PersonExportVO&gt; listForExport(PersonQueryDTO query) &#123;    List&lt;User&gt; users = this.list(buildWrapper(query));    return users.stream().map(user -&gt; &#123;        PersonExportVO vo = new PersonExportVO();        vo.setRealName(user.getRealName());        vo.setPhone(MaskUtil.maskPhone(AESUtil.decrypt(user.getPhone())));  // 解密+脱敏        vo.setIdCard(MaskUtil.maskIdCard(AESUtil.decrypt(user.getIdCard()))); // 解密+脱敏        vo.setEmployeeNo(user.getEmployeeNo());        vo.setDeptName(getDeptName(user.getDeptId()));        vo.setPositionName(getPositionName(user.getPositionId()));        return vo;    &#125;).collect(Collectors.toList());&#125;

多Sheet导出/** * 多Sheet导出（解决问题#13） */@GetMapping(&quot;/report/export&quot;)public void exportReport(HttpServletResponse response) throws IOException &#123;    response.setContentType(&quot;application/vnd.openxmlformats-officedocument.spreadsheetml.sheet&quot;);    response.setHeader(&quot;Content-Disposition&quot;,        &quot;attachment; filename=&quot; + URLEncoder.encode(&quot;矿山综合报表.xlsx&quot;, &quot;UTF-8&quot;));    try (ExcelWriter writer = EasyExcel.write(response.getOutputStream()).build()) &#123;        // Sheet1: 设备台账        WriteSheet sheet1 = EasyExcel.writerSheet(0, &quot;设备台账&quot;)            .head(DeviceExportVO.class).build();        writer.write(deviceService.listForExport(new DeviceQueryDTO()), sheet1);        // Sheet2: 人员花名册        WriteSheet sheet2 = EasyExcel.writerSheet(1, &quot;人员花名册&quot;)            .head(PersonExportVO.class).build();        writer.write(personService.listForExport(new PersonQueryDTO()), sheet2);        // Sheet3: 告警统计        WriteSheet sheet3 = EasyExcel.writerSheet(2, &quot;告警统计&quot;)            .head(AlarmExportVO.class).build();        writer.write(alarmService.listForExport(new AlarmQueryDTO()), sheet3);    &#125;&#125;

动态表头导出/** * 动态表头导出（按用户选择导出列） */@GetMapping(&quot;/device/export/dynamic&quot;)public void exportDynamic(@RequestParam List&lt;String&gt; columns,                          HttpServletResponse response) throws IOException &#123;    response.setContentType(&quot;application/vnd.openxmlformats-officedocument.spreadsheetml.sheet&quot;);    response.setHeader(&quot;Content-Disposition&quot;,        &quot;attachment; filename=&quot; + URLEncoder.encode(&quot;设备台账.xlsx&quot;, &quot;UTF-8&quot;));    // 根据选择列构建表头    List&lt;List&lt;String&gt;&gt; headList = columns.stream()        .map(Collections::singletonList)        .collect(Collectors.toList());    // 查询数据    List&lt;Device&gt; devices = deviceService.list();    List&lt;List&lt;Object&gt;&gt; dataList = devices.stream()        .map(device -&gt; toDynamicRow(device, columns))        .collect(Collectors.toList());    EasyExcel.write(response.getOutputStream())        .head(headList)        .sheet(&quot;设备台账&quot;)        .doWrite(dataList);&#125;private List&lt;Object&gt; toDynamicRow(Device device, List&lt;String&gt; columns) &#123;    List&lt;Object&gt; row = new ArrayList&lt;&gt;();    for (String column : columns) &#123;        switch (column) &#123;            case &quot;deviceCode&quot; -&gt; row.add(device.getDeviceCode());            case &quot;deviceName&quot; -&gt; row.add(device.getDeviceName());            case &quot;location&quot; -&gt; row.add(device.getLocation());            case &quot;status&quot; -&gt; row.add(device.getStatus().getDesc());            // ...            default -&gt; row.add(&quot;&quot;);        &#125;    &#125;    return row;&#125;

导入导出工具类封装/** * EasyExcel工具类 */public class EasyExcelUtil &#123;    /**     * 同步导出     */    public static &lt;T&gt; void export(HttpServletResponse response, String fileName,                                   String sheetName, Class&lt;T&gt; clazz, List&lt;T&gt; data) &#123;        try &#123;            response.setContentType(&quot;application/vnd.openxmlformats-officedocument.spreadsheetml.sheet&quot;);            response.setHeader(&quot;Content-Disposition&quot;,                &quot;attachment; filename=&quot; + URLEncoder.encode(fileName, &quot;UTF-8&quot;));            EasyExcel.write(response.getOutputStream(), clazz)                .registerWriteHandler(new MineExportStyleHandler())                .sheet(sheetName)                .doWrite(data);        &#125; catch (IOException e) &#123;            throw new BusinessException(&quot;导出失败: &quot; + e.getMessage());        &#125;    &#125;    /**     * 下载导入模板     */    public static &lt;T&gt; void downloadTemplate(HttpServletResponse response,                                             String fileName, Class&lt;T&gt; clazz, String sheetName) &#123;        try &#123;            response.setContentType(&quot;application/vnd.openxmlformats-officedocument.spreadsheetml.sheet&quot;);            response.setHeader(&quot;Content-Disposition&quot;,                &quot;attachment; filename=&quot; + URLEncoder.encode(fileName, &quot;UTF-8&quot;));            EasyExcel.write(response.getOutputStream(), clazz)                .sheet(sheetName)                .doWrite(Collections.emptyList());        &#125; catch (IOException e) &#123;            throw new BusinessException(&quot;模板下载失败: &quot; + e.getMessage());        &#125;    &#125;&#125;


总结导入导出是项目每个管理模块的标配功能。从POI到EasyExcel，核心认知是：大数据量必须用流式处理，EasyExcel的SAX模式是最佳选择。
关键收获：

EasyExcel流式写入不会OOM，分批查询+写入是大数据量导出的标准方案
导入监听器逐行校验+分批保存，既保证数据质量又避免大事务
导入结果必须返回详细错误信息（行号+原因），用户体验才好
导出敏感数据必须脱敏，不能明文导出手机号&#x2F;身份证
异步导出+限制并发是大数据量场景的必要保障

前言
在实际场景中，新手阶段我写异常处理的典型方式：整个方法体包一个try-catch(Exception e)，然后e.printStackTrace()完事。直到线上出了问题，日志里只有一行堆栈，完全不知道业务上下文，排查了整整一天。从那以后，我开始认真对待异常处理。
Java异常体系Throwable├── Error（严重错误，不应捕获）│   ├── OutOfMemoryError│   ├── StackOverflowError│   └── NoClassDefFoundError└── Exception（可以捕获处理）    ├── 受检异常（Checked Exception）    │   ├── IOException    │   ├── SQLException    │   └── ClassNotFoundException    └── 非受检异常（RuntimeException）        ├── NullPointerException        ├── IndexOutOfBoundsException        ├── ClassCastException        └── IllegalArgumentException

受检 vs 非受检// 受检异常：编译器强制要求处理public void readFile() throws IOException &#123;    FileReader reader = new FileReader(&quot;data.txt&quot;);  // 必须处理或抛出&#125;// 非受检异常：编译器不强制要求处理public void divide(int a, int b) &#123;    int result = a / b;  // ArithmeticException，编译器不管&#125;

常见的异常处理反模式反模式1：吞掉异常// ❌ 最差写法：捕获后什么都不做try &#123;    userMapper.insert(user);&#125; catch (Exception e) &#123;    // 静默忽略，数据没入库也不知道&#125;

反模式2：只打印堆栈// ❌ 只打印堆栈，没有业务上下文try &#123;    orderService.createOrder(dto);&#125; catch (Exception e) &#123;    e.printStackTrace();  // 输出到System.err，生产环境可能丢失&#125;

反模式3：捕获范围过大// ❌ 一个catch包住所有异常try &#123;    String name = user.getName();    int age = Integer.parseInt(name);    orderService.createOrder(dto);    emailService.sendNotify(user.getEmail());&#125; catch (Exception e) &#123;    // 哪一步出错了？不知道    e.printStackTrace();&#125;

反模式4：在循环中频繁try-catch// ❌ 循环中每次都try-catchfor (String id : idList) &#123;    try &#123;        User user = userService.getById(Long.valueOf(id));        // 处理逻辑    &#125; catch (Exception e) &#123;        e.printStackTrace();    &#125;&#125;

正确的异常处理姿势1. 精准捕获，分别处理try &#123;    User user = userService.getById(userId);    if (user == null) &#123;        throw new BusinessException(&quot;用户不存在&quot;);    &#125;    orderService.createOrder(user, dto);&#125; catch (BusinessException e) &#123;    log.warn(&quot;业务异常: userId=&#123;&#125;, msg=&#123;&#125;&quot;, userId, e.getMessage());    return Result.fail(e.getMessage());&#125; catch (NumberFormatException e) &#123;    log.error(&quot;参数格式错误: userId=&#123;&#125;&quot;, userId, e);    return Result.fail(&quot;参数格式错误&quot;);&#125; catch (Exception e) &#123;    log.error(&quot;系统异常: userId=&#123;&#125;&quot;, userId, e);    return Result.fail(&quot;系统繁忙&quot;);&#125;

2. 使用日志框架代替printStackTrace// ❌ printStackTrace输出到stderr，生产环境不可控e.printStackTrace();// ✅ 使用日志框架，输出到文件，带上下文log.error(&quot;创建订单失败: userId=&#123;&#125;, orderId=&#123;&#125;&quot;, userId, orderId, e);

3. 自定义业务异常// 业务异常基类public class BusinessException extends RuntimeException &#123;    private int code;    public BusinessException(String message) &#123;        super(message);        this.code = 500;    &#125;    public BusinessException(int code, String message) &#123;        super(message);        this.code = code;    &#125;&#125;// 特定业务异常public class UserNotFoundException extends BusinessException &#123;    public UserNotFoundException(Long userId) &#123;        super(404, &quot;用户不存在: &quot; + userId);    &#125;&#125;public class OrderCreateException extends BusinessException &#123;    public OrderCreateException(String reason) &#123;        super(500, &quot;订单创建失败: &quot; + reason);    &#125;&#125;

4. 全局异常处理@RestControllerAdvicepublic class GlobalExceptionHandler &#123;    @ExceptionHandler(BusinessException.class)    public Result&lt;?&gt; handleBusiness(BusinessException e) &#123;        log.warn(&quot;业务异常: &#123;&#125;&quot;, e.getMessage());        return Result.fail(e.getCode(), e.getMessage());    &#125;    @ExceptionHandler(MethodArgumentNotValidException.class)    public Result&lt;&gt; handleValidation(MethodArgumentNotValidException e) &#123;        String msg = e.getBindingResult().getFieldErrors().stream()            .map(fe -&gt; fe.getField() + &quot;: &quot; + fe.getDefaultMessage())            .collect(Collectors.joining(&quot;; &quot;));        return Result.fail(400, msg);    &#125;    @ExceptionHandler(Exception.class)    public Result&lt;&gt; handleException(Exception e) &#123;        log.error(&quot;系统异常&quot;, e);        return Result.fail(500, &quot;系统繁忙，请稍后重试&quot;);    &#125;&#125;

5. try-with-resources// ❌ 手动关闭资源BufferedReader reader = null;try &#123;    reader = new BufferedReader(new FileReader(&quot;data.txt&quot;));    String line = reader.readLine();&#125; catch (IOException e) &#123;    log.error(&quot;读取文件失败&quot;, e);&#125; finally &#123;    if (reader != null) &#123;        try &#123;            reader.close();        &#125; catch (IOException e) &#123;            log.error(&quot;关闭流失败&quot;, e);        &#125;    &#125;&#125;// ✅ try-with-resources自动关闭try (BufferedReader reader = new BufferedReader(new FileReader(&quot;data.txt&quot;))) &#123;    String line = reader.readLine();&#125; catch (IOException e) &#123;    log.error(&quot;读取文件失败&quot;, e);&#125;

异常处理的最佳实践
能不用异常就不用：参数校验用if判断，不要用异常控制流程
精准捕获：不要catch Exception，捕获具体的异常类型
不要吞异常：至少记录日志
日志带上下文：记录关键业务参数，方便排查
自定义业务异常：区分系统异常和业务异常
全局异常处理：统一返回格式，避免到处try-catch
受检异常慎重使用：过多的受检异常会导致代码臃肿

总结
异常处理是是重要的学习领域。从”try-catch大法好”到精准捕获、自定义异常、全局处理，核心认知的转变是：**异常处理不是为了”让程序不报错”，而是为了”让错误可追溯、可定位、可恢复”***好的异常处理，是线上排查问题的第一道防线。
总结异常处理是是重要的学习领域。从”try-catch大法好”到精准捕获、自定义异常、全局处理，核心认知的转变是：异常处理不是为了”让程序不报错”，而是为了”让错误可追溯、可定位、可恢复”。好的异常处理，是线上排查问题的第一道防线。

前言 在实际场景中，”抽象类和接口有什么区别？”——这是面试必考题，但实际开发中真正让人纠结的是：这个场景到底该用抽象类还是接口？ 通过实践总结出一套简单实用的判断标准。 核心区别一览
维度 抽象类 接口
关键字 abstract class interface
实例化 不能 不能
构造方法 ✅ 可以有 ❌ 不能有
成员变量 任意类型 public static final 常量
方法 抽象+具体 抽象+default+static
访问修饰符 任意 public（默认）
多继承 单继承 多实现
设计语义 is-a（是什么） can-do（能做什么）
JDK8&#x2F;9&#x2F;11 接口的变化public interface UserService &#123; // JDK8之前：只能有抽象方法 User getUser(Long id); // JDK8：default方法，提供默认实现 default User getOrCreate(Long id) &#123; User user = getUser(id); return user != null user : createDefault(id); &#125; // JDK8：static方法 static User createDefault(Long id) &#123; User user = new User(); user.setId(id); return user; &#125; // JDK9：private方法，供default方法复用 // private void validateId(Long id) &#123; ... &#125;&#125;
接口越来越”像”抽象类了，但本质区别不变：接口没有状态（成员变量），抽象类有。
判断标准：三问法第一问：有没有公共状态？ 有公共字段&#x2F;状态 → 抽象类 只定义行为，无状态 → 接口
// ✅ 抽象类：有公共状态public abstract class BaseEntity &#123; private Long id; private LocalDateTime createTime;&#125;// ✅ 接口：只定义行为public interface Serializable &#123; // 无状态，只标记能力&#125;
第二问：有没有模板逻辑？ 有公共流程骨架，子类填充细节 → 抽象类 各实现独立，无公共流程 → 接口
// ✅ 抽象类：模板方法模式public abstract class AbstractImporter &#123; public final void importData(File file) &#123; validate(file); // 子类实现 parse(file); // 子类实现 save(); // 公共逻辑 &#125; protected abstract void validate(File file); protected abstract void parse(File file); private void save() &#123; /* 公共保存逻辑 */ &#125;&#125;// ✅ 接口：各实现独立public interface PayStrategy &#123; PayResult pay(PayOrder order);&#125;
第三问：需不需要多继承？ 一个类需要具备多种能力 → 接口 只需要一种身份 → 抽象类或接口均可
// ✅ 接口：一个类可以实现多个接口public class UserDTO implements Serializable, Cloneable, Comparable&lt;UserDTO&gt; &#123; // ...&#125;
项目中的典型选择场景1：实体类基类 → 抽象类@Datapublic abstract class BaseEntity &#123; private Long id; private LocalDateTime createTime; private LocalDateTime updateTime; private Integer deleted;&#125;
原因：有公共状态（id、时间字段），子类自动继承。 场景2：策略&#x2F;处理器 → 接口public interface MessageHandler &#123; String getType(); void handle(Message msg);&#125;
原因：无公共状态，只定义行为契约，支持多实现。 场景3：模板流程 → 抽象类 + 接口配合// 接口：定义能力public interface DataProcessor &#123; ProcessResult process(Data data);&#125;// 抽象类：提供模板public abstract class AbstractDataProcessor implements DataProcessor &#123; @Override public final ProcessResult process(Data data) &#123; validate(data); ProcessResult result = doProcess(data); postProcess(result); return result; &#125; protected abstract void validate(Data data); protected abstract ProcessResult doProcess(Data data); protected void postProcess(ProcessResult result) &#123; /* 默认空实现 */ &#125;&#125;
场景4：能力标记 → 接口// 标记接口：无任何方法public interface Refreshable &#123; // 标记该组件支持刷新&#125;// 功能接口public interface Refreshable &#123; void refresh();&#125;
常见误区1. “接口优于抽象类”的教条很多文章说”优先用接口”，但这是有前提的。如果你的场景有公共状态和模板逻辑，强行用接口会导致：
default方法泛滥 常量接口反模式 逻辑分散在多个default方法中，难以维护
2. 常量接口反模式// ❌ 不要用接口定义常量public interface Constants &#123; String NAME = &quot;test&quot;; int MAX_SIZE = 100;&#125;// ✅ 用final类+private构造public final class Constants &#123; private Constants() &#123;&#125; public static final String NAME = &quot;test&quot;; public static final int MAX_SIZE = 100;&#125;
3. 接口承载过多逻辑// ❌ default方法写业务逻辑public interface UserService &#123; default User createUser(String name) &#123; // 50行业务逻辑... &#125;&#125;// ✅ 接口只定义契约，逻辑放在抽象类或实现类public interface UserService &#123; User createUser(String name);&#125;
总结 抽象类和接口的选择，核心是理解它们的设计语义：抽象类是”is-a”，定义你是什么；接口是”can-do”，定义你能做什么*实用原则是：
有公共状态 → 抽象类 有模板流程 → 抽象类 只定义行为 → 接口 需要多继承 → 接口 不确定 → 先用接口，后续需要时再加抽象类

前言
实际项目初期，所有业务逻辑全靠if-else硬编码。瓦斯告警通知方式只有短信，后来要加站内信、App推送，每次改代码都牵一发动全身。巡检流程每新增一种类型就要改Service，权限判断到处都是switch-case。学习设计模式后，用策略模式消灭if-else、模板方法统一流程、观察者模式解耦通知，代码变得灵活可扩展，需求变更不再痛苦。
本文以实际项目为背景，结合实际场景讲解7种最常用的设计模式，以及它们在项目中的落地实践。
项目背景智慧矿山管理系统 - 模块架构

+————+    +————+    +————+
| 安全告警    |    | 巡检管理    |    | 设备监测    |
| 多渠道通知  |    | 多类型流程  |    | 多策略预警  |
+—–+——+    +—–+——+    +—–+——+
|                  |                 |
v                  v                 v
+———————————————————-+
|                   设计模式应用层                            |
|  策略模式  |  模板方法  |  观察者  |  工厂  |  责任链       |
+———————————————————-+

设计原则SOLID在讲解具体模式之前，先理解设计原则：

原则   |  说明                     |  智慧矿山示例
S     |  单一职责：一个类只做一件事   |  AlarmService只管告警，不管通知
O     |  开闭原则：对扩展开放，修改关闭 |  新增通知渠道不改动告警逻辑
L     |  里氏替换：子类可替换父类      |  任何通知策略都能替换使用
I     |  接口隔离：接口小而专          |  通知和预警用不同接口
D     |  依赖倒置：依赖抽象非实现      |  依赖NotifyStrategy而非具体实现

何时用设计模式问题信号                    推荐模式----------                  ----------代码重复 -----------------&gt; 模板方法if-else过多 --------------&gt; 策略模式对象创建复杂 -------------&gt; 工厂模式需要通知多个对象 ----------&gt; 观察者模式功能动态组合 -------------&gt; 装饰器模式请求需要链式处理 ----------&gt; 责任链模式全局唯一实例 -------------&gt; 单例模式注意：不要为了用模式而用模式！先写简单代码，重构时再引入模式。

策略模式场景：告警通知方式重构前：

AlarmService.notify(alarm)
if (type &#x3D;&#x3D; “SMS”) {
smsService.send(alarm);
} else if (type &#x3D;&#x3D; “EMAIL”) {
emailService.send(alarm);
} else if (type &#x3D;&#x3D; “APP”) {
appPushService.send(alarm);
} else if (type &#x3D;&#x3D; “WECHAT”) {
wechatService.send(alarm);
}
&#x2F;&#x2F; 新增通知方式？加else if！
重构后：
AlarmService.notify(alarm)
NotifyStrategy strategy &#x3D; getStrategy(type);
strategy.send(alarm);
&#x2F;&#x2F; 新增通知方式？新增一个实现类即可！

策略接口/** * 告警通知策略接口 */public interface NotifyStrategy &#123;    /**     * 发送通知     */    void send(Alarm alarm);    /**     * 支持的通知类型     */    String getType();&#125;

策略实现// 短信通知@Component@Slf4jpublic class SmsNotifyStrategy implements NotifyStrategy &#123;    private final SmsService smsService;    @Override    public void send(Alarm alarm) &#123;        String phone = alarm.getHandlerPhone();        String content = buildSmsContent(alarm);        smsService.send(phone, content);        log.info(&quot;短信通知已发送: alarmId=&#123;&#125;, phone=&#123;&#125;&quot;, alarm.getId(), phone);    &#125;    @Override    public String getType() &#123;        return &quot;SMS&quot;;    &#125;    private String buildSmsContent(Alarm alarm) &#123;        return String.format(&quot;【智慧矿山告警】%s %s 当前值:%s 阈值:%s&quot;,            alarm.getSensorName(), alarm.getAlarmType(),            alarm.getCurrentValue(), alarm.getThreshold());    &#125;&#125;// 邮件通知@Component@Slf4jpublic class EmailNotifyStrategy implements NotifyStrategy &#123;    private final EmailService emailService;    @Override    public void send(Alarm alarm) &#123;        String email = alarm.getHandlerEmail();        String subject = &quot;【智慧矿山告警】&quot; + alarm.getSensorName();        String body = buildEmailBody(alarm);        emailService.sendHtml(email, subject, body);        log.info(&quot;邮件通知已发送: alarmId=&#123;&#125;, email=&#123;&#125;&quot;, alarm.getId(), email);    &#125;    @Override    public String getType() &#123;        return &quot;EMAIL&quot;;    &#125;    private String buildEmailBody(Alarm alarm) &#123;        return String.format(&quot;&quot;&quot;            &lt;h2&gt;安全告警通知&lt;/h2&gt;            &lt;table&gt;                &lt;tr&gt;&lt;td&gt;传感器&lt;/td&gt;&lt;td&gt;%s&lt;/td&gt;&lt;/tr&gt;                &lt;tr&gt;&lt;td&gt;告警类型&lt;/td&gt;&lt;td&gt;%s&lt;/td&gt;&lt;/tr&gt;                &lt;tr&gt;&lt;td&gt;当前值&lt;/td&gt;&lt;td&gt;%s&lt;/td&gt;&lt;/tr&gt;                &lt;tr&gt;&lt;td&gt;阈值&lt;/td&gt;&lt;td&gt;%s&lt;/td&gt;&lt;/tr&gt;                &lt;tr&gt;&lt;td&gt;告警级别&lt;/td&gt;&lt;td&gt;%s&lt;/td&gt;&lt;/tr&gt;                &lt;tr&gt;&lt;td&gt;时间&lt;/td&gt;&lt;td&gt;%s&lt;/td&gt;&lt;/tr&gt;            &lt;/table&gt;            &quot;&quot;&quot;, alarm.getSensorName(), alarm.getAlarmType(),            alarm.getCurrentValue(), alarm.getThreshold(),            alarm.getLevel().getDesc(), alarm.getCreateTime());    &#125;&#125;// App推送@Component@Slf4jpublic class AppPushNotifyStrategy implements NotifyStrategy &#123;    private final AppPushService appPushService;    @Override    public void send(Alarm alarm) &#123;        PushMessage message = PushMessage.builder()            .userId(alarm.getHandlerUserId())            .title(&quot;安全告警&quot;)            .content(alarm.getSensorName() + &quot; &quot; + alarm.getAlarmType())            .extra(Map.of(&quot;alarmId&quot;, String.valueOf(alarm.getId())))            .build();        appPushService.push(message);        log.info(&quot;App推送已发送: alarmId=&#123;&#125;&quot;, alarm.getId());    &#125;    @Override    public String getType() &#123;        return &quot;APP&quot;;    &#125;&#125;// 企业微信通知@Component@Slf4jpublic class WechatNotifyStrategy implements NotifyStrategy &#123;    private final WechatWorkService wechatWorkService;    @Override    public void send(Alarm alarm) &#123;        WechatMessage msg = WechatMessage.builder()            .toUser(alarm.getHandlerUserId())            .msgType(&quot;text&quot;)            .content(buildWechatContent(alarm))            .build();        wechatWorkService.sendMessage(msg);        log.info(&quot;企业微信通知已发送: alarmId=&#123;&#125;&quot;, alarm.getId());    &#125;    @Override    public String getType() &#123;        return &quot;WECHAT&quot;;    &#125;    private String buildWechatContent(Alarm alarm) &#123;        return String.format(&quot;【告警通知】\n传感器：%s\n类型：%s\n当前值：%s\n阈值：%s&quot;,            alarm.getSensorName(), alarm.getAlarmType(),            alarm.getCurrentValue(), alarm.getThreshold());    &#125;&#125;

策略工厂@Component@RequiredArgsConstructorpublic class NotifyStrategyFactory &#123;    private final List&lt;NotifyStrategy&gt; strategies;    /**     * 缓存策略映射     */    private Map&lt;String, NotifyStrategy&gt; strategyMap;    @PostConstruct    public void init() &#123;        strategyMap = strategies.stream()            .collect(Collectors.toMap(NotifyStrategy::getType, Function.identity()));    &#125;    /**     * 获取通知策略     */    public NotifyStrategy getStrategy(String type) &#123;        NotifyStrategy strategy = strategyMap.get(type);        if (strategy == null) &#123;            throw new BusinessException(&quot;不支持的通知类型: &quot; + type);        &#125;        return strategy;    &#125;    /**     * 获取所有支持的类型     */    public Set&lt;String&gt; getSupportedTypes() &#123;        return strategyMap.keySet();    &#125;&#125;

使用@Service@RequiredArgsConstructor@Slf4jpublic class AlarmNotifyService &#123;    private final NotifyStrategyFactory strategyFactory;    /**     * 发送告警通知（解决问题#1）     */    public void notifyAlarm(Alarm alarm) &#123;        List&lt;String&gt; channels = alarm.getNotifyChannels();        for (String channel : channels) &#123;            try &#123;                NotifyStrategy strategy = strategyFactory.getStrategy(channel);                strategy.send(alarm);            &#125; catch (Exception e) &#123;                log.error(&quot;告警通知发送失败: channel=&#123;&#125;, alarmId=&#123;&#125;&quot;, channel, alarm.getId(), e);            &#125;        &#125;    &#125;    /**     * 按告警级别自动选择通知渠道     */    public void notifyByLevel(Alarm alarm) &#123;        List&lt;String&gt; channels = switch (alarm.getLevel()) &#123;            case CRITICAL -&gt; List.of(&quot;SMS&quot;, &quot;APP&quot;, &quot;WECHAT&quot;);            case WARNING  -&gt; List.of(&quot;APP&quot;, &quot;WECHAT&quot;);            case INFO     -&gt; List.of(&quot;APP&quot;);        &#125;;        for (String channel : channels) &#123;            strategyFactory.getStrategy(channel).send(alarm);        &#125;    &#125;&#125;

预警策略/** * 设备预警策略接口（解决问题#7） */public interface AlertStrategy &#123;    /**     * 判断是否触发预警     */    boolean shouldAlert(SensorData data);    /**     * 计算预警级别     */    AlarmLevel calculateLevel(SensorData data);    /**     * 支持的传感器类型     */    String getSensorType();&#125;// 瓦斯预警策略@Componentpublic class GasAlertStrategy implements AlertStrategy &#123;    @Override    public boolean shouldAlert(SensorData data) &#123;        BigDecimal value = new BigDecimal(data.getValue());        BigDecimal threshold = new BigDecimal(data.getThreshold());        return value.compareTo(threshold) &gt;= 0;    &#125;    @Override    public AlarmLevel calculateLevel(SensorData data) &#123;        BigDecimal value = new BigDecimal(data.getValue());        BigDecimal threshold = new BigDecimal(data.getThreshold());        BigDecimal ratio = value.divide(threshold, 2, RoundingMode.HALF_UP);        if (ratio.compareTo(new BigDecimal(&quot;1.5&quot;)) &gt;= 0) return AlarmLevel.CRITICAL;        if (ratio.compareTo(new BigDecimal(&quot;1.2&quot;)) &gt;= 0) return AlarmLevel.WARNING;        return AlarmLevel.INFO;    &#125;    @Override    public String getSensorType() &#123;        return &quot;GAS&quot;;    &#125;&#125;// 温度预警策略@Componentpublic class TemperatureAlertStrategy implements AlertStrategy &#123;    @Override    public boolean shouldAlert(SensorData data) &#123;        double value = Double.parseDouble(data.getValue());        double threshold = Double.parseDouble(data.getThreshold());        return value &gt;= threshold;    &#125;    @Override    public AlarmLevel calculateLevel(SensorData data) &#123;        double value = Double.parseDouble(data.getValue());        double threshold = Double.parseDouble(data.getThreshold());        double ratio = value / threshold;        if (ratio &gt;= 1.3) return AlarmLevel.CRITICAL;        if (ratio &gt;= 1.1) return AlarmLevel.WARNING;        return AlarmLevel.INFO;    &#125;    @Override    public String getSensorType() &#123;        return &quot;TEMPERATURE&quot;;    &#125;&#125;

模板方法模式场景：巡检流程巡检流程骨架（不变的部分）：

+——–+    +——–+    +——–+    +——–+    +——–+
校验   | -&gt; | 初始化  | -&gt; | 执行   | -&gt; | 记录   | -&gt; | 通知
任务   |    | 环境   |    | 巡检   |    | 结果   |    | 相关人
+——–+    +——–+    +——–+    +——–+    +——–+
不同巡检类型的差异：
类型    |  执行巡检步骤      |  记录结果方式
日常巡检 |  检查设备运行状态  |  填写巡检表
专项巡检 |  仪器检测精度      |  上传检测报告
应急巡检 |  现场安全隐患排查  |  拍照+描述

模板抽象类/** * 巡检流程模板（解决问题#2 #13） */public abstract class AbstractInspectTemplate &#123;    /**     * 模板方法：定义巡检流程骨架（final防止子类覆盖）     */    public final InspectResult execute(InspectTask task) &#123;        // 1. 校验任务        validateTask(task);        // 2. 初始化环境        InspectContext context = initContext(task);        try &#123;            // 3. 执行巡检（子类实现）            doInspect(context);            // 4. 记录结果（子类实现）            InspectResult result = recordResult(context);            // 5. 后置处理            postProcess(result);            return result;        &#125; catch (Exception e) &#123;            // 异常处理            handleException(task, e);            throw new BusinessException(&quot;巡检执行失败: &quot; + e.getMessage());        &#125;    &#125;    /**     * 校验任务（通用逻辑）     */    protected void validateTask(InspectTask task) &#123;        if (task == null) &#123;            throw new BusinessException(&quot;巡检任务不能为空&quot;);        &#125;        if (task.getStatus() != InspectStatus.PENDING) &#123;            throw new BusinessException(&quot;任务状态不允许执行&quot;);        &#125;        if (task.getExpiredTime() != null &amp;&amp;            task.getExpiredTime().isBefore(LocalDateTime.now())) &#123;            throw new BusinessException(&quot;巡检任务已超时&quot;);        &#125;    &#125;    /**     * 初始化环境（通用逻辑，子类可覆盖）     */    protected InspectContext initContext(InspectTask task) &#123;        InspectContext context = new InspectContext();        context.setTaskId(task.getId());        context.setStartTime(LocalDateTime.now());        context.setInspectorId(UserContext.getUserId());        return context;    &#125;    /**     * 执行巡检（抽象方法，子类必须实现）     */    protected abstract void doInspect(InspectContext context);    /**     * 记录结果（抽象方法，子类必须实现）     */    protected abstract InspectResult recordResult(InspectContext context);    /**     * 后置处理（通用逻辑，子类可覆盖）     */    protected void postProcess(InspectResult result) &#123;        log.info(&quot;巡检完成: taskId=&#123;&#125;, result=&#123;&#125;&quot;, result.getTaskId(), result.getStatus());    &#125;    /**     * 异常处理（通用逻辑，子类可覆盖）     */    protected void handleException(InspectTask task, Exception e) &#123;        log.error(&quot;巡检异常: taskId=&#123;&#125;&quot;, task.getId(), e);    &#125;&#125;

具体实现// 日常巡检@Service@Slf4jpublic class DailyInspectService extends AbstractInspectTemplate &#123;    private final DeviceMapper deviceMapper;    private final InspectRecordMapper recordMapper;    @Override    protected void doInspect(InspectContext context) &#123;        InspectTask task = context.getTask();        log.info(&quot;执行日常巡检: taskId=&#123;&#125;, location=&#123;&#125;&quot;, task.getId(), task.getLocation());        // 检查设备运行状态        List&lt;Device&gt; devices = deviceMapper.selectByLocation(task.getLocation());        for (Device device : devices) &#123;            boolean normal = checkDeviceStatus(device);            context.addCheckItem(device.getDeviceId(), normal ? &quot;正常&quot; : &quot;异常&quot;);        &#125;    &#125;    @Override    protected InspectResult recordResult(InspectContext context) &#123;        // 填写巡检表        InspectRecord record = new InspectRecord();        record.setTaskId(context.getTaskId());        record.setType(&quot;DAILY&quot;);        record.setItems(context.getCheckItems());        recordMapper.insert(record);        return InspectResult.success(context.getTaskId(), record.getId());    &#125;    private boolean checkDeviceStatus(Device device) &#123;        return device.getStatus() == DeviceStatus.ONLINE            &amp;&amp; device.getHealthScore() &gt;= 60;    &#125;&#125;// 专项巡检@Service@Slf4jpublic class SpecialInspectService extends AbstractInspectTemplate &#123;    private final InspectReportMapper reportMapper;    @Override    protected void doInspect(InspectContext context) &#123;        InspectTask task = context.getTask();        log.info(&quot;执行专项巡检: taskId=&#123;&#125;, target=&#123;&#125;&quot;, task.getId(), task.getTarget());        // 仪器检测精度        Map&lt;String, BigDecimal&gt; measurements = takeMeasurements(task.getTarget());        context.setMeasurements(measurements);    &#125;    @Override    protected InspectResult recordResult(InspectContext context) &#123;        // 上传检测报告        InspectReport report = new InspectReport();        report.setTaskId(context.getTaskId());        report.setType(&quot;SPECIAL&quot;);        report.setMeasurements(context.getMeasurements());        reportMapper.insert(report);        return InspectResult.success(context.getTaskId(), report.getId());    &#125;    private Map&lt;String, BigDecimal&gt; takeMeasurements(String target) &#123;        // 仪器检测逻辑        return Map.of(&quot;precision&quot;, new BigDecimal(&quot;0.98&quot;), &quot;stability&quot;, new BigDecimal(&quot;0.95&quot;));    &#125;&#125;

巡检调度器@Service@RequiredArgsConstructorpublic class InspectDispatcher &#123;    private final Map&lt;String, AbstractInspectTemplate&gt; templateMap;    /**     * 根据类型分发巡检     */    public InspectResult executeInspect(InspectTask task) &#123;        AbstractInspectTemplate template = templateMap.get(task.getType().getCode() + &quot;InspectService&quot;);        if (template == null) &#123;            throw new BusinessException(&quot;不支持的巡检类型: &quot; + task.getType());        &#125;        return template.execute(task);    &#125;&#125;

观察者模式场景：告警事件通知重构前：

AlarmService.handle(alarm)
alarmMapper.insert(alarm);
smsService.send(alarm);    &#x2F;&#x2F; 耦合
emailService.send(alarm);  &#x2F;&#x2F; 耦合
appService.push(alarm);    &#x2F;&#x2F; 耦合
statService.record(alarm); &#x2F;&#x2F; 耦合
logService.save(alarm);    &#x2F;&#x2F; 耦合
新增通知？改AlarmService！
重构后：
AlarmService.handle(alarm)
alarmMapper.insert(alarm);
eventPublisher.publishEvent(alarm);
&#x2F;&#x2F; 各监听器独立处理，互不影响
SmsListener.onAlarm(alarm);
EmailListener.onAlarm(alarm);
AppPushListener.onAlarm(alarm);
StatListener.onAlarm(alarm);

Spring事件机制实现/** * 告警事件（解决问题#3 #9） */@Getterpublic class AlarmEvent extends ApplicationEvent &#123;    private final Alarm alarm;    public AlarmEvent(Object source, Alarm alarm) &#123;        super(source);        this.alarm = alarm;    &#125;&#125;/** * 巡检完成事件 */@Getterpublic class InspectCompleteEvent extends ApplicationEvent &#123;    private final InspectResult result;    public InspectCompleteEvent(Object source, InspectResult result) &#123;        super(source);        this.result = result;    &#125;&#125;

事件发布@Service@RequiredArgsConstructor@Slf4jpublic class AlarmService &#123;    private final AlarmMapper alarmMapper;    private final ApplicationEventPublisher publisher;    @Transactional(rollbackFor = Exception.class)    public void handleAlarm(AlarmDTO dto) &#123;        // 1. 保存告警        Alarm alarm = new Alarm();        BeanUtils.copyProperties(dto, alarm);        alarm.setStatus(AlarmStatus.PENDING);        alarmMapper.insert(alarm);        // 2. 发布告警事件（观察者模式）        publisher.publishEvent(new AlarmEvent(this, alarm));        log.info(&quot;告警已处理: alarmId=&#123;&#125;&quot;, alarm.getId());    &#125;&#125;

事件监听/** * 告警通知监听器（异步，不阻塞主流程） */@Component@Slf4jpublic class AlarmNotifyListener &#123;    private final NotifyStrategyFactory strategyFactory;    /**     * 告警通知（解决问题#3：异步发送，不阻塞告警处理）     */    @EventListener    @Async(&quot;alarmExecutor&quot;)    public void onAlarm(AlarmEvent event) &#123;        Alarm alarm = event.getAlarm();        try &#123;            strategyFactory.getStrategy(&quot;SMS&quot;).send(alarm);            strategyFactory.getStrategy(&quot;APP&quot;).send(alarm);        &#125; catch (Exception e) &#123;            log.error(&quot;告警通知发送失败: alarmId=&#123;&#125;&quot;, alarm.getId(), e);        &#125;    &#125;&#125;/** * 告警统计监听器 */@Component@Slf4jpublic class AlarmStatListener &#123;    private final AlarmStatService statService;    @EventListener    @Async    public void onAlarm(AlarmEvent event) &#123;        statService.recordAlarm(event.getAlarm());    &#125;&#125;/** * 告警日志监听器 */@Component@Slf4jpublic class AlarmLogListener &#123;    private final OperateLogService logService;    @EventListener    public void onAlarm(AlarmEvent event) &#123;        logService.saveAlarmLog(event.getAlarm());    &#125;&#125;/** * 巡检完成监听器 */@Component@Slf4jpublic class InspectCompleteListener &#123;    private final InspectStatService statService;    private final NotifyStrategyFactory notifyFactory;    @EventListener    @Async    public void onInspectComplete(InspectCompleteEvent event) &#123;        InspectResult result = event.getResult();        // 更新统计        statService.updateStats(result);        // 通知相关人员        // ...    &#125;&#125;

工厂模式场景：设备创建/** * 设备工厂（解决问题#4） */public interface DeviceFactory &#123;    /**     * 创建设备     */    Device createDevice(DeviceCreateDTO dto);    /**     * 支持的设备类型     */    String getDeviceType();&#125;// 通风机工厂@Componentpublic class VentilationDeviceFactory implements DeviceFactory &#123;    @Override    public Device createDevice(DeviceCreateDTO dto) &#123;        Device device = new Device();        device.setType(DeviceType.VENTILATION);        device.setName(dto.getName());        device.setLocation(dto.getLocation());        device.setStatus(DeviceStatus.OFFLINE);        device.setHealthScore(100);        // 通风机特有属性        device.setExtAttr(&quot;airVolume&quot;, dto.getAirVolume());        device.setExtAttr(&quot;pressure&quot;, dto.getPressure());        return device;    &#125;    @Override    public String getDeviceType() &#123;        return &quot;VENTILATION&quot;;    &#125;&#125;// 排水泵工厂@Componentpublic class DrainageDeviceFactory implements DeviceFactory &#123;    @Override    public Device createDevice(DeviceCreateDTO dto) &#123;        Device device = new Device();        device.setType(DeviceType.DRAINAGE);        device.setName(dto.getName());        device.setLocation(dto.getLocation());        device.setStatus(DeviceStatus.OFFLINE);        device.setHealthScore(100);        device.setExtAttr(&quot;flowRate&quot;, dto.getFlowRate());        device.setExtAttr(&quot;head&quot;, dto.getHead());        return device;    &#125;    @Override    public String getDeviceType() &#123;        return &quot;DRAINAGE&quot;;    &#125;&#125;// 设备工厂调度@Component@RequiredArgsConstructorpublic class DeviceFactoryDispatcher &#123;    private final List&lt;DeviceFactory&gt; factories;    private Map&lt;String, DeviceFactory&gt; factoryMap;    @PostConstruct    public void init() &#123;        factoryMap = factories.stream()            .collect(Collectors.toMap(DeviceFactory::getDeviceType, Function.identity()));    &#125;    public Device create(String type, DeviceCreateDTO dto) &#123;        DeviceFactory factory = factoryMap.get(type);        if (factory == null) &#123;            throw new BusinessException(&quot;不支持的设备类型: &quot; + type);        &#125;        return factory.createDevice(dto);    &#125;&#125;

装饰器模式场景：通知重试/** * 通知策略装饰器：添加重试能力（解决问题#14） */public class RetryNotifyDecorator implements NotifyStrategy &#123;    private final NotifyStrategy delegate;    private final int maxRetries;    private final long retryIntervalMs;    public RetryNotifyDecorator(NotifyStrategy delegate, int maxRetries, long retryIntervalMs) &#123;        this.delegate = delegate;        this.maxRetries = maxRetries;        this.retryIntervalMs = retryIntervalMs;    &#125;    @Override    public void send(Alarm alarm) &#123;        for (int i = 0; i &lt;= maxRetries; i++) &#123;            try &#123;                delegate.send(alarm);                return;  // 成功则返回            &#125; catch (Exception e) &#123;                if (i == maxRetries) &#123;                    throw new BusinessException(&quot;通知发送失败，重试&quot; + maxRetries + &quot;次后仍不成功&quot;);                &#125;                try &#123;                    Thread.sleep(retryIntervalMs);                &#125; catch (InterruptedException ie) &#123;                    Thread.currentThread().interrupt();                    throw new BusinessException(&quot;通知重试被中断&quot;);                &#125;            &#125;        &#125;    &#125;    @Override    public String getType() &#123;        return delegate.getType();    &#125;&#125;// 使用：给短信通知加上重试能力NotifyStrategy retrySms = new RetryNotifyDecorator(smsNotifyStrategy, 3, 1000);retrySms.send(alarm);  // 最多重试3次，每次间隔1秒

场景：日志装饰器/** * 日志装饰器：给通知策略添加日志 */public class LoggingNotifyDecorator implements NotifyStrategy &#123;    private final NotifyStrategy delegate;    public LoggingNotifyDecorator(NotifyStrategy delegate) &#123;        this.delegate = delegate;    &#125;    @Override    public void send(Alarm alarm) &#123;        log.info(&quot;开始发送通知: type=&#123;&#125;, alarmId=&#123;&#125;&quot;, delegate.getType(), alarm.getId());        long start = System.currentTimeMillis();        try &#123;            delegate.send(alarm);            log.info(&quot;通知发送成功: type=&#123;&#125;, alarmId=&#123;&#125;, cost=&#123;&#125;ms&quot;,                delegate.getType(), alarm.getId(), System.currentTimeMillis() - start);        &#125; catch (Exception e) &#123;            log.error(&quot;通知发送失败: type=&#123;&#125;, alarmId=&#123;&#125;, cost=&#123;&#125;ms&quot;,                delegate.getType(), alarm.getId(), System.currentTimeMillis() - start, e);            throw e;        &#125;    &#125;    @Override    public String getType() &#123;        return delegate.getType();    &#125;&#125;// 组合使用：日志 + 重试 + 实际通知NotifyStrategy strategy = new LoggingNotifyDecorator(    new RetryNotifyDecorator(smsNotifyStrategy, 3, 1000));strategy.send(alarm);

责任链模式场景：巡检审批流程审批流程：+--------+    +--------+    +--------+    +--------+| 班组长  | -&gt; | 安监科  | -&gt; | 矿长   | -&gt; | 集团   || 审批   |    | 审批    |    | 审批    |    | 审批   |+--------+    +--------+    +--------+    +--------+     |              |             |             |  金额&lt;=1万     金额&lt;=5万      金额&lt;=20万    金额&gt;20万  直接通过      通过/上交      通过/上交     最终审批

抽象处理器/** * 审批处理器（解决问题#6 #15） */public abstract class ApprovalHandler &#123;    protected ApprovalHandler next;    public ApprovalHandler setNext(ApprovalHandler next) &#123;        this.next = next;        return next;    &#125;    /**     * 处理审批     */    public abstract ApprovalResult handle(ApprovalRequest request);&#125;

具体处理器// 班组长审批@Component@Slf4jpublic class TeamLeaderHandler extends ApprovalHandler &#123;    @Override    public ApprovalResult handle(ApprovalRequest request) &#123;        if (request.getAmount().compareTo(new BigDecimal(&quot;10000&quot;)) &lt;= 0) &#123;            log.info(&quot;班组长审批通过: requestId=&#123;&#125;&quot;, request.getId());            return ApprovalResult.approved(&quot;班组长审批通过&quot;);        &#125;        if (next != null) &#123;            log.info(&quot;班组长转交上级审批: requestId=&#123;&#125;&quot;, request.getId());            return next.handle(request);        &#125;        return ApprovalResult.rejected(&quot;无上级审批人&quot;);    &#125;&#125;// 安监科审批@Component@Slf4jpublic class SafetyDeptHandler extends ApprovalHandler &#123;    @Override    public ApprovalResult handle(ApprovalRequest request) &#123;        if (request.getAmount().compareTo(new BigDecimal(&quot;50000&quot;)) &lt;= 0) &#123;            log.info(&quot;安监科审批通过: requestId=&#123;&#125;&quot;, request.getId());            return ApprovalResult.approved(&quot;安监科审批通过&quot;);        &#125;        if (next != null) &#123;            return next.handle(request);        &#125;        return ApprovalResult.rejected(&quot;无上级审批人&quot;);    &#125;&#125;// 矿长审批@Component@Slf4jpublic class MineManagerHandler extends ApprovalHandler &#123;    @Override    public ApprovalResult handle(ApprovalRequest request) &#123;        if (request.getAmount().compareTo(new BigDecimal(&quot;200000&quot;)) &lt;= 0) &#123;            log.info(&quot;矿长审批通过: requestId=&#123;&#125;&quot;, request.getId());            return ApprovalResult.approved(&quot;矿长审批通过&quot;);        &#125;        if (next != null) &#123;            return next.handle(request);        &#125;        return ApprovalResult.rejected(&quot;金额超出审批权限&quot;);    &#125;&#125;// 集团审批@Component@Slf4jpublic class GroupHandler extends ApprovalHandler &#123;    @Override    public ApprovalResult handle(ApprovalRequest request) &#123;        log.info(&quot;集团最终审批通过: requestId=&#123;&#125;&quot;, request.getId());        return ApprovalResult.approved(&quot;集团审批通过&quot;);    &#125;&#125;

责任链构建@Configurationpublic class ApprovalChainConfig &#123;    @Bean    public ApprovalHandler approvalChain(            TeamLeaderHandler teamLeader,            SafetyDeptHandler safetyDept,            MineManagerHandler mineManager,            GroupHandler group) &#123;        // 构建审批链：班组长 -&gt; 安监科 -&gt; 矿长 -&gt; 集团        teamLeader.setNext(safetyDept);        safetyDept.setNext(mineManager);        mineManager.setNext(group);        return teamLeader;  // 返回链头    &#125;&#125;// 使用@Service@RequiredArgsConstructorpublic class ApprovalService &#123;    private final ApprovalHandler approvalChain;    public ApprovalResult approve(ApprovalRequest request) &#123;        return approvalChain.handle(request);    &#125;&#125;

单例模式场景：系统配置// 饿汉式（简单，类加载时创建）public class MineSystemConfig &#123;    private static final MineSystemConfig INSTANCE = new MineSystemConfig();    private MineSystemConfig() &#123;        // 加载配置    &#125;    public static MineSystemConfig getInstance() &#123;        return INSTANCE;    &#125;    private Map&lt;String, String&gt; configMap = new HashMap&lt;&gt;();    public String getConfig(String key) &#123;        return configMap.get(key);    &#125;&#125;// 枚举单例（最佳实践，防反射破坏 #8）public enum MineConfig &#123;    INSTANCE;    private final Map&lt;String, String&gt; configMap = new HashMap&lt;&gt;();    MineConfig() &#123;        // 加载配置        configMap.put(&quot;mine.name&quot;, &quot;XX煤矿&quot;);        configMap.put(&quot;mine.code&quot;, &quot;MINE-001&quot;);        configMap.put(&quot;alarm.level.critical&quot;, &quot;1.5&quot;);    &#125;    public String get(String key) &#123;        return configMap.get(key);    &#125;    public BigDecimal getAlarmThreshold(String type) &#123;        return new BigDecimal(configMap.getOrDefault(&quot;alarm.level.&quot; + type, &quot;1.0&quot;));    &#125;&#125;// 使用BigDecimal threshold = MineConfig.INSTANCE.getAlarmThreshold(&quot;critical&quot;);

模式组合实战策略+工厂+观察者：告警处理全流程传感器数据 -&gt; 预警判断(策略) -&gt; 创建告警 -&gt; 发布事件(观察者)

|
|
通知(策略)       记录日志        更新统计
短信&#x2F;邮件&#x2F;推送   (监听器)        (监听器)

@Service@RequiredArgsConstructor@Slf4jpublic class SensorDataProcessor &#123;    private final Map&lt;String, AlertStrategy&gt; alertStrategyMap;    private final AlarmMapper alarmMapper;    private final ApplicationEventPublisher publisher;    /**     * 处理传感器数据     */    public void process(SensorData data) &#123;        // 1. 获取预警策略（策略模式）        AlertStrategy strategy = alertStrategyMap.get(data.getSensorType());        if (strategy == null) &#123;            log.debug(&quot;无预警策略: type=&#123;&#125;&quot;, data.getSensorType());            return;        &#125;        // 2. 判断是否预警        if (strategy.shouldAlert(data)) &#123;            // 3. 创建告警            Alarm alarm = new Alarm();            alarm.setSensorId(data.getSensorId());            alarm.setSensorType(data.getSensorType());            alarm.setCurrentValue(data.getValue());            alarm.setThreshold(data.getThreshold());            alarm.setLevel(strategy.calculateLevel(data));            alarm.setStatus(AlarmStatus.PENDING);            alarmMapper.insert(alarm);            // 4. 发布告警事件（观察者模式）            publisher.publishEvent(new AlarmEvent(this, alarm));            log.info(&quot;告警已创建: sensorId=&#123;&#125;, level=&#123;&#125;&quot;, data.getSensorId(), alarm.getLevel());        &#125;    &#125;&#125;

设计模式选择指南需要通知多对象   |  观察者模式            |  告警事件通知

问题            |  推荐模式              |  智慧矿山应用
if-else过多     |  策略模式              |  告警通知&#x2F;预警策略
代码重复        |  模板方法              |  巡检流程
对象创建复杂     |  工厂模式              |  设备创建
功能动态组合     |  装饰器模式            |  通知重试&#x2F;日志
链式处理        |  责任链模式            |  审批流程
全局唯一        |  单例模式              |  系统配置

总结设计模式是实际项目代码质量的保障。从”if-else一把梭”到”策略模式+模板方法+观察者模式”，核心认知是：设计模式不是炫技，而是应对变化的工具。
关键收获：

策略模式消灭if-else是最常见最实用的优化
模板方法统一流程骨架，子类只实现差异部分
Spring事件机制是观察者模式的最佳实践
责任链模式让审批流程可配置可扩展
装饰器模式动态组合功能，比继承更灵活
不要过度设计，先写简单代码，重构时再引入模式

前言
在实际场景中，多台服务器的日志散落在各处，排查问题时需要逐台登录查看，效率极低。后来搭建了ELK日志系统，所有日志集中管理，一条命令就能搜索全集群日志。
日志收集架构应用 → Filebeat → Logstash → Elasticsearch → Kibana应用：生成日志文件Filebeat：轻量级日志采集器，部署在每台应用服务器Logstash：日志处理和转发Elasticsearch：日志存储和搜索Kibana：日志可视化查询

日志规范日志格式&lt;!-- logback-spring.xml --&gt;&lt;encoder&gt;    &lt;pattern&gt;%d&#123;yyyy-MM-dd HH:mm:ss.SSS&#125; [%thread] %-5level %logger&#123;50&#125; - %msg%n&lt;/pattern&gt;&lt;/encoder&gt;

JSON格式日志（推荐）&lt;encoder class=&quot;net.logstash.logback.encoder.LogstashEncoder&quot;&gt;    &lt;includeContext&gt;true&lt;/includeContext&gt;    &lt;includeMdc&gt;true&lt;/includeMdc&gt;    &lt;customFields&gt;&#123;&quot;app_name&quot;:&quot;myapp&quot;,&quot;env&quot;:&quot;prod&quot;&#125;&lt;/customFields&gt;&lt;/encoder&gt;

JSON格式日志方便Logstash解析：
&#123;    &quot;@timestamp&quot;: &quot;2022-12-31T10:00:00.000Z&quot;,    &quot;level&quot;: &quot;ERROR&quot;,    &quot;logger_name&quot;: &quot;com.example.UserService&quot;,    &quot;message&quot;: &quot;查询用户失败: userId=1&quot;,    &quot;thread_name&quot;: &quot;http-nio-8080-exec-1&quot;,    &quot;app_name&quot;: &quot;myapp&quot;,    &quot;env&quot;: &quot;prod&quot;,    &quot;traceId&quot;: &quot;abc123&quot;&#125;

Filebeat配置# filebeat.ymlfilebeat.inputs:- type: log  enabled: true  paths:    - /data/logs/myapp.log    - /data/logs/myapp-error.log  fields:    app: myapp    env: prod  fields_under_root: true  multiline:    pattern: &#x27;^\d&#123;4&#125;-\d&#123;2&#125;-\d&#123;2&#125;&#x27;    negate: true    match: afteroutput.logstash:  hosts: [&quot;logstash:5044&quot;]# 或直接输出到Elasticsearch# output.elasticsearch:#   hosts: [&quot;elasticsearch:9200&quot;]#   index: &quot;myapp-%&#123;+yyyy.MM.dd&#125;&quot;

Logstash配置# logstash.confinput &#123;  beats &#123;    port =&gt; 5044  &#125;&#125;filter &#123;  # 解析JSON日志  json &#123;    source =&gt; &quot;message&quot;    remove_field =&gt; [&quot;message&quot;]  &#125;  # 添加字段  mutate &#123;    add_field =&gt; &#123; &quot;log_type&quot; =&gt; &quot;application&quot; &#125;  &#125;  # 提取错误级别  if [level] == &quot;ERROR&quot; &#123;    mutate &#123;      add_tags =&gt; [&quot;error&quot;]    &#125;  &#125;&#125;output &#123;  elasticsearch &#123;    hosts =&gt; [&quot;elasticsearch:9200&quot;]    index =&gt; &quot;myapp-%&#123;+YYYY.MM.dd&#125;&quot;  &#125;&#125;

Kibana使用基础查询# 搜索关键词message: &quot;NullPointerException&quot;# 搜索特定级别level: &quot;ERROR&quot;# 组合搜索level: &quot;ERROR&quot; AND app_name: &quot;myapp&quot;# 模糊搜索message: *Exception*# 范围搜索@timestamp: [2022-12-31 TO now]

常用面板1. 错误日志面板：level: ERROR2. 慢请求面板：cost &gt; 30004. 接口耗时面板：按uri分组统计5. 业务指标面板：订单创建、支付成功等

MDC链路追踪@Componentpublic class TraceInterceptor implements HandlerInterceptor &#123;    @Override    public boolean preHandle(HttpServletRequest request, ...) &#123;        String traceId = request.getHeader(&quot;X-Trace-Id&quot;);        if (traceId == null) &#123;            traceId = IdUtil.simpleUUID();        &#125;        MDC.put(&quot;traceId&quot;, traceId);        MDC.put(&quot;userId&quot;, String.valueOf(UserContext.getUserId()));        return true;    &#125;    @Override    public void afterCompletion(...) &#123;        MDC.clear();    &#125;&#125;

logback配置引用MDC：
&lt;pattern&gt;%d&#123;yyyy-MM-dd HH:mm:ss.SSS&#125; [%X&#123;traceId&#125;] [%thread] %-5level %logger&#123;50&#125; - %msg%n&lt;/pattern&gt;

日志告警ElastAlert# error_alert.yamlname: Error Log Alerttype: frequencyindex: myapp-*num_events: 10timeframe:  minutes: 5filter:- term:    level: &quot;ERROR&quot;alert:- &quot;email&quot;email:- &quot;dev-team@example.com&quot;

简单脚本告警#!/bin/bash# check_errors.shCOUNT=$(grep -c &quot;ERROR&quot; /data/logs/myapp.log)if [ $COUNT -gt 100 ]; then    curl -s &quot;https://hook.dingtalk.com/xxx&quot;         -H &#x27;Content-Type: application/json&#x27;         -d &quot;&#123;&quot;msgtype&quot;:&quot;text&quot;,&quot;text&quot;:&#123;&quot;content&quot;:&quot;【告警】5分钟内ERROR日志$&#123;COUNT&#125;条&quot;&#125;&#125;&quot;fi

日志清理# 定时清理30天前的日志find /data/logs -name &quot;*.log&quot; -mtime +30 -deletefind /data/logs -name &quot;*.gz&quot; -mtime +30 -delete# Elasticsearch索引清理curl -X DELETE &quot;localhost:9200/myapp-2022.11.*&quot;

总结
日志收集是运维体系的基础。从”逐台登录看日志”到”ELK集中管理”核心认知是：日志不是写完就完事，而是要能快速搜索和定位*JSON格式+MDC链路追踪+集中收集——这三样做好，线上排查效率提升10倍。

前言 实际场景中，统计报表是管理层的核心需求：日产量统计、安全告警趋势、设备故障率分析、人员出勤率、物资消耗统计等。最初我写的统计SQL又慢又乱，查一次全表扫描耗时十几秒。后来学会了聚合函数、分组统计、窗口函数、预计算表，报表开发效率和查询性能都大幅提升。 本文以实际项目为背景，系统讲解SQL聚合统计、环比同比、Top N排名、累计统计、Java实现和性能优化。 项目背景智慧矿山系统 - 报表统计体系
+————+ +————+ +————+ +————+ | 产量日报 | | 安全统计 | | 设备报表 | | 人员报表 | | 日&#x2F;月&#x2F;年 | | 告警趋势 | | 故障率 | | 出勤率 | +—–+——+ +—–+——+ +—–+——+ +—–+——+ | | | | v v v v +———————————————————-+ | SQL聚合统计 + 预计算 + 缓存 | +———————————————————-+
报表统计场景
报表类型 统计维度 数据量 更新频率 查询频率
产量日报 日&#x2F;月&#x2F;年 10万+&#x2F;年 每日 高
告警趋势 日&#x2F;月 50万+&#x2F;年 实时 高
设备故障率 日&#x2F;月&#x2F;季 5万+&#x2F;年 每日 中
人员出勤 日&#x2F;月 30万+&#x2F;年 每日 高
物资消耗 月&#x2F;季 10万+&#x2F;年 每月 低
安全评分 月&#x2F;季 12条&#x2F;年 每月 中
常用聚合函数基础聚合-- 产量统计SELECT COUNT(*) AS total_records, -- 总记录数 COUNT(DISTINCT work_area) AS unique_areas, -- 不重复工作面数 SUM(actual_output) AS total_output, -- 总产量 AVG(actual_output) AS avg_output, -- 平均产量 MAX(actual_output) AS max_output, -- 最高产量 MIN(actual_output) AS min_output -- 最低产量FROM biz_daily_outputWHERE output_date &gt;= &#x27;2022-01-01&#x27; AND output_date &lt; &#x27;2022-02-01&#x27;;
条件聚合-- 告警统计（按级别统计）SELECT COUNT(*) AS total, SUM(CASE WHEN level = &#x27;CRITICAL&#x27; THEN 1 ELSE 0 END) AS critical_count, SUM(CASE WHEN level = &#x27;WARNING&#x27; THEN 1 ELSE 0 END) AS warning_count, SUM(CASE WHEN level = &#x27;INFO&#x27; THEN 1 ELSE 0 END) AS info_count, -- 百分比 ROUND(SUM(CASE WHEN level = &#x27;CRITICAL&#x27; THEN 1 ELSE 0 END) / COUNT(*) * 100, 2) AS critical_rateFROM biz_alarmWHERE create_time &gt;= &#x27;2022-01-01&#x27; AND create_time &lt; &#x27;2022-02-01&#x27;;-- NULL值处理（解决问题#11）SELECT COUNT(*) AS total, IFNULL(SUM(actual_output), 0) AS total_output, -- NULL转0 COALESCE(AVG(efficiency), 0) AS avg_efficiency -- 第一个非NULL值FROM biz_daily_outputWHERE output_date &gt;= &#x27;2022-01-01&#x27;;
分组统计按日期分组-- 每日产量统计SELECT output_date AS date, COUNT(*) AS record_count, SUM(actual_output) AS daily_output, AVG(efficiency) AS avg_efficiencyFROM biz_daily_outputWHERE output_date &gt;= &#x27;2022-01-01&#x27; AND output_date &lt; &#x27;2022-02-01&#x27;GROUP BY output_dateORDER BY output_date;
查询结果可视化：产量(吨)5000 | ___4000 | ___ | |3000 | | | | | ___2000 | __| |_| |_| |__1000 || | 0 +--+--+--+--+--+--+--+-- 01 02 03 04 05 06 07 日期
按月分组-- 月度安全告警趋势（解决问题#8）SELECT DATE_FORMAT(create_time, &#x27;%Y-%m&#x27;) AS month, COUNT(*) AS alarm_count, SUM(CASE WHEN level = &#x27;CRITICAL&#x27; THEN 1 ELSE 0 END) AS critical_count, SUM(CASE WHEN level = &#x27;WARNING&#x27; THEN 1 ELSE 0 END) AS warning_countFROM biz_alarmWHERE create_time &gt;= &#x27;2022-01-01&#x27; AND create_time &lt; &#x27;2023-01-01&#x27;GROUP BY DATE_FORMAT(create_time, &#x27;%Y-%m&#x27;)ORDER BY month;
按工作面分组-- 各工作面产量对比SELECT work_area, COUNT(*) AS work_days, SUM(actual_output) AS total_output, AVG(actual_output) AS avg_daily_output, AVG(efficiency) AS avg_efficiencyFROM biz_daily_outputWHERE output_date &gt;= &#x27;2022-01-01&#x27; AND output_date &lt; &#x27;2023-01-01&#x27;GROUP BY work_areaORDER BY total_output DESC;
多维度分组-- 按工作面和月份交叉统计SELECT work_area, DATE_FORMAT(output_date, &#x27;%Y-%m&#x27;) AS month, SUM(actual_output) AS total_output, AVG(efficiency) AS avg_efficiencyFROM biz_daily_outputWHERE output_date &gt;= &#x27;2022-01-01&#x27; AND output_date &lt; &#x27;2023-01-01&#x27;GROUP BY work_area, DATE_FORMAT(output_date, &#x27;%Y-%m&#x27;)ORDER BY work_area, month;
日期格式统一-- 统一日期格式（解决问题#8 #12）-- 日DATE_FORMAT(create_time, &#x27;%Y-%m-%d&#x27;) -- 2022-07-04-- 周DATE_FORMAT(create_time, &#x27;%Y-W%u&#x27;) -- 2022-W27-- 月DATE_FORMAT(create_time, &#x27;%Y-%m&#x27;) -- 2022-07-- 季CONCAT(YEAR(create_time), &#x27;-Q&#x27;, QUARTER(create_time)) -- 2022-Q3-- 年YEAR(create_time) -- 2022
环比同比环比统计-- 本月 vs 上月（解决问题#3：SQL直接计算环比）SELECT &#x27;本月&#x27; AS period, COUNT(*) AS alarm_count, SUM(CASE WHEN level = &#x27;CRITICAL&#x27; THEN 1 ELSE 0 END) AS critical_countFROM biz_alarmWHERE create_time &gt;= DATE_FORMAT(NOW(), &#x27;%Y-%m-01&#x27;) AND create_time &lt; DATE_ADD(DATE_FORMAT(NOW(), &#x27;%Y-%m-01&#x27;), INTERVAL 1 MONTH)UNION ALLSELECT &#x27;上月&#x27; AS period, COUNT(*) AS alarm_count, SUM(CASE WHEN level = &#x27;CRITICAL&#x27; THEN 1 ELSE 0 END) AS critical_countFROM biz_alarmWHERE create_time &gt;= DATE_ADD(DATE_FORMAT(NOW(), &#x27;%Y-%m-01&#x27;), INTERVAL -1 MONTH) AND create_time &lt; DATE_FORMAT(NOW(), &#x27;%Y-%m-01&#x27;);
环比增长率（窗口函数）-- 月度环比增长率（解决问题#2 #3）SELECT month, alarm_count, LAG(alarm_count) OVER (ORDER BY month) AS last_month_count, CASE WHEN LAG(alarm_count) OVER (ORDER BY month) &gt; 0 THEN ROUND((alarm_count - LAG(alarm_count) OVER (ORDER BY month)) / LAG(alarm_count) OVER (ORDER BY month) * 100, 2) ELSE NULL END AS growth_rateFROM ( SELECT DATE_FORMAT(create_time, &#x27;%Y-%m&#x27;) AS month, COUNT(*) AS alarm_count FROM biz_alarm WHERE create_time &gt;= &#x27;2022-01-01&#x27; GROUP BY DATE_FORMAT(create_time, &#x27;%Y-%m&#x27;)) monthlyORDER BY month;
同比统计-- 今年 vs 去年同期SELECT curr.month, curr.alarm_count AS this_year, prev.alarm_count AS last_year, ROUND((curr.alarm_count - prev.alarm_count) / prev.alarm_count * 100, 2) AS yoy_rateFROM ( SELECT DATE_FORMAT(create_time, &#x27;%m&#x27;) AS month, COUNT(*) AS alarm_count FROM biz_alarm WHERE create_time &gt;= &#x27;2022-01-01&#x27; AND create_time &lt; &#x27;2023-01-01&#x27; GROUP BY DATE_FORMAT(create_time, &#x27;%m&#x27;)) currJOIN ( SELECT DATE_FORMAT(create_time, &#x27;%m&#x27;) AS month, COUNT(*) AS alarm_count FROM biz_alarm WHERE create_time &gt;= &#x27;2021-01-01&#x27; AND create_time &lt; &#x27;2022-01-01&#x27; GROUP BY DATE_FORMAT(create_time, &#x27;%m&#x27;)) prev ON curr.month = prev.monthORDER BY curr.month;
Top N排名基础排名-- 产量TOP10工作面（解决问题#9）SELECT work_area, SUM(actual_output) AS total_output, DENSE_RANK() OVER (ORDER BY SUM(actual_output) DESC) AS rank_noFROM biz_daily_outputWHERE output_date &gt;= &#x27;2022-01-01&#x27;GROUP BY work_areaORDER BY total_output DESCLIMIT 10;
窗口函数排名对比-- 三种排名函数对比-- ROW_NUMBER: 1,2,3,4... (不并列)-- RANK: 1,1,3,4... (并列跳号)-- DENSE_RANK: 1,1,2,3... (并列不跳号，推荐)SELECT work_area, total_output, ROW_NUMBER() OVER (ORDER BY total_output DESC) AS row_num, RANK() OVER (ORDER BY total_output DESC) AS rank_val, DENSE_RANK() OVER (ORDER BY total_output DESC) AS dense_rank_valFROM ( SELECT work_area, SUM(actual_output) AS total_output FROM biz_daily_output WHERE output_date &gt;= &#x27;2022-01-01&#x27; GROUP BY work_area) t;
累计统计累计产量-- 累计产量（窗口函数，解决问题#10）SELECT output_date, daily_output, SUM(daily_output) OVER (ORDER BY output_date) AS cumulative_outputFROM ( SELECT output_date, SUM(actual_output) AS daily_output FROM biz_daily_output WHERE output_date &gt;= &#x27;2022-01-01&#x27; AND output_date &lt; &#x27;2022-02-01&#x27; GROUP BY output_date) dailyORDER BY output_date;
滚动平均-- 7日滚动平均产量SELECT output_date, daily_output, ROUND(AVG(daily_output) OVER ( ORDER BY output_date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW ), 2) AS moving_avg_7dFROM ( SELECT output_date, SUM(actual_output) AS daily_output FROM biz_daily_output WHERE output_date &gt;= &#x27;2022-01-01&#x27; GROUP BY output_date) dailyORDER BY output_date;
Java实现统计VO@Datapublic class DailyOutputVO &#123; private String date; private BigDecimal dailyOutput; private BigDecimal cumulativeOutput; private BigDecimal efficiency; private BigDecimal growthRate;&#125;@Datapublic class AlarmStatisticsVO &#123; private String period; private Long totalCount; private Long criticalCount; private Long warningCount; private Long infoCount; private BigDecimal criticalRate; private BigDecimal growthRate;&#125;@Datapublic class WorkAreaRankVO &#123; private String workArea; private BigDecimal totalOutput; private Integer rankNo; private BigDecimal avgEfficiency;&#125;
统计Service@Service@RequiredArgsConstructorpublic class StatisticsServiceImpl implements StatisticsService &#123; private final DailyOutputMapper outputMapper; private final AlarmMapper alarmMapper; private final RedisTemplate&lt;String, Object&gt; redisTemplate; /** * 日产量统计（带缓存） */ @Override @Cacheable(value = &quot;mine:stats&quot;, key = &quot;&#x27;daily:&#x27; + #startDate + &#x27;:&#x27; + #endDate&quot;) public List&lt;DailyOutputVO&gt; getDailyOutput(LocalDate startDate, LocalDate endDate) &#123; return outputMapper.selectDailyOutput(startDate, endDate); &#125; /** * 告警统计 */ @Override public AlarmStatisticsVO getAlarmStatistics(LocalDate startDate, LocalDate endDate) &#123; String cacheKey = &quot;mine:stats:alarm:&quot; + startDate + &quot;:&quot; + endDate; AlarmStatisticsVO cached = (AlarmStatisticsVO) redisTemplate.opsForValue().get(cacheKey); if (cached != null) return cached; AlarmStatisticsVO vo = alarmMapper.selectAlarmStatistics(startDate, endDate); redisTemplate.opsForValue().set(cacheKey, vo, 30, TimeUnit.MINUTES); return vo; &#125; /** * 工作面产量排名 */ @Override public List&lt;WorkAreaRankVO&gt; getWorkAreaRank(LocalDate startDate, LocalDate endDate, int topN) &#123; return outputMapper.selectWorkAreaRank(startDate, endDate, topN); &#125;&#125;
Mapper XML&lt;!-- 日产量统计 --&gt;&lt;select id=&quot;selectDailyOutput&quot; resultType=&quot;DailyOutputVO&quot;&gt; SELECT output_date AS date, SUM(actual_output) AS dailyOutput, AVG(efficiency) AS efficiency FROM biz_daily_output WHERE output_date &amp;gt;= #&#123;startDate&#125; AND output_date &amp;lt; #&#123;endDate&#125; GROUP BY output_date ORDER BY output_date&lt;/select&gt;&lt;!-- 告警统计（解决问题#5：使用&gt;=和&lt;） --&gt;&lt;select id=&quot;selectAlarmStatistics&quot; resultType=&quot;AlarmStatisticsVO&quot;&gt; SELECT DATE_FORMAT(create_time, &#x27;%Y-%m&#x27;) AS period, COUNT(*) AS totalCount, SUM(CASE WHEN level = &#x27;CRITICAL&#x27; THEN 1 ELSE 0 END) AS criticalCount, SUM(CASE WHEN level = &#x27;WARNING&#x27; THEN 1 ELSE 0 END) AS warningCount, SUM(CASE WHEN level = &#x27;INFO&#x27; THEN 1 ELSE 0 END) AS infoCount, ROUND(SUM(CASE WHEN level = &#x27;CRITICAL&#x27; THEN 1 ELSE 0 END) / COUNT(*) * 100, 2) AS criticalRate FROM biz_alarm WHERE create_time &amp;gt;= #&#123;startDate&#125; AND create_time &amp;lt; #&#123;endDate&#125; GROUP BY DATE_FORMAT(create_time, &#x27;%Y-%m&#x27;) ORDER BY period&lt;/select&gt;&lt;!-- 工作面排名 --&gt;&lt;select id=&quot;selectWorkAreaRank&quot; resultType=&quot;WorkAreaRankVO&quot;&gt; SELECT work_area AS workArea, SUM(actual_output) AS totalOutput, DENSE_RANK() OVER (ORDER BY SUM(actual_output) DESC) AS rankNo, AVG(efficiency) AS avgEfficiency FROM biz_daily_output WHERE output_date &amp;gt;= #&#123;startDate&#125; AND output_date &amp;lt; #&#123;endDate&#125; GROUP BY work_area ORDER BY totalOutput DESC LIMIT #&#123;topN&#125;&lt;/select&gt;
Controller@RestController@RequestMapping(&quot;/statistics&quot;)@RequiredArgsConstructor@Tag(name = &quot;数据统计&quot;)public class StatisticsController &#123; private final StatisticsService statisticsService; @RequirePermission(&quot;stats:output&quot;) @Operation(summary = &quot;日产量统计&quot;) @GetMapping(&quot;/output/daily&quot;) public Result&lt;List&lt;DailyOutputVO&gt;&gt; dailyOutput( @RequestParam @DateTimeFormat(pattern = &quot;yyyy-MM-dd&quot;) LocalDate startDate, @RequestParam @DateTimeFormat(pattern = &quot;yyyy-MM-dd&quot;) LocalDate endDate) &#123; return Result.success(statisticsService.getDailyOutput(startDate, endDate)); &#125; @RequirePermission(&quot;stats:alarm&quot;) @Operation(summary = &quot;告警统计&quot;) @GetMapping(&quot;/alarm&quot;) public Result&lt;AlarmStatisticsVO&gt; alarmStatistics( @RequestParam @DateTimeFormat(pattern = &quot;yyyy-MM-dd&quot;) LocalDate startDate, @RequestParam @DateTimeFormat(pattern = &quot;yyyy-MM-dd&quot;) LocalDate endDate) &#123; return Result.success(statisticsService.getAlarmStatistics(startDate, endDate)); &#125; @RequirePermission(&quot;stats:rank&quot;) @Operation(summary = &quot;工作面排名&quot;) @GetMapping(&quot;/work-area/rank&quot;) public Result&lt;List&lt;WorkAreaRankVO&gt;&gt; workAreaRank( @RequestParam @DateTimeFormat(pattern = &quot;yyyy-MM-dd&quot;) LocalDate startDate, @RequestParam @DateTimeFormat(pattern = &quot;yyyy-MM-dd&quot;) LocalDate endDate, @RequestParam(defaultValue = &quot;10&quot;) Integer topN) &#123; return Result.success(statisticsService.getWorkAreaRank(startDate, endDate, topN)); &#125;&#125;
性能优化索引优化-- 统计查询依赖时间字段，必须加索引（解决问题#1）ALTER TABLE biz_daily_output ADD INDEX idx_output_date(output_date);ALTER TABLE biz_daily_output ADD INDEX idx_area_date(work_area, output_date);ALTER TABLE biz_alarm ADD INDEX idx_create_time(create_time);ALTER TABLE biz_alarm ADD INDEX idx_level_time(level, create_time);-- 复合索引：覆盖统计查询ALTER TABLE biz_daily_output ADD INDEX idx_stats(output_date, work_area, actual_output, efficiency);
预计算统计表-- 每日统计汇总表（解决问题#6）CREATE TABLE stat_daily ( stat_date DATE NOT NULL COMMENT &#x27;统计日期&#x27;, work_area VARCHAR(50) NOT NULL COMMENT &#x27;工作面&#x27;, daily_output DECIMAL(12,2) NOT NULL DEFAULT 0 COMMENT &#x27;日产量&#x27;, efficiency DECIMAL(5,2) DEFAULT NULL COMMENT &#x27;效率&#x27;, alarm_count INT NOT NULL DEFAULT 0 COMMENT &#x27;告警数&#x27;, critical_count INT NOT NULL DEFAULT 0 COMMENT &#x27;严重告警数&#x27;, worker_count INT NOT NULL DEFAULT 0 COMMENT &#x27;出勤人数&#x27;, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (stat_date, work_area), KEY `idx_date` (`stat_date`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=&#x27;每日统计汇总&#x27;;-- 月度统计表CREATE TABLE stat_monthly ( stat_month VARCHAR(7) NOT NULL COMMENT &#x27;统计月份&#x27;, work_area VARCHAR(50) NOT NULL COMMENT &#x27;工作面&#x27;, monthly_output DECIMAL(14,2) NOT NULL DEFAULT 0 COMMENT &#x27;月产量&#x27;, avg_efficiency DECIMAL(5,2) DEFAULT NULL COMMENT &#x27;平均效率&#x27;, alarm_count INT NOT NULL DEFAULT 0, critical_count INT NOT NULL DEFAULT 0, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (stat_month, work_area)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=&#x27;月度统计汇总&#x27;;
定时预计算@Component@RequiredArgsConstructor@Slf4jpublic class StatisticsScheduler &#123; private final StatisticsService statisticsService; /** * 每天凌晨1点统计前一天数据（解决问题#6 #13） */ @Scheduled(cron = &quot;0 0 1 * * ?&quot;) public void generateDailyStat() &#123; LocalDate yesterday = LocalDate.now().minusDays(1); log.info(&quot;开始生成每日统计: date=&#123;&#125;&quot;, yesterday); try &#123; statisticsService.generateDailyStat(yesterday); log.info(&quot;每日统计生成完成: date=&#123;&#125;&quot;, yesterday); &#125; catch (Exception e) &#123; log.error(&quot;每日统计生成失败: date=&#123;&#125;&quot;, yesterday, e); &#125; &#125; /** * 每月1号凌晨2点统计上月数据 */ @Scheduled(cron = &quot;0 0 2 1 * ?&quot;) public void generateMonthlyStat() &#123; YearMonth lastMonth = YearMonth.now().minusMonths(1); log.info(&quot;开始生成月度统计: month=&#123;&#125;&quot;, lastMonth); try &#123; statisticsService.generateMonthlyStat(lastMonth); log.info(&quot;月度统计生成完成: month=&#123;&#125;&quot;, lastMonth); &#125; catch (Exception e) &#123; log.error(&quot;月度统计生成失败: month=&#123;&#125;&quot;, lastMonth, e); &#125; &#125;&#125;
缓存策略/** * 统计缓存管理 */@Component@RequiredArgsConstructorpublic class StatsCacheManager &#123; private final RedisTemplate&lt;String, Object&gt; redisTemplate; private static final String PREFIX = &quot;mine:stats:&quot;; /** * 缓存统计结果（解决问题#4） */ public &lt;T&gt; T getOrCompute(String key, Supplier&lt;T&gt; supplier, long expireMinutes) &#123; String cacheKey = PREFIX + key; T cached = (T) redisTemplate.opsForValue().get(cacheKey); if (cached != null) return cached; T result = supplier.get(); redisTemplate.opsForValue().set(cacheKey, result, expireMinutes, TimeUnit.MINUTES); return result; &#125; /** * 清除统计缓存 */ public void clearCache(String pattern) &#123; Set&lt;String&gt; keys = redisTemplate.keys(PREFIX + pattern + &quot;*&quot;); if (keys != null &amp;&amp; !keys.isEmpty()) &#123; redisTemplate.delete(keys); &#125; &#125; /** * 统计数据更新后清除相关缓存 */ public void onStatDataChange() &#123; clearCache(&quot;daily&quot;); clearCache(&quot;alarm&quot;); clearCache(&quot;rank&quot;); &#125;&#125;
读写分离/** * 统计查询走从库（解决问题#7） */@Service@RequiredArgsConstructorpublic class StatisticsServiceImpl implements StatisticsService &#123; @DS(&quot;slave&quot;) // 使用从库数据源 @Override public List&lt;DailyOutputVO&gt; getDailyOutput(LocalDate startDate, LocalDate endDate) &#123; return outputMapper.selectDailyOutput(startDate, endDate); &#125; @DS(&quot;slave&quot;) @Override public AlarmStatisticsVO getAlarmStatistics(LocalDate startDate, LocalDate endDate) &#123; // ... &#125;&#125;
大屏数据接口/** * 矿山安全大屏数据 */@RestController@RequestMapping(&quot;/dashboard&quot;)@RequiredArgsConstructorpublic class DashboardController &#123; private final StatisticsService statisticsService; /** * 安全大屏综合数据 */ @GetMapping(&quot;/safety&quot;) public Result&lt;SafetyDashboardVO&gt; safetyDashboard() &#123; LocalDate today = LocalDate.now(); LocalDate monthStart = today.withDayOfMonth(1); SafetyDashboardVO vo = new SafetyDashboardVO(); // 今日告警数 vo.setTodayAlarmCount(statisticsService.getTodayAlarmCount()); // 本月告警趋势 vo.setMonthlyAlarmTrend(statisticsService.getAlarmTrend(monthStart, today)); // 设备在线率 vo.setDeviceOnlineRate(statisticsService.getDeviceOnlineRate()); // 井下人数 vo.setUndergroundPersonCount(statisticsService.getUndergroundPersonCount()); // 安全评分 vo.setSafetyScore(statisticsService.getSafetyScore(today)); return Result.success(vo); &#125;&#125;
总结报表统计是实际项目管理层的核心需求。从”写复杂SQL全表扫描”到”聚合统计+预计算+缓存+读写分离”，核心认知是：统计查询是性能杀手，必须用索引+预计算+缓存三重保障。 关键收获：
聚合函数+条件聚合+窗口函数覆盖90%的统计需求 环比同比用窗口函数LAG，比子查询更高效 预计算统计表是大数据量统计的必经之路 缓存策略要考虑数据更新后的失效 时间范围必传、索引覆盖、NULL处理是统计SQL的基本功

前言
在实际场景中，刚写Java的时候，@Override是我接触的第一个注解，当时只知道”加上它就表示重写父类方法”，至于注解是什么、怎么工作的、能不能自定义，完全没概念。直到用了Spring的@Component、@Autowired，我才开始好奇：这些注解到底是怎么起作用的？
注解是什么？注解（Annotation）是Java 5引入的一种元数据机制，为代码提供标记信息，本身不直接执行逻辑。
// 注解就像是给代码贴标签@Override       // 标记：这是重写方法@Deprecated     // 标记：这个方法已过时@SuppressWarnings(&quot;unchecked&quot;)  // 标记：忽略指定警告

关键认知：**注解本身不做任何事，是”读”注解的代码在做事。
内置注解@Override// 编译期检查是否正确重写了父类方法@Overridepublic String toString() &#123;    return &quot;User&quot;;&#125;// 如果拼写错误，编译报错@Overrid  // 拼错public String tostring() &#123; &#125; // 编译报错：没有重写任何方法

@Deprecated// 标记已过时的方法，调用时编译器会警告@Deprecatedpublic void oldMethod() &#123;    // 旧逻辑，建议不再使用&#125;

@SuppressWarnings// 抑制编译器警告@SuppressWarnings(&quot;unchecked&quot;)  // 抑制泛型警告@SuppressWarnings(&quot;rawtypes&quot;)   // 抑制原始类型警告

元注解：定义注解的注解元注解用来修饰自定义注解：
@Target——注解能用在哪里@Target(ElementType.TYPE)         // 类、接口、枚举@Target(ElementType.FIELD)        // 字段@Target(ElementType.METHOD)       // 方法@Target(ElementType.PARAMETER)    // 参数@Target(ElementType.CONSTRUCTOR)  // 构造器@Target(ElementType.LOCAL_VARIABLE) // 局部变量// 可以指定多个@Target(&#123;ElementType.TYPE, ElementType.METHOD&#125;)

@Retention——注解保留到什么时候@Retention(RetentionPolicy.SOURCE)  // 源码阶段，编译后消失（如@Override）@Retention(RetentionPolicy.CLASS)   // 字节码阶段，默认值，运行时不可见@Retention(RetentionPolicy.RUNTIME) // 运行时保留，可通过反射读取（如Spring注解）

@Documented——生成文档时包含@Documented  // Javadoc生成文档时会包含该注解

@Inherited——子类可继承@Inherited  // 父类的注解可以被子类继承

自定义注解基础语法@Target(ElementType.METHOD)@Retention(RetentionPolicy.RUNTIME)public @interface Log &#123;    String value() default &quot;&quot;;    String module() default &quot;&quot;;    boolean enable() default true;&#125;

注解属性的类型限制：

基本类型（int, long, boolean等）
String
Class
枚举
注解
以上类型的数组

实战：自定义日志注解// 1. 定义注解@Target(ElementType.METHOD)@Retention(RetentionPolicy.RUNTIME)public @interface OperationLog &#123;    String value();           // 操作描述    String type() default &quot;QUERY&quot;;  // 操作类型&#125;// 2. 使用注解@Servicepublic class UserService &#123;    @OperationLog(value = &quot;查询用户&quot;, type = &quot;QUERY&quot;)    public User getById(Long id) &#123;        return userMapper.selectById(id);    &#125;    @OperationLog(value = &quot;删除用户&quot;, type = &quot;DELETE&quot;)    public void deleteById(Long id) &#123;        userMapper.deleteById(id);    &#125;&#125;// 3. 通过AOP读取注解并处理@Aspect@Componentpublic class LogAspect &#123;    @Around(&quot;@annotation(operationLog)&quot;)    public Object around(ProceedingJoinPoint joinPoint, OperationLog operationLog) throws Throwable &#123;        // 读取注解信息        String desc = operationLog.value();        String type = operationLog.type();        // 记录操作日志        log.info(&quot;操作类型: &#123;&#125;, 操作描述: &#123;&#125;&quot;, type, desc);        long start = System.currentTimeMillis();        Object result = joinPoint.proceed();        long cost = System.currentTimeMillis() - start;        log.info(&quot;操作耗时: &#123;&#125;ms&quot;, cost);        return result;    &#125;&#125;

实战：参数校验注解// 1. 定义注解@Target(ElementType.FIELD)@Retention(RetentionPolicy.RUNTIME)public @interface Range &#123;    int min() default 0;    int max() default Integer.MAX_VALUE;    String message() default &quot;数值超出范围&quot;;&#125;// 2. 使用注解public class Order &#123;    @Range(min = 1, max = 999, message = &quot;商品数量必须在1-999之间&quot;)    private int quantity;    @Range(min = 0, message = &quot;金额不能为负数&quot;)    private BigDecimal amount;&#125;// 3. 通过反射读取并校验public class Validator &#123;    public static void validate(Object obj) throws IllegalAccessException &#123;        Class&lt;&gt; clazz = obj.getClass();        for (Field field : clazz.getDeclaredFields()) &#123;            if (field.isAnnotationPresent(Range.class)) &#123;                field.setAccessible(true);                Range range = field.getAnnotation(Range.class);                int value = field.getInt(obj);                if (value &lt; range.min() || value &gt; range.max()) &#123;                    throw new IllegalArgumentException(range.message());                &#125;            &#125;        &#125;    &#125;&#125;

Spring常用注解原理Spring的注解之所以能工作，是因为Spring在启动时通过反射扫描并处理了这些注解：
// Spring扫描@Component注解的简化逻辑public void scanComponent(String basePackage) &#123;    Set&lt;Class&lt;&gt;&gt; classes = getClasses(basePackage);    for (Class&lt;&gt; clazz : classes) &#123;        if (clazz.isAnnotationPresent(Component.class)) &#123;            // 创建Bean定义，注册到容器            BeanDefinition bd = new BeanDefinition(clazz);            registry.registerBeanDefinition(clazz.getName(), bd);        &#125;    &#125;&#125;

