本地文件上传基础实现@PostMapping(&quot;/upload/local&quot;)public Result&lt;String&gt; uploadLocal(@RequestParam(&quot;file&quot;) MultipartFile file) &#123;    // 1. 校验    if (file.isEmpty()) &#123;        return Result.fail(&quot;文件不能为空&quot;);    &#125;    if (file.getSize() &gt; 10 * 1024 * 1024) &#123;        return Result.fail(&quot;文件不能超过10MB&quot;);    &#125;    // 2. 生成文件名    String originalName = file.getOriginalFilename();    String ext = originalName.substring(originalName.lastIndexOf(&quot;.&quot;));    String fileName = IdUtil.simpleUUID() + ext;    // 3. 按日期分目录    String datePath = LocalDate.now().format(DateTimeFormatter.ofPattern(&quot;yyyy/MM/dd&quot;));    String dir = &quot;/data/upload/&quot; + datePath;    // 4. 保存文件    try &#123;        File dirFile = new File(dir);        if (!dirFile.exists()) &#123;            dirFile.mkdirs();        &#125;        file.transferTo(new File(dir, fileName));        return Result.success(&quot;/upload/&quot; + datePath + &quot;/&quot; + fileName);    &#125; catch (IOException e) &#123;        log.error(&quot;文件上传失败&quot;, e);        return Result.fail(&quot;文件上传失败&quot;);    &#125;&#125;

本地存储的问题+----------+     +----------+     +----------+| 用户A    |     | 用户B    |     | 用户C    |+----+-----+     +----+-----+     +----+-----+     |                |                |     v                v                v+----+-----+     +----+-----+     +----+-----+| 服务器1   |     | 服务器2   |     | 服务器3   || /data/   |     | /data/   |     | /data/   || upload/  |     | upload/  |     | upload/  || a.jpg    |     | b.jpg    |     | c.jpg    |+----------+     +----------+     +----------+问题1：A上传的文件在服务器1，B从服务器2访问不到问题2：磁盘满了上传失败问题3：没有CDN，跨地区访问慢问题4：备份迁移困难

OSS文件上传阿里云OSS配置&lt;dependency&gt;    &lt;groupId&gt;com.aliyun.oss&lt;/groupId&gt;    &lt;artifactId&gt;aliyun-sdk-oss&lt;/artifactId&gt;    &lt;version&gt;3.15.1&lt;/version&gt;&lt;/dependency&gt;

aliyun:  oss:    endpoint: oss-cn-hangzhou.aliyuncs.com    access-key-id: $&#123;OSS_ACCESS_KEY&#125;    access-key-secret: $&#123;OSS_SECRET_KEY&#125;    bucket-name: smart-mine    url-prefix: https://smart-mine.oss-cn-hangzhou.aliyuncs.com/

OSS工具类@Component@Slf4jpublic class OssUtil &#123;    @Value(&quot;$&#123;aliyun.oss.endpoint&#125;&quot;)    private String endpoint;    @Value(&quot;$&#123;aliyun.oss.access-key-id&#125;&quot;)    private String accessKeyId;    @Value(&quot;$&#123;aliyun.oss.access-key-secret&#125;&quot;)    private String accessKeySecret;    @Value(&quot;$&#123;aliyun.oss.bucket-name&#125;&quot;)    private String bucketName;    @Value(&quot;$&#123;aliyun.oss.url-prefix&#125;&quot;)    private String urlPrefix;    private OSS ossClient;    @PostConstruct    public void init() &#123;        ossClient = new OSSClientBuilder().build(endpoint, accessKeyId, accessKeySecret);        log.info(&quot;OSS客户端初始化完成&quot;);    &#125;    /**     * 上传文件     */    public String upload(String objectName, InputStream inputStream) &#123;        ossClient.putObject(bucketName, objectName, inputStream);        return urlPrefix + objectName;    &#125;    /**     * 上传字节数组     */    public String upload(String objectName, byte[] data) &#123;        ossClient.putObject(bucketName, objectName, new ByteArrayInputStream(data));        return urlPrefix + objectName;    &#125;    /**     * 删除文件     */    public void delete(String objectName) &#123;        ossClient.deleteObject(bucketName, objectName);    &#125;    /**     * 生成签名URL（临时访问，解决问题#9）     */    public String generatePresignedUrl(String objectName, int expireMinutes) &#123;        Date expiration = new Date(System.currentTimeMillis() + expireMinutes * 60 * 1000L);        URL url = ossClient.generatePresignedUrl(bucketName, objectName, expiration);        return url.toString();    &#125;    /**     * 判断文件是否存在     */    public boolean doesObjectExist(String objectName) &#123;        return ossClient.doesObjectExist(bucketName, objectName);    &#125;    @PreDestroy    public void destroy() &#123;        if (ossClient != null) &#123;            ossClient.shutdown();        &#125;    &#125;&#125;

文件上传Service@Service@RequiredArgsConstructor@Slf4jpublic class FileService &#123;    private final OssUtil ossUtil;    private final FileRecordMapper fileRecordMapper;    // 允许的文件类型（白名单，解决问题#3）    private static final Set&lt;String&gt; ALLOWED_TYPES = Set.of(        &quot;image/jpeg&quot;, &quot;image/png&quot;, &quot;image/gif&quot;,        &quot;application/pdf&quot;,        &quot;application/vnd.ms-excel&quot;,        &quot;application/vnd.openxmlformats-officedocument.spreadsheetml.sheet&quot;,        &quot;application/msword&quot;,        &quot;application/vnd.openxmlformats-officedocument.wordprocessingml.document&quot;    );    // 允许的文件扩展名    private static final Set&lt;String&gt; ALLOWED_EXTENSIONS = Set.of(        &quot;.jpg&quot;, &quot;.jpeg&quot;, &quot;.png&quot;, &quot;.gif&quot;, &quot;.pdf&quot;,        &quot;.xls&quot;, &quot;.xlsx&quot;, &quot;.doc&quot;, &quot;.docx&quot;    );    // 最大文件大小：10MB（解决问题#4）    private static final long MAX_SIZE = 10 * 1024 * 1024;    /**     * 上传文件（解决问题#1 #2 #8 #15）     */    @Transactional(rollbackFor = Exception.class)    public FileUploadVO upload(MultipartFile file, String module) &#123;        // 1. 校验文件        validate(file);        // 2. 生成对象名        String objectName = generateObjectName(file, module);        // 3. 上传到OSS        String url;        try &#123;            url = ossUtil.upload(objectName, file.getInputStream());        &#125; catch (IOException e) &#123;            throw new BusinessException(&quot;文件上传失败&quot;);        &#125;        // 4. 记录文件信息（解决问题#15）        FileRecord record = new FileRecord();        record.setOriginalName(file.getOriginalFilename());        record.setObjectName(objectName);        record.setUrl(url);        record.setModule(module);        record.setSize(file.getSize());        record.setContentType(file.getContentType());        record.setUploadUserId(UserContext.getUserId());        fileRecordMapper.insert(record);        return new FileUploadVO(record.getId(), url, file.getOriginalFilename());    &#125;    /**     * 文件校验     */    private void validate(MultipartFile file) &#123;        if (file.isEmpty()) &#123;            throw new BusinessException(&quot;文件不能为空&quot;);        &#125;        if (file.getSize() &gt; MAX_SIZE) &#123;            throw new BusinessException(&quot;文件不能超过10MB&quot;);        &#125;        // Content-Type白名单校验        if (!ALLOWED_TYPES.contains(file.getContentType())) &#123;            throw new BusinessException(&quot;不支持的文件类型: &quot; + file.getContentType());        &#125;        // 扩展名校验        String originalName = file.getOriginalFilename();        String ext = originalName.substring(originalName.lastIndexOf(&quot;.&quot;)).toLowerCase();        if (!ALLOWED_EXTENSIONS.contains(ext)) &#123;            throw new BusinessException(&quot;不支持的文件扩展名: &quot; + ext);        &#125;    &#125;    /**     * 生成对象名（解决问题#8）     * 格式：模块/年/月/日/UUID.ext     */    private String generateObjectName(MultipartFile file, String module) &#123;        String originalName = file.getOriginalFilename();        String ext = originalName.substring(originalName.lastIndexOf(&quot;.&quot;));        String datePath = LocalDate.now().format(DateTimeFormatter.ofPattern(&quot;yyyy/MM/dd&quot;));        String fileName = IdUtil.simpleUUID() + ext;        return module + &quot;/&quot; + datePath + &quot;/&quot; + fileName;        // 例如：inspect/2022/08/31/abc123.jpg    &#125;    /**     * 删除文件（解决问题#11）     */    @Transactional(rollbackFor = Exception.class)    public void delete(Long fileId) &#123;        FileRecord record = fileRecordMapper.selectById(fileId);        if (record == null) &#123;            throw new BusinessException(&quot;文件记录不存在&quot;);        &#125;        // 1. 删除OSS文件        try &#123;            ossUtil.delete(record.getObjectName());        &#125; catch (Exception e) &#123;            log.error(&quot;OSS文件删除失败: objectName=&#123;&#125;&quot;, record.getObjectName(), e);        &#125;        // 2. 删除数据库记录        fileRecordMapper.deleteById(fileId);        log.info(&quot;文件已删除: fileId=&#123;&#125;, objectName=&#123;&#125;&quot;, fileId, record.getObjectName());    &#125;&#125;

文件记录表CREATE TABLE `sys_file_record` (    `id`              BIGINT NOT NULL AUTO_INCREMENT,    `original_name`   VARCHAR(200) NOT NULL COMMENT &#x27;原始文件名&#x27;,    `object_name`     VARCHAR(500) NOT NULL COMMENT &#x27;OSS对象名&#x27;,    `url`             VARCHAR(500) NOT NULL COMMENT &#x27;访问URL&#x27;,    `module`          VARCHAR(50) NOT NULL COMMENT &#x27;业务模块&#x27;,    `biz_id`          BIGINT DEFAULT NULL COMMENT &#x27;关联业务ID&#x27;,    `size`            BIGINT NOT NULL COMMENT &#x27;文件大小(字节)&#x27;,    `content_type`    VARCHAR(100) DEFAULT NULL COMMENT &#x27;文件类型&#x27;,    `upload_user_id`  BIGINT DEFAULT NULL COMMENT &#x27;上传人ID&#x27;,    `create_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,    PRIMARY KEY (`id`),    KEY `idx_module` (`module`, `biz_id`),    KEY `idx_upload_user` (`upload_user_id`, `create_time`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=&#x27;文件记录&#x27;;

Controller@RestController@RequestMapping(&quot;/file&quot;)@RequiredArgsConstructor@Tag(name = &quot;文件管理&quot;)public class FileController &#123;    private final FileService fileService;    @RequirePermission(&quot;file:upload&quot;)    @Operation(summary = &quot;上传文件&quot;)    @PostMapping(&quot;/upload&quot;)    public Result&lt;FileUploadVO&gt; upload(            @RequestParam(&quot;file&quot;) MultipartFile file,            @RequestParam(defaultValue = &quot;common&quot;) String module) &#123;        return Result.success(fileService.upload(file, module));    &#125;    @RequirePermission(&quot;file:upload&quot;)    @Operation(summary = &quot;批量上传&quot;)    @PostMapping(&quot;/upload/batch&quot;)    public Result&lt;List&lt;FileUploadVO&gt;&gt; uploadBatch(            @RequestParam(&quot;files&quot;) MultipartFile[] files,            @RequestParam(defaultValue = &quot;common&quot;) String module) &#123;        List&lt;FileUploadVO&gt; results = Arrays.stream(files)            .map(file -&gt; fileService.upload(file, module))            .collect(Collectors.toList());        return Result.success(results);    &#125;    @RequirePermission(&quot;file:delete&quot;)    @Operation(summary = &quot;删除文件&quot;)    @DeleteMapping(&quot;/&#123;id&#125;&quot;)    public Result&lt;Void&gt; delete(@PathVariable Long id) &#123;        fileService.delete(id);        return Result.success();    &#125;&#125;

图片处理图片魔数校验/** * 图片内容校验（解决问题#3：不只看扩展名） */private static final Map&lt;String, String&gt; IMAGE_MAGIC_NUMBERS = Map.of(    &quot;FFD8FF&quot;,   &quot;JPEG&quot;,    &quot;89504E47&quot;, &quot;PNG&quot;,    &quot;47494638&quot;, &quot;GIF&quot;);private boolean isImage(MultipartFile file) throws IOException &#123;    byte[] bytes = new byte[4];    file.getInputStream().read(bytes);    String hex = Hex.encodeHexString(bytes).toUpperCase();    return IMAGE_MAGIC_NUMBERS.keySet().stream().anyMatch(hex::startsWith);&#125;

图片压缩&lt;dependency&gt;    &lt;groupId&gt;net.coobird&lt;/groupId&gt;    &lt;artifactId&gt;thumbnailator&lt;/artifactId&gt;    &lt;version&gt;0.4.19&lt;/version&gt;&lt;/dependency&gt;

/** * 图片压缩上传（解决问题#6） */public FileUploadVO uploadCompressed(MultipartFile file, String module) &#123;    try &#123;        ByteArrayOutputStream bos = new ByteArrayOutputStream();        Thumbnails.of(file.getInputStream())            .scale(1.0)            .outputQuality(0.8)  // 压缩到80%质量            .toOutputStream(bos);        String objectName = generateObjectName(file, module);        String url = ossUtil.upload(objectName, bos.toByteArray());        return new FileUploadVO(null, url, file.getOriginalFilename());    &#125; catch (IOException e) &#123;        throw new BusinessException(&quot;图片压缩失败&quot;);    &#125;&#125;/** * 生成缩略图（解决问题#12） */public String uploadThumbnail(MultipartFile file, String module) &#123;    try &#123;        ByteArrayOutputStream bos = new ByteArrayOutputStream();        Thumbnails.of(file.getInputStream())            .size(200, 200)       // 缩略图尺寸            .keepAspectRatio(true)            .outputQuality(0.7)            .toOutputStream(bos);        String objectName = generateObjectName(file, module)            .replace(&quot;.&quot;, &quot;_thumb.&quot;);        return ossUtil.upload(objectName, bos.toByteArray());    &#125; catch (IOException e) &#123;        throw new BusinessException(&quot;缩略图生成失败&quot;);    &#125;&#125;/** * 巡检照片上传（原图+缩略图） */public FileUploadVO uploadInspectPhoto(MultipartFile file) &#123;    // 1. 上传原图    FileUploadVO vo = uploadCompressed(file, &quot;inspect&quot;);    // 2. 生成缩略图    String thumbUrl = uploadThumbnail(file, &quot;inspect&quot;);    vo.setThumbUrl(thumbUrl);    return vo;&#125;

大文件分片上传分片上传流程前端                                后端                          OSS+--------+                         +--------+                   +--------+| 1.分片  | -- chunk1(5MB) ------&gt; | 保存到   |                  |        ||    上传  | -- chunk2(5MB) ------&gt; | 临时目录 |                  |        ||        | -- chunk3(5MB) ------&gt; |          |                  |        || 2.通知  | -- merge请求 -------&gt; | 3.合并   | -- 上传合并文件 -&gt; | 4.存储  ||    合并  | &lt;--- 返回URL -------- |          |                  |        |+--------+                         +--------+                   +--------+

分片上传实现/** * 分片上传（解决问题#7） */@RestController@RequestMapping(&quot;/file&quot;)@RequiredArgsConstructor@Slf4jpublic class ChunkUploadController &#123;    private final OssUtil ossUtil;    /**     * 上传分片     */    @PostMapping(&quot;/upload/chunk&quot;)    public Result&lt;Void&gt; uploadChunk(            @RequestParam(&quot;file&quot;) MultipartFile file,            @RequestParam(&quot;chunkIndex&quot;) int chunkIndex,            @RequestParam(&quot;totalChunks&quot;) int totalChunks,            @RequestParam(&quot;fileId&quot;) String fileId) &#123;        // 保存分片到临时目录        Path chunkDir = Paths.get(&quot;/data/temp/chunk&quot;, fileId);        try &#123;            Files.createDirectories(chunkDir);            Path chunkPath = chunkDir.resolve(String.valueOf(chunkIndex));            file.transferTo(chunkPath.toFile());            log.info(&quot;分片上传: fileId=&#123;&#125;, chunk=&#123;&#125;/&#123;&#125;&quot;, fileId, chunkIndex + 1, totalChunks);            return Result.success();        &#125; catch (IOException e) &#123;            throw new BusinessException(&quot;分片上传失败&quot;);        &#125;    &#125;    /**     * 合并分片并上传到OSS     */    @PostMapping(&quot;/upload/merge&quot;)    public Result&lt;String&gt; mergeChunks(            @RequestParam(&quot;fileId&quot;) String fileId,            @RequestParam(&quot;totalChunks&quot;) int totalChunks,            @RequestParam(&quot;fileName&quot;) String fileName) &#123;        Path chunkDir = Paths.get(&quot;/data/temp/chunk&quot;, fileId);        try &#123;            // 1. 合并所有分片            Path mergedFile = Paths.get(&quot;/data/temp/merged&quot;, fileId + &quot;_&quot; + fileName);            Files.createDirectories(mergedFile.getParent());            try (OutputStream os = Files.newOutputStream(mergedFile)) &#123;                for (int i = 0; i &lt; totalChunks; i++) &#123;                    Path chunkPath = chunkDir.resolve(String.valueOf(i));                    Files.copy(chunkPath, os);                &#125;            &#125;            // 2. 上传到OSS            String objectName = &quot;large/&quot; + LocalDate.now().format(DateTimeFormatter.ofPattern(&quot;yyyy/MM/dd&quot;))                + &quot;/&quot; + fileId + &quot;/&quot; + fileName;            String url = ossUtil.upload(objectName, Files.newInputStream(mergedFile));            // 3. 清理临时文件            cleanTempFiles(chunkDir, mergedFile);            log.info(&quot;大文件上传完成: fileId=&#123;&#125;, fileName=&#123;&#125;&quot;, fileId, fileName);            return Result.success(url);        &#125; catch (IOException e) &#123;            throw new BusinessException(&quot;文件合并失败&quot;);        &#125;    &#125;    private void cleanTempFiles(Path chunkDir, Path mergedFile) throws IOException &#123;        // 删除分片        Files.walk(chunkDir)            .sorted(Comparator.reverseOrder())            .map(Path::toFile)            .forEach(File::delete);        // 删除合并文件        Files.deleteIfExists(mergedFile);    &#125;&#125;

文件下载OSS签名URL下载/** * 生成临时下载URL（解决问题#9） */@GetMapping(&quot;/download/&#123;id&#125;&quot;)public Result&lt;String&gt; getDownloadUrl(@PathVariable Long id) &#123;    FileRecord record = fileRecordMapper.selectById(id);    if (record == null) &#123;        throw new BusinessException(&quot;文件不存在&quot;);    &#125;    // 生成1小时有效的签名URL    String signedUrl = ossUtil.generatePresignedUrl(record.getObjectName(), 60);    return Result.success(signedUrl);&#125;

文件预览/** * 图片预览（缩略图） */@GetMapping(&quot;/preview/&#123;id&#125;&quot;)public Result&lt;String&gt; getPreviewUrl(@PathVariable Long id) &#123;    FileRecord record = fileRecordMapper.selectById(id);    if (record == null) &#123;        throw new BusinessException(&quot;文件不存在&quot;);    &#125;    // 优先返回缩略图URL    String thumbName = record.getObjectName().replace(&quot;.&quot;, &quot;_thumb.&quot;);    if (ossUtil.doesObjectExist(thumbName)) &#123;        return Result.success(ossUtil.generatePresignedUrl(thumbName, 60));    &#125;    // 无缩略图返回原图    return Result.success(ossUtil.generatePresignedUrl(record.getObjectName(), 60));&#125;

上传安全限流防刷/** * 上传限流（解决问题#13） */@PostMapping(&quot;/upload&quot;)@RequirePermission(&quot;file:upload&quot;)public Result&lt;FileUploadVO&gt; upload(@RequestParam(&quot;file&quot;) MultipartFile file,                                    @RequestParam String module) &#123;    String rateKey = &quot;mine:upload:rate:&quot; + UserContext.getUserId();    if (!rateLimiter.allow(rateKey, 20, 60)) &#123;        return Result.fail(&quot;上传太频繁，请稍后再试&quot;);    &#125;    return Result.success(fileService.upload(file, module));&#125;

文件类型安全校验校验层级：1. 扩展名校验：.jpg/.png/.pdf/...           （易伪造）2. Content-Type校验：image/jpeg/...          （可伪造）3. 魔数校验：FFD8FF(JPEG)/89504E47(PNG)/...  （最可靠）+-----------+     +-----------+     +-----------+| 扩展名    | --&gt; | Content-  | --&gt; | 魔数校验  || 白名单    |     | Type校验   |     | 读取文件头 |+-----------+     +-----------+     +-----------+     |                 |                  |   通过              通过               通过     |                 |                  |     v                 v                  v   允许上传         允许上传           允许上传

上传组件封装/** * 文件上传VO */@Data@AllArgsConstructor@NoArgsConstructorpublic class FileUploadVO &#123;    private Long fileId;    private String url;    private String originalName;    private String thumbUrl;   // 缩略图URL&#125;/** * 文件记录Entity */@Data@TableName(&quot;sys_file_record&quot;)public class FileRecord &#123;    @TableId(type = IdType.AUTO)    private Long id;    private String originalName;    private String objectName;    private String url;    private String module;    private Long bizId;    private Long size;    private String contentType;    private Long uploadUserId;    private LocalDateTime createTime;&#125;


总结文件上传下载是项目每个模块的基本功能。从本地存储迁移到OSS，核心认知是：文件存储交给专业服务，应用只负责上传和返回URL。
关键收获：

OSS解决了容量、CDN、备份、高可用等所有存储问题
文件校验必须做三重：扩展名+Content-Type+魔数
图片压缩和缩略图是巡检场景的刚需
大文件用分片上传，避免超时
文件记录入库，方便管理和追溯
签名URL控制文件访问权限，保障安全

文件管理后台文件列表查询/** * 文件列表查询 */@GetMapping(&quot;/list&quot;)@RequirePermission(&quot;file:list&quot;)public Result&lt;PageResult&lt;FileRecordVO&gt;&gt; list(FileQueryDTO query) &#123;    return Result.success(fileService.list(query));&#125;

@Service@RequiredArgsConstructorpublic class FileQueryService &#123;    private final FileRecordMapper fileRecordMapper;    public PageResult&lt;FileRecordVO&gt; list(FileQueryDTO query) &#123;        Page&lt;FileRecord&gt; page = new Page&lt;&gt;(query.getPage(), query.getSize());        LambdaQueryWrapper&lt;FileRecord&gt; wrapper = new LambdaQueryWrapper&lt;&gt;();        wrapper.eq(StringUtils.isNotBlank(query.getModule()), FileRecord::getModule, query.getModule())               .eq(query.getBizId() != null, FileRecord::getBizId, query.getBizId())               .like(StringUtils.isNotBlank(query.getOriginalName()), FileRecord::getOriginalName, query.getOriginalName())               .ge(query.getStartTime() != null, FileRecord::getCreateTime, query.getStartTime())               .le(query.getEndTime() != null, FileRecord::getCreateTime, query.getEndTime())               .orderByDesc(FileRecord::getCreateTime);        Page&lt;FileRecord&gt; result = fileRecordMapper.selectPage(page, wrapper);        List&lt;FileRecordVO&gt; voList = result.getRecords().stream()            .map(this::toVO)            .collect(Collectors.toList());        return PageResult.of(voList, result.getTotal(), result.getCurrent(), result.getSize());    &#125;    private FileRecordVO toVO(FileRecord record) &#123;        FileRecordVO vo = new FileRecordVO();        BeanUtils.copyProperties(record, vo);        vo.setSizeDesc(FileSizeUtil.format(record.getSize()));        vo.setUploadUserName(getUserName(record.getUploadUserId()));        return vo;    &#125;&#125;

文件大小格式化工具/** * 文件大小格式化 */public class FileSizeUtil &#123;    private static final long KB = 1024;    private static final long MB = KB * 1024;    private static final long GB = MB * 1024;    public static String format(long size) &#123;        if (size &gt;= GB) &#123;            return String.format(&quot;%.2f GB&quot;, (double) size / GB);        &#125; else if (size &gt;= MB) &#123;            return String.format(&quot;%.2f MB&quot;, (double) size / MB);        &#125; else if (size &gt;= KB) &#123;            return String.format(&quot;%.2f KB&quot;, (double) size / KB);        &#125; else &#123;            return size + &quot; B&quot;;        &#125;    &#125;&#125;

文件清理策略文件清理规则：

文件类型         |  临时文件保留      |  正式文件保留
导入临时文件      |  24小时           |  不保留
导出文件         |  7天              |  不保留
巡检照片         |  永久             |  永久
设备照片         |  永久             |  永久
安全附件         |  永久             |  永久
用户头像         |  永久             |  永久

@Component@RequiredArgsConstructor@Slf4jpublic class FileCleanupScheduler &#123;    private final FileRecordMapper fileRecordMapper;    private final OssUtil ossUtil;    /**     * 每天凌晨3点清理过期临时文件     */    @Scheduled(cron = &quot;0 0 3 * * ?&quot;)    public void cleanupTempFiles() &#123;        LocalDateTime expireTime = LocalDateTime.now().minusDays(1);        // 查询过期的临时文件        List&lt;FileRecord&gt; expiredFiles = fileRecordMapper.selectList(            new LambdaQueryWrapper&lt;FileRecord&gt;()                .eq(FileRecord::getModule, &quot;temp&quot;)                .lt(FileRecord::getCreateTime, expireTime)        );        for (FileRecord record : expiredFiles) &#123;            try &#123;                ossUtil.delete(record.getObjectName());                fileRecordMapper.deleteById(record.getId());            &#125; catch (Exception e) &#123;                log.error(&quot;清理临时文件失败: id=&#123;&#125;&quot;, record.getId(), e);            &#125;        &#125;        log.info(&quot;临时文件清理完成，清理数量：&#123;&#125;&quot;, expiredFiles.size());    &#125;    /**     * 每周日凌晨4点清理过期导出文件     */    @Scheduled(cron = &quot;0 0 4 ? * SUN&quot;)    public void cleanupExportFiles() &#123;        LocalDateTime expireTime = LocalDateTime.now().minusDays(7);        List&lt;FileRecord&gt; expiredFiles = fileRecordMapper.selectList(            new LambdaQueryWrapper&lt;FileRecord&gt;()                .eq(FileRecord::getModule, &quot;export&quot;)                .lt(FileRecord::getCreateTime, expireTime)        );        for (FileRecord record : expiredFiles) &#123;            try &#123;                ossUtil.delete(record.getObjectName());                fileRecordMapper.deleteById(record.getId());            &#125; catch (Exception e) &#123;                log.error(&quot;清理导出文件失败: id=&#123;&#125;&quot;, record.getId(), e);            &#125;        &#125;        log.info(&quot;导出文件清理完成，清理数量：&#123;&#125;&quot;, expiredFiles.size());    &#125;&#125;

存储空间统计/** * 文件存储统计 */@GetMapping(&quot;/stats&quot;)@RequirePermission(&quot;file:list&quot;)public Result&lt;FileStatsVO&gt; getStorageStats() &#123;    return Result.success(fileService.getStorageStats());&#125;

@Datapublic class FileStatsVO &#123;    private Long totalFiles;        // 总文件数    private Long totalSize;         // 总大小(字节)    private String totalSizeDesc;   // 格式化大小    private Map&lt;String, Long&gt; countByModule;   // 各模块文件数    private Map&lt;String, Long&gt; sizeByModule;    // 各模块文件大小&#125;// SQL统计&lt;select id=&quot;selectFileStats&quot; resultType=&quot;map&quot;&gt;    SELECT        module,        COUNT(*) AS file_count,        SUM(size) AS total_size    FROM sys_file_record    GROUP BY module    ORDER BY total_size DESC&lt;/select&gt;

前言 在实际场景中，做订单复制功能时，复制了订单对象后修改了副本，结果原始订单的数据也被改了。排查后才知道是浅拷贝的问题——引用类型字段只是复制了引用，两个对象指向同一份数据。从那以后，我认真搞清楚了深拷贝和浅拷贝的区别。 浅拷贝 vs 深拷贝浅拷贝：创建新对象，但引用类型字段复制引用（指向同一对象）深拷贝：创建新对象，引用类型字段也创建新对象（完全独立）
浅拷贝Cloneable接口public class User implements Cloneable &#123; private String name; private Address address; // 引用类型 @Override protected User clone() throws CloneNotSupportedException &#123; return (User) super.clone(); // 浅拷贝 &#125;&#125;public class Address &#123; private String city; private String street;&#125;// 浅拷贝的问题User user1 = new User(&quot;张三&quot;, new Address(&quot;北京&quot;, &quot;长安街&quot;));User user2 = user1.clone();user2.getAddress().setCity(&quot;上海&quot;);System.out.println(user1.getAddress().getCity()); // 上海！原始数据被改了！// 原因：address字段只是复制了引用// user1.address 和 user2.address 指向同一个Address对象
拷贝构造器public class User &#123; private String name; private Address address; // 拷贝构造器 public User(User other) &#123; this.name = other.name; // String不可变，安全 this.address = other.address; // 引用类型，浅拷贝！ &#125;&#125;
深拷贝方式1：手动深拷贝public class User implements Cloneable &#123; private String name; private Address address; @Override protected User clone() throws CloneNotSupportedException &#123; User cloned = (User) super.clone(); cloned.address = address.clone(); // 递归克隆引用类型 return cloned; &#125;&#125;public class Address implements Cloneable &#123; private String city; private String street; @Override protected Address clone() throws CloneNotSupportedException &#123; return (Address) super.clone(); &#125;&#125;
方式2：拷贝构造器public class User &#123; private String name; private Address address; private List&lt;String&gt; tags; public User(User other) &#123; this.name = other.name; this.address = new Address(other.address); // 深拷贝 this.tags = new ArrayList&lt;&gt;(other.tags); // 深拷贝List &#125;&#125;public class Address &#123; private String city; private String street; public Address(Address other) &#123; this.city = other.city; this.street = other.street; &#125;&#125;
方式3：序列化深拷贝public class DeepCopyUtil &#123; @SuppressWarnings(&quot;unchecked&quot;) public static &lt;T extends Serializable&gt; T deepCopy(T obj) &#123; try &#123; ByteArrayOutputStream bos = new ByteArrayOutputStream(); try (ObjectOutputStream oos = new ObjectOutputStream(bos)) &#123; oos.writeObject(obj); &#125; ByteArrayInputStream bis = new ByteArrayInputStream(bos.toByteArray()); try (ObjectInputStream ois = new ObjectInputStream(bis)) &#123; return (T) ois.readObject(); &#125; &#125; catch (Exception e) &#123; throw new RuntimeException(&quot;深拷贝失败&quot;, e); &#125; &#125;&#125;// 使用User deepCopy = DeepCopyUtil.deepCopy(user);
方式4：JSON序列化深拷贝public class DeepCopyUtil &#123; private static final ObjectMapper MAPPER = new ObjectMapper(); public static &lt;T&gt; T deepCopy(T obj, Class&lt;T&gt; clazz) &#123; try &#123; String json = MAPPER.writeValueAsString(obj); return MAPPER.readValue(json, clazz); &#125; catch (JsonProcessingException e) &#123; throw new RuntimeException(&quot;深拷贝失败&quot;, e); &#125; &#125; public static &lt;T&gt; T deepCopy(T obj, TypeReference&lt;T&gt; typeRef) &#123; try &#123; String json = MAPPER.writeValueAsString(obj); return MAPPER.readValue(json, typeRef); &#125; catch (JsonProcessingException e) &#123; throw new RuntimeException(&quot;深拷贝失败&quot;, e); &#125; &#125;&#125;// 使用User deepCopy = DeepCopyUtil.deepCopy(user, User.class);List&lt;User&gt; deepCopyList = DeepCopyUtil.deepCopy(userList, new TypeReference&lt;List&lt;User&gt;&gt;() &#123;&#125;);
BeanUtils复制Spring BeanUtils// 浅拷贝！引用类型字段只复制引用User target = new User();BeanUtils.copyProperties(source, target);// 注意：// 1. 浅拷贝，引用类型共享// 2. 字段名和类型必须一致// 3. 忽略null字段需要额外处理
Hutool BeanUtil// 浅拷贝User target = BeanUtil.copyProperties(source, User.class);// 忽略null字段CopyOptions options = CopyOptions.create().ignoreNullValue();BeanUtil.copyProperties(source, target, options);
MapStruct（推荐）// 编译期生成代码，性能好，类型安全@Mapperpublic interface UserMapper &#123; UserMapper INSTANCE = Mappers.getMapper(UserMapper.class); UserVO toVO(User user); User toEntity(UserCreateDTO dto); List&lt;UserVO&gt; toVOList(List&lt;User&gt; users);&#125;// 使用UserVO vo = UserMapper.INSTANCE.toVO(user);
实战：DTO&#x2F;VO&#x2F;Entity转换// Entity → VO（返回给前端）public UserVO toVO(User user) &#123; UserVO vo = new UserVO(); vo.setId(user.getId()); vo.setName(user.getName()); vo.setDeptName(user.getDept() != null user.getDept().getName() : null); vo.setCreateTime(user.getCreateTime().format(DateTimeFormatter.ofPattern(&quot;yyyy-MM-dd HH:mm:ss&quot;))); return vo;&#125;// DTO → Entity（前端传入）public User toEntity(UserCreateDTO dto) &#123; User user = new User(); user.setName(dto.getName()); user.setAge(dto.getAge()); user.setDeptId(dto.getDeptId()); return user;&#125;
各种复制方式对比
方式 深浅 性能 适用场景
Cloneable 可深可浅 好 简单对象
拷贝构造器 可深可浅 好 简单对象
序列化 深 差 复杂对象
JSON序列化 深 中 通用
BeanUtils 浅 中 同结构对象
MapStruct 可深可浅 最好 DTO&#x2F;VO转换
常见坑1. BeanUtils浅拷贝引用类型User source = new User();source.setAddress(new Address(&quot;北京&quot;, &quot;长安街&quot;));User target = new User();BeanUtils.copyProperties(source, target);target.getAddress().setCity(&quot;上海&quot;);System.out.println(source.getAddress().getCity()); // 上海！被改了！
2. List的浅拷贝// ❌ 浅拷贝List&lt;User&gt; copy = new ArrayList&lt;&gt;(users);// 修改copy中的User对象，原List也受影响// ✅ 深拷贝List&lt;User&gt; deepCopy = users.stream() .map(u -&gt; DeepCopyUtil.deepCopy(u, User.class)) .collect(Collectors.toList());
3. 数组的浅拷贝int[] arr = &#123;1, 2, 3&#125;;// 浅拷贝（基本类型无所谓）int[] copy1 = arr.clone();int[] copy2 = Arrays.copyOf(arr, arr.length);int[] copy3 = System.arraycopy(arr, 0, new int[3], 0, 3);// 对象数组需要深拷贝User[] users = &#123;new User(&quot;张三&quot;), new User(&quot;李四&quot;)&#125;;User[] deepCopy = Arrays.stream(users).map(u -&gt; DeepCopyUtil.deepCopy(u, User.class)).toArray(User[]::new);
总结 深拷贝和浅拷贝是Java对象复制的核心概念。常见的坑是：以为复制了对象就是独立的，结果引用类型字段共享导致数据被篡改核心认知是：引用类型的复制要格外小心，BeanUtils是浅拷贝，深拷贝用JSON序列化最简单 各种复制方式完整对比
方式 深浅 性能 安全性 适用场景
Cloneable 可深可浅 好 中 简单对象
拷贝构造器 可深可浅 好 高 简单对象
Java序列化 深 差 低 复杂对象
JSON序列化 深 中 高 通用
BeanUtils 浅 中 中 同结构对象
BeanUtil(Hutool) 浅 中 中 同结构对象
MapStruct 可深可浅 最好 最高 DTO&#x2F;VO转换
Spring CopyProperties 浅 中 中 同结构对象
总结深拷贝和浅拷贝是Java对象复制的核心概念。常见的坑是：以为复制了对象就是独立的，结果引用类型字段共享导致数据被篡改。核心认知是：引用类型的复制要格外小心，BeanUtils是浅拷贝，深拷贝用JSON序列化最简单。

前言
在实际场景中，刚写Java的时候，我经常看到List、Map&lt;String, Object&gt;这种带尖括号的写法，只知道这是”泛型”，但为什么要用、怎么用，完全不清楚。直到有一次从集合中取数据时频繁强转类型导致ClassCastException，我才真正理解泛型的价值。
没有泛型的痛苦JDK 1.5之前没有泛型，集合中存取元素都是Object：
// 没有泛型的写法List list = new ArrayList();list.add(&quot;hello&quot;);list.add(123);  // 编译不报错！String str = (String) list.get(1);  // 运行时ClassCastException！

问题很明显：

什么类型都能往里塞，编译器不检查
取出来要强转，转错就崩
错误在运行时才暴露，排查困难

泛型的本质泛型是参数化类型，把类型当作参数传入：
// 有泛型的写法List&lt;String&gt; list = new ArrayList&lt;&gt;();list.add(&quot;hello&quot;);// list.add(123);  // 编译直接报错！String str = list.get(0);  // 无需强转

好处：

编译期类型检查：类型不对直接编译报错
消除强转：取出来就是指定类型
错误前置：从运行时提前到编译期

泛型的使用方式1. 泛型类// 自定义泛型类public class Result&lt;T&gt; &#123;    private int code;    private String msg;    private T data;    public Result(int code, String msg, T data) &#123;        this.code = code;        this.msg = msg;        this.data = data;    &#125;    public T getData() &#123;        return data;    &#125;&#125;// 使用Result&lt;User&gt; userResult = new Result&lt;&gt;(200, &quot;success&quot;, new User());Result&lt;List&lt;Order&gt;&gt; orderResult = new Result&lt;&gt;(200, &quot;success&quot;, orderList);

2. 泛型方法// 泛型方法：&lt;T&gt;在返回值之前public &lt;T&gt; T getById(Long id, Class&lt;T&gt; clazz) &#123;    // 根据id和类型查询    return mapper.selectById(id, clazz);&#125;// 使用User user = getById(1L, User.class);Order order = getById(1L, Order.class);

3. 泛型接口// 经典的Mapper接口public interface BaseMapper&lt;T&gt; &#123;    int insert(T entity);    T selectById(Long id);    int updateById(T entity);    int deleteById(Long id);&#125;// 实现public interface UserMapper extends BaseMapper&lt;User&gt; &#123;    // 自动拥有User类型的CRUD方法&#125;

通配符无界通配符// 可以接收任何类型的Listpublic void printList(List&lt;&gt; list) &#123;    for (Object item : list) &#123;        System.out.println(item);    &#125;&#125;printList(new ArrayList&lt;String&gt;());printList(new ArrayList&lt;Integer&gt;());

&lt; extends T&gt; 上界通配符// 接收T或T的子类public double sum(List&lt; extends Number&gt; list) &#123;    double total = 0;    for (Number n : list) &#123;        total += n.doubleValue();    &#125;    return total;&#125;List&lt;Integer&gt; ints = Arrays.asList(1, 2, 3);List&lt;Double&gt; doubles = Arrays.asList(1.1, 2.2);sum(ints);     // ✅sum(doubles);  // ✅

限制：不能往里添加元素（除了null）
List&lt; extends Number&gt; list = new ArrayList&lt;Integer&gt;();// list.add(1);     // 编译报错// list.add(1.0);   // 编译报错list.add(null);      // 只能加null

&lt; super T&gt; 下界通配符// 接收T或T的父类public void addNumbers(List&lt; super Integer&gt; list) &#123;    list.add(1);    list.add(2);    list.add(3);&#125;List&lt;Number&gt; numbers = new ArrayList&lt;&gt;();List&lt;Object&gt; objects = new ArrayList&lt;&gt;();addNumbers(numbers);  // ✅addNumbers(objects);  // ✅

限制：取出来是Object，需要强转
PECS原则Producer Extends, Consumer Super：

如果要从集合中读取数据（生产者），用&lt; extends T&gt;
如果要往集合中写入数据（消费者），用&lt; super T&gt;
既要读又要写，就不用通配符

// 经典例子：Collections.copy方法public static &lt;T&gt; void copy(List&lt; super T&gt; dest, List&lt; extends T&gt; src) &#123;    for (int i = 0; i &lt; src.size(); i++) &#123;        dest.set(i, src.get(i));  // src是生产者，dest是消费者    &#125;&#125;

类型擦除泛型在编译后会被擦除，替换为原始类型：
// 编译前List&lt;String&gt; list1 = new ArrayList&lt;&gt;();List&lt;Integer&gt; list2 = new ArrayList&lt;&gt;();// 编译后（类型擦除）List list1 = new ArrayList();List list2 = new ArrayList();// 两者运行时类型相同System.out.println(list1.getClass() == list2.getClass()); // true

擦除带来的限制// ❌ 不能用基本类型List&lt;int&gt; list;        // 编译报错List&lt;Integer&gt; list;    // ✅// ❌ 不能new泛型数组T[] array = new T[10]; // 编译报错// ❌ 不能instanceof泛型类型if (obj instanceof List&lt;String&gt;) &#123;&#125;  // 编译报错if (obj instanceof List) &#123;&#125;          // ✅// ❌ 不能new泛型对象T t = new T();  // 编译报错

实际项目中的泛型应用1. 统一返回结果public class Result&lt;T&gt; &#123;    private int code;    private String msg;    private T data;    public static &lt;T&gt; Result&lt;T&gt; success(T data) &#123;        return new Result&lt;&gt;(200, &quot;success&quot;, data);    &#125;    public static &lt;T&gt; Result&lt;T&gt; fail(String msg) &#123;        return new Result&lt;&gt;(500, msg, null);    &#125;&#125;

2. 基础Service封装public class BaseServiceImpl&lt;T, ID&gt; implements BaseService&lt;T, ID&gt; &#123;    protected BaseMapper&lt;T&gt; mapper;    @Override    public T getById(ID id) &#123;        return mapper.selectById(id);    &#125;    @Override    public List&lt;T&gt; listAll() &#123;        return mapper.selectList(null);    &#125;&#125;

总结
泛型是Java类型安全的基石。核心收获是理解了泛型不是”语法糖”，而是一种编译期类型检查机制。虽然运行时会被擦除，但编译期的类型保护已经帮我们规避了大量的ClassCastException。掌握泛型类、泛型方法、通配符和PECS原则，是读懂框架源码的基础。
泛型在实际项目中的应用统一返回结果@Data@Builder@NoArgsConstructor@AllArgsConstructorpublic class Result&lt;T&gt; &#123;    private int code;    private String msg;    private T data;        public static &lt;T&gt; Result&lt;T&gt; success(T data) &#123;        return Result.&lt;T&gt;builder().code(200).msg(&quot;success&quot;).data(data).build();    &#125;        public static &lt;T&gt; Result&lt;T&gt; fail(String msg) &#123;        return Result.&lt;T&gt;builder().code(500).msg(msg).build();    &#125;        public static &lt;T&gt; Result&lt;T&gt; fail(int code, String msg) &#123;        return Result.&lt;T&gt;builder().code(code).msg(msg).build();    &#125;&#125;// 使用Result&lt;DeviceInfo&gt; device = Result.success(deviceInfo);Result&lt;List&lt;AlarmRecord&gt;&gt; alarms = Result.success(alarmList);

基础Service封装public interface BaseService&lt;T, ID&gt; &#123;    T getById(ID id);    List&lt;T&gt; listAll();    Page&lt;T&gt; page(Page&lt;T&gt; page);    boolean save(T entity);    boolean updateById(T entity);    boolean removeById(ID id);&#125;@Servicepublic class DeviceServiceImpl implements BaseService&lt;Device, Long&gt; &#123;    @Autowired    private DeviceMapper deviceMapper;        @Override    public Device getById(Long id) &#123;        return deviceMapper.selectById(id);    &#125;        @Override    public List&lt;Device&gt; listAll() &#123;        return deviceMapper.selectList(null);    &#125;        @Override    public boolean save(Device entity) &#123;        return deviceMapper.insert(entity) &gt; 0;    &#125;&#125;

泛型工具方法@UtilityClasspublic class GenericUtil &#123;        /**     * 列表转换     */    public static &lt;S, T&gt; List&lt;T&gt; convertList(List&lt;S&gt; source,             Function&lt;S, T&gt; converter) &#123;        return source.stream()            .map(converter)            .collect(Collectors.toList());    &#125;        /**     * 分页转换     */    public static &lt;S, T&gt; Page&lt;T&gt; convertPage(Page&lt;S&gt; sourcePage,            Function&lt;S, T&gt; converter) &#123;        Page&lt;T&gt; targetPage = new Page&lt;&gt;(sourcePage.getCurrent(),             sourcePage.getSize(), sourcePage.getTotal());        targetPage.setRecords(            convertList(sourcePage.getRecords(), converter));        return targetPage;    &#125;&#125;

总结泛型是Java类型安全的基石。核心收获是理解了泛型不是语法糖，而是一种编译期类型检查机制。虽然运行时会被擦除，但编译期的类型保护已经帮我们规避了大量的ClassCastException。掌握泛型类、泛型方法、通配符和PECS原则，是读懂框架源码的基础。

前言 实际场景中，用户管理是最基础也是最重要的模块：矿工、班组长、安监人员、管理层，每种角色有不同属性和权限。学了一整年的基础知识，是时候把所有技能串联起来，完成一个完整的CRUD业务模块。用户管理涵盖增删改查、分页、校验、缓存、加密、权限等所有常见需求，是初级开发者的基本功。 本文以实际项目的矿工管理为例，从需求分析、数据库设计到完整代码实现，串联所有知识点。 项目背景智慧矿山系统 - 用户管理模块
用户列表查询（分页、条件筛选、导出） 用户详情查询 新增用户（参数校验、密码加密） 修改用户 删除用户（逻辑删除） 重置密码 修改状态 分配角色 批量导入
技术栈+-----------+ +-----------+ +-----------+ +-----------+| SpringBoot | | MyBatis- | | MySQL | | Redis || 2.7.x | | Plus 3.5 | | 8.0 | | 缓存 |+-----------+ +-----------+ +-----------+ +-----------++-----------+ +-----------+ +-----------+ +-----------+| BCrypt | | EasyExcel | | Swagger | | OSS || 加密 | | 导入导出 | | 文档 | | 文件存储 |+-----------+ +-----------+ +-----------+ +-----------+
需求分析功能清单用户管理功能树
用户查询 +– 列表查询（分页、关键词搜索、状态筛选、部门筛选） +– 详情查询 +– 导出Excel 用户新增 +– 表单校验（用户名唯一、密码强度、手机号格式） +– 密码BCrypt加密 +– 分配默认角色 用户修改 +– 乐观锁并发控制 +– 部分更新（非空字段才更新） 用户删除 +– 逻辑删除 +– 清除角色关联 +– 清除缓存 其他操作 +– 重置密码 +– 修改状态 +– 分配角色
数据库设计CREATE TABLE `sys_user` ( `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT &#x27;主键ID&#x27;, `username` VARCHAR(50) NOT NULL COMMENT &#x27;用户名&#x27;, `password` VARCHAR(100) NOT NULL COMMENT &#x27;密码(BCrypt)&#x27;, `real_name` VARCHAR(50) DEFAULT NULL COMMENT &#x27;真实姓名&#x27;, `employee_no` VARCHAR(30) DEFAULT NULL COMMENT &#x27;工号&#x27;, `phone` VARCHAR(100) DEFAULT NULL COMMENT &#x27;手机号(AES加密)&#x27;, `email` VARCHAR(200) DEFAULT NULL COMMENT &#x27;邮箱&#x27;, `avatar` VARCHAR(500) DEFAULT NULL COMMENT &#x27;头像URL&#x27;, `gender` TINYINT DEFAULT 0 COMMENT &#x27;性别：0-未知 1-男 2-女&#x27;, `dept_id` BIGINT DEFAULT NULL COMMENT &#x27;部门ID&#x27;, `position_id` BIGINT DEFAULT NULL COMMENT &#x27;岗位ID&#x27;, `status` TINYINT NOT NULL DEFAULT 1 COMMENT &#x27;状态：0-禁用 1-启用&#x27;, `remark` VARCHAR(500) DEFAULT NULL COMMENT &#x27;备注&#x27;, `version` INT NOT NULL DEFAULT 1 COMMENT &#x27;乐观锁版本号&#x27;, `deleted` TINYINT NOT NULL DEFAULT 0 COMMENT &#x27;逻辑删除：0-未删除 1-已删除&#x27;, `create_by` BIGINT DEFAULT NULL COMMENT &#x27;创建人ID&#x27;, `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT &#x27;创建时间&#x27;, `update_by` BIGINT DEFAULT NULL COMMENT &#x27;更新人ID&#x27;, `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT &#x27;更新时间&#x27;, PRIMARY KEY (`id`), UNIQUE KEY `uk_username` (`username`, `deleted`), -- 解决问题#5 KEY `idx_phone` (`phone`), KEY `idx_dept_id` (`dept_id`), KEY `idx_status_create_time` (`status`, `create_time`) -- 解决问题#1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=&#x27;用户表&#x27;;
Entity@Data@Builder@TableName(value = &quot;sys_user&quot;, autoResultMap = true)public class User &#123; @TableId(type = IdType.AUTO) private Long id; private String username; private String password; private String realName; private String employeeNo; @TableField(typeHandler = EncryptTypeHandler.class) // AES加密存储 private String phone; private String email; private String avatar; private Integer gender; private Long deptId; private Long positionId; private UserStatus status; private String remark; @Version private Integer version; @TableLogic @TableField(select = false) private Integer deleted; @TableField(fill = FieldFill.INSERT) private Long createBy; @TableField(fill = FieldFill.INSERT) private LocalDateTime createTime; @TableField(fill = FieldFill.INSERT_UPDATE) private Long updateBy; @TableField(fill = FieldFill.INSERT_UPDATE) private LocalDateTime updateTime;&#125;
DTO&#x2F;VO分层查询DTO@Datapublic class UserQueryDTO &#123; @RequestParam(defaultValue = &quot;1&quot;) @Min(value = 1, message = &quot;页码最小为1&quot;) private Integer page; @RequestParam(defaultValue = &quot;10&quot;) @Min(value = 1, message = &quot;每页条数最小为1&quot;) @Max(value = 100, message = &quot;每页条数最大为100&quot;) private Integer size; private String keyword; // 用户名/姓名/手机号/工号 private UserStatus status; private Long deptId; private Long positionId;&#125;
创建DTO@Datapublic class UserCreateDTO &#123; @NotBlank(message = &quot;用户名不能为空&quot;) @Size(min = 3, max = 20, message = &quot;用户名长度3-20&quot;) @Pattern(regexp = &quot;^[a-zA-Z0-9_]+$&quot;, message = &quot;用户名只能包含字母数字下划线&quot;) private String username; @NotBlank(message = &quot;密码不能为空&quot;) @Size(min = 8, max = 20, message = &quot;密码长度8-20&quot;) private String password; private String realName; @Pattern(regexp = &quot;^1[3-9]\\d&#123;9&#125;$&quot;, message = &quot;手机号格式不正确&quot;) private String phone; @Email(message = &quot;邮箱格式不正确&quot;) private String email; private Integer gender; private Long deptId; private Long positionId; private String remark; @NotEmpty(message = &quot;至少分配一个角色&quot;) private List&lt;Long&gt; roleIds;&#125;
更新DTO@Datapublic class UserUpdateDTO &#123; @NotNull(message = &quot;ID不能为空&quot;) private Long id; private String realName; @Pattern(regexp = &quot;^1[3-9]\\d&#123;9&#125;$&quot;, message = &quot;手机号格式不正确&quot;) private String phone; @Email(message = &quot;邮箱格式不正确&quot;) private String email; private Integer gender; private Long deptId; private Long positionId; private UserStatus status; private String remark;&#125;
用户VO@Data@JsonInclude(JsonInclude.Include.NON_NULL)public class UserVO &#123; @JsonSerialize(using = ToStringSerializer.class) private Long id; private String username; private String realName; private String employeeNo; @JsonSerialize(using = PhoneMaskSerializer.class) // 脱敏（问题#10） private String phone; private String email; private String avatar; private Integer gender; private String genderDesc; private Long deptId; private String deptName; private Long positionId; private String positionName; private UserStatus status; private String statusDesc; private String remark; @JsonFormat(pattern = &quot;yyyy-MM-dd HH:mm:ss&quot;) private LocalDateTime createTime; private List&lt;String&gt; roles; // 角色列表&#125;
Service实现用户列表查询@Overridepublic PageResult&lt;UserVO&gt; list(UserQueryDTO query) &#123; Page&lt;User&gt; page = new Page&lt;&gt;(query.getPage(), query.getSize()); // 条件构造（解决问题#15：空条件跳过） LambdaQueryWrapper&lt;User&gt; wrapper = new LambdaQueryWrapper&lt;&gt;(); if (StringUtils.isNotBlank(query.getKeyword())) &#123; wrapper.and(w -&gt; w .like(User::getUsername, query.getKeyword()) .or().like(User::getRealName, query.getKeyword()) .or().like(User::getEmployeeNo, query.getKeyword()) ); &#125; wrapper.eq(query.getStatus() != null, User::getStatus, query.getStatus()) .eq(query.getDeptId() != null, User::getDeptId, query.getDeptId()) .orderByDesc(User::getCreateTime); Page&lt;User&gt; result = this.page(page, wrapper); // 转换VO（解决问题#4：批量查部门） List&lt;UserVO&gt; voList = result.getRecords().stream() .map(this::toVO) .collect(Collectors.toList()); return PageResult.of(voList, result.getTotal(), result.getCurrent(), result.getSize());&#125;// Entity -&gt; VO（解决问题#10 #11）private UserVO toVO(User user) &#123; UserVO vo = new UserVO(); BeanUtils.copyProperties(user, vo); vo.setStatusDesc(user.getStatus().getDesc()); vo.setGenderDesc(getGenderDesc(user.getGender())); // 填充部门名称 if (user.getDeptId() != null) &#123; Dept dept = deptService.getById(user.getDeptId()); if (dept != null) vo.setDeptName(dept.getName()); &#125; // 填充岗位名称 if (user.getPositionId() != null) &#123; Position position = positionService.getById(user.getPositionId()); if (position != null) vo.setPositionName(position.getName()); &#125; // 填充角色 List&lt;String&gt; roleNames = getUserRoleNames(user.getId()); vo.setRoles(roleNames); return vo;&#125;
新增用户@Override@Transactional(rollbackFor = Exception.class)public void add(UserCreateDTO dto) &#123; // 1. 检查用户名唯一（解决问题#2） long count = this.count(new LambdaQueryWrapper&lt;User&gt;() .eq(User::getUsername, dto.getUsername())); if (count &gt; 0) &#123; throw new BusinessException(&quot;用户名已存在&quot;); &#125; // 2. 密码加密（解决问题#3） String encodedPassword = passwordEncoder.encode(dto.getPassword()); // 3. 手机号AES加密 String encryptedPhone = StringUtils.isNotBlank(dto.getPhone()) ? AESUtil.encrypt(dto.getPhone()) : null; // 4. 保存用户 User user = User.builder() .username(dto.getUsername()) .password(encodedPassword) .realName(dto.getRealName()) .phone(encryptedPhone) .email(dto.getEmail()) .gender(dto.getGender() != null ? dto.getGender() : 0) .deptId(dto.getDeptId()) .positionId(dto.getPositionId()) .status(UserStatus.ENABLED) .remark(dto.getRemark()) .build(); this.save(user); // 5. 分配角色 if (dto.getRoleIds() != null &amp;&amp; !dto.getRoleIds().isEmpty()) &#123; assignRoles(user.getId(), dto.getRoleIds()); &#125; log.info(&quot;用户新增成功: username=&#123;&#125;, operator=&#123;&#125;&quot;, dto.getUsername(), UserContext.getUserId());&#125;
修改用户@Override@Transactional(rollbackFor = Exception.class)public void update(UserUpdateDTO dto) &#123; User user = this.getById(dto.getId()); if (user == null) &#123; throw new BusinessException(&quot;用户不存在&quot;); &#125; // 部分更新（非空才更新） if (dto.getRealName() != null) user.setRealName(dto.getRealName()); if (dto.getPhone() != null) user.setPhone(AESUtil.encrypt(dto.getPhone())); if (dto.getEmail() != null) user.setEmail(dto.getEmail()); if (dto.getGender() != null) user.setGender(dto.getGender()); if (dto.getDeptId() != null) user.setDeptId(dto.getDeptId()); if (dto.getPositionId() != null) user.setPositionId(dto.getPositionId()); if (dto.getStatus() != null) user.setStatus(dto.getStatus()); if (dto.getRemark() != null) user.setRemark(dto.getRemark()); // 乐观锁更新（解决问题#8） int updated = userMapper.updateByIdWithVersion(user); if (updated == 0) &#123; throw new BusinessException(&quot;数据已被修改，请刷新后重试&quot;); &#125; // 清除用户缓存 permissionService.clearUserPermCache(dto.getId()); log.info(&quot;用户修改成功: id=&#123;&#125;, operator=&#123;&#125;&quot;, dto.getId(), UserContext.getUserId());&#125;
删除用户@Override@Transactional(rollbackFor = Exception.class)public void delete(Long id) &#123; User user = this.getById(id); if (user == null) &#123; throw new BusinessException(&quot;用户不存在&quot;); &#125; if (&quot;admin&quot;.equals(user.getUsername())) &#123; throw new BusinessException(&quot;不能删除超级管理员&quot;); &#125; // 1. 逻辑删除 this.removeById(id); // 2. 清除角色关联（解决问题#14） userRoleMapper.delete( new LambdaQueryWrapper&lt;UserRole&gt;().eq(UserRole::getUserId, id)); // 3. 清除缓存 permissionService.clearUserPermCache(id); log.info(&quot;用户删除成功: id=&#123;&#125;, username=&#123;&#125;&quot;, id, user.getUsername());&#125;
重置密码@Override@Transactional(rollbackFor = Exception.class)public void resetPassword(Long id) &#123; User user = this.getById(id); if (user == null) &#123; throw new BusinessException(&quot;用户不存在&quot;); &#125; // 生成随机临时密码（解决问题#13中的重置逻辑） String tempPassword = RandomUtil.randomString(&quot;abcdefghijkmnpqrstuvwxyzABCDEFGHJKMNPQRSTUVWXYZ23456789&quot;, 8); user.setPassword(passwordEncoder.encode(tempPassword)); this.updateById(user); // 发送临时密码到手机 String phone = AESUtil.decrypt(user.getPhone()); smsService.sendTempPassword(phone, tempPassword); log.info(&quot;密码重置成功: userId=&#123;&#125;, operator=&#123;&#125;&quot;, id, UserContext.getUserId());&#125;
修改状态@Override@Transactional(rollbackFor = Exception.class)public void updateStatus(Long id, UserStatus status) &#123; LambdaUpdateWrapper&lt;User&gt; wrapper = new LambdaUpdateWrapper&lt;&gt;(); wrapper.eq(User::getId, id).set(User::getStatus, status); this.update(wrapper); // 清除缓存 permissionService.clearUserPermCache(id);&#125;
分配角色@Override@Transactional(rollbackFor = Exception.class)public void assignRoles(Long userId, List&lt;Long&gt; roleIds) &#123; // 1. 删除旧角色 userRoleMapper.delete( new LambdaQueryWrapper&lt;UserRole&gt;().eq(UserRole::getUserId, userId)); // 2. 插入新角色 for (Long roleId : roleIds) &#123; UserRole userRole = new UserRole(); userRole.setUserId(userId); userRole.setRoleId(roleId); userRoleMapper.insert(userRole); &#125; // 3. 清除缓存 permissionService.clearUserPermCache(userId); log.info(&quot;角色分配完成: userId=&#123;&#125;, roleIds=&#123;&#125;&quot;, userId, roleIds);&#125;
Controller@RestController@RequestMapping(&quot;/users&quot;)@RequiredArgsConstructor@Tag(name = &quot;用户管理&quot;)public class UserController &#123; private final UserService userService; @RequirePermission(&quot;user:list&quot;) @Operation(summary = &quot;查询用户列表&quot;) @GetMapping(&quot;/list&quot;) public Result&lt;PageResult&lt;UserVO&gt;&gt; list(@Valid UserQueryDTO query) &#123; return Result.success(userService.list(query)); &#125; @RequirePermission(&quot;user:detail&quot;) @Operation(summary = &quot;查询用户详情&quot;) @GetMapping(&quot;/&#123;id&#125;&quot;) public Result&lt;UserVO&gt; getDetail(@PathVariable Long id) &#123; return Result.success(userService.getDetail(id)); &#125; @RequirePermission(&quot;user:add&quot;) @Operation(summary = &quot;新增用户&quot;) @PostMapping public Result&lt;Void&gt; add(@RequestBody @Valid UserCreateDTO dto) &#123; userService.add(dto); return Result.success(); &#125; @RequirePermission(&quot;user:update&quot;) @Operation(summary = &quot;修改用户&quot;) @PutMapping public Result&lt;Void&gt; update(@RequestBody @Valid UserUpdateDTO dto) &#123; userService.update(dto); return Result.success(); &#125; @RequirePermission(&quot;user:delete&quot;) @Operation(summary = &quot;删除用户&quot;) @DeleteMapping(&quot;/&#123;id&#125;&quot;) public Result&lt;Void&gt; delete(@PathVariable Long id) &#123; userService.delete(id); return Result.success(); &#125; @RequirePermission(&quot;user:resetPwd&quot;) @Operation(summary = &quot;重置密码&quot;) @PutMapping(&quot;/&#123;id&#125;/resetPassword&quot;) public Result&lt;Void&gt; resetPassword(@PathVariable Long id) &#123; userService.resetPassword(id); return Result.success(); &#125; @RequirePermission(&quot;user:update&quot;) @Operation(summary = &quot;修改状态&quot;) @PutMapping(&quot;/&#123;id&#125;/status&quot;) public Result&lt;Void&gt; updateStatus(@PathVariable Long id, @RequestParam UserStatus status) &#123; userService.updateStatus(id, status); return Result.success(); &#125; @RequirePermission(&quot;user:role&quot;) @Operation(summary = &quot;分配角色&quot;) @PutMapping(&quot;/&#123;id&#125;/roles&quot;) public Result&lt;Void&gt; assignRoles(@PathVariable Long id, @RequestBody List&lt;Long&gt; roleIds) &#123; userService.assignRoles(id, roleIds); return Result.success(); &#125;&#125;
全局异常处理@RestControllerAdvice@Slf4jpublic class GlobalExceptionHandler &#123; /** * 业务异常（解决问题#12） */ @ExceptionHandler(BusinessException.class) public Result&lt;Void&gt; handleBusinessException(BusinessException e) &#123; log.warn(&quot;业务异常: &#123;&#125;&quot;, e.getMessage()); return Result.fail(e.getCode(), e.getMessage()); &#125; /** * 参数校验异常 */ @ExceptionHandler(MethodArgumentNotValidException.class) public Result&lt;Void&gt; handleValidException(MethodArgumentNotValidException e) &#123; String message = e.getBindingResult().getFieldErrors().stream() .map(FieldError::getDefaultMessage) .collect(Collectors.joining(&quot;, &quot;)); log.warn(&quot;参数校验失败: &#123;&#125;&quot;, message); return Result.fail(400, message); &#125; /** * 其他异常 */ @ExceptionHandler(Exception.class) public Result&lt;Void&gt; handleException(Exception e) &#123; log.error(&quot;系统异常&quot;, e); return Result.fail(500, &quot;系统繁忙，请稍后再试&quot;); // 不暴露堆栈 &#125;&#125;
自动填充@Componentpublic class MyMetaObjectHandler implements MetaObjectHandler &#123; @Override public void insertFill(MetaObject metaObject) &#123; Long userId = UserContext.getUserId(); this.strictInsertFill(metaObject, &quot;createBy&quot;, Long.class, userId); this.strictInsertFill(metaObject, &quot;createTime&quot;, LocalDateTime.class, LocalDateTime.now()); this.strictInsertFill(metaObject, &quot;updateBy&quot;, Long.class, userId); this.strictInsertFill(metaObject, &quot;updateTime&quot;, LocalDateTime.class, LocalDateTime.now()); &#125; @Override public void updateFill(MetaObject metaObject) &#123; Long userId = UserContext.getUserId(); this.strictUpdateFill(metaObject, &quot;updateBy&quot;, Long.class, userId); this.strictUpdateFill(metaObject, &quot;updateTime&quot;, LocalDateTime.class, LocalDateTime.now()); &#125;&#125;
知识点串联用户管理模块用到的全部知识点：SpringBoot+-- 自动配置+-- 配置文件(yaml)+-- 注解(@Service, @RestController, @Transactional)MyBatis-Plus+-- 条件构造器(LambdaQueryWrapper)+-- 分页查询(Page)+-- 乐观锁(@Version)+-- 逻辑删除(@TableLogic)+-- 自动填充(@TableField(fill))+-- 类型处理器(TypeHandler/AES加密)安全+-- BCrypt密码加密+-- AES敏感数据加密+-- 数据脱敏(VO)+-- 权限注解+AOP工具+-- EasyExcel导入导出+-- Redis缓存+-- OSS文件上传(头像)规范+-- DTO/VO/Entity分层+-- 参数校验@Valid+-- 全局异常处理+-- 统一返回Result+-- 日志规范
总结用户管理模块是实际项目所有知识的综合实战。Entity映射、DTO&#x2F;VO分层、参数校验、全局异常、逻辑删除、乐观锁、BCrypt加密、AES加密、分页查询——每一个知识点都在实战中得到了应用。 关键收获：
DTO&#x2F;VO&#x2F;Entity三层分离是代码规范的基础 参数校验+全局异常+统一返回是接口规范的三件套 逻辑删除+联合唯一索引解决软删除场景的唯一约束问题 BCrypt加密密码+AES加密手机号+VO脱敏是数据安全的标配 乐观锁防并发覆盖是多人操作场景的必要保障 从零到一完成一个完整的CRUD模块，是初级开发者的基本功
批量导入导入DTO@Datapublic class UserImportDTO &#123; @ExcelProperty(&quot;用户名&quot;) private String username; @ExcelProperty(&quot;真实姓名&quot;) private String realName; @ExcelProperty(&quot;工号&quot;) private String employeeNo; @ExcelProperty(&quot;手机号&quot;) private String phone; @ExcelProperty(&quot;邮箱&quot;) private String email; @ExcelProperty(&quot;部门&quot;) private String deptName; @ExcelProperty(&quot;岗位&quot;) private String positionName;&#125;
导入监听器@Slf4jpublic class UserImportListener extends AnalysisEventListener&lt;UserImportDTO&gt; &#123; private final UserService userService; private final DeptService deptService; private final List&lt;UserImportDTO&gt; successList = new ArrayList&lt;&gt;(); private final List&lt;ImportError&gt; errorList = new ArrayList&lt;&gt;(); private int total = 0; private int successCount = 0; public UserImportListener(UserService userService, DeptService deptService) &#123; this.userService = userService; this.deptService = deptService; &#125; @Override public void invoke(UserImportDTO data, AnalysisContext context) &#123; total++; int rowNum = context.readRowHolder().getRowIndex() + 1; // 校验数据 String error = validate(data, rowNum); if (error != null) &#123; errorList.add(new ImportError(rowNum, error)); return; &#125; successList.add(data); // 每500条批量保存 if (successList.size() &gt;= 500) &#123; saveBatch(); &#125; &#125; @Override public void doAfterAllAnalysed(AnalysisContext context) &#123; if (!successList.isEmpty()) &#123; saveBatch(); &#125; log.info(&quot;用户导入完成: 总数=&#123;&#125;, 成功=&#123;&#125;, 失败=&#123;&#125;&quot;, total, successCount, errorList.size()); &#125; private String validate(UserImportDTO data, int rowNum) &#123; if (StringUtils.isBlank(data.getUsername())) &#123; return &quot;第&quot; + rowNum + &quot;行：用户名不能为空&quot;; &#125; if (data.getUsername().length() &lt; 3 || data.getUsername().length() &gt; 20) &#123; return &quot;第&quot; + rowNum + &quot;行：用户名长度3-20&quot;; &#125; if (userService.existsByUsername(data.getUsername())) &#123; return &quot;第&quot; + rowNum + &quot;行：用户名&quot; + data.getUsername() + &quot;已存在&quot;; &#125; return null; &#125; private void saveBatch() &#123; try &#123; userService.importUsers(successList); successCount += successList.size(); &#125; catch (Exception e) &#123; log.error(&quot;批量导入失败&quot;, e); errorList.add(new ImportError(0, &quot;批量保存失败: &quot; + e.getMessage())); &#125; successList.clear(); &#125; public ImportResult getResult() &#123; return new ImportResult(total, successCount, errorList.size(), errorList); &#125;&#125;
导入Service/** * 批量导入用户 */@Override@Transactional(rollbackFor = Exception.class)public void importUsers(List&lt;UserImportDTO&gt; dataList) &#123; for (UserImportDTO dto : dataList) &#123; // 1. 解析部门 Long deptId = null; if (StringUtils.isNotBlank(dto.getDeptName())) &#123; Dept dept = deptService.getByName(dto.getDeptName()); if (dept != null) deptId = dept.getId(); &#125; // 2. 生成默认密码 String defaultPassword = &quot;Mine@&quot; + RandomUtil.randomNumbers(6); String encodedPassword = passwordEncoder.encode(defaultPassword); // 3. 保存用户 User user = User.builder() .username(dto.getUsername()) .password(encodedPassword) .realName(dto.getRealName()) .employeeNo(dto.getEmployeeNo()) .phone(StringUtils.isNotBlank(dto.getPhone()) ? AESUtil.encrypt(dto.getPhone()) : null) .email(dto.getEmail()) .deptId(deptId) .status(UserStatus.ENABLED) .build(); this.save(user); // 4. 分配默认角色（矿工） UserRole userRole = new UserRole(); userRole.setUserId(user.getId()); userRole.setRoleId(6L); // 默认矿工角色 userRoleMapper.insert(userRole); &#125;&#125;
导入Controller@RequirePermission(&quot;user:import&quot;)@Operation(summary = &quot;导入用户&quot;)@PostMapping(&quot;/import&quot;)public Result&lt;ImportResult&gt; importUsers(@RequestParam(&quot;file&quot;) MultipartFile file) throws IOException &#123; // 校验文件 String originalName = file.getOriginalFilename(); if (originalName == null || (!originalName.endsWith(&quot;.xlsx&quot;) &amp;&amp; !originalName.endsWith(&quot;.xls&quot;))) &#123; return Result.fail(&quot;请上传Excel文件&quot;); &#125; if (file.getSize() &gt; 10 * 1024 * 1024) &#123; return Result.fail(&quot;文件大小不能超过10MB&quot;); &#125; UserImportListener listener = new UserImportListener(userService, deptService); EasyExcel.read(file.getInputStream(), UserImportDTO.class, listener).sheet().doRead(); return Result.success(listener.getResult());&#125;@Operation(summary = &quot;下载导入模板&quot;)@GetMapping(&quot;/import/template&quot;)public void downloadTemplate(HttpServletResponse response) throws IOException &#123; response.setContentType(&quot;application/vnd.openxmlformats-officedocument.spreadsheetml.sheet&quot;); response.setHeader(&quot;Content-Disposition&quot;, &quot;attachment; filename=&quot; + URLEncoder.encode(&quot;用户导入模板.xlsx&quot;, &quot;UTF-8&quot;)); EasyExcel.write(response.getOutputStream(), UserImportDTO.class) .sheet(&quot;用户数据&quot;).doWrite(Collections.emptyList());&#125;
用户导出/** * 导出用户列表 */@Datapublic class UserExportVO &#123; @ExcelProperty(&quot;用户名&quot;) private String username; @ExcelProperty(&quot;真实姓名&quot;) private String realName; @ExcelProperty(&quot;工号&quot;) private String employeeNo; @ExcelProperty(&quot;手机号&quot;) private String phone; // 已脱敏 @ExcelProperty(&quot;邮箱&quot;) private String email; @ExcelProperty(&quot;部门&quot;) private String deptName; @ExcelProperty(&quot;岗位&quot;) private String positionName; @ExcelProperty(&quot;状态&quot;) private String statusDesc; @ExcelProperty(value = &quot;创建时间&quot;) @DateTimeFormat(&quot;yyyy-MM-dd HH:mm:ss&quot;) private LocalDateTime createTime;&#125;// Controller@RequirePermission(&quot;user:export&quot;)@Operation(summary = &quot;导出用户列表&quot;)@GetMapping(&quot;/export&quot;)public void exportUsers(UserQueryDTO query, HttpServletResponse response) throws IOException &#123; response.setContentType(&quot;application/vnd.openxmlformats-officedocument.spreadsheetml.sheet&quot;); response.setHeader(&quot;Content-Disposition&quot;, &quot;attachment; filename=&quot; + URLEncoder.encode(&quot;用户列表.xlsx&quot;, &quot;UTF-8&quot;)); List&lt;UserExportVO&gt; list = userService.listForExport(query); EasyExcel.write(response.getOutputStream(), UserExportVO.class) .registerWriteHandler(new MineExportStyleHandler()) .sheet(&quot;用户列表&quot;) .doWrite(list);&#125;
用户详情接口@Overridepublic UserVO getDetail(Long id) &#123; User user = this.getById(id); if (user == null) &#123; throw new BusinessException(&quot;用户不存在&quot;); &#125; UserVO vo = toVO(user); // 填充额外详情信息 vo.setRoles(getUserRoleNames(id)); // 填充最近登录记录 vo.setLastLoginTime(getLastLoginTime(id)); return vo;&#125;/** * 获取用户角色名称列表 */private List&lt;String&gt; getUserRoleNames(Long userId) &#123; List&lt;Long&gt; roleIds = userRoleMapper.selectList( new LambdaQueryWrapper&lt;UserRole&gt;().eq(UserRole::getUserId, userId) ).stream().map(UserRole::getRoleId).collect(Collectors.toList()); if (roleIds.isEmpty()) return Collections.emptyList(); return roleMapper.selectBatchIds(roleIds).stream() .map(Role::getRoleName) .collect(Collectors.toList());&#125;
常见问题与解决方案
问题 原因 解决方案
用户名唯一索引冲突 逻辑删除后重新创建同名用户 联合唯一索引(username, deleted)
分页查询慢 查询条件无索引 添加(status, create_time)复合索引
密码重置后仍用旧密码登录 Token未失效 密码修改清黑名单
导入数据手机号格式乱 无格式校验 正则校验^1[3-9]\d{9}$
导出数据未脱敏 直接导出Entity 使用脱敏VO导出
乐观锁更新失败 并发修改 前端刷新重试

前言 在实际场景中，线上出了问题总是用户先发现，这种被动救火的方式让人很被动。后来学会用SpringBoot Actuator做应用监控，配合告警机制，问题能在第一时间发现和处理。 SpringBoot Actuator依赖&lt;dependency&gt; &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt; &lt;artifactId&gt;spring-boot-starter-actuator&lt;/artifactId&gt;&lt;/dependency&gt;
配置management: endpoints: web: exposure: include: health,info,metrics,env,loggers base-path: /actuator endpoint: health: show-details: when-authorized metrics: enabled: true metrics: tags: application: myapp
常用端点
端点 说明
&#x2F;actuator&#x2F;health 健康检查
&#x2F;actuator&#x2F;metrics 指标数据
&#x2F;actuator&#x2F;env 环境变量
&#x2F;actuator&#x2F;loggers 日志级别
&#x2F;actuator&#x2F;info 应用信息
&#x2F;actuator&#x2F;beans Bean列表
健康检查curl http://localhost:8080/actuator/health&#123; &quot;status&quot;: &quot;UP&quot;, &quot;components&quot;: &#123; &quot;db&quot;: &#123; &quot;status&quot;: &quot;UP&quot; &#125;, &quot;redis&quot;: &#123; &quot;status&quot;: &quot;UP&quot; &#125;, &quot;diskSpace&quot;: &#123; &quot;status&quot;: &quot;UP&quot; &#125; &#125;&#125;
自定义健康检查@Componentpublic class CustomHealthIndicator extends AbstractHealthIndicator &#123; @Autowired private RedisTemplate&lt;String, String&gt; redisTemplate; @Override protected void doHealthCheck(Health.Builder builder) throws Exception &#123; try &#123; redisTemplate.opsForValue().set(&quot;health_check&quot;, &quot;1&quot;, 5, TimeUnit.SECONDS); String value = redisTemplate.opsForValue().get(&quot;health_check&quot;); if (&quot;1&quot;.equals(value)) &#123; builder.up().withDetail(&quot;redis&quot;, &quot;连接正常&quot;); &#125; else &#123; builder.down().withDetail(&quot;redis&quot;, &quot;读写异常&quot;); &#125; &#125; catch (Exception e) &#123; builder.down().withDetail(&quot;redis&quot;, &quot;连接失败: &quot; + e.getMessage()); &#125; &#125;&#125;
指标监控# 查看所有指标curl http://localhost:8080/actuator/metrics# 查看HTTP请求指标curl http://localhost:8080/actuator/metrics/http.server.requests# 查看JVM内存curl http://localhost:8080/actuator/metrics/jvm.memory.used
自定义指标@Service@RequiredArgsConstructorpublic class OrderService &#123; private final MeterRegistry meterRegistry; private final Counter orderCreateCounter; private final Timer orderCreateTimer; public OrderService(MeterRegistry meterRegistry) &#123; this.meterRegistry = meterRegistry; this.orderCreateCounter = Counter.builder(&quot;order.create.count&quot;) .description(&quot;订单创建数量&quot;) .register(meterRegistry); this.orderCreateTimer = Timer.builder(&quot;order.create.time&quot;) .description(&quot;订单创建耗时&quot;) .register(meterRegistry); &#125; public void createOrder(OrderCreateDTO dto) &#123; orderCreateCounter.increment(); orderCreateTimer.record(() -&gt; &#123; doCreateOrder(dto); &#125;); &#125;&#125;
日志监控关键日志埋点// 接口耗时log.info(&quot;接口耗时: uri=&#123;&#125;, cost=&#123;&#125;ms&quot;, uri, cost);// 异常日志log.error(&quot;系统异常: userId=&#123;&#125;&quot;, userId, e);// 业务关键节点log.info(&quot;订单创建: orderId=&#123;&#125;, amount=&#123;&#125;&quot;, orderId, amount);
日志告警脚本#!/bin/bash# check_error.sh - 检查错误日志并发送告警LOG_FILE=/data/logs/app-error.logALERT_KEYWORDS=&quot;OutOfMemoryError|StackOverflowError|Connection refused&quot;ALERT_EMAIL=dev-team@example.com# 检查最近5分钟的错误RECENT_ERRORS=$(find &quot;$LOG_FILE&quot; -mmin -5 -exec grep -c &quot;$ALERT_KEYWORDS&quot; &#123;&#125; \;)if [ &quot;$RECENT_ERRORS&quot; -gt 0 ]; then echo &quot;发现$&#123;RECENT_ERRORS&#125;个严重错误&quot; | mail -s &quot;【告警】应用异常&quot; $ALERT_EMAILfi
应用监控面板Prometheus + Grafana# application.ymlmanagement: endpoints: web: exposure: include: health,info,prometheus metrics: export: prometheus: enabled: true
# prometheus.ymlscrape_configs: - job_name: &#x27;myapp&#x27; metrics_path: /actuator/prometheus static_configs: - targets: [&#x27;localhost:8080&#x27;]
告警机制邮件告警@Component@Slf4jpublic class AlertService &#123; @Autowired private JavaMailSender mailSender; @Value(&quot;$&#123;alert.mail.to&#125;&quot;) private String alertMailTo; public void sendAlert(String subject, String content) &#123; try &#123; SimpleMailMessage message = new SimpleMailMessage(); message.setTo(alertMailTo); message.setSubject(&quot;【告警】&quot; + subject); message.setText(content); mailSender.send(message); log.info(&quot;告警邮件发送成功: &#123;&#125;&quot;, subject); &#125; catch (Exception e) &#123; log.error(&quot;告警邮件发送失败&quot;, e); &#125; &#125;&#125;
钉钉&#x2F;企微告警@Component@Slf4jpublic class DingTalkAlertService &#123; @Value(&quot;$&#123;alert.dingtalk.webhook&#125;&quot;) private String webhook; public void sendAlert(String title, String content) &#123; JSONObject msg = new JSONObject(); msg.put(&quot;msgtype&quot;, &quot;markdown&quot;); JSONObject markdown = new JSONObject(); markdown.put(&quot;title&quot;, title); markdown.put(&quot;text&quot;, &quot;### &quot; + title + &quot;&quot; + content); msg.put(&quot;markdown&quot;, markdown); HttpUtil.post(webhook, msg.toString()); &#125;&#125;
异常自动告警@Aspect@Component@Slf4j@RequiredArgsConstructorpublic class ErrorAlertAspect &#123; private final AlertService alertService; @AfterThrowing(pointcut = &quot;execution(* com.example.service..*.*(..))&quot;, throwing = &quot;ex&quot;) public void afterThrowing(JoinPoint jp, Exception ex) &#123; String className = jp.getTarget().getClass().getSimpleName(); String methodName = jp.getSignature().getName(); String errorMsg = ex.getMessage(); // 只对严重异常告警 if (ex instanceof OutOfMemoryError || ex instanceof StackOverflowError) &#123; alertService.sendAlert( &quot;严重异常: &quot; + className + &quot;.&quot; + methodName, &quot;异常信息: &quot; + errorMsg ); &#125; &#125;&#125;
监控检查清单□ 健康检查接口可用□ 关键接口有耗时日志□ 异常有告警通知□ 慢SQL有监控□ 内存/CPU有监控□ 磁盘空间有监控□ 定时检查日志中的ERROR
总结 监控告警是线上稳定性的保障。从”用户反馈才知道问题”到”主动监控+告警”核心认知是：监控不是事后补救，而是事前预警*Actuator健康检查+关键指标监控+异常告警通知——这三样做好，线上问题无处遁形。

前言 刚写接口时，返回格式随心所欲：有的返回 Map、有的返回对象、有的直接返回字符串，矿端前端同事苦不堪言。在实际场景中，每种接口返回格式都不一样，前端每个接口都要特殊处理，尤其是错误处理逻辑到处重复。后来统一了返回格式，所有接口返回统一的 Result 对象，前后端协作效率大幅提升。 本文将从实际项目的真实场景出发，系统讲解统一返回结果封装的设计、实现和最佳实践。 没有统一返回的痛点// 各种返回格式@GetMapping(&quot;/user&quot;)public User getUser() &#123; return user; &#125; // 直接返回对象@GetMapping(&quot;/status&quot;)public Map&lt;String, Object&gt; getStatus() &#123; ... &#125; // 返回Map@GetMapping(&quot;/count&quot;)public int getCount() &#123; return count; &#125; // 返回基本类型@GetMapping(&quot;/error&quot;)public String getError() &#123; return &quot;error&quot;; &#125; // 返回字符串@GetMapping(&quot;/alarm&quot;)public ResponseEntity&lt;GasAlarm&gt; getAlarm() &#123; ... &#125; // 返回ResponseEntity
前端无法统一处理没有统一返回的痛点
每个接口都要特殊处理 错误处理逻辑到处重复 新接口需要前后端反复确认格式 异常情况返回格式不可预测
统一返回结构Result 类/** * 统一返回结果 */@Datapublic class Result&lt;T&gt; &#123; /** 业务状态码 */ private int code; /** 提示信息 */ private String msg; /** 数据 */ private T data; /** 时间戳 */ private long timestamp; private Result() &#123; this.timestamp = System.currentTimeMillis(); &#125; private Result(int code, String msg, T data) &#123; this.code = code; this.msg = msg; this.data = data; this.timestamp = System.currentTimeMillis(); &#125; // ===== 成功 ===== public static &lt;T&gt; Result&lt;T&gt; success(T data) &#123; return new Result&lt;&gt;(200, &quot;success&quot;, data); &#125; public static &lt;T&gt; Result&lt;T&gt; success() &#123; return new Result&lt;&gt;(200, &quot;success&quot;, null); &#125; public static &lt;T&gt; Result&lt;T&gt; success(String msg, T data) &#123; return new Result&lt;&gt;(200, msg, data); &#125; // ===== 失败 ===== public static &lt;T&gt; Result&lt;T&gt; fail(String msg) &#123; return new Result&lt;&gt;(500, msg, null); &#125; public static &lt;T&gt; Result&lt;T&gt; fail(int code, String msg) &#123; return new Result&lt;&gt;(code, msg, null); &#125; public static &lt;T&gt; Result&lt;T&gt; fail(ResultCode resultCode) &#123; return new Result&lt;&gt;(resultCode.getCode(), resultCode.getMsg(), null); &#125; public static &lt;T&gt; Result&lt;T&gt; fail(ResultCode resultCode, String msg) &#123; return new Result&lt;&gt;(resultCode.getCode(), msg, null); &#125; // ===== 判断 ===== public boolean isSuccess() &#123; return code == 200; &#125;&#125;
返回示例// 成功 - 单个对象&#123; &quot;code&quot;: 200, &quot;msg&quot;: &quot;success&quot;, &quot;data&quot;: &#123; &quot;id&quot;: 1, &quot;mineCode&quot;: &quot;M001&quot;, &quot;location&quot;: &quot;采煤工作面3号&quot;, &quot;concentration&quot;: 0.85, &quot;status&quot;: &quot;PENDING&quot; &#125;, &quot;timestamp&quot;: 1666123456789&#125;// 成功 - 列表&#123; &quot;code&quot;: 200, &quot;msg&quot;: &quot;success&quot;, &quot;data&quot;: &#123; &quot;list&quot;: [...], &quot;total&quot;: 100, &quot;page&quot;: 1, &quot;size&quot;: 10 &#125;, &quot;timestamp&quot;: 1666123456789&#125;// 失败 - 业务异常&#123; &quot;code&quot;: 404, &quot;msg&quot;: &quot;瓦斯报警不存在: 1001&quot;, &quot;data&quot;: null, &quot;timestamp&quot;: 1666123456789&#125;// 失败 - 参数校验&#123; &quot;code&quot;: 400, &quot;msg&quot;: &quot;concentration: 浓度不能为空; mineCode: 矿井编码不能为空&quot;, &quot;data&quot;: null, &quot;timestamp&quot;: 1666123456789&#125;// 失败 - 系统异常&#123; &quot;code&quot;: 500, &quot;msg&quot;: &quot;系统繁忙，请稍后重试&quot;, &quot;data&quot;: null, &quot;timestamp&quot;: 1666123456789&#125;
分页结果封装/** * 分页结果封装 */@Datapublic class PageResult&lt;T&gt; &#123; /** 数据列表 */ private List&lt;T&gt; list; /** 总条数 */ private long total; /** 当前页 */ private long page; /** 每页条数 */ private long size; /** 总页数 */ private long totalPages; public static &lt;T&gt; PageResult&lt;T&gt; of(List&lt;T&gt; list, long total, long page, long size) &#123; PageResult&lt;T&gt; result = new PageResult&lt;&gt;(); result.setList(list); result.setTotal(total); result.setPage(page); result.setSize(size); result.setTotalPages((total + size - 1) / size); return result; &#125; /** * 从MyBatis-Plus的Page转换 */ public static &lt;T&gt; PageResult&lt;T&gt; of(Page&lt;T&gt; page) &#123; return PageResult.of( page.getRecords(), page.getTotal(), page.getCurrent(), page.getSize() ); &#125; /** * 从MyBatis-Plus的IPage转换（带VO转换） */ public static &lt;T, R&gt; PageResult&lt;R&gt; of(Page&lt;T&gt; page, Function&lt;T, R&gt; converter) &#123; List&lt;R&gt; voList = page.getRecords().stream() .map(converter) .collect(Collectors.toList()); return PageResult.of(voList, page.getTotal(), page.getCurrent(), page.getSize()); &#125;&#125;
使用示例@RestController@RequestMapping(&quot;/gas-alarm&quot;)public class GasAlarmController &#123; @GetMapping(&quot;/list&quot;) public Result&lt;PageResult&lt;GasAlarmVO&gt;&gt; list(@Valid GasAlarmQueryDTO query) &#123; Page&lt;GasAlarm&gt; page = gasAlarmService.list(query); return Result.success(PageResult.of(page, this::toVO)); &#125; @GetMapping(&quot;/&#123;id&#125;&quot;) public Result&lt;GasAlarmVO&gt; getById(@PathVariable Long id) &#123; return Result.success(gasAlarmService.getById(id)); &#125; @PostMapping public Result&lt;Void&gt; add(@RequestBody @Valid GasAlarmDTO dto) &#123; gasAlarmService.add(dto); return Result.success(); &#125; @DeleteMapping(&quot;/&#123;id&#125;&quot;) public Result&lt;Void&gt; delete(@PathVariable Long id) &#123; gasAlarmService.delete(id); return Result.success(); &#125;&#125;
业务状态码设计枚举方式/** * 业务状态码枚举 */@Getter@AllArgsConstructorpublic enum ResultCode &#123; // ===== 通用 ===== SUCCESS(200, &quot;操作成功&quot;), FAIL(500, &quot;操作失败&quot;), // ===== 客户端错误 4xx ===== BAD_REQUEST(400, &quot;参数错误&quot;), UNAUTHORIZED(401, &quot;未认证&quot;), FORBIDDEN(403, &quot;无权限&quot;), NOT_FOUND(404, &quot;资源不存在&quot;), METHOD_NOT_ALLOWED(405, &quot;请求方法不允许&quot;), TOO_MANY_REQUESTS(429, &quot;请求过于频繁&quot;), // ===== 用户模块 1xxx ===== USER_NOT_FOUND(1001, &quot;用户不存在&quot;), USER_DISABLED(1002, &quot;用户已禁用&quot;), PASSWORD_ERROR(1003, &quot;密码错误&quot;), USER_EXISTS(1004, &quot;用户已存在&quot;), // ===== 瓦斯模块 2xxx ===== GAS_ALARM_NOT_FOUND(2001, &quot;瓦斯报警不存在&quot;), GAS_ALARM_STATUS_ERROR(2002, &quot;报警状态不允许此操作&quot;), GAS_CONCENTRATION_EXCEED(2003, &quot;瓦斯浓度超标&quot;), // ===== 设备模块 3xxx ===== DEVICE_NOT_FOUND(3001, &quot;设备不存在&quot;), DEVICE_OFFLINE(3002, &quot;设备离线&quot;), DEVICE_CODE_EXISTS(3003, &quot;设备编码已存在&quot;), // ===== 矿井模块 4xxx ===== MINE_NOT_FOUND(4001, &quot;矿井不存在&quot;), MINE_CODE_EXISTS(4002, &quot;矿井编码已存在&quot;), // ===== 人员模块 5xxx ===== PERSON_NOT_FOUND(5001, &quot;人员不存在&quot;), PERSON_IN_MINE(5002, &quot;人员仍在井下，无法删除&quot;), // ===== 订单模块 6xxx ===== ORDER_NOT_FOUND(6001, &quot;工单不存在&quot;), ORDER_STATUS_ERROR(6002, &quot;工单状态不允许此操作&quot;); private final int code; private final String msg;&#125;
状态码设计规范状态码设计规范
HTTP标准码： 200 成功 400 参数错误 401 未认证 403 无权限 404 资源不存在 500 系统异常 业务码规则：模块前缀 + 序号 1xxx 用户模块 2xxx 瓦斯模块 3xxx 设备模块 4xxx 矿井模块 5xxx 人员模块 6xxx 工单模块 … 注意：业务码和HTTP状态码是两套体系 HTTP状态码通常统一返回200 业务码通过Result.code区分
全局返回处理自动包装返回值（不推荐）/** * 自动包装返回值 * 虽然方便，但不推荐使用 */@RestControllerAdvice(basePackages = &quot;com.mine&quot;)public class ResponseAdvice implements ResponseBodyAdvice&lt;Object&gt; &#123; @Override public boolean supports(MethodParameter returnType, Class&lt;? extends HttpMessageConverter&lt;?&gt;&gt; converterType) &#123; // 已经是Result类型的不需要包装 return !returnType.getParameterType().isAssignableFrom(Result.class); &#125; @Override public Object beforeBodyWrite(Object body, MethodParameter returnType, MediaType selectedContentType, Class&lt;? extends HttpMessageConverter&lt;?&gt;&gt; selectedConverterType, ServerHttpRequest request, ServerHttpResponse response) &#123; if (body == null) &#123; return Result.success(); &#125; if (body instanceof Result) &#123; return body; &#125; if (body instanceof String) &#123; // String类型特殊处理，需要转JSON return JSON.toJSONString(Result.success(body)); &#125; return Result.success(body); &#125;&#125;
为什么不推荐自动包装？自动包装的问题
String返回值需要特殊处理 Swagger文档不友好 不够显式，容易出问题 部分接口不想包装
前端统一处理// axios拦截器 - 实际项目前端import axios from &#x27;axios&#x27;import &#123; Message &#125; from &#x27;element-ui&#x27;import router from &#x27;@/router&#x27;import store from &#x27;@/store&#x27;const request = axios.create(&#123; baseURL: &#x27;/api&#x27;, timeout: 30000&#125;)// 请求拦截器request.interceptors.request.use( config =&gt; &#123; const token = store.getters.token if (token) &#123; config.headers[&#x27;Authorization&#x27;] = &#x27;Bearer &#x27; + token &#125; const mineCode = store.getters.currentMineCode if (mineCode) &#123; config.headers[&#x27;X-Mine-Code&#x27;] = mineCode &#125; return config &#125;, error =&gt; Promise.reject(error))// 响应拦截器request.interceptors.response.use( response =&gt; &#123; const result = response.data if (result.code === 200) &#123; // 成功 → 直接返回data return result.data &#125; // 处理Token续期 const newToken = response.headers[&#x27;x-new-token&#x27;] if (newToken) &#123; store.dispatch(&#x27;user/refreshToken&#x27;, newToken) &#125; // 按业务码处理 switch (result.code) &#123; case 401: Message.error(&#x27;登录已过期&#x27;) store.dispatch(&#x27;user/logout&#x27;) router.push(&#x27;/login&#x27;) break case 403: Message.error(&#x27;无操作权限&#x27;) break case 400: Message.warning(result.msg) break case 429: Message.warning(&#x27;操作过于频繁，请稍后再试&#x27;) break default: Message.error(result.msg || &#x27;操作失败&#x27;) &#125; return Promise.reject(result) &#125;, error =&gt; &#123; if (error.response) &#123; switch (error.response.status) &#123; case 401: router.push(&#x27;/login&#x27;) break case 403: Message.error(&#x27;无权限&#x27;) break case 500: Message.error(&#x27;服务器异常&#x27;) break default: Message.error(&#x27;网络异常&#x27;) &#125; &#125; else &#123; Message.error(&#x27;网络异常&#x27;) &#125; return Promise.reject(error) &#125;)export default request
常见问题1. Long 精度丢失// ❌ 前端JS处理Long会丢失精度// &#123;&quot;id&quot;: 1234567890123456789&#125; → JS中变成 1234567890123456800// ✅ Long序列化为String@JsonSerialize(using = ToStringSerializer.class)private Long id;// ✅ 全局配置@Configurationpublic class JacksonConfig &#123; @Bean public ObjectMapper objectMapper() &#123; ObjectMapper mapper = new ObjectMapper(); SimpleModule module = new SimpleModule(); module.addSerializer(Long.class, ToStringSerializer.instance); module.addSerializer(Long.TYPE, ToStringSerializer.instance); mapper.registerModule(module); return mapper; &#125;&#125;
2. null 字段处理// ❌ 返回大量null字段// &#123;&quot;id&quot;: 1, &quot;name&quot;: &quot;张三&quot;, &quot;email&quot;: null, &quot;phone&quot;: null, ...&#125;// ✅ 全局配置不返回null@JsonInclude(JsonInclude.Include.NON_NULL)// 或在类上标注@JsonInclude(JsonInclude.Include.NON_NULL)public class GasAlarmVO &#123; private Long id; private String mineCode; // null字段不会出现在JSON中&#125;// ✅ application.yml全局配置spring: jackson: default-property-inclusion: non_null
3. 日期格式// ❌ 日期返回时间戳// &#123;&quot;createTime&quot;: 1659523200000&#125;// ✅ 指定日期格式@JsonFormat(pattern = &quot;yyyy-MM-dd HH:mm:ss&quot;, timezone = &quot;GMT+8&quot;)private LocalDateTime createTime;// ✅ 全局配置spring: jackson: date-format: yyyy-MM-dd HH:mm:ss time-zone: GMT+8
4. 枚举序列化// ❌ 枚举默认返回name// &#123;&quot;status&quot;: &quot;PENDING&quot;&#125;// ✅ 返回自定义值@JsonFormat(shape = JsonFormat.Shape.OBJECT)public enum AlarmStatus &#123; PENDING(0, &quot;待处理&quot;), HANDLING(1, &quot;处理中&quot;), HANDLED(2, &quot;已处理&quot;); @EnumValue private final int code; @JsonValue private final String desc;&#125;// 返回: &#123;&quot;status&quot;: &quot;待处理&quot;&#125;
5. 敏感字段脱敏// 自定义脱敏注解@Target(ElementType.FIELD)@Retention(RetentionPolicy.RUNTIME)@JacksonAnnotationsInside@JsonSerialize(using = SensitiveDataSerializer.class)public @interface Sensitive &#123; SensitiveType value();&#125;public enum SensitiveType &#123; PHONE, ID_CARD, NAME&#125;public class SensitiveDataSerializer extends JsonSerializer&lt;String&gt; &#123; @Override public void serialize(String value, JsonGenerator gen, SerializerProvider provider) &#123; Sensitive sensitive = gen.getOutputContext().getCurrentValue() .getClass().getDeclaredField(gen.getOutputContext().getCurrentName()) .getAnnotation(Sensitive.class); switch (sensitive.value()) &#123; case PHONE: gen.writeString(value.substring(0, 3) + &quot;****&quot; + value.substring(7)); break; case ID_CARD: gen.writeString(value.substring(0, 4) + &quot;**********&quot; + value.substring(14)); break; case NAME: gen.writeString(value.charAt(0) + &quot;**&quot;); break; &#125; &#125;&#125;// 使用public class PersonVO &#123; @Sensitive(SensitiveType.PHONE) private String phone; @Sensitive(SensitiveType.ID_CARD) private String idCard; @Sensitive(SensitiveType.NAME) private String name;&#125;
总结统一返回结果是接口规范化的第一步。在实际场景中，从”返回格式随意”到”统一 Result 封装”，核心认知是：前后端协作的基础是接口规范，而接口规范的第一步是统一返回格式。Result + PageResult + 全局异常处理，三者组合构成了完整的接口返回体系。 关键收获：
Result 统一封装 是前后端协作的基础 PageResult 分页封装 是列表接口的标配 ResultCode 枚举 是状态码管理的最佳方式 手动返回 Result 比自动包装更可控 Long 转 String + null 不返回 + 日期格式化 是 JSON 序列化的三大注意点
VO与Entity分离为什么需要分离// 直接返回Entity的问题：// 1. 敏感字段泄露（密码、盐值）// 2. 字段太多，前端不需要的也返回了// 3. 数据库结构变化直接影响接口// 4. 不同接口需要返回不同粒度的数据// Entity -&gt; 数据库映射@Data@TableName(&quot;gas_sensor&quot;)public class GasSensor &#123; @TableId(type = IdType.AUTO) private Long id; private String sensorCode; private Long mineId; private BigDecimal threshold; private Integer status; private String remark; private Integer deleted; // 逻辑删除标记 private LocalDateTime createTime; private LocalDateTime updateTime; private Long createBy; private Long updateBy;&#125;// VO -&gt; 接口返回@Datapublic class GasSensorVO &#123; @JsonSerialize(using = ToStringSerializer.class) private Long id; private String sensorCode; private String mineName; // 关联矿井名称 private BigDecimal threshold; private String statusDesc; // 状态描述而非代码 @JsonFormat(pattern = &quot;yyyy-MM-dd HH:mm:ss&quot;, timezone = &quot;GMT+8&quot;) private LocalDateTime createTime;&#125;
转换工具// 方式1：手动转换（最清晰）public class GasSensorConverter &#123; public static GasSensorVO toVO(GasSensor entity) &#123; if (entity == null) return null; GasSensorVO vo = new GasSensorVO(); vo.setId(entity.getId()); vo.setSensorCode(entity.getSensorCode()); vo.setThreshold(entity.getThreshold()); vo.setStatusDesc(entity.getStatus() == 1 ? &quot;在线&quot; : &quot;离线&quot;); vo.setCreateTime(entity.getCreateTime()); return vo; &#125; public static List&lt;GasSensorVO&gt; toVOList(List&lt;GasSensor&gt; entities) &#123; return entities.stream().map(GasSensorConverter::toVO).collect(Collectors.toList()); &#125;&#125;// 方式2：MapStruct（推荐，编译期生成代码）@Mapper(componentModel = &quot;spring&quot;)public interface GasSensorMapper &#123; @Mapping(source = &quot;status&quot;, target = &quot;statusDesc&quot;, qualifiedByName = &quot;statusToDesc&quot;) GasSensorVO toVO(GasSensor entity); List&lt;GasSensorVO&gt; toVOList(List&lt;GasSensor&gt; entities); @Named(&quot;statusToDesc&quot;) default String statusToDesc(Integer status) &#123; return status == 1 ? &quot;在线&quot; : &quot;离线&quot;; &#125;&#125;
DTO -&gt; 请求参数// 请求DTO@Datapublic class GasThresholdUpdateDTO &#123; @NotNull(message = &quot;传感器ID不能为空&quot;) @JsonSerialize(using = ToStringSerializer.class) private Long sensorId; @NotNull(message = &quot;阈值不能为空&quot;) @DecimalMin(value = &quot;0.1&quot;, message = &quot;阈值不能小于0.1&quot;) @DecimalMax(value = &quot;5.0&quot;, message = &quot;阈值不能大于5.0&quot;) private BigDecimal threshold; private String remark;&#125;// Controller@PutMapping(&quot;/threshold&quot;)public Result&lt;Void&gt; updateThreshold(@RequestBody @Valid GasThresholdUpdateDTO dto) &#123; gasMonitorService.updateThreshold(dto); return Result.success();&#125;// Servicepublic void updateThreshold(GasThresholdUpdateDTO dto) &#123; GasSensor sensor = gasSensorMapper.selectById(dto.getSensorId()); if (sensor == null) &#123; throw new BusinessException(ResultCode.GAS_SENSOR_OFFLINE); &#125; sensor.setThreshold(dto.getThreshold()); sensor.setRemark(dto.getRemark()); gasSensorMapper.updateById(sensor);&#125;
接口版本管理// 通过URL路径版本控制@RestController@RequestMapping(&quot;/api/v1/gas-monitor&quot;)public class GasMonitorControllerV1 &#123; @GetMapping(&quot;/&#123;id&#125;&quot;) public Result&lt;GasDataVO&gt; getById(@PathVariable Long id) &#123; // V1版本逻辑 &#125;&#125;@RestController@RequestMapping(&quot;/api/v2/gas-monitor&quot;)public class GasMonitorControllerV2 &#123; @GetMapping(&quot;/&#123;id&#125;&quot;) public Result&lt;GasDataV2VO&gt; getById(@PathVariable Long id) &#123; // V2版本：增加了历史数据 &#125;&#125;// 通过Header版本控制@GetMapping(value = &quot;/&#123;id&#125;&quot;, headers = &quot;X-API-Version=1&quot;)public Result&lt;GasDataVO&gt; getByIdV1(@PathVariable Long id) &#123; ... &#125;@GetMapping(value = &quot;/&#123;id&#125;&quot;, headers = &quot;X-API-Version=2&quot;)public Result&lt;GasDataV2VO&gt; getByIdV2(@PathVariable Long id) &#123; ... &#125;
接口文档与Result// Swagger/Knife4j配合Result返回@Api(tags = &quot;瓦斯监测管理&quot;)@RestController@RequestMapping(&quot;/gas-monitor&quot;)public class GasMonitorController &#123; @ApiOperation(&quot;查询瓦斯数据&quot;) @GetMapping(&quot;/&#123;id&#125;&quot;) public Result&lt;GasDataVO&gt; getById( @ApiParam(&quot;瓦斯数据ID&quot;) @PathVariable Long id) &#123; return Result.success(gasMonitorService.getById(id)); &#125; @ApiOperation(&quot;更新瓦斯阈值&quot;) @PutMapping(&quot;/threshold&quot;) public Result&lt;Void&gt; updateThreshold( @RequestBody @Valid GasThresholdUpdateDTO dto) &#123; gasMonitorService.updateThreshold(dto); return Result.success(); &#125;&#125;
补充：实际项目更多踩坑接口版本管理/** * 接口版本控制 —— 通过URL路径区分版本 */@RestController@RequestMapping(&quot;/api/v1/gas-alarm&quot;)public class GasAlarmControllerV1 &#123; @GetMapping(&quot;/list&quot;) public Result&lt;PageResult&lt;GasAlarmVO&gt;&gt; list(@Valid GasAlarmQueryDTO query) &#123; return Result.success(gasAlarmService.listV1(query)); &#125;&#125;@RestController@RequestMapping(&quot;/api/v2/gas-alarm&quot;)public class GasAlarmControllerV2 &#123; @GetMapping(&quot;/list&quot;) public Result&lt;PageResult&lt;GasAlarmVOV2&gt;&gt; list(@Valid GasAlarmQueryDTO query) &#123; return Result.success(gasAlarmService.listV2(query)); &#125;&#125;
版本管理策略接口版本管理策略
新版本兼容旧版本 旧版本标注废弃@Deprecated 给前端充足的迁移时间 迁移完成后移除旧版本
接口文档与Result配合/** * Swagger文档配合Result封装 */@Api(tags = &quot;瓦斯报警管理&quot;)@RestController@RequestMapping(&quot;/gas-alarm&quot;)public class GasAlarmController &#123; @ApiOperation(&quot;查询瓦斯报警列表&quot;) @ApiResponses(&#123; @ApiResponse(code = 200, message = &quot;成功&quot;, response = Result.class), @ApiResponse(code = 400, message = &quot;参数错误&quot;), @ApiResponse(code = 401, message = &quot;未认证&quot;) &#125;) @GetMapping(&quot;/list&quot;) public Result&lt;PageResult&lt;GasAlarmVO&gt;&gt; list(@Valid GasAlarmQueryDTO query) &#123; return Result.success(gasAlarmService.list(query)); &#125; @ApiOperation(&quot;上报瓦斯报警&quot;) @PostMapping(&quot;/report&quot;) public Result&lt;Void&gt; reportAlarm(@RequestBody @Valid GasAlarmDTO dto) &#123; gasAlarmService.reportAlarm(dto); return Result.success(); &#125;&#125;
Result类的扩展/** * Result扩展 —— 支持更多场景 */@Datapublic class Result&lt;T&gt; &#123; private int code; private String msg; private T data; private long timestamp; // 扩展字段 private String traceId; // 追踪ID private String serverIp; // 服务端IP（排查问题用） // 静态工厂方法扩展 public static &lt;T&gt; Result&lt;T&gt; success(T data, String traceId) &#123; Result&lt;T&gt; result = new Result&lt;&gt;(200, &quot;success&quot;, data); result.setTraceId(traceId); return result; &#125; public static &lt;T&gt; Result&lt;T&gt; fail(ResultCode resultCode, String traceId) &#123; Result&lt;T&gt; result = new Result&lt;&gt;(resultCode.getCode(), resultCode.getMsg(), null); result.setTraceId(traceId); return result; &#125;&#125;
响应体增强/** * 响应增强 —— 自动添加traceId和serverIp */@RestControllerAdvice(basePackages = &quot;com.mine&quot;)public class ResponseEnhanceAdvice implements ResponseBodyAdvice&lt;Object&gt; &#123; @Override public boolean supports(MethodParameter returnType, Class&lt;? extends HttpMessageConverter&lt;?&gt;&gt; converterType) &#123; return true; &#125; @Override public Object beforeBodyWrite(Object body, MethodParameter returnType, MediaType selectedContentType, Class&lt;? extends HttpMessageConverter&lt;?&gt;&gt; selectedConverterType, ServerHttpRequest request, ServerHttpResponse response) &#123; if (body instanceof Result) &#123; Result&lt;?&gt; result = (Result&lt;?&gt;) body; result.setTraceId(MDC.get(&quot;traceId&quot;)); result.setServerIp(getServerIp()); &#125; return body; &#125;&#125;
接口规范检查清单接口规范检查清单
返回格式： 所有接口统一返回 Result 分页接口使用 PageResult 空数据返回空列表而非null 状态码： 200表示成功 4xx表示客户端错误 5xx表示服务端错误 业务码按模块区分（1xxx&#x2F;2xxx&#x2F;…） 数据格式： Long类型转String null字段不返回 日期统一格式yyyy-MM-dd HH:mm:ss 枚举返回友好描述 敏感字段脱敏 前后端协作： 前端统一拦截器处理错误 接口文档与实际返回一致 错误码前后端同步
接口安全与Result接口签名验证/** * 接口签名验证，防止数据篡改 */@Componentpublic class SignatureInterceptor implements HandlerInterceptor &#123; @Override public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) throws Exception &#123; String timestamp = request.getHeader(&quot;X-Timestamp&quot;); String nonce = request.getHeader(&quot;X-Nonce&quot;); String sign = request.getHeader(&quot;X-Sign&quot;); // 1. 验证时间戳（5分钟内有效） long ts = Long.parseLong(timestamp); if (Math.abs(System.currentTimeMillis() - ts) &gt; 5 * 60 * 1000) &#123; writeErrorResponse(response, 401, &quot;请求已过期&quot;); return false; &#125; // 2. 验证nonce（防重放） if (redisTemplate.hasKey(&quot;nonce:&quot; + nonce)) &#123; writeErrorResponse(response, 401, &quot;重复请求&quot;); return false; &#125; redisTemplate.opsForValue().set(&quot;nonce:&quot; + nonce, &quot;1&quot;, Duration.ofMinutes(5)); // 3. 验证签名 String expectedSign = HmacUtil.sign(timestamp + nonce, secretKey); if (!expectedSign.equals(sign)) &#123; writeErrorResponse(response, 401, &quot;签名验证失败&quot;); return false; &#125; return true; &#125;&#125;
数据加密返回// 敏感数据加密返回@GetMapping(&quot;/person/&#123;id&#125;&quot;)public Result&lt;EncryptedData&gt; getPersonInfo(@PathVariable Long id) &#123; PersonVO person = personService.getById(id); // 加密敏感字段 String encrypted = AesUtil.encrypt(JSON.toJSONString(person), secretKey); return Result.success(new EncryptedData(encrypted));&#125;
接口幂等性设计/** * 幂等性注解 */@Target(ElementType.METHOD)@Retention(RetentionPolicy.RUNTIME)public @interface Idempotent &#123; /** 幂等key表达式 */ String key() default &quot;&quot;; /** 过期时间(秒) */ int expire() default 60;&#125;// 切面实现@Aspect@Componentpublic class IdempotentAspect &#123; @Autowired private RedisTemplate&lt;String, String&gt; redisTemplate; @Around(&quot;@annotation(idempotent)&quot;) public Object around(ProceedingJoinPoint pjp, Idempotent idempotent) throws Throwable &#123; String key = &quot;idempotent:&quot; + buildKey(pjp, idempotent.key()); Boolean absent = redisTemplate.opsForValue() .setIfAbsent(key, &quot;1&quot;, Duration.ofSeconds(idempotent.expire())); if (Boolean.FALSE.equals(absent)) &#123; // 已处理过，返回上次的结果 String cachedResult = redisTemplate.opsForValue().get(key + &quot;:result&quot;); if (cachedResult != null) &#123; return JSON.parseObject(cachedResult, Result.class); &#125; throw new BusinessException(&quot;请勿重复提交&quot;); &#125; Object result = pjp.proceed(); // 缓存结果 if (result instanceof Result) &#123; redisTemplate.opsForValue().set(key + &quot;:result&quot;, JSON.toJSONString(result), Duration.ofSeconds(idempotent.expire())); &#125; return result; &#125;&#125;// 使用：通风控制指令幂等@Idempotent(key = &quot;#dto.deviceId + &#x27;:&#x27; + #dto.command&quot;, expire = 10)@PostMapping(&quot;/vent/control&quot;)public Result&lt;Void&gt; controlVent(@RequestBody @Valid VentControlDTO dto) &#123; ventService.control(dto); return Result.success();&#125;
接口性能与Result大数据量分页优化// 游标分页（避免深分页性能问题）@GetMapping(&quot;/gas-data/cursor&quot;)public Result&lt;List&lt;GasDataVO&gt;&gt; listByCursor( @RequestParam(required = false) Long lastId, @RequestParam(defaultValue = &quot;20&quot;) int size) &#123; List&lt;GasDataVO&gt; list = gasMonitorService.listByCursor(lastId, size); return Result.success(list);&#125;
字段过滤// 动态字段过滤（前端指定返回哪些字段）@GetMapping(&quot;/gas/&#123;id&#125;&quot;)public Result&lt;Map&lt;String, Object&gt;&gt; getById( @PathVariable Long id, @RequestParam(required = false) String fields) &#123; GasDataVO data = gasMonitorService.getById(id); if (StringUtils.isBlank(fields)) &#123; return Result.success(BeanUtil.beanToMap(data)); &#125; // 只返回指定字段 Map&lt;String, Object&gt; filtered = new HashMap&lt;&gt;(); for (String field : fields.split(&quot;,&quot;)) &#123; filtered.put(field, ReflectUtil.getFieldValue(data, field)); &#125; return Result.success(filtered);&#125;
接口规范完整检查表
检查项 说明 状态
统一返回Result 所有接口返回Result -
状态码枚举 ResultCode业务码体系 -
分页封装 PageResult -
Long转String @JsonSerialize -
null不返回 @JsonInclude(NON_NULL) -
日期格式化 @JsonFormat -
Entity-VO分离 不直接返回Entity -
DTO校验 @Valid + @Validated -
全局异常处理 @RestControllerAdvice -
接口签名 敏感接口签名验证 -
幂等设计 重复提交防护 -
Swagger文档 @ApiOperation等 -
接口版本 v1&#x2F;v2版本管理 -
敏感数据加密 AES加密返回 -
字段过滤 动态返回指定字段 -

前言 在实际场景中，代码写完了只在本地能跑不算完，必须部署到服务器上才能让用户访问。最初我只会用java -jar启动项目，后来学会了打包、配置、Nginx代理、进程守护，部署流程越来越规范。 打包Maven打包# 清理+打包，跳过测试mvn clean package -DskipTests# 产物在target目录# target/myapp-1.0.0.jar
SpringBoot打包配置&lt;build&gt; &lt;finalName&gt;myapp&lt;/finalName&gt; &lt;plugins&gt; &lt;plugin&gt; &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt; &lt;artifactId&gt;spring-boot-maven-plugin&lt;/artifactId&gt; &lt;configuration&gt; &lt;excludes&gt; &lt;exclude&gt; &lt;groupId&gt;org.projectlombok&lt;/groupId&gt; &lt;artifactId&gt;lombok&lt;/artifactId&gt; &lt;/exclude&gt; &lt;/excludes&gt; &lt;/configuration&gt; &lt;/plugin&gt; &lt;/plugins&gt;&lt;/build&gt;
上传到服务器# scp上传scp target/myapp.jar root@192.168.1.100:/data/app/# 或使用FTP工具（FileZilla等）
启动应用基础启动# 前台启动（关闭终端就停止）java -jar myapp.jar# 后台启动nohup java -jar myapp.jar &gt; app.log 2&gt;&amp;1 &amp;# 查看进程ps -ef | grep myapp# 停止kill &lt;pid&gt;
生产环境启动脚本#!/bin/bash# deploy.shAPP_NAME=myappAPP_HOME=/data/appJAR_NAME=$&#123;APP_NAME&#125;.jarPID_FILE=$&#123;APP_HOME&#125;/$&#123;APP_NAME&#125;.pidLOG_FILE=$&#123;APP_HOME&#125;/logs/app.log# JVM参数JVM_OPTS=&quot;-Xms512m -Xmx2g -XX:+UseG1GC -XX:+HeapDumpOnOutOfMemoryError&quot;# Spring参数SPRING_OPTS=&quot;--spring.profiles.active=prod&quot;case &quot;$1&quot; in start) if [ -f &quot;$PID_FILE&quot; ]; then PID=$(cat $PID_FILE) if ps -p $PID &gt; /dev/null; then echo &quot;$APP_NAME is already running (PID: $PID)&quot; exit 1 fi fi echo &quot;Starting $APP_NAME...&quot; nohup java $JVM_OPTS -jar $&#123;APP_HOME&#125;/$&#123;JAR_NAME&#125; $SPRING_OPTS &gt; $LOG_FILE 2&gt;&amp;1 &amp; echo $! &gt; $PID_FILE echo &quot;$APP_NAME started (PID: $!)&quot; ;; stop) if [ -f &quot;$PID_FILE&quot; ]; then PID=$(cat $PID_FILE) echo &quot;Stopping $APP_NAME (PID: $PID)...&quot; kill $PID rm -f $PID_FILE echo &quot;$APP_NAME stopped&quot; else echo &quot;$APP_NAME is not running&quot; fi ;; restart) $0 stop sleep 3 $0 start ;; status) if [ -f &quot;$PID_FILE&quot; ]; then PID=$(cat $PID_FILE) if ps -p $PID &gt; /dev/null; then echo &quot;$APP_NAME is running (PID: $PID)&quot; else echo &quot;$APP_NAME is not running (stale PID file)&quot; fi else echo &quot;$APP_NAME is not running&quot; fi ;; *) echo &quot;Usage: $0 &#123;start|stop|restart|status&#125;&quot; exit 1 ;;esac
# 使用chmod +x deploy.sh./deploy.sh start./deploy.sh stop./deploy.sh restart./deploy.sh status
Nginx反向代理安装Nginx# CentOSyum install nginx# Ubuntuapt install nginx
配置# /etc/nginx/conf.d/myapp.confupstream backend &#123; server 127.0.0.1:8080; # 多实例 # server 127.0.0.1:8081; # server 127.0.0.1:8082;&#125;server &#123; listen 80; server_name api.example.com; # SSL配置（HTTPS） # listen 443 ssl; # ssl_certificate /etc/nginx/ssl/api.example.com.pem; # ssl_certificate_key /etc/nginx/ssl/api.example.com.key; # 请求体大小限制 client_max_body_size 20m; # API代理 location /api/ &#123; proxy_pass http://backend/; proxy_set_header Host $host; proxy_set_header X-Real-IP $remote_addr; proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for; proxy_set_header X-Forwarded-Proto $scheme; # 超时设置 proxy_connect_timeout 60s; proxy_read_timeout 120s; proxy_send_timeout 60s; &#125; # 前端静态文件 location / &#123; root /data/app/dist; index index.html; try_files $uri $uri/ /index.html; # Vue Router history模式 &#125; # 健康检查 location /health &#123; proxy_pass http://backend/actuator/health; &#125; # 日志 access_log /var/log/nginx/myapp_access.log; error_log /var/log/nginx/myapp_error.log;&#125;
常用命令# 检查配置nginx -t# 重载配置nginx -s reload# 启动systemctl start nginx# 停止systemctl stop nginx# 重启systemctl restart nginx# 开机自启systemctl enable nginx
健康检查# application.ymlmanagement: endpoints: web: exposure: include: health,info endpoint: health: show-details: when-authorized
# 健康检查curl http://localhost:8080/actuator/health
日志管理日志目录结构/data/app/├── myapp.jar├── deploy.sh└── logs/ ├── app.log # 应用日志 ├── app.2022-12-30.log # 按天滚动 ├── gc.log # GC日志 └── heapdump.hprof # 堆dump
JVM参数增加GC日志JVM_OPTS=&quot;-Xms512m -Xmx2g -XX:+UseG1GC -Xloggc:/data/app/logs/gc.log -XX:+PrintGCDetails -XX:+PrintGCDateStamps -XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath=/data/app/logs/&quot;
常见问题排查1. 端口被占用# 查看端口占用netstat -tlnp | grep 8080lsof -i :8080# 杀掉占用进程kill -9 &lt;pid&gt;
2. 内存不足# 查看内存free -h# 查看Java进程内存jmap -heap &lt;pid&gt;# 调整JVM参数-Xms256m -Xmx512m
3. 磁盘满# 查看磁盘df -h# 查看大文件du -sh /data/* | sort -rh | head -10# 清理日志find /data/logs -name &quot;*.log&quot; -mtime +7 -delete
4. 应用无响应# 查看线程dumpjstack &lt;pid&gt; &gt; thread_dump.txt# 查看是否有死锁grep &quot;BLOCKED&quot; thread_dump.txt# 查看CPU占用top -H -p &lt;pid&gt;
部署检查清单□ 配置文件：数据库、Redis、OSS等连接信息正确□ JVM参数：内存、GC、堆dump配置□ Nginx配置：反向代理、SSL、超时□ 日志配置：输出到文件、按天滚动□ 健康检查：/actuator/health可访问□ 防火墙：只开放80/443端口□ 进程守护：应用挂掉自动重启□ 备份策略：数据库定期备份□ 监控告警：应用异常时通知
总结 项目部署是开发的最后一公里。从”只会java -jar”到”脚本化+Nginx+日志管理”核心认知是：部署不是一次性操作，而是可重复的标准化流程*启动脚本、Nginx配置、日志管理——这三样做好了，部署就不再是噩梦。

前言 实际场景中，权限控制是最核心的安全需求。矿井下有矿长、调度员、安全员、维修工等数十种角色，每种角色能访问的系统模块完全不同。最初我用硬编码 if-else 判断权限，随着角色从 5 个增长到 30 多个，代码变成了一团乱麻——改一个权限要改十几个地方，新加角色怕遗漏权限，删除角色怕残留入口。学习 RBAC 模型后，用户-角色-权限三层设计让权限管理变得清晰灵活。本文结合实际项目的真实场景，完整还原 RBAC 从设计到落地的全过程。 一、为什么需要 RBAC1.1 硬编码权限的痛点硬编码权限的维护噩梦 1.2 RBAC 模型概述RBAC 核心模型
+——–+ +——–+ +————+ | 用户 | N:N | 角色 | N:N | 权限 | | (User) +——&gt;+ (Role) +——&gt;+ (Permission)| +——–+ +——–+ +————+ | | | v v v 张三&#x2F;李四 矿长&#x2F;调度员 人员管理:查询 王五&#x2F;赵六 安全员&#x2F;维修工 设备监控:操作 报警处置:确认 一个用户可以拥有多个角色 一个角色可以拥有多个权限 用户通过角色间接获得权限
1.3 RBAC 扩展模型对比实际项目采用 RBAC1 模型，角色继承关系如下：
模型层级 | 能力描述 | 适用场景 RBAC0 | 用户-角色-权限 基础映射 | 小型项目 RBAC1 | RBAC0 + 角色继承（矿长继承调度员权限） | 层级分明的组织 RBAC2 | RBAC0 + 互斥约束（审批人和提交人不能同一角色） | 需要审计的系统 RBAC3 | RBAC1 + RBAC2 完整合集 | 企业级系统 角色继承树 矿长(ADMIN) | +————-+————-+ | | | 副矿长 调度总监 安全总监 | | | +—-+—-+ +—-+—-+ +——+——+ | | | | | | | 区段长 机电主管 调度员 监控员 安全员 瓦检员 通风员 | | | 班组长 操作员 巡检员
二、数据库设计2.1 ER 关系图RBAC 数据库 ER 图
+————-+ +—————+ +————–+ | sys_user | | sys_user_role | | sys_role | +————-+ +—————+ +————–+ | *id |&lt;–&gt;| *id | | *id | | username | | user_id (FK) |—&gt;| role_name | | password | | role_id (FK) |—&gt;| role_code | | real_name | +—————+ | parent_id | | phone | | description | | status | | status | +————-+ +——-+——+ | +————+———-+ | sys_role_permission | +————————+ | *id | | role_id (FK) ———+ | permission_id (FK) —+–+ +————————+ | | +———————-+ | sys_permission | +———————-+ | *id | | parent_id | | name | | type (1菜单 2按钮) | | permission | | path | | icon | | sort | +———————-+
2.2 用户表（sys_user）CREATE TABLE `sys_user` ( `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT &#x27;主键ID&#x27;, `username` VARCHAR(50) NOT NULL COMMENT &#x27;用户名&#x27;, `password` VARCHAR(100) NOT NULL COMMENT &#x27;密码&#x27;, `real_name` VARCHAR(50) DEFAULT NULL COMMENT &#x27;真实姓名&#x27;, `phone` VARCHAR(20) DEFAULT NULL COMMENT &#x27;手机号&#x27;, `email` VARCHAR(200) DEFAULT NULL COMMENT &#x27;邮箱&#x27;, `avatar` VARCHAR(500) DEFAULT NULL COMMENT &#x27;头像URL&#x27;, `gender` TINYINT DEFAULT 0 COMMENT &#x27;性别：0-未知 1-男 2-女&#x27;, `dept_id` BIGINT DEFAULT NULL COMMENT &#x27;部门ID&#x27;, `status` TINYINT NOT NULL DEFAULT 1 COMMENT &#x27;状态：0-禁用 1-启用&#x27;, `remark` VARCHAR(500) DEFAULT NULL COMMENT &#x27;备注&#x27;, `version` INT NOT NULL DEFAULT 1 COMMENT &#x27;乐观锁版本号&#x27;, `deleted` TINYINT NOT NULL DEFAULT 0 COMMENT &#x27;逻辑删除：0-未删除 1-已删除&#x27;, `create_by` BIGINT DEFAULT NULL COMMENT &#x27;创建人ID&#x27;, `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT &#x27;创建时间&#x27;, `update_by` BIGINT DEFAULT NULL COMMENT &#x27;更新人ID&#x27;, `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT &#x27;更新时间&#x27;, PRIMARY KEY (`id`), UNIQUE KEY `uk_username` (`username`, `deleted`), KEY `idx_phone` (`phone`), KEY `idx_dept_id` (`dept_id`), KEY `idx_status_create_time` (`status`, `create_time`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=&#x27;用户表&#x27;;
2.3 角色表（sys_role）CREATE TABLE `sys_role` ( `id` BIGINT NOT NULL AUTO_INCREMENT, `role_name` VARCHAR(50) NOT NULL COMMENT &#x27;角色名称&#x27;, `role_code` VARCHAR(50) NOT NULL COMMENT &#x27;角色编码&#x27;, `parent_id` BIGINT DEFAULT 0 COMMENT &#x27;父角色ID，用于角色继承&#x27;, `description` VARCHAR(200) DEFAULT NULL COMMENT &#x27;描述&#x27;, `data_scope` TINYINT NOT NULL DEFAULT 1 COMMENT &#x27;数据权限：1-全部 2-本部门 3-本部门及下级 4-仅本人&#x27;, `status` TINYINT NOT NULL DEFAULT 1 COMMENT &#x27;状态：0-禁用 1-启用&#x27;, `deleted` TINYINT NOT NULL DEFAULT 0, `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uk_role_code` (`role_code`, `deleted`), KEY `idx_parent_id` (`parent_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=&#x27;角色表&#x27;;-- 智慧矿山角色初始化INSERT INTO sys_role (id, role_name, role_code, parent_id, description, data_scope) VALUES(1, &#x27;超级管理员&#x27;, &#x27;ADMIN&#x27;, 0, &#x27;拥有所有权限&#x27;, 1),(2, &#x27;矿长&#x27;, &#x27;MINE_MASTER&#x27;, 1, &#x27;矿区最高管理者&#x27;, 1),(3, &#x27;副矿长&#x27;, &#x27;DEP_MASTER&#x27;, 2, &#x27;协助矿长管理&#x27;, 1),(4, &#x27;调度总监&#x27;, &#x27;DISPATCH_DIR&#x27;, 2, &#x27;调度中心负责人&#x27;, 1),(5, &#x27;安全总监&#x27;, &#x27;SAFETY_DIR&#x27;, 2, &#x27;安全管理负责人&#x27;, 1),(6, &#x27;区段长&#x27;, &#x27;SECTION_CHIEF&#x27;,3, &#x27;采区负责人&#x27;, 2),(7, &#x27;调度员&#x27;, &#x27;DISPATCHER&#x27;, 4, &#x27;井下生产调度&#x27;, 2),(8, &#x27;安全员&#x27;, &#x27;SAFETY_OFF&#x27;, 5, &#x27;现场安全监督&#x27;, 3),(9, &#x27;监控员&#x27;, &#x27;MONITOR&#x27;, 4, &#x27;监控室值班&#x27;, 2),(10, &#x27;维修工&#x27;, &#x27;REPAIRMAN&#x27;, 3, &#x27;设备维修保养&#x27;, 4);
2.4 权限表（sys_permission）CREATE TABLE `sys_permission` ( `id` BIGINT NOT NULL AUTO_INCREMENT, `parent_id` BIGINT DEFAULT 0 COMMENT &#x27;父权限ID&#x27;, `name` VARCHAR(50) NOT NULL COMMENT &#x27;权限名称&#x27;, `type` TINYINT NOT NULL COMMENT &#x27;类型：1-菜单 2-按钮&#x27;, `permission` VARCHAR(100) DEFAULT NULL COMMENT &#x27;权限标识&#x27;, `path` VARCHAR(200) DEFAULT NULL COMMENT &#x27;路由路径&#x27;, `icon` VARCHAR(100) DEFAULT NULL COMMENT &#x27;图标&#x27;, `sort` INT DEFAULT 0 COMMENT &#x27;排序&#x27;, `status` TINYINT NOT NULL DEFAULT 1, `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=&#x27;权限表&#x27;;-- 智慧矿山权限初始化（菜单树）INSERT INTO sys_permission (id, parent_id, name, type, permission, path, sort) VALUES-- 一级菜单(1, 0, &#x27;人员定位&#x27;, 1, NULL, &#x27;/person-location&#x27;, 1),(2, 0, &#x27;设备监控&#x27;, 1, NULL, &#x27;/device-monitor&#x27;, 2),(3, 0, &#x27;安全监测&#x27;, 1, NULL, &#x27;/safety-monitor&#x27;, 3),(4, 0, &#x27;生产调度&#x27;, 1, NULL, &#x27;/production&#x27;, 4),(5, 0, &#x27;系统管理&#x27;, 1, NULL, &#x27;/system&#x27;, 5),-- 人员定位子菜单(101, 1, &#x27;实时定位&#x27;, 1, NULL, &#x27;/person-location/realtime&#x27;, 1),(102, 1, &#x27;轨迹回放&#x27;, 1, NULL, &#x27;/person-location/track&#x27;, 2),(103, 1, &#x27;区域统计&#x27;, 1, NULL, &#x27;/person-location/zone&#x27;, 3),-- 人员定位按钮(111, 101, &#x27;查看&#x27;, 2, &#x27;location:view&#x27;, NULL, 1),(112, 101, &#x27;导出&#x27;, 2, &#x27;location:export&#x27;, NULL, 2),(113, 102, &#x27;回放&#x27;, 2, &#x27;location:track&#x27;, NULL, 1),(114, 103, &#x27;统计&#x27;, 2, &#x27;location:statistics&#x27;, NULL, 1),-- 设备监控子菜单(201, 2, &#x27;设备列表&#x27;, 1, NULL, &#x27;/device-monitor/list&#x27;, 1),(202, 2, &#x27;设备状态&#x27;, 1, NULL, &#x27;/device-monitor/status&#x27;, 2),(203, 2, &#x27;维修记录&#x27;, 1, NULL, &#x27;/device-monitor/repair&#x27;, 3),-- 设备监控按钮(211, 201, &#x27;查看&#x27;, 2, &#x27;device:view&#x27;, NULL, 1),(212, 201, &#x27;新增&#x27;, 2, &#x27;device:add&#x27;, NULL, 2),(213, 201, &#x27;修改&#x27;, 2, &#x27;device:update&#x27;, NULL, 3),(214, 201, &#x27;删除&#x27;, 2, &#x27;device:delete&#x27;, NULL, 4),(215, 202, &#x27;操作&#x27;, 2, &#x27;device:operate&#x27;, NULL, 1),(216, 203, &#x27;记录&#x27;, 2, &#x27;repair:record&#x27;, NULL, 1),-- 安全监测子菜单(301, 3, &#x27;瓦斯监测&#x27;, 1, NULL, &#x27;/safety/gas&#x27;, 1),(302, 3, &#x27;通风监测&#x27;, 1, NULL, &#x27;/safety/vent&#x27;, 2),(303, 3, &#x27;报警记录&#x27;, 1, NULL, &#x27;/safety/alarm&#x27;, 3),-- 安全监测按钮(311, 301, &#x27;查看&#x27;, 2, &#x27;gas:view&#x27;, NULL, 1),(312, 301, &#x27;处置&#x27;, 2, &#x27;gas:handle&#x27;, NULL, 2),(313, 302, &#x27;查看&#x27;, 2, &#x27;vent:view&#x27;, NULL, 1),(314, 302, &#x27;控制&#x27;, 2, &#x27;vent:control&#x27;, NULL, 2),(315, 303, &#x27;查看&#x27;, 2, &#x27;alarm:view&#x27;, NULL, 1),(316, 303, &#x27;确认&#x27;, 2, &#x27;alarm:confirm&#x27;, NULL, 2),-- 生产调度子菜单(401, 4, &#x27;调度指令&#x27;, 1, NULL, &#x27;/production/dispatch&#x27;, 1),(402, 4, &#x27;班次管理&#x27;, 1, NULL, &#x27;/production/shift&#x27;, 2),-- 生产调度按钮(411, 401, &#x27;查看&#x27;, 2, &#x27;dispatch:view&#x27;, NULL, 1),(412, 401, &#x27;下发&#x27;, 2, &#x27;dispatch:issue&#x27;, NULL, 2),(413, 401, &#x27;撤回&#x27;, 2, &#x27;dispatch:revoke&#x27;, NULL, 3),-- 系统管理子菜单(501, 5, &#x27;用户管理&#x27;, 1, NULL, &#x27;/system/user&#x27;, 1),(502, 5, &#x27;角色管理&#x27;, 1, NULL, &#x27;/system/role&#x27;, 2),(503, 5, &#x27;权限管理&#x27;, 1, NULL, &#x27;/system/permission&#x27;,3),(504, 5, &#x27;操作日志&#x27;, 1, NULL, &#x27;/system/log&#x27;, 4),-- 系统管理按钮(511, 501, &#x27;查询&#x27;, 2, &#x27;user:list&#x27;, NULL, 1),(512, 501, &#x27;新增&#x27;, 2, &#x27;user:add&#x27;, NULL, 2),(513, 501, &#x27;修改&#x27;, 2, &#x27;user:update&#x27;, NULL, 3),(514, 501, &#x27;删除&#x27;, 2, &#x27;user:delete&#x27;, NULL, 4),(521, 502, &#x27;查询&#x27;, 2, &#x27;role:list&#x27;, NULL, 1),(522, 502, &#x27;新增&#x27;, 2, &#x27;role:add&#x27;, NULL, 2),(523, 502, &#x27;分配权限&#x27;, 2, &#x27;role:permission&#x27;, NULL, 3),(531, 503, &#x27;查询&#x27;, 2, &#x27;permission:list&#x27;, NULL, 1),(532, 503, &#x27;新增&#x27;, 2, &#x27;permission:add&#x27;, NULL, 2),(541, 504, &#x27;查询&#x27;, 2, &#x27;log:view&#x27;, NULL, 1),(542, 504, &#x27;清除&#x27;, 2, &#x27;log:clear&#x27;, NULL, 2);
2.5 用户角色关联表（sys_user_role）CREATE TABLE `sys_user_role` ( `id` BIGINT NOT NULL AUTO_INCREMENT, `user_id` BIGINT NOT NULL COMMENT &#x27;用户ID&#x27;, `role_id` BIGINT NOT NULL COMMENT &#x27;角色ID&#x27;, PRIMARY KEY (`id`), UNIQUE KEY `uk_user_role` (`user_id`, `role_id`), KEY `idx_role_id` (`role_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=&#x27;用户角色关联表&#x27;;-- 初始化数据：张三同时拥有安全员和监控员角色INSERT INTO sys_user_role (user_id, role_id) VALUES(1, 1), -- 超级管理员(2, 2), -- 矿长(3, 8), -- 安全员(3, 9), -- 监控员（同一人多角色）(4, 7), -- 调度员(5, 10); -- 维修工
2.6 角色权限关联表（sys_role_permission）CREATE TABLE `sys_role_permission` ( `id` BIGINT NOT NULL AUTO_INCREMENT, `role_id` BIGINT NOT NULL COMMENT &#x27;角色ID&#x27;, `permission_id` BIGINT NOT NULL COMMENT &#x27;权限ID&#x27;, PRIMARY KEY (`id`), UNIQUE KEY `uk_role_permission` (`role_id`, `permission_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=&#x27;角色权限关联表&#x27;;-- 安全员角色权限：安全监测(3) + 人员定位查看(1,101,111) + 报警确认(303,315,316)INSERT INTO sys_role_permission (role_id, permission_id) VALUES(8, 1), (8, 101), (8, 111), (8, 102), (8, 113),(8, 3), (8, 301), (8, 311), (8, 312),(8, 302), (8, 313), (8, 303), (8, 315), (8, 316);
三、Entity 层设计3.1 角色实体@Data@TableName(&quot;sys_role&quot;)public class Role &#123; @TableId(type = IdType.AUTO) private Long id; private String roleName; private String roleCode; private Long parentId; private String description; private Integer dataScope; private Integer status; @TableLogic @TableField(select = false) private Integer deleted; private LocalDateTime createTime; private LocalDateTime updateTime; /** * 角色继承 —— 获取所有祖先角色ID * 用于 RBAC1 角色继承模型 */ @TableField(exist = false) private List&lt;Long&gt; ancestorRoleIds;&#125;
3.2 权限实体@Data@TableName(&quot;sys_permission&quot;)public class Permission &#123; @TableId(type = IdType.AUTO) private Long id; private Long parentId; private String name; private Integer type; // 1-菜单 2-按钮 private String permission; // 权限标识，如 user:list private String path; // 路由路径 private String icon; private Integer sort; private Integer status; private LocalDateTime createTime; @TableField(exist = false) private List&lt;Permission&gt; children;&#125;
3.3 关联实体@Data@TableName(&quot;sys_user_role&quot;)public class UserRole &#123; @TableId(type = IdType.AUTO) private Long id; private Long userId; private Long roleId;&#125;@Data@TableName(&quot;sys_role_permission&quot;)public class RolePermission &#123; @TableId(type = IdType.AUTO) private Long id; private Long roleId; private Long permissionId;&#125;
四、权限 Service 核心实现4.1 权限查询流程权限查询完整流程
请求进入 | v [1] 从 UserContext 获取 userId | v [2] 查 Redis 缓存 user:permissions:{userId} | +– 缓存命中 –&gt; 直接返回权限列表 | v 缓存未命中 [3] 查 sys_user_role 获取角色ID列表 | v [4] 角色继承：递归查 parent_id 获取祖先角色 | v [5] 查 sys_role_permission 获取权限ID列表 | v [6] 查 sys_permission 获取权限标识列表 | 过滤：status&#x3D;1 且 permission 非空 | 去重 v [7] 写入 Redis 缓存，TTL&#x3D;30min | v 返回权限列表
4.2 权限 Service 完整代码@Service@RequiredArgsConstructor@Slf4jpublic class PermissionServiceImpl implements PermissionService &#123; private final UserMapper userMapper; private final UserRoleMapper userRoleMapper; private final RoleMapper roleMapper; private final RolePermissionMapper rolePermissionMapper; private final PermissionMapper permissionMapper; private final RedisTemplate&lt;String, Object&gt; redisTemplate; private static final String PERMISSION_CACHE_PREFIX = &quot;user:permissions:&quot;; private static final long CACHE_TTL_MINUTES = 30; /** * 获取用户所有权限标识（包含角色继承） */ @Override public List&lt;String&gt; getUserPermissions(Long userId) &#123; // 1. 查缓存 String cacheKey = PERMISSION_CACHE_PREFIX + userId; List&lt;String&gt; cached = (List&lt;String&gt;) redisTemplate.opsForValue().get(cacheKey); if (cached != null) &#123; log.debug(&quot;权限缓存命中: userId=&#123;&#125;&quot;, userId); return cached; &#125; // 2. 查用户直接角色 List&lt;Long&gt; roleIds = getUserRoleIds(userId); if (roleIds.isEmpty()) &#123; return Collections.emptyList(); &#125; // 3. 角色继承：获取所有祖先角色（RBAC1） List&lt;Long&gt; allRoleIds = getAllInheritedRoleIds(roleIds); // 4. 查角色权限 List&lt;Long&gt; permissionIds = rolePermissionMapper.selectList( new LambdaQueryWrapper&lt;RolePermission&gt;() .in(RolePermission::getRoleId, allRoleIds) ).stream().map(RolePermission::getPermissionId).collect(Collectors.toList()); if (permissionIds.isEmpty()) &#123; return Collections.emptyList(); &#125; // 5. 查权限标识 List&lt;String&gt; permissions = permissionMapper.selectBatchIds(permissionIds).stream() .filter(p -&gt; p.getStatus() == 1 &amp;&amp; StringUtils.isNotBlank(p.getPermission())) .map(Permission::getPermission) .distinct() .collect(Collectors.toList()); // 6. 写缓存 redisTemplate.opsForValue().set(cacheKey, permissions, CACHE_TTL_MINUTES, TimeUnit.MINUTES); log.info(&quot;权限缓存已刷新: userId=&#123;&#125;, permissionCount=&#123;&#125;&quot;, userId, permissions.size()); return permissions; &#125; /** * 获取用户菜单树（前端渲染导航栏） */ @Override public List&lt;PermissionVO&gt; getUserMenus(Long userId) &#123; List&lt;Long&gt; roleIds = getUserRoleIds(userId); if (roleIds.isEmpty()) return Collections.emptyList(); List&lt;Long&gt; allRoleIds = getAllInheritedRoleIds(roleIds); List&lt;Long&gt; permissionIds = rolePermissionMapper.selectList( new LambdaQueryWrapper&lt;RolePermission&gt;() .in(RolePermission::getRoleId, allRoleIds) ).stream().map(RolePermission::getPermissionId).collect(Collectors.toList()); if (permissionIds.isEmpty()) return Collections.emptyList(); List&lt;Permission&gt; allPermissions = permissionMapper.selectBatchIds(permissionIds).stream() .filter(p -&gt; p.getStatus() == 1) .sorted(Comparator.comparingInt(Permission::getSort)) .collect(Collectors.toList()); return buildMenuTree(allPermissions); &#125; /** * 获取用户角色ID列表 */ private List&lt;Long&gt; getUserRoleIds(Long userId) &#123; return userRoleMapper.selectList( new LambdaQueryWrapper&lt;UserRole&gt;().eq(UserRole::getUserId, userId) ).stream().map(UserRole::getRoleId).collect(Collectors.toList()); &#125; /** * 递归获取所有继承的角色ID * 例：区段长 -&gt; 副矿长 -&gt; 矿长 -&gt; 超级管理员 */ private List&lt;Long&gt; getAllInheritedRoleIds(List&lt;Long&gt; roleIds) &#123; Set&lt;Long&gt; allRoleIds = new LinkedHashSet&lt;&gt;(roleIds); Queue&lt;Long&gt; queue = new LinkedList&lt;&gt;(roleIds); while (!queue.isEmpty()) &#123; Long roleId = queue.poll(); Role role = roleMapper.selectById(roleId); if (role != null &amp;&amp; role.getParentId() != null &amp;&amp; role.getParentId() &gt; 0) &#123; if (allRoleIds.add(role.getParentId())) &#123; queue.add(role.getParentId()); &#125; &#125; &#125; return new ArrayList&lt;&gt;(allRoleIds); &#125; /** * 构建菜单树 */ private List&lt;PermissionVO&gt; buildMenuTree(List&lt;Permission&gt; permissions) &#123; Map&lt;Long, PermissionVO&gt; voMap = new LinkedHashMap&lt;&gt;(); permissions.forEach(p -&gt; voMap.put(p.getId(), toPermissionVO(p))); List&lt;PermissionVO&gt; roots = new ArrayList&lt;&gt;(); voMap.values().forEach(vo -&gt; &#123; if (vo.getParentId() == 0) &#123; roots.add(vo); &#125; else &#123; PermissionVO parent = voMap.get(vo.getParentId()); if (parent != null) &#123; parent.getChildren().add(vo); &#125; &#125; &#125;); return roots; &#125; private PermissionVO toPermissionVO(Permission p) &#123; PermissionVO vo = new PermissionVO(); BeanUtils.copyProperties(p, vo); return vo; &#125; /** * 清除用户权限缓存（角色/权限变更时调用） */ @Override public void clearUserPermissionCache(Long userId) &#123; String cacheKey = PERMISSION_CACHE_PREFIX + userId; redisTemplate.delete(cacheKey); log.info(&quot;权限缓存已清除: userId=&#123;&#125;&quot;, userId); &#125; /** * 清除所有用户的权限缓存（批量变更时调用） */ @Override public void clearAllPermissionCache() &#123; Set&lt;String&gt; keys = redisTemplate.keys(PERMISSION_CACHE_PREFIX + &quot;*&quot;); if (keys != null &amp;&amp; !keys.isEmpty()) &#123; redisTemplate.delete(keys); log.info(&quot;全量权限缓存已清除: count=&#123;&#125;&quot;, keys.size()); &#125; &#125;&#125;
五、权限拦截：AOP + 自定义注解5.1 权限拦截流程权限拦截执行链
HTTP Request | v [JwtFilter] 解析Token → 设置 UserContext | v [PermissionAspect] AOP 拦截 @RequirePermission | +– 无注解 –&gt; 放行 | v 有注解 获取 userId + requiredPermission | v 调用 PermissionService.getUserPermissions(userId) | +– 超级管理员 –&gt; 直接放行 | +– 权限列表包含 required –&gt; 放行 | +– 权限列表不包含 required –&gt; 抛 403 异常
5.2 自定义注解/** * 权限校验注解 * 标注在 Controller 方法上，声明所需权限标识 */@Target(ElementType.METHOD)@Retention(RetentionPolicy.RUNTIME)@Documentedpublic @interface RequirePermission &#123; /** * 权限标识，如 &quot;user:list&quot; */ String value();&#125;
5.3 AOP 切面@Aspect@Component@RequiredArgsConstructor@Slf4jpublic class PermissionAspect &#123; private final PermissionService permissionService; @Around(&quot;@annotation(requirePermission)&quot;) public Object around(ProceedingJoinPoint pjp, RequirePermission requirePermission) throws Throwable &#123; Long userId = UserContext.getUserId(); if (userId == null) &#123; throw new BusinessException(401, &quot;未登录&quot;); &#125; String required = requirePermission.value(); log.debug(&quot;权限校验: userId=&#123;&#125;, required=&#123;&#125;&quot;, userId, required); List&lt;String&gt; permissions = permissionService.getUserPermissions(userId); if (!permissions.contains(required)) &#123; log.warn(&quot;权限不足: userId=&#123;&#125;, required=&#123;&#125;, owned=&#123;&#125;&quot;, userId, required, permissions); throw new BusinessException(403, &quot;无操作权限: &quot; + required); &#125; return pjp.proceed(); &#125;&#125;
5.4 超级管理员跳过校验@Aspect@Component@RequiredArgsConstructor@Slf4jpublic class AdminBypassAspect &#123; private final UserRoleMapper userRoleMapper; private final RoleMapper roleMapper; @Around(&quot;@annotation(requirePermission)&quot;) public Object around(ProceedingJoinPoint pjp, RequirePermission requirePermission) throws Throwable &#123; Long userId = UserContext.getUserId(); // 超级管理员直接放行 if (isAdmin(userId)) &#123; log.debug(&quot;超级管理员放行: userId=&#123;&#125;&quot;, userId); return pjp.proceed(); &#125; // 非管理员走正常权限校验 // ... 交给 PermissionAspect 处理 return pjp.proceed(); &#125; private boolean isAdmin(Long userId) &#123; List&lt;UserRole&gt; userRoles = userRoleMapper.selectList( new LambdaQueryWrapper&lt;UserRole&gt;().eq(UserRole::getUserId, userId) ); return userRoles.stream().anyMatch(ur -&gt; &#123; Role role = roleMapper.selectById(ur.getRoleId()); return role != null &amp;&amp; &quot;ADMIN&quot;.equals(role.getRoleCode()); &#125;); &#125;&#125;
六、Controller 层使用6.1 用户管理接口@RestController@RequestMapping(&quot;/users&quot;)@RequiredArgsConstructor@Tag(name = &quot;用户管理&quot;)public class UserController &#123; private final UserService userService; @RequirePermission(&quot;user:list&quot;) @Operation(summary = &quot;查询用户列表&quot;) @GetMapping(&quot;/list&quot;) public Result&lt;PageResult&lt;UserVO&gt;&gt; list(@Valid UserQueryDTO query) &#123; return Result.success(userService.list(query)); &#125; @RequirePermission(&quot;user:add&quot;) @Operation(summary = &quot;新增用户&quot;) @PostMapping public Result&lt;Void&gt; add(@RequestBody @Valid UserCreateDTO dto) &#123; userService.add(dto); return Result.success(); &#125; @RequirePermission(&quot;user:update&quot;) @Operation(summary = &quot;修改用户&quot;) @PutMapping public Result&lt;Void&gt; update(@RequestBody @Valid UserUpdateDTO dto) &#123; userService.update(dto); return Result.success(); &#125; @RequirePermission(&quot;user:delete&quot;) @Operation(summary = &quot;删除用户&quot;) @DeleteMapping(&quot;/&#123;id&#125;&quot;) public Result&lt;Void&gt; delete(@PathVariable Long id) &#123; userService.delete(id); return Result.success(); &#125;&#125;
6.2 角色管理接口@RestController@RequestMapping(&quot;/roles&quot;)@RequiredArgsConstructor@Tag(name = &quot;角色管理&quot;)public class RoleController &#123; private final RoleService roleService; @RequirePermission(&quot;role:list&quot;) @GetMapping(&quot;/list&quot;) public Result&lt;List&lt;RoleVO&gt;&gt; list() &#123; return Result.success(roleService.listAll()); &#125; @RequirePermission(&quot;role:add&quot;) @PostMapping public Result&lt;Void&gt; add(@RequestBody @Valid RoleCreateDTO dto) &#123; roleService.add(dto); return Result.success(); &#125; @RequirePermission(&quot;role:permission&quot;) @PutMapping(&quot;/&#123;roleId&#125;/permissions&quot;) public Result&lt;Void&gt; assignPermissions(@PathVariable Long roleId, @RequestBody List&lt;Long&gt; permissionIds) &#123; roleService.assignPermissions(roleId, permissionIds); return Result.success(); &#125;&#125;
6.3 前端菜单加载接口@RestController@RequestMapping(&quot;/menus&quot;)@RequiredArgsConstructorpublic class MenuController &#123; private final PermissionService permissionService; /** * 获取当前用户的菜单树 * 前端根据此接口返回的数据渲染导航栏 * 没有权限的菜单不会出现在返回结果中 */ @GetMapping public Result&lt;List&lt;PermissionVO&gt;&gt; getMenus() &#123; Long userId = UserContext.getUserId(); return Result.success(permissionService.getUserMenus(userId)); &#125;&#125;
七、数据权限7.1 数据权限场景数据权限控制层级
data_scope &#x3D; 1: 全部数据 矿长、副矿长可以看所有矿区数据
data_scope &#x3D; 2: 本部门数据 调度总监只能看调度中心的数据
data_scope &#x3D; 3: 本部门及下级数据 安全总监可以看安全部 + 各安全组数据
data_scope &#x3D; 4: 仅本人数据 维修工只能看自己的维修工单
部门树： 矿区总部 生产调度中心 调度一组 调度二组 安全管理部 瓦斯检测组 通风安全组 机电维修部 采掘设备组 运输设备组
7.2 数据权限拦截/** * 数据权限拦截器 * 在 SQL 执行前自动追加数据范围条件 */@Component@RequiredArgsConstructorpublic class DataScopeInterceptor implements InnerInterceptor &#123; private final UserRoleMapper userRoleMapper; private final RoleMapper roleMapper; private final DeptMapper deptMapper; @Override public void beforeQuery(Executor executor, MappedStatement ms, Object parameter, RowBounds rowBounds, ResultHandler resultHandler, BoundSql boundSql) &#123; Long userId = UserContext.getUserId(); if (userId == null) return; // 获取用户角色的数据权限范围 Integer dataScope = getMaxDataScope(userId); if (dataScope == null || dataScope == 1) return; // 全部数据不过滤 // 获取用户所在部门及下级部门ID Long deptId = UserContext.getDeptId(); List&lt;Long&gt; deptIds = getVisibleDeptIds(deptId, dataScope); // 追加 SQL 条件 String originalSql = boundSql.getSql(); String dataFilter = &quot; AND dept_id IN (&quot; + deptIds.stream().map(String::valueOf).collect(Collectors.joining(&quot;,&quot;)) + &quot;)&quot;; // 使用 SQL 解析器追加条件 // ... &#125; private List&lt;Long&gt; getVisibleDeptIds(Long deptId, Integer dataScope) &#123; List&lt;Long&gt; deptIds = new ArrayList&lt;&gt;(); switch (dataScope) &#123; case 2: // 本部门 deptIds.add(deptId); break; case 3: // 本部门及下级 deptIds.add(deptId); deptIds.addAll(getChildDeptIds(deptId)); break; case 4: // 仅本人 — 由具体 SQL 控制 break; &#125; return deptIds; &#125; private List&lt;Long&gt; getChildDeptIds(Long parentId) &#123; // 递归查子部门 List&lt;Dept&gt; children = deptMapper.selectList( new LambdaQueryWrapper&lt;Dept&gt;().eq(Dept::getParentId, parentId) ); List&lt;Long&gt; ids = children.stream().map(Dept::getId).collect(Collectors.toList()); for (Dept child : children) &#123; ids.addAll(getChildDeptIds(child.getId())); &#125; return ids; &#125;&#125;
八、缓存策略8.1 缓存设计权限缓存策略
缓存Key: user:permissions:{userId} 缓存Value: [“user:list”,”user:add”,”device:view”,…] TTL: 30分钟 缓存失效触发条件： +————————————————————-+ | 触发事件 | 失效范围 | | +————————————————————-+ | 用户角色变更 | 该用户缓存 | | | 角色权限变更 | 该角色下所有用户缓存 | | | 权限状态变更 | 全部用户缓存 | | | 角色删除 | 该角色下所有用户缓存 | | +————————————————————-+
8.2 角色权限变更时的缓存清理@Service@RequiredArgsConstructor@Slf4jpublic class RoleServiceImpl implements RoleService &#123; private final RoleMapper roleMapper; private final RolePermissionMapper rolePermissionMapper; private final UserRoleMapper userRoleMapper; private final PermissionService permissionService; @Override @Transactional(rollbackFor = Exception.class) public void assignPermissions(Long roleId, List&lt;Long&gt; permissionIds) &#123; // 1. 删除旧权限 rolePermissionMapper.delete( new LambdaQueryWrapper&lt;RolePermission&gt;().eq(RolePermission::getRoleId, roleId) ); // 2. 插入新权限 List&lt;RolePermission&gt; list = permissionIds.stream() .map(pid -&gt; &#123; RolePermission rp = new RolePermission(); rp.setRoleId(roleId); rp.setPermissionId(pid); return rp; &#125;).collect(Collectors.toList()); rolePermissionMapper.insertBatchSomeColumn(list); // 3. 清除该角色下所有用户的权限缓存 List&lt;Long&gt; userIds = userRoleMapper.selectList( new LambdaQueryWrapper&lt;UserRole&gt;().eq(UserRole::getRoleId, roleId) ).stream().map(UserRole::getUserId).collect(Collectors.toList()); userIds.forEach(permissionService::clearUserPermissionCache); log.info(&quot;角色权限变更，已清理&#123;&#125;个用户的缓存: roleId=&#123;&#125;&quot;, userIds.size(), roleId); &#125;&#125;
九、前端权限控制9.1 菜单权限// router/index.js// 根据后端返回的菜单树动态生成路由const menus = await api.getMenus(); // 调用 /menus 接口function buildRoutes(menus) &#123; return menus.map(menu =&gt; &#123; const route = &#123; path: menu.path, component: () =&gt; import(`@/views$&#123;menu.path&#125;.vue`), meta: &#123; title: menu.name &#125; &#125;; if (menu.children &amp;&amp; menu.children.length &gt; 0) &#123; route.children = buildRoutes(menu.children.filter(c =&gt; c.type === 1)); &#125; return route; &#125;);&#125;// 动态添加路由buildRoutes(menus).forEach(route =&gt; router.addRoute(route));
9.2 按钮权限// directives/permission.js// 自定义指令 v-permissionapp.directive(&#x27;permission&#x27;, &#123; mounted(el, binding) &#123; const required = binding.value; const permissions = store.state.user.permissions; if (!permissions.includes(required)) &#123; el.parentNode &amp;&amp; el.parentNode.removeChild(el); &#125; &#125;&#125;);// 使用// &lt;el-button v-permission=&quot;&#x27;user:add&#x27;&quot; @click=&quot;handleAdd&quot;&gt;新增&lt;/el-button&gt;// &lt;el-button v-permission=&quot;&#x27;user:delete&#x27;&quot; @click=&quot;handleDelete&quot;&gt;删除&lt;/el-button&gt;
十、实际项目权限问题汇总 序号 | 问题描述 | 问题原因 | 解决方案 1 | 调度员看不到报警确认按钮 | 角色未分配 alarm:confirm 权限 | 为调度员角色补充 alarm:confirm 权限 2 | 安员甲能看A区数据但看不到B区 | data_scope&#x3D;2 只看本部门 | 调整为 data_scope&#x3D;3 本部门及下级 3 | 矿长登录后菜单加载超慢（3秒） | 每次请求都查5张表，无缓存 | 引入 Redis 缓存，TTL&#x3D;30min 4 | 修改角色权限后用户仍能访问旧权限 | 权限缓存未及时清理 | 角色权限变更时清理相关用户缓存 5 | 一人兼两岗（安全员+监控员）权限不叠加 | 硬编码只取第一个角色 | RBAC 多角色叠加，合并所有角色权限 6 | 前端能看到菜单但后端报403 | 前端菜单用type&#x3D;1，后端校验type&#x3D;2 | 统一 permission 字段为校验标准 7 | 删除角色后用户仍能访问该角色权限 | 逻辑删除后关联表未清理 | 级联删除 sys_user_role 和 sys_role_permission 8 | 瓦检员权限和通风员几乎一样，重复配置 | 无角色继承机制 | 引入 RBAC1 角色继承，减少重复配置 9 | 新增矿种后需要逐个角色添加权限 | 无权限模板机制 | 创建权限模板，新模块一键分配给角色 10 | 超级管理员账号被误删导致系统无法管理 | 硬编码 ADMIN 角色 | 超级管理员账号增加不可删除保护 11 | 井下移动端权限和PC端不同，但用的是同一套 | 未区分终端类型 | 权限标识增加终端前缀 mobile:user:list 12 | 用户切换部门后数据权限没变 | 部门信息缓存未更新 | 用户部门变更时清理权限缓存 13 | 权限表数据量到2000+后菜单加载变慢 | 递归查 parent_id 没有索引 | 添加 idx_parent_id 索引，菜单树缓存 14 | 临时授权场景无法处理 | 只有永久角色分配 | 增加临时权限表，支持过期时间 15 | 操作日志无法追溯谁给谁分配了什么权限 | 权限变更无审计记录 | 增加 permission_change_log 审计表
十一、权限审计日志/** * 权限变更审计日志 */@Data@TableName(&quot;permission_change_log&quot;)public class PermissionChangeLog &#123; @TableId(type = IdType.AUTO) private Long id; private Long operatorId; // 操作人 private String operatorName; private String changeType; // ASSIGN_ROLE, REMOVE_ROLE, ASSIGN_PERMISSION, REMOVE_PERMISSION private Long targetUserId; // 目标用户 private Long roleId; // 变更的角色 private String permissionIds; // 变更的权限ID列表 private String beforeSnapshot;// 变更前快照 private String afterSnapshot; // 变更后快照 private LocalDateTime createTime;&#125;/** * AOP 切面自动记录权限变更日志 */@Aspect@Component@RequiredArgsConstructor@Slf4jpublic class PermissionAuditAspect &#123; private final PermissionChangeLogMapper logMapper; @AfterReturning(&quot;execution(* com.mine.service.RoleService.assignPermissions(..)) &amp;&amp; args(roleId, permissionIds)&quot;) public void logAssignPermissions(Long roleId, List&lt;Long&gt; permissionIds) &#123; Long operatorId = UserContext.getUserId(); String operatorName = UserContext.getUserName(); PermissionChangeLog changeLog = new PermissionChangeLog(); changeLog.setOperatorId(operatorId); changeLog.setOperatorName(operatorName); changeLog.setChangeType(&quot;ASSIGN_PERMISSION&quot;); changeLog.setRoleId(roleId); changeLog.setPermissionIds(permissionIds.stream().map(String::valueOf).collect(Collectors.joining(&quot;,&quot;))); changeLog.setCreateTime(LocalDateTime.now()); logMapper.insert(changeLog); log.info(&quot;权限变更审计: operator=&#123;&#125;, roleId=&#123;&#125;, permissionIds=&#123;&#125;&quot;, operatorName, roleId, permissionIds); &#125;&#125;
十二、最佳实践总结RBAC 最佳实践检查清单
[设计层面] 采用 RBAC1 模型，支持角色继承 权限标识统一格式：模块:操作（user:list） 菜单和按钮分离：type&#x3D;1菜单，type&#x3D;2按钮 数据权限分层：全部&#x2F;本部门&#x2F;本部门及下级&#x2F;仅本人 [安全层面] 超级管理员账号不可删除、不可禁用 权限校验前后端双重验证（前端隐藏+后端拦截） 权限变更审计日志完整记录 敏感操作二次确认（删除角色、清空权限） [性能层面] 权限查询 Redis 缓存，TTL&#x3D;30min 角色权限变更时精准清理缓存 菜单树结果缓存 权限表 parent_id 加索引 [运维层面] 权限初始化脚本纳入版本管理 定期审计权限分配是否合理 临时权限到期自动回收 权限配置变更走审批流程
十三、总结RBAC 是权限管理的标准模型。实际场景中，我从”硬编码 if-else”到”RBAC1 角色继承模型”，核心认知是：用户-角色-权限三层解耦，让权限管理灵活可扩展。@RequirePermission 注解 + AOP 拦截，让权限校验零侵入；Redis 缓存让权限查询毫秒级响应；数据权限拦截器让行级过滤自动化。RBAC 不是万能的，但它是绝大多数后台系统的最佳起点。

前言在实际场景中，AQS（AbstractQueuedSynchronizer）几乎渗透到了每一个并发场景——矿车调度系统的互斥访问用 ReentrantLock，设备状态变更的限流用 Semaphore，多传感器数据汇聚的等待用 CountDownLatch，井下人员定位的读写分离用 ReentrantReadWriteLock。2023年之前只知道 AQS 是”抽象队列同步器”，完全不清楚内部运作机制。一旦遇到锁超时、队列出错、线程饥饿等线上问题，排查基本靠猜。2023年决定啃透 AQS 源码，系统理解 volatile state + CLH 队列 + CAS + park&#x2F;unpark 这套统一设计范式，之后在生产中排错和选型才真正有了底气。
AQS 架构总览AQS 是 JUC（java.util.concurrent）并发包的底层框架，提供了一套通用的同步状态管理机制。ReentrantLock、Semaphore、CountDownLatch、ReentrantReadWriteLock 等工具全部基于 AQS 实现，区别仅在于 state 的语义和 tryAcquire&#x2F;tryRelease 的具体逻辑。 核心架构层次用户 API 层：
ReentrantLock &#x2F; Semaphore &#x2F; CountDownLatch …
同步器实现层：
FairSync &#x2F; NonfairSync &#x2F; Sync 子类
AQS 框架层：
state + CLH队列 + acquire&#x2F;release 模板
原语操作层：
Unsafe CAS &#x2F; LockSupport park&#x2F;unpark
JVM 层：
volatile 语义 &#x2F; 内存屏障 &#x2F; 线程调度
关键设计决策
设计决策 说明
volatile int state 核心同步状态变量，volatile 保证可见性，CAS 保证原子性，不同工具赋予不同语义
CLH 双向等待队列 FIFO 公平排队，每个等待线程封装为 Node 节点，通过 prev&#x2F;next 指针串联
模板方法模式 AQS 定义 acquire&#x2F;release 等模板流程，子类只需实现 tryAcquire&#x2F;tryRelease
CAS + park&#x2F;unpark CAS 无锁竞争 state，失败后通过 LockSupport.park 阻塞线程，避免自旋空转
独占&#x2F;共享双模式 独占模式同一时刻一个线程获取（ReentrantLock），共享模式允许多个线程同时获取（Semaphore）
基于 AQS 的并发工具AbstractQueuedSynchronizer ├── ReentrantLock │ ├── FairSync（公平锁） │ └── NonfairSync（非公平锁） ├── ReentrantReadWriteLock │ ├── ReadLock（共享模式） │ └── WriteLock（独占模式） ├── Semaphore │ ├── FairSync │ └── NonfairSync ├── CountDownLatch（共享模式） └── 自定义同步器（Mutex、Limiter 等）
核心数据结构state 变量state 是 AQS 的灵魂——一个 volatile int 变量，不同并发工具赋予它完全不同的语义。 // AQS 的核心：一个 volatile int state 变量private volatile int state;// 获取 stateprotected final int getState() &#123; return state;&#125;// 设置 state（仅在持有锁时使用，不需要 CAS）protected final void setState(int newState) &#123; state = newState;&#125;// CAS 修改 state（竞争时使用，保证原子性）protected final boolean compareAndSetState(int expect, int update) &#123; return unsafe.compareAndSwapInt(this, stateOffset, expect, update);&#125;
state 在不同工具中的语义：
并发工具 state 语义 state&#x3D;0 含义 state&gt;0 含义
ReentrantLock 锁计数 未锁定 锁定（重入次数）
ReentrantReadWriteLock 高16位读锁计数 + 低16位写锁计数 无锁 读锁&#x2F;写锁被持有
Semaphore 剩余许可数 无许可可用 剩余许可数量
CountDownLatch 剩余计数 计数归零，所有线程放行 还需等待的数量
CLH 双向等待队列AQS 使用 CLH（Craig, Landin, and Hagersten）队列的变体来管理等待获取同步状态的线程。队列是一个 FIFO 双向链表，头节点是哨兵节点（已获取锁的线程），后续节点是等待中的线程。 static final class Node &#123; // ====== 模式标记 ====== static final Node SHARED = new Node(); // 共享模式标记 static final Node EXCLUSIVE = null; // 独占模式标记 // ====== 等待状态（waitStatus）====== static final int CANCELLED = 1; // 线程已取消（超时/中断） static final int SIGNAL = -1; // 后继线程需要被唤醒 static final int CONDITION = -2; // 线程在 Condition 队列中等待 static final int PROPAGATE = -3; // 共享模式传播唤醒 // ====== 节点字段 ====== volatile int waitStatus; // 等待状态 volatile Node prev; // 前驱节点 volatile Node next; // 后继节点 volatile Thread thread; // 等待的线程 Node nextWaiter; // Condition 队列的后继节点 / 模式标记 // 判断是否共享模式 boolean isShared() &#123; return nextWaiter == SHARED; &#125; // 获取前驱节点 Node predecessor() throws NullPointerException &#123; Node p = prev; if (p == null) throw new NullPointerException(); return p; &#125;&#125;
CLH 队列结构图哨兵节点 ◄──► Node B ◄──► Node C ◄──► Node D：
ws&#x3D;SIGNAL ws&#x3D;SIGNAL ws&#x3D;SIGNAL ws&#x3D;0 thread&#x3D;null thread&#x3D;T2 thread&#x3D;T3 thread&#x3D;T4
waitStatus 状态转换图架构流程： flowchart TD N1[&quot;ws 0 初始状态&quot;] N2[&quot;wsSIGNAL wsCANCEL&quot;] N3[&quot;wsPROPAGATE (-1)&quot;] N4[&quot;(1) (-3) 后继需唤醒 线程已取消&quot;] N5[&quot;共享传播&quot;] N6[&quot;wsCONDITION (-2)&quot;] N7[&quot;Condition队列&quot;] N1 --&gt; N2 N1 --&gt; N3 N1 --&gt; N4 N1 --&gt; N5 N2 --&gt; N3 N2 --&gt; N4 N2 --&gt; N5 N3 --&gt; N2 N3 --&gt; N4 N3 --&gt; N5 N4 --&gt; N2 N4 --&gt; N3 N4 --&gt; N5 N5 --&gt; N2 N5 --&gt; N3 N5 --&gt; N4 N2 --&gt; N6 N2 --&gt; N7 N3 --&gt; N6 N3 --&gt; N7 N4 --&gt; N6 N4 --&gt; N7 N5 --&gt; N6 N5 --&gt; N7
独占模式源码分析独占模式（Exclusive）是 AQS 最基础的模式，同一时刻只有一个线程能获取同步状态。ReentrantLock 就是典型的独占模式实现。 acquire——获取锁的总入口public final void acquire(int arg) &#123; if (!tryAcquire(arg) &amp;&amp; // 1. 尝试获取锁（子类实现） acquireQueued(addWaiter(Node.EXCLUSIVE), arg)) // 2. 获取失败，入队等待 selfInterrupt(); // 3. 补充中断标志&#125;
这三步的逻辑关系： 线程请求获取锁 │ ▼ tryAcquire(arg) ──── 成功 ────► 返回，获取锁完成 │ 失败 │ ▼ addWaiter(EXCLUSIVE) ──► 创建 Node，加入 CLH 队列尾部 │ ▼ acquireQueued(node, arg) ──► 在队列中自旋/阻塞等待 │ ├─ 被中断唤醒 ──► selfInterrupt() 补充中断标志 └─ 正常获取 ────► 返回
tryAcquire——模板方法AQS 只提供框架，具体获取逻辑由子类实现。这是典型的模板方法模式。 // AQS 的默认实现：直接抛异常，强制子类重写protected boolean tryAcquire(int arg) &#123; throw new UnsupportedOperationException();&#125;
ReentrantLock 的公平锁实现： // ReentrantLock.FairSync.tryAcquire()protected final boolean tryAcquire(int acquires) &#123; final Thread current = Thread.currentThread(); int c = getState(); if (c == 0) &#123; // state=0，锁空闲 // 公平锁：先检查队列中是否有等待线程 if (!hasQueuedPredecessors() &amp;&amp; // 队列为空或自己就是队首 compareAndSetState(0, acquires)) &#123; // CAS 竞争 state setExclusiveOwnerThread(current); // 设置独占持有者 return true; &#125; &#125; else if (current == getExclusiveOwnerThread()) &#123; // 可重入：当前线程已经持有锁，state+1 int nextc = c + acquires; if (nextc &lt; 0) throw new Error(&quot;Maximum lock count exceeded&quot;); setState(nextc); // 已经持有锁，不需要 CAS return true; &#125; return false; // 获取失败&#125;
ReentrantLock 的非公平锁实现： // ReentrantLock.NonfairSync.tryAcquire()// 相比公平锁，少了 hasQueuedPredecessors() 检查final boolean nonfairTryAcquire(int acquires) &#123; final Thread current = Thread.currentThread(); int c = getState(); if (c == 0) &#123; // 非公平锁：直接 CAS 竞争，不管队列中有没有等待线程 if (compareAndSetState(0, acquires)) &#123; setExclusiveOwnerThread(current); return true; &#125; &#125; else if (current == getExclusiveOwnerThread()) &#123; int nextc = c + acquires; if (nextc &lt; 0) throw new Error(&quot;Maximum lock count exceeded&quot;); setState(nextc); return true; &#125; return false;&#125;
公平锁 vs 非公平锁的核心区别： 公平锁获取流程： tryAcquire → hasQueuedPredecessors()? → CAS state → 成功/失败 │ ├─ 队列有等待线程 → 放弃竞争，保证先到先得 └─ 队列空 → CAS 竞争非公平锁获取流程： tryAcquire → CAS state → 成功/失败 │ └─ 直接竞争，不管队列（允许插队）
addWaiter——入队获取锁失败的线程需要封装为 Node 节点，加入 CLH 队列尾部。 private Node addWaiter(Node mode) &#123; // 1. 创建 Node 节点 Node node = new Node(Thread.currentThread(), mode); // 2. 快速尝试在尾部添加（乐观策略） Node pred = tail; if (pred != null) &#123; node.prev = pred; // 先设置 prev（不需要 CAS） if (compareAndSetTail(pred, node)) &#123; // CAS 设置 tail 指向新节点 pred.next = node; // 成功后才设置旧 tail 的 next return node; &#125; // CAS 失败，说明有其他线程竞争入队，走 enq 自旋 &#125; // 3. 快速入队失败，走自旋入队 enq(node); return node;&#125;
enq——自旋入队当快速入队 CAS 失败时，通过自旋保证节点一定能成功入队。 private Node enq(final Node node) &#123; for (;;) &#123; // 自旋，直到成功 Node t = tail; if (t == null) &#123; // 队列为空，需要初始化：创建哨兵节点 if (compareAndSetHead(new Node())) // CAS 设置 head tail = head; // head 和 tail 指向同一个哨兵节点 &#125; else &#123; // 队列已初始化，正常入队 node.prev = t; // 先设置 prev if (compareAndSetTail(t, node)) &#123; // CAS 设置 tail t.next = node; // 成功后设置 next return t; &#125; // CAS 失败，继续自旋 &#125; &#125;&#125;
入队过程图解： 架构流程： flowchart TD N1[&quot;哨兵节点 threadnull&quot;] N2[&quot;哨兵节点 Node B&quot;] N3[&quot;threadnull&quot;] N4[&quot;threadT2&quot;] N5[&quot;哨兵节点 Node B Node C&quot;] N6[&quot;threadT2 threadT3&quot;] N1 --&gt; N2 N1 --&gt; N3 N1 --&gt; N4 N2 --&gt; N5 N2 --&gt; N3 N2 --&gt; N6 N3 --&gt; N5 N3 --&gt; N6 N4 --&gt; N5 N4 --&gt; N3 N4 --&gt; N6
acquireQueued——队列中自旋&#x2F;阻塞等待节点入队后，线程进入自旋逻辑：如果前驱是 head 就尝试获取锁，否则阻塞等待。 final boolean acquireQueued(final Node node, int arg) &#123; boolean failed = true; // 标记是否获取成功 try &#123; boolean interrupted = false; // 标记是否被中断 for (;;) &#123; // 自旋 final Node p = node.predecessor(); // 获取前驱节点 if (p == head &amp;&amp; tryAcquire(arg)) &#123; // 前驱是 head 且获取锁成功 → 出队 setHead(node); // 当前节点成为新的 head（哨兵） p.next = null; // 断开旧 head 的 next，help GC failed = false; return interrupted; // 返回等待期间是否被中断 &#125; // 获取锁失败，判断是否需要阻塞 if (shouldParkAfterFailedAcquire(p, node) &amp;&amp; // 前驱状态是否允许阻塞 parkAndCheckInterrupt()) // 阻塞当前线程 interrupted = true; &#125; &#125; finally &#123; if (failed) cancelAcquire(node); // 获取失败（异常/超时），取消节点 &#125;&#125;
acquireQueued 的自旋逻辑： 架构流程： flowchart TD N1[&quot;predecessor()&quot;] N2[&quot;然后重试自旋 被唤醒&quot;] N3[&quot;重试自旋 检查中断标志&quot;] N4[&quot;head&quot;] N1 --&gt; N2 N1 --&gt; N3 N4 --&gt; N2 N4 --&gt; N3 N2 --&gt; N3 N3 --&gt; N2
shouldParkAfterFailedAcquire——判断是否应该阻塞不是获取锁失败就立即阻塞，必须确保前驱节点的 waitStatus 为 SIGNAL，这样前驱释放锁时才会唤醒当前线程。 private static boolean shouldParkAfterFailedAcquire(Node pred, Node node) &#123; int ws = pred.waitStatus; if (ws == Node.SIGNAL) &#123; // 前驱已经设置了 SIGNAL → 它释放锁时会唤醒我 → 可以安全阻塞 return true; &#125; if (ws &gt; 0) &#123; // 前驱已取消（CANCELLED=1 是唯一大于0的状态） // 跳过所有取消的节点，找到第一个未取消的前驱 do &#123; node.prev = pred = pred.prev; &#125; while (pred.waitStatus &gt; 0); pred.next = node; // 重新链接 &#125; else &#123; // 前驱状态为 0 或 PROPAGATE → CAS 设置为 SIGNAL // 确保前驱释放锁时会唤醒当前线程 compareAndSetWaitStatus(pred, ws, Node.SIGNAL); &#125; return false; // 不能直接阻塞，需要重试自旋&#125;
跳过取消节点的图解： 清理前： head ──► [哨兵] ◄──► [B:CANCEL] ◄──► [C:CANCEL] ◄──► [D:0] ◄──► [E:SIGNAL]清理后（从 E 的视角）： head ──► [哨兵] ◄──────────────────────────────► [D:0] ◄──► [E:SIGNAL] 跳过了 B、C 两个取消节点
parkAndCheckInterrupt——阻塞当前线程private boolean parkAndCheckInterrupt() &#123; LockSupport.park(this); // 阻塞当前线程 return Thread.interrupted(); // 清除中断标志并返回&#125;
release——释放锁public final boolean release(int arg) &#123; if (tryRelease(arg)) &#123; // 1. 尝试释放锁（子类实现） Node h = head; if (h != null &amp;&amp; h.waitStatus != 0) unparkSuccessor(h); // 2. 唤醒后继节点 return true; &#125; return false;&#125;
tryRelease——ReentrantLock 的实现// ReentrantLock.Sync.tryRelease()protected final boolean tryRelease(int releases) &#123; int c = getState() - releases; // 安全检查：只有锁持有者才能释放 if (Thread.currentThread() != getExclusiveOwnerThread()) throw new IllegalMonitorStateException(); boolean free = false; if (c == 0) &#123; // state=0，完全释放锁 free = true; setExclusiveOwnerThread(null); // 清除持有者 &#125; setState(c); // 还未完全释放，只更新 state（已持有锁，不需要 CAS） return free;&#125;
unparkSuccessor——唤醒后继节点private void unparkSuccessor(Node node) &#123; int ws = node.waitStatus; if (ws &lt; 0) compareAndSetWaitStatus(node, ws, 0); // 清除等待状态 Node s = node.next; if (s == null || s.waitStatus &gt; 0) &#123; // 后继为空或已取消 → 从尾部向前遍历，找到最靠近 head 的未取消节点 s = null; for (Node t = tail; t != null &amp;&amp; t != node; t = t.prev) if (t.waitStatus &lt;= 0) s = t; &#125; if (s != null) LockSupport.unpark(s.thread); // 唤醒后继线程&#125;
为什么从尾部向前遍历而不是从头部向后遍历？ 因为在 addWaiter 中，入队操作不是原子的： Step 1: node.prev = pred; // prev 指针先设置 Step 2: CAS(tail, node); // tail 指针更新 Step 3: pred.next = node; // next 指针最后设置如果从 head 向后遍历（沿 next 指针），可能遇到 next 还未设置的情况，导致遍历不到新入队的节点。而从 tail 向前遍历（沿 prev 指针），因为 prev 是最先设置的，所以一定能遍历到所有节点。 head ──► [A] ──► [B] ──x── [C] ◄── tail │ next │ 未设置！ [B] ◄── [C] prev 已设置
独占模式完整时序图时间线 线程A（持锁） 线程B（等待） 线程C（等待） CLH 队列 t0 lock()成功 head=null t1 lock()失败 addWaiter() [哨兵]↔[B] t2 lock()失败 [哨兵]↔[B]↔[C] t3 park()阻塞 park()阻塞 t4 tryRelease() ◄── unpark ── t5 tryAcquire()成功 [哨兵]↔[C] setHead(B) B成为新哨兵 t6 unlock()返回 t7 ◄── unpark ── t8 tryAcquire()成功 [C成为哨兵]
共享模式源码分析共享模式（Shared）允许多个线程同时获取同步状态。Semaphore、CountDownLatch 都是共享模式的实现。与独占模式的关键区别在于：共享模式获取成功后会传播唤醒后续共享节点。 acquireShared——共享获取入口public final void acquireShared(int arg) &#123; if (tryAcquireShared(arg) &lt; 0) // 1. 尝试共享获取（子类实现） doAcquireShared(arg); // 2. 获取失败，入队等待&#125;
tryAcquireShared——Semaphore 公平锁实现// Semaphore.FairSync.tryAcquireShared()protected int tryAcquireShared(int acquires) &#123; for (;;) &#123; // 公平锁：先检查队列中是否有等待线程 if (hasQueuedPredecessors()) return -1; // 队列有等待者，获取失败 int available = getState(); int remaining = available - acquires; if (remaining &lt; 0 || compareAndSetState(available, remaining)) return remaining; // remaining &gt;= 0：获取成功，返回剩余许可数 // remaining &lt; 0：获取失败，许可不足 // CAS 失败：其他线程竞争，重试 &#125;&#125;
doAcquireShared——共享模式入队等待private void doAcquireShared(int arg) &#123; final Node node = addWaiter(Node.SHARED); // 共享模式节点 boolean failed = true; try &#123; boolean interrupted = false; for (;;) &#123; Node p = node.predecessor(); if (p == head) &#123; int r = tryAcquireShared(arg); if (r &gt;= 0) &#123; // 获取成功！设置新 head 并传播唤醒 setHeadAndPropagate(node, r); p.next = null; // help GC if (interrupted) selfInterrupt(); failed = false; return; &#125; &#125; // 与独占模式相同的阻塞判断逻辑 if (shouldParkAfterFailedAcquire(p, node) &amp;&amp; parkAndCheckInterrupt()) interrupted = true; &#125; &#125; finally &#123; if (failed) cancelAcquire(node); &#125;&#125;
setHeadAndPropagate——传播唤醒这是共享模式的核心。当一个共享节点获取成功后，如果还有剩余资源，需要继续唤醒后续的共享节点。 private void setHeadAndPropagate(Node node, int propagate) &#123; Node h = head; // 记录旧 head setHead(node); // 设置新 head // 判断是否需要传播唤醒 if (propagate &gt; 0 || h == null || h.waitStatus &lt; 0 || (h = head) == null || h.waitStatus &lt; 0) &#123; Node s = node.next; if (s == null || s.isShared()) doReleaseShared(); // 唤醒后继共享节点 &#125;&#125;
传播唤醒的含义： Semaphore(permits=3) 的传播唤醒场景：初始：3 个许可，A、B、C 三个线程等待Step 1：线程 T 释放 3 个许可 state: 0 → 3Step 2：唤醒 head.next（线程A） tryAcquireShared(1) → remaining=2 &gt;= 0，成功！ setHeadAndPropagate(node, 2) ← propagate=2，还有剩余许可Step 3：传播唤醒线程B tryAcquireShared(1) → remaining=1 &gt;= 0，成功！ setHeadAndPropagate(node, 1) ← propagate=1，还有剩余许可Step 4：传播唤醒线程C tryAcquireShared(1) → remaining=0 &gt;= 0，成功！ setHeadAndPropagate(node, 0) ← propagate=0，无剩余许可，停止传播结果：3 个等待线程全部被唤醒，许可恰好用完
releaseShared——共享释放public final boolean releaseShared(int arg) &#123; if (tryReleaseShared(arg)) &#123; // 1. 尝试释放（子类实现） doReleaseShared(); // 2. 唤醒等待的共享节点 return true; &#125; return false;&#125;
doReleaseShared——共享模式唤醒核心private void doReleaseShared() &#123; for (;;) &#123; Node h = head; if (h != null &amp;&amp; h != tail) &#123; int ws = h.waitStatus; if (ws == Node.SIGNAL) &#123; // head 状态为 SIGNAL，需要唤醒后继 if (!compareAndSetWaitStatus(h, Node.SIGNAL, 0)) continue; // CAS 失败，重试 unparkSuccessor(h); // 唤醒后继线程 &#125; else if (ws == 0 &amp;&amp; !compareAndSetWaitStatus(h, 0, Node.PROPAGATE)) &#123; continue; // 设置 PROPAGATE 状态，确保后续传播 &#125; &#125; // head 未变化，退出自旋 if (h == head) break; &#125;&#125;
CountDownLatch 的 AQS 实现CountDownLatch 是共享模式的典型应用。初始化时设置 state &#x3D; count，每次 countDown 将 state 减 1，当 state 归零时唤醒所有等待线程。 // CountDownLatch.Syncprivate static final class Sync extends AbstractQueuedSynchronizer &#123; Sync(int count) &#123; setState(count); // 初始化计数 &#125; int getCount() &#123; return getState(); &#125; // await() 调用：state==0 时返回 1（通过），否则返回 -1（阻塞） protected int tryAcquireShared(int acquires) &#123; return (getState() == 0) ? 1 : -1; &#125; // countDown() 调用：CAS 将 state-1 protected boolean tryReleaseShared(int releases) &#123; for (;;) &#123; int c = getState(); if (c == 0) return false; // 已经归零，不需要再减 int nextc = c - 1; if (compareAndSetState(c, nextc)) return nextc == 0; // state 减到 0 时返回 true，触发唤醒 &#125; &#125;&#125;
CountDownLatch 工作流程： CountDownLatch(3) 三个线程 countDown，主线程 await初始 state=3：时间线 线程1 线程2 线程3 主线程 state t0 await() 3 t1 park() 3 t2 countDown() 2 t3 countDown() 1 t4 countDown() 0 t5 unpark() 0 t6 继续执行state 归零时 tryReleaseShared 返回 true→ doReleaseShared() 唤醒所有等待线程
Condition 接口实现Condition 是 AQS 对 Object.wait&#x2F;notify 的增强实现，支持多个等待队列、精确唤醒、不依赖 synchronized。 Condition 队列与 CLH 队列的关系Node A ◄──► Node B Node X ───► Node Y ───►：
(持锁运行) (等锁) (等条件) (等条件)
await——等待条件// ConditionObject.await()public final void await() throws InterruptedException &#123; if (Thread.interrupted()) throw new InterruptedException(); // 1. 创建新节点，加入 Condition 等待队列 Node node = addConditionWaiter(); // 2. 完全释放锁（包括重入），保存持有锁时的 state int savedState = fullyRelease(node); int interruptMode = 0; // 3. 循环检查：节点是否已经被移到 CLH 队列 while (!isOnSyncQueue(node)) &#123; LockSupport.park(this); // 不在 CLH 队列中，阻塞等待 if ((interruptMode = checkInterruptWhileWaiting(node)) != 0) break; &#125; // 4. 被信号唤醒或中断后，重新竞争锁 if (acquireQueued(node, savedState) &amp;&amp; interruptMode != THROW_IE) interruptMode = REINTERRUPT; // 5. 清理 Condition 队列中取消的节点 if (node.nextWaiter != null) unlinkCancelledWaiters(); if (interruptMode != 0) reportInterruptAfterWait(interruptMode);&#125;
signal——唤醒等待线程// ConditionObject.signal()public final void signal() &#123; // 检查当前线程是否持有锁 if (!isHeldExclusively()) throw new IllegalMonitorStateException(); Node first = firstWaiter; if (first != null) doSignal(first); // 唤醒 Condition 队列的第一个节点&#125;// 将节点从 Condition 队列移到 CLH 队列private void doSignal(Node first) &#123; do &#123; if ((firstWaiter = first.nextWaiter) == null) lastWaiter = null; first.nextWaiter = null; &#125; while (!transferForSignal(first) &amp;&amp; // CAS 修改节点状态并入队 (first = firstWaiter) != null);&#125;// 将节点从 Condition 队列转移到 CLH 队列final boolean transferForSignal(Node node) &#123; // CAS 修改 waitStatus：CONDITION → 0 if (!compareAndSetWaitStatus(node, Node.CONDITION, 0)) return false; // 节点已取消 // 入队到 CLH 队列尾部 Node p = enq(node); int ws = p.waitStatus; // 设置前驱为 SIGNAL（确保会被唤醒） if (ws &gt; 0 || !compareAndSetWaitStatus(p, ws, Node.SIGNAL)) LockSupport.unpark(node.thread); // 前驱已取消或 CAS 失败，直接唤醒 return true;&#125;
await&#x2F;signal 完整工作流程架构流程： flowchart TD N1[&quot;CLH队列 释放锁&quot;] N2[&quot;Condition&quot;] N3[&quot;transfer CLH队列&quot;] N4[&quot;unpark() 等待队列&quot;] N5[&quot;ForSignal (等锁)&quot;] N6[&quot;入队 Condition park() (持锁) savedState 等待队列&quot;] N1 --&gt; N2 N1 --&gt; N3 N1 --&gt; N4 N1 --&gt; N5 N6 --&gt; N2 N6 --&gt; N3 N6 --&gt; N4 N6 --&gt; N5
公平锁 vs 非公平锁深度对比源码层面的区别// ===== 公平锁 FairSync =====final void lock() &#123; acquire(1); // 直接走 acquire → tryAcquire → hasQueuedPredecessors&#125;protected final boolean tryAcquire(int acquires) &#123; final Thread current = Thread.currentThread(); int c = getState(); if (c == 0) &#123; if (!hasQueuedPredecessors() &amp;&amp; // ← 关键区别：检查队列 compareAndSetState(0, acquires)) &#123; setExclusiveOwnerThread(current); return true; &#125; &#125; // ... 可重入逻辑&#125;// ===== 非公平锁 NonfairSync =====final void lock() &#123; if (compareAndSetState(0, 1)) // ← 关键区别：上来就 CAS 插队 setExclusiveOwnerThread(Thread.currentThread()); else acquire(1);&#125;protected final boolean tryAcquire(int acquires) &#123; return nonfairTryAcquire(acquires); // 不检查 hasQueuedPredecessors，直接 CAS&#125;
性能对比
指标 公平锁 非公平锁
吞吐量 低（线程上下文切换多） 高（减少上下文切换）
平均等待时间 低 高（队列尾部线程可能等待更久）
最大等待时间 可控 不可控（可能线程饥饿）
上下文切换次数 多 少
适用场景 需要严格公平性 高并发，允许短暂不公平
非公平锁为什么吞吐量更高非公平锁的&quot;插队&quot;优势：时间线 线程A(持锁) 线程B(等待) 线程C(新来) t0 持有锁 t1 释放锁 unpark(B) t2 lock() → CAS成功！ t3 醒来，CAS失败非公平锁：线程C 刚好到达，CAS 直接获取锁 - 线程C 在 CPU 上运行，无需上下文切换 - 线程B 还在唤醒中，避免了&quot;唤醒后又要切换&quot;的开销公平锁：线程C 必须排队 - 线程B 先唤醒，获取锁 - 线程C 入队等待，需要 park → 未来再 unpark - 多了一次上下文切换
AQS 在并发工具中的应用总结各工具对 AQS 的使用方式
并发工具 模式 state 含义 tryAcquire tryRelease
ReentrantLock 独占 0&#x3D;未锁定，&gt;0&#x3D;重入次数 CAS 0→1 &#x2F; 重入 state+1 state-1，&#x3D;0 释放
Semaphore 共享 剩余许可数 state-acquires，&lt;0 失败 state+releases
CountDownLatch 共享 剩余计数 state&#x3D;&#x3D;0 通过，否则阻塞 state-1，&#x3D;0 唤醒
ReentrantReadWriteLock 共享+独占 高16位读锁 &#x2F; 低16位写锁 写锁 CAS &#x2F; 读锁 CAS 高16位 写锁-1 &#x2F; 读锁-1
ReentrantReadWriteLock 的 state 划分&#x2F;&#x2F; 读锁持有次数 写锁重入次数：
可中断与超时获取可中断获取——acquireInterruptiblypublic final void acquireInterruptibly(int arg) throws InterruptedException &#123; if (Thread.interrupted()) throw new InterruptedException(); if (!tryAcquire(arg)) doAcquireInterruptibly(arg); // 与 acquireQueued 类似，但被中断时直接抛异常&#125;private void doAcquireInterruptibly(int arg) throws InterruptedException &#123; final Node node = addWaiter(Node.EXCLUSIVE); boolean failed = true; try &#123; for (;;) &#123; final Node p = node.predecessor(); if (p == head &amp;&amp; tryAcquire(arg)) &#123; setHead(node); p.next = null; failed = false; return; &#125; if (shouldParkAfterFailedAcquire(p, node) &amp;&amp; parkAndCheckInterrupt()) throw new InterruptedException(); // ← 关键区别：被中断直接抛异常 &#125; &#125; finally &#123; if (failed) cancelAcquire(node); &#125;&#125;
超时获取——tryAcquireNanospublic final boolean tryAcquireNanos(int arg, long nanosTimeout) throws InterruptedException &#123; if (Thread.interrupted()) throw new InterruptedException(); return tryAcquire(arg) || doAcquireNanos(arg, nanosTimeout);&#125;private boolean doAcquireNanos(int arg, long nanosTimeout) throws InterruptedException &#123; if (nanosTimeout &lt;= 0L) return false; long deadline = System.nanoTime() + nanosTimeout; final Node node = addWaiter(Node.EXCLUSIVE); boolean failed = true; try &#123; for (;;) &#123; final Node p = node.predecessor(); if (p == head &amp;&amp; tryAcquire(arg)) &#123; setHead(node); p.next = null; failed = false; return true; &#125; nanosTimeout = deadline - System.nanoTime(); if (nanosTimeout &lt;= 0L) return false; // ← 超时，返回 false if (shouldParkAfterFailedAcquire(p, node) &amp;&amp; nanosTimeout &gt; SPIN_FOR_TIMEOUT_THRESHOLD) // 大于1ms才park LockSupport.parkNanos(this, nanosTimeout); if (Thread.interrupted()) throw new InterruptedException(); &#125; &#125; finally &#123; if (failed) cancelAcquire(node); &#125;&#125;
acquire vs acquireInterruptibly vs tryAcquireNanos
特性 acquire acquireInterruptibly tryAcquireNanos
响应中断 不响应，仅记录标志 响应，抛出 InterruptedException 响应，抛出 InterruptedException
超时支持 无 无 有
返回值 void void boolean
对应 API lock() lockInterruptibly() tryLock(time, unit)
自定义 AQS 同步器实战实现一个不可重入互斥锁public class MutexLock implements Lock &#123; private final Sync sync = new Sync(); private static class Sync extends AbstractQueuedSynchronizer &#123; // state=0 未锁定，state=1 锁定 @Override protected boolean tryAcquire(int arg) &#123; // CAS 设置 state 为 1 if (compareAndSetState(0, 1)) &#123; setExclusiveOwnerThread(Thread.currentThread()); return true; &#125; return false; &#125; @Override protected boolean tryRelease(int arg) &#123; if (getState() == 0) throw new IllegalMonitorStateException(); setExclusiveOwnerThread(null); setState(0); // 不需要 CAS，因为只有持锁线程才能释放 return true; &#125; @Override protected boolean isHeldExclusively() &#123; return getState() == 1; &#125; Condition newCondition() &#123; return new ConditionObject(); &#125; &#125; @Override public void lock() &#123; sync.acquire(1); &#125; @Override public void lockInterruptibly() throws InterruptedException &#123; sync.acquireInterruptibly(1); &#125; @Override public boolean tryLock() &#123; return sync.tryAcquire(1); &#125; @Override public boolean tryLock(long time, TimeUnit unit) throws InterruptedException &#123; return sync.tryAcquireNanos(1, unit.toNanos(time)); &#125; @Override public void unlock() &#123; sync.release(1); &#125; @Override public Condition newCondition() &#123; return sync.newCondition(); &#125;&#125;
实现一个限流器（共享模式）public class SimpleLimiter &#123; private final Sync sync; public SimpleLimiter(int permits) &#123; this.sync = new Sync(permits); &#125; private static class Sync extends AbstractQueuedSynchronizer &#123; Sync(int permits) &#123; setState(permits); &#125; @Override protected int tryAcquireShared(int arg) &#123; for (;;) &#123; int available = getState(); int remaining = available - arg; if (remaining &lt; 0 || compareAndSetState(available, remaining)) return remaining; &#125; &#125; @Override protected boolean tryReleaseShared(int arg) &#123; for (;;) &#123; int current = getState(); int next = current + arg; if (compareAndSetState(current, next)) return true; &#125; &#125; &#125; public void acquire() throws InterruptedException &#123; sync.acquireSharedInterruptibly(1); &#125; public void release() &#123; sync.releaseShared(1); &#125; public int availablePermits() &#123; return sync.getState(); &#125;&#125;
实现一个倒计时门闩public class SimpleCountDownLatch &#123; private final Sync sync; public SimpleCountDownLatch(int count) &#123; if (count &lt;= 0) throw new IllegalArgumentException(&quot;count &lt;= 0&quot;); this.sync = new Sync(count); &#125; private static class Sync extends AbstractQueuedSynchronizer &#123; Sync(int count) &#123; setState(count); &#125; int getCount() &#123; return getState(); &#125; @Override protected int tryAcquireShared(int acquires) &#123; return (getState() == 0) ? 1 : -1; &#125; @Override protected boolean tryReleaseShared(int releases) &#123; for (;;) &#123; int c = getState(); if (c == 0) return false; int nextc = c - 1; if (compareAndSetState(c, nextc)) return nextc == 0; &#125; &#125; &#125; public void await() throws InterruptedException &#123; sync.acquireSharedInterruptibly(1); &#125; public void countDown() &#123; sync.releaseShared(1); &#125; public long getCount() &#123; return sync.getCount(); &#125;&#125;
LockSupport 工具类park&#x2F;unpark 原理AQS 的线程阻塞和唤醒依赖 LockSupport 类，底层使用 Unsafe 的 park&#x2F;unpark 实现。 public class LockSupport &#123; // 阻塞当前线程 public static void park(Object blocker) &#123; Thread t = Thread.currentThread(); setBlocker(t, blocker); // 设置阻塞对象（用于诊断） U.park(false, 0L); // 调用 Unsafe.park setBlocker(t, null); // 清除阻塞对象 &#125; // 带超时的阻塞 public static void parkNanos(Object blocker, long nanos) &#123; if (nanos &gt; 0) &#123; Thread t = Thread.currentThread(); setBlocker(t, blocker); U.park(false, nanos); // 超时后自动返回 setBlocker(t, null); &#125; &#125; // 唤醒指定线程 public static void unpark(Thread thread) &#123; if (thread != null) U.unpark(thread); // 调用 Unsafe.unpark &#125;&#125;
park&#x2F;unpark vs Object.wait&#x2F;notify
特性 LockSupport.park&#x2F;unpark Object.wait&#x2F;notify
锁依赖 无锁依赖，任何位置调用 必须在 synchronized 块中
唤醒精度 精确唤醒指定线程 随机唤醒（notify）或全部唤醒（notifyAll）
调用顺序 unpark 可以在 park 之前调用（许可机制） notify 必须在 wait 之后调用
中断处理 不抛异常，返回后通过 Thread.interrupted() 检查 抛出 InterruptedException
虚假唤醒 需要循环检查条件 需要循环检查条件
适用场景 AQS 等高级同步器 synchronized 配合使用
park&#x2F;unpark 的许可机制： 每个线程内部有一个 &quot;permit&quot; 标志（0 或 1）park()： - permit == 0 → 阻塞线程 - permit == 1 → 消费 permit（设为0），立即返回unpark(thread)： - 将 thread 的 permit 设为 1 - 如果 thread 正在 park 阻塞，则唤醒它 - 如果 thread 还未 park，则下次 park 不会阻塞这就是为什么 unpark 可以在 park 之前调用的原因： t1: unpark(T2) → T2 的 permit = 1 t2: park() → 检查 permit = 1，消费后立即返回，不阻塞
cancelAcquire——取消获取当线程在获取锁的过程中被中断或超时，需要取消获取并清理队列。 private void cancelAcquire(Node node) &#123; if (node == null) return; node.thread = null; // 清除线程引用 // 跳过已取消的前驱节点 Node pred = node.prev; while (pred.waitStatus &gt; 0) &#123; node.prev = pred = pred.prev; &#125; Node predNext = pred.next; // 记录有效前驱的 next node.waitStatus = Node.CANCELLED; // 设置为已取消 // 情况1：如果自己是尾节点，直接移除 if (node == tail &amp;&amp; compareAndSetTail(node, pred)) &#123; compareAndSetNext(pred, predNext, null); &#125; else &#123; // 情况2：如果前驱不是头节点且状态有效，尝试将后继链接到前驱 int ws; if (pred != head &amp;&amp; ((ws = pred.waitStatus) == Node.SIGNAL || (ws &lt;= 0 &amp;&amp; compareAndSetWaitStatus(pred, ws, Node.SIGNAL))) &amp;&amp; pred.thread != null) &#123; Node next = node.next; if (next != null &amp;&amp; next.waitStatus &lt;= 0) compareAndSetNext(pred, predNext, next); &#125; else &#123; // 情况3：唤醒后继节点 unparkSuccessor(node); &#125; node.next = node; // help GC &#125;&#125;
生产环境注意事项1. 锁超时处理// 使用 tryLock 避免无限等待Lock lock = new ReentrantLock();if (lock.tryLock(5, TimeUnit.SECONDS)) &#123; try &#123; // 执行业务逻辑 &#125; finally &#123; lock.unlock(); &#125;&#125; else &#123; // 超时处理 throw new RuntimeException(&quot;获取锁超时&quot;);&#125;
2. 避免死锁// 解决：按固定顺序获取锁public void safeTransfer(Lock from, Lock to) &#123; // 始终先获取 hash 值较小的锁 Lock first = from.hashCode() &lt; to.hashCode() ? from : to; Lock second = from.hashCode() &lt; to.hashCode() ? to : from; first.lock(); try &#123; second.lock(); try &#123; // 执行业务 &#125; finally &#123; second.unlock(); &#125; &#125; finally &#123; first.unlock(); &#125;&#125;
3. 正确使用 Condition// 必须在循环中检查条件（防止虚假唤醒）lock.lock();try &#123; while (!conditionMet()) &#123; condition.await(); &#125; // 执行操作&#125; finally &#123; lock.unlock();&#125;
4. 锁与事务的顺序// 正确：先提交事务再释放锁lock.lock();try &#123; doBusiness(); transactionManager.commit(); // 先提交&#125; finally &#123; lock.unlock(); // 后释放&#125;// 错误：先释放锁再提交事务// 其他线程可能读到未提交的数据
常见项目问题与解决方案在实际项目的并发编程实践中，我们遇到过大量与 AQS 相关的问题。以下是总结的 15 个常见问题与解决方案： 面试高频问题深度解析1. AQS 的原理是什么？AQS 通过 volatile int state + CLH 双向等待队列实现同步。state 表示同步状态，由 volatile 保证可见性、CAS 保证原子性。队列存放等待获取同步状态的线程。AQS 定义了 acquire&#x2F;release 等模板流程，子类只需实现 tryAcquire&#x2F;tryRelease 即可定义自己的同步语义。 2. AQS 为什么用 volatile state 而不是 AtomicInteger？// volatile + CAS 比 AtomicInteger 更灵活private volatile int state;// 原因：// 1. state 可以被赋予不同含义（锁计数、许可数等），子类需要直接读写 state// 2. setState() 在已持锁场景下不需要 CAS，直接赋值更高效// 3. AtomicInteger 内部也是 volatile int + CAS，但封装后无法直接赋值// 4. AQS 需要 compareAndSetState 精确控制 CAS 的期望值
3. 公平锁和非公平锁的实现区别？公平锁在 tryAcquire 中先检查 hasQueuedPredecessors()，队列有等待线程就不插队。非公平锁直接 CAS 竞争 state，允许插队。非公平锁吞吐量更高（减少上下文切换），但可能导致线程饥饿。 4. 独占模式和共享模式的区别？独占模式同一时刻只有一个线程获取（ReentrantLock），共享模式允许多个线程同时获取（Semaphore、CountDownLatch）。共享模式获取成功后会通过 setHeadAndPropagate 传播唤醒后续共享节点，这是与独占模式最核心的区别。 5. 为什么 unparkSuccessor 从尾部向前遍历？因为 addWaiter 中入队操作不是原子的：先设置 node.prev，再 CAS 设置 tail，最后设置 pred.next。从 head 向后遍历可能遇到 next 还未设置的情况。而从 tail 向前遍历，prev 是最先设置的，一定能遍历到所有节点。 6. AQS 的模板方法模式体现在哪？AQS 定义模板流程： 子类实现具体逻辑： acquire() tryAcquire() release() tryRelease() acquireShared() tryAcquireShared() releaseShared() tryReleaseShared() isHeldExclusively()AQS 负责：入队、阻塞、唤醒、取消、传播子类负责：state 的获取/释放语义
7. park&#x2F;unpark 与 Object.wait&#x2F;notify 的区别？
特性 park&#x2F;unpark wait&#x2F;notify
锁关联 无锁依赖 必须在 synchronized 块中
唤醒方式 精确唤醒单个线程 随机唤醒或全部唤醒
调用顺序 unpark 可以在 park 之前 notify 必须在 wait 之后
中断处理 不抛异常，返回后检查 抛出 InterruptedException
底层实现 Unsafe.park&#x2F;unpark ObjectMonitor
性能对比与选型建议锁类型对比
