配置server:  port: 8080spring:  application:    name: mine-gateway  cloud:    nacos:      discovery:        server-addr: nacos.mine-cloud.com:8848        namespace: $&#123;NAMESPACE:dev&#125;      config:        server-addr: nacos.mine-cloud.com:8848        namespace: $&#123;NAMESPACE:dev&#125;        file-extension: yaml    gateway:      routes:        - id: mine-device          uri: lb://mine-device          predicates:            - Path=/api/device/**          filters:            - StripPrefix=1        - id: mine-alert          uri: lb://mine-alert          predicates:            - Path=/api/alert/**          filters:            - StripPrefix=1        - id: mine-location          uri: lb://mine-location          predicates:            - Path=/api/location/**          filters:            - StripPrefix=1        - id: mine-dispatch          uri: lb://mine-dispatch          predicates:            - Path=/api/dispatch/**          filters:            - StripPrefix=1

全局过滤器：认证与限流@Component@Slf4jpublic class AuthGlobalFilter implements GlobalFilter, Ordered &#123;    @Autowired    private RedisTemplate&lt;String, Object&gt; redisTemplate;    @Override    public Mono&lt;Void&gt; filter(ServerWebExchange exchange, GatewayFilterChain chain) &#123;        String path = exchange.getRequest().getURI().getPath();        // 白名单路径放行        if (path.contains(&quot;/auth/login&quot;) || path.contains(&quot;/auth/register&quot;)) &#123;            return chain.filter(exchange);        &#125;        // 检查Token        String token = exchange.getRequest().getHeaders().getFirst(&quot;Authorization&quot;);        if (token == null || !validateToken(token)) &#123;            exchange.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);            return exchange.getResponse().setComplete();        &#125;        // 传递用户信息到下游服务        String userId = parseUserId(token);        String mineCode = parseMineCode(token);        ServerHttpRequest request = exchange.getRequest().mutate()            .header(&quot;X-User-Id&quot;, userId)            .header(&quot;X-Mine-Code&quot;, mineCode)            .build();        log.debug(&quot;[网关] 请求路由: path=&#123;&#125;, userId=&#123;&#125;, mineCode=&#123;&#125;&quot;, path, userId, mineCode);        return chain.filter(exchange.mutate().request(request).build());    &#125;    private boolean validateToken(String token) &#123;        try &#123;            String userId = JWT.decode(token.replace(&quot;Bearer &quot;, &quot;&quot;)).getClaim(&quot;userId&quot;).asString();            return redisTemplate.hasKey(&quot;token:&quot; + userId);        &#125; catch (Exception e) &#123;            return false;        &#125;    &#125;    @Override    public int getOrder() &#123;        return -1;    &#125;&#125;

设备监控服务依赖&lt;dependencies&gt;    &lt;dependency&gt;        &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;        &lt;artifactId&gt;spring-boot-starter-web&lt;/artifactId&gt;    &lt;/dependency&gt;    &lt;dependency&gt;        &lt;groupId&gt;com.alibaba.cloud&lt;/groupId&gt;        &lt;artifactId&gt;spring-cloud-starter-alibaba-nacos-discovery&lt;/artifactId&gt;    &lt;/dependency&gt;    &lt;dependency&gt;        &lt;groupId&gt;com.alibaba.cloud&lt;/groupId&gt;        &lt;artifactId&gt;spring-cloud-starter-alibaba-nacos-config&lt;/artifactId&gt;    &lt;/dependency&gt;    &lt;dependency&gt;        &lt;groupId&gt;org.springframework.cloud&lt;/groupId&gt;        &lt;artifactId&gt;spring-cloud-starter-openfeign&lt;/artifactId&gt;    &lt;/dependency&gt;    &lt;dependency&gt;        &lt;groupId&gt;org.springframework.cloud&lt;/groupId&gt;        &lt;artifactId&gt;spring-cloud-starter-loadbalancer&lt;/artifactId&gt;    &lt;/dependency&gt;    &lt;dependency&gt;        &lt;groupId&gt;com.mine&lt;/groupId&gt;        &lt;artifactId&gt;mqtt-spring-boot-starter&lt;/artifactId&gt;        &lt;version&gt;1.0.0&lt;/version&gt;    &lt;/dependency&gt;&lt;/dependencies&gt;

bootstrap.yamlspring:  application:    name: mine-device  cloud:    nacos:      discovery:        server-addr: nacos.mine-cloud.com:8848        namespace: $&#123;NAMESPACE:dev&#125;      config:        server-addr: nacos.mine-cloud.com:8848        namespace: $&#123;NAMESPACE:dev&#125;        file-extension: yaml        shared-configs:          - data-id: common.yaml            refresh: true          - data-id: mqtt.yaml            refresh: true

Feign客户端@FeignClient(name = &quot;mine-alert&quot;, fallbackFactory = AlertClientFallbackFactory.class)public interface AlertClient &#123;    @PostMapping(&quot;/alert/create&quot;)    Result&lt;Void&gt; createAlert(@RequestBody AlertCreateDTO dto);    @GetMapping(&quot;/alert/device/&#123;deviceId&#125;&quot;)    Result&lt;List&lt;AlertVO&gt;&gt; getByDeviceId(@PathVariable(&quot;deviceId&quot;) Long deviceId);&#125;@Component@Slf4jpublic class AlertClientFallbackFactory implements FallbackFactory&lt;AlertClient&gt; &#123;    @Override    public AlertClient create(Throwable cause) &#123;        log.error(&quot;[设备服务] 预警服务调用失败: &#123;&#125;&quot;, cause.getMessage());        return dto -&gt; Result.fail(&quot;预警服务不可用&quot;);    &#125;&#125;

启动类@EnableFeignClients@EnableDiscoveryClient@SpringBootApplicationpublic class MineDeviceApplication &#123;    public static void main(String[] args) &#123;        SpringApplication.run(MineDeviceApplication.class, args);    &#125;&#125;

安全预警服务服务间调用@Service@RequiredArgsConstructor@Slf4jpublic class AlertServiceImpl implements AlertService &#123;    private final AlertMapper alertMapper;    private final DeviceClient deviceClient;    @Override    @SentinelResource(value = &quot;createAlert&quot;, fallback = &quot;createAlertFallback&quot;)    public AlertVO createAlert(AlertCreateDTO dto) &#123;        // 1. 查询设备信息        Result&lt;DeviceVO&gt; deviceResult = deviceClient.getById(dto.getDeviceId());        if (deviceResult == null || !deviceResult.isSuccess()) &#123;            throw new BusinessException(&quot;设备不存在&quot;);        &#125;        // 2. 创建预警        Alert alert = new Alert();        alert.setDeviceId(dto.getDeviceId());        alert.setLevel(dto.getLevel());        alert.setType(dto.getType());        alert.setDescription(dto.getDescription());        alert.setStatus(AlertStatus.PENDING);        alertMapper.insert(alert);        log.info(&quot;[智慧矿山] 创建预警: alertId=&#123;&#125;, deviceId=&#123;&#125;, level=&#123;&#125;&quot;,            alert.getId(), dto.getDeviceId(), dto.getLevel());        return AlertVO.build(alert);    &#125;    public AlertVO createAlertFallback(AlertCreateDTO dto, Throwable ex) &#123;        log.error(&quot;[智慧矿山] 创建预警降级: &#123;&#125;&quot;, ex.getMessage());        throw new BusinessException(&quot;系统繁忙，请稍后重试&quot;);    &#125;&#125;

公共模块// 统一返回结果@Data@Builderpublic class Result&lt;T&gt; &#123;    private int code;    private String message;    private T data;    public static &lt;T&gt; Result&lt;T&gt; success(T data) &#123;        return Result.&lt;T&gt;builder().code(200).message(&quot;success&quot;).data(data).build();    &#125;    public static &lt;T&gt; Result&lt;T&gt; fail(String message) &#123;        return Result.&lt;T&gt;builder().code(500).message(message).build();    &#125;&#125;// 全局异常处理@RestControllerAdvicepublic class GlobalExceptionHandler &#123;    @ExceptionHandler(BusinessException.class)    public Result&lt;Void&gt; handleBusiness(BusinessException e) &#123;        return Result.fail(e.getMessage());    &#125;    @ExceptionHandler(Exception.class)    public Result&lt;Void&gt; handleException(Exception e) &#123;        log.error(&quot;系统异常&quot;, e);        return Result.fail(&quot;系统异常&quot;);    &#125;&#125;


面试高频问题1. SpringCloud微服务架构包含哪些组件？注册中心(Nacos)、配置中心(Nacos)、网关(Gateway)、服务调用(OpenFeign)、负载均衡(LoadBalancer)、熔断降级(Sentinel)。
2. Gateway的作用？统一入口、路由转发、身份认证、限流熔断、日志监控。所有外部请求先经过Gateway再路由到具体服务。
3. 微服务之间如何通信？同步调用：OpenFeign（推荐）。异步通信：MQ。选择：需要实时响应用Feign，不需要实时用MQ。
总结SpringCloud + Nacos是Java微服务的主流方案。从零搭建后，核心认知是：Nacos同时做注册中心和配置中心，Gateway做统一入口，OpenFeign做服务调用，Sentinel做熔断降级。微服务不是拆分越细越好，而是按业务域合理拆分。
在实际场景中，我们将系统拆分为5个核心微服务，通过Nacos实现服务发现和配置管理，通过Gateway实现统一入口和认证，通过OpenFeign实现服务间调用。理解了微服务架构的每个组件，排查服务注册、配置加载、服务调用等问题时效率大幅提升。
Nacos配置中心详解配置文件结构Nacos配置中心:├── mine-device.yaml           # 设备服务专属配置├── mine-alert.yaml            # 预警服务专属配置├── mine-location.yaml         # 定位服务专属配置├── common.yaml                # 公共配置(共享)│   ├── spring.datasource.*    # 数据源配置│   ├── spring.redis.*         # Redis配置│   └── mine.common.*          # 业务公共配置└── mqtt.yaml                  # MQTT公共配置

配置动态刷新/** * 设备阈值配置 - 支持动态刷新 */@Component@RefreshScope  // 支持Nacos配置动态刷新@Slf4jpublic class DeviceThresholdConfig &#123;    @Value(&quot;$&#123;mine.threshold.gas:1.0&#125;&quot;)    private Double gasThreshold;    @Value(&quot;$&#123;mine.threshold.temperature:35.0&#125;&quot;)    private Double temperatureThreshold;    @Value(&quot;$&#123;mine.threshold.pressure:1000.0&#125;&quot;)    private Double pressureThreshold;    public Double getGasThreshold() &#123;        return gasThreshold;    &#125;    /**     * 配置变更时自动刷新     */    @EventListener(RefreshScopeRefreshedEvent.class)    public void onRefresh() &#123;        log.info(&quot;[智慧矿山] 设备阈值配置已刷新: gas=&#123;&#125;&quot;, gasThreshold);    &#125;&#125;

Nacos命名空间隔离# dev环境spring:  cloud:    nacos:      discovery:        server-addr: nacos.mine-cloud.com:8848        namespace: dev# prod环境spring:  cloud:    nacos:      discovery:        server-addr: nacos.mine-cloud.com:8848        namespace: prod

Feign高级配置Feign拦截器：传递Token@Componentpublic class FeignRequestInterceptor implements RequestInterceptor &#123;    @Override    public void apply(RequestTemplate template) &#123;        // 从当前请求上下文获取Token        ServletRequestAttributes attributes =            (ServletRequestAttributes) RequestContextHolder.getRequestAttributes();        if (attributes != null) &#123;            HttpServletRequest request = attributes.getRequest();            String token = request.getHeader(&quot;Authorization&quot;);            if (token != null) &#123;                template.header(&quot;Authorization&quot;, token);            &#125;            String userId = request.getHeader(&quot;X-User-Id&quot;);            if (userId != null) &#123;                template.header(&quot;X-User-Id&quot;, userId);            &#125;            String mineCode = request.getHeader(&quot;X-Mine-Code&quot;);            if (mineCode != null) &#123;                template.header(&quot;X-Mine-Code&quot;, mineCode);            &#125;        &#125;    &#125;&#125;

Feign超时配置# application.ymlfeign:  client:    config:      default:        connect-timeout: 5000        read-timeout: 10000      mine-alert:  # 针对特定服务        connect-timeout: 3000        read-timeout: 30000  # 预警服务可能耗时较长

