微服务链路追踪/** * 网关过滤器：添加TraceId */@Component@Slf4jpublic class TraceFilter implements GlobalFilter, Ordered &#123;    @Override    public Mono&lt;Void&gt; filter(ServerWebExchange exchange, GatewayFilterChain chain) &#123;        String traceId = UUID.randomUUID().toString().replace(&quot;-&quot;, &quot;&quot;);        ServerHttpRequest request = exchange.getRequest().mutate()            .header(&quot;X-Trace-Id&quot;, traceId)            .build();        log.info(&quot;[网关] TraceId=&#123;&#125;&quot;, traceId);        return chain.filter(exchange.mutate().request(request).build());    &#125;    @Override    public int getOrder() &#123;        return -2;    &#125;&#125;

