自定义监控指标// 设备在线率指标@Componentpublic class DeviceMetrics &#123;    private final AtomicLong onlineDevices = new AtomicLong(0);    private final AtomicLong offlineDevices = new AtomicLong(0);    private final AtomicLong alertCount = new AtomicLong(0);    @Autowired    public DeviceMetrics(MeterRegistry registry) &#123;        // 设备在线数        Gauge.builder(&quot;mine.device.online&quot;, onlineDevices, AtomicLong::get)            .description(&quot;当前在线设备数量&quot;)            .register(registry);        // 设备离线数        Gauge.builder(&quot;mine.device.offline&quot;, offlineDevices, AtomicLong::get)            .description(&quot;当前离线设备数量&quot;)            .register(registry);        // 告警计数        Counter alertCounter = Counter.builder(&quot;mine.alert.count&quot;)            .description(&quot;告警总次数&quot;)            .tag(&quot;type&quot;, &quot;gas&quot;)            .register(registry);    &#125;    public void deviceOnline() &#123; onlineDevices.incrementAndGet(); offlineDevices.decrementAndGet(); &#125;    public void deviceOffline() &#123; offlineDevices.incrementAndGet(); onlineDevices.decrementAndGet(); &#125;    public void newAlert() &#123; alertCount.incrementAndGet(); &#125;&#125;

