实际项目基于SpringCloud + Nacos构建微服务架构，通过Sentinel保障服务稳定性，Gateway统一入口管理，Feign简化服务调用。在实际项目中，需要重点关注服务雪崩防护、分布式事务、链路追踪等核心问题，建立完善的监控与告警体系。

前言Spring事务是Java开发必须掌握的核心知识，但只背失效场景不够，面试官追问事务传播机制原理、AOP代理创建流程就会露馅。这篇文章从@Transactional源码到事务传播机制原理，从只读事务优化到多数据源事务，结合实际项目实战经验，全面深入分析Spring事务核心原理。

一、事务代理创建全流程1.1 @Transactional注解解析Spring容器启动时，@Transactional注解被SpringTransactionAnnotationParser解析为TransactionAttribute对象，最终注册到TransactionAttributeSource中。
// SpringTransactionAnnotationParser.javapublic class SpringTransactionAnnotationParser implements TransactionAnnotationParser &#123;    @Override    @Nullable    public TransactionAttribute parseTransactionAnnotation(AnnotatedElement element) &#123;        AnnotationAttributes attributes = AnnotatedElementUtils.findMergedAnnotationAttributes(                element, Transactional.class, false, false);        if (attributes != null) &#123;            return parseTransactionAnnotation(attributes);        &#125;        return null;    &#125;    protected TransactionAttribute parseTransactionAnnotation(AnnotationAttributes attributes) &#123;        RuleBasedTransactionAttribute rbta = new RuleBasedTransactionAttribute();        Propagation propagation = (Propagation) attributes.get(&quot;propagation&quot;);        rbta.setPropagationBehavior(propagation.value());        Isolation isolation = (Isolation) attributes.get(&quot;isolation&quot;);        rbta.setIsolationLevel(isolation.value());        rbta.setTimeout(Duration.parse((String) attributes.get(&quot;timeout&quot;)));        rbta.setReadOnly(attributes.getBoolean(&quot;readOnly&quot;));        List&lt;RollbackRuleAttribute&gt; rollbackRules = new ArrayList&lt;&gt;();        for (Class&lt;?&gt; rbRule : attributes.getClassArray(&quot;rollbackFor&quot;)) &#123;            rollbackRules.add(new RollbackRuleAttribute(rbRule));        &#125;        for (Class&lt;?&gt; rbRule : attributes.getClassArray(&quot;noRollbackFor&quot;)) &#123;            rollbackRules.add(new NoRollbackRuleAttribute(rbRule));        &#125;        rbta.setRollbackRules(rollbackRules);        return rbta;    &#125;&#125;

1.2 AOP代理创建流程Spring通过InfrastructureAdvisorAutoProxyCreator（实现了SmartInstantiationAwareBeanPostProcessor）在Bean创建后为其创建代理对象。核心流程如下：
// AbstractAutoProxyCreator.javapublic abstract class AbstractAutoProxyCreator extends ProxyProcessorSupport        implements SmartInstantiationAwareBeanPostProcessor, BeanFactoryAware &#123;    @Override    public Object postProcessAfterInitialization(Object bean, String beanName) &#123;        if (bean != null) &#123;            Object cacheKey = getCacheKey(bean.getClass(), beanName);            if (this.earlyProxyReferences.remove(cacheKey) != bean) &#123;                return wrapIfNecessary(bean, beanName, cacheKey);            &#125;        &#125;        return bean;    &#125;    protected Object wrapIfNecessary(Object bean, String beanName, Object cacheKey) &#123;        Object[] specificInterceptors = getAdvicesAndAdvisorsForBean(                bean.getClass(), beanName, null);        if (specificInterceptors != DO_NOT_PROXY) &#123;            Object proxy = createProxy(bean.getClass(), beanName,                    specificInterceptors, new SingletonTargetSource(bean));            return proxy;        &#125;        return bean;    &#125;&#125;

匹配过程：TransactionAttributeSourceAdvisor中的Pointcut会检查当前Bean的方法上是否存在@Transactional注解，如果存在则创建代理。
// TransactionAttributeSourceAdvisor.javapublic class TransactionAttributeSourceAdvisor extends AbstractPointcutAdvisor &#123;    private final TransactionAttributeSource transactionAttributeSource;    private final TransactionInterceptor transactionInterceptor;    private final TransactionAttributeSourcePointcut pointcut =            new TransactionAttributeSourcePointcut() &#123;                @Override                @Nullable                protected TransactionAttributeSource getTransactionAttributeSource() &#123;                    return transactionAttributeSource;                &#125;            &#125;;&#125;

实际项目示例：在智慧矿山系统中，DeviceDataService标注了@Transactional，Spring容器启动时检测到该注解，会为其创建CGLIB代理（因为DeviceDataService未实现接口），代理对象在方法调用时织入事务逻辑。
1.3 TransactionInterceptor完整调用链TransactionInterceptor是事务的核心拦截器，它实现了MethodInterceptor接口。当代理对象的方法被调用时，请求首先进入invoke()方法。
// TransactionInterceptor.javapublic class TransactionInterceptor extends TransactionAspectSupport        implements MethodInterceptor, Serializable &#123;    @Override    @Nullable    public Object invoke(MethodInvocation invocation) throws Throwable &#123;        Class&lt;?&gt; targetClass = (invocation.getThis() != null ?                AopUtils.getTargetClass(invocation.getThis()) : null);        return invokeWithinTransaction(invocation.getMethod(), targetClass,                invocation::proceed);    &#125;&#125;

// TransactionAspectSupport.java（核心逻辑）public abstract class TransactionAspectSupport &#123;    @Nullable    protected Object invokeWithinTransaction(Method method, @Nullable Class&lt;?&gt; targetClass,            InvocationCallback invocation) throws Throwable &#123;        // 1. 获取事务属性        TransactionAttributeSource tas = getTransactionAttributeSource();        TransactionAttribute txAttr = (tas != null ?                tas.getTransactionAttribute(method, targetClass) : null);        // 2. 确定TransactionManager        PlatformTransactionManager transactionManager = determineTransactionManager(txAttr);        // 3. 准备方法标识        String joinpointIdentification = methodIdentification(method, targetClass, txAttr);        // 4. 根据传播行为创建/获取事务        TransactionInfo txInfo = null;        if (txAttr == null || !(transactionManager instanceof CallbackPreferringPlatformTransactionManager)) &#123;            txInfo = createTransactionIfNecessary(transactionManager, txAttr, joinpointIdentification);        &#125;        Object retVal;        try &#123;            // 5. 执行目标方法            retVal = invocation.proceedWithInvocation();        &#125; catch (Throwable ex) &#123;            // 6. 异常处理            completeTransactionAfterThrowing(txInfo, ex);            throw ex;        &#125; finally &#123;            // 7. 清理事务上下文            cleanupTransactionInfo(txInfo);        &#125;        // 8. 提交事务        commitTransactionAfterReturning(txInfo);        return retVal;    &#125;    protected TransactionInfo createTransactionIfNecessary(            PlatformTransactionManager tm, @Nullable TransactionAttribute txAttr,            final String joinpointIdentification) &#123;        if (txAttr != null &amp;&amp; txAttr.getName() == null) &#123;            txAttr = new DelegatingTransactionAttribute(txAttr) &#123;                @Override                public String getName() &#123;                    return joinpointIdentification;                &#125;            &#125;;        &#125;        TransactionStatus status = null;        if (txAttr != null) &#123;            status = tm.getTransaction(txAttr);        &#125;        return prepareTransactionInfo(tm, txAttr, joinpointIdentification, status);    &#125;&#125;

完整调用链图：
代理对象.methodXxx()    |    vCglibAopProxy.intercept() / JdkDynamicAopProxy.invoke()    |    vReflectiveMethodInvocation.proceed()  --&gt;  遍历拦截器链    |    vTransactionInterceptor.invoke()    |    vTransactionAspectSupport.invokeWithinTransaction()    |    +--1. getTransactionAttribute()         获取@Transactional属性    +--2. determineTransactionManager()      确定事务管理器    +--3. createTransactionIfNecessary()     创建/获取事务    |       |    |       v    |   AbstractPlatformTransactionManager.getTransaction()    |       |    |       +-- handleExistingTransaction()     处理已存在事务（传播行为核心逻辑）    |       +-- startTransaction()              新建事务    |               |    |               +-- suspend()               挂起当前事务（REQUIRES_NEW等）    |               +-- doBegin()               底层开启事务（获取Connection、设置隔离级别等）    |               +-- 绑定到TransactionSynchronizationManager（ThreadLocal）    |    +--4. invocation.proceedWithInvocation()  执行目标方法    |    +--5a. completeTransactionAfterThrowing()  异常 -&gt; 回滚    |       |    |       v    |   AbstractPlatformTransactionManager.processRollback()    |       +-- triggerBeforeCompletion()    |       +-- doRollback()                    底层执行rollback    |       +-- triggerAfterCompletion()    |       +-- cleanupAfterCompletion()        清理资源、恢复挂起事务    |    +--5b. commitTransactionAfterReturning()   正常 -&gt; 提交    |       |    |       v    |   AbstractPlatformTransactionManager.commit()    |       +-- triggerBeforeCommit()    |       +-- triggerBeforeCompletion()    |       +-- doCommit()                      底层执行commit    |       +-- triggerAfterCommit()    |       +-- cleanupAfterCompletion()        清理资源、恢复挂起事务    |    +--6. cleanupTransactionInfo()             恢复ThreadLocal中的旧事务信息


二、PlatformTransactionManager体系2.1 类层次结构Spring通过PlatformTransactionManager接口抽象事务管理，不同的数据访问技术对应不同的实现。
PlatformTransactionManager (接口)    |    +-- AbstractPlatformTransactionManager (抽象基类，实现事务传播行为模板)    |       |    |       +-- DataSourceTransactionManager      JDBC / MyBatis    |       +-- JpaTransactionManager             JPA / Hibernate    |       +-- HibernateTransactionManager       Hibernate（已废弃，推荐JpaTransactionManager）    |       +-- JtaTransactionManager             JTA分布式事务    |       +-- WebLogicJtaTransactionManager     WebLogic JTA    |       +-- WebSphereUowTransactionManager    WebSphere UOW    |    +-- CallbackPreferringPlatformTransactionManager (函数式事务管理)            +-- WebSphereUowTransactionManager

2.2 DataSourceTransactionManager详解DataSourceTransactionManager是最常用的事务管理器，适用于JDBC和MyBatis。
public class DataSourceTransactionManager extends AbstractPlatformTransactionManager        implements ResourceTransactionManager, InitializingBean &#123;    private DataSource dataSource;    @Override    protected Object doGetTransaction() &#123;        DataSourceTransactionObject txObject = new DataSourceTransactionObject();        ConnectionHolder conHolder = (ConnectionHolder) TransactionSynchronizationManager                .getResource(obtainDataSource());        txObject.setConnectionHolder(conHolder, false);        return txObject;    &#125;    @Override    protected void doBegin(Object transaction, TransactionDefinition definition) &#123;        DataSourceTransactionObject txObject = (DataSourceTransactionObject) transaction;        Connection con = null;        try &#123;            if (!txObject.hasConnectionHolder() ||                    txObject.getConnectionHolder().isSynchronizedWithTransaction()) &#123;                Connection newCon = obtainDataSource().getConnection();                txObject.setConnectionHolder(new ConnectionHolder(newCon), true);            &#125;            txObject.getConnectionHolder().setSynchronizedWithTransaction(true);            con = txObject.getConnectionHolder().getConnection();            Integer previousIsolationLevel = DataSourceUtils.prepareConnectionForTransaction(con, definition);            txObject.setPreviousIsolationLevel(previousIsolationLevel);            if (con.getAutoCommit()) &#123;                txObject.setMustRestoreAutoCommit(true);                con.setAutoCommit(false);  // 关键：关闭自动提交            &#125;            TransactionSynchronizationManager.bindResource(obtainDataSource(),                    txObject.getConnectionHolder());        &#125; catch (Throwable ex) &#123;            // 异常处理...        &#125;    &#125;    @Override    protected void doCommit(DefaultTransactionStatus status) &#123;        DataSourceTransactionObject txObject = (DataSourceTransactionObject) status.getTransaction();        Connection con = txObject.getConnectionHolder().getConnection();        con.commit();    &#125;    @Override    protected void doRollback(DefaultTransactionStatus status) &#123;        Connection con = txObject.getConnectionHolder().getConnection();        con.rollback();    &#125;&#125;

实际项目配置：
@Configurationpublic class DataSourceConfig &#123;    @Bean    @ConfigurationProperties(prefix = &quot;spring.datasource.hikari&quot;)    public DataSource dataSource() &#123;        return DataSourceBuilder.create().type(HikariDataSource.class).build();    &#125;    @Bean    public PlatformTransactionManager transactionManager(DataSource dataSource) &#123;        return new DataSourceTransactionManager(dataSource);    &#125;&#125;

2.3 JpaTransactionManager详解JpaTransactionManager同时支持JPA和JDBC，在实际项目中使用JPA操作设备实体时需要此管理器。
public class JpaTransactionManager extends AbstractPlatformTransactionManager        implements ResourceTransactionManager, InitializingBean &#123;    private EntityManagerFactory entityManagerFactory;    @Override    protected Object doGetTransaction() &#123;        JpaTransactionObject txObject = new JpaTransactionObject();        EntityManagerHolder emHolder = (EntityManagerHolder) TransactionSynchronizationManager                .getResource(this.entityManagerFactory);        txObject.setEntityManagerHolder(emHolder, false);        ConnectionHolder conHolder = (ConnectionHolder) TransactionSynchronizationManager                .getResource(obtainDataSource());        txObject.setConnectionHolder(conHolder, false);        return txObject;    &#125;    @Override    protected void doBegin(Object transaction, TransactionDefinition definition) &#123;        // 1. 创建或获取EntityManager        // 2. 开启JPA事务（entityTransaction.begin()）        // 3. 如果需要，同时开启JDBC事务        // 4. 将EntityManager绑定到ThreadLocal    &#125;&#125;

2.4 JtaTransactionManagerJtaTransactionManager委托给J2EE容器的JTA实现，用于分布式事务。
public class JtaTransactionManager extends AbstractPlatformTransactionManager        implements TransactionFactory, Serializable &#123;    private transient UserTransaction userTransaction;    private transient TransactionManager transactionManager;    @Override    protected void doBegin(Object transaction, TransactionDefinition definition) &#123;        this.userTransaction.begin();    &#125;&#125;


