3.1 rollbackFor深入分析Spring默认回滚规则基于DefaultTransactionAttribute：
// RuleBasedTransactionAttribute.javapublic class RuleBasedTransactionAttribute extends DefaultTransactionAttribute &#123;    @Override    public boolean rollbackOn(Throwable ex) &#123;        RollbackRuleAttribute winner = null;        int deepest = Integer.MAX_VALUE;        for (RollbackRuleAttribute rule : this.rollbackRules) &#123;            int depth = rule.getDepth(ex.getClass());            if (depth &gt;= 0 &amp;&amp; depth &lt; deepest) &#123;                deepest = depth;                winner = rule;            &#125;        &#125;        if (winner == null) &#123;            return super.rollbackOn(ex);        &#125;        return !(winner instanceof NoRollbackRuleAttribute);    &#125;&#125;// DefaultTransactionAttribute.javapublic boolean rollbackOn(Throwable ex) &#123;    return (ex instanceof RuntimeException || ex instanceof Error);&#125;

实际项目案例：
// 错误：IOException是checked异常，默认不回滚@Transactionalpublic void exportDeviceData(String path) throws IOException &#123;    deviceMapper.updateExportStatus(deviceId, &quot;EXPORTING&quot;);  // 已执行    Files.writeString(Path.of(path), data);                   // IOException    // 数据库不会回滚！exportStatus停留在EXPORTING&#125;// 正确：指定rollbackFor@Transactional(rollbackFor = Exception.class)public void exportDeviceData(String path) throws IOException &#123;    deviceMapper.updateExportStatus(deviceId, &quot;EXPORTING&quot;);    Files.writeString(Path.of(path), data);    // IOException触发回滚，exportStatus恢复&#125;

3.2 timeout机制@Overrideprotected void doBegin(Object transaction, TransactionDefinition definition) &#123;    if (timeout != TransactionDefinition.TIMEOUT_DEFAULT) &#123;        txObject.getConnectionHolder().setTimeoutInSeconds(timeout);    &#125;&#125;

注意：Spring的timeout只是设置了一个deadline时间戳，每次执行SQL前并不主动检查。真正触发超时回滚的是MySQL的innodb_lock_wait_timeout（默认50秒），当事务持有锁超过该时间，MySQL会主动断开，Spring捕获异常后回滚。

四、事务传播机制深度分析4.1 七种传播行为概览public enum Propagation &#123;    REQUIRED,       // 0: 支持当前事务，不存在则新建    SUPPORTS,       // 1: 支持当前事务，不存在则以非事务方式执行    MANDATORY,      // 2: 必须在事务中执行，不存在则抛异常    REQUIRES_NEW,   // 3: 新建事务，挂起当前事务    NOT_SUPPORTED,  // 4: 以非事务方式执行，挂起当前事务    NEVER,          // 5: 以非事务方式执行，存在事务则抛异常    NESTED          // 6: 嵌套事务，不存在则新建&#125;

传播行为状态图：
当前存在事务？

| 是                               | 否
+———-v———-+          +———–v—————+
加入当前事务         |          |  行为取决于传播类型
+———————+          +—————————+
传播行为          | 存在事务时            | 不存在事务时           | 智慧矿山场景
REQUIRED         | 加入当前事务          | 新建事务               | 设备数据采集+告警判断
SUPPORTS         | 加入当前事务          | 非事务执行             | 查询设备列表
MANDATORY        | 加入当前事务          | 抛IllegalTransaction   | 必须由事务方法调用
REQUIRES_NEW     | 挂起当前事务,新建事务  | 新建事务               | 操作日志记录
NOT_SUPPORTED    | 挂起当前事务,非事务执行 | 非事务执行             | 非关键通知发送
NEVER            | 抛IllegalTransaction  | 非事务执行             | 禁止事务的操作
NESTED           | 创建Savepoint嵌套     | 新建事务               | 批量设备注册部分失败

4.2 REQUIRED – 默认传播行为// AbstractPlatformTransactionManager.javaprivate TransactionStatus handleExistingTransaction(TransactionDefinition definition,        Object transaction, boolean debugEnabled) throws TransactionException &#123;    if (definition.getPropagationBehavior() == TransactionDefinition.PROPAGATION_REQUIRED) &#123;        return joinTransaction(definition, transaction, debugEnabled);    &#125;&#125;private TransactionStatus joinTransaction(TransactionDefinition definition,        Object transaction, boolean debugEnabled) &#123;    DefaultTransactionStatus status = prepareTransactionStatus(            definition, transaction, false, debugEnabled, null, true);    return status;&#125;

实际项目示例：
@Servicepublic class DeviceAlarmService &#123;    @Autowired    private AlarmRuleService alarmRuleService;    @Transactional(propagation = Propagation.REQUIRED)    public void processDeviceData(DeviceDataDTO data) &#123;        // 操作1: 保存设备原始数据        deviceDataMapper.insert(data);        // 操作2: 判断告警规则（加入当前事务）        alarmRuleService.evaluateRules(data);        // 操作3: 更新设备最后上报时间        deviceMapper.updateLastReportTime(data.getDeviceId(), LocalDateTime.now());    &#125;&#125;@Servicepublic class AlarmRuleService &#123;    @Transactional(propagation = Propagation.REQUIRED)    public void evaluateRules(DeviceDataDTO data) &#123;        List&lt;AlarmRule&gt; rules = alarmRuleMapper.selectByDeviceType(data.getDeviceType());        for (AlarmRule rule : rules) &#123;            if (rule.isTriggered(data)) &#123;                alarmRecordMapper.insert(buildAlarmRecord(data, rule));            &#125;        &#125;    &#125;&#125;

4.3 REQUIRES_NEW – 独立事务// handleExistingTransaction中处理REQUIRES_NEWif (definition.getPropagationBehavior() == TransactionDefinition.PROPAGATION_REQUIRES_NEW) &#123;    SuspendedResourcesHolder suspendedResources = suspend(transaction);    try &#123;        return startTransaction(definition, transaction, debugEnabled, suspendedResources);    &#125; catch (RuntimeException | Error ex) &#123;        resume(transaction, suspendedResources);        throw ex;    &#125;&#125;// suspend()方法 -- 挂起事务protected final SuspendedResourcesHolder suspend(@Nullable Object transaction) throws TransactionException &#123;    List&lt;TransactionSynchronization&gt; suspendedSynchronizations = doSuspendSynchronization();    Object suspendedResources = null;    if (transaction != null) &#123;        suspendedResources = doSuspend(transaction);    &#125;    String name = TransactionSynchronizationManager.getCurrentTransactionName();    TransactionSynchronizationManager.setCurrentTransactionName(null);    boolean readOnly = TransactionSynchronizationManager.isCurrentTransactionReadOnly();    Integer isolationLevel = TransactionSynchronizationManager.getCurrentTransactionIsolationLevel();    boolean wasActive = TransactionSynchronizationManager.isActualTransactionActive();    return new SuspendedResourcesHolder(suspendedResources, suspendedSynchronizations,            name, readOnly, isolationLevel, wasActive);&#125;

实际项目示例：
@Servicepublic class DeviceAlarmService &#123;    @Autowired    private OperationLogService operationLogService;    @Transactional(propagation = Propagation.REQUIRED)    public void handleAlarm(AlarmRecord record) &#123;        try &#123;            alarmRecordMapper.updateStatus(record.getId(), &quot;PROCESSING&quot;);            notificationService.sendAlarmNotification(record);            operationLogService.logOperation(record, &quot;ALARM_HANDLED&quot;);        &#125; catch (Exception e) &#123;            operationLogService.logOperation(record, &quot;ALARM_FAILED&quot;);            throw e;        &#125;    &#125;&#125;@Servicepublic class OperationLogService &#123;    @Transactional(propagation = Propagation.REQUIRES_NEW)    public void logOperation(AlarmRecord record, String action) &#123;        OperationLog log = new OperationLog();        log.setDeviceId(record.getDeviceId());        log.setAction(action);        log.setTimestamp(LocalDateTime.now());        operationLogMapper.insert(log);    &#125;&#125;

4.4 NESTED – 嵌套事务与Savepoint机制// handleExistingTransaction中处理NESTEDif (definition.getPropagationBehavior() == TransactionDefinition.PROPAGATION_NESTED) &#123;    if (!isNestedTransactionAllowed()) &#123;        throw new NestedTransactionNotSupportedException(                &quot;Transaction manager does not support nested transactions&quot;);    &#125;    if (useSavepointForNestedTransaction()) &#123;        DefaultTransactionStatus status = prepareTransactionStatus(                definition, transaction, false, debugEnabled, null, true);        status.createAndHoldSavepoint();        return status;    &#125;&#125;// AbstractTransactionStatus.javapublic void createAndHoldSavepoint() throws TransactionException &#123;    Object savepoint = getSavepointManager().createSavepoint();    this.savepoint = savepoint;&#125;// JDBC底层实现// Connection.setSavepoint(&quot;SAVEPOINT_1&quot;)// 内层回滚 -&gt; Connection.rollback(savepoint)// 内层提交 -&gt; Connection.releaseSavepoint(savepoint)

Savepoint机制示意图：
外层事务 BEGIN    |    +-- INSERT INTO device (name, type) VALUES (&#x27;传感器A&#x27;, &#x27;TEMP&#x27;)    |    +-- SAVEPOINT_1 &lt;- 内层事务创建Savepoint    |       |    |       +-- INSERT INTO alarm_record (device_id, level) VALUES (1001, &#x27;HIGH&#x27;)    |       |    |       +-- ROLLBACK TO SAVEPOINT_1 &lt;- 内层异常，回滚到Savepoint    |       |   （内层INSERT被撤销，外层INSERT不受影响）    |       |    |       +-- RELEASE SAVEPOINT_1    |    +-- UPDATE device SET status = &#x27;ACTIVE&#x27; WHERE id = 1001    |    +-- COMMIT &lt;- 外层事务提交

实际项目示例：
@Servicepublic class BatchDeviceService &#123;    @Transactional(propagation = Propagation.REQUIRED)    public BatchResult batchRegisterDevices(List&lt;DeviceRegisterDTO&gt; devices) &#123;        BatchResult result = new BatchResult();        for (DeviceRegisterDTO dto : devices) &#123;            try &#123;                deviceService.registerSingleDevice(dto);                result.addSuccess(dto.getSn());            &#125; catch (Exception e) &#123;                result.addFailed(dto.getSn(), e.getMessage());            &#125;        &#125;        return result;    &#125;&#125;@Servicepublic class DeviceService &#123;    @Transactional(propagation = Propagation.NESTED)    public void registerSingleDevice(DeviceRegisterDTO dto) &#123;        if (deviceMapper.selectBySn(dto.getSn()) != null) &#123;            throw new BusinessException(&quot;设备SN已存在: &quot; + dto.getSn());        &#125;        Device device = new Device();        device.setSn(dto.getSn());        device.setType(dto.getType());        deviceMapper.insert(device);        deviceConfigService.initDefaultConfig(device.getId());    &#125;&#125;

4.5 SUPPORTS &#x2F; MANDATORY &#x2F; NOT_SUPPORTED &#x2F; NEVER// SUPPORTS：有事务就加入，没有就非事务执行@Servicepublic class DeviceQueryService &#123;    @Transactional(propagation = Propagation.SUPPORTS)    public List&lt;Device&gt; listDevices(Long mineAreaId) &#123;        return deviceMapper.selectByMineAreaId(mineAreaId);    &#125;&#125;// MANDATORY：必须由事务方法调用@Servicepublic class DeviceDataWriteService &#123;    @Transactional(propagation = Propagation.MANDATORY)    public void writeDeviceData(DeviceDataDTO data) &#123;        deviceDataMapper.insert(data);    &#125;&#125;// NOT_SUPPORTED：挂起事务，非事务执行@Servicepublic class NotificationService &#123;    @Transactional(propagation = Propagation.NOT_SUPPORTED)    public void sendAlarmNotification(AlarmRecord record) &#123;        smsClient.send(record.getContactPhone(), record.getMessage());        emailClient.send(record.getContactEmail(), record.getDetail());    &#125;&#125;// NEVER：存在事务则抛异常@Servicepublic class SystemMonitorService &#123;    @Transactional(propagation = Propagation.NEVER)    public SystemStatus checkSystemStatus() &#123;        return SystemStatus.builder()                .dbAlive(checkDatabase())                .redisAlive(checkRedis())                .kafkaAlive(checkKafka())                .build();    &#125;&#125;


五、隔离级别与MySQL InnoDB实现5.1 四种隔离级别


隔离级别
脏读
不可重复读
幻读
说明



READ_UNCOMMITTED
可能
可能
可能
最低隔离级别，可读到未提交数据


READ_COMMITTED
不会
可能
