实际项目实践：我们选择自注入方案，代码侵入性低、可读性好，且项目已使用@Lazy解决其他循环依赖问题。

八、@TransactionalEventListener与事务同步8.1 @EventListener的问题@Servicepublic class DeviceService &#123;    @Autowired    private ApplicationEventPublisher eventPublisher;    @Transactional(rollbackFor = Exception.class)    public void registerDevice(DeviceRegisterDTO dto) &#123;        Device device = buildDevice(dto);        deviceMapper.insert(device);        // 问题：事务可能未提交，监听器读不到数据        eventPublisher.publishEvent(new DeviceCreatedEvent(device.getId()));    &#125;&#125;@Componentpublic class DeviceEventListener &#123;    @EventListener    public void onDeviceCreated(DeviceCreatedEvent event) &#123;        // 问题1：此时事务可能未提交，其他事务读不到设备数据        // 问题2：如果这里抛异常，会传播到发布者，导致事务回滚        // 问题3：如果事务最终回滚，但事件已经被处理了        Device device = deviceMapper.selectById(event.getDeviceId());        notificationService.sendWelcome(device.getContactEmail());    &#125;&#125;

8.2 @TransactionalEventListener解决方案@Componentpublic class DeviceTransactionEventListener &#123;    /**     * @TransactionalEventListener 在事务的特定阶段触发     * phase选项：     *   AFTER_COMMIT     -&gt; 事务提交后（最常用）     *   AFTER_COMPLETION -&gt; 事务完成后（提交或回滚）     *   BEFORE_COMMIT    -&gt; 事务提交前     *   AFTER_ROLLBACK   -&gt; 事务回滚后     */    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)    public void onDeviceCreatedAfterCommit(DeviceCreatedEvent event) &#123;        Device device = deviceMapper.selectById(event.getDeviceId());        notificationService.sendWelcome(device.getContactEmail());    &#125;    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)    public void initDataSync(DeviceCreatedEvent event) &#123;        edgeGatewayService.syncDevice(event.getDeviceId());    &#125;    @TransactionalEventListener(phase = TransactionPhase.AFTER_ROLLBACK)    public void onDeviceCreateRollback(DeviceCreatedEvent event) &#123;        cacheService.evictDeviceCache(event.getDeviceId());        log.warn(&quot;设备创建失败，已清理缓存: deviceId=&#123;&#125;&quot;, event.getDeviceId());    &#125;&#125;

8.3 实现原理// ApplicationListenerMethodTransactionalAdapter.javapublic class ApplicationListenerMethodTransactionalAdapter extends ApplicationListenerMethodAdapter &#123;    private final TransactionPhase transactionPhase;    @Override    public void onApplicationEvent(ApplicationEvent event) &#123;        if (TransactionSynchronizationManager.isSynchronizationActive()) &#123;            TransactionSynchronization synchronization =                    new TransactionSynchronizationEventAdapter(this, event);            TransactionSynchronizationManager.registerSynchronization(synchronization);        &#125; else if (this.transactionPhase == TransactionPhase.AFTER_COMMIT) &#123;            processEvent(event);        &#125;    &#125;&#125;// TransactionSynchronizationEventAdapter.javaclass TransactionSynchronizationEventAdapter implements TransactionSynchronization &#123;    @Override    public void beforeCommit(boolean readOnly) &#123;        if (this.phase == TransactionPhase.BEFORE_COMMIT) &#123;            processEvent();        &#125;    &#125;    @Override    public void afterCommit() &#123;        if (this.phase == TransactionPhase.AFTER_COMMIT) &#123;            processEvent();        &#125;    &#125;    @Override    public void afterCompletion(int status) &#123;        if (this.phase == TransactionPhase.AFTER_COMPLETION) &#123;            processEvent();        &#125; else if (this.phase == TransactionPhase.AFTER_ROLLBACK &amp;&amp;                status == TransactionSynchronization.STATUS_ROLLED_BACK) &#123;            processEvent();        &#125;    &#125;&#125;

8.4 @EventListener vs @TransactionalEventListener对比


维度
@EventListener
@TransactionalEventListener



触发时机
事件发布后立即执行
事务特定阶段（默认AFTER_COMMIT）


事务上下文
在发布者事务中执行
在事务同步回调中执行


事务回滚影响
事件已处理，回滚无法撤销
AFTER_COMMIT保证事务已提交


异常传播
异常传播到发布者
AFTER_COMMIT异常不影响原事务


无事务场景
正常执行
默认不执行（可设置fallbackExecution）


适用场景
同步处理、事务内操作
事务提交后异步操作、通知发送



九、声明式事务 vs 编程式事务9.1 声明式事务@Servicepublic class DeviceService &#123;    @Transactional(rollbackFor = Exception.class)    public void registerDevice(DeviceRegisterDTO dto) &#123;        deviceMapper.insert(buildDevice(dto));        deviceConfigService.initDefaultConfig(dto.getDeviceId());    &#125;&#125;

9.2 编程式事务// 方式一：TransactionTemplate（推荐）@Servicepublic class DeviceService &#123;    @Autowired    private TransactionTemplate transactionTemplate;    public void registerDevice(DeviceRegisterDTO dto) &#123;        transactionTemplate.executeWithoutResult(status -&gt; &#123;            deviceMapper.insert(buildDevice(dto));            deviceConfigService.initDefaultConfig(dto.getDeviceId());        &#125;);    &#125;    public Device registerAndReturn(DeviceRegisterDTO dto) &#123;        return transactionTemplate.execute(status -&gt; &#123;            Device device = buildDevice(dto);            deviceMapper.insert(device);            deviceConfigService.initDefaultConfig(device.getId());            return device;        &#125;);    &#125;&#125;// 方式二：PlatformTransactionManager@Servicepublic class DeviceService &#123;    @Autowired    private PlatformTransactionManager transactionManager;    public void registerDevice(DeviceRegisterDTO dto) &#123;        DefaultTransactionDefinition def = new DefaultTransactionDefinition();        def.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRED);        def.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);        def.setTimeout(30);        TransactionStatus status = transactionManager.getTransaction(def);        try &#123;            deviceMapper.insert(buildDevice(dto));            deviceConfigService.initDefaultConfig(dto.getDeviceId());            transactionManager.commit(status);        &#125; catch (Exception e) &#123;            transactionManager.rollback(status);            throw e;        &#125;    &#125;&#125;

9.3 编程式事务的典型场景@Servicepublic class DataMigrationService &#123;    @Autowired    private TransactionTemplate transactionTemplate;    /**     * 智慧矿山场景：历史数据迁移，需要在循环中精确控制事务边界     */    public MigrationResult migrateHistoricalData(List&lt;HistoricalData&gt; dataList) &#123;        MigrationResult result = new MigrationResult();        int batchSize = 500;        for (int i = 0; i &lt; dataList.size(); i += batchSize) &#123;            List&lt;HistoricalData&gt; batch = dataList.subList(i,                    Math.min(i + batchSize, dataList.size()));            transactionTemplate.executeWithoutResult(status -&gt; &#123;                for (HistoricalData data : batch) &#123;                    try &#123;                        deviceDataMapper.insert(convertToEntity(data));                        result.incrementSuccess();                    &#125; catch (DuplicateKeyException e) &#123;                        result.incrementSkipped();                    &#125;                &#125;            &#125;);            log.info(&quot;已迁移 &#123;&#125;/&#123;&#125; 条数据&quot;, Math.min(i + batchSize, dataList.size()),                    dataList.size());        &#125;        return result;    &#125;&#125;

9.4 对比总结


维度
声明式事务
编程式事务



代码侵入
低（注解）
高（模板代码）


粒度控制
方法级
代码块级


可读性
好
一般


灵活性
有限
高（精确控制事务边界）


自调用
失效
不受影响


异常处理
自动回滚
手动rollback


适用场景
常规CRUD
批量处理、精确控制、局部事务


推荐度
默认推荐
特殊场景使用



十、多数据源事务10.1 问题场景智慧矿山系统中，设备数据量巨大，按照矿区维度分库，一个服务需要同时操作多个数据源。
@Configurationpublic class MultiDataSourceConfig &#123;    @Bean(&quot;mineAreaADs&quot;)    @ConfigurationProperties(prefix = &quot;spring.datasource.mine-area-a&quot;)    public DataSource mineAreaADataSource() &#123;        return DataSourceBuilder.create().type(HikariDataSource.class).build();    &#125;    @Bean(&quot;mineAreaBDs&quot;)    @ConfigurationProperties(prefix = &quot;spring.datasource.mine-area-b&quot;)    public DataSource mineAreaBDataSource() &#123;        return DataSourceBuilder.create().type(HikariDataSource.class).build();    &#125;    @Bean    @Primary    public DataSource dynamicDataSource(            @Qualifier(&quot;mineAreaADs&quot;) DataSource dsA,            @Qualifier(&quot;mineAreaBDs&quot;) DataSource dsB) &#123;        Map&lt;Object, Object&gt; targetDataSources = new HashMap&lt;&gt;();        targetDataSources.put(&quot;MINE_A&quot;, dsA);        targetDataSources.put(&quot;MINE_B&quot;, dsB);        DynamicRoutingDataSource routingDs = new DynamicRoutingDataSource();        routingDs.setDefaultTargetDataSource(dsA);        routingDs.setTargetDataSources(targetDataSources);        return routingDs;    &#125;    @Bean    public PlatformTransactionManager transactionManager(DataSource dynamicDataSource) &#123;        // 问题：只能管理一个DataSource的事务！        return new DataSourceTransactionManager(dynamicDataSource);    &#125;&#125;

问题：@Transactional只能绑定一个DataSource的Connection，在事务执行过程中切换数据源，第二个数据源的操作不在事务管控范围内。
10.2 方案一：JTA分布式事务// 使用Atomikos实现JTA事务管理@Configurationpublic class JtaDataSourceConfig &#123;    @Bean(&quot;mineAreaAXaDs&quot;)    public AtomikosDataSourceBean mineAreaADataSource() &#123;        AtomikosDataSourceBean ds = new AtomikosDataSourceBean();        ds.setXaDataSourceClassName(&quot;com.mysql.cj.jdbc.MysqlXADataSource&quot;);        ds.setXaProperties(xaProperties(&quot;mine_a_db&quot;));        ds.setUniqueResourceName(&quot;mineAreaA&quot;);        return ds;    &#125;    @Bean(&quot;mineAreaBXaDs&quot;)    public AtomikosDataSourceBean mineAreaBDataSource() &#123;        AtomikosDataSourceBean ds = new AtomikosDataSourceBean();        ds.setXaDataSourceClassName(&quot;com.mysql.cj.jdbc.MysqlXADataSource&quot;);        ds.setXaProperties(xaProperties(&quot;mine_b_db&quot;));        ds.setUniqueResourceName(&quot;mineAreaB&quot;);        return ds;    &#125;    @Bean    public JtaTransactionManager jtaTransactionManager(UserTransaction userTransaction,            TransactionManager transactionManager) &#123;        JtaTransactionManager jtaTm = new JtaTransactionManager();        jtaTm.setUserTransaction(userTransaction);        jtaTm.setTransactionManager(transactionManager);        return jtaTm;    &#125;&#125;@Servicepublic class CrossMineAreaService &#123;    @Transactional    public void transferDevice(Long deviceId, String fromArea, String toArea) &#123;        mineAreaADeviceMapper.deleteById(deviceId);        mineAreaBDeviceMapper.insert(device);        // JTA两阶段提交保证原子性    &#125;&#125;

JTA缺点：性能开销大（两阶段提交），需要XA数据源支持，数据库必须支持XA协议。
10.3 方案二：Seata AT模式// Seata AT模式：无侵入的分布式事务方案// 每个数据源添加undo_log表// CREATE TABLE undo_log (...);@Servicepublic class CrossMineAreaService &#123;    @GlobalTransactional(name = &quot;transfer-device&quot;, rollbackFor = Exception.class)    public void transferDevice(Long deviceId, String fromArea, String toArea) &#123;        mineAreaADeviceMapper.deleteById(deviceId);        mineAreaBDeviceMapper.insert(device);        // Seata自动管理两阶段提交        // 阶段一：业务SQL + 生成undo_log        // 阶段二：提交（异步删除undo_log）或回滚（根据undo_log反向补偿）    &#125;&#125;

10.4 方案三：自定义路由 + 本地事务@Target(&#123;ElementType.METHOD, ElementType.TYPE&#125;)@Retention(RetentionPolicy.RUNTIME)@DataSource(&quot;MINE_A&quot;)public @interface MineAreaA &#123;&#125;@Target(&#123;ElementType.METHOD, ElementType.TYPE&#125;)@Retention(RetentionPolicy.RUNTIME)@DataSource(&quot;MINE_B&quot;)public @interface MineAreaB &#123;&#125;@Servicepublic class DeviceService &#123;    @MineAreaA    @Transactional(rollbackFor = Exception.class)    public void operateOnMineA(Device device) &#123;        deviceMapper.insert(device);    &#125;    @MineAreaB    @Transactional(rollbackFor = Exception.class)    public void operateOnMineB(Device device) &#123;        deviceMapper.insert(device);    &#125;&#125;

10.5 三种方案对比


维度
JTA (Atomikos)
Seata AT
自定义路由



一致性
强一致性
最终一致性（AT模式近似强一致）
需自行保证


性能
低（两阶段提交）
中（一阶段+异步二阶段）
高（无额外开销）


侵入性
中（需XA数据源）
低（只需undo_log表）
高（需设计路由+补偿）


数据库要求
支持XA协议
无特殊要求
无特殊要求


运维复杂度
中
高（Seata Server）
低


适用场景
传统企业应用
微服务架构
单体应用分库


实际项目实践：由于是单体应用且按矿区分库，我们选择自定义路由方案。跨矿区操作通过消息队列+补偿机制保证最终一致性。

十一、事务最佳实践11.1 最佳实践总结


#
最佳实践
说明
示例



1
始终指定rollbackFor
避免checked异常不回滚
@Transactional(rollbackFor = Exception.class)


2
只读方法加readOnly
减少锁开销，优化查询性能
@Transactional(readOnly = true)


3
事务方法必须是public
非public方法代理不生效
public void save()


4
避免自调用
通过代理对象调用或使用编程式事务
self.save() 或 transactionTemplate.execute()


5
事务粒度最小化
只在必要的操作上开启事务
不在事务中做RPC调用、文件IO


6
避免长事务
长事务持有锁时间长，影响并发
拆分事务、异步处理非核心操作


7
选择合适的传播行为
默认REQUIRED即可，特殊场景用NESTED&#x2F;REQUIRES_NEW
日志记录用REQUIRES_NEW


8
catch异常后手动回滚
不要吞掉异常
TransactionAspectSupport.currentTransactionStatus().setRollbackOnly()


9
事务注解放实现类上
放接口上可能导致CGLIB代理失效
@Service public class DeviceServiceImpl


10
多数据源注意事务边界
一个@Transactional只能管一个数据源
使用Seata或自行补偿


11
避免事务中调用异步方法
异步操作不在事务上下文中
使用@TransactionalEventListener


12
事务超时设合理值
避免无限等待
@Transactional(timeout = 30)


11.2 实际项目事务规范/** * 实际项目事务使用规范 */// 1. 标准写法模板@Transactional(rollbackFor = Exception.class, timeout = 30)public void standardBusinessMethod() &#123;    // 业务逻辑&#125;// 2. 只读查询模板@Transactional(readOnly = true)public List&lt;Device&gt; queryDevices(Long mineAreaId) &#123;    return deviceMapper.selectByMineAreaId(mineAreaId);&#125;// 3. 需要独立事务的操作@Transactional(propagation = Propagation.REQUIRES_NEW, rollbackFor = Exception.class)public void independentOperation() &#123;    // 日志记录等&#125;// 4. 嵌套事务模板@Transactional(propagation = Propagation.NESTED, rollbackFor = Exception.class)public void partialFailureOperation() &#123;    // 允许部分失败的操作&#125;// 5. 跨服务操作 -- 不在事务中做RPC调用public void crossServiceOperation() &#123;    Device device = doInLocalTransaction();    remoteService.notifyDeviceCreated(device.getId());&#125;


十二、常见项目问题与解决方案以下是实际项目开发中遇到的事务问题汇总，涵盖面试高频考点和生产环境真实Bug。



#
问题
现象
原因
解决方案



1
自调用事务失效
同类方法内部调用@Transactional方法，事务不生效
this.method()绕过AOP代理，TransactionInterceptor未执行
自注入@Lazy private XxxService self，或使用AopContext.currentProxy()


2
非public方法事务不生效
private&#x2F;protected方法标注@Transactional，事务不生效
Spring AOP默认只拦截public方法，AbstractFallbackTransactionAttributeSource中非public返回null
确保事务方法为public，代码审查时检查


3
rollbackFor未指定导致不回滚
方法抛出checked Exception（如IOException），数据库未回滚
Spring默认只回滚RuntimeException和Error，checked异常不触发回滚
始终指定@Transactional(rollbackFor = Exception.class)


4
异常被catch导致不回滚
try-catch捕获异常后未重新抛出或标记回滚，事务正常提交
异常未传播到TransactionInterceptor，invokeWithinTransaction走commit分支
catch中调用TransactionAspectSupport.currentTransactionStatus().setRollbackOnly()或重新抛出异常


5
嵌套事务内层回滚影响外层
NESTED内层异常回滚后，外层也回滚
内层回滚时抛出UnexpectedRollbackException，因为globalRollbackOnParticipationFailure默认true
内层catch异常避免传播；或设置globalRollbackOnParticipationFailure=false（不推荐）


6
REQUIRES_NEW挂起事务资源泄漏
REQUIRES_NEW方法频繁调用，数据库连接数暴涨
每次REQUIRES_NEW都挂起当前事务并获取新Connection，外层事务长时间持有时内层连接用完不释放
减少REQUIRES_NEW使用频率；确保外层事务短小；监控连接池使用率


7
多数据源事务不一致
一个事务中切换数据源，第二个数据源操作不受事务管控
@Transactional绑定的Connection只属于一个DataSource，切换后操作在新Connection上
使用Seata&#x2F;JTA分布式事务；或拆分事务，每个数据源独立事务+补偿


8
只读事务写操作报错
@Transactional(readOnly = true)方法中执行INSERT&#x2F;UPDATE抛异常
MySQL的SET TRANSACTION READ ONLY禁止写操作
只读事务中只做查询；写操作使用readOnly = false或REQUIRES_NEW


9
事务超时导致Lock Wait Timeout
事务执行时间超过innodb_lock_wait_timeout，抛出LockWaitTimeoutException
长事务持有行锁&#x2F;表锁，其他事务等待超时
优化SQL和索引减少锁持有时间；设置合理的@Transactional(timeout=30)；拆分长事务


10
Long类型主键自增事务问题
事务回滚后，自增ID不回退，出现ID跳跃
MySQL的innodb_autoinc_lock_mode=1（默认），自增ID分配不受事务回滚影响
这是正常行为，不应依赖ID连续；如需连续序列使用序列表+行锁


11
@Transactional标记在接口上代理失效
接口方法标注@Transactional，CGLIB代理时事务不生效
CGLIB基于类代理，不解析接口上的注解；JDK代理才解析接口注解
将@Transactional标注在实现类的方法上，而非接口上


12
循环依赖+事务代理冲突
Bean A依赖Bean B，Bean B依赖Bean A，且Bean A有@Transactional，启动报错
Spring通过三级缓存解决循环依赖，但@Transactional的代理对象通过SmartInstantiationAwareBeanPostProcessor提前暴露，可能引发BeanCurrentlyInCreationException
使用@Lazy延迟注入；重构设计消除循环依赖；将@Transactional移到不参与循环的Bean上


13
事务中RPC调用导致长事务
@Transactional方法中调用远程服务（HTTP&#x2F;Dubbo），响应慢时事务长时间不提交
远程调用期间事务一直持有数据库连接和锁，阻塞其他事务
事务中只做本地数据库操作；RPC调用移到事务外；使用@TransactionalEventListener在事务提交后再调用远程服务


14
事务中嵌套异步操作数据不一致
@Transactional方法中调用@Async方法，异步方法读不到未提交的数据
@Async在新线程执行，新线程没有事务上下文，无法看到未提交的数据
使用@TransactionalEventListener(phase=AFTER_COMMIT)替代@Async；或在事务提交后再触发异步操作


15
Savepoint不支持的存储引擎
MySQL使用MyISAM引擎时，NESTED传播行为报错
MyISAM不支持事务和Savepoint，只有InnoDB支持
确保所有事务相关表使用InnoDB引擎；建表时显式指定ENGINE=InnoDB


12.1 重点问题详解问题5：嵌套事务内层回滚影响外层@Servicepublic class AlarmProcessService &#123;    @Transactional(rollbackFor = Exception.class)    public void processAlarm(AlarmRecord record) &#123;        alarmRecordMapper.updateStatus(record.getId(), &quot;PROCESSING&quot;);        try &#123;            subAlarmService.handleSubAlarm(record);  // NESTED        &#125; catch (Exception e) &#123;            log.warn(&quot;子告警处理失败&quot;, e);        &#125;        alarmRecordMapper.updateStatus(record.getId(), &quot;PROCESSED&quot;);        // 实际结果：整个事务被标记为rollback-only！    &#125;&#125;@Servicepublic class SubAlarmService &#123;    @Transactional(propagation = Propagation.NESTED, rollbackFor = Exception.class)    public void handleSubAlarm(AlarmRecord record) &#123;        subAlarmMapper.insert(buildSubAlarm(record));        throw new RuntimeException(&quot;子告警处理失败&quot;);    &#125;&#125;// 修复：内层catch异常，不让异常传播@Servicepublic class AlarmProcessService &#123;    @Transactional(rollbackFor = Exception.class)    public void processAlarm(AlarmRecord record) &#123;        alarmRecordMapper.updateStatus(record.getId(), &quot;PROCESSING&quot;);        try &#123;            subAlarmService.handleSubAlarm(record);        &#125; catch (Exception e) &#123;            log.warn(&quot;子告警处理失败，跳过&quot;, e);        &#125;        alarmRecordMapper.updateStatus(record.getId(), &quot;PROCESSED&quot;);    &#125;&#125;

问题13：事务中RPC调用导致长事务// 错误示例@Servicepublic class DeviceDataUploadService &#123;    @Transactional(rollbackFor = Exception.class)    public void uploadAndProcess(DeviceDataDTO data) &#123;        deviceDataMapper.insert(data);        // 在事务中调用边缘网关 -- 危险！        edgeGatewayClient.pushData(data);        deviceDataMapper.updateSyncStatus(data.getId(), &quot;SYNCED&quot;);    &#125;&#125;// 正确做法：事务内只做本地操作@Servicepublic class DeviceDataUploadService &#123;    @Autowired    private ApplicationEventPublisher eventPublisher;    @Transactional(rollbackFor = Exception.class)    public void uploadAndProcess(DeviceDataDTO data) &#123;        deviceDataMapper.insert(data);        deviceDataMapper.updateSyncStatus(data.getId(), &quot;PENDING&quot;);        eventPublisher.publishEvent(new DeviceDataSavedEvent(data.getId()));    &#125;&#125;@Componentpublic class DeviceDataSyncListener &#123;    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)    public void onDeviceDataSaved(DeviceDataSavedEvent event) &#123;        DeviceDataDTO data = deviceDataMapper.selectById(event.getDataId());        edgeGatewayClient.pushData(data);        deviceDataMapper.updateSyncStatus(event.getDataId(), &quot;SYNCED&quot;);    &#125;&#125;

问题14：事务中嵌套异步操作数据不一致// 错误示例@Servicepublic class DeviceRegisterService &#123;    @Autowired    private AsyncTaskService asyncTaskService;    @Transactional(rollbackFor = Exception.class)    public void registerDevice(DeviceRegisterDTO dto) &#123;        Device device = buildDevice(dto);        deviceMapper.insert(device);  // 未提交        // @Async在新线程执行，新线程没有事务上下文        asyncTaskService.initDeviceConfig(device.getId());    &#125;&#125;@Servicepublic class AsyncTaskService &#123;    @Async    public void initDeviceConfig(Long deviceId) &#123;        Device device = deviceMapper.selectById(deviceId);  // 可能返回null！        if (device != null) &#123;            configService.initDefaultConfig(deviceId);        &#125;    &#125;&#125;// 修复：使用@TransactionalEventListener确保事务提交后执行@Servicepublic class DeviceRegisterService &#123;    @Autowired    private ApplicationEventPublisher eventPublisher;    @Transactional(rollbackFor = Exception.class)    public void registerDevice(DeviceRegisterDTO dto) &#123;        Device device = buildDevice(dto);        deviceMapper.insert(device);        eventPublisher.publishEvent(new DeviceCreatedEvent(device.getId()));    &#125;&#125;@Componentpublic class DeviceConfigInitListener &#123;    @Async    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)    public void onDeviceCreated(DeviceCreatedEvent event) &#123;        configService.initDefaultConfig(event.getDeviceId());    &#125;&#125;


十三、Spring事务核心流程总结@Transactional 注解

getTransactionAttribute()  获取属性
determineTransactionManager() 确定TM
createTransactionIfNecessary() 创建事务
invocation.proceed()  执行业务方法
cleanupTransactionInfo() 清理上下文

核心要点回顾：

Spring事务基于AOP代理：理解代理机制是避免事务失效的基础
7种传播行为：REQUIRED最常用，REQUIRES_NEW用于独立事务，NESTED用于部分失败场景
隔离级别：MySQL InnoDB默认REPEATABLE_READ，通过MVCC+Next-Key Lock实现
只读事务：多层优化（JDBC - InnoDB - JPA），但不允许写操作
自调用失效：4种解决方案，推荐自注入和AopContext
事务同步：@TransactionalEventListener比@EventListener更适合事务场景
编程式事务：在需要精确控制事务边界时使用
多数据源事务：JTA&#x2F;Seata&#x2F;自定义路由三种方案各有优劣
长事务危害：事务中不做RPC调用、文件IO等耗时操作
生产问题：15个常见问题覆盖了90%的事务相关Bug

以上内容来自实际项目的实际开发经验和问题排查总结，理解这些原理后，不仅能应对面试追问，更能在项目中设计出健壮的事务方案。

前言在实际项目的电商模块建设中，我们面临了从零搭建订单系统的挑战。矿山物资采购场景下，订单链路涉及多种支付渠道、大额交易、复杂的售后退货流程，以及秒杀抢购时的高并发冲击。承接上篇内容，本文将继续深入讲解支付集成架构、支付回调处理、支付对账、订单超时取消、退款流程设计、订单查询优化、订单导出优化、订单统计设计、售后系统、订单状态通知、高并发订单设计等核心模块，并总结项目实战中遇到的常见问题与解决方案。

七、支付集成架构7.1 多渠道支付统一接入在实际场景中，我们需要同时对接支付宝、微信支付两大主流渠道，同时预留银联、企业对公转账等渠道的扩展能力。核心设计思路是采用策略模式 + 工厂模式实现支付渠道的统一抽象与灵活切换。
/** * 支付渠道策略接口 */public interface PaymentChannelStrategy &#123;    /**     * 获取渠道标识     */    String getChannelCode();    /**     * 创建支付请求     */    PaymentCreateResult createPayment(PaymentCreateRequest request);    /**     * 查询支付状态     */    PaymentQueryResult queryPayment(String outTradeNo);    /**     * 关闭支付交易     */    PaymentCloseResult closePayment(String outTradeNo);    /**     * 申请退款     */    RefundResult applyRefund(RefundRequest request);    /**     * 验证回调签名     */    boolean verifyCallback(PaymentCallback callback);    /**     * 解析回调数据     */    PaymentCallbackData parseCallback(String callbackData);&#125;

7.2 支付渠道工厂@Componentpublic class PaymentChannelFactory implements ApplicationContextAware &#123;    private Map&lt;String, PaymentChannelStrategy&gt; channelMap;    @Override    public void setApplicationContext(ApplicationContext applicationContext) &#123;        Map&lt;String, PaymentChannelStrategy&gt; beans =            applicationContext.getBeansOfType(PaymentChannelStrategy.class);        this.channelMap = beans.values().stream()            .collect(Collectors.toMap(                PaymentChannelStrategy::getChannelCode,                Function.identity()            ));    &#125;    public PaymentChannelStrategy getChannel(String channelCode) &#123;        PaymentChannelStrategy strategy = channelMap.get(channelCode);        if (strategy == null) &#123;            throw new BusinessException(&quot;不支持的支付渠道: &quot; + channelCode);        &#125;        return strategy;    &#125;    public List&lt;String&gt; getAvailableChannels() &#123;        return new ArrayList&lt;&gt;(channelMap.keySet());    &#125;&#125;

7.3 支付宝渠道实现@Slf4j@Componentpublic class AlipayChannelStrategy implements PaymentChannelStrategy &#123;    @Value(&quot;$&#123;payment.alipay.app-id&#125;&quot;)    private String appId;    @Value(&quot;$&#123;payment.alipay.private-key&#125;&quot;)    private String privateKey;    @Value(&quot;$&#123;payment.alipay.public-key&#125;&quot;)    private String alipayPublicKey;    @Value(&quot;$&#123;payment.alipay.gateway&#125;&quot;)    private String gateway;    @Value(&quot;$&#123;payment.alipay.notify-url&#125;&quot;)    private String notifyUrl;    @Value(&quot;$&#123;payment.alipay.return-url&#125;&quot;)    private String returnUrl;    private AlipayClient alipayClient;    @PostConstruct    public void init() &#123;        alipayClient = new DefaultAlipayClient(            gateway, appId, privateKey,            &quot;json&quot;, &quot;UTF-8&quot;, alipayPublicKey, &quot;RSA2&quot;        );    &#125;    @Override    public String getChannelCode() &#123;        return &quot;ALIPAY&quot;;    &#125;    @Override    public PaymentCreateResult createPayment(PaymentCreateRequest request) &#123;        try &#123;            // 根据支付方式选择不同的API            switch (request.getPayMethod()) &#123;                case QR_CODE:                    return createQrPay(request);                case H5:                    return createH5Pay(request);                case APP:                    return createAppPay(request);                case PC_WEB:                    return createPagePay(request);                default:                    throw new BusinessException(&quot;不支持的支付宝支付方式&quot;);            &#125;        &#125; catch (AlipayApiException e) &#123;            log.error(&quot;支付宝创建支付失败&quot;, e);            throw new BusinessException(&quot;支付宝支付创建失败: &quot; + e.getErrMsg());        &#125;    &#125;    /**     * 电脑网站支付（PC）     */    private PaymentCreateResult createPagePay(PaymentCreateRequest request)            throws AlipayApiException &#123;        AlipayTradePagePayRequest alipayRequest = new AlipayTradePagePayRequest();        alipayRequest.setReturnUrl(returnUrl);        alipayRequest.setNotifyUrl(notifyUrl);        JSONObject bizContent = new JSONObject();        bizContent.put(&quot;out_trade_no&quot;, request.getOutTradeNo());        bizContent.put(&quot;total_amount&quot;, request.getAmount().toPlainString());        bizContent.put(&quot;subject&quot;, request.getSubject());        bizContent.put(&quot;product_code&quot;, &quot;FAST_INSTANT_TRADE_PAY&quot;);        // 超时时间设置，订单30分钟未支付自动关闭        bizContent.put(&quot;timeout_express&quot;, &quot;30m&quot;);        alipayRequest.setBizContent(bizContent.toString());        AlipayTradePagePayResponse response = alipayClient.pageExecute(alipayRequest);        return PaymentCreateResult.builder()            .payUrl(response.getBody())            .outTradeNo(request.getOutTradeNo())            .channelCode(getChannelCode())            .build();    &#125;    /**     * APP支付     */    private PaymentCreateResult createAppPay(PaymentCreateRequest request)            throws AlipayApiException &#123;        AlipayTradeAppPayRequest alipayRequest = new AlipayTradeAppPayRequest();        alipayRequest.setNotifyUrl(notifyUrl);        JSONObject bizContent = new JSONObject();        bizContent.put(&quot;out_trade_no&quot;, request.getOutTradeNo());        bizContent.put(&quot;total_amount&quot;, request.getAmount().toPlainString());        bizContent.put(&quot;subject&quot;, request.getSubject());        bizContent.put(&quot;product_code&quot;, &quot;QUICK_MSECURITY_PAY&quot;);        bizContent.put(&quot;timeout_express&quot;, &quot;30m&quot;);        alipayRequest.setBizContent(bizContent.toString());        AlipayTradeAppPayResponse response = alipayClient.sdkExecute(alipayRequest);        return PaymentCreateResult.builder()            .payInfo(response.getBody())            .outTradeNo(request.getOutTradeNo())            .channelCode(getChannelCode())            .build();    &#125;    /**     * 扫码支付     */    private PaymentCreateResult createQrPay(PaymentCreateRequest request)            throws AlipayApiException &#123;        AlipayTradePrecreateRequest alipayRequest = new AlipayTradePrecreateRequest();        alipayRequest.setNotifyUrl(notifyUrl);        JSONObject bizContent = new JSONObject();        bizContent.put(&quot;out_trade_no&quot;, request.getOutTradeNo());        bizContent.put(&quot;total_amount&quot;, request.getAmount().toPlainString());        bizContent.put(&quot;subject&quot;, request.getSubject());        bizContent.put(&quot;timeout_express&quot;, &quot;30m&quot;);        alipayRequest.setBizContent(bizContent.toString());        AlipayTradePrecreateResponse response = alipayClient.execute(alipayRequest);        if (response.isSuccess()) &#123;            return PaymentCreateResult.builder()                .qrCode(response.getQrCode())                .outTradeNo(request.getOutTradeNo())                .channelCode(getChannelCode())                .build();        &#125;        throw new BusinessException(&quot;支付宝扫码支付创建失败: &quot; + response.getSubMsg());    &#125;    /**     * H5支付     */    private PaymentCreateResult createH5Pay(PaymentCreateRequest request)            throws AlipayApiException &#123;        AlipayTradeWapPayRequest alipayRequest = new AlipayTradeWapPayRequest();        alipayRequest.setReturnUrl(returnUrl);        alipayRequest.setNotifyUrl(notifyUrl);        JSONObject bizContent = new JSONObject();        bizContent.put(&quot;out_trade_no&quot;, request.getOutTradeNo());        bizContent.put(&quot;total_amount&quot;, request.getAmount().toPlainString());        bizContent.put(&quot;subject&quot;, request.getSubject());        bizContent.put(&quot;product_code&quot;, &quot;QUICK_WAP_WAY&quot;);        bizContent.put(&quot;timeout_express&quot;, &quot;30m&quot;);        alipayRequest.setBizContent(bizContent.toString());        AlipayTradeWapPayResponse response = alipayClient.pageExecute(alipayRequest, &quot;POST&quot;);        return PaymentCreateResult.builder()            .payUrl(response.getBody())            .outTradeNo(request.getOutTradeNo())            .channelCode(getChannelCode())            .build();    &#125;    @Override    public PaymentQueryResult queryPayment(String outTradeNo) &#123;        try &#123;            AlipayTradeQueryRequest request = new AlipayTradeQueryRequest();            JSONObject bizContent = new JSONObject();            bizContent.put(&quot;out_trade_no&quot;, outTradeNo);            request.setBizContent(bizContent.toString());            AlipayTradeQueryResponse response = alipayClient.execute(request);            if (response.isSuccess()) &#123;                return PaymentQueryResult.builder()                    .outTradeNo(outTradeNo)                    .tradeNo(response.getTradeNo())                    .tradeStatus(response.getTradeStatus())                    .totalAmount(new BigDecimal(response.getTotalAmount()))                    .build();            &#125;            return null;        &#125; catch (AlipayApiException e) &#123;            log.error(&quot;支付宝查询支付状态失败&quot;, e);            throw new BusinessException(&quot;查询支付状态失败&quot;);        &#125;    &#125;    @Override    public PaymentCloseResult closePayment(String outTradeNo) &#123;        try &#123;            AlipayTradeCloseRequest request = new AlipayTradeCloseRequest();            JSONObject bizContent = new JSONObject();            bizContent.put(&quot;out_trade_no&quot;, outTradeNo);            request.setBizContent(bizContent.toString());            AlipayTradeCloseResponse response = alipayClient.execute(request);            return PaymentCloseResult.builder()                .success(response.isSuccess())                .build();        &#125; catch (AlipayApiException e) &#123;            log.error(&quot;支付宝关闭交易失败&quot;, e);            return PaymentCloseResult.builder().success(false).build();        &#125;    &#125;    @Override    public boolean verifyCallback(PaymentCallback callback) &#123;        try &#123;            Map&lt;String, String&gt; params = callback.getParams();            boolean signVerified = AlipaySignature.rsaCheckV1(                params, alipayPublicKey, &quot;UTF-8&quot;, &quot;RSA2&quot;            );            return signVerified;        &#125; catch (AlipayApiException e) &#123;            log.error(&quot;支付宝回调签名验证失败&quot;, e);            return false;        &#125;    &#125;    @Override    public PaymentCallbackData parseCallback(String callbackData) &#123;        // 解析支付宝回调数据        JSONObject json = JSON.parseObject(callbackData);        return PaymentCallbackData.builder()            .outTradeNo(json.getString(&quot;out_trade_no&quot;))            .tradeNo(json.getString(&quot;trade_no&quot;))            .tradeStatus(json.getString(&quot;trade_status&quot;))            .totalAmount(json.getBigDecimal(&quot;total_amount&quot;))            .buyerId(json.getString(&quot;buyer_id&quot;))            .gmtPayment(json.getString(&quot;gmt_payment&quot;))            .build();    &#125;    // applyRefund 实现见退款章节    @Override    public RefundResult applyRefund(RefundRequest request) &#123;        // 在退款章节详细展开        return null;    &#125;&#125;

7.4 微信支付渠道实现@Slf4j@Componentpublic class WechatPayChannelStrategy implements PaymentChannelStrategy &#123;    @Value(&quot;$&#123;payment.wechat.app-id&#125;&quot;)    private String appId;    @Value(&quot;$&#123;payment.wechat.mch-id&#125;&quot;)    private String mchId;    @Value(&quot;$&#123;payment.wechat.api-key&#125;&quot;)    private String apiKey;    @Value(&quot;$&#123;payment.wechat.cert-path&#125;&quot;)    private String certPath;    @Value(&quot;$&#123;payment.wechat.notify-url&#125;&quot;)    private String notifyUrl;    private WXPay wxPay;    @PostConstruct    public void init() throws Exception &#123;        WXPayConfig config = new WXPayConfig() &#123;            @Override            public String getAppID() &#123; return appId; &#125;            @Override            public String getMchID() &#123; return mchId; &#125;            @Override            public String getKey() &#123; return apiKey; &#125;            @Override            public InputStream getCertStream() &#123;                try &#123;                    return new FileInputStream(certPath);                &#125; catch (FileNotFoundException e) &#123;                    throw new RuntimeException(&quot;微信支付证书不存在&quot;, e);                &#125;            &#125;            @Override            public IWXPayDomain getWXPayDomain() &#123;                return new IWXPayDomain() &#123;                    @Override                    public void report(String domain, long elapsedTimeMillis,                            Exception ex) &#123;&#125;                    @Override                    public DomainInfo getDomain(WXPayConfig config) &#123;                        return new DomainInfo(&quot;api.mch.weixin.qq.com&quot;, true);                    &#125;                &#125;;            &#125;        &#125;;        wxPay = new WXPay(config);    &#125;    @Override    public String getChannelCode() &#123;        return &quot;WECHAT&quot;;    &#125;    @Override    public PaymentCreateResult createPayment(PaymentCreateRequest request) &#123;        try &#123;            Map&lt;String, String&gt; reqData = new HashMap&lt;&gt;();            reqData.put(&quot;out_trade_no&quot;, request.getOutTradeNo());            // 微信金额单位为分            reqData.put(&quot;total_fee&quot;, String.valueOf(                request.getAmount().multiply(new BigDecimal(100)).intValue()));            reqData.put(&quot;body&quot;, request.getSubject());            reqData.put(&quot;notify_url&quot;, notifyUrl);            reqData.put(&quot;trade_type&quot;, getTradeType(request.getPayMethod()));            // 30分钟超时            reqData.put(&quot;time_expire&quot;, LocalDateTime.now()                .plusMinutes(30)                .format(DateTimeFormatter.ofPattern(&quot;yyyyMMddHHmmss&quot;)));            switch (request.getPayMethod()) &#123;                case JSAPI:                    reqData.put(&quot;openid&quot;, request.getOpenId());                    break;                case NATIVE:                    // 扫码支付，无需额外参数                    break;                case APP:                    // APP支付                    break;                case H5:                    Map&lt;String, String&gt; sceneInfo = new HashMap&lt;&gt;();                    sceneInfo.put(&quot;type&quot;, &quot;Wap&quot;);                    sceneInfo.put(&quot;wap_url&quot;, request.getWapUrl());                    sceneInfo.put(&quot;wap_name&quot;, request.getWapName());                    reqData.put(&quot;scene_info&quot;, JSON.toJSONString(sceneInfo));                    break;                default:                    break;            &#125;            Map&lt;String, String&gt; response = wxPay.unifiedOrder(reqData);            if (&quot;SUCCESS&quot;.equals(response.get(&quot;return_code&quot;))                    &amp;&amp; &quot;SUCCESS&quot;.equals(response.get(&quot;result_code&quot;))) &#123;                return PaymentCreateResult.builder()                    .prepayId(response.get(&quot;prepay_id&quot;))                    .qrCode(response.get(&quot;code_url&quot;))                    .outTradeNo(request.getOutTradeNo())                    .channelCode(getChannelCode())                    .build();            &#125;            throw new BusinessException(&quot;微信支付创建失败: &quot; + response.get(&quot;err_code_des&quot;));        &#125; catch (Exception e) &#123;            log.error(&quot;微信支付创建失败&quot;, e);            throw new BusinessException(&quot;微信支付创建失败&quot;);        &#125;    &#125;    private String getTradeType(PayMethod payMethod) &#123;        switch (payMethod) &#123;            case JSAPI: return &quot;JSAPI&quot;;            case NATIVE: return &quot;NATIVE&quot;;            case APP: return &quot;APP&quot;;            case H5: return &quot;MWEB&quot;;            default: throw new BusinessException(&quot;不支持的微信支付方式&quot;);        &#125;    &#125;    @Override    public boolean verifyCallback(PaymentCallback callback) &#123;        try &#123;            Map&lt;String, String&gt; params = callback.getParams();            return WXPayUtil.isSignatureValid(params, apiKey);        &#125; catch (Exception e) &#123;            log.error(&quot;微信支付回调签名验证失败&quot;, e);            return false;        &#125;    &#125;    @Override    public PaymentCallbackData parseCallback(String callbackData) &#123;        try &#123;            Map&lt;String, String&gt; params = WXPayUtil.xmlToMap(callbackData);            return PaymentCallbackData.builder()                .outTradeNo(params.get(&quot;out_trade_no&quot;))                .tradeNo(params.get(&quot;transaction_id&quot;))                .tradeStatus(&quot;SUCCESS&quot;.equals(params.get(&quot;result_code&quot;))                    ? &quot;TRADE_SUCCESS&quot; : &quot;TRADE_FAILED&quot;)                .totalAmount(new BigDecimal(params.get(&quot;total_fee&quot;))                    .divide(new BigDecimal(100)))                .build();        &#125; catch (Exception e) &#123;            log.error(&quot;微信支付回调数据解析失败&quot;, e);            throw new BusinessException(&quot;回调数据解析失败&quot;);        &#125;    &#125;    @Override    public PaymentQueryResult queryPayment(String outTradeNo) &#123;        try &#123;            Map&lt;String, String&gt; reqData = new HashMap&lt;&gt;();            reqData.put(&quot;out_trade_no&quot;, outTradeNo);            Map&lt;String, String&gt; response = wxPay.orderQuery(reqData);            if (&quot;SUCCESS&quot;.equals(response.get(&quot;trade_state&quot;))) &#123;                return PaymentQueryResult.builder()                    .outTradeNo(outTradeNo)                    .tradeNo(response.get(&quot;transaction_id&quot;))                    .tradeStatus(response.get(&quot;trade_state&quot;))                    .totalAmount(new BigDecimal(response.get(&quot;total_fee&quot;))                        .divide(new BigDecimal(100)))                    .build();            &#125;            return null;        &#125; catch (Exception e) &#123;            log.error(&quot;微信支付查询失败&quot;, e);            throw new BusinessException(&quot;查询支付状态失败&quot;);        &#125;    &#125;    @Override    public PaymentCloseResult closePayment(String outTradeNo) &#123;        try &#123;            Map&lt;String, String&gt; reqData = new HashMap&lt;&gt;();            reqData.put(&quot;out_trade_no&quot;, outTradeNo);            Map&lt;String, String&gt; response = wxPay.closeOrder(reqData);            return PaymentCloseResult.builder()                .success(&quot;SUCCESS&quot;.equals(response.get(&quot;result_code&quot;)))                .build();        &#125; catch (Exception e) &#123;            log.error(&quot;微信支付关闭订单失败&quot;, e);            return PaymentCloseResult.builder().success(false).build();        &#125;    &#125;    @Override    public RefundResult applyRefund(RefundRequest request) &#123;        // 在退款章节详细展开        return null;    &#125;&#125;

7.5 统一下单服务@Service@Slf4jpublic class UnifiedPaymentService &#123;    @Autowired    private PaymentChannelFactory channelFactory;    @Autowired    private PaymentRecordMapper paymentRecordMapper;    @Autowired    private OrderService orderService;    @Autowired    private RedissonClient redissonClient;    /**     * 统一下单入口     */    @Transactional    public PaymentCreateResult createPayment(CreatePaymentRequest request) &#123;        // 1. 查询订单        Order order = orderService.getByOrderNo(request.getOrderNo());        if (order == null) &#123;            throw new BusinessException(&quot;订单不存在&quot;);        &#125;        // 2. 校验订单状态        if (order.getStatus() != OrderStatus.CREATED                &amp;&amp; order.getStatus() != OrderStatus.PAYING) &#123;            throw new BusinessException(&quot;订单状态不允许支付&quot;);        &#125;        // 3. 防重复支付（分布式锁）        String lockKey = &quot;pay:lock:&quot; + order.getOrderNo();        RLock lock = redissonClient.getLock(lockKey);        try &#123;            boolean locked = lock.tryLock(5, 30, TimeUnit.SECONDS);            if (!locked) &#123;                throw new BusinessException(&quot;支付处理中，请勿重复提交&quot;);            &#125;            // 4. 检查是否已存在有效支付记录            PaymentRecord existRecord = paymentRecordMapper                .selectValidByOrderNo(order.getOrderNo());            if (existRecord != null) &#123;                // 已有支付记录，查询支付状态                PaymentChannelStrategy channel = channelFactory                    .getChannel(existRecord.getChannelCode());                PaymentQueryResult queryResult = channel                    .queryPayment(existRecord.getOutTradeNo());                if (queryResult != null                        &amp;&amp; &quot;TRADE_SUCCESS&quot;.equals(queryResult.getTradeStatus())) &#123;                    throw new BusinessException(&quot;订单已支付，请勿重复付款&quot;);                &#125;            &#125;            // 5. 生成支付流水号            String outTradeNo = generateOutTradeNo(                request.getChannelCode(), order.getOrderNo());            // 6. 创建支付记录            PaymentRecord record = new PaymentRecord();            record.setOrderNo(order.getOrderNo());            record.setOutTradeNo(outTradeNo);            record.setChannelCode(request.getChannelCode());            record.setAmount(order.getTotalAmount());            record.setStatus(PaymentStatus.INIT);            record.setCreateBy(order.getUserId());            paymentRecordMapper.insert(record);            // 7. 更新订单状态为支付中            orderService.updateStatus(order.getId(), OrderStatus.PAYING);            // 8. 调用支付渠道下单            PaymentChannelStrategy channel = channelFactory                .getChannel(request.getChannelCode());            PaymentCreateRequest channelRequest = PaymentCreateRequest.builder()                .outTradeNo(outTradeNo)                .amount(order.getTotalAmount())                .subject(&quot;智慧矿山-订单&quot; + order.getOrderNo())                .payMethod(request.getPayMethod())                .openId(request.getOpenId())                .wapUrl(request.getWapUrl())                .wapName(&quot;智慧矿山商城&quot;)                .build();            PaymentCreateResult result = channel.createPayment(channelRequest);            // 9. 更新支付记录            record.setPrepayId(result.getPrepayId());            record.setStatus(PaymentStatus.WAITING);            paymentRecordMapper.updateById(record);            return result;        &#125; catch (InterruptedException e) &#123;            Thread.currentThread().interrupt();            throw new BusinessException(&quot;支付处理异常&quot;);        &#125; finally &#123;            if (lock.isHeldByCurrentThread()) &#123;                lock.unlock();            &#125;        &#125;    &#125;    /**     * 生成支付流水号     * 格式: 支付渠道标识 + 时间戳 + 订单号后6位 + 4位随机数     */    private String generateOutTradeNo(String channelCode, String orderNo) &#123;        String channelPrefix;        switch (channelCode) &#123;            case &quot;ALIPAY&quot;: channelPrefix = &quot;AP&quot;; break;            case &quot;WECHAT&quot;: channelPrefix = &quot;WX&quot;; break;            case &quot;UNIONPAY&quot;: channelPrefix = &quot;UP&quot;; break;            default: channelPrefix = &quot;OT&quot;;        &#125;        String timestamp = LocalDateTime.now()            .format(DateTimeFormatter.ofPattern(&quot;yyyyMMddHHmmss&quot;));        String orderSuffix = orderNo.length() &gt; 6            ? orderNo.substring(orderNo.length() - 6) : orderNo;        String random = String.format(&quot;%04d&quot;, new Random().nextInt(10000));        return channelPrefix + timestamp + orderSuffix + random;    &#125;&#125;

7.6 支付渠道配置表CREATE TABLE `payment_channel_config` (    `id` BIGINT PRIMARY KEY AUTO_INCREMENT,    `channel_code` VARCHAR(32) NOT NULL COMMENT &#x27;渠道编码: ALIPAY/WECHAT/UNIONPAY&#x27;,    `channel_name` VARCHAR(64) NOT NULL COMMENT &#x27;渠道名称&#x27;,    `app_id` VARCHAR(128) COMMENT &#x27;应用ID&#x27;,    `mch_id` VARCHAR(64) COMMENT &#x27;商户号&#x27;,    `private_key` TEXT COMMENT &#x27;应用私钥&#x27;,    `public_key` TEXT COMMENT &#x27;平台公钥&#x27;,    `api_key` VARCHAR(256) COMMENT &#x27;API密钥&#x27;,    `cert_path` VARCHAR(512) COMMENT &#x27;证书路径&#x27;,    `gateway_url` VARCHAR(256) COMMENT &#x27;网关地址&#x27;,    `notify_url` VARCHAR(256) COMMENT &#x27;回调地址&#x27;,    `return_url` VARCHAR(256) COMMENT &#x27;同步跳转地址&#x27;,    `status` TINYINT DEFAULT 1 COMMENT &#x27;1-启用 0-禁用&#x27;,    `min_amount` DECIMAL(18,2) COMMENT &#x27;最小支付金额&#x27;,    `max_amount` DECIMAL(18,2) COMMENT &#x27;最大支付金额&#x27;,    `fee_rate` DECIMAL(5,4) COMMENT &#x27;手续费率&#x27;,    `remark` VARCHAR(256) COMMENT &#x27;备注&#x27;,    `create_time` DATETIME DEFAULT CURRENT_TIMESTAMP,    `update_time` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,    UNIQUE KEY `uk_channel_code` (`channel_code`)) COMMENT &#x27;支付渠道配置表&#x27;;

八、支付回调处理8.1 支付回调整体流程支付回调流程



步骤
操作
说明



1
接收回调请求
支付平台异步通知


2
验证签名
防止伪造回调


3
幂等性校验
查询订单状态，防止重复处理


4
金额校验
回调金额与订单金额一致


5
更新支付记录
更新支付流水状态


6
更新订单状态
标记为已支付


7
发送支付成功事件
通过MQ广播


8
触发后续业务
库存确认、发货准备等


9
返回成功响应
通知支付平台停止重试


8.2 统一回调处理控制器@RestController@RequestMapping(&quot;/api/payment&quot;)@Slf4jpublic class PaymentCallbackController &#123;    @Autowired    private PaymentChannelFactory channelFactory;    @Autowired    private PaymentCallbackService callbackService;    /**     * 支付宝异步回调     */    @PostMapping(&quot;/alipay/callback&quot;)    public String handleAlipayCallback(HttpServletRequest request) &#123;        Map&lt;String, String&gt; params = extractParams(request);        PaymentCallback callback = PaymentCallback.builder()            .channelCode(&quot;ALIPAY&quot;)            .params(params)            .rawData(params.toString())            .build();        CallbackResult result = callbackService.handleCallback(callback);        return result.isSuccess() ? &quot;success&quot; : &quot;fail&quot;;    &#125;    /**     * 微信支付异步回调     */    @PostMapping(&quot;/wechat/callback&quot;)    public String handleWechatCallback(@RequestBody String xmlData) &#123;        PaymentCallback callback = PaymentCallback.builder()            .channelCode(&quot;WECHAT&quot;)            .rawData(xmlData)            .build();        CallbackResult result = callbackService.handleCallback(callback);        // 微信回调返回XML格式        if (result.isSuccess()) &#123;            return &quot;&lt;xml&gt;&lt;return_code&gt;SUCCESS&lt;/return_code&gt;&quot;                + &quot;&lt;return_msg&gt;OK&lt;/return_msg&gt;&lt;/xml&gt;&quot;;        &#125;        return &quot;&lt;xml&gt;&lt;return_code&gt;FAIL&lt;/return_code&gt;&quot;            + &quot;&lt;return_msg&gt;PROCESS_FAIL&lt;/return_msg&gt;&lt;/xml&gt;&quot;;    &#125;    private Map&lt;String, String&gt; extractParams(HttpServletRequest request) &#123;        Map&lt;String, String&gt; params = new HashMap&lt;&gt;();        Enumeration&lt;String&gt; parameterNames = request.getParameterNames();        while (parameterNames.hasMoreElements()) &#123;            String name = parameterNames.nextElement();            params.put(name, request.getParameter(name));        &#125;        return params;    &#125;&#125;

8.3 回调处理核心服务@Service@Slf4jpublic class PaymentCallbackService &#123;    @Autowired    private PaymentChannelFactory channelFactory;    @Autowired    private OrderService orderService;    @Autowired    private PaymentRecordMapper paymentRecordMapper;    @Autowired    private RocketMQTemplate rocketMQTemplate;    @Autowired    private RedissonClient redissonClient;    /**     * 统一回调处理     */    @Transactional    public CallbackResult handleCallback(PaymentCallback callback) &#123;        // 1. 获取支付渠道策略        PaymentChannelStrategy channel = channelFactory            .getChannel(callback.getChannelCode());        // 2. 验证签名        if (!channel.verifyCallback(callback)) &#123;            log.warn(&quot;支付回调签名验证失败, channel=&#123;&#125;&quot;, callback.getChannelCode());            return CallbackResult.fail(&quot;签名验证失败&quot;);        &#125;        // 3. 解析回调数据        PaymentCallbackData data = channel.parseCallback(callback.getRawData());        log.info(&quot;收到支付回调: outTradeNo=&#123;&#125;, tradeNo=&#123;&#125;, status=&#123;&#125;&quot;,            data.getOutTradeNo(), data.getTradeNo(), data.getTradeStatus());        // 4. 查询支付记录        PaymentRecord record = paymentRecordMapper            .selectByOutTradeNo(data.getOutTradeNo());        if (record == null) &#123;            log.warn(&quot;支付记录不存在: &#123;&#125;&quot;, data.getOutTradeNo());            return CallbackResult.fail(&quot;支付记录不存在&quot;);        &#125;        // 5. 幂等性校验        if (record.getStatus() == PaymentStatus.SUCCESS) &#123;            log.info(&quot;支付记录已处理: &#123;&#125;&quot;, data.getOutTradeNo());            return CallbackResult.success();        &#125;        // 6. 分布式锁防止并发处理        String lockKey = &quot;callback:lock:&quot; + record.getOrderNo();        RLock lock = redissonClient.getLock(lockKey);        try &#123;            boolean locked = lock.tryLock(10, 30, TimeUnit.SECONDS);            if (!locked) &#123;                log.warn(&quot;回调处理锁获取失败: &#123;&#125;&quot;, record.getOrderNo());                return CallbackResult.fail(&quot;处理中&quot;);            &#125;            // 7. 金额校验            if (data.getTotalAmount().compareTo(record.getAmount()) != 0) &#123;                log.error(&quot;支付金额不一致: 订单金额=&#123;&#125;, 回调金额=&#123;&#125;, outTradeNo=&#123;&#125;&quot;,                    record.getAmount(), data.getTotalAmount(),                    data.getOutTradeNo());                // 记录异常，需要人工介入                sendAmountMismatchAlert(record, data);                return CallbackResult.fail(&quot;金额不一致&quot;);            &#125;            // 8. 判断支付结果            if (&quot;TRADE_SUCCESS&quot;.equals(data.getTradeStatus())                    || &quot;TRADE_FINISHED&quot;.equals(data.getTradeStatus())) &#123;                handlePaymentSuccess(record, data);            &#125; else &#123;                handlePaymentFailed(record, data);            &#125;            return CallbackResult.success();        &#125; catch (InterruptedException e) &#123;            Thread.currentThread().interrupt();            return CallbackResult.fail(&quot;处理异常&quot;);        &#125; finally &#123;            if (lock.isHeldByCurrentThread()) &#123;                lock.unlock();            &#125;        &#125;    &#125;    /**     * 支付成功处理     */    private void handlePaymentSuccess(PaymentRecord record,            PaymentCallbackData data) &#123;        // 1. 更新支付记录        record.setStatus(PaymentStatus.SUCCESS);        record.setTradeNo(data.getTradeNo());        record.setBuyerId(data.getBuyerId());        record.setPaymentTime(LocalDateTime.now());        record.setCallbackData(data.toString());        paymentRecordMapper.updateById(record);        // 2. 更新订单状态        Order order = orderService.getByOrderNo(record.getOrderNo());        if (order.getStatus() == OrderStatus.PAID) &#123;            log.info(&quot;订单已支付，跳过: &#123;&#125;&quot;, order.getOrderNo());            return;        &#125;        orderService.updateStatus(order.getId(), OrderStatus.PAID);        // 3. 发送支付成功事件（核心领域事件）        PaymentSuccessEvent event = new PaymentSuccessEvent();        event.setOrderId(order.getId());        event.setOrderNo(order.getOrderNo());        event.setAmount(record.getAmount());        event.setChannelCode(record.getChannelCode());        event.setTradeNo(data.getTradeNo());        event.setPaymentTime(LocalDateTime.now());        rocketMQTemplate.convertAndSend(&quot;payment-success-topic&quot;, event);        log.info(&quot;支付成功处理完成: orderNo=&#123;&#125;, tradeNo=&#123;&#125;&quot;,            order.getOrderNo(), data.getTradeNo());    &#125;    /**     * 支付失败处理     */    private void handlePaymentFailed(PaymentRecord record,            PaymentCallbackData data) &#123;        record.setStatus(PaymentStatus.FAILED);        record.setCallbackData(data.toString());        paymentRecordMapper.updateById(record);        // 将订单状态回退到待支付        Order order = orderService.getByOrderNo(record.getOrderNo());        if (order.getStatus() == OrderStatus.PAYING) &#123;            orderService.updateStatus(order.getId(), OrderStatus.CREATED);        &#125;        log.info(&quot;支付失败处理完成: orderNo=&#123;&#125;&quot;, record.getOrderNo());    &#125;    /**     * 发送金额不一致告警     */    private void sendAmountMismatchAlert(PaymentRecord record,            PaymentCallbackData data) &#123;        AlertMessage alert = AlertMessage.builder()            .level(&quot;HIGH&quot;)            .title(&quot;支付金额不一致告警&quot;)            .content(String.format(                &quot;订单号: %s, 订单金额: %s, 实付金额: %s, 渠道: %s&quot;,                record.getOrderNo(), record.getAmount(),                data.getTotalAmount(), record.getChannelCode()))            .build();        rocketMQTemplate.convertAndSend(&quot;alert-topic&quot;, alert);    &#125;&#125;

8.4 回调重试机制支付平台在未收到成功响应时，会按一定策略重试回调通知。我们需要确保回调接口的健壮性。



支付渠道
重试策略
最大重试次数
重试间隔



支付宝
固定间隔
7次
0s, 2m, 10m, 10m, 1h, 2h, 6h


微信
固定间隔
8次
15s, 15s, 30s, 3m, 10m, 20m, 30m, 30m


银联
固定间隔
5次
0s, 2m, 10m, 1h, 2h


/** * 回调补偿定时任务 * 主动查询支付状态，防止回调丢失 */@Component@Slf4jpublic class PaymentCallbackCompensateJob &#123;    @Autowired    private PaymentRecordMapper paymentRecordMapper;    @Autowired    private PaymentChannelFactory channelFactory;    @Autowired    private PaymentCallbackService callbackService;    /**     * 每分钟执行一次     * 检查支付中超过5分钟仍未收到回调的记录     */    @Scheduled(cron = &quot;0 * * * * ?&quot;)    public void compensate() &#123;        LocalDateTime threshold = LocalDateTime.now().minusMinutes(5);        List&lt;PaymentRecord&gt; records = paymentRecordMapper            .selectWaitingRecords(threshold);        for (PaymentRecord record : records) &#123;            try &#123;                // 主动查询支付渠道                PaymentChannelStrategy channel = channelFactory                    .getChannel(record.getChannelCode());                PaymentQueryResult result = channel                    .queryPayment(record.getOutTradeNo());                if (result != null                        &amp;&amp; &quot;TRADE_SUCCESS&quot;.equals(result.getTradeStatus())) &#123;                    // 构造回调数据并处理                    PaymentCallbackData data = PaymentCallbackData.builder()                        .outTradeNo(record.getOutTradeNo())                        .tradeNo(result.getTradeNo())                        .tradeStatus(result.getTradeStatus())                        .totalAmount(result.getTotalAmount())                        .build();                    PaymentCallback callback = PaymentCallback.builder()                        .channelCode(record.getChannelCode())                        .rawData(data.toString())                        .build();                    callbackService.handleCallback(callback);                    log.info(&quot;回调补偿成功: &#123;&#125;&quot;, record.getOutTradeNo());                &#125;            &#125; catch (Exception e) &#123;                log.error(&quot;回调补偿失败: &#123;&#125;&quot;, record.getOutTradeNo(), e);            &#125;        &#125;    &#125;&#125;

九、支付对账9.1 对账的必要性支付对账是保证系统资金安全的关键环节。在实际场景中，大额订单频繁出现，任何资金差错都可能造成严重损失。对账的主要目的包括：

确保本地支付记录与支付渠道的账单一致
发现并处理长款（用户已付款但本地未记录）和短款（本地已记录但用户未付款）
作为财务核算的数据基础
满足审计合规要求

9.2 对账流程设计架构流程：
flowchart TD    N1[&quot;下载渠道账单  加载本地记录&quot;]    N2[&quot;生成对账报告  差异记录归类处理&quot;]    N3[&quot;按流水号逐笔对账&quot;]    N1 --&gt; N2    N3 --&gt; N2

9.3 对账核心实现@Service@Slf4jpublic class PaymentReconciliationService &#123;    @Autowired    private PaymentChannelFactory channelFactory;    @Autowired    private PaymentRecordMapper paymentRecordMapper;    @Autowired    private ReconciliationResultMapper reconciliationResultMapper;    @Autowired    private RocketMQTemplate rocketMQTemplate;    /**     * 执行日终对账     */    public ReconciliationReport reconcile(String channelCode, LocalDate date) &#123;        log.info(&quot;开始对账: channel=&#123;&#125;, date=&#123;&#125;&quot;, channelCode, date);        // 1. 下载渠道账单        List&lt;ChannelBillItem&gt; channelBills = downloadChannelBill(channelCode, date);        log.info(&quot;渠道账单记录数: &#123;&#125;&quot;, channelBills.size());        // 2. 加载本地支付记录        List&lt;PaymentRecord&gt; localRecords = loadLocalRecords(channelCode, date);        log.info(&quot;本地支付记录数: &#123;&#125;&quot;, localRecords.size());        // 3. 逐笔对账        Map&lt;String, ChannelBillItem&gt; channelBillMap = channelBills.stream()            .collect(Collectors.toMap(ChannelBillItem::getOutTradeNo,                Function.identity(), (a, b) -&gt; b));        Map&lt;String, PaymentRecord&gt; localRecordMap = localRecords.stream()            .collect(Collectors.toMap(PaymentRecord::getOutTradeNo,                Function.identity(), (a, b) -&gt; b));        ReconciliationReport report = new ReconciliationReport();        report.setChannelCode(channelCode);        report.setReconcileDate(date);        report.setChannelCount(channelBills.size());        report.setLocalCount(localRecords.size());        List&lt;ReconciliationResult&gt; results = new ArrayList&lt;&gt;();        // 4. 以渠道账单为基准，逐笔比对        for (ChannelBillItem billItem : channelBills) &#123;            PaymentRecord localRecord = localRecordMap.get(billItem.getOutTradeNo());            if (localRecord == null) &#123;                // 长款：渠道有记录但本地没有                results.add(buildReconciliationResult(                    channelCode, date, billItem.getOutTradeNo(),                    ReconciliationType.CHANNEL_LONG,                    billItem.getAmount(), null,                    &quot;渠道有记录但本地无支付记录&quot;));                continue;            &#125;            // 金额比对            if (billItem.getAmount().compareTo(localRecord.getAmount()) != 0) &#123;                results.add(buildReconciliationResult(                    channelCode, date, billItem.getOutTradeNo(),                    ReconciliationType.AMOUNT_MISMATCH,                    billItem.getAmount(), localRecord.getAmount(),                    String.format(&quot;金额不一致: 渠道=%s, 本地=%s&quot;,                        billItem.getAmount(), localRecord.getAmount())));                continue;            &#125;            // 状态比对            if (!isStatusMatch(billItem.getStatus(), localRecord.getStatus())) &#123;                results.add(buildReconciliationResult(                    channelCode, date, billItem.getOutTradeNo(),                    ReconciliationType.STATUS_MISMATCH,                    billItem.getAmount(), localRecord.getAmount(),                    String.format(&quot;状态不一致: 渠道=%s, 本地=%s&quot;,                        billItem.getStatus(), localRecord.getStatus())));                continue;            &#125;            // 一致，标记为已对账            localRecord.setReconciled(true);            paymentRecordMapper.updateById(localRecord);        &#125;        // 5. 检查短款：本地有记录但渠道没有        for (PaymentRecord localRecord : localRecords) &#123;            if (!channelBillMap.containsKey(localRecord.getOutTradeNo())                    &amp;&amp; localRecord.getStatus() == PaymentStatus.SUCCESS) &#123;                results.add(buildReconciliationResult(                    channelCode, date, localRecord.getOutTradeNo(),                    ReconciliationType.CHANNEL_SHORT,                    null, localRecord.getAmount(),                    &quot;本地已支付但渠道账单无记录&quot;));            &#125;        &#125;        // 6. 保存对账结果        for (ReconciliationResult result : results) &#123;            reconciliationResultMapper.insert(result);        &#125;        // 7. 生成对账报告        report.setMatchCount(localRecords.size() - results.size());        report.setMismatchCount(results.size());        report.setChannelLongCount((int) results.stream()            .filter(r -&gt; r.getType() == ReconciliationType.CHANNEL_LONG).count());        report.setChannelShortCount((int) results.stream()            .filter(r -&gt; r.getType() == ReconciliationType.CHANNEL_SHORT).count());        report.setAmountMismatchCount((int) results.stream()            .filter(r -&gt; r.getType() == ReconciliationType.AMOUNT_MISMATCH).count());        report.setStatusMismatchCount((int) results.stream()            .filter(r -&gt; r.getType() == ReconciliationType.STATUS_MISMATCH).count());        // 8. 存在差异时发送告警        if (!results.isEmpty()) &#123;            sendReconciliationAlert(report, results);        &#125;        log.info(&quot;对账完成: channel=&#123;&#125;, match=&#123;&#125;, mismatch=&#123;&#125;&quot;,            channelCode, report.getMatchCount(), report.getMismatchCount());        return report;    &#125;    /**     * 下载渠道账单     */    private List&lt;ChannelBillItem&gt; downloadChannelBill(String channelCode,            LocalDate date) &#123;        PaymentChannelStrategy channel = channelFactory.getChannel(channelCode);        return channel.downloadBill(date);    &#125;    /**     * 加载本地支付记录     */    private List&lt;PaymentRecord&gt; loadLocalRecords(String channelCode,            LocalDate date) &#123;        LocalDateTime startTime = date.atStartOfDay();        LocalDateTime endTime = date.plusDays(1).atStartOfDay();        return paymentRecordMapper.selectByChannelAndTimeRange(            channelCode, startTime, endTime);    &#125;    private boolean isStatusMatch(String channelStatus, PaymentStatus localStatus) &#123;        if (&quot;TRADE_SUCCESS&quot;.equals(channelStatus)                || &quot;TRADE_FINISHED&quot;.equals(channelStatus)) &#123;            return localStatus == PaymentStatus.SUCCESS;        &#125;        if (&quot;TRADE_CLOSED&quot;.equals(channelStatus)) &#123;            return localStatus == PaymentStatus.CLOSED;        &#125;        return false;    &#125;    private ReconciliationResult buildReconciliationResult(            String channelCode, LocalDate date, String outTradeNo,            ReconciliationType type, BigDecimal channelAmount,            BigDecimal localAmount, String description) &#123;        ReconciliationResult result = new ReconciliationResult();        result.setChannelCode(channelCode);        result.setReconcileDate(date);        result.setOutTradeNo(outTradeNo);        result.setType(type);        result.setChannelAmount(channelAmount);        result.setLocalAmount(localAmount);        result.setDescription(description);        result.setStatus(ReconciliationStatus.PENDING);        return result;    &#125;    private void sendReconciliationAlert(ReconciliationReport report,            List&lt;ReconciliationResult&gt; results) &#123;        AlertMessage alert = AlertMessage.builder()            .level(&quot;HIGH&quot;)            .title(&quot;支付对账差异告警&quot;)            .content(String.format(                &quot;渠道: %s, 日期: %s, 差异数: %d, 长款: %d, 短款: %d, 金额不一致: %d&quot;,                report.getChannelCode(), report.getReconcileDate(),                report.getMismatchCount(), report.getChannelLongCount(),                report.getChannelShortCount(), report.getAmountMismatchCount()))            .build();        rocketMQTemplate.convertAndSend(&quot;alert-topic&quot;, alert);    &#125;&#125;

9.4 对账定时任务@Component@Slf4jpublic class ReconciliationJob &#123;    @Autowired    private PaymentReconciliationService reconciliationService;    @Autowired    private PaymentChannelFactory channelFactory;    /**     * 每天凌晨2点执行，对前一天的数据进行对账     */    @Scheduled(cron = &quot;0 0 2 * * ?&quot;)    public void dailyReconciliation() &#123;        LocalDate yesterday = LocalDate.now().minusDays(1);        List&lt;String&gt; channels = channelFactory.getAvailableChannels();        for (String channel : channels) &#123;            try &#123;                reconciliationService.reconcile(channel, yesterday);            &#125; catch (Exception e) &#123;                log.error(&quot;对账失败: channel=&#123;&#125;&quot;, channel, e);            &#125;        &#125;    &#125;&#125;

9.5 对账差异数据表CREATE TABLE `reconciliation_result` (    `id` BIGINT PRIMARY KEY AUTO_INCREMENT,    `channel_code` VARCHAR(32) NOT NULL COMMENT &#x27;支付渠道&#x27;,    `reconcile_date` DATE NOT NULL COMMENT &#x27;对账日期&#x27;,    `out_trade_no` VARCHAR(64) NOT NULL COMMENT &#x27;商户订单号&#x27;,    `type` VARCHAR(32) NOT NULL COMMENT &#x27;差异类型: CHANNEL_LONG/CHANNEL_SHORT/AMOUNT_MISMATCH/STATUS_MISMATCH&#x27;,    `channel_amount` DECIMAL(18,2) COMMENT &#x27;渠道金额&#x27;,    `local_amount` DECIMAL(18,2) COMMENT &#x27;本地金额&#x27;,    `description` VARCHAR(512) COMMENT &#x27;差异描述&#x27;,    `status` VARCHAR(32) DEFAULT &#x27;PENDING&#x27; COMMENT &#x27;处理状态: PENDING/PROCESSING/RESOLVED&#x27;,    `handler` VARCHAR(64) COMMENT &#x27;处理人&#x27;,    `handle_time` DATETIME COMMENT &#x27;处理时间&#x27;,    `handle_remark` VARCHAR(512) COMMENT &#x27;处理备注&#x27;,    `create_time` DATETIME DEFAULT CURRENT_TIMESTAMP,    `update_time` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,    INDEX `idx_channel_date` (`channel_code`, `reconcile_date`),    INDEX `idx_status` (`status`)) COMMENT &#x27;对账差异记录表&#x27;;

十、订单超时取消10.1 超时取消方案对比


方案
优点
缺点
适用场景



数据库定时扫描
实现简单
延迟大、数据库压力大
订单量小的系统


Redis Key过期
延迟低
可靠性差，不保证通知
辅助方案


RocketMQ延迟消息
延迟低、可靠性高
延迟级别固定
中等规模系统


时间轮(Netty)
延迟极低、精度高
单机方案，需配合持久化
高性能场景


Redis + MQ组合
延迟低、可靠、灵活
实现复杂
大规模生产系统


在实际场景中，我们采用 RocketMQ延迟消息 + 定时任务兜底 的双保险方案。
10.2 延迟消息方案@Component@Slf4jpublic class OrderTimeoutHandler &#123;    @Autowired    private RocketMQTemplate rocketMQTemplate;    @Autowired    private OrderService orderService;    /**     * 订单超时时间（秒），默认30分钟     */    @Value(&quot;$&#123;order.timeout-seconds:1800&#125;&quot;)    private long orderTimeoutSeconds;    /**     * 发送延迟消息     * 在创建订单后立即调用     */    public void sendDelayMessage(Long orderId) &#123;        OrderTimeoutEvent event = new OrderTimeoutEvent();        event.setOrderId(orderId);        event.setCreateTime(LocalDateTime.now());        rocketMQTemplate.syncSend(            &quot;order-timeout-topic&quot;,            MessageBuilder.withPayload(event)                .setKeys(String.valueOf(orderId))                .build(),            3000,  // 发送超时3秒            getDelayLevel(orderTimeoutSeconds)        );        log.info(&quot;订单超时延迟消息已发送: orderId=&#123;&#125;, timeout=&#123;&#125;s&quot;,            orderId, orderTimeoutSeconds);    &#125;    /**     * RocketMQ延迟级别映射     * Level  1: 1s    Level  2: 5s    Level  3: 10s   Level  4: 30s     * Level  5: 1m    Level  6: 2m    Level  7: 3m    Level  8: 4m     * Level  9: 5m    Level 10: 6m    Level 11: 7m    Level 12: 8m     * Level 13: 9m    Level 14: 10m   Level 15: 20m   Level 16: 30m     * Level 17: 1h    Level 18: 2h     */    private int getDelayLevel(long seconds) &#123;        if (seconds &lt;= 1) return 1;        if (seconds &lt;= 5) return 2;        if (seconds &lt;= 10) return 3;        if (seconds &lt;= 30) return 4;        if (seconds &lt;= 60) return 5;        if (seconds &lt;= 120) return 6;        if (seconds &lt;= 180) return 7;        if (seconds &lt;= 240) return 8;        if (seconds &lt;= 300) return 9;        if (seconds &lt;= 360) return 10;        if (seconds &lt;= 420) return 11;        if (seconds &lt;= 480) return 12;        if (seconds &lt;= 540) return 13;        if (seconds &lt;= 600) return 14;        if (seconds &lt;= 1200) return 15;        if (seconds &lt;= 1800) return 16;        if (seconds &lt;= 3600) return 17;        return 18;    &#125;    /**     * 消费延迟消息     */    @RocketMQMessageListener(        topic = &quot;order-timeout-topic&quot;,        consumerGroup = &quot;order-timeout-consumer&quot;,        selectorExpression = &quot;*&quot;    )    @Component    public class OrderTimeoutConsumer implements RocketMQListener&lt;OrderTimeoutEvent&gt; &#123;        @Autowired        private OrderService orderService;        @Autowired        private StockService stockService;        @Override        public void onMessage(OrderTimeoutEvent event) &#123;            Long orderId = event.getOrderId();            // 1. 查询订单            Order order = orderService.getById(orderId);            if (order == null) &#123;                log.warn(&quot;超时订单不存在: &#123;&#125;&quot;, orderId);                return;            &#125;            // 2. 如果订单已支付，忽略            if (order.getStatus() == OrderStatus.PAID                    || order.getStatus() == OrderStatus.SHIPPED                    || order.getStatus() == OrderStatus.COMPLETED) &#123;                log.info(&quot;订单已支付，忽略超时: &#123;&#125;&quot;, orderId);                return;            &#125;            // 3. 如果订单仍未支付，执行取消            if (order.getStatus() == OrderStatus.CREATED                    || order.getStatus() == OrderStatus.PAYING) &#123;                try &#123;                    orderService.cancelOrder(orderId);                    log.info(&quot;订单超时取消成功: &#123;&#125;&quot;, orderId);                &#125; catch (Exception e) &#123;                    log.error(&quot;订单超时取消失败: &#123;&#125;&quot;, orderId, e);                &#125;            &#125;        &#125;    &#125;&#125;

10.3 定时任务兜底方案延迟消息可能因MQ故障而丢失，定时任务作为兜底方案确保超时订单不会被遗漏。
@Component@Slf4jpublic class OrderTimeoutJob &#123;    @Autowired    private OrderMapper orderMapper;    @Autowired    private OrderService orderService;    /**     * 每分钟执行一次，扫描超时未支付订单     */    @Scheduled(cron = &quot;0 * * * * ?&quot;)    public void handleTimeoutOrders() &#123;        // 查询超过30分钟仍未支付的订单        LocalDateTime timeoutTime = LocalDateTime.now().minusMinutes(30);        // 分页查询，避免一次性加载过多数据        int pageNum = 1;        int pageSize = 500;        int totalCancelled = 0;        while (true) &#123;            PageHelper.startPage(pageNum, pageSize);            List&lt;Order&gt; timeoutOrders = orderMapper                .selectTimeoutOrders(timeoutTime);            if (timeoutOrders.isEmpty()) &#123;                break;            &#125;            for (Order order : timeoutOrders) &#123;                try &#123;                    orderService.cancelOrder(order.getId());                    totalCancelled++;                &#125; catch (Exception e) &#123;                    log.error(&quot;定时任务取消超时订单失败: orderId=&#123;&#125;&quot;,                        order.getId(), e);                &#125;            &#125;            if (timeoutOrders.size() &lt; pageSize) &#123;                break;            &#125;            pageNum++;        &#125;        if (totalCancelled &gt; 0) &#123;            log.info(&quot;定时任务取消超时订单: &#123;&#125; 笔&quot;, totalCancelled);        &#125;    &#125;    /**     * 每天凌晨4点清理异常订单     * 处理长时间处于&quot;支付中&quot;状态的订单     */    @Scheduled(cron = &quot;0 0 4 * * ?&quot;)    public void cleanAbnormalOrders() &#123;        LocalDateTime threshold = LocalDateTime.now().minusHours(2);        // 查询超过2小时仍处于&quot;支付中&quot;状态的订单        List&lt;Order&gt; abnormalOrders = orderMapper            .selectByStatusAndTime(OrderStatus.PAYING, threshold);        for (Order order : abnormalOrders) &#123;            try &#123;                // 主动查询支付状态                PaymentQueryResult result = paymentChannelFactory                    .getChannel(order.getChannelCode())                    .queryPayment(order.getOutTradeNo());                if (result != null                        &amp;&amp; &quot;TRADE_SUCCESS&quot;.equals(result.getTradeStatus())) &#123;                    // 用户已支付但回调丢失，补发回调                    log.warn(&quot;发现支付成功但未回调的订单: &#123;&#125;&quot;, order.getOrderNo());                    // 触发回调处理逻辑...                &#125; else &#123;                    // 确认未支付，取消订单                    orderService.cancelOrder(order.getId());                    log.info(&quot;清理异常订单: &#123;&#125;&quot;, order.getOrderNo());                &#125;            &#125; catch (Exception e) &#123;                log.error(&quot;清理异常订单失败: &#123;&#125;&quot;, order.getOrderNo(), e);            &#125;        &#125;    &#125;&#125;

10.4 取消订单完整逻辑@Transactional(rollbackFor = Exception.class)public void cancelOrder(Long orderId) &#123;    // 1. 查询订单    Order order = orderMapper.selectByIdForUpdate(orderId);    if (order == null) &#123;        throw new BusinessException(&quot;订单不存在&quot;);    &#125;    // 2. 状态校验（只有待支付和支付中的订单可以取消）    if (order.getStatus() != OrderStatus.CREATED            &amp;&amp; order.getStatus() != OrderStatus.PAYING) &#123;        log.info(&quot;订单状态不允许取消: orderId=&#123;&#125;, status=&#123;&#125;&quot;,            orderId, order.getStatus());        return;    &#125;    // 3. 更新订单状态    order.setStatus(OrderStatus.CANCELLED);    order.setCancelReason(&quot;超时未支付，系统自动取消&quot;);    order.setCancelTime(LocalDateTime.now());    order.setUpdateTime(LocalDateTime.now());    orderMapper.updateById(order);    // 4. 回滚库存    List&lt;OrderItem&gt; items = orderItemMapper.selectByOrderId(orderId);    for (OrderItem item : items) &#123;        stockService.rollbackStock(item.getProductId(),            item.getQuantity(), order.getOrderNo());    &#125;    // 5. 释放优惠券    if (order.getCouponId() != null) &#123;        couponService.releaseCoupon(order.getCouponId(), order.getUserId());    &#125;    // 6. 释放积分    if (order.getPointsUsed() &gt; 0) &#123;        pointsService.rollbackPoints(order.getUserId(),            order.getPointsUsed(), order.getOrderNo());    &#125;    // 7. 关闭支付交易（如果存在支付记录）    if (order.getStatus() == OrderStatus.PAYING) &#123;        try &#123;            PaymentRecord record = paymentRecordMapper                .selectValidByOrderNo(order.getOrderNo());            if (record != null) &#123;                PaymentChannelStrategy channel = channelFactory                    .getChannel(record.getChannelCode());                channel.closePayment(record.getOutTradeNo());                record.setStatus(PaymentStatus.CLOSED);                paymentRecordMapper.updateById(record);            &#125;        &#125; catch (Exception e) &#123;            log.error(&quot;关闭支付交易失败: &#123;&#125;&quot;, order.getOrderNo(), e);            // 不影响取消流程，后续对账会处理        &#125;    &#125;    // 8. 发送订单取消事件    OrderCancelledEvent event = new OrderCancelledEvent();    event.setOrderId(orderId);    event.setOrderNo(order.getOrderNo());    event.setUserId(order.getUserId());    event.setCancelReason(order.getCancelReason());    rocketMQTemplate.convertAndSend(&quot;order-cancelled-topic&quot;, event);    log.info(&quot;订单取消完成: orderId=&#123;&#125;, reason=&#123;&#125;&quot;, orderId,        order.getCancelReason());&#125;

