11.2 退款流程买家发起退款申请    │    ▼商家审核 ──拒绝──&gt; 退款关闭，买家可申诉    │  同意    │    ▼买家退货（如需退货）    │    ▼商家确认收货    │    ▼系统发起退款至支付渠道    │    ▼支付渠道退款回调    │    ▼更新退款状态 + 通知买家

11.3 退款核心代码@Service@Slf4jpublic class RefundService &#123;    @Autowired    private RefundOrderMapper refundOrderMapper;    @Autowired    private OrderService orderService;    @Autowired    private PaymentChannelFactory channelFactory;    @Autowired    private PaymentRecordMapper paymentRecordMapper;    @Autowired    private RocketMQTemplate rocketMQTemplate;    @Autowired    private RedissonClient redissonClient;    /**     * 创建退款申请     */    @Transactional    public RefundOrder createRefund(CreateRefundRequest request) &#123;        // 1. 查询原订单        Order order = orderService.getByOrderNo(request.getOrderNo());        if (order == null) &#123;            throw new BusinessException(&quot;订单不存在&quot;);        &#125;        // 2. 校验订单状态        if (order.getStatus() != OrderStatus.PAID                &amp;&amp; order.getStatus() != OrderStatus.SHIPPED                &amp;&amp; order.getStatus() != OrderStatus.COMPLETED) &#123;            throw new BusinessException(&quot;当前订单状态不允许退款&quot;);        &#125;        // 3. 校验退款金额        BigDecimal totalRefunded = refundOrderMapper            .sumRefundedAmountByOrderNo(order.getOrderNo());        BigDecimal remaining = order.getTotalAmount()            .subtract(totalRefunded == null ? BigDecimal.ZERO : totalRefunded);        if (request.getRefundAmount().compareTo(remaining) &gt; 0) &#123;            throw new BusinessException(&quot;退款金额超出可退金额，最多可退: &quot; + remaining);        &#125;        // 4. 防重复提交        String lockKey = &quot;refund:lock:&quot; + order.getOrderNo();        RLock lock = redissonClient.getLock(lockKey);        try &#123;            boolean locked = lock.tryLock(5, 30, TimeUnit.SECONDS);            if (!locked) &#123;                throw new BusinessException(&quot;退款处理中，请勿重复提交&quot;);            &#125;            // 5. 创建退款单            RefundOrder refundOrder = new RefundOrder();            refundOrder.setRefundNo(generateRefundNo());            refundOrder.setOrderNo(order.getOrderNo());            refundOrder.setUserId(order.getUserId());            refundOrder.setRefundAmount(request.getRefundAmount());            refundOrder.setRefundReason(request.getRefundReason());            refundOrder.setRefundType(request.getRefundType());            refundOrder.setStatus(RefundStatus.APPLIED);            refundOrder.setApplyTime(LocalDateTime.now());            refundOrderMapper.insert(refundOrder);            log.info(&quot;退款申请创建成功: refundNo=&#123;&#125;, orderNo=&#123;&#125;, amount=&#123;&#125;&quot;,                refundOrder.getRefundNo(), order.getOrderNo(),                request.getRefundAmount());            return refundOrder;        &#125; catch (InterruptedException e) &#123;            Thread.currentThread().interrupt();            throw new BusinessException(&quot;退款申请异常&quot;);        &#125; finally &#123;            if (lock.isHeldByCurrentThread()) &#123;                lock.unlock();            &#125;        &#125;    &#125;    /**     * 商家审核退款     */    @Transactional    public void approveRefund(Long refundId, boolean approved, String remark) &#123;        RefundOrder refundOrder = refundOrderMapper.selectById(refundId);        if (refundOrder == null) &#123;            throw new BusinessException(&quot;退款单不存在&quot;);        &#125;        if (refundOrder.getStatus() != RefundStatus.APPLIED) &#123;            throw new BusinessException(&quot;退款单状态不允许审核&quot;);        &#125;        if (approved) &#123;            refundOrder.setStatus(RefundStatus.APPROVED);            refundOrder.setApproveTime(LocalDateTime.now());            refundOrder.setApproveRemark(remark);            // 如果是仅退款（无需退货），直接发起退款            if (refundOrder.getRefundType() == RefundType.REFUND_ONLY) &#123;                executeRefund(refundOrder);            &#125;            // 如果是退货退款，等待买家退货后再退款        &#125; else &#123;            refundOrder.setStatus(RefundStatus.REJECTED);            refundOrder.setApproveRemark(remark);        &#125;        refundOrderMapper.updateById(refundOrder);        // 发送退款审核结果通知        RefundAuditEvent event = new RefundAuditEvent();        event.setRefundNo(refundOrder.getRefundNo());        event.setOrderNo(refundOrder.getOrderNo());        event.setApproved(approved);        event.setUserId(refundOrder.getUserId());        rocketMQTemplate.convertAndSend(&quot;refund-audit-topic&quot;, event);    &#125;    /**     * 执行退款至支付渠道     */    @Transactional    public void executeRefund(RefundOrder refundOrder) &#123;        // 1. 查询原支付记录        PaymentRecord paymentRecord = paymentRecordMapper            .selectSuccessByOrderNo(refundOrder.getOrderNo());        if (paymentRecord == null) &#123;            throw new BusinessException(&quot;原支付记录不存在&quot;);        &#125;        // 2. 构建退款请求        RefundRequest refundRequest = RefundRequest.builder()            .outTradeNo(paymentRecord.getOutTradeNo())            .outRefundNo(refundOrder.getRefundNo())            .totalAmount(paymentRecord.getAmount())            .refundAmount(refundOrder.getRefundAmount())            .reason(refundOrder.getRefundReason())            .build();        // 3. 调用支付渠道退款接口        try &#123;            PaymentChannelStrategy channel = channelFactory                .getChannel(paymentRecord.getChannelCode());            RefundResult result = channel.applyRefund(refundRequest);            if (result.isSuccess()) &#123;                refundOrder.setStatus(RefundStatus.REFUNDING);                refundOrder.setChannelRefundNo(result.getChannelRefundNo());            &#125; else &#123;                refundOrder.setStatus(RefundStatus.FAILED);                refundOrder.setFailReason(result.getFailReason());            &#125;        &#125; catch (Exception e) &#123;            log.error(&quot;退款至支付渠道失败: refundNo=&#123;&#125;&quot;, refundOrder.getRefundNo(), e);            refundOrder.setStatus(RefundStatus.FAILED);            refundOrder.setFailReason(&quot;退款接口调用异常: &quot; + e.getMessage());        &#125;        refundOrderMapper.updateById(refundOrder);    &#125;    /**     * 退款回调处理     */    @Transactional    public void handleRefundCallback(RefundCallbackData data) &#123;        RefundOrder refundOrder = refundOrderMapper            .selectByRefundNo(data.getOutRefundNo());        if (refundOrder == null) &#123;            log.warn(&quot;退款单不存在: &#123;&#125;&quot;, data.getOutRefundNo());            return;        &#125;        if (data.isSuccess()) &#123;            refundOrder.setStatus(RefundStatus.REFUNDED);            refundOrder.setRefundTime(LocalDateTime.now());        &#125; else &#123;            refundOrder.setStatus(RefundStatus.FAILED);            refundOrder.setFailReason(data.getFailReason());        &#125;        refundOrderMapper.updateById(refundOrder);        // 发送退款结果通知        RefundResultEvent event = new RefundResultEvent();        event.setRefundNo(refundOrder.getRefundNo());        event.setOrderNo(refundOrder.getOrderNo());        event.setUserId(refundOrder.getUserId());        event.setSuccess(data.isSuccess());        event.setRefundAmount(refundOrder.getRefundAmount());        rocketMQTemplate.convertAndSend(&quot;refund-result-topic&quot;, event);    &#125;    /**     * 生成退款单号     */    private String generateRefundNo() &#123;        return &quot;RF&quot; + LocalDateTime.now()            .format(DateTimeFormatter.ofPattern(&quot;yyyyMMddHHmmss&quot;))            + String.format(&quot;%06d&quot;, new Random().nextInt(1000000));    &#125;&#125;

11.4 支付宝退款实现// AlipayChannelStrategy 中的 applyRefund 实现@Overridepublic RefundResult applyRefund(RefundRequest request) &#123;    try &#123;        AlipayTradeRefundRequest alipayRequest = new AlipayTradeRefundRequest();        JSONObject bizContent = new JSONObject();        bizContent.put(&quot;out_trade_no&quot;, request.getOutTradeNo());        bizContent.put(&quot;refund_amount&quot;, request.getRefundAmount().toPlainString());        bizContent.put(&quot;out_request_no&quot;, request.getOutRefundNo());        bizContent.put(&quot;refund_reason&quot;, request.getReason());        alipayRequest.setBizContent(bizContent.toString());        AlipayTradeRefundResponse response = alipayClient.execute(alipayRequest);        if (response.isSuccess()) &#123;            return RefundResult.builder()                .success(true)                .channelRefundNo(response.getTradeNo())                .build();        &#125;        return RefundResult.builder()            .success(false)            .failReason(response.getSubMsg())            .build();    &#125; catch (AlipayApiException e) &#123;        log.error(&quot;支付宝退款失败&quot;, e);        return RefundResult.builder()            .success(false)            .failReason(e.getErrMsg())            .build();    &#125;&#125;

11.5 退款数据表CREATE TABLE `refund_order` (    `id` BIGINT PRIMARY KEY AUTO_INCREMENT,    `refund_no` VARCHAR(64) NOT NULL COMMENT &#x27;退款单号&#x27;,    `order_no` VARCHAR(64) NOT NULL COMMENT &#x27;原订单号&#x27;,    `user_id` BIGINT NOT NULL COMMENT &#x27;用户ID&#x27;,    `refund_amount` DECIMAL(18,2) NOT NULL COMMENT &#x27;退款金额&#x27;,    `refund_reason` VARCHAR(512) COMMENT &#x27;退款原因&#x27;,    `refund_type` VARCHAR(32) NOT NULL COMMENT &#x27;退款类型: REFUND_ONLY/REFUND_AND_RETURN&#x27;,    `status` VARCHAR(32) NOT NULL COMMENT &#x27;退款状态: APPLIED/APPROVED/REJECTED/REFUNDING/REFUNDED/FAILED&#x27;,    `channel_refund_no` VARCHAR(64) COMMENT &#x27;支付渠道退款号&#x27;,    `apply_time` DATETIME COMMENT &#x27;申请时间&#x27;,    `approve_time` DATETIME COMMENT &#x27;审核时间&#x27;,    `refund_time` DATETIME COMMENT &#x27;退款到账时间&#x27;,    `approve_remark` VARCHAR(512) COMMENT &#x27;审核备注&#x27;,    `fail_reason` VARCHAR(512) COMMENT &#x27;失败原因&#x27;,    `create_time` DATETIME DEFAULT CURRENT_TIMESTAMP,    `update_time` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,    UNIQUE KEY `uk_refund_no` (`refund_no`),    INDEX `idx_order_no` (`order_no`),    INDEX `idx_user_id` (`user_id`),    INDEX `idx_status` (`status`)) COMMENT &#x27;退款订单表&#x27;;

十二、订单查询优化12.1 查询性能问题分析在实际场景中，订单表数据量增长很快。上线半年后订单表超过500万行，多维条件组合查询性能急剧下降。典型的慢查询场景包括：

用户端：按时间范围 + 订单状态查询个人订单
运营端：按时间范围 + 订单状态 + 商品分类 + 支付渠道等多维条件查询
财务端：按时间范围 + 支付状态 + 退款状态查询

12.2 CQRS架构采用 CQRS（Command Query Responsibility Segregation） 模式，将写操作和读操作分离。写操作走MySQL主库，读操作走Elasticsearch。
架构流程：
flowchart TD    N1[&quot;业务服务&quot;]    N2[&quot;Canal&quot;]    N3[&quot;ES集群 数据同步 (查询)&quot;]    N4[&quot;MySQL主库 (Command)&quot;]    N5[&quot;(主数据)&quot;]    N6[&quot;查询服务 (Query)&quot;]    N1 --&gt; N2    N1 --&gt; N3    N4 --&gt; N2    N4 --&gt; N3    N5 --&gt; N2    N5 --&gt; N3    N2 --&gt; N6    N3 --&gt; N6

12.3 Elasticsearch索引设计&#123;  &quot;mappings&quot;: &#123;    &quot;properties&quot;: &#123;      &quot;orderId&quot;: &#123; &quot;type&quot;: &quot;long&quot; &#125;,      &quot;orderNo&quot;: &#123; &quot;type&quot;: &quot;keyword&quot; &#125;,      &quot;userId&quot;: &#123; &quot;type&quot;: &quot;long&quot; &#125;,      &quot;userName&quot;: &#123; &quot;type&quot;: &quot;keyword&quot;, &quot;fields&quot;: &#123; &quot;text&quot;: &#123; &quot;type&quot;: &quot;text&quot;, &quot;analyzer&quot;: &quot;ik_max_word&quot; &#125; &#125; &#125;,      &quot;status&quot;: &#123; &quot;type&quot;: &quot;keyword&quot; &#125;,      &quot;totalAmount&quot;: &#123; &quot;type&quot;: &quot;double&quot; &#125;,      &quot;payAmount&quot;: &#123; &quot;type&quot;: &quot;double&quot; &#125;,      &quot;channelCode&quot;: &#123; &quot;type&quot;: &quot;keyword&quot; &#125;,      &quot;categoryId&quot;: &#123; &quot;type&quot;: &quot;long&quot; &#125;,      &quot;categoryName&quot;: &#123; &quot;type&quot;: &quot;keyword&quot; &#125;,      &quot;productName&quot;: &#123; &quot;type&quot;: &quot;text&quot;, &quot;analyzer&quot;: &quot;ik_max_word&quot; &#125;,      &quot;productCount&quot;: &#123; &quot;type&quot;: &quot;integer&quot; &#125;,      &quot;createTime&quot;: &#123; &quot;type&quot;: &quot;date&quot;, &quot;format&quot;: &quot;yyyy-MM-dd HH:mm:ss||epoch_millis&quot; &#125;,      &quot;payTime&quot;: &#123; &quot;type&quot;: &quot;date&quot;, &quot;format&quot;: &quot;yyyy-MM-dd HH:mm:ss||epoch_millis&quot; &#125;,      &quot;cancelTime&quot;: &#123; &quot;type&quot;: &quot;date&quot;, &quot;format&quot;: &quot;yyyy-MM-dd HH:mm:ss||epoch_millis&quot; &#125;,      &quot;completeTime&quot;: &#123; &quot;type&quot;: &quot;date&quot;, &quot;format&quot;: &quot;yyyy-MM-dd HH:mm:ss||epoch_millis&quot; &#125;,      &quot;receiverName&quot;: &#123; &quot;type&quot;: &quot;keyword&quot; &#125;,      &quot;receiverPhone&quot;: &#123; &quot;type&quot;: &quot;keyword&quot; &#125;,      &quot;receiverProvince&quot;: &#123; &quot;type&quot;: &quot;keyword&quot; &#125;,      &quot;receiverCity&quot;: &#123; &quot;type&quot;: &quot;keyword&quot; &#125;,      &quot;receiverDistrict&quot;: &#123; &quot;type&quot;: &quot;keyword&quot; &#125;,      &quot;source&quot;: &#123; &quot;type&quot;: &quot;keyword&quot; &#125;,      &quot;remark&quot;: &#123; &quot;type&quot;: &quot;text&quot;, &quot;analyzer&quot;: &quot;ik_max_word&quot; &#125;    &#125;  &#125;,  &quot;settings&quot;: &#123;    &quot;number_of_shards&quot;: 5,    &quot;number_of_replicas&quot;: 1,    &quot;index&quot;: &#123;      &quot;max_result_window&quot;: 100000    &#125;  &#125;&#125;

12.4 Canal数据同步@Component@Slf4j@CanalTable(&quot;t_order&quot;)public class OrderCanalListener implements EntryHandler&lt;OrderES&gt; &#123;    @Autowired    private ElasticsearchRestTemplate esTemplate;    @Override    public void insert(OrderES orderES) &#123;        try &#123;            esTemplate.save(orderES);            log.debug(&quot;ES同步-新增订单: &#123;&#125;&quot;, orderES.getOrderNo());        &#125; catch (Exception e) &#123;            log.error(&quot;ES同步-新增订单失败: &#123;&#125;&quot;, orderES.getOrderNo(), e);        &#125;    &#125;    @Override    public void update(OrderES orderES) &#123;        try &#123;            esTemplate.save(orderES);            log.debug(&quot;ES同步-更新订单: &#123;&#125;&quot;, orderES.getOrderNo());        &#125; catch (Exception e) &#123;            log.error(&quot;ES同步-更新订单失败: &#123;&#125;&quot;, orderES.getOrderNo(), e);        &#125;    &#125;    @Override    public void delete(OrderES orderES) &#123;        try &#123;            esTemplate.delete(orderES);            log.debug(&quot;ES同步-删除订单: &#123;&#125;&quot;, orderES.getOrderNo());        &#125; catch (Exception e) &#123;            log.error(&quot;ES同步-删除订单失败: &#123;&#125;&quot;, orderES.getOrderNo(), e);        &#125;    &#125;&#125;

12.5 订单查询服务@Service@Slf4jpublic class OrderQueryService &#123;    @Autowired    private ElasticsearchRestTemplate esTemplate;    @Autowired    private OrderMapper orderMapper;    @Autowired    private OrderArchiveMapper archiveMapper;    /**     * 多条件分页查询订单     */    public PageResult&lt;OrderQueryVO&gt; searchOrders(OrderSearchRequest request) &#123;        // 1. 构建ES查询条件        BoolQueryBuilder boolQuery = QueryBuilders.boolQuery();        // 用户ID        if (request.getUserId() != null) &#123;            boolQuery.filter(QueryBuilders.termQuery(&quot;userId&quot;, request.getUserId()));        &#125;        // 订单状态        if (CollectionUtils.isNotEmpty(request.getStatuses())) &#123;            boolQuery.filter(QueryBuilders.termsQuery(&quot;status&quot;, request.getStatuses()));        &#125;        // 时间范围        if (request.getStartTime() != null || request.getEndTime() != null) &#123;            RangeQueryBuilder rangeQuery = QueryBuilders.rangeQuery(&quot;createTime&quot;);            if (request.getStartTime() != null) &#123;                rangeQuery.gte(request.getStartTime()                    .format(DateTimeFormatter.ofPattern(&quot;yyyy-MM-dd HH:mm:ss&quot;)));            &#125;            if (request.getEndTime() != null) &#123;                rangeQuery.lte(request.getEndTime()                    .format(DateTimeFormatter.ofPattern(&quot;yyyy-MM-dd HH:mm:ss&quot;)));            &#125;            boolQuery.filter(rangeQuery);        &#125;        // 关键字搜索（订单号/商品名）        if (StringUtils.isNotBlank(request.getKeyword())) &#123;            boolQuery.should(QueryBuilders.wildcardQuery(&quot;orderNo&quot;,                &quot;*&quot; + request.getKeyword() + &quot;*&quot;));            boolQuery.should(QueryBuilders.matchQuery(&quot;productName&quot;, request.getKeyword()));            boolQuery.minimumShouldMatch(1);        &#125;        // 支付渠道        if (StringUtils.isNotBlank(request.getChannelCode())) &#123;            boolQuery.filter(QueryBuilders.termQuery(&quot;channelCode&quot;,                request.getChannelCode()));        &#125;        // 商品分类        if (request.getCategoryId() != null) &#123;            boolQuery.filter(QueryBuilders.termQuery(&quot;categoryId&quot;,                request.getCategoryId()));        &#125;        // 收货地区        if (StringUtils.isNotBlank(request.getReceiverProvince())) &#123;            boolQuery.filter(QueryBuilders.termQuery(&quot;receiverProvince&quot;,                request.getReceiverProvince()));        &#125;        // 2. 构建排序        SortBuilder&lt;?&gt; sortBuilder = new FieldSortBuilder(&quot;createTime&quot;)            .order(SortOrder.DESC);        // 3. 构建查询        NativeSearchQuery searchQuery = new NativeSearchQueryBuilder()            .withQuery(boolQuery)            .withSort(sortBuilder)            .withPageable(PageRequest.of(request.getPageNum() - 1,                request.getPageSize()))            .build();        // 4. 执行查询        SearchHits&lt;OrderES&gt; searchHits = esTemplate.search(searchQuery, OrderES.class);        // 5. 转换结果        List&lt;OrderQueryVO&gt; list = searchHits.getSearchHits().stream()            .map(hit -&gt; convertToVO(hit.getContent()))            .collect(Collectors.toList());        return PageResult.of(list, searchHits.getTotalHits(),            request.getPageNum(), request.getPageSize());    &#125;    /**     * 根据ID查询订单（先查主库，再查归档）     */    public Order getOrder(Long orderId) &#123;        // 1. 先查主表        Order order = orderMapper.selectById(orderId);        if (order != null) &#123;            return order;        &#125;        // 2. 再查归档表        OrderArchive archive = archiveMapper.selectById(orderId);        if (archive != null) &#123;            return Order.fromArchive(archive);        &#125;        return null;    &#125;&#125;

十三、订单导出优化13.1 传统导出的问题在实际场景中，运营和财务人员经常需要导出订单数据。最初采用同步导出方式，数据量大时经常超时失败。主要问题包括：

大数据量导出导致OOM
同步阻塞导致HTTP请求超时
复杂查询拖慢数据库
导出文件格式不统一

13.2 异步导出方案@Service@Slf4jpublic class OrderExportService &#123;    @Autowired    private ElasticsearchRestTemplate esTemplate;    @Autowired    private RocketMQTemplate rocketMQTemplate;    @Autowired    private ExportTaskMapper exportTaskMapper;    @Autowired    private MinioClient minioClient;    /**     * 创建导出任务     */    @Transactional    public ExportTask createExportTask(OrderExportRequest request, Long userId) &#123;        ExportTask task = new ExportTask();        task.setTaskNo(generateTaskNo());        task.setUserId(userId);        task.setExportType(&quot;ORDER&quot;);        task.setParams(JSON.toJSONString(request));        task.setStatus(ExportStatus.PENDING);        task.setCreateTime(LocalDateTime.now());        exportTaskMapper.insert(task);        // 发送导出消息到MQ        ExportMessage message = new ExportMessage();        message.setTaskId(task.getId());        rocketMQTemplate.convertAndSend(&quot;order-export-topic&quot;, message);        return task;    &#125;    /**     * 执行导出（MQ消费者调用）     */    public void executeExport(Long taskId) &#123;        ExportTask task = exportTaskMapper.selectById(taskId);        if (task == null) &#123;            log.error(&quot;导出任务不存在: &#123;&#125;&quot;, taskId);            return;        &#125;        task.setStatus(ExportStatus.PROCESSING);        task.setStartTime(LocalDateTime.now());        exportTaskMapper.updateById(task);        try &#123;            OrderExportRequest request = JSON.parseObject(                task.getParams(), OrderExportRequest.class);            // 使用SXSSFWorkbook流式写入，避免OOM            // 最大行数限制            int maxRows = 1000000;            // 分批从ES查询数据            String filePath = doExport(request, maxRows);            // 上传到MinIO            String fileUrl = uploadToMinio(filePath, task.getTaskNo());            task.setStatus(ExportStatus.COMPLETED);            task.setFileUrl(fileUrl);            task.setEndTime(LocalDateTime.now());            exportTaskMapper.updateById(task);            // 发送导出完成通知            ExportCompleteEvent event = new ExportCompleteEvent();            event.setTaskId(taskId);            event.setUserId(task.getUserId());            event.setFileUrl(fileUrl);            rocketMQTemplate.convertAndSend(&quot;export-complete-topic&quot;, event);        &#125; catch (Exception e) &#123;            log.error(&quot;导出任务执行失败: &#123;&#125;&quot;, taskId, e);            task.setStatus(ExportStatus.FAILED);            task.setFailReason(e.getMessage());            task.setEndTime(LocalDateTime.now());            exportTaskMapper.updateById(task);        &#125;    &#125;    /**     * 流式导出     */    private String doExport(OrderExportRequest request, int maxRows) throws Exception &#123;        String filePath = &quot;/tmp/export/&quot; + request.getExportFileName() + &quot;.xlsx&quot;;        // 使用SXSSFWorkbook，窗口大小1000行        SXSSFWorkbook workbook = new SXSSFWorkbook(1000);        Sheet sheet = workbook.createSheet(&quot;订单数据&quot;);        // 1. 写入表头        Row headerRow = sheet.createRow(0);        String[] headers = &#123;&quot;订单号&quot;, &quot;用户&quot;, &quot;商品&quot;, &quot;数量&quot;, &quot;订单金额&quot;,            &quot;支付金额&quot;, &quot;支付渠道&quot;, &quot;订单状态&quot;, &quot;下单时间&quot;, &quot;支付时间&quot;,            &quot;收货人&quot;, &quot;收货电话&quot;, &quot;收货地址&quot;&#125;;        for (int i = 0; i &lt; headers.length; i++) &#123;            headerRow.createCell(i).setCellValue(headers[i]);        &#125;        // 2. 分批从ES查询并写入        int pageNum = 0;        int pageSize = 5000;        int totalRows = 0;        while (totalRows &lt; maxRows) &#123;            // 构建ES查询            NativeSearchQuery searchQuery = buildExportQuery(request, pageNum, pageSize);            SearchHits&lt;OrderES&gt; hits = esTemplate.search(searchQuery, OrderES.class);            if (hits.isEmpty()) &#123;                break;            &#125;            for (SearchHit&lt;OrderES&gt; hit : hits) &#123;                OrderES order = hit.getContent();                Row row = sheet.createRow(totalRows + 1);                row.createCell(0).setCellValue(order.getOrderNo());                row.createCell(1).setCellValue(order.getUserName());                row.createCell(2).setCellValue(order.getProductName());                row.createCell(3).setCellValue(order.getProductCount());                row.createCell(4).setCellValue(order.getTotalAmount().toString());                row.createCell(5).setCellValue(order.getPayAmount().toString());                row.createCell(6).setCellValue(order.getChannelCode());                row.createCell(7).setCellValue(order.getStatus());                row.createCell(8).setCellValue(order.getCreateTime());                row.createCell(9).setCellValue(order.getPayTime());                row.createCell(10).setCellValue(order.getReceiverName());                row.createCell(11).setCellValue(order.getReceiverPhone());                row.createCell(12).setCellValue(order.getReceiverProvince()                    + order.getReceiverCity() + order.getReceiverDistrict());                totalRows++;            &#125;            if (hits.getSearchHits().size() &lt; pageSize) &#123;                break;            &#125;            pageNum++;            // 每批数据写入后清理缓存            if (pageNum % 10 == 0) &#123;                workbook.dispose();            &#125;        &#125;        // 3. 写入文件        FileOutputStream fos = new FileOutputStream(filePath);        workbook.write(fos);        fos.close();        workbook.dispose();        return filePath;    &#125;    private String uploadToMinio(String filePath, String taskNo) throws Exception &#123;        String bucketName = &quot;order-export&quot;;        String objectName = taskNo + &quot;/&quot; + taskNo + &quot;.xlsx&quot;;        minioClient.putObject(            PutObjectArgs.builder()                .bucket(bucketName)                .object(objectName)                .filename(filePath)                .build()        );        return minioClient.getPresignedObjectUrl(            GetPresignedObjectUrlArgs.builder()                .bucket(bucketName)                .object(objectName)                .expiry(7, TimeUnit.DAYS)                .build()        );    &#125;&#125;

