14.2 实时统计（Redis）@Service@Slf4jpublic class OrderStatisticsService &#123;    @Autowired    private StringRedisTemplate redisTemplate;    @Autowired    private OrderMapper orderMapper;    @Autowired    private ElasticsearchRestTemplate esTemplate;    private static final String DAILY_SALES_KEY = &quot;stats:daily:sales:&quot;;    private static final String DAILY_ORDER_COUNT_KEY = &quot;stats:daily:count:&quot;;    private static final String CHANNEL_STATS_KEY = &quot;stats:channel:&quot;;    private static final String CONVERSION_KEY = &quot;stats:conversion:&quot;;    /**     * 实时更新销售统计（在支付成功回调中调用）     */    public void updateRealtimeStats(PaymentSuccessEvent event) &#123;        String today = LocalDate.now().format(DateTimeFormatter.ofPattern(&quot;yyyyMMdd&quot;));        // 1. 累加日销售额        redisTemplate.opsForValue().increment(            DAILY_SALES_KEY + today,            event.getAmount().longValue());        // 2. 累加日订单数        redisTemplate.opsForValue().increment(DAILY_ORDER_COUNT_KEY + today);        // 3. 累加渠道统计        redisTemplate.opsForHash().increment(            CHANNEL_STATS_KEY + today,            event.getChannelCode(), 1);        // 4. 更新转化漏斗        redisTemplate.opsForHash().increment(            CONVERSION_KEY + today, &quot;paid&quot;, 1);    &#125;    /**     * 更新下单转化（在下单时调用）     */    public void updateCreateConversion() &#123;        String today = LocalDate.now().format(DateTimeFormatter.ofPattern(&quot;yyyyMMdd&quot;));        redisTemplate.opsForHash().increment(CONVERSION_KEY + today, &quot;created&quot;, 1);    &#125;    /**     * 获取实时大盘数据     */    public DashboardVO getDashboard() &#123;        String today = LocalDate.now().format(DateTimeFormatter.ofPattern(&quot;yyyyMMdd&quot;));        DashboardVO dashboard = new DashboardVO();        // 日销售额        String salesStr = redisTemplate.opsForValue()            .get(DAILY_SALES_KEY + today);        dashboard.setDailySales(salesStr != null            ? new BigDecimal(salesStr) : BigDecimal.ZERO);        // 日订单数        String countStr = redisTemplate.opsForValue()            .get(DAILY_ORDER_COUNT_KEY + today);        dashboard.setDailyOrderCount(countStr != null            ? Integer.parseInt(countStr) : 0);        // 渠道分布        Map&lt;Object, Object&gt; channelStats = redisTemplate.opsForHash()            .entries(CHANNEL_STATS_KEY + today);        dashboard.setChannelDistribution(channelStats.entrySet().stream()            .collect(Collectors.toMap(                e -&gt; e.getKey().toString(),                e -&gt; Integer.parseInt(e.getValue().toString())            )));        // 转化漏斗        Map&lt;Object, Object&gt; conversion = redisTemplate.opsForHash()            .entries(CONVERSION_KEY + today);        int created = parseIntSafe(conversion.get(&quot;created&quot;));        int paid = parseIntSafe(conversion.get(&quot;paid&quot;));        dashboard.setCreatedCount(created);        dashboard.setPaidCount(paid);        dashboard.setPayRate(created &gt; 0            ? BigDecimal.valueOf(paid)                .divide(BigDecimal.valueOf(created), 4, RoundingMode.HALF_UP)                .multiply(new BigDecimal(100))            : BigDecimal.ZERO);        return dashboard;    &#125;    private int parseIntSafe(Object obj) &#123;        return obj != null ? Integer.parseInt(obj.toString()) : 0;    &#125;    /**     * 商品销量排行（ES聚合查询）     */    public List&lt;ProductSalesVO&gt; getProductSalesRanking(int topN, LocalDate date) &#123;        BoolQueryBuilder boolQuery = QueryBuilders.boolQuery();        boolQuery.filter(QueryBuilders.rangeQuery(&quot;createTime&quot;)            .gte(date.atStartOfDay()                .format(DateTimeFormatter.ofPattern(&quot;yyyy-MM-dd HH:mm:ss&quot;)))            .lt(date.plusDays(1).atStartOfDay()                .format(DateTimeFormatter.ofPattern(&quot;yyyy-MM-dd HH:mm:ss&quot;))));        boolQuery.filter(QueryBuilders.termQuery(&quot;status&quot;, &quot;PAID&quot;));        NativeSearchQuery searchQuery = new NativeSearchQueryBuilder()            .withQuery(boolQuery)            .addAggregation(AggregationBuilders                .terms(&quot;product_ranking&quot;)                .field(&quot;categoryId&quot;)                .size(topN)                .subAggregation(AggregationBuilders                    .sum(&quot;total_sales&quot;).field(&quot;totalAmount&quot;))                .subAggregation(AggregationBuilders                    .sum(&quot;total_count&quot;).field(&quot;productCount&quot;))            )            .build();        SearchHits&lt;OrderES&gt; hits = esTemplate.search(searchQuery, OrderES.class);        Aggregations aggregations = hits.getAggregations();        List&lt;ProductSalesVO&gt; result = new ArrayList&lt;&gt;();        Terms productTerms = aggregations.get(&quot;product_ranking&quot;);        for (Terms.Bucket bucket : productTerms.getBuckets()) &#123;            ProductSalesVO vo = new ProductSalesVO();            vo.setCategoryId(Long.parseLong(bucket.getKeyAsString()));            vo.setOrderCount(bucket.getDocCount());            Sum totalSales = bucket.getAggregations().get(&quot;total_sales&quot;);            vo.setTotalAmount(BigDecimal.valueOf(totalSales.getValue()));            result.add(vo);        &#125;        return result;    &#125;&#125;

