flowchart TD    N1[&quot;无售后  待审核&quot;]    N2[&quot;已拒绝 待收货&quot;]    N3[&quot;审核通过&quot;]    N4[&quot;退款中 换货&quot;]    N5[&quot;维修&quot;]    N6[&quot;已完成 已完成&quot;]    N1 --&gt; N2    N3 --&gt; N2    N2 --&gt; N4    N2 --&gt; N5    N4 --&gt; N5    N5 --&gt; N4    N4 --&gt; N6    N5 --&gt; N6

15.3 售后核心代码@Service@Slf4jpublic class AfterSaleService &#123;    @Autowired    private AfterSaleOrderMapper afterSaleOrderMapper;    @Autowired    private OrderService orderService;    @Autowired    private RefundService refundService;    @Autowired    private RocketMQTemplate rocketMQTemplate;    /**     * 创建售后申请     */    @Transactional    public AfterSaleOrder createAfterSale(CreateAfterSaleRequest request) &#123;        // 1. 查询原订单        Order order = orderService.getByOrderNo(request.getOrderNo());        if (order == null) &#123;            throw new BusinessException(&quot;订单不存在&quot;);        &#125;        // 2. 校验是否在售后时效内        if (order.getCompleteTime() != null                &amp;&amp; order.getCompleteTime()                    .isBefore(LocalDateTime.now().minusDays(15))) &#123;            throw new BusinessException(&quot;已超过售后申请时效（15天）&quot;);        &#125;        // 3. 校验是否已有进行中的售后单        AfterSaleOrder existing = afterSaleOrderMapper            .selectProcessingByOrderNo(request.getOrderNo());        if (existing != null) &#123;            throw new BusinessException(&quot;该订单已有进行中的售后申请&quot;);        &#125;        // 4. 创建售后单        AfterSaleOrder afterSale = new AfterSaleOrder();        afterSale.setAfterSaleNo(generateAfterSaleNo());        afterSale.setOrderNo(order.getOrderNo());        afterSale.setUserId(order.getUserId());        afterSale.setType(request.getType());        afterSale.setReason(request.getReason());        afterSale.setDescription(request.getDescription());        afterSale.setImages(String.join(&quot;,&quot;, request.getImages()));        afterSale.setStatus(AfterSaleStatus.APPLIED);        afterSale.setApplyTime(LocalDateTime.now());        afterSaleOrderMapper.insert(afterSale);        // 5. 发送售后申请通知        AfterSaleApplyEvent event = new AfterSaleApplyEvent();        event.setAfterSaleNo(afterSale.getAfterSaleNo());        event.setOrderNo(order.getOrderNo());        event.setType(request.getType());        rocketMQTemplate.convertAndSend(&quot;after-sale-apply-topic&quot;, event);        return afterSale;    &#125;    /**     * 商家审核售后     */    @Transactional    public void auditAfterSale(Long afterSaleId, boolean approved,            String remark, BigDecimal refundAmount) &#123;        AfterSaleOrder afterSale = afterSaleOrderMapper.selectById(afterSaleId);        if (afterSale == null) &#123;            throw new BusinessException(&quot;售后单不存在&quot;);        &#125;        if (afterSale.getStatus() != AfterSaleStatus.APPLIED) &#123;            throw new BusinessException(&quot;售后单状态不允许审核&quot;);        &#125;        if (approved) &#123;            afterSale.setStatus(AfterSaleStatus.APPROVED);            afterSale.setAgreedRefundAmount(refundAmount != null                ? refundAmount : afterSale.getRefundAmount());            afterSale.setAuditTime(LocalDateTime.now());            afterSale.setAuditRemark(remark);            // 如果是仅退款类型，直接发起退款            if (afterSale.getType() == AfterSaleType.REFUND_ONLY) &#123;                initiateRefund(afterSale);            &#125;            // 如果是退货退款，等待买家退货        &#125; else &#123;            afterSale.setStatus(AfterSaleStatus.REJECTED);            afterSale.setAuditRemark(remark);            afterSale.setAuditTime(LocalDateTime.now());        &#125;        afterSaleOrderMapper.updateById(afterSale);        // 发送审核结果通知        AfterSaleAuditEvent event = new AfterSaleAuditEvent();        event.setAfterSaleNo(afterSale.getAfterSaleNo());        event.setApproved(approved);        event.setUserId(afterSale.getUserId());        rocketMQTemplate.convertAndSend(&quot;after-sale-audit-topic&quot;, event);    &#125;    /**     * 买家填写退货物流     */    @Transactional    public void submitReturnLogistics(Long afterSaleId,            ReturnLogisticsDTO logistics) &#123;        AfterSaleOrder afterSale = afterSaleOrderMapper.selectById(afterSaleId);        if (afterSale == null) &#123;            throw new BusinessException(&quot;售后单不存在&quot;);        &#125;        if (afterSale.getStatus() != AfterSaleStatus.APPROVED) &#123;            throw new BusinessException(&quot;售后单状态不允许提交物流&quot;);        &#125;        afterSale.setStatus(AfterSaleStatus.RETURNED);        afterSale.setLogisticsCompany(logistics.getCompany());        afterSale.setLogisticsNo(logistics.getNo());        afterSale.setReturnTime(LocalDateTime.now());        afterSaleOrderMapper.updateById(afterSale);    &#125;    /**     * 商家确认收货并退款     */    @Transactional    public void confirmReceiveAndRefund(Long afterSaleId) &#123;        AfterSaleOrder afterSale = afterSaleOrderMapper.selectById(afterSaleId);        if (afterSale == null) &#123;            throw new BusinessException(&quot;售后单不存在&quot;);        &#125;        if (afterSale.getStatus() != AfterSaleStatus.RETURNED) &#123;            throw new BusinessException(&quot;售后单状态不允许确认收货&quot;);        &#125;        initiateRefund(afterSale);        afterSaleOrderMapper.updateById(afterSale);    &#125;    /**     * 发起退款     */    private void initiateRefund(AfterSaleOrder afterSale) &#123;        CreateRefundRequest refundRequest = new CreateRefundRequest();        refundRequest.setOrderNo(afterSale.getOrderNo());        refundRequest.setRefundAmount(afterSale.getAgreedRefundAmount());        refundRequest.setRefundReason(afterSale.getReason());        refundRequest.setRefundType(RefundType.REFUND_ONLY);        refundService.createRefund(refundRequest);        afterSale.setStatus(AfterSaleStatus.REFUNDING);    &#125;    private String generateAfterSaleNo() &#123;        return &quot;AS&quot; + LocalDateTime.now()            .format(DateTimeFormatter.ofPattern(&quot;yyyyMMddHHmmss&quot;))            + String.format(&quot;%06d&quot;, new Random().nextInt(1000000));    &#125;&#125;

