16.2 通知服务架构@Service@Slf4jpublic class OrderNotificationService &#123;    @Autowired    private SmsService smsService;    @Autowired    private WebSocketService webSocketService;    @Autowired    private SiteMessageService siteMessageService;    @Autowired    private WechatTemplateService wechatTemplateService;    @Autowired    private EmailService emailService;    @Autowired    private NotificationConfigMapper configMapper;    /**     * 发送订单通知     * 根据通知类型，查询配置决定走哪些渠道     */    public void sendNotification(NotificationType type,            NotificationData data) &#123;        // 1. 查询通知配置        List&lt;NotificationConfig&gt; configs = configMapper            .selectByType(type);        for (NotificationConfig config : configs) &#123;            try &#123;                switch (config.getChannel()) &#123;                    case SMS:                        sendSms(data, config);                        break;                    case WEBSOCKET:                        sendWebSocket(data, config);                        break;                    case SITE_MESSAGE:                        sendSiteMessage(data, config);                        break;                    case WECHAT_TEMPLATE:                        sendWechatTemplate(data, config);                        break;                    case EMAIL:                        sendEmail(data, config);                        break;                    default:                        log.warn(&quot;未知通知渠道: &#123;&#125;&quot;, config.getChannel());                &#125;            &#125; catch (Exception e) &#123;                log.error(&quot;发送通知失败: type=&#123;&#125;, channel=&#123;&#125;&quot;,                    type, config.getChannel(), e);                // 通知失败不影响主流程，记录日志即可            &#125;        &#125;    &#125;    private void sendSms(NotificationData data, NotificationConfig config) &#123;        SmsRequest request = new SmsRequest();        request.setPhone(data.getPhone());        request.setTemplateCode(config.getTemplateId());        Map&lt;String, String&gt; params = new HashMap&lt;&gt;();        params.put(&quot;orderNo&quot;, data.getOrderNo());        params.put(&quot;amount&quot;, data.getAmount().toPlainString());        params.put(&quot;time&quot;, LocalDateTime.now()            .format(DateTimeFormatter.ofPattern(&quot;yyyy-MM-dd HH:mm&quot;)));        request.setParams(params);        smsService.send(request);    &#125;    private void sendWebSocket(NotificationData data,            NotificationConfig config) &#123;        WebSocketMessage message = WebSocketMessage.builder()            .userId(data.getUserId())            .type(data.getType().name())            .title(data.getTitle())            .content(data.getContent())            .data(data)            .timestamp(System.currentTimeMillis())            .build();        webSocketService.sendToUser(data.getUserId(), message);    &#125;    private void sendSiteMessage(NotificationData data,            NotificationConfig config) &#123;        SiteMessage message = new SiteMessage();        message.setUserId(data.getUserId());        message.setTitle(data.getTitle());        message.setContent(data.getContent());        message.setType(data.getType().name());        message.setIsRead(false);        siteMessageService.send(message);    &#125;    private void sendWechatTemplate(NotificationData data,            NotificationConfig config) &#123;        WechatTemplateMessage message = new WechatTemplateMessage();        message.setTouser(data.getOpenId());        message.setTemplateId(config.getTemplateId());        message.setPage(&quot;pages/order/detail?orderNo=&quot; + data.getOrderNo());        Map&lt;String, WechatTemplateData&gt; templateData = new HashMap&lt;&gt;();        templateData.put(&quot;first&quot;,            new WechatTemplateData(data.getTitle()));        templateData.put(&quot;keyword1&quot;,            new WechatTemplateData(data.getOrderNo()));        templateData.put(&quot;keyword2&quot;,            new WechatTemplateData(data.getAmount().toPlainString()));        templateData.put(&quot;keyword3&quot;,            new WechatTemplateData(data.getStatusDesc()));        templateData.put(&quot;remark&quot;,            new WechatTemplateData(data.getRemark()));        message.setData(templateData);        wechatTemplateService.send(message);    &#125;    private void sendEmail(NotificationData data,            NotificationConfig config) &#123;        EmailRequest request = new EmailRequest();        request.setTo(data.getEmail());        request.setSubject(data.getTitle());        request.setTemplate(config.getTemplateId());        Map&lt;String, Object&gt; params = new HashMap&lt;&gt;();        params.put(&quot;orderNo&quot;, data.getOrderNo());        params.put(&quot;amount&quot;, data.getAmount());        params.put(&quot;status&quot;, data.getStatusDesc());        params.put(&quot;time&quot;, LocalDateTime.now());        request.setParams(params);        emailService.send(request);    &#125;&#125;

16.3 WebSocket实时推送@Configuration@EnableWebSocketpublic class WebSocketConfig implements WebSocketConfigurer &#123;    @Override    public void registerWebSocketHandlers(WebSocketHandlerRegistry registry) &#123;        registry.addHandler(orderWebSocketHandler(), &quot;/ws/order&quot;)            .addInterceptors(new WebSocketHandshakeInterceptor())            .setAllowedOrigins(&quot;*&quot;);    &#125;    @Bean    public WebSocketHandler orderWebSocketHandler() &#123;        return new OrderWebSocketHandler();    &#125;&#125;

@Component@Slf4jpublic class OrderWebSocketHandler extends TextWebSocketHandler &#123;    /**     * 用户ID -&gt; WebSocket会话映射     */    private static final ConcurrentHashMap&lt;Long, WebSocketSession&gt;        SESSION_MAP = new ConcurrentHashMap&lt;&gt;();    @Override    public void afterConnectionEstablished(WebSocketSession session)            throws Exception &#123;        Long userId = getUserId(session);        if (userId != null) &#123;            SESSION_MAP.put(userId, session);            log.info(&quot;WebSocket连接建立: userId=&#123;&#125;&quot;, userId);        &#125;    &#125;    @Override    public void afterConnectionClosed(WebSocketSession session,            CloseStatus status) throws Exception &#123;        Long userId = getUserId(session);        if (userId != null) &#123;            SESSION_MAP.remove(userId);            log.info(&quot;WebSocket连接关闭: userId=&#123;&#125;&quot;, userId);        &#125;    &#125;    /**     * 向指定用户推送消息     */    public void sendToUser(Long userId, Object message) &#123;        WebSocketSession session = SESSION_MAP.get(userId);        if (session != null &amp;&amp; session.isOpen()) &#123;            try &#123;                String json = JSON.toJSONString(message);                session.sendMessage(new TextMessage(json));            &#125; catch (Exception e) &#123;                log.error(&quot;WebSocket推送失败: userId=&#123;&#125;&quot;, userId, e);            &#125;        &#125;    &#125;    /**     * 向所有在线用户广播     */    public void broadcast(Object message) &#123;        String json = JSON.toJSONString(message);        SESSION_MAP.forEach((userId, session) -&gt; &#123;            if (session.isOpen()) &#123;                try &#123;                    session.sendMessage(new TextMessage(json));                &#125; catch (Exception e) &#123;                    log.error(&quot;WebSocket广播失败: userId=&#123;&#125;&quot;, userId, e);                &#125;            &#125;        &#125;);    &#125;    private Long getUserId(WebSocketSession session) &#123;        Object userId = session.getAttributes().get(&quot;userId&quot;);        return userId != null ? (Long) userId : null;    &#125;&#125;

16.4 MQ事件驱动通知@Component@RocketMQMessageListener(    topic = &quot;payment-success-topic&quot;,    consumerGroup = &quot;notification-payment-consumer&quot;)@Slf4jpublic class PaymentSuccessNotificationConsumer        implements RocketMQListener&lt;PaymentSuccessEvent&gt; &#123;    @Autowired    private OrderNotificationService notificationService;    @Autowired    private OrderMapper orderMapper;    @Override    public void onMessage(PaymentSuccessEvent event) &#123;        Order order = orderMapper.selectById(event.getOrderId());        if (order == null) &#123;            return;        &#125;        NotificationData data = NotificationData.builder()            .userId(order.getUserId())            .type(NotificationType.PAYMENT_SUCCESS)            .orderNo(order.getOrderNo())            .amount(event.getAmount())            .title(&quot;支付成功通知&quot;)            .content(&quot;您的订单 &quot; + order.getOrderNo()                + &quot; 已支付成功，金额 ¥&quot; + event.getAmount())            .statusDesc(&quot;已支付&quot;)            .remark(&quot;我们将尽快为您安排发货&quot;)            .build();        notificationService.sendNotification(            NotificationType.PAYMENT_SUCCESS, data);    &#125;&#125;@Component@RocketMQMessageListener(    topic = &quot;order-cancelled-topic&quot;,    consumerGroup = &quot;notification-cancel-consumer&quot;)@Slf4jpublic class OrderCancelledNotificationConsumer        implements RocketMQListener&lt;OrderCancelledEvent&gt; &#123;    @Autowired    private OrderNotificationService notificationService;    @Override    public void onMessage(OrderCancelledEvent event) &#123;        NotificationData data = NotificationData.builder()            .userId(event.getUserId())            .type(NotificationType.ORDER_CANCELLED)            .orderNo(event.getOrderNo())            .title(&quot;订单取消通知&quot;)            .content(&quot;您的订单 &quot; + event.getOrderNo() + &quot; 已取消&quot;)            .statusDesc(&quot;已取消&quot;)            .remark(event.getCancelReason())            .build();        notificationService.sendNotification(            NotificationType.ORDER_CANCELLED, data);    &#125;&#125;

十七、高并发订单设计17.1 高并发场景在实际场景中，每年几次大型矿山物资集中采购活动会产生秒杀级的高并发订单请求。峰值QPS可达上万，主要挑战包括：

瞬间大流量导致数据库连接池耗尽
库存超卖风险
订单号生成性能瓶颈
支付渠道限流

17.2 架构设计架构流程：
flowchart TD    N1[&quot;Nginx 限流&quot;]    N2[&quot;Gateway 网关限流&quot;]    N3[&quot;用户级限流&quot;]    N4[&quot;负载均衡&quot;]    N5[&quot;订单服务 Sentinel限流降级&quot;]    N6[&quot;消费者 异步落库&quot;]    N7[&quot;发送确认&quot;]    N1 --&gt; N2    N1 --&gt; N3    N4 --&gt; N2    N4 --&gt; N3    N2 --&gt; N5    N3 --&gt; N5    N5 --&gt; N6    N5 --&gt; N7

17.3 Redis预扣库存@Service@Slf4jpublic class StockService &#123;    @Autowired    private StringRedisTemplate redisTemplate;    @Autowired    private RedissonClient redissonClient;    @Autowired    private RocketMQTemplate rocketMQTemplate;    private static final String STOCK_KEY = &quot;stock:product:&quot;;    /**     * 预扣库存（Lua脚本保证原子性）     */    public boolean preDeductStock(Long productId, int quantity) &#123;        String key = STOCK_KEY + productId;        String script =            &quot;local stock = tonumber(redis.call(&#x27;GET&#x27;, KEYS[1])) &quot; +            &quot;if stock and stock &gt;= tonumber(ARGV[1]) then &quot; +            &quot;  redis.call(&#x27;DECRBY&#x27;, KEYS[1], ARGV[1]) &quot; +            &quot;  return 1 &quot; +            &quot;else &quot; +            &quot;  return 0 &quot; +            &quot;end&quot;;        DefaultRedisScript&lt;Long&gt; redisScript = new DefaultRedisScript&lt;&gt;(script, Long.class);        Long result = redisTemplate.execute(redisScript,            Collections.singletonList(key),            String.valueOf(quantity));        return result != null &amp;&amp; result == 1;    &#125;    /**     * 回滚库存     */    public void rollbackStock(Long productId, int quantity, String orderNo) &#123;        String key = STOCK_KEY + productId;        redisTemplate.opsForValue().increment(key, quantity);        log.info(&quot;库存回滚: productId=&#123;&#125;, quantity=&#123;&#125;, orderNo=&#123;&#125;&quot;,            productId, quantity, orderNo);    &#125;    /**     * 初始化库存到Redis     */    public void initStockToRedis(Long productId, int stock) &#123;        String key = STOCK_KEY + productId;        redisTemplate.opsForValue().set(key, String.valueOf(stock));    &#125;    /**     * 获取当前库存     */    public int getCurrentStock(Long productId) &#123;        String key = STOCK_KEY + productId;        String stock = redisTemplate.opsForValue().get(key);        return stock != null ? Integer.parseInt(stock) : 0;    &#125;&#125;

17.4 MQ异步下单@Service@Slf4jpublic class HighConcurrencyOrderService &#123;    @Autowired    private StockService stockService;    @Autowired    private OrderMapper orderMapper;    @Autowired    private RocketMQTemplate rocketMQTemplate;    @Autowired    private RedissonClient redissonClient;    @Autowired    private IdGenerator idGenerator;    /**     * 高并发下单入口     * 核心思路：Redis预扣库存 + MQ异步创建订单     */    public OrderCreateResult createOrder(CreateOrderRequest request) &#123;        Long productId = request.getProductId();        int quantity = request.getQuantity();        Long userId = request.getUserId();        // 1. 用户级限流（防止同一用户重复下单）        String userLimitKey = &quot;order:limit:&quot; + userId;        Boolean canOrder = redisTemplate.opsForValue()            .setIfAbsent(userLimitKey, &quot;1&quot;, 5, TimeUnit.SECONDS);        if (!canOrder) &#123;            throw new BusinessException(&quot;操作过于频繁，请稍后重试&quot;);        &#125;        // 2. Redis预扣库存        boolean deducted = stockService.preDeductStock(productId, quantity);        if (!deducted) &#123;            throw new BusinessException(&quot;库存不足&quot;);        &#125;        try &#123;            // 3. 生成订单号（雪花算法，无需数据库交互）            String orderNo = idGenerator.nextId();            // 4. 发送MQ消息，异步创建订单            OrderCreateMessage message = new OrderCreateMessage();            message.setOrderNo(orderNo);            message.setUserId(userId);            message.setProductId(productId);            message.setQuantity(quantity);            message.setAddressId(request.getAddressId());            message.setCouponId(request.getCouponId());            message.setCreateTime(LocalDateTime.now());            SendResult sendResult = rocketMQTemplate.syncSend(                &quot;order-create-topic&quot;,                MessageBuilder.withPayload(message)                    .setKeys(orderNo)                    .build(),                3000            );            if (sendResult.getSendStatus() != SendStatus.SEND_OK) &#123;                // 发送失败，回滚库存                stockService.rollbackStock(productId, quantity, orderNo);                throw new BusinessException(&quot;系统繁忙，请稍后重试&quot;);            &#125;            // 5. 返回订单号，前端轮询查询订单状态            return OrderCreateResult.builder()                .orderNo(orderNo)                .status(&quot;CREATING&quot;)                .build();        &#125; catch (BusinessException e) &#123;            stockService.rollbackStock(productId, quantity, &quot;FAILED&quot;);            throw e;        &#125; catch (Exception e) &#123;            stockService.rollbackStock(productId, quantity, &quot;FAILED&quot;);            log.error(&quot;高并发下单异常&quot;, e);            throw new BusinessException(&quot;系统繁忙，请稍后重试&quot;);        &#125;    &#125;&#125;/** * MQ消费者：异步创建订单落库 */@RocketMQMessageListener(    topic = &quot;order-create-topic&quot;,    consumerGroup = &quot;order-create-consumer&quot;)@Component@Slf4jclass OrderCreateConsumer implements RocketMQListener&lt;OrderCreateMessage&gt; &#123;    @Autowired    private OrderMapper orderMapper;    @Autowired    private OrderItemMapper orderItemMapper;    @Autowired    private ProductMapper productMapper;    @Autowired    private AddressMapper addressMapper;    @Autowired    private OrderTimeoutHandler orderTimeoutHandler;    @Override    public void onMessage(OrderCreateMessage message) &#123;        try &#123;            // 1. 构建订单            Product product = productMapper.selectById(message.getProductId());            Address address = addressMapper.selectById(message.getAddressId());            Order order = new Order();            order.setId(idGenerator.nextId());            order.setOrderNo(message.getOrderNo());            order.setUserId(message.getUserId());            order.setTotalAmount(product.getPrice()                .multiply(BigDecimal.valueOf(message.getQuantity())));            order.setStatus(OrderStatus.CREATED);            order.setCreateTime(message.getCreateTime());            // 设置收货地址            order.setReceiverName(address.getName());            order.setReceiverPhone(address.getPhone());            order.setReceiverProvince(address.getProvince());            order.setReceiverCity(address.getCity());            order.setReceiverDistrict(address.getDistrict());            order.setReceiverAddress(address.getDetail());            orderMapper.insert(order);            // 2. 构建订单明细            OrderItem item = new OrderItem();            item.setOrderId(order.getId());            item.setProductId(product.getId());            item.setProductName(product.getName());            item.setQuantity(message.getQuantity());            item.setPrice(product.getPrice());            orderItemMapper.insert(item);            // 3. 发送超时延迟消息            orderTimeoutHandler.sendDelayMessage(order.getId());            // 4. 发送下单成功通知            // 通过MQ通知用户下单结果            log.info(&quot;异步创建订单成功: orderNo=&#123;&#125;&quot;, order.getOrderNo());        &#125; catch (DuplicateKeyException e) &#123;            // 幂等处理，订单号重复说明已处理            log.info(&quot;订单已存在，跳过: orderNo=&#123;&#125;&quot;, message.getOrderNo());        &#125; catch (Exception e) &#123;            log.error(&quot;异步创建订单失败: orderNo=&#123;&#125;&quot;, message.getOrderNo(), e);            // 创建失败，回滚库存            stockService.rollbackStock(                message.getProductId(), message.getQuantity(),                message.getOrderNo());        &#125;    &#125;&#125;

17.5 雪花算法ID生成器@Component@Slf4jpublic class SnowflakeIdGenerator implements IdGenerator &#123;    /**     * 起始时间戳（2024-01-01）     */    private static final long EPOCH = 1704038400000L;    /**     * 位数分配     * 时间戳: 41位（约69年）     * 数据中心: 5位（0-31）     * 机器ID: 5位（0-31）     * 序列号: 12位（0-4095）     */    private static final long DATACENTER_ID_BITS = 5L;    private static final long WORKER_ID_BITS = 5L;    private static final long SEQUENCE_BITS = 12L;    private static final long MAX_DATACENTER_ID = ~(-1L &lt;&lt; DATACENTER_ID_BITS);    private static final long MAX_WORKER_ID = ~(-1L &lt;&lt; WORKER_ID_BITS);    private static final long SEQUENCE_MASK = ~(-1L &lt;&lt; SEQUENCE_BITS);    private static final long WORKER_ID_SHIFT = SEQUENCE_BITS;    private static final long DATACENTER_ID_SHIFT = SEQUENCE_BITS + WORKER_ID_BITS;    private static final long TIMESTAMP_SHIFT =        SEQUENCE_BITS + WORKER_ID_BITS + DATACENTER_ID_BITS;    @Value(&quot;$&#123;snowflake.datacenter-id:0&#125;&quot;)    private long datacenterId;    @Value(&quot;$&#123;snowflake.worker-id:0&#125;&quot;)    private long workerId;    private long sequence = 0L;    private long lastTimestamp = -1L;    @PostConstruct    public void init() &#123;        if (datacenterId &gt; MAX_DATACENTER_ID || datacenterId &lt; 0) &#123;            throw new IllegalArgumentException(                &quot;datacenterId超出范围: &quot; + datacenterId);        &#125;        if (workerId &gt; MAX_WORKER_ID || workerId &lt; 0) &#123;            throw new IllegalArgumentException(                &quot;workerId超出范围: &quot; + workerId);        &#125;        log.info(&quot;雪花算法ID生成器初始化: datacenterId=&#123;&#125;, workerId=&#123;&#125;&quot;,            datacenterId, workerId);    &#125;    @Override    public synchronized String nextId() &#123;        long timestamp = System.currentTimeMillis();        // 时钟回拨检测        if (timestamp &lt; lastTimestamp) &#123;            long offset = lastTimestamp - timestamp;            if (offset &lt;= 5) &#123;                // 5ms以内等待                try &#123;                    wait(offset &lt;&lt; 1);                    timestamp = System.currentTimeMillis();                    if (timestamp &lt; lastTimestamp) &#123;                        throw new RuntimeException(&quot;时钟回拨，拒绝生成ID&quot;);                    &#125;                &#125; catch (InterruptedException e) &#123;                    Thread.currentThread().interrupt();                    throw new RuntimeException(&quot;等待被中断&quot;, e);                &#125;            &#125; else &#123;                throw new RuntimeException(&quot;时钟回拨，拒绝生成ID&quot;);            &#125;        &#125;        if (timestamp == lastTimestamp) &#123;            sequence = (sequence + 1) &amp; SEQUENCE_MASK;            if (sequence == 0) &#123;                timestamp = waitNextMillis(lastTimestamp);            &#125;        &#125; else &#123;            sequence = 0L;        &#125;        lastTimestamp = timestamp;        long id = ((timestamp - EPOCH) &lt;&lt; TIMESTAMP_SHIFT)            | (datacenterId &lt;&lt; DATACENTER_ID_SHIFT)            | (workerId &lt;&lt; WORKER_ID_SHIFT)            | sequence;        return String.valueOf(id);    &#125;    private long waitNextMillis(long lastTimestamp) &#123;        long timestamp = System.currentTimeMillis();        while (timestamp &lt;= lastTimestamp) &#123;            timestamp = System.currentTimeMillis();        &#125;        return timestamp;    &#125;&#125;

17.6 Sentinel限流降级@Service@Slf4jpublic class OrderService &#123;    /**     * 下单接口限流降级     */    @SentinelResource(        value = &quot;createOrder&quot;,        blockHandler = &quot;handleCreateOrderBlock&quot;,        fallback = &quot;handleCreateOrderFallback&quot;    )    public Order createOrder(CreateOrderRequest request) &#123;        // 正常业务逻辑        // ...    &#125;    /**     * 限流处理：QPS超过阈值时触发     */    public Order handleCreateOrderBlock(CreateOrderRequest request,            BlockException e) &#123;        log.warn(&quot;下单接口限流: userId=&#123;&#125;&quot;, request.getUserId());        throw new BusinessException(&quot;当前下单人数过多，请稍后重试&quot;);    &#125;    /**     * 熔断降级：异常比例/慢调用比例超阈值时触发     */    public Order handleCreateOrderFallback(CreateOrderRequest request,            Throwable e) &#123;        log.error(&quot;下单接口熔断: userId=&#123;&#125;&quot;, request.getUserId(), e);        throw new BusinessException(&quot;系统繁忙，请稍后重试&quot;);    &#125;&#125;

Sentinel流控规则配置：
@Configurationpublic class SentinelConfig &#123;    @PostConstruct    public void initFlowRules() &#123;        List&lt;FlowRule&gt; rules = new ArrayList&lt;&gt;();        // 下单接口限流：单机QPS上限1000        FlowRule createOrderRule = new FlowRule();        createOrderRule.setResource(&quot;createOrder&quot;);        createOrderRule.setGrade(RuleConstant.FLOW_GRADE_QPS);        createOrderRule.setCount(1000);        createOrderRule.setControlBehavior(RuleConstant.CONTROL_BEHAVIOR_WARM_UP);        createOrderRule.setWarmUpPeriodSec(10);        rules.add(createOrderRule);        // 支付接口限流：单机QPS上限500        FlowRule payRule = new FlowRule();        payRule.setResource(&quot;payOrder&quot;);        payRule.setGrade(RuleConstant.FLOW_GRADE_QPS);        payRule.setCount(500);        rules.add(payRule);        FlowRuleManager.loadRules(rules);        // 熔断规则        List&lt;DegradeRule&gt; degradeRules = new ArrayList&lt;&gt;();        DegradeRule degradeRule = new DegradeRule();        degradeRule.setResource(&quot;createOrder&quot;);        degradeRule.setGrade(RuleConstant.DEGRADE_GRADE_EXCEPTION_RATIO);        degradeRule.setCount(0.5);  // 异常比例50%        degradeRule.setTimeWindow(30);  // 熔断时长30秒        degradeRule.setMinRequestAmount(50);  // 最小请求数        degradeRule.setStatIntervalMs(10000);  // 统计时长10秒        degradeRules.add(degradeRule);        DegradeRuleManager.loadRules(degradeRules);    &#125;&#125;

17.7 数据库读写分离@Configurationpublic class DataSourceConfig &#123;    @Bean    @Primary    @ConfigurationProperties(&quot;spring.datasource.master&quot;)    public DataSource masterDataSource() &#123;        return DataSourceBuilder.create().build();    &#125;    @Bean    @ConfigurationProperties(&quot;spring.datasource.slave&quot;)    public DataSource slaveDataSource() &#123;        return DataSourceBuilder.create().build();    &#125;    @Bean    public DataSource routingDataSource(            DataSource masterDataSource,            DataSource slaveDataSource) &#123;        Map&lt;Object, Object&gt; targetDataSources = new HashMap&lt;&gt;();        targetDataSources.put(&quot;master&quot;, masterDataSource);        targetDataSources.put(&quot;slave&quot;, slaveDataSource);        RoutingDataSource routingDataSource = new RoutingDataSource();        routingDataSource.setTargetDataSources(targetDataSources);        routingDataSource.setDefaultTargetDataSource(masterDataSource);        return routingDataSource;    &#125;&#125;/** * 动态数据源路由 */public class RoutingDataSource extends AbstractRoutingDataSource &#123;    @Override    protected Object determineCurrentLookupKey() &#123;        return DataSourceContextHolder.getDataSourceType();    &#125;&#125;/** * 数据源上下文持有者 */public class DataSourceContextHolder &#123;    private static final ThreadLocal&lt;String&gt; CONTEXT_HOLDER =        new ThreadLocal&lt;&gt;();    public static void setMaster() &#123;        CONTEXT_HOLDER.set(&quot;master&quot;);    &#125;    public static void setSlave() &#123;        CONTEXT_HOLDER.set(&quot;slave&quot;);    &#125;    public static String getDataSourceType() &#123;        return CONTEXT_HOLDER.get();    &#125;    public static void clear() &#123;        CONTEXT_HOLDER.remove();    &#125;&#125;/** * AOP切面：读操作走从库，写操作走主库 */@Aspect@Component@Slf4jpublic class DataSourceAspect &#123;    @Before(&quot;@annotation(org.springframework.transaction.annotation.Transactional)&quot;)    public void beforeTransactional(JoinPoint point) &#123;        DataSourceContextHolder.setMaster();    &#125;    @Before(&quot;execution(* com.mine.shop.service.*.get*(..)) || &quot;          + &quot;execution(* com.mine.shop.service.*.query*(..)) || &quot;          + &quot;execution(* com.mine.shop.service.*.search*(..)) || &quot;          + &quot;execution(* com.mine.shop.service.*.find*(..)) || &quot;          + &quot;execution(* com.mine.shop.service.*.list*(..)) || &quot;          + &quot;execution(* com.mine.shop.service.*.count*(..))&quot;)    public void beforeReadOperation(JoinPoint point) &#123;        if (DataSourceContextHolder.getDataSourceType() == null) &#123;            DataSourceContextHolder.setSlave();        &#125;    &#125;    @After(&quot;execution(* com.mine.shop.service.*.*(..))&quot;)    public void after(JoinPoint point) &#123;        DataSourceContextHolder.clear();    &#125;&#125;

十八、数据归档策略18.1 冷热数据分离@Component@Slf4jpublic class OrderArchiveService &#123;    @Autowired    private OrderMapper orderMapper;    @Autowired    private OrderArchiveMapper archiveMapper;    @Autowired    private OrderItemMapper orderItemMapper;    @Autowired    private OrderItemArchiveMapper orderItemArchiveMapper;    @Autowired    private PaymentRecordMapper paymentRecordMapper;    @Autowired    private PaymentRecordArchiveMapper paymentRecordArchiveMapper;    /**     * 归档90天前的已完成/已取消订单     */    @Scheduled(cron = &quot;0 0 3 * * ?&quot;) // 每天凌晨3点执行    public void archiveOrders() &#123;        LocalDateTime archiveTime = LocalDateTime.now().minusDays(90);        int pageNum = 1;        int pageSize = 200;        int totalArchived = 0;        while (true) &#123;            PageHelper.startPage(pageNum, pageSize);            List&lt;Order&gt; orders = orderMapper.selectCompletedOrdersBefore(archiveTime);            if (orders.isEmpty()) &#123;                break;            &#125;            for (Order order : orders) &#123;                try &#123;                    archiveSingleOrder(order);                    totalArchived++;                &#125; catch (Exception e) &#123;                    log.error(&quot;订单归档失败: orderId=&#123;&#125;&quot;, order.getId(), e);                &#125;            &#125;            if (orders.size() &lt; pageSize) &#123;                break;            &#125;            pageNum++;        &#125;        log.info(&quot;订单归档完成: 归档数量=&#123;&#125;&quot;, totalArchived);    &#125;    @Transactional    public void archiveSingleOrder(Order order) &#123;        // 1. 迁移订单到归档表        OrderArchive archive = OrderArchive.fromOrder(order);        archiveMapper.insert(archive);        // 2. 迁移订单明细        List&lt;OrderItem&gt; items = orderItemMapper.selectByOrderId(order.getId());        for (OrderItem item : items) &#123;            OrderItemArchive itemArchive = OrderItemArchive.fromOrderItem(item);            orderItemArchiveMapper.insert(itemArchive);        &#125;        // 3. 迁移支付记录        List&lt;PaymentRecord&gt; records = paymentRecordMapper            .selectByOrderNo(order.getOrderNo());        for (PaymentRecord record : records) &#123;            PaymentRecordArchive recordArchive =                PaymentRecordArchive.fromPaymentRecord(record);            paymentRecordArchiveMapper.insert(recordArchive);        &#125;        // 4. 删除原表数据（先删明细，再删主表）        orderItemMapper.deleteByOrderId(order.getId());        paymentRecordMapper.deleteByOrderNo(order.getOrderNo());        orderMapper.deleteById(order.getId());        log.debug(&quot;订单归档成功: &#123;&#125;&quot;, order.getOrderNo());    &#125;&#125;

18.2 归档表结构-- 订单归档表CREATE TABLE `order_archive` (    `id` BIGINT PRIMARY KEY,    `order_no` VARCHAR(64) UNIQUE,    `user_id` BIGINT,    `total_amount` DECIMAL(18,2),    `pay_amount` DECIMAL(18,2),    `status` INT,    `channel_code` VARCHAR(32),    `create_time` DATETIME,    `pay_time` DATETIME,    `complete_time` DATETIME,    `cancel_time` DATETIME,    `archive_time` DATETIME) ENGINE=ARCHIVE COMMENT=&#x27;订单归档表&#x27;;-- 订单明细归档表CREATE TABLE `order_item_archive` (    `id` BIGINT PRIMARY KEY,    `order_id` BIGINT,    `product_id` BIGINT,    `product_name` VARCHAR(256),    `quantity` INT,    `price` DECIMAL(18,2),    INDEX `idx_order_id` (`order_id`)) ENGINE=ARCHIVE COMMENT=&#x27;订单明细归档表&#x27;;-- 支付记录归档表CREATE TABLE `payment_record_archive` (    `id` BIGINT PRIMARY KEY,    `order_no` VARCHAR(64),    `out_trade_no` VARCHAR(64),    `channel_code` VARCHAR(32),    `amount` DECIMAL(18,2),    `status` VARCHAR(32),    `trade_no` VARCHAR(64),    `payment_time` DATETIME,    INDEX `idx_order_no` (`order_no`)) ENGINE=ARCHIVE COMMENT=&#x27;支付记录归档表&#x27;;

十九、常见项目问题与解决方案二十、总结（下）本文从实际项目实战出发，系统讲解了订单系统下半部分的核心架构设计，涵盖以下关键模块：

支付集成架构：策略模式实现多渠道统一抽象，支付宝&#x2F;微信支付完整接入，防重复支付与分布式锁保障
支付回调处理：统一回调入口、签名验证、幂等性校验、金额校验、回调补偿机制
支付对账：日终自动对账、差异分类处理、长款&#x2F;短款&#x2F;金额不一致的告警与处理
订单超时取消：RocketMQ延迟消息 + 定时任务兜底双保险，取消订单的完整资源回滚
退款流程设计：多种退款场景、退款状态机、渠道退款接口对接、退款回调处理
订单查询优化：CQRS读写分离、ES索引设计、Canal数据同步、多条件组合查询
订单导出优化：异步导出、SXSSFWorkbook流式写入、MinIO文件存储、分页ES查询
订单统计设计：Redis实时统计、ES聚合分析、转化漏斗、商品排行
售后系统：多种售后类型、售后状态机、退货退款流程、售后与退款联动
订单状态通知：MQ事件驱动、多渠道通知（短信&#x2F;WebSocket&#x2F;站内信&#x2F;微信模板&#x2F;邮件）
高并发订单设计：Redis预扣库存、MQ异步落库、雪花算法ID生成、Sentinel限流降级、读写分离

一个健壮的订单系统需要考虑方方面面。从业务逻辑到技术实现，从正常流程到异常处理，从单机到分布式，从同步到异步，每一个环节都需要精心设计与反复验证。在实际项目的实践中，我们深刻体会到：架构没有银弹，只有适合业务场景的最佳实践。

前言
面试中场景题越来越重要，这些题目考察的是实际项目经验。这篇文章结合SpringBoot核心原理、实际项目实战经验，深入分析全局异常处理、参数校验、请求日志等工程实践问题。

SpringBoot工程实践框架全局异常处理架构// 全局异常处理架构@RestControllerAdvicepublic class GlobalExceptionHandler &#123;        @ExceptionHandler(MethodArgumentNotValidException.class)    public ResponseEntity&lt;ErrorResponse&gt; handleValidationException(            MethodArgumentNotValidException ex) &#123;        List&lt;String&gt; errors = ex.getBindingResult()                .getFieldErrors()                .stream()                .map(error -&gt; error.getField() + &quot;: &quot; + error.getDefaultMessage())                .collect(Collectors.toList());                ErrorResponse response = ErrorResponse.builder()                .code(HttpStatus.BAD_REQUEST.value())                .message(&quot;参数校验失败&quot;)                .errors(errors)                .timestamp(LocalDateTime.now())                .build();                return ResponseEntity.badRequest().body(response);    &#125;        @ExceptionHandler(BusinessException.class)    public ResponseEntity&lt;ErrorResponse&gt; handleBusinessException(BusinessException ex) &#123;        ErrorResponse response = ErrorResponse.builder()                .code(ex.getCode())                .message(ex.getMessage())                .timestamp(LocalDateTime.now())                .build();                return ResponseEntity.status(ex.getCode()).body(response);    &#125;        @ExceptionHandler(Exception.class)    public ResponseEntity&lt;ErrorResponse&gt; handleGenericException(Exception ex) &#123;        ErrorResponse response = ErrorResponse.builder()                .code(HttpStatus.INTERNAL_SERVER_ERROR.value())                .message(&quot;系统内部错误&quot;)                .timestamp(LocalDateTime.now())                .build();                return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(response);    &#125;&#125;

参数校验机制// 参数校验机制public class ValidationService &#123;        private final Validator validator;        public &lt;T&gt; void validate(T object, Class&lt;?&gt;... groups) &#123;        Set&lt;ConstraintViolation&lt;T&gt;&gt; violations = validator.validate(object, groups);                if (!violations.isEmpty()) &#123;            StringBuilder message = new StringBuilder(&quot;参数校验失败: &quot;);            for (ConstraintViolation&lt;T&gt; violation : violations) &#123;                message.append(violation.getPropertyPath())                       .append(&quot; &quot;)                       .append(violation.getMessage())                       .append(&quot;; &quot;);            &#125;            throw new ValidationException(message.toString());        &#125;    &#125;        public &lt;T&gt; void validateProperty(T object, String propertyName, Class&lt;?&gt;... groups) &#123;        Set&lt;ConstraintViolation&lt;T&gt;&gt; violations = validator.validateProperty(object, propertyName, groups);                if (!violations.isEmpty()) &#123;            throw new ValidationException(violations.iterator().next().getMessage());        &#125;    &#125;&#125;


一、为什么项目中必须做全局异常处理1. 不做全局异常处理的问题


问题
说明
示例



用户体验差
返回堆栈信息，用户看不懂
java.lang.NullPointerException: ...


安全风险
暴露系统内部结构
暴露数据库表名、类名、方法名


格式不统一
不同异常返回不同格式
有的返回HTML，有的返回JSON


无法监控
异常信息散落在日志中，难以追踪
需要手动搜索日志定位问题


2. 全局异常处理的好处// 没有全局异常处理@GetMapping(&quot;/user/&#123;id&#125;&quot;)public ResponseEntity&lt;User&gt; getUser(@PathVariable Long id) &#123;    User user = userService.findById(id);    if (user == null) &#123;        throw new RuntimeException(&quot;用户不存在&quot;);  // 返回堆栈信息    &#125;    return ResponseEntity.ok(user);&#125;// 有全局异常处理@GetMapping(&quot;/user/&#123;id&#125;&quot;)public ResponseEntity&lt;User&gt; getUser(@PathVariable Long id) &#123;    User user = userService.findById(id);    if (user == null) &#123;        throw new BusinessException(404, &quot;用户不存在&quot;);  // 返回统一格式    &#125;    return ResponseEntity.ok(user);&#125;

3. 统一响应格式// 统一响应封装@Datapublic class ApiResponse&lt;T&gt; &#123;    private Integer code;    private String message;    private T data;    private Long timestamp;    public static &lt;T&gt; ApiResponse&lt;T&gt; success(T data) &#123;        ApiResponse&lt;T&gt; response = new ApiResponse&lt;&gt;();        response.setCode(200);        response.setMessage(&quot;success&quot;);        response.setData(data);        response.setTimestamp(System.currentTimeMillis());        return response;    &#125;    public static &lt;T&gt; ApiResponse&lt;T&gt; fail(Integer code, String message) &#123;        ApiResponse&lt;T&gt; response = new ApiResponse&lt;&gt;();        response.setCode(code);        response.setMessage(message);        response.setTimestamp(System.currentTimeMillis());        return response;    &#125;&#125;

4. 完整的全局异常处理实现@RestControllerAdvice@Slf4jpublic class GlobalExceptionHandler &#123;    /**     * 处理业务异常     */    @ExceptionHandler(BusinessException.class)    public ApiResponse&lt;Void&gt; handleBusinessException(BusinessException ex) &#123;        log.warn(&quot;业务异常: code=&#123;&#125;, message=&#123;&#125;&quot;, ex.getCode(), ex.getMessage());        return ApiResponse.fail(ex.getCode(), ex.getMessage());    &#125;    /**     * 处理参数校验异常（@RequestBody @Valid触发）     */    @ExceptionHandler(MethodArgumentNotValidException.class)    public ApiResponse&lt;Void&gt; handleValidationException(            MethodArgumentNotValidException ex) &#123;        String detail = ex.getBindingResult()                .getFieldErrors()                .stream()                .map(error -&gt; error.getField() + &quot;: &quot; + error.getDefaultMessage())                .collect(Collectors.joining(&quot;; &quot;));        log.warn(&quot;参数校验失败: &#123;&#125;&quot;, detail);        return ApiResponse.fail(400, &quot;参数校验失败: &quot; + detail);    &#125;    /**     * 处理参数绑定异常（@RequestParam类型转换失败）     */    @ExceptionHandler(BindException.class)    public ApiResponse&lt;Void&gt; handleBindException(BindException ex) &#123;        String detail = ex.getBindingResult()                .getFieldErrors()                .stream()                .map(error -&gt; error.getField() + &quot;: &quot; + error.getDefaultMessage())                .collect(Collectors.joining(&quot;; &quot;));        log.warn(&quot;参数绑定失败: &#123;&#125;&quot;, detail);        return ApiResponse.fail(400, &quot;参数绑定失败: &quot; + detail);    &#125;    /**     * 处理参数格式异常（如URL路径参数类型错误）     */    @ExceptionHandler(MethodArgumentTypeMismatchException.class)    public ApiResponse&lt;Void&gt; handleTypeMismatchException(            MethodArgumentTypeMismatchException ex) &#123;        log.warn(&quot;参数格式错误: name=&#123;&#125;, value=&#123;&#125;&quot;, ex.getName(), ex.getValue());        return ApiResponse.fail(400, &quot;参数格式错误: &quot; + ex.getName());    &#125;    /**     * 处理请求方式不支持     */    @ExceptionHandler(HttpRequestMethodNotSupportedException.class)    public ApiResponse&lt;Void&gt; handleMethodNotSupported(            HttpRequestMethodNotSupportedException ex) &#123;        log.warn(&quot;请求方式不支持: &#123;&#125;&quot;, ex.getMethod());        return ApiResponse.fail(405, &quot;不支持的请求方式: &quot; + ex.getMethod());    &#125;    /**     * 处理缺少请求参数     */    @ExceptionHandler(MissingServletRequestParameterException.class)    public ApiResponse&lt;Void&gt; handleMissingParam(            MissingServletRequestParameterException ex) &#123;        log.warn(&quot;缺少请求参数: &#123;&#125;&quot;, ex.getParameterName());        return ApiResponse.fail(400, &quot;缺少必要参数: &quot; + ex.getParameterName());    &#125;    /**     * 处理Feign调用异常     */    @ExceptionHandler(FeignException.class)    public ApiResponse&lt;Void&gt; handleFeignException(FeignException ex) &#123;        log.error(&quot;Feign调用异常: status=&#123;&#125;, message=&#123;&#125;&quot;, ex.status(), ex.getMessage());        return ApiResponse.fail(503, &quot;远程服务调用失败&quot;);    &#125;    /**     * 处理其他未知异常     */    @ExceptionHandler(Exception.class)    public ApiResponse&lt;Void&gt; handleException(Exception ex) &#123;        log.error(&quot;系统异常&quot;, ex);  // 记录完整堆栈        return ApiResponse.fail(500, &quot;系统内部错误，请稍后重试&quot;);    &#125;&#125;// 统一错误响应@Datapublic class ErrorResponse &#123;    private Integer code;    private String message;    private String detail;    public ErrorResponse(Integer code, String message, String detail) &#123;        this.code = code;        this.message = message;        this.detail = detail;    &#125;&#125;// 自定义业务异常@Datapublic class BusinessException extends RuntimeException &#123;    private Integer code;    public BusinessException(Integer code, String message) &#123;        super(message);        this.code = code;    &#125;&#125;

5. 真实项目中的异常处理问题


问题
现象
解决方法



异步线程异常丢失
@Async方法抛出异常，全局处理器捕获不到
使用AsyncUncaughtExceptionHandler或CompletableFuture处理


Filter中异常无法捕获
@RestControllerAdvice只能拦截Controller层
在Filter中手动捕获并写入响应


Feign异常被包装
远程调用400&#x2F;500被包装为FeignException
配置FeignErrorDecoder解析原始异常


异常信息泄露
500错误返回了SQL语句或堆栈
生产环境不返回detail字段，只记录日志


嵌套异常丢失原因
catch后抛出新异常，原始cause丢失
使用new BusinessException(“msg”, e)保留cause


并发修改异常
ArrayList遍历时修改抛ConcurrentModificationException
使用CopyOnWriteArrayList或迭代器删除


6. 异步线程异常处理// 异步线程异常处理@Configurationpublic class AsyncConfig implements AsyncConfigurer &#123;    @Override    public Executor getAsyncExecutor() &#123;        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();        executor.setCorePoolSize(10);        executor.setMaxPoolSize(50);        executor.setQueueCapacity(200);        executor.setThreadNamePrefix(&quot;async-&quot;);        executor.initialize();        return executor;    &#125;    @Override    public AsyncUncaughtExceptionHandler getAsyncUncaughtExceptionHandler() &#123;        return (ex, method, params) -&gt; &#123;            log.error(&quot;异步任务异常: method=&#123;&#125;, params=&#123;&#125;&quot;, method.getName(),                    Arrays.toString(params), ex);        &#125;;    &#125;&#125;


二、前端传参校验1. 常用参数校验注解


注解
说明
示例



@NotNull
不能为null
@NotNull(message = &quot;姓名不能为空&quot;)


@NotBlank
字符串不能为null且非空白
@NotBlank(message = &quot;密码不能为空&quot;)


@NotEmpty
集合&#x2F;数组不能为null且非空
@NotEmpty(message = &quot;列表不能为空&quot;)


@Size
字符串长度或集合大小范围
@Size(min=6, max=20, message=&quot;密码长度6-20&quot;)


@Min&#x2F;@Max
数字最小&#x2F;最大值
@Min(value=18, message=&quot;年龄最小18&quot;)


@Email
邮箱格式校验
@Email(message=&quot;邮箱格式错误&quot;)


@Pattern
正则表达式校验
@Pattern(regexp=&quot;^1[3-9]\\d{9}$&quot;, message=&quot;手机号格式错误&quot;)


@Valid
嵌套对象校验
@Valid UserDTO user


2. 参数校验示例// DTO@Datapublic class UserCreateDTO &#123;    @NotBlank(message = &quot;姓名不能为空&quot;)    @Size(max = 50, message = &quot;姓名长度不能超过50&quot;)    private String name;    @NotBlank(message = &quot;密码不能为空&quot;)    @Size(min = 6, max = 20, message = &quot;密码长度6-20&quot;)    private String password;    @Email(message = &quot;邮箱格式错误&quot;)    @Size(max = 100, message = &quot;邮箱长度不能超过100&quot;)    private String email;    @Min(value = 18, message = &quot;年龄最小18&quot;)    @Max(value = 150, message = &quot;年龄最大150&quot;)    private Integer age;    @NotEmpty(message = &quot;角色列表不能为空&quot;)    private List&lt;String&gt; roles;    @Valid  // 嵌套校验    private AddressDTO address;&#125;// 嵌套校验对象@Datapublic class AddressDTO &#123;    @NotBlank(message = &quot;省份不能为空&quot;)    private String province;    @NotBlank(message = &quot;城市不能为空&quot;)    private String city;    @NotBlank(message = &quot;详细地址不能为空&quot;)    private String detail;&#125;// Controller@RestController@RequestMapping(&quot;/users&quot;)public class UserController &#123;    @Autowired    private UserService userService;    @PostMapping    public ApiResponse&lt;User&gt; createUser(@Valid @RequestBody UserCreateDTO dto) &#123;        User user = userService.create(dto);        return ApiResponse.success(user);    &#125;    @GetMapping(&quot;/&#123;id&#125;&quot;)    public ApiResponse&lt;User&gt; getUser(@PathVariable @Min(1) Long id) &#123;        User user = userService.findById(id);        return ApiResponse.success(user);    &#125;&#125;

3. 分组校验（同一DTO不同校验规则）// 分组接口public interface Create &#123;&#125;public interface Update &#123;&#125;// DTO分组校验@Datapublic class UserDTO &#123;    @Null(groups = Create.class, message = &quot;创建时ID必须为空&quot;)    @NotNull(groups = Update.class, message = &quot;更新时ID不能为空&quot;)    private Long id;    @NotBlank(groups = &#123;Create.class, Update.class&#125;, message = &quot;姓名不能为空&quot;)    private String name;    @NotBlank(groups = Create.class, message = &quot;创建时密码不能为空&quot;)    private String password;  // 更新时密码可选&#125;// Controller使用分组@PostMappingpublic ApiResponse&lt;User&gt; create(@Validated(Create.class) @RequestBody UserDTO dto) &#123;    return ApiResponse.success(userService.create(dto));&#125;@PutMappingpublic ApiResponse&lt;User&gt; update(@Validated(Update.class) @RequestBody UserDTO dto) &#123;    return ApiResponse.success(userService.update(dto));&#125;

4. 自定义校验注解// 自定义校验注解@Documented@Constraint(validatedBy = PhoneValidator.class)@Target(&#123;ElementType.FIELD, ElementType.PARAMETER&#125;)@Retention(RetentionPolicy.RUNTIME)public @interface Phone &#123;    String message() default &quot;手机号格式错误&quot;;    Class&lt;?&gt;[] groups() default &#123;&#125;;    Class&lt;? extends Payload&gt;[] payload() default &#123;&#125;;&#125;// 校验器实现public class PhoneValidator implements ConstraintValidator&lt;Phone, String&gt; &#123;    private static final Pattern PHONE_PATTERN = Pattern.compile(&quot;^1[3-9]\\d&#123;9&#125;$&quot;);    @Override    public void initialize(Phone constraintAnnotation) &#123;    &#125;    @Override    public boolean isValid(String value, ConstraintValidatorContext context) &#123;        if (value == null || value.isEmpty()) &#123;            return true;  // 空值由@NotBlank处理        &#125;        return PHONE_PATTERN.matcher(value).matches();    &#125;&#125;// 使用@Datapublic class UserDTO &#123;    @Phone(message = &quot;手机号格式错误&quot;)    private String phone;&#125;

5. 手动触发校验// 手动触发校验（在Service层使用）@Servicepublic class UserService &#123;    @Autowired    private Validator validator;    public void validateUser(UserDTO dto) &#123;        Set&lt;ConstraintViolation&lt;UserDTO&gt;&gt; violations = validator.validate(dto);        if (!violations.isEmpty()) &#123;            String message = violations.stream()                .map(ConstraintViolation::getMessage)                .collect(Collectors.joining(&quot;; &quot;));            throw new BusinessException(400, message);        &#125;    &#125;&#125;

6. 全局校验配置@Configurationpublic class ValidationConfig &#123;    /**     * 配置全局校验     */    @Bean    public Validator validator() &#123;        ValidatorFactory factory = Validation.byProvider(HibernateValidator.class)                .configure()                .addProperty(&quot;hibernate.validator.fail_fast&quot;, &quot;false&quot;)  // 校验所有字段                .buildValidatorFactory();        return factory.getValidator();    &#125;&#125;

7. 真实项目中的参数校验问题


问题
现象
解决方法



嵌套对象校验不生效
对象内的字段没加@Valid
嵌套对象必须加@Valid注解


分组校验与@Valid冲突
@Valid不支持分组，导致校验规则不生效
使用@Validated替代@Valid


集合元素校验缺失
List内的DTO字段没有校验
使用@Validated配合List&lt;@Valid UserDTO&gt;


手动构造对象漏校验
Service中new的对象跳过了校验
注入Validator手动触发校验


校验消息国际化
错误消息写死中文，多语言不支持
使用ValidationMessages.properties配置



三、接口请求日志统一打印1. 需求分析需要记录：

请求信息：URL、HTTP方法、请求头、请求参数
响应信息：响应状态码、响应体
性能指标：请求耗时

2. 实现方式方式1：使用拦截器@Slf4j@Componentpublic class RequestLogInterceptor implements HandlerInterceptor &#123;    private static final String START_TIME = &quot;startTime&quot;;    @Override    public boolean preHandle(HttpServletRequest request,                            HttpServletResponse response,                            Object handler) throws Exception &#123;        // 记录开始时间        request.setAttribute(START_TIME, System.currentTimeMillis());        // 记录请求信息        log.info(&quot;========== 请求开始 ==========&quot;);        log.info(&quot;请求方法: &#123;&#125;&quot;, request.getMethod());        log.info(&quot;请求URL: &#123;&#125;&quot;, request.getRequestURI());        log.info(&quot;请求参数: &#123;&#125;&quot;, getRequestParams(request));        return true;    &#125;    @Override    public void afterCompletion(HttpServletRequest request,                               HttpServletResponse response,                               Object handler,                               Exception ex) throws Exception &#123;        // 计算耗时        long startTime = (long) request.getAttribute(START_TIME);        long duration = System.currentTimeMillis() - startTime;        // 记录响应信息        log.info(&quot;响应状态码: &#123;&#125;&quot;, response.getStatus());        log.info(&quot;请求耗时: &#123;&#125;ms&quot;, duration);        log.info(&quot;========== 请求结束 ==========\n&quot;);    &#125;    /**     * 获取请求参数     */    private String getRequestParams(HttpServletRequest request) &#123;        StringBuilder params = new StringBuilder();        // URL参数        Map&lt;String, String[]&gt; parameterMap = request.getParameterMap();        if (!parameterMap.isEmpty()) &#123;            params.append(&quot;URL参数: &quot;).append(parameterMap);        &#125;        // POST请求体（需要包装request）        if (&quot;POST&quot;.equalsIgnoreCase(request.getMethod()) &amp;&amp;            request.getContentType() != null &amp;&amp;            request.getContentType().contains(&quot;application/json&quot;)) &#123;            try &#123;                String body = request.getReader().lines().collect(Collectors.joining());                params.append(&quot;, 请求体: &quot;).append(body);            &#125; catch (IOException e) &#123;                log.warn(&quot;读取请求体失败&quot;, e);            &#125;        &#125;        return params.toString();    &#125;&#125;// 配置@Configurationpublic class WebMvcConfig implements WebMvcConfigurer &#123;    @Autowired    private RequestLogInterceptor requestLogInterceptor;    @Override    public void addInterceptors(InterceptorRegistry registry) &#123;        registry.addInterceptor(requestLogInterceptor)                .addPathPatterns(&quot;/api/**&quot;)                .excludePathPatterns(&quot;/api/health&quot;);    &#125;&#125;

方式2：使用过滤器（支持读取请求体多次）// 请求体包装器public class RequestBodyWrapper extends HttpServletRequestWrapper &#123;    private final byte[] body;    public RequestBodyWrapper(HttpServletRequest request) throws IOException &#123;        super(request);        body = request.getInputStream().readAllBytes();    &#125;    @Override    public ServletInputStream getInputStream() throws IOException &#123;        return new ByteArrayInputStream(body);    &#125;    public String getBody() &#123;        return new String(body, StandardCharsets.UTF_8);    &#125;&#125;// 日志过滤器@Slf4j@Componentpublic class RequestLogFilter implements Filter &#123;    @Override    public void doFilter(ServletRequest request, ServletResponse response,                         FilterChain chain) throws IOException, ServletException &#123;        long startTime = System.currentTimeMillis();        // 包装request以支持多次读取        RequestBodyWrapper wrappedRequest = new RequestBodyWrapper((HttpServletRequest) request);        // 记录请求信息        log.info(&quot;请求: &#123;&#125; &#123;&#125;&quot;, wrappedRequest.getMethod(), wrappedRequest.getRequestURI());        log.info(&quot;参数: &#123;&#125;&quot;, wrappedRequest.getBody());        // 继续执行        chain.doFilter(wrappedRequest, response);        // 记录响应信息        long duration = System.currentTimeMillis() - startTime;        log.info(&quot;响应耗时: &#123;&#125;ms&quot;, duration);    &#125;&#125;

方式3：使用AOP（更灵活）@Slf4j@Aspect@Componentpublic class RequestLogAspect &#123;    @Around(&quot;execution(* com.example.controller..*.*(..))&quot;)    public Object logRequest(ProceedingJoinPoint joinPoint) throws Throwable &#123;        long startTime = System.currentTimeMillis();        // 获取请求信息        HttpServletRequest request = getRequest();        String method = request.getMethod();        String url = request.getRequestURI();        // 获取方法参数        Signature signature = joinPoint.getSignature();        String methodName = signature.getName();        Object[] args = joinPoint.getArgs();        log.info(&quot;请求开始: &#123;&#125; &#123;&#125; [&#123;&#125;]&quot;, method, url, methodName);        log.info(&quot;请求参数: &#123;&#125;&quot;, Arrays.toString(args));        // 执行方法        Object result = null;        try &#123;            result = joinPoint.proceed();            return result;        &#125; finally &#123;            long duration = System.currentTimeMillis() - startTime;            log.info(&quot;请求结束: &#123;&#125; &#123;&#125; [&#123;&#125;] 耗时: &#123;&#125;ms&quot;, method, url, methodName, duration);            log.info(&quot;响应结果: &#123;&#125;&quot;, result != null ? result.toString() : &quot;null&quot;);        &#125;    &#125;    private HttpServletRequest getRequest() &#123;        ServletRequestAttributes attributes =                (ServletRequestAttributes) RequestContextHolder.getRequestAttributes();        return attributes != null ? attributes.getRequest() : null;    &#125;&#125;

3. 敏感信息脱敏// 日志脱敏工具public class SensitiveDataUtils &#123;    private static final Set&lt;String&gt; SENSITIVE_FIELDS = Set.of(        &quot;password&quot;, &quot;pwd&quot;, &quot;token&quot;, &quot;secret&quot;,        &quot;idCard&quot;, &quot;phone&quot;, &quot;mobile&quot;, &quot;bankCard&quot;    );    /**     * JSON字符串脱敏     */    public static String maskSensitive(String json) &#123;        if (json == null || json.isEmpty()) &#123;            return json;        &#125;        try &#123;            ObjectMapper mapper = new ObjectMapper();            Map&lt;String, Object&gt; map = mapper.readValue(json, Map.class);            maskMap(map);            return mapper.writeValueAsString(map);        &#125; catch (Exception e) &#123;            return &quot;***&quot;;        &#125;    &#125;    @SuppressWarnings(&quot;unchecked&quot;)    private static void maskMap(Map&lt;String, Object&gt; map) &#123;        for (Map.Entry&lt;String, Object&gt; entry : map.entrySet()) &#123;            if (SENSITIVE_FIELDS.contains(entry.getKey().toLowerCase())) &#123;                entry.setValue(&quot;***&quot;);            &#125; else if (entry.getValue() instanceof Map) &#123;                maskMap((Map&lt;String, Object&gt;) entry.getValue());            &#125;        &#125;    &#125;&#125;// 在日志切面中使用脱敏log.info(&quot;请求参数: &#123;&#125;&quot;, SensitiveDataUtils.maskSensitive(args.toString()));

4. 日志输出示例========== 请求开始 ==========请求方法: POST请求URL: /api/users请求参数: URL参数: &#123;&#125;, 请求体: &#123;&quot;name&quot;:&quot;张三&quot;,&quot;email&quot;:&quot;test@example.com&quot;,&quot;password&quot;:&quot;***&quot;&#125;========== 请求结束 ==========响应状态码: 201请求耗时: 156ms

5. 三种方式对比


方式
优点
缺点
适用场景



Interceptor
可以获取Handler信息
无法读取请求体（不包装时）
普通请求日志


Filter
可以读取请求体多次
无法获取Handler方法信息
需要记录请求体的场景


AOP
可以获取方法参数和返回值
性能略差、异步请求不适用
需要记录方法细节的场景


6. 真实项目中的日志问题


问题
现象
解决方法



敏感信息泄露
日志中打印了密码、Token
脱敏处理后再打印


大文件请求体OOM
上传文件时读取整个body到内存
判断Content-Type，文件上传跳过body记录


异步请求日志丢失
RequestContextHolder在子线程为null
在主线程手动传递Request属性


日志量过大
高并发下日志文件暴涨
设置日志级别、采样打印（如1%概率）


响应体读取问题
读取后下游获取不到
使用ContentCachingResponseWrapper包装


GET请求参数截断
URL参数过长被截断
限制日志长度，超长截断并标记


7. 文件上传跳过body记录// 文件上传请求跳过body记录@Slf4j@Componentpublic class RequestLogFilter implements Filter &#123;    private static final Set&lt;String&gt; SKIP_CONTENT_TYPES = Set.of(        &quot;multipart/form-data&quot;, &quot;application/octet-stream&quot;    );    @Override    public void doFilter(ServletRequest request, ServletResponse response,                         FilterChain chain) throws IOException, ServletException &#123;        long startTime = System.currentTimeMillis();        HttpServletRequest httpRequest = (HttpServletRequest) request;        String contentType = httpRequest.getContentType();        // 文件上传只记录URL，不记录body        if (contentType != null &amp;&amp; SKIP_CONTENT_TYPES.stream()                .anyMatch(contentType::contains)) &#123;            log.info(&quot;请求: &#123;&#125; &#123;&#125; [文件上传，跳过body记录]&quot;,                    httpRequest.getMethod(), httpRequest.getRequestURI());            chain.doFilter(request, response);        &#125; else &#123;            RequestBodyWrapper wrappedRequest = new RequestBodyWrapper(httpRequest);            log.info(&quot;请求: &#123;&#125; &#123;&#125;&quot;, wrappedRequest.getMethod(), wrappedRequest.getRequestURI());            log.info(&quot;参数: &#123;&#125;&quot;, wrappedRequest.getBody());            chain.doFilter(wrappedRequest, response);        &#125;        long duration = System.currentTimeMillis() - startTime;        log.info(&quot;响应耗时: &#123;&#125;ms&quot;, duration);    &#125;&#125;


四、最佳实践总结


场景
最佳实践



全局异常处理
使用@RestControllerAdvice统一处理，区分业务异常和系统异常


统一响应格式
使用ApiResponse封装，所有接口返回统一结构


参数校验
使用@Valid&#x2F;@Validated + 校验注解，DTO中定义校验规则


分组校验
同一DTO不同场景使用@Validated(Create.class)分组


请求日志
使用Interceptor或AOP，注意脱敏和文件上传跳过


日志级别
业务异常用warn，系统异常用error，请求日志用info


敏感信息
日志中脱敏处理（密码、手机号、Token等）



总结
这三个场景题都是生产环境必备的技能：

全局异常处理：提升用户体验，保护系统安全，统一响应格式
参数校验：避免脏数据进入系统，分组校验适配不同场景
请求日志：便于问题排查和性能监控，注意敏感信息脱敏

前言 高并发高可用是互联网公司面试的重点，尤其是秒杀系统、缓存架构等场景。参与过高并发项目的架构设计和优化，经历过秒杀活动的流量洪峰，这篇文章结合高并发核心原理、实际项目实战经验，整理了高并发最核心的面试题。
高并发高可用核心原理框架流量削峰策略// 流量削峰策略public enum TrafficShapingStrategy &#123; RATE_LIMITING(&quot;限流&quot;, &quot;限制单位时间内请求数&quot;, &quot;令牌桶、漏桶&quot;), CACHE(&quot;缓存&quot;, &quot;热点数据缓存&quot;, &quot;Redis缓存、多级缓存&quot;), ASYNCHRONOUS(&quot;异步化&quot;, &quot;非核心流程异步处理&quot;, &quot;MQ消息队列&quot;), DEGRADATION(&quot;降级&quot;, &quot;非核心功能降级&quot;, &quot;熔断、开关&quot;), QUEUE(&quot;队列缓冲&quot;, &quot;请求排队处理&quot;, &quot;MQ队列&quot;); private final String description; private final String explanation; private final String implementation; TrafficShapingStrategy(String description, String explanation, String implementation) &#123; this.description = description; this.explanation = explanation; this.implementation = implementation; &#125;&#125;
高可用架构// 高可用架构public class HighAvailabilityArchitecture &#123; // 故障转移 public void failover(String serviceName) &#123; ServiceInstance primary = getPrimaryInstance(serviceName); if (!isHealthy(primary)) &#123; ServiceInstance backup = getBackupInstance(serviceName); switchTraffic(serviceName, primary, backup); &#125; &#125; // 负载均衡 public ServiceInstance loadBalance(String serviceName) &#123; List&lt;ServiceInstance&gt; healthyInstances = getHealthyInstances(serviceName); return selectInstance(healthyInstances); &#125; // 健康检查 public boolean isHealthy(ServiceInstance instance) &#123; return instance.isAlive() &amp;&amp; instance.getLatency() &lt; MAX_LATENCY; &#125;&#125;
一、秒杀系统设计1. 秒杀系统架构秒杀系统架构
层级 组件 功能
网关层 Nginx &#x2F; Gateway 限流（限制QPS）、黑白名单、请求分发
缓存层 Redis &#x2F; 本地缓存 库存预减 &#x2F; 热点数据
服务层 秒杀服务 &#x2F; 订单服务 库存校验 &#x2F; 创建订单
数据库层 MySQL &#x2F; MQ队列 扣减库存 &#x2F; 异步下单
2. 核心技术方式方案1：库存预减// 秒杀开始前，将库存加载到Redis@Servicepublic class StockService &#123; @Autowired private StringRedisTemplate redisTemplate; public void loadStockToRedis(Long productId, Integer stock) &#123; redisTemplate.opsForValue().set(&quot;stock:&quot; + productId, stock.toString()); &#125; // 预减库存 public boolean deductStock(Long productId) &#123; String key = &quot;stock:&quot; + productId; Long result = redisTemplate.opsForValue().decrement(key); if (result != null &amp;&amp; result &gt;= 0) &#123; return true; &#125; return false; &#125; // 回滚库存（订单创建失败时） public void rollbackStock(Long productId) &#123; String key = &quot;stock:&quot; + productId; redisTemplate.opsForValue().increment(key); &#125;&#125;
方案2：防超卖// 使用Lua脚本保证原子性public boolean deductStockWithLua(Long productId) &#123; String key = &quot;stock:&quot; + productId; String luaScript = &quot;&quot;&quot; local stock = tonumber(redis.call(&#x27;get&#x27;, KEYS[1])) if stock and stock &gt; 0 then redis.call(&#x27;decr&#x27;, KEYS[1]) return 1 else return 0 end &quot;&quot;&quot;; Long result = redisTemplate.execute( new DefaultRedisScript&lt;&gt;(luaScript, Long.class), List.of(key) ); return result != null &amp;&amp; result == 1;&#125;
方案3：异步下单// 秒杀流程@Servicepublic class SeckillService &#123; @Autowired private StockService stockService; @Autowired private RabbitTemplate rabbitTemplate; public ResponseEntity&lt;&gt; seckill(Long productId, Long userId) &#123; // 1. 校验用户是否已秒杀 if (hasSeckilled(userId, productId)) &#123; return ResponseEntity.badRequest().body(&quot;您已参与过本次秒杀&quot;); &#125; // 2. 预减库存 boolean success = stockService.deductStock(productId); if (!success) &#123; return ResponseEntity.badRequest().body(&quot;库存不足&quot;); &#125; // 3. 发送消息到MQ，异步创建订单 SeckillMessage message = new SeckillMessage(productId, userId); rabbitTemplate.convertAndSend(&quot;seckill-exchange&quot;, &quot;seckill.key&quot;, message); return ResponseEntity.ok(&quot;秒杀成功，正在处理订单...&quot;); &#125;&#125;// MQ消费者@Componentpublic class SeckillConsumer &#123; @RabbitListener(queues = &quot;seckill-queue&quot;) public void handleMessage(SeckillMessage message) &#123; try &#123; // 1. 创建订单 orderService.createOrder(message.getProductId(), message.getUserId()); // 2. 扣减数据库库存 productService.deductStock(message.getProductId()); // 3. 记录秒杀记录 seckillRecordService.save(message); &#125; catch (Exception e) &#123; // 回滚Redis库存 stockService.rollbackStock(message.getProductId()); log.error(&quot;秒杀订单创建失败&quot;, e); &#125; &#125;&#125;
方案4：防作弊// 防作弊校验@Servicepublic class AntiCheatService &#123; @Autowired private StringRedisTemplate redisTemplate; private static final String REQUEST_LIMIT_KEY = &quot;seckill:limit:&quot;; private static final String USER_SECKILL_KEY = &quot;seckill:user:&quot;; public boolean check(Long userId, Long productId) &#123; // 1. 用户是否已秒杀 if (Boolean.TRUE.equals(redisTemplate.hasKey(USER_SECKILL_KEY + userId + &quot;:&quot; + productId))) &#123; return false; &#125; // 2. 请求频率限制（同一用户5秒内最多请求3次） String limitKey = REQUEST_LIMIT_KEY + userId; Long count = redisTemplate.opsForValue().increment(limitKey); if (count != null) &#123; if (count == 1) &#123; redisTemplate.expire(limitKey, 5, TimeUnit.SECONDS); &#125; if (count &gt; 3) &#123; return false; &#125; &#125; // 3. 设备校验（可选） // if (!checkDevice(userId, deviceId)) &#123; // return false; // &#125; return true; &#125;&#125;
二、多级缓存架构1. 缓存架构设计多级缓存架构
层级 组件 功能
客户端缓存 浏览器&#x2F;APP 静态资源缓存、数据缓存（localStorage&#x2F;sessionStorage）
CDN缓存 边缘节点 静态资源加速、边缘节点缓存
反向代理缓存 Nginx 热点页面缓存、响应缓存
服务端缓存 Caffeine &#x2F; Redis &#x2F; 数据库 热点数据 &#x2F; 分布式缓存 &#x2F; 持久化数据
2. 本地缓存// 使用Caffeine作为本地缓存@Configurationpublic class CacheConfig &#123; @Bean public Cache&lt;String, Object&gt; localCache() &#123; return Caffeine.newBuilder() .maximumSize(1000) // 最大缓存数 .expireAfterWrite(5, TimeUnit.MINUTES) // 写入后过期 .expireAfterAccess(3, TimeUnit.MINUTES) // 访问后过期 .recordStats() // 记录统计信息 .build(); &#125;&#125;// 缓存使用@Servicepublic class ProductService &#123; @Autowired private Cache&lt;String, Object&gt; localCache; @Autowired private StringRedisTemplate redisTemplate; @Autowired private ProductMapper productMapper; public Product getProduct(Long id) &#123; String key = &quot;product:&quot; + id; // 1. 先查本地缓存 Object localValue = localCache.getIfPresent(key); if (localValue != null) &#123; return (Product) localValue; &#125; // 2. 再查Redis String redisValue = redisTemplate.opsForValue().get(key); if (redisValue != null) &#123; Product product = JSON.parseObject(redisValue, Product.class); localCache.put(key, product); return product; &#125; // 3. 最后查数据库 Product product = productMapper.selectById(id); if (product != null) &#123; redisTemplate.opsForValue().set(key, JSON.toJSONString(product)); localCache.put(key, product); &#125; return product; &#125;&#125;
3. 热点Key问题// 热点Key解决方案：二级缓存+ 本地缓存@Servicepublic class HotKeyService &#123; @Autowired private Cache&lt;String, Object&gt; localCache; @Autowired private StringRedisTemplate redisTemplate; // 热点Key列表 private static final Set&lt;String&gt; HOT_KEYS = Set.of( &quot;product:1001&quot;, // 爆款商品 &quot;product:1002&quot;, &quot;config:system&quot; // 系统配置 ); public Object getHotData(String key) &#123; // 如果是热点Key，先查本地缓存 if (HOT_KEYS.contains(key)) &#123; Object localValue = localCache.getIfPresent(key); if (localValue != null) &#123; return localValue; &#125; &#125; // 查Redis String value = redisTemplate.opsForValue().get(key); if (value != null) &#123; Object parsedValue = JSON.parse(value); // 热点Key写入本地缓存 if (HOT_KEYS.contains(key)) &#123; localCache.put(key, parsedValue); &#125; return parsedValue; &#125; return null; &#125;&#125;// 热点Key自动发现（基于访问频率）@Servicepublic class HotKeyDetector &#123; @Autowired private StringRedisTemplate redisTemplate; // 每小时检测一次热点Key @Scheduled(fixedRate = 3600000) public void detectHotKeys() &#123; // 统计各Key的访问次数 // 可以通过Redis的incr命令统计 // 将访问量超过1000的Key标记为热点Key &#125;&#125;
三、限流降级熔断1. 限流策略// 基于令牌桶的限流@Componentpublic class RateLimiter &#123; private final Map&lt;String, Bucket&gt; buckets = new ConcurrentHashMap&lt;&gt;(); public boolean tryAcquire(String key, int rate, int burst) &#123; Bucket bucket = buckets.computeIfAbsent(key, k -&gt; Bucket4j.builder() .addLimit(Bandwidth.classic(burst, Refill.greedy(rate, Duration.ofSeconds(1)))) .build()); return bucket.tryConsume(1); &#125;&#125;// 使用限流@RestControllerpublic class OrderController &#123; @Autowired private RateLimiter rateLimiter; @PostMapping(&quot;/orders&quot;) public ResponseEntity&lt;&gt; createOrder(@RequestBody OrderDTO dto) &#123; String key = &quot;order:&quot; + dto.getUserId(); // 限流：每个用户每秒最多创建5个订单 if (!rateLimiter.tryAcquire(key, 1, 5)) &#123; return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS) .body(&quot;操作太频繁，请稍后重试&quot;); &#125; Order order = orderService.create(dto); return ResponseEntity.ok(order); &#125;&#125;
2. 降级策略// 服务降级配置@Servicepublic class DegradeService &#123; @Autowired private UserServiceClient userService; @Autowired private OrderServiceClient orderService; // 核心服务：不降级 public User getUser(Long userId) &#123; return userService.getUser(userId); &#125; // 非核心服务：可降级 @SentinelResource(value = &quot;statistics&quot;, fallback = &quot;fallbackStatistics&quot;) public StatisticsDTO getStatistics(Long userId) &#123; return statisticsService.getStatistics(userId); &#125; public StatisticsDTO fallbackStatistics(Long userId, Throwable e) &#123; // 返回降级数据 StatisticsDTO dto = new StatisticsDTO(); dto.setUserId(userId); dto.setMessage(&quot;统计服务暂时不可用&quot;); return dto; &#125;&#125;// 业务降级示例public void processOrder(OrderDTO dto) &#123; try &#123; // 核心流程 orderService.createOrder(dto); inventoryService.deductStock(dto); paymentService.pay(dto); // 非核心流程：可降级 try &#123; notificationService.sendNotify(dto); &#125; catch (Exception e) &#123; log.warn(&quot;发送通知失败，已降级处理&quot;, e); &#125; try &#123; statisticsService.recordOrder(dto); &#125; catch (Exception e) &#123; log.warn(&quot;记录统计失败，已降级处理&quot;, e); &#125; &#125; catch (Exception e) &#123; // 核心流程失败，需要回滚 throw new BusinessException(&quot;订单创建失败&quot;, e); &#125;&#125;
四、灰度发布1. 灰度发布策略灰度发布流程
阶段 旧版（v1.0） 新版（v2.0）
全量发布 100%用户 -
灰度阶段1 90%用户 10%用户
灰度阶段2 50%用户 50%用户
全量切换 - 100%用户
2. 灰度发布实现// 基于用户ID的灰度路由@Configurationpublic class GrayConfig &#123; @Bean public RouteLocator grayRouteLocator(RouteLocatorBuilder builder) &#123; return builder.routes() .route(&quot;gray-route&quot;, r -&gt; r .path(&quot;/api/**&quot;) .filters(f -&gt; f.filter(new GrayFilter())) .uri(&quot;lb://user-service&quot;)) .build(); &#125;&#125;// 灰度过滤器public class GrayFilter implements GatewayFilter &#123; @Autowired private GrayConfig grayConfig; @Override public Mono&lt;Void&gt; filter(ServerWebExchange exchange, GatewayFilterChain chain) &#123; String userId = exchange.getRequest().getHeaders().getFirst(&quot;X-User-Id&quot;); // 判断用户是否在灰度名单中 if (isGrayUser(userId)) &#123; exchange.getRequest().mutate() .header(&quot;X-Gray-Enabled&quot;, &quot;true&quot;) .build(); &#125; return chain.filter(exchange); &#125; private boolean isGrayUser(String userId) &#123; // 可以从配置中心获取灰度用户列表 // 或者基于用户ID的哈希值进行分析 if (userId == null) return false; // 简单示例：用户ID尾号为0的进入灰度 return userId.endsWith(&quot;0&quot;); &#125;&#125;// 服务端灰度判断@RestControllerpublic class UserController &#123; @Value(&quot;$&#123;server.version&#125;&quot;) private String version; @GetMapping(&quot;/users/&#123;id&#125;&quot;) public ResponseEntity&lt;UserDTO&gt; getUser(@PathVariable Long id, @RequestHeader(value = &quot;X-Gray-Enabled&quot;, required = false) String grayEnabled) &#123; log.info(&quot;UserService version: &#123;&#125;, Gray enabled: &#123;&#125;&quot;, version, grayEnabled); User user = userService.getById(id); return ResponseEntity.ok(convertToDTO(user)); &#125;&#125;
3. 灰度发布的价值和风险
维度 价值 风险
用户体验 逐步发布，降低影响范围 部分用户可能遇到问题
问题发现 早期发现问题，快速回滚 问题可能影响部分用户
性能测试 在真实流量下测试 可能影响系统稳定性
业务验证 验证新功能效果 功能不符合预期
五、性能测试与监控1. 秒杀系统性能测试/** * 秒杀系统压测结果 */public class SeckillPerformanceTest &#123; /** * 压测场景：10万用户同时抢购1000件商品 */ @Test public void testSeckillPerformance() &#123; // 压测结果： // QPS: 50000 // 成功率: 99.9% // 平均响应时间: 50ms // P99响应时间: 150ms // 数据库QPS: 1000 (异步下单后) &#125;&#125;/** * 性能对比表 */// | 方案 | QPS | 成功率 | 平均响应时间 | 数据库QPS |// |------|-----|--------|--------------|-----------|// | 裸奔(直接DB) | 500 | 95% | 2000ms | 1000 |// | Redis缓存 | 2000 | 98% | 500ms | 500 |// | 完整版(多级缓存+MQ) | 50000 | 99.9% | 50ms | 100 |
2. 限流效果测试/** * 限流效果测试 */@Servicepublic class RateLimitTest &#123; /** * 测试令牌桶限流效果 */ @Test public void testTokenBucket() &#123; RateLimiter limiter = new RateLimiter(); // 设置限流：每秒1000个请求，桶容量5000 int successCount = 0; int failCount = 0; for (int i = 0; i &lt; 10000; i++) &#123; if (limiter.tryAcquire(&quot;test&quot;, 1000, 5000)) &#123; successCount++; &#125; else &#123; failCount++; &#125; &#125; // 结果：约1000个成功，9000个失败（1秒内） System.out.println(&quot;成功: &quot; + successCount + &quot;, 失败: &quot; + failCount); &#125;&#125;
3. 监控指标/** * 高并发系统监控指标 */@Componentpublic class HighConcurrencyMetrics &#123; private final Counter requestCounter; private final Counter successCounter; private final Counter failCounter; private final Timer latencyTimer; private final Gauge stockGauge; private final Gauge cacheHitRateGauge; private final Gauge rateLimitRejectGauge; public HighConcurrencyMetrics(MeterRegistry registry) &#123; this.requestCounter = Counter.builder(&quot;hc_request_total&quot;) .description(&quot;请求总数&quot;) .register(registry); this.successCounter = Counter.builder(&quot;hc_success_total&quot;) .description(&quot;成功请求数&quot;) .register(registry); this.failCounter = Counter.builder(&quot;hc_fail_total&quot;) .description(&quot;失败请求数&quot;) .tag(&quot;reason&quot;, &quot;unknown&quot;) .register(registry); this.latencyTimer = Timer.builder(&quot;hc_request_latency&quot;) .description(&quot;请求延迟&quot;) .register(registry); this.stockGauge = Gauge.builder(&quot;hc_stock_remaining&quot;) .description(&quot;剩余库存&quot;) .register(registry); this.cacheHitRateGauge = Gauge.builder(&quot;hc_cache_hit_rate&quot;) .description(&quot;缓存命中率&quot;) .register(registry); this.rateLimitRejectGauge = Gauge.builder(&quot;hc_rate_limit_reject&quot;) .description(&quot;限流拒绝数&quot;) .register(registry); &#125; public void recordRequest() &#123; requestCounter.increment(); &#125; public void recordSuccess() &#123; successCounter.increment(); &#125; public void recordFail(String reason) &#123; failCounter.increment(); &#125; public void recordLatency(long millis) &#123; latencyTimer.record(millis, TimeUnit.MILLISECONDS); &#125; public void setStock(int stock) &#123; stockGauge.set(stock); &#125;&#125;
4. 告警规则# Prometheus告警规则groups:- name: high-concurrency-alerts rules: - alert: HighRequestRate expr: rate(hc_request_total[1m]) &gt; 10000 for: 1m labels: severity: warning annotations: summary: &quot;请求量过高&quot; description: &quot;当前QPS: &#123;&#123; $value &#125;&#125;&quot; - alert: LowSuccessRate expr: hc_success_total / hc_request_total &lt; 0.99 for: 1m labels: severity: critical annotations: summary: &quot;成功率过低&quot; description: &quot;成功率: &#123;&#123; $value &#125;&#125;&quot; - alert: HighLatency expr: avg(hc_request_latency_seconds) &gt; 1 for: 1m labels: severity: warning annotations: summary: &quot;响应时间过高&quot; description: &quot;平均延迟: &#123;&#123; $value &#125;&#125;s&quot; - alert: StockLow expr: hc_stock_remaining &lt; 100 for: 0m labels: severity: info annotations: summary: &quot;库存不足&quot; description: &quot;剩余库存: &#123;&#123; $value &#125;&#125;&quot; - alert: HighRateLimitReject expr: rate(hc_rate_limit_reject[1m]) &gt; 1000 for: 1m labels: severity: warning annotations: summary: &quot;限流拒绝过多&quot; description: &quot;拒绝数: &#123;&#123; $value &#125;&#125;&quot;
六、常见问题排查1. 秒杀超卖问题// 问题：库存扣减后订单创建失败，导致库存不一致// 排查步骤：// 1. 检查Redis和数据库库存是否一致// 2. 检查MQ消费是否有失败// 3. 检查异常处理是否正确回滚// 解决方案：@Servicepublic class StockConsistencyChecker &#123; @Scheduled(cron = &quot;0 */5 * * * ?&quot;) public void checkStockConsistency() &#123; // 对比Redis和数据库库存 List&lt;Long&gt; productIds = productMapper.selectActiveProductIds(); for (Long productId : productIds) &#123; Integer redisStock = getRedisStock(productId); Integer dbStock = getDbStock(productId); if (!redisStock.equals(dbStock)) &#123; log.warn(&quot;库存不一致: productId=&#123;&#125;, redis=&#123;&#125;, db=&#123;&#125;&quot;, productId, redisStock, dbStock); // 以数据库为准修正Redis redisTemplate.opsForValue().set(&quot;stock:&quot; + productId, dbStock.toString()); &#125; &#125; &#125;&#125;
2. 缓存击穿问题// 问题：热点Key过期瞬间，大量请求穿透到数据库// 排查步骤：// 1. 检查缓存过期时间设置// 2. 检查热点Key列表// 3. 检查本地缓存配置// 解决方案：@Servicepublic class CacheBreakdownHandler &#123; @Autowired private Cache&lt;String, Object&gt; localCache; @Autowired private StringRedisTemplate redisTemplate; public Object getWithLock(String key) &#123; // 1. 先查本地缓存 Object localValue = localCache.getIfPresent(key); if (localValue != null) &#123; return localValue; &#125; // 2. 分布式锁防止并发穿透 String lockKey = &quot;lock:cache:&quot; + key; RLock lock = redissonClient.getLock(lockKey); try &#123; if (lock.tryLock(3, 10, TimeUnit.SECONDS)) &#123; // 双重检查 localValue = localCache.getIfPresent(key); if (localValue != null) &#123; return localValue; &#125; // 查Redis String redisValue = redisTemplate.opsForValue().get(key); if (redisValue != null) &#123; Object parsedValue = JSON.parse(redisValue); localCache.put(key, parsedValue); return parsedValue; &#125; // 查数据库（限流保护） if (!dbRateLimiter.tryAcquire()) &#123; throw new BusinessException(&quot;系统繁忙&quot;); &#125; Object dbValue = loadFromDb(key); if (dbValue != null) &#123; redisTemplate.opsForValue().set(key, JSON.toJSONString(dbValue), 30, TimeUnit.MINUTES); localCache.put(key, dbValue); &#125; return dbValue; &#125; else &#123; // 获取锁失败，返回空或默认值 return null; &#125; &#125; finally &#123; lock.unlock(); &#125; &#125;&#125;
3. 限流绕过问题// 问题：恶意用户绕过限流// 排查步骤：// 1. 检查限流Key是否正确// 2. 检查是否有IP伪造// 3. 检查是否有请求频率异常// 解决方案：@Servicepublic class AdvancedRateLimiter &#123; @Autowired private StringRedisTemplate redisTemplate; /** * 多维度限流 */ public boolean tryAcquire(String userId, String ip, String deviceId) &#123; // 用户维度限流 boolean userLimit = checkLimit(&quot;rate:user:&quot; + userId, 10, 60); // IP维度限流 boolean ipLimit = checkLimit(&quot;rate:ip:&quot; + ip, 100, 60); // 设备维度限流 boolean deviceLimit = checkLimit(&quot;rate:device:&quot; + deviceId, 10, 60); return userLimit &amp;&amp; ipLimit &amp;&amp; deviceLimit; &#125; private boolean checkLimit(String key, int limit, int seconds) &#123; Long count = redisTemplate.opsForValue().increment(key); if (count == 1) &#123; redisTemplate.expire(key, seconds, TimeUnit.SECONDS); &#125; return count &lt;= limit; &#125;&#125;
七、生产环境配置1. Nginx限流配置http &#123; # 限流配置 limit_req_zone $binary_remote_addr zone=seckill:10m rate=1000r/s; server &#123; location /api/seckill &#123; # 限流：每秒1000个请求，桶容量5000 limit_req zone=seckill burst=5000 nodelay; # 连接数限制 limit_conn seckill_conn 1000; proxy_pass http://seckill-service; &#125; &#125;&#125;
2. Redis集群配置@Configurationpublic class RedisClusterConfig &#123; @Bean public RedissonClient redissonClient() &#123; Config config = new Config(); config.useClusterServers() .addNodeAddress( &quot;redis://redis-0:6379&quot;, &quot;redis://redis-1:6379&quot;, &quot;redis://redis-2:6379&quot; ) .setMasterConnectionPoolSize(100) .setSlaveConnectionPoolSize(100) .setConnectTimeout(10000) .setRetryAttempts(3) .setRetryInterval(1500); return Redisson.create(config); &#125;&#125;
3. 线程池配置@Configurationpublic class ThreadPoolConfig &#123; @Bean public ThreadPoolExecutor seckillThreadPool() &#123; return new ThreadPoolExecutor( 10, // corePoolSize 50, // maximumPoolSize 60, // keepAliveTime TimeUnit.SECONDS, new LinkedBlockingQueue&lt;&gt;(10000), // workQueue new ThreadFactoryBuilder().setNameFormat(&quot;seckill-%d&quot;).build(), new ThreadPoolExecutor.CallerRunsPolicy() // 拒绝策略 ); &#125;&#125;
八、面试加分点1. 秒杀系统优化路径秒杀系统优化演进：V1.0 裸奔版 → 直接操作数据库 → QPS: 500V2.0 缓存版 → Redis预减库存 → QPS: 2000V3.0 异步版 → MQ异步下单 → QPS: 10000V4.0 完整版 → 多级缓存+限流+异步 → QPS: 50000
2. 高并发设计原则高并发设计原则：1. 削峰填谷：使用MQ异步处理2. 多级缓存：本地缓存+分布式缓存3. 读写分离：主库写，从库读4. 分库分表：数据水平拆分5. 服务降级：非核心服务降级6. 熔断限流：保护系统不被压垮7. 灰度发布：降低发布风险8. 监控告警：实时发现问题
3. 热点Key解决方案总结热点Key解决方案：1. 本地缓存：Caffeine缓存热点数据2. 二级缓存：Redis + 本地缓存3. 热点预热：系统启动时加载热点数据4. 自动发现：基于访问频率识别热点Key5. 数据分片：将热点数据分散到多个节点6. CDN加速：静态资源使用CDN
总结 高并发高可用是互联网公司的核心竞争力，掌握这些知识不仅能应对面试，还能设计出稳定的高并发系统。核心要点：
秒杀系统：库存预减、异步下单、防超卖、防作弊 多级缓存：本地缓存分布式缓存、热点Key处理 限流降级：令牌桶限流、业务降级、非核心服务降级 灰度发布：基于用户的路由策略、价值和风险评估 监控告警：完善的指标监控和告警机制 问题排查：快速定位和解决生产问题
这些都是面试中高频问到的问题，一定要深入理解并能说出落地实现。在实际项目中，需要根据业务场景选择合适的技术方案，平衡性能、可用性和成本。

前言在实际场景中，我们采用微服务架构拆分了多个核心业务域——矿车调度、设备管理、人员定位、安全告警、物资管理等，各服务独立部署、独立数据库。随着业务复杂度的增长，跨服务的数据一致性成为最棘手的问题：矿车调拨需要同时更新调度服务与设备服务的状态，物资出库需要同步更新库存与领用记录，安全告警触发需要联动设备控制与人员通知。2024年初，我们引入 Seata AT 模式作为分布式事务的解决方案，一阶段业务数据和 undo_log 在同一个本地事务中提交，二阶段提交只需异步删除 undo_log，回滚则根据 undo_log 反向补偿，对业务代码几乎零侵入。但生产上线后问题不断：全局锁冲突导致超时、undo_log 膨胀、回滚失败需人工介入……带着这些问题深入源码，才真正理解 Seata AT 模式的精妙设计与局限所在。本文将从架构总览、核心流程、全局事务提交、全局事务回滚、undo_log 机制、全局锁机制等维度，逐层剥开源码，力求讲透每一个关键设计决策。
Seata AT 模式架构总览核心角色与交互Seata AT 模式的整体架构由三个核心角色组成：TC（Transaction Coordinator，事务协调者）、TM（Transaction Manager，事务管理器）、RM（Resource Manager，资源管理器）。 架构流程： flowchart TD N1[&quot;Seata AT 模式架构 注册&quot;] N2[&quot;TM&quot;] N3[&quot;TC (事务管理器)&quot;] N4[&quot;(事务协调者)&quot;] N5[&quot;提交&quot;] N6[&quot;回滚 TM TC (事务管理器) (事务协调者)&quot;] N7[&quot;RM (资源管理器) 代理数据源 锁申请结果&quot;] N8[&quot;回滚指令 生成undo 执行补偿&quot;] N9[&quot;GlobalTransact&quot;] N10[&quot;GlobalSession&quot;] N11[&quot;DataSourceProxy&quot;] N12[&quot;BranchSession&quot;] N13[&quot;undo_log undo_log&quot;] N14[&quot;LockManager 执行反向SQL&quot;] N1 --&gt; N2 N1 --&gt; N3 N1 --&gt; N4 N5 --&gt; N2 N5 --&gt; N3 N5 --&gt; N4 N6 --&gt; N2 N6 --&gt; N3 N6 --&gt; N4 N2 --&gt; N7 N2 --&gt; N8 N3 --&gt; N7 N3 --&gt; N8 N4 --&gt; N7 N4 --&gt; N8 N7 --&gt; N9 N7 --&gt; N10 N7 --&gt; N11 N7 --&gt; N12 N7 --&gt; N13 N7 --&gt; N14 N8 --&gt; N9 N8 --&gt; N10 N8 --&gt; N11 N8 --&gt; N12 N8 --&gt; N13 N8 --&gt; N14
三个核心角色的职责
角色 全称 职责 实际项目中的映射
TC Transaction Coordinator 维护全局事务和分支事务的状态，驱动全局提交或回滚，管理全局锁 独立部署的 Seata Server（seata-server-1.7.1）
TM Transaction Manager 定义全局事务的范围，开启全局事务、提交或回滚全局事务 矿车调度服务中的 @GlobalTransactional 注解标注的方法
RM Resource Manager 控制分支事务，向 TC 注册分支事务，管理分支事务的资源，报告分支事务状态 各微服务中的 DataSourceProxy，负责拦截 SQL、生成 undo_log、执行回滚
AT 模式两阶段提交总览架构流程： flowchart TD N1[&quot;AT 模式两阶段提交流程&quot;] N2[&quot;Before Image 3.&quot;] N3[&quot;执行业务SQL 4. 查询修改后数据&quot;] N4[&quot;一阶段Branch&quot;] N5[&quot;Commit&quot;] N6[&quot;1. 拦截业务SQL 2.&quot;] N7[&quot;查询修改前数据&quot;] N8[&quot;申请全局锁 7. 本地事务提交&quot;] N9[&quot;释放本地锁但全局锁仍持有&quot;] N10[&quot;是 否&quot;] N11[&quot;二阶段提交&quot;] N12[&quot;二阶段回滚 异步删除 根据&quot;] N13[&quot;Before undo_log&quot;] N14[&quot;Image 生成 反向SQL执行&quot;] N15[&quot;释放全局锁 删除 undo_log&quot;] N16[&quot;释放全局锁&quot;] N17[&quot;是 否 二阶段提交&quot;] N18[&quot;二阶段回滚&quot;] N19[&quot;异步删除 根据 Before&quot;] N20[&quot;undo_log Image 生成&quot;] N21[&quot;反向SQL执行 释放全局锁 删除&quot;] N22[&quot;undo_log 释放全局锁&quot;] N1 --&gt; N2 N1 --&gt; N3 N4 --&gt; N2 N4 --&gt; N3 N5 --&gt; N2 N5 --&gt; N3 N6 --&gt; N2 N6 --&gt; N3 N7 --&gt; N2 N7 --&gt; N3 N2 --&gt; N8 N2 --&gt; N9 N3 --&gt; N8 N3 --&gt; N9 N8 --&gt; N6 N8 --&gt; N7 N9 --&gt; N6 N9 --&gt; N7 N8 --&gt; N10 N8 --&gt; N11 N8 --&gt; N12 N8 --&gt; N13 N8 --&gt; N14 N8 --&gt; N15 N8 --&gt; N16 N9 --&gt; N10 N9 --&gt; N11 N9 --&gt; N12 N9 --&gt; N13 N9 --&gt; N14 N9 --&gt; N15 N9 --&gt; N16 N10 --&gt; N17 N10 --&gt; N18 N10 --&gt; N19 N10 --&gt; N20 N10 --&gt; N21 N10 --&gt; N22 N11 --&gt; N17 N11 --&gt; N18 N11 --&gt; N19 N11 --&gt; N20 N11 --&gt; N21 N11 --&gt; N22 N12 --&gt; N17 N12 --&gt; N18 N12 --&gt; N19 N12 --&gt; N20 N12 --&gt; N21 N12 --&gt; N22 N13 --&gt; N17 N13 --&gt; N18 N13 --&gt; N19 N13 --&gt; N20 N13 --&gt; N21 N13 --&gt; N22 N14 --&gt; N17 N14 --&gt; N18 N14 --&gt; N19 N14 --&gt; N20 N14 --&gt; N21 N14 --&gt; N22 N15 --&gt; N17 N15 --&gt; N18 N15 --&gt; N19 N15 --&gt; N20 N15 --&gt; N21 N15 --&gt; N22 N16 --&gt; N17 N16 --&gt; N18 N16 --&gt; N19 N16 --&gt; N20 N16 --&gt; N21 N16 --&gt; N22 N17 --&gt; N19 N17 --&gt; N20 N17 --&gt; N21 N17 --&gt; N22 N18 --&gt; N19 N18 --&gt; N20 N18 --&gt; N21 N18 --&gt; N22 N19 --&gt; N20 N19 --&gt; N21 N19 --&gt; N22 N20 --&gt; N19 N20 --&gt; N21 N20 --&gt; N22 N21 --&gt; N19 N21 --&gt; N20 N21 --&gt; N22 N22 --&gt; N19 N22 --&gt; N20 N22 --&gt; N21
AT 模式 vs TCC 模式 vs Saga 模式
对比维度 AT 模式 TCC 模式 Saga 模式
侵入性 低（仅代理数据源） 高（需编写 try&#x2F;confirm&#x2F;cancel） 中（需编写补偿逻辑）
一致性 强一致（全局锁保证） 强一致（业务层保证） 最终一致
性能 一阶段提交本地事务，二阶段异步删除 两阶段均需远程调用 长事务，无锁等待
适用场景 关系型数据库，SQL 可自动解析 非关系型存储，需业务定制 长流程业务编排
回滚机制 根据 undo_log 自动反向补偿 业务自定义 cancel 逻辑 正向&#x2F;反向补偿流程
隔离性 全局锁保证读已提交 业务层隔离 无隔离（脏读可能）
智慧矿山应用 矿车调拨、物资出库 设备状态变更（Redis+DB混合存储） 安全告警联动流程
@GlobalTransactional 入口源码分析注解定义与属性// @GlobalTransactional 注解定义@Retention(RetentionPolicy.RUNTIME)@Target(&#123;ElementType.METHOD, ElementType.TYPE&#125;)@Inheritedpublic @interface GlobalTransactional &#123; /** * 全局事务超时时间（毫秒），默认60秒 * 在实际场景中，矿车调拨涉及3个服务调用，设置120秒 */ int timeoutMills() default 60000; /** * 全局事务名称，用于标识事务用途 * 建议格式：业务域-操作名，如 &quot;minecart-allocate&quot; */ String name() default &quot;&quot;; /** * 回滚异常类，默认所有异常都回滚 */ Class&lt;? extends Throwable&gt;[] rollbackFor() default &#123;&#125;; /** * 不回滚的异常类 */ Class&lt;? extends Throwable&gt;[] noRollbackFor() default &#123;&#125;;&#125;
GlobalTransactionalInterceptor 拦截器Seata 通过 AOP 拦截 @GlobalTransactional 注解标注的方法，将业务逻辑包装在全局事务模板中执行。 // GlobalTransactionalInterceptor 拦截器核心源码public class GlobalTransactionalInterceptor implements MethodInterceptor &#123; private final TransactionalTemplate transactionalTemplate = new TransactionalTemplate(); @Override public Object invoke(MethodInvocation methodInvocation) throws Throwable &#123; Method method = methodInvocation.getMethod(); GlobalTransactional anno = method.getAnnotation(GlobalTransactional.class); if (anno != null) &#123; return handleGlobalTransaction(methodInvocation, anno); &#125; return methodInvocation.proceed(); &#125; private Object handleGlobalTransaction(MethodInvocation invocation, GlobalTransactional anno) throws Throwable &#123; return transactionalTemplate.execute(new TransactionalExecutor() &#123; @Override public Object execute() throws Throwable &#123; return invocation.proceed(); &#125; @Override public TransactionInfo getTransactionInfo() &#123; TransactionInfo info = new TransactionInfo(); info.setTimeOut(anno.timeoutMills()); info.setName(anno.name()); info.setRollbackFor(anno.rollbackFor()); info.setNoRollbackFor(anno.noRollbackFor()); return info; &#125; &#125;); &#125;&#125;
TransactionalTemplate 全局事务模板TransactionalTemplate 是 Seata 全局事务的核心编排器，它定义了全局事务的标准执行流程——开启、执行、提交或回滚。 // TransactionalTemplate.execute() 核心流程public Object execute(TransactionalExecutor business) throws Throwable &#123; // 1. 获取事务信息 TransactionInfo txInfo = business.getTransactionInfo(); // 2. 获取或创建全局事务 GlobalTransaction tx = GlobalTransactionContext.getCurrentOrCreate(); // 3. 开启全局事务 → 向 TC 注册，获取 XID beginTransaction(txInfo, tx); Object rs = null; try &#123; // 4. 执行业务逻辑 → RM 自动注册分支事务 rs = business.execute(); &#125; catch (Throwable ex) &#123; // 5. 业务异常 → 根据异常类型决定回滚或提交 completeTransactionAfterThrowing(txInfo, tx, ex); throw ex; &#125; // 6. 业务成功 → 提交全局事务 commitTransaction(tx, txInfo); return rs;&#125;private void beginTransaction(TransactionInfo txInfo, GlobalTransaction tx) throws TransactionalExecutor.ExecutionException &#123; try &#123; // 向 TC 发送 Begin 请求，获取 XID tx.begin(txInfo.getTimeOut(), txInfo.getName()); // 将 XID 绑定到当前线程 RootContext.bind(tx.getXid()); &#125; catch (TransactionException txe) &#123; throw new TransactionalExecutor.ExecutionException(tx, txe, TransactionalExecutor.Code.BeginFailure); &#125;&#125;private void commitTransaction(GlobalTransaction tx, TransactionInfo txInfo) throws TransactionalExecutor.ExecutionException &#123; try &#123; tx.commit(); &#125; catch (TransactionException txe) &#123; throw new TransactionalExecutor.ExecutionException(tx, txe, TransactionalExecutor.Code.CommitFailure); &#125; finally &#123; triggerAfterCompletion(); cleanUp(); &#125;&#125;private void completeTransactionAfterThrowing(TransactionInfo txInfo, GlobalTransaction tx, Throwable originalException) throws TransactionalExecutor.ExecutionException &#123; if (txInfo != null &amp;&amp; txInfo.rollbackOn(originalException)) &#123; try &#123; tx.rollback(); &#125; catch (TransactionException txe) &#123; throw new TransactionalExecutor.ExecutionException(tx, txe, TransactionalExecutor.Code.RollbackFailure, originalException); &#125; &#125; else &#123; commitTransaction(tx, txInfo); &#125;&#125;
全局事务开启时序TM (矿车调度服务) TC (Seata Server) │ │ │ 1.@GlobalTransactional 拦截 │ │ 2.beginTransaction() │ │ ────── GlobalBeginRequest ────────► │ │ (timeout=120000, │ │ name=&quot;minecart-allocate&quot;) │ │ │ 3.创建 GlobalSession │ │ 4.生成 XID │ │ 如: 192.168.1.10:8091:1234567890 │ ◄──── GlobalBeginResponse ──────── │ │ (xid, status=Begin) │ │ │ │ 5.RootContext.bind(xid) │ │ │ │ 6.执行业务逻辑(RM注册分支) │ │ │
数据源代理与 undo_log 生成DataSourceProxy 代理链Seata AT 模式通过代理 JDBC 核心组件来拦截 SQL 执行，自动生成 undo_log。 原始 JDBC 调用链： DataSource → Connection → PreparedStatement → execute()Seata AT 代理调用链： DataSourceProxy → ConnectionProxy → PreparedStatementProxy → execute() │ │ │ │ │ └─ 拦截 SQL 执行 │ └─ 管理本地事务提交/回滚 └─ 创建代理 Connection 核心执行链路： PreparedStatementProxy.execute() → ExecuteTemplate.execute() → 判断是否在全局事务中 (RootContext.inGlobalTransaction()) → 否：直接执行原始 SQL → 是：走 AT 模式逻辑 → BaseTransactionalExecutor.execute() → AbstractDMLExecutor.executeAutoCommitFalse() / executeAutoCommitTrue()
ExecuteTemplate 执行模板// ExecuteTemplate 拦截 SQL 执行的核心入口public class ExecuteTemplate &#123; public static &lt;T, S extends Statement&gt; T execute(List&lt;SQLRecognizer&gt; sqlRecognizers, StatementProxy&lt;S&gt; statementProxy, StatementCallback&lt;T, S&gt; statementCallback, Object... args) throws SQLException &#123; if (!RootContext.inGlobalTransaction() &amp;&amp; !RootContext.requireGlobalLock()) &#123; return statementCallback.execute(statementProxy.getTargetStatement(), args); &#125; if (sqlRecognizers == null) &#123; sqlRecognizers = SQLVisitorFactory.get( statementProxy.getTargetSQL(), statementProxy.getTargetStatement().getConnection().getMetaData().getDatabaseProductName()); &#125; Executor&lt;T&gt; executor; if (sqlRecognizers == null || sqlRecognizers.isEmpty()) &#123; executor = new PlainExecutor(statementProxy, statementCallback); &#125; else &#123; if (sqlRecognizers.size() == 1) &#123; SQLRecognizer sqlRecognizer = sqlRecognizers.get(0); switch (sqlRecognizer.getSQLType()) &#123; case INSERT: executor = new InsertExecutor&lt;&gt;(sqlRecognizers, statementProxy, statementCallback, args); break; case UPDATE: executor = new UpdateExecutor&lt;&gt;(sqlRecognizers, statementProxy, statementCallback, args); break; case DELETE: executor = new DeleteExecutor&lt;&gt;(sqlRecognizers, statementProxy, statementCallback, args); break; case SELECT_FOR_UPDATE: executor = new SelectForUpdateExecutor&lt;&gt;(sqlRecognizers, statementProxy, statementCallback, args); break; default: executor = new PlainExecutor(statementProxy, statementCallback); break; &#125; &#125; else &#123; executor = new MultiExecutor&lt;&gt;(sqlRecognizers, statementProxy, statementCallback, args); &#125; &#125; return executor.execute(); &#125;&#125;
AbstractDMLExecutor——Before&#x2F;After Image 生成public abstract class AbstractDMLExecutor&lt;T, S extends Statement&gt; extends BaseTransactionalExecutor &#123; @Override public T doExecute(Object... args) throws Throwable &#123; AbstractConnectionProxy connectionProxy = statementProxy.getConnectionProxy(); if (connectionProxy.getAutoCommit()) &#123; return executeAutoCommitTrue(args); &#125; else &#123; return executeAutoCommitFalse(args); &#125; &#125; /** * 自动提交模式下的执行流程 * 关键：先关闭自动提交，生成 undo_log 后一起提交 */ protected T executeAutoCommitTrue(Object[] args) throws Throwable &#123; ConnectionProxy connectionProxy = statementProxy.getConnectionProxy(); connectionProxy.setAutoCommit(false); try &#123; return executeAutoCommitFalse(args); &#125; catch (Exception e) &#123; throw e; &#125; finally &#123; try &#123; connectionProxy.setAutoCommit(true); &#125; catch (SQLException ex) &#123; log.warn(&quot;set auto commit back to true failed&quot;, ex); &#125; &#125; &#125; /** * 手动提交模式下的核心流程——AT 模式的精髓所在 * 1. 查询 Before Image * 2. 执行业务 SQL * 3. 查询 After Image * 4. 生成 undo_log * 5. 注册分支事务 + 申请全局锁 * 6. 本地事务提交（业务数据 + undo_log 一起提交） */ protected T executeAutoCommitFalse(Object[] args) throws Exception &#123; // Step 1: 查询修改前数据（Before Image） TableRecords beforeImage = beforeImage(); // Step 2: 执行业务 SQL T result = statementCallback.execute(statementProxy.getTargetStatement(), args); // Step 3: 查询修改后数据（After Image） TableRecords afterImage = afterImage(beforeImage); // Step 4: 生成 undo_log 并保存到本地事务中 prepareUndoLog(beforeImage, afterImage); return result; &#125;&#125;
Before Image 与 After Image 的查询逻辑以 UpdateExecutor 为例： public class UpdateExecutor&lt;T, S extends Statement&gt; extends AbstractDMLExecutor&lt;T, S&gt; &#123; @Override protected TableRecords beforeImage() throws SQLException &#123; SQLUpdateRecognizer recognizer = (SQLUpdateRecognizer) sqlRecognizer; String whereCondition = recognizer.getWhereCondition(); // 构造 SELECT 语句查询修改前的数据 // 原始SQL: UPDATE minecart SET status = &#x27;ALLOCATED&#x27; WHERE id = 1 // 构造SQL: SELECT id, status, ... FROM minecart WHERE id = 1 String selectSQL = buildBeforeImageSQL(recognizer); return buildTableRecords(selectSQL); &#125; @Override protected TableRecords afterImage(TableRecords beforeImage) throws SQLException &#123; TableMeta tableMeta = getTableMeta(); String pk = tableMeta.getPkName(); // 根据主键构造 SELECT 语句查询修改后的数据 String selectSQL = buildAfterImageSQL(beforeImage); return buildTableRecords(selectSQL); &#125;&#125;// Before Image SQL 构建示例// 原始业务 SQL:// UPDATE minecart SET status = &#x27;ALLOCATED&#x27;, allocate_time = NOW() WHERE id = 1//// 构造的 Before Image SQL:// SELECT id, status, allocate_time FROM minecart WHERE id = 1//// Before Image 结果:// id=1, status=IDLE, allocate_time=null//// After Image 结果:// id=1, status=ALLOCATED, allocate_time=2024-06-25 10:30:00
undo_log 的数据结构与存储// BranchUndoLog——分支事务的回滚日志public class BranchUndoLog &#123; private String xid; // 全局事务ID private long branchId; // 分支事务ID private List&lt;SQLUndoLog&gt; sqlUndoLogs; // SQL回滚日志列表&#125;// SQLUndoLog——单条 SQL 的回滚日志public class SQLUndoLog &#123; private SQLType sqlType; // SQL类型：INSERT / UPDATE / DELETE private String tableName; // 表名 private TableRecords beforeImage; // 修改前数据快照 private TableRecords afterImage; // 修改后数据快照&#125;
undo_log 表在业务库中的建表语句： CREATE TABLE IF NOT EXISTS `undo_log` ( `id` BIGINT(20) NOT NULL AUTO_INCREMENT COMMENT &#x27;increment id&#x27;, `branch_id` BIGINT(20) NOT NULL COMMENT &#x27;branch transaction id&#x27;, `xid` VARCHAR(100) NOT NULL COMMENT &#x27;global transaction id&#x27;, `context` VARCHAR(128) NOT NULL COMMENT &#x27;undo_log context&#x27;, `rollback_info` LONGBLOB NOT NULL COMMENT &#x27;rollback info&#x27;, `log_status` INT(11) NOT NULL COMMENT &#x27;0:normal, 1:defense&#x27;, `log_created` DATETIME(6) NOT NULL COMMENT &#x27;create datetime&#x27;, `log_modified` DATETIME(6) NOT NULL COMMENT &#x27;modify datetime&#x27;, PRIMARY KEY (`id`), UNIQUE KEY `ux_undo_log` (`xid`, `branch_id`)) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT =&#x27;AT transaction mode undo log&#x27;;
undo_log 反向 SQL 生成规则undo_log 反向 SQL 生成规则：
SQL 类型 反向 SQL 说明 ────────────────────────────────────────────────────────── INSERT → DELETE 根据 After Image 的 主键删除 UPDATE → UPDATE 根据 Before Image 的 值恢复原始数据 DELETE → INSERT 根据 Before Image 的 全字段值重新插入
示例：矿车状态更新：
业务SQL: UPDATE minecart SET status&#x3D;’ALLOCATED’ WHERE id&#x3D;1 Before Image: id&#x3D;1, status&#x3D;IDLE After Image: id&#x3D;1, status&#x3D;ALLOCATED 回滚SQL: UPDATE minecart SET status&#x3D;’IDLE’ WHERE id&#x3D;1
示例：物资出库：
业务SQL: INSERT INTO stock_out(order_id,material_id,qty) VALUES(‘ORD001’,’MAT002’,10) After Image: id&#x3D;100, order_id&#x3D;ORD001, material_id&#x3D;MAT002 回滚SQL: DELETE FROM stock_out WHERE id&#x3D;100
prepareUndoLog 与 flushUndoLogs 核心逻辑// BaseTransactionalExecutor.prepareUndoLog() 源码简化protected void prepareUndoLog(TableRecords beforeImage, TableRecords afterImage) throws SQLException &#123; if (beforeImage.getRows().isEmpty() &amp;&amp; afterImage.getRows().isEmpty()) &#123; return; &#125; SQLUndoLog sqlUndoLog = new SQLUndoLog(); sqlUndoLog.setSqlType(sqlRecognizer.getSQLType()); sqlUndoLog.setTableName(sqlRecognizer.getTableName()); sqlUndoLog.setBeforeImage(beforeImage); sqlUndoLog.setAfterImage(afterImage); ConnectionProxy connectionProxy = statementProxy.getConnectionProxy(); connectionProxy.appendUndoLog(sqlUndoLog);&#125;// ConnectionProxy.flushUndoLogs() —— 在本地事务提交前写入 undo_logpublic void flushUndoLogs() throws SQLException &#123; List&lt;SQLUndoLog&gt; sqlUndoLogs = context.getUndoItems(); if (sqlUndoLogs.isEmpty()) &#123; return; &#125; BranchUndoLog branchUndoLog = new BranchUndoLog(); branchUndoLog.setXid(RootContext.getXid()); branchUndoLog.setBranchId(context.getBranchId()); branchUndoLog.setSqlUndoLogs(sqlUndoLogs); byte[] undoLogContent = serializer.serialize(branchUndoLog); insertUndoLog(branchUndoLog.getXid(), branchUndoLog.getBranchId(), buildContext(serializer.getName()), undoLogContent);&#125;
分支事务注册与全局锁申请// ConnectionProxy.commit() —— 本地事务提交时的完整流程public void commit() throws SQLException &#123; if (context.inGlobalTransaction()) &#123; try &#123; // 1. 注册分支事务，向 TC 申请全局锁 register(); &#125; catch (TransactionException e) &#123; rollback(); throw new SQLException(&quot;branch register failed, global lock acquire failed&quot;, e); &#125; try &#123; // 2. 写入 undo_log（与业务数据在同一个本地事务中） flushUndoLogs(); // 3. 提交本地事务（业务数据 + undo_log 一起提交） targetConnection.commit(); &#125; catch (SQLException e) &#123; report(false); throw e; &#125; // 4. 向 TC 报告分支事务状态为一阶段成功 report(true); &#125; else &#123; targetConnection.commit(); &#125;&#125;// 注册分支事务private void register() throws TransactionException &#123; Long branchId = DefaultResourceManager.get() .branchRegister(BranchType.AT, getResource().getResourceId(), RootContext.getXid(), context.getApplicationData(), context.buildLockKeys()); context.setBranchId(branchId);&#125;
一阶段完整时序图RM (矿车调度服务) TC (Seata Server) 数据库 │ │ │ │ 1. 业务方法执行 │ │ │ 2. DataSourceProxy拦截SQL │ │ │ │ │ │ 3. Before Image查询 │ │ │ ──────────────────────────────────────────────────────────────► │ │ ◄──── id=1, status=IDLE ────────────────────────────────────── │ │ │ │ │ 4. 执行业务SQL │ │ │ ────── UPDATE minecart SET... ───────────────────────────────► │ │ ◄──── 执行成功 ─────────────────────────────────────────────── │ │ │ │ │ 5. After Image查询 │ │ │ ──────────────────────────────────────────────────────────────► │ │ ◄──── id=1, status=ALLOCATED ───────────────────────────────── │ │ │ │ │ 6. 注册分支事务+申请全局锁 │ │ │ ────── BranchRegisterRequest ─────► │ │ │ │ 7.创建BranchSession │ │ │ 8.申请全局锁 │ │ ◄──── BranchRegisterResponse ───── │ │ │ │ │ │ 9. 写入undo_log │ │ │ ────── INSERT INTO undo_log ──────────────────────────────────►│ │ │ │ │ 10. 提交本地事务 │ │ │ ────── COMMIT ────────────────────────────────────────────────►│ │ (业务数据+undo_log一起提交) │ │ │ │ │ │ 11. 报告分支事务状态 │ │ │ ────── BranchReportRequest ───────► │ │ │ (status=PhaseOne_Done) │ │ │ │ │
全局事务提交流程源码分析TM 发起全局提交// DefaultGlobalTransaction.commit()public void commit() throws TransactionException &#123; if (role == GlobalTransactionRole.Participant) &#123; return; &#125; GlobalStatus status = transactionManager.commit(xid); switch (status) &#123; case Committed: break; case CommitRetrying: break; default: throw new TransactionException(&quot;Unexpected status: &quot; + status); &#125;&#125;
TC 协调全局提交——DefaultCore.commit()// DefaultCore.commit() —— TC 端全局提交的核心逻辑public GlobalStatus commit(String xid) throws TransactionException &#123; GlobalSession globalSession = holdGlobalSession(xid); if (globalSession == null) &#123; return GlobalStatus.Finished; &#125; globalSession.addSessionLifecycleListener(sessionHolder); globalSession.lockAndExcute(() -&gt; &#123; if (globalSession.getStatus() != GlobalStatus.Begin) &#123; return false; &#125; globalSession.changeGlobalStatus(GlobalStatus.Committing); doGlobalCommit(globalSession, false); return true; &#125;); return globalSession.getStatus();&#125;
doGlobalCommit——异步删除 undo_logAT 模式二阶段提交的核心特点：一阶段已经提交了本地事务，二阶段只需异步删除 undo_log。 // DefaultCore.doGlobalCommit() 核心源码public void doGlobalCommit(GlobalSession globalSession, boolean retrying) throws TransactionException &#123; for (BranchSession branchSession : globalSession.getSortedBranches()) &#123; BranchStatus currentStatus = branchSession.getStatus(); if (currentStatus == BranchStatus.PhaseOne_Failed) &#123; globalSession.removeBranch(branchSession); continue; &#125; try &#123; BranchStatus branchStatus = branchCommit(globalSession, branchSession); switch (branchStatus) &#123; case PhaseTwo_Committed: globalSession.removeBranch(branchSession); break; case PhaseTwo_CommitFailed_Unretryable: globalSession.changeGlobalStatus(GlobalStatus.CommitFailed); throw new TransactionException(&quot;Commit failed.&quot;); case PhaseTwo_CommitFailed_Retryable: if (!retrying) &#123; queueToRetryCommit(globalSession); return; &#125; break; default: throw new TransactionException(&quot;Unknown branch status: &quot; + branchStatus); &#125; &#125; catch (Exception ex) &#123; log.error(&quot;Exception occur during branch commit&quot;, ex); queueToRetryCommit(globalSession); return; &#125; &#125; if (globalSession.hasBranch()) &#123; return; &#125; globalSession.cleanLocks(); globalSession.changeGlobalStatus(GlobalStatus.Committed); globalSession.close(); globalSession.remove();&#125;
RM 分支提交——删除 undo_log// DataSourceManager.branchCommit()public BranchStatus branchCommit(BranchType branchType, String xid, long branchId, String resourceId, String applicationData) throws TransactionException &#123; return asyncBranchCommit(xid, branchId, resourceId);&#125;// 异步删除 undo_logprivate BranchStatus asyncBranchCommit(String xid, long branchId, String resourceId) &#123; COMMITTING_EXECUTOR.execute(() -&gt; &#123; try &#123; undoLogManager.deleteUndoLog(xid, branchId, dataSource); &#125; catch (Exception e) &#123; log.warn(&quot;Failed to delete undo log for xid=&#123;&#125;, branchId=&#123;&#125;&quot;, xid, branchId, e); &#125; &#125;); return BranchStatus.PhaseTwo_Committed;&#125;// UndoLogManager.deleteUndoLog()public void deleteUndoLog(String xid, long branchId, DataSource dataSource) &#123; try (Connection conn = dataSource.getConnection(); PreparedStatement ps = conn.prepareStatement( &quot;DELETE FROM undo_log WHERE xid = ? AND branch_id = ?&quot;)) &#123; ps.setString(1, xid); ps.setLong(2, branchId); int deleteRows = ps.executeUpdate(); log.info(&quot;Delete undo log xid=&#123;&#125;, branchId=&#123;&#125;, deleteRows=&#123;&#125;&quot;, xid, branchId, deleteRows); &#125; catch (SQLException e) &#123; log.error(&quot;Failed to delete undo log, xid=&#123;&#125;, branchId=&#123;&#125;&quot;, xid, branchId, e); &#125;&#125;
AT 模式二阶段提交为什么这么快？架构流程： flowchart TD N1[&quot;AT 模式二阶段提交 vs 传统两阶段提交 对比 传统两阶段提交&quot;] N2[&quot;不提交本地事务&quot;] N3[&quot;一阶段&quot;] N4[&quot;执行业务SQL&quot;] N5[&quot;持有本地锁 二阶段&quot;] N6[&quot;提交本地事务&quot;] N7[&quot;释放本地锁 问题一阶段持有本地锁时间长&quot;] N8[&quot;其他事务被阻塞&quot;] N9[&quot;一阶段执行业务SQL&quot;] N10[&quot;生成undo_log&quot;] N11[&quot;释放本地锁全局锁仍持有 二阶段&quot;] N12[&quot;异步删除undo_log&quot;] N13[&quot;释放全局锁 优势一阶段就提交了本地事务&quot;] N14[&quot;本地锁快速释放 二阶段只需异步删除undo_log&quot;] N15[&quot;几乎零开销&quot;] N1 --&gt; N2 N3 --&gt; N2 N4 --&gt; N2 N2 --&gt; N5 N2 --&gt; N6 N5 --&gt; N7 N5 --&gt; N8 N6 --&gt; N7 N6 --&gt; N8 N7 --&gt; N3 N7 --&gt; N4 N8 --&gt; N3 N8 --&gt; N4 N7 --&gt; N9 N7 --&gt; N10 N8 --&gt; N9 N8 --&gt; N10 N9 --&gt; N6 N10 --&gt; N6 N6 --&gt; N11 N6 --&gt; N12 N11 --&gt; N13 N11 --&gt; N14 N11 --&gt; N15 N12 --&gt; N13 N12 --&gt; N14 N12 --&gt; N15
全局提交完整时序图TM (矿车调度服务) TC (Seata Server) RM-1 (调度服务) RM-2 (设备服务) │ │ │ │ │ 业务方法正常返回 │ │ │ │ ── GlobalCommitRequest►│ │ │ │ │ │ │ │ │ 1.获取GlobalSession │ │ │ │ 2.状态→Committing │ │ │ │ │ │ │ │ ── BranchCommitRequest ──►│ │ │ │ (xid, branchId=2001) │ │ │ │ │ 3.异步删除undo_log │ │ │ ◄─ PhaseTwo_Committed ───│ │ │ │ │ │ │ │ ── BranchCommitRequest ────────────────────────►│ │ │ (xid, branchId=2002) │ │ │ │ 4.异步删除undo_log │ │ │ ◄─ PhaseTwo_Committed ──────────────────────── │ │ │ │ │ │ │ 5.清理全局锁 │ │ │ │ 6.状态→Committed │ │ │ ◄─ GlobalCommitResponse│ │ │ │ (status=Committed) │ │ │ │ │ │ │
全局事务回滚流程源码分析TM 发起全局回滚// DefaultGlobalTransaction.rollback()public void rollback() throws TransactionException &#123; if (role == GlobalTransactionRole.Participant) &#123; return; &#125; GlobalStatus status = transactionManager.rollback(xid); switch (status) &#123; case Rollbacked: break; case RollbackFailed: throw new TransactionException(&quot;Global rollback failed.&quot;); case RollbackRetrying: break; default: throw new TransactionException(&quot;Unexpected status: &quot; + status); &#125;&#125;
TC 协调全局回滚——DefaultCore.rollback()// DefaultCore.rollback()public GlobalStatus rollback(String xid) throws TransactionException &#123; GlobalSession globalSession = holdGlobalSession(xid); if (globalSession == null) &#123; return GlobalStatus.Finished; &#125; globalSession.addSessionLifecycleListener(sessionHolder); globalSession.lockAndExcute(() -&gt; &#123; GlobalStatus status = globalSession.getStatus(); if (status == GlobalStatus.Begin) &#123; globalSession.changeGlobalStatus(GlobalStatus.Rollbacking); doGlobalRollback(globalSession, false); return true; &#125; if (status == GlobalStatus.Committing) &#123; log.warn(&quot;Global transaction is committing, cannot rollback. xid=&#123;&#125;&quot;, xid); return false; &#125; return false; &#125;); return globalSession.getStatus();&#125;
doGlobalRollback——逆序回滚分支事务// DefaultCore.doGlobalRollback() 核心源码public void doGlobalRollback(GlobalSession globalSession, boolean retrying) throws TransactionException &#123; // 逆序回滚各分支事务——与注册顺序相反 for (BranchSession branchSession : globalSession.getReverseSortedBranches()) &#123; BranchStatus currentStatus = branchSession.getStatus(); try &#123; BranchStatus branchStatus = branchRollback(globalSession, branchSession); switch (branchStatus) &#123; case PhaseTwo_Rollbacked: globalSession.removeBranch(branchSession); break; case PhaseTwo_RollbackFailed_Unretryable: globalSession.changeGlobalStatus(GlobalStatus.RollbackFailed); throw new TransactionException(&quot;Rollback failed.&quot;); case PhaseTwo_RollbackFailed_Retryable: if (!retrying) &#123; queueToRetryRollback(globalSession); return; &#125; break; case PhaseOne_Failed: globalSession.removeBranch(branchSession); break; default: throw new TransactionException(&quot;Unknown branch status: &quot; + branchStatus); &#125; &#125; catch (Exception ex) &#123; log.error(&quot;Exception occur during branch rollback&quot;, ex); queueToRetryRollback(globalSession); return; &#125; &#125; if (globalSession.hasBranch()) &#123; return; &#125; globalSession.cleanLocks(); globalSession.changeGlobalStatus(GlobalStatus.Rollbacked); globalSession.close(); globalSession.remove();&#125;
RM 分支回滚——根据 undo_log 执行反向 SQL// DataSourceManager.branchRollback()public BranchStatus branchRollback(BranchType branchType, String xid, long branchId, String resourceId, String applicationData) throws TransactionException &#123; DataSourceProxy dataSourceProxy = get(resourceId); if (dataSourceProxy == null) &#123; throw new TransactionException(&quot;DataSource not found: &quot; + resourceId); &#125; try &#123; UndoLogManager undoLogManager = dataSourceProxy.getUndoLogManager(); undoLogManager.undo(dataSourceProxy, xid, branchId); &#125; catch (TransactionException te) &#123; if (te.getCode() == TransactionExceptionCode.BranchRollbackFailed_Unretryable) &#123; return BranchStatus.PhaseTwo_RollbackFailed_Unretryable; &#125; return BranchStatus.PhaseTwo_RollbackFailed_Retryable; &#125; return BranchStatus.PhaseTwo_Rollbacked;&#125;
UndoLogManager.undo()——回滚的核心实现// UndoLogManager.undo() 核心源码public void undo(DataSourceProxy dataSourceProxy, String xid, long branchId) throws TransactionException &#123; ConnectionProxy cp = null; try &#123; cp = dataSourceProxy.getConnectionProxy(); // Step 1: 查询 undo_log 记录 BranchUndoLog undoLog = getUndoLog(cp, xid, branchId); if (undoLog == null) &#123; // undo_log 不存在，幂等处理：直接返回成功 return; &#125; // Step 2: 校验 After Image 与当前数据是否一致（防脏写校验） if (!canUndo(undoLog, cp)) &#123; // After Image 与当前数据不一致 // 需要人工介入！ throw new TransactionException( TransactionExceptionCode.BranchRollbackFailed_Unretryable, String.format( &quot;Rollback branch transaction failed, data has been changed. &quot; + &quot;xid=%s, branchId=%s&quot;, xid, branchId)); &#125; // Step 3: 根据 Before Image 生成反向 SQL 并执行 for (SQLUndoLog sqlUndoLog : undoLog.getSqlUndoLogs()) &#123; AbstractUndoExecutor undoExecutor = UndoExecutorFactory.getUndoExecutor( dataSourceProxy.getDbType(), sqlUndoLog); undoExecutor.executeUndoOn(cp); &#125; // Step 4: 删除 undo_log 记录 deleteUndoLog(cp, xid, branchId); &#125; catch (SQLException e) &#123; throw new TransactionException(&quot;Undo operation failed.&quot;, e); &#125; finally &#123; if (cp != null) &#123; try &#123; cp.close(); &#125; catch (SQLException e) &#123; log.warn(&quot;Failed to close connection&quot;, e); &#125; &#125; &#125;&#125;
防脏写校验——canUndo() 详解// UndoLogManager.canUndo() —— 防脏写校验private boolean canUndo(BranchUndoLog undoLog, ConnectionProxy cp) throws SQLException &#123; for (SQLUndoLog sqlUndoLog : undoLog.getSqlUndoLogs()) &#123; TableRecords currentData = queryCurrentData(cp, sqlUndoLog); TableRecords afterImage = sqlUndoLog.getAfterImage(); if (sqlUndoLog.getSqlType() == SQLType.DELETE) &#123; if (!currentData.getRows().isEmpty()) &#123; log.warn(&quot;Delete undo check failed, current data is not empty. &quot; + &quot;tableName=&#123;&#125;&quot;, sqlUndoLog.getTableName()); return false; &#125; &#125; else &#123; if (!compareData(afterImage, currentData)) &#123; log.warn(&quot;After Image check failed, data has been changed. &quot; + &quot;tableName=&#123;&#125;, afterImage=&#123;&#125;, currentData=&#123;&#125;&quot;, sqlUndoLog.getTableName(), afterImage, currentData); return false; &#125; &#125; &#125; return true;&#125;// 逐字段比较 After Image 与当前数据private boolean compareData(TableRecords afterImage, TableRecords currentData) &#123; if (afterImage.getRows().size() != currentData.getRows().size()) &#123; return false; &#125; for (int i = 0; i &lt; afterImage.getRows().size(); i++) &#123; Row afterRow = afterImage.getRows().get(i); Row currentRow = currentData.getRows().get(i); for (int j = 0; j &lt; afterRow.getFields().size(); j++) &#123; Field afterField = afterRow.getFields().get(j); Field currentField = currentRow.getFields().get(j); if (!Objects.equals(afterField.getValue(), currentField.getValue())) &#123; return false; &#125; &#125; &#125; return true;&#125;
AbstractUndoExecutor——反向 SQL 生成与执行// AbstractUndoExecutor 抽象基类public abstract class AbstractUndoExecutor &#123; protected SQLUndoLog sqlUndoLog; public void executeUndoOn(ConnectionProxy cp) throws SQLException &#123; String undoSQL = buildUndoSQL(); try (PreparedStatement ps = cp.getTargetConnection().prepareStatement(undoSQL)) &#123; setUndoParameters(ps, sqlUndoLog.getBeforeImage()); int affectedRows = ps.executeUpdate(); if (affectedRows == 0) &#123; throw new SQLException(&quot;Undo operation affected 0 rows.&quot;); &#125; &#125; &#125; protected abstract String buildUndoSQL();&#125;// MySQLInsertUndoExecutor —— INSERT 的反向 SQL 为 DELETEpublic class MySQLInsertUndoExecutor extends AbstractUndoExecutor &#123; @Override protected String buildUndoSQL() &#123; StringBuilder sql = new StringBuilder(&quot;DELETE FROM &quot;); sql.append(sqlUndoLog.getTableName()); sql.append(&quot; WHERE &quot;); List&lt;Field&gt; pkFields = sqlUndoLog.getAfterImage().pkFields(); for (int i = 0; i &lt; pkFields.size(); i++) &#123; if (i &gt; 0) sql.append(&quot; AND &quot;); sql.append(pkFields.get(i).getName()).append(&quot; = ?&quot;); &#125; return sql.toString(); &#125;&#125;// MySQLUpdateUndoExecutor —— UPDATE 的反向 SQL 仍为 UPDATE（用 Before Image 的值）public class MySQLUpdateUndoExecutor extends AbstractUndoExecutor &#123; @Override protected String buildUndoSQL() &#123; StringBuilder sql = new StringBuilder(&quot;UPDATE &quot;); sql.append(sqlUndoLog.getTableName()).append(&quot; SET &quot;); List&lt;Field&gt; beforeFields = sqlUndoLog.getBeforeImage().nonPkFields(); for (int i = 0; i &lt; beforeFields.size(); i++) &#123; if (i &gt; 0) sql.append(&quot;, &quot;); sql.append(beforeFields.get(i).getName()).append(&quot; = ?&quot;); &#125; sql.append(&quot; WHERE &quot;); List&lt;Field&gt; pkFields = sqlUndoLog.getBeforeImage().pkFields(); for (int i = 0; i &lt; pkFields.size(); i++) &#123; if (i &gt; 0) sql.append(&quot; AND &quot;); sql.append(pkFields.get(i).getName()).append(&quot; = ?&quot;); &#125; return sql.toString(); &#125;&#125;// MySQLDeleteUndoExecutor —— DELETE 的反向 SQL 为 INSERTpublic class MySQLDeleteUndoExecutor extends AbstractUndoExecutor &#123; @Override protected String buildUndoSQL() &#123; StringBuilder sql = new StringBuilder(&quot;INSERT INTO &quot;); sql.append(sqlUndoLog.getTableName()).append(&quot; (&quot;); List&lt;Field&gt; beforeFields = sqlUndoLog.getBeforeImage().allFields(); for (int i = 0; i &lt; beforeFields.size(); i++) &#123; if (i &gt; 0) sql.append(&quot;, &quot;); sql.append(beforeFields.get(i).getName()); &#125; sql.append(&quot;) VALUES (&quot;); for (int i = 0; i &lt; beforeFields.size(); i++) &#123; if (i &gt; 0) sql.append(&quot;, &quot;); sql.append(&quot;?&quot;); &#125; sql.append(&quot;)&quot;); return sql.toString(); &#125;&#125;
全局回滚完整时序图TM (矿车调度服务) TC (Seata Server) RM-1 (调度服务) RM-2 (设备服务) │ │ │ │ │ 业务方法抛出异常 │ │ │ │ ── GlobalRollbackReq──►│ │ │ │ │ │ │ │ │ 1.获取GlobalSession │ │ │ │ 2.状态→Rollbacking │ │ │ │ │ │ │ │ 逆序回滚分支： │ │ │ │ │ │ │ │ ── BranchRollbackReq ────────────────────────►│ │ │ (xid, branchId=2002) │ │ │ │ │ 3.查询undo_log │ │ │ │ 4.校验After Image │ │ │ │ 5.执行反向SQL │ │ │ │ 6.删除undo_log │ │ │ ◄─ PhaseTwo_Rollbacked ──────────────────────│ │ │ │ │ │ │ ── BranchRollbackReq ──►│ │ │ │ (xid, branchId=2001) │ │ │ │ │ 3.查询undo_log │ │ │ │ 4.校验After Image │ │ │ │ 5.执行反向SQL │ │ │ │ 6.删除undo_log │ │ │ ◄─ PhaseTwo_Rollbacked ─│ │ │ │ │ │ │ │ 7.清理全局锁 │ │ │ │ 8.状态→Rollbacked │ │ │ ◄─ GlobalRollbackResp │ │ │ │ (status=Rollbacked) │ │ │ │ │ │ │
防脏写校验的场景分析防脏写校验场景分析：
场景1：正常回滚 ────────────── 全局事务A: UPDATE minecart SET status&#x3D;’ALLOCATED’ WHERE id&#x3D;1 After Image: status&#x3D;’ALLOCATED’ 当前数据: status&#x3D;’ALLOCATED’ ← 一致，可以回滚 回滚SQL: UPDATE minecart SET status&#x3D;’IDLE’ WHERE id&#x3D;1 场景2：数据被本地事务修改（脏写），回滚失败 ────────────────────────────────────────── 全局事务A: UPDATE minecart SET status&#x3D;’ALLOCATED’ WHERE id&#x3D;1 After Image: status&#x3D;’ALLOCATED’ 本地事务B: UPDATE minecart SET status&#x3D;’MAINTENANCE’ WHERE id&#x3D;1 当前数据: status&#x3D;’MAINTENANCE’ ← 不一致，不能回滚！ 结果: 抛出异常，需人工介入 场景3：DELETE 后有新 INSERT，回滚失败 ────────────────────────────────────── 全局事务A: DELETE FROM minecart WHERE id&#x3D;1 After Image: (空) 本地事务B: INSERT INTO minecart VALUES(1,’NEW’,…) 当前数据: id&#x3D;1, status&#x3D;’NEW’ ← 不为空，不能回滚！ 结果: 抛出异常，需人工介入 实际项目实际案例： 矿车调拨全局事务回滚时，设备状态已被本地维护任务修改， After Image 校验失败，进入 RollbackFailed 状态， 需要运维人员根据 undo_log 手动补偿。
全局锁机制源码分析全局锁的必要性AT 模式的核心设计是在一阶段就提交本地事务，这意味着全局事务尚未完成时，本地事务已经提交，其他本地事务可以读到未确认的数据。如果另一个全局事务也修改了同一行数据，就会出现写冲突。全局锁就是为了解决这个问题。 为什么需要全局锁？：
没有全局锁的场景： 全局事务A 全局事务B UPDATE account UPDATE account SET balance&#x3D;balance-100 SET balance&#x3D;balance+50 WHERE id&#x3D;1 WHERE id&#x3D;1 t1: 一阶段提交本地事务 balance: 900 t2: t1: 一阶段提交本地事务 balance: 950 t3: 全局回滚 根据undo_log: balance→1000 但B的undo_log: before&#x3D;900 数据不一致！ 有全局锁的场景： 全局事务A 全局事务B t1: 申请全局锁(account:1)→成功 t2: 一阶段提交本地事务 t3: t1: 申请全局锁(account:1)→失败 等待全局锁释放… t4: 全局提交&#x2F;回滚 释放全局锁 t5: t2: 申请全局锁→成功 t3: 一阶段提交本地事务 数据一致性保证！
全局锁的存储结构全局锁存储结构（TC 内存模式）：
ConcurrentHashMap&lt;String, ConcurrentHashMap&lt;String, Long&gt;&gt; resourceId lockKey branchId (数据源ID) (表名:主键) (分支事务ID) 示例： { “jdbc:mysql:&#x2F;&#x2F;minecart-db:3306&#x2F;minecart” → { “minecart:1” → 2001, &#x2F;&#x2F; 矿车1被分支2001锁定 “minecart:3” → 2001, &#x2F;&#x2F; 矿车3被分支2001锁定 “equipment:5” → 2002, &#x2F;&#x2F; 设备5被分支2002锁定 }, “jdbc:mysql:&#x2F;&#x2F;stock-db:3306&#x2F;stock” → { “material:MAT002” → 2003, &#x2F;&#x2F; 物资MAT002被分支2003锁定 } } lockKey 格式： 单行锁：tableName:pkValue 如 “minecart:1” 多行锁：tableName:pk1:pk2:pk3 如 “minecart:1:2:3”
全局锁申请源码// LockManager.acquireLock() —— 全局锁申请入口public boolean acquireLock(BranchSession branchSession) throws TransactionException &#123; String lockKey = branchSession.getLockKey(); if (StringUtils.isBlank(lockKey)) &#123; return true; &#125; List&lt;LockKey&gt; lockKeys = LockKeyParser.parse(lockKey); return lockStore.acquireLock(branchSession.getXid(), branchSession.getBranchId(), lockKeys, branchSession.isAutoCommit());&#125;// LockStore.acquireLock() —— 内存模式的全局锁申请实现public boolean acquireLock(String xid, long branchId, List&lt;LockKey&gt; lockKeys, boolean autoCommit) throws TransactionException &#123; // 分两步：先检查所有锁是否可获取，再一次性获取 List&lt;LockKey&gt; conflictKeys = new ArrayList&lt;&gt;(); for (LockKey lockKey : lockKeys) &#123; String key = lockKey.getTable() + &quot;:&quot; + lockKey.getPk(); ConcurrentHashMap&lt;String, Long&gt; tableLocks = LOCK_MAP.get(lockKey.getTable()); if (tableLocks != null) &#123; Long holdingBranchId = tableLocks.get(key); if (holdingBranchId != null &amp;&amp; !holdingBranchId.equals(branchId)) &#123; conflictKeys.add(lockKey); &#125; &#125; &#125; if (!conflictKeys.isEmpty()) &#123; if (autoCommit) &#123; throw new LockConflictException(); &#125; else &#123; // 默认重试 30 次，每次间隔 10ms return retryAcquireLock(xid, branchId, lockKeys); &#125; &#125; // 无冲突，一次性获取所有锁 for (LockKey lockKey : lockKeys) &#123; String key = lockKey.getTable() + &quot;:&quot; + lockKey.getPk(); LOCK_MAP.computeIfAbsent(lockKey.getTable(), k -&gt; new ConcurrentHashMap&lt;&gt;()) .put(key, branchId); &#125; return true;&#125;// 重试获取全局锁private boolean retryAcquireLock(String xid, long branchId, List&lt;LockKey&gt; lockKeys) &#123; int retry = 0; int maxRetry = 30; long retryInterval = 10; while (retry &lt; maxRetry) &#123; try &#123; Thread.sleep(retryInterval); &#125; catch (InterruptedException e) &#123; Thread.currentThread().interrupt(); return false; &#125; boolean conflict = false; for (LockKey lockKey : lockKeys) &#123; String key = lockKey.getTable() + &quot;:&quot; + lockKey.getPk(); ConcurrentHashMap&lt;String, Long&gt; tableLocks = LOCK_MAP.get(lockKey.getTable()); if (tableLocks != null) &#123; Long holdingBranchId = tableLocks.get(key); if (holdingBranchId != null &amp;&amp; !holdingBranchId.equals(branchId)) &#123; conflict = true; break; &#125; &#125; &#125; if (!conflict) &#123; for (LockKey lockKey : lockKeys) &#123; String key = lockKey.getTable() + &quot;:&quot; + lockKey.getPk(); LOCK_MAP.computeIfAbsent(lockKey.getTable(), k -&gt; new ConcurrentHashMap&lt;&gt;()) .put(key, branchId); &#125; return true; &#125; retry++; &#125; return false;&#125;
全局锁释放源码// LockManager.releaseLock() —— 全局锁释放public boolean releaseLock(String xid, long branchId) &#123; List&lt;String&gt; lockKeys = getLockKeysByBranch(branchId); for (String lockKey : lockKeys) &#123; String[] parts = lockKey.split(&quot;:&quot;); String table = parts[0]; String pk = parts[1]; ConcurrentHashMap&lt;String, Long&gt; tableLocks = LOCK_MAP.get(table); if (tableLocks != null) &#123; Long holdingBranchId = tableLocks.get(pk); if (holdingBranchId != null &amp;&amp; holdingBranchId.equals(branchId)) &#123; tableLocks.remove(pk); &#125; &#125; &#125; return true;&#125;// GlobalSession.cleanLocks() —— 全局事务完成时清理所有分支的锁public void cleanLocks() &#123; for (BranchSession branchSession : branchSessions) &#123; LockManager lockManager = DefaultLockManager.get(); lockManager.releaseLock(branchSession.getXid(), branchSession.getBranchId()); &#125;&#125;
全局锁 vs 本地锁全局锁 vs 本地锁 对比：
维度 全局锁 本地锁 ──────────────────────────────────────────────────────────── 作用范围 跨服务（全局事务间） 单服务（本地事务间） 持有者 TC（Seata Server） 数据库引擎 粒度 行级（表名:主键值） 行级&#x2F;表级 生命周期 全局事务开始→提交&#x2F;回滚 SQL执行→事务提交 释放时机 全局提交&#x2F;回滚后 本地事务提交&#x2F;回滚后 存储位置 TC内存&#x2F;Redis&#x2F;DB 数据库锁管理器 冲突处理 等待重试&#x2F;抛异常 等待&#x2F;死锁检测 AT 模式的锁生命周期： 一阶段：
执行业务SQL前：申请全局锁
执行业务SQL时：持有本地锁
提交本地事务后：释放本地锁，但仍持有全局锁
二阶段：
全局提交&#x2F;回滚后：释放全局锁
关键理解： 全局锁不是数据库锁，而是 Seata TC 管理的逻辑锁 全局锁保证的是”两个全局事务不会同时修改同一行” 但全局锁不能防止本地事务修改数据（这就是脏写的根源） After Image 校验就是用来检测这种脏写的
全局锁存储模式对比
存储模式 实现类 性能 持久性 适用场景
内存 MemoryLockManager 最高 TC重启后丢失 开发&#x2F;测试环境
Redis RedisLockManager 高 Redis持久化保证 生产环境（推荐）
数据库 DataBaseLockManager 较低 数据库持久化保证 生产环境（TC高可用）
在实际场景中，我们使用 Redis 模式存储全局锁，配合 Seata Server 的高可用部署，确保全局锁在 TC 故障转移后不丢失。
XID 的传播机制XID 的生成规则// DefaultTransactionManager.begin() —— XID 的生成public String begin(String applicationId, String transactionServiceGroup, String name, int timeout) throws TransactionException &#123; GlobalBeginRequest request = new GlobalBeginRequest(); request.setTransactionName(name); request.setTimeout(timeout); request.setApplicationId(applicationId); GlobalBeginResponse response = (GlobalBeginResponse) syncCall(request); // XID 格式：ip:port:transactionId // 如：192.168.1.10:8091:1234567890 return response.getXid();&#125;
XID 在微服务间的传播架构流程： XID 跨服务传播机制 矿车调度服务 (TM) 设备管理服务 (RM) 人员定位服务 (RM) ┌─────────────────┐ ┌─────────────────┐ ┌──────────────┐ @GlobalTransact 获取XID RootContext .bind(xid) HTTP&#x2F;RPC调用 ──┼──────► 拦截器提取XID Header: RootContext TX_XID&#x3D;xid .bind(xid) HTTP&#x2F;RPC调用 ───┼──► 拦截器提取XID Header: RootContext TX_XID&#x3D;xid .bind(xid) → @GlobalTransact 获取XID RootContext .bind(xid) HTTP&#x2F;RPC调用 ──┼──────► 拦截器提取XID Header: RootContext TX_XID&#x3D;xid .bind(xid) HTTP&#x2F;RPC调用 ───┼──► 拦截器提取XID Header: RootContext TX_XID&#x3D;xid .bind(xid) Seata Spring MVC 拦截器public class SeataHandlerInterceptor implements HandlerInterceptor &#123; @Override public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) &#123; String xid = RootContext.getXid(); String rpcXid = request.getHeader(RootContext.KEY_XID); if (StringUtils.isBlank(xid) &amp;&amp; StringUtils.isNotBlank(rpcXid)) &#123; RootContext.bind(rpcXid); log.debug(&quot;Bind xid [&#123;&#125;] to current thread&quot;, rpcXid); &#125; return true; &#125; @Override public void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler, Exception ex) &#123; String xid = RootContext.getXid(); if (StringUtils.isNotBlank(xid)) &#123; RootContext.unbind(); log.debug(&quot;Unbind xid [&#123;&#125;] from current thread&quot;, xid); &#125; &#125;&#125;
RootContext——XID 的线程级存储public class RootContext &#123; private static final ThreadLocal&lt;String&gt; CONTEXT_HOLDER = new ThreadLocal&lt;&gt;(); private static final ThreadLocal&lt;String&gt; LOCK_HOLDER = new ThreadLocal&lt;&gt;(); public static void bind(String xid) &#123; if (StringUtils.isNotBlank(xid)) &#123; CONTEXT_HOLDER.set(xid); &#125; &#125; public static String getXid() &#123; return CONTEXT_HOLDER.get(); &#125; public static boolean inGlobalTransaction() &#123; return CONTEXT_HOLDER.get() != null; &#125; public static String.unbind() &#123; String xid = CONTEXT_HOLDER.get(); CONTEXT_HOLDER.remove(); return xid; &#125;&#125;
线程池场景下的 XID 传播在实际场景中，大量使用了异步线程池处理耗时操作，需要在提交任务时传递 XID。 // 线程池场景下的 XID 传播方案public class XidTaskDecorator implements TaskDecorator &#123; @Override public Runnable decorate(Runnable runnable) &#123; String xid = RootContext.getXid(); return () -&gt; &#123; try &#123; if (StringUtils.isNotBlank(xid)) &#123; RootContext.bind(xid); &#125; runnable.run(); &#125; finally &#123; RootContext.unbind(); &#125; &#125;; &#125;&#125;// 配置线程池时使用 XidTaskDecorator@Beanpublic ThreadPoolTaskExecutor taskExecutor() &#123; ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor(); executor.setCorePoolSize(10); executor.setMaxPoolSize(50); executor.setQueueCapacity(200); executor.setTaskDecorator(new XidTaskDecorator()); // 关键！ executor.setThreadNamePrefix(&quot;xid-task-&quot;); return executor;&#125;// 实际项目中的实际使用@GlobalTransactional(name = &quot;alarm-notify&quot;, timeoutMills = 60000)public void processAlarm(AlarmEvent event) &#123; alarmService.saveAlarm(event); taskExecutor.execute(() -&gt; &#123; notificationService.sendNotification(event); &#125;);&#125;
Seata AT 模式中的并发场景分析场景1：两个全局事务修改同一行时间轴 全局事务A (矿车调拨) 全局事务B (矿车维修) t1 @GlobalTransactional @GlobalTransactional t2 UPDATE minecart UPDATE minecart SET status=&#x27;ALLOCATED&#x27; SET status=&#x27;MAINTENANCE&#x27; WHERE id=1 WHERE id=1 t3 申请全局锁 minecart:1 → 成功 t4 执行业务SQL + 生成undo_log t5 提交本地事务 申请全局锁 minecart:1 → 冲突！ t6 等待重试（30次，每次10ms） t7 全局提交 t8 释放全局锁 minecart:1 t9 申请全局锁 minecart:1 → 成功 t10 执行业务SQL + 生成undo_log t11 提交本地事务 t12 全局提交 结果：事务A和事务B串行执行，数据一致性保证
场景2：全局事务与本地事务修改同一行时间轴 全局事务A (矿车调拨) 本地事务B (状态巡检) t1 @GlobalTransactional t2 UPDATE minecart SET status=&#x27;ALLOCATED&#x27; WHERE id=1 t3 申请全局锁 minecart:1 → 成功 t4 执行业务SQL + 生成undo_log t5 提交本地事务（释放本地锁） t6 UPDATE minecart SET status=&#x27;MAINTENANCE&#x27; WHERE id=1 t7 本地事务B提交成功！ t8 全局回滚！ t9 校验 After Image: 期望 status=&#x27;ALLOCATED&#x27; 实际 status=&#x27;MAINTENANCE&#x27; t10 校验失败！不能自动回滚！ → 进入 RollbackFailed 状态 → 需人工介入 这就是 AT 模式的&quot;脏写&quot;问题 全局锁只能防止全局事务间的冲突 不能防止本地事务的修改
场景3：读操作的全局锁——SELECT FOR UPDATE// SelectForUpdateExecutor —— SELECT FOR UPDATE 也会申请全局锁public class SelectForUpdateExecutor&lt;T, S extends Statement&gt; extends BaseTransactionalExecutor&lt;T, S&gt; &#123; @Override protected T doExecute(Object... args) throws Throwable &#123; // 1. 申请全局锁 LockManager lockManager = DefaultLockManager.get(); lockManager.acquireLock(new LockKey(getTableName(), getPkValues())); // 2. 执行 SELECT ... FOR UPDATE（获取本地锁） return statementCallback.execute(statementProxy.getTargetStatement(), args); &#125;&#125;// 实际项目中的应用：@GlobalTransactional(name = &quot;minecart-allocate&quot;)public void allocateMinecart(Long minecartId, Long taskId) &#123; // 锁定矿车记录 Minecart minecart = minecartMapper.selectForUpdate(minecartId); if (!&quot;IDLE&quot;.equals(minecart.getStatus())) &#123; throw new BusinessException(&quot;矿车状态不允许调拨&quot;); &#125; minecart.setStatus(&quot;ALLOCATED&quot;); minecart.setAllocateTime(new Date()); minecartMapper.updateById(minecart);&#125;
Seata Server（TC）核心源码分析GlobalSession 全局会话管理public class GlobalSession implements SessionLifecycle, Comparable&lt;GlobalSession&gt; &#123; private String xid; private GlobalStatus status; private String applicationId; private String transactionServiceGroup; private String transactionName; private int timeout; private long beginTime; private List&lt;BranchSession&gt; branchSessions = new ArrayList&lt;&gt;(); private GlobalSession parent; public void addBranch(BranchSession branchSession) &#123; branchSessions.add(branchSession); branchSession.setGlobalSession(this); &#125; public void removeBranch(BranchSession branchSession) &#123; branchSessions.remove(branchSession); &#125; public List&lt;BranchSession&gt; getSortedBranches() &#123; return new ArrayList&lt;&gt;(branchSessions); &#125; public List&lt;BranchSession&gt; getReverseSortedBranches() &#123; List&lt;BranchSession&gt; reversed = new ArrayList&lt;&gt;(branchSessions); Collections.reverse(reversed); return reversed; &#125; public void changeGlobalStatus(GlobalStatus status) &#123; this.status = status; sessionHolder.onGlobalStatusChanged(this, status); &#125;&#125;
TC 的事务状态机架构流程： flowchart TD N1[&quot;TC 全局事务状态机&quot;] N2[&quot;Begin TM 开启全局事务&quot;] N3[&quot;Begin&quot;] N4[&quot;TM 开启全局事务&quot;] N5[&quot;Committing&quot;] N6[&quot;Rollbacking&quot;] N7[&quot;等待所有分支一阶段完成 Committing TM 发起全局提交&quot;] N8[&quot;Committed 异常流程&quot;] N9[&quot;RollbackFailed&quot;] N1 --&gt; N2 N3 --&gt; N2 N4 --&gt; N2 N2 --&gt; N5 N2 --&gt; N6 N5 --&gt; N6 N6 --&gt; N5 N5 --&gt; N7 N6 --&gt; N7 N7 --&gt; N5 N5 --&gt; N8 N5 --&gt; N3 N8 --&gt; N6 N3 --&gt; N6 N6 --&gt; N9
TC 的定时任务——超时清理与重试public class DefaultCoordinator extends AbstractTCInboundHandler implements TransactionMessageListener, Disposable &#123; private final ScheduledThreadPoolExecutor timeoutCheckExecutor = new ScheduledThreadPoolExecutor(1, new NamedThreadFactory(&quot;timeoutCheck&quot;, 1)); private final ScheduledThreadPoolExecutor retryCommitExecutor = new ScheduledThreadPoolExecutor(1, new NamedThreadFactory(&quot;retryCommit&quot;, 1)); private final ScheduledThreadPoolExecutor retryRollbackExecutor = new ScheduledThreadPoolExecutor(1, new NamedThreadFactory(&quot;retryRollback&quot;, 1)); public void init() &#123; timeoutCheckExecutor.scheduleAtFixedRate( this::timeoutCheck, 0, 1, TimeUnit.SECONDS); retryCommitExecutor.scheduleAtFixedRate( this::handleRetryCommit, 0, 1, TimeUnit.SECONDS); retryRollbackExecutor.scheduleAtFixedRate( this::handleRetryRollback, 0, 1, TimeUnit.SECONDS); &#125; /** * 超时检测——关闭超时的全局事务 */ private void timeoutCheck() &#123; Collection&lt;GlobalSession&gt; allSessions = sessionHolder.getAllSessions(); for (GlobalSession session : allSessions) &#123; if (session.getStatus() != GlobalStatus.Begin) &#123; continue; &#125; if (System.currentTimeMillis() - session.getBeginTime() &gt; session.getTimeout()) &#123; log.warn(&quot;Global transaction timeout, xid=&#123;&#125;&quot;, session.getXid()); try &#123; doGlobalRollback(session, false); &#125; catch (TransactionException e) &#123; log.error(&quot;Timeout rollback failed, xid=&#123;&#125;&quot;, session.getXid(), e); &#125; &#125; &#125; &#125; private void handleRetryCommit() &#123; Collection&lt;GlobalSession&gt; committingSessions = sessionHolder.getSessionsByStatus(GlobalStatus.CommitRetrying); for (GlobalSession session : committingSessions) &#123; try &#123; doGlobalCommit(session, true); &#125; catch (TransactionException e) &#123; log.error(&quot;Retry commit failed, xid=&#123;&#125;&quot;, session.getXid(), e); &#125; &#125; &#125; private void handleRetryRollback() &#123; Collection&lt;GlobalSession&gt; rollbackingSessions = sessionHolder.getSessionsByStatus(GlobalStatus.RollbackRetrying); for (GlobalSession session : rollbackingSessions) &#123; try &#123; doGlobalRollback(session, true); &#125; catch (TransactionException e) &#123; log.error(&quot;Retry rollback failed, xid=&#123;&#125;&quot;, session.getXid(), e); &#125; &#125; &#125;&#125;
一阶段与二阶段完整对比
对比维度 一阶段（Phase One） 二阶段-提交（Phase Two Commit） 二阶段-回滚（Phase Two Rollback）
执行者 RM TC 协调 + RM TC 协调 + RM
核心操作 拦截SQL + 生成undo_log + 注册分支 + 申请全局锁 + 本地提交 异步删除undo_log + 释放全局锁 校验After Image + 执行反向SQL + 删除undo_log + 释放全局锁
数据一致性 业务数据+undo_log原子提交 仅清理undo_log 根据undo_log反向补偿
耗时 较长（含业务逻辑+Before&#x2F;After Image查询） 极短（异步删除） 较长（需校验+执行反向SQL）
失败处理 报告TC，触发全局回滚 放入重试队列，异步重试 放入重试队列；不可重试则人工介入
锁状态 申请并持有全局锁 释放全局锁 释放全局锁
常见项目问题与解决方案在实际项目的生产实践中，我们遇到了大量与 Seata AT 模式相关的问题。以下是总结的 15 个常见问题与解决方案： 总结Seata AT 模式的源码揭示了以下核心设计思想：
代理模式零侵入：通过 DataSourceProxy → ConnectionProxy → PreparedStatementProxy 的代理链，拦截所有 SQL 执行，自动生成 Before&#x2F;After Image，对业务代码完全透明
两阶段提交的轻量化：一阶段业务数据和 undo_log 在同一个本地事务中提交（尽早释放本地锁），二阶段提交只需异步删除 undo_log（几乎零开销），回滚则根据 undo_log 反向补偿
全局锁保证隔离性：TC 管理行级全局锁，防止两个全局事务同时修改同一行数据。但全局锁不能防止本地事务的修改，这就是脏写问题的根源
After Image 校验防脏写：回滚前校验 After Image 与当前数据是否一致，不一致说明数据已被本地事务修改，不能自动回滚，需人工介入
XID 传播机制：通过 RootContext（ThreadLocal）存储 XID，通过 HTTP&#x2F;RPC 拦截器在微服务间传播，实现跨服务全局事务的串联
逆序回滚保证一致性：回滚时按照分支注册的逆序回滚，先注册的后回滚，确保数据恢复的正确性
异步+重试的容错设计：二阶段提交异步删除 undo_log 不阻塞主流程；提交&#x2F;回滚失败时放入重试队列由定时任务异步重试，保证最终一致性
在实际场景中，我们正是基于对源码的深入理解，才得以正确配置和使用 Seata AT 模式——合理设置超时时间、正确配置数据源代理、处理 XID 线程传播、规避全局锁冲突、应对回滚失败场景。理解源码，才能在生产环境中正确使用和高效排错。

前言在实际项目的持续迭代中，数据导出功能从最初简单的Excel导出，逐步演变为需要支持CSV、PDF等多种格式，并且还要支持加密、压缩、水印、分页、审计日志等附加功能。早期我们采用”每种组合写一个类”的方式，3种格式乘以3种功能就是9个类，4种格式乘以5种功能直接飙升到20个类——类爆炸问题触目惊心。更致命的是，每新增一种格式或功能，所有排列组合都需要新增类，代码维护成本指数级增长。 工厂模式解决了”创建什么”的问题——根据导出类型动态创建对应的导出器；装饰器模式解决了”功能组合”的问题——动态叠加加密、压缩、水印等功能，像套娃一样层层包装。两者配合，4种格式+5种功能只需9个类而非20个，新增格式只需一个实现类，新增功能只需一个装饰器。 本文将以实际项目的导出功能为实战场景，从问题出发，系统性地阐述工厂模式与装饰器模式的设计原理、源码实现、组合策略、踩坑记录与最佳实践。
导出功能的演进历程阶段一：单格式导出项目初期，只有设备台账导出为Excel的需求。代码简单粗暴——一个 ExcelExportUtil 工具类搞定一切： public class ExcelExportUtil &#123; public static byte[] exportDeviceLedger(List&lt;Device&gt; devices) &#123; // 直接写死Excel生成逻辑 Workbook workbook = new XSSFWorkbook(); Sheet sheet = workbook.createSheet(&quot;设备台账&quot;); // ... 200行硬编码 return toBytes(workbook); &#125;&#125;
这一阶段的问题：导出逻辑与业务逻辑耦合，一个方法里混杂了数据查询、格式化、样式设置、文件生成四种职责。 阶段二：多格式导出随着业务发展，需要支持CSV和PDF导出。直觉做法是再写两个工具类： ExcelExportUtil -&gt; 设备台账ExcelCsvExportUtil -&gt; 设备台账CSVPdfExportUtil -&gt; 设备台账PDFExcelExportUtil -&gt; 巡检记录Excel（需求来了，再写一遍？）CsvExportUtil -&gt; 巡检记录CSVPdfExportUtil -&gt; 巡检记录PDF...
问题暴露：格式与业务数据两维组合，每新增一种业务数据就要写N个格式的工具类，代码大量重复。 阶段三：格式与功能组合爆炸真正的噩梦开始——产品提出了加密、压缩、水印需求： 导出格式: Excel / CSV / PDF / Word (4种)附加功能: 加密 / 压缩 / 水印 / 分页 / 审计日志 (5种)排列组合: 4 × 2^5 = 128种可能如果每种组合写一个类: ExcelExportService EncryptedExcelExportService CompressedExcelExportService WatermarkedExcelExportService EncryptedCompressedExcelExportService EncryptedWatermarkedExcelExportService ... (128个类)
这种方案的致命缺陷： 格式维度: Excel CSV PDF Word …：
┃ ┃ ┃ ┃ 功能维度: 加密 × 压缩 × 水印 × 分页 × 审计 ┃ ┃ ┃ ┃ ┃ 组合数量: N × 2^M N&#x3D;4, M&#x3D;5 → 128个类 N&#x3D;5, M&#x3D;6 → 320个类 N&#x3D;6, M&#x3D;7 → 768个类 → 不可维护，不可扩展
阶段四：工厂+装饰器的解耦方案引入工厂模式和装饰器模式后，架构彻底改观： 工厂模式: 解决&quot;创建什么&quot; → N种格式 = N个导出器实现类装饰器模式: 解决&quot;功能组合&quot; → M种功能 = M个装饰器总类数: N + M 4种格式 + 5种功能 = 9个类（而非128个） 5种格式 + 6种功能 = 11个类（而非320个） 6种格式 + 7种功能 = 13个类（而非768个）
工厂模式详解模式定义工厂方法模式（Factory Method Pattern）定义了一个创建对象的接口，但由子类决定要实例化的类是哪一个。工厂方法让类把实例化推迟到子类。 在实际场景中，我们使用的是工厂模式的变体——基于Spring自动注册的工厂，利用Spring的依赖注入自动收集所有导出器实现，无需手动注册。 核心角色架构流程： flowchart TD N1[&quot;工厂模式结构&quot;] N2[&quot;DataExporter&quot;] N3[&quot;ExporterFactory (接口)&quot;] N4[&quot;(工厂)&quot;] N5[&quot;Excel&quot;] N6[&quot;CSV PDF Word&quot;] N7[&quot;Exporter Exporter&quot;] N8[&quot;Excel CSV PDF Word&quot;] N1 --&gt; N2 N1 --&gt; N3 N1 --&gt; N4 N2 --&gt; N3 N2 --&gt; N4 N3 --&gt; N2 N3 --&gt; N4 N4 --&gt; N2 N4 --&gt; N3 N2 --&gt; N5 N2 --&gt; N6 N2 --&gt; N7 N3 --&gt; N5 N3 --&gt; N6 N3 --&gt; N7 N4 --&gt; N5 N4 --&gt; N6 N4 --&gt; N7 N5 --&gt; N8 N5 --&gt; N7 N6 --&gt; N8 N6 --&gt; N7 N7 --&gt; N8
导出器接口public interface DataExporter &#123; /** * 获取导出类型 */ ExportType getType(); /** * 导出数据 * @param data 导出数据模型 * @return 导出文件字节数组 */ byte[] export(ExportData data);&#125;
导出类型枚举@Getter@AllArgsConstructorpublic enum ExportType &#123; EXCEL(&quot;xlsx&quot;, &quot;application/vnd.openxmlformats-officedocument.spreadsheetml.sheet&quot;), CSV(&quot;csv&quot;, &quot;text/csv&quot;), PDF(&quot;pdf&quot;, &quot;application/pdf&quot;), WORD(&quot;docx&quot;, &quot;application/vnd.openxmlformats-officedocument.wordprocessingml.document&quot;); private final String extension; private final String contentType;&#125;
导出数据模型@Getter@Setter@Builderpublic class ExportData &#123; /** 工作表名称 / 文件标题 */ private String sheetName; /** 表头列表 */ private List&lt;String&gt; headers; /** 数据行 */ private List&lt;List&lt;String&gt;&gt; rows; /** 水印文本（装饰器可设置） */ private String watermark; /** 元数据（扩展用） */ private Map&lt;String, String&gt; metadata; /** * 快速构建导出数据 */ public static ExportData of(String sheetName, List&lt;String&gt; headers, List&lt;List&lt;String&gt;&gt; rows) &#123; return ExportData.builder() .sheetName(sheetName) .headers(headers) .rows(rows) .metadata(new HashMap&lt;&gt;()) .build(); &#125;&#125;
Excel导出器实现实际项目中对Excel导出有严格的样式要求：表头加粗居中、数据行交替背景色、自适应列宽、大文件使用SXSSFWorkbook流式写入。 @Service@Slf4jpublic class ExcelExporter implements DataExporter &#123; private static final int STREAM_THRESHOLD = 1000; @Override public ExportType getType() &#123; return ExportType.EXCEL; &#125; @Override public byte[] export(ExportData data) &#123; log.info(&quot;导出Excel: sheet=&#123;&#125;, 数据量=&#123;&#125;条&quot;, data.getSheetName(), data.getRows().size()); int rowCount = data.getRows().size(); // 大数据量使用流式写入，避免OOM try (Workbook workbook = rowCount &gt; STREAM_THRESHOLD ? new SXSSFWorkbook(100) : new XSSFWorkbook()) &#123; Sheet sheet = workbook.createSheet(data.getSheetName()); // 表头样式 CellStyle headerStyle = createHeaderStyle(workbook); CellStyle oddRowStyle = createOddRowStyle(workbook); CellStyle evenRowStyle = createEvenRowStyle(workbook); // 写表头 Row headerRow = sheet.createRow(0); for (int i = 0; i &lt; data.getHeaders().size(); i++) &#123; Cell cell = headerRow.createCell(i); cell.setCellValue(data.getHeaders().get(i)); cell.setCellStyle(headerStyle); &#125; // 写数据 for (int i = 0; i &lt; rowCount; i++) &#123; Row row = sheet.createRow(i + 1); List&lt;String&gt; rowData = data.getRows().get(i); CellStyle rowStyle = (i % 2 == 0) ? oddRowStyle : evenRowStyle; for (int j = 0; j &lt; rowData.size(); j++) &#123; Cell cell = row.createCell(j); cell.setCellValue(rowData.get(j)); cell.setCellStyle(rowStyle); &#125; &#125; // 自适应列宽 for (int i = 0; i &lt; data.getHeaders().size(); i++) &#123; sheet.autoSizeColumn(i); &#125; byte[] result = toBytes(workbook); // 流式写入需要清理临时文件 if (workbook instanceof SXSSFWorkbook) &#123; ((SXSSFWorkbook) workbook).dispose(); &#125; log.info(&quot;Excel导出完成: 大小=&#123;&#125;KB&quot;, result.length / 1024); return result; &#125; catch (IOException e) &#123; throw new BusinessException(&quot;导出Excel失败: &quot; + e.getMessage(), e); &#125; &#125; private CellStyle createHeaderStyle(Workbook workbook) &#123; CellStyle style = workbook.createCellStyle(); Font font = workbook.createFont(); font.setBold(true); font.setFontHeightInPoints((short) 12); style.setFont(font); style.setAlignment(HorizontalAlignment.CENTER); style.setVerticalAlignment(VerticalAlignment.CENTER); style.setFillForegroundColor(IndexedColors.GREY_25_PERCENT.getIndex()); style.setFillPattern(FillPatternType.SOLID_FOREGROUND); style.setBorderBottom(BorderStyle.THIN); style.setBorderTop(BorderStyle.THIN); style.setBorderLeft(BorderStyle.THIN); style.setBorderRight(BorderStyle.THIN); return style; &#125; private CellStyle createOddRowStyle(Workbook workbook) &#123; CellStyle style = workbook.createCellStyle(); style.setBorderBottom(BorderStyle.THIN); style.setBorderTop(BorderStyle.THIN); style.setBorderLeft(BorderStyle.THIN); style.setBorderRight(BorderStyle.THIN); return style; &#125; private CellStyle createEvenRowStyle(Workbook workbook) &#123; CellStyle style = createOddRowStyle(workbook); style.setFillForegroundColor(IndexedColors.PALE_BLUE.getIndex()); style.setFillPattern(FillPatternType.SOLID_FOREGROUND); return style; &#125; private byte[] toBytes(Workbook workbook) throws IOException &#123; ByteArrayOutputStream out = new ByteArrayOutputStream(); workbook.write(out); return out.toByteArray(); &#125;&#125;
CSV导出器实现实际项目要求CSV文件必须包含BOM头（解决Excel打开中文乱码）、逗号转义、换行符转义。 @Service@Slf4jpublic class CsvExporter implements DataExporter &#123; private static final byte[] BOM = &#123;(byte) 0xEF, (byte) 0xBB, (byte) 0xBF&#125;; private static final String DELIMITER = &quot;,&quot;; private static final String QUOTE = &quot;\&quot;&quot;; @Override public ExportType getType() &#123; return ExportType.CSV; &#125; @Override public byte[] export(ExportData data) &#123; log.info(&quot;导出CSV: 数据量=&#123;&#125;条&quot;, data.getRows().size()); try (ByteArrayOutputStream out = new ByteArrayOutputStream()) &#123; // 写入BOM头（解决Excel打开中文乱码） out.write(BOM); // 写表头 out.write(toCsvRow(data.getHeaders()).getBytes(StandardCharsets.UTF_8)); // 写数据 for (List&lt;String&gt; row : data.getRows()) &#123; out.write(toCsvRow(row).getBytes(StandardCharsets.UTF_8)); &#125; byte[] result = out.toByteArray(); log.info(&quot;CSV导出完成: 大小=&#123;&#125;KB&quot;, result.length / 1024); return result; &#125; catch (IOException e) &#123; throw new BusinessException(&quot;导出CSV失败&quot;, e); &#125; &#125; private String toCsvRow(List&lt;String&gt; values) &#123; StringBuilder sb = new StringBuilder(); for (int i = 0; i &lt; values.size(); i++) &#123; if (i &gt; 0) &#123; sb.append(DELIMITER); &#125; sb.append(escapeCsvValue(values.get(i))); &#125; sb.append(&quot;\n&quot;); return sb.toString(); &#125; /** * CSV值转义规则： * 1. 包含逗号、双引号、换行符的值必须用双引号包裹 * 2. 双引号本身需要转义为两个双引号 */ private String escapeCsvValue(String value) &#123; if (value == null) &#123; return &quot;&quot;; &#125; if (value.contains(DELIMITER) || value.contains(QUOTE) || value.contains(&quot;\n&quot;)) &#123; return QUOTE + value.replace(QUOTE, QUOTE + QUOTE) + QUOTE; &#125; return value; &#125;&#125;
PDF导出器实现实际项目要求PDF导出支持横向A4排版、中文字体、表格样式、页眉页脚。 @Service@Slf4jpublic class PdfExporter implements DataExporter &#123; /** 中文字体路径（项目部署在Linux服务器，需预装字体） */ private static final String FONT_PATH = &quot;/usr/share/fonts/simhei.ttf&quot;; @Override public ExportType getType() &#123; return ExportType.PDF; &#125; @Override public byte[] export(ExportData data) &#123; log.info(&quot;导出PDF: 数据量=&#123;&#125;条&quot;, data.getRows().size()); try (ByteArrayOutputStream out = new ByteArrayOutputStream()) &#123; Document document = new Document(PageSize.A4.rotate(), 36, 36, 50, 50); PdfWriter writer = PdfWriter.getInstance(document, out); // 页眉页脚 writer.setPageEvent(new PdfHeaderFooter(data.getSheetName())); document.open(); // 中文字体 BaseFont baseFont = BaseFont.createFont(FONT_PATH, BaseFont.IDENTITY_H, BaseFont.NOT_EMBEDDED); Font headerFont = new Font(baseFont, 10, Font.BOLD); Font dataFont = new Font(baseFont, 9, Font.NORMAL); // 表格 PdfPTable table = new PdfPTable(data.getHeaders().size()); table.setWidthPercentage(100); // 表头 for (String header : data.getHeaders()) &#123; PdfPCell cell = new PdfPCell(new Phrase(header, headerFont)); cell.setBackgroundColor(BaseColor.LIGHT_GRAY); cell.setHorizontalAlignment(Element.ALIGN_CENTER); cell.setPadding(8); table.addCell(cell); &#125; // 数据行 for (List&lt;String&gt; row : data.getRows()) &#123; for (String cellValue : row) &#123; PdfPCell cell = new PdfPCell(new Phrase(cellValue, dataFont)); cell.setPadding(5); table.addCell(cell); &#125; &#125; document.add(table); document.close(); byte[] result = out.toByteArray(); log.info(&quot;PDF导出完成: 大小=&#123;&#125;KB&quot;, result.length / 1024); return result; &#125; catch (Exception e) &#123; throw new BusinessException(&quot;导出PDF失败: &quot; + e.getMessage(), e); &#125; &#125; /** * PDF页眉页脚事件 */ static class PdfHeaderFooter extends PdfPageEventHelper &#123; private final String title; private int pageCount; PdfHeaderFooter(String title) &#123; this.title = title; &#125; @Override public void onEndPage(PdfWriter writer, Document document) &#123; PdfContentByte canvas = writer.getDirectContent(); Rectangle pageSize = document.getPageSize(); // 页眉 ColumnText.showTextAligned(canvas, Element.ALIGN_LEFT, new Phrase(title), pageSize.getLeft(36), pageSize.getTop(30), 0); // 页脚 ColumnText.showTextAligned(canvas, Element.ALIGN_CENTER, new Phrase(String.format(&quot;第 %d 页&quot;, ++pageCount)), pageSize.getWidth() / 2, pageSize.getBottom(20), 0); &#125; &#125;&#125;
Word导出器实现@Service@Slf4jpublic class WordExporter implements DataExporter &#123; @Override public ExportType getType() &#123; return ExportType.WORD; &#125; @Override public byte[] export(ExportData data) &#123; log.info(&quot;导出Word: 数据量=&#123;&#125;条&quot;, data.getRows().size()); try (XWPFDocument document = new XWPFDocument()) &#123; // 标题 XWPFParagraph titlePara = document.createParagraph(); titlePara.setAlignment(ParagraphAlignment.CENTER); XWPFRun titleRun = titlePara.createRun(); titleRun.setText(data.getSheetName()); titleRun.setBold(true); titleRun.setFontSize(16); // 表格 XWPFTable table = document.createTable( data.getRows().size() + 1, data.getHeaders().size()); table.setWidth(&quot;100%&quot;); // 表头 XWPFTableRow headerRow = table.getRow(0); for (int i = 0; i &lt; data.getHeaders().size(); i++) &#123; XWPFTableCell cell = headerRow.getCell(i); cell.setText(data.getHeaders().get(i)); cell.setColor(&quot;D9E2F3&quot;); &#125; // 数据行 for (int i = 0; i &lt; data.getRows().size(); i++) &#123; XWPFTableRow row = table.getRow(i + 1); List&lt;String&gt; rowData = data.getRows().get(i); for (int j = 0; j &lt; rowData.size(); j++) &#123; row.getCell(j).setText(rowData.get(j)); &#125; &#125; ByteArrayOutputStream out = new ByteArrayOutputStream(); document.write(out); byte[] result = out.toByteArray(); log.info(&quot;Word导出完成: 大小=&#123;&#125;KB&quot;, result.length / 1024); return result; &#125; catch (IOException e) &#123; throw new BusinessException(&quot;导出Word失败&quot;, e); &#125; &#125;&#125;
Spring自动注册工厂利用Spring的依赖注入，自动收集所有 DataExporter 实现类并注册到工厂中。新增导出格式时，只需新增一个实现类并标注 @Service，工厂自动感知，零修改。 @Component@Slf4jpublic class ExporterFactory &#123; /** * 导出器注册表：ExportType -&gt; DataExporter * Spring自动注入所有DataExporter实现类 */ private final Map&lt;ExportType, DataExporter&gt; exporterMap; /** * 构造时自动收集所有DataExporter实现 * Spring会将所有标注@Service的DataExporter实现类注入List */ public ExporterFactory(List&lt;DataExporter&gt; exporters) &#123; this.exporterMap = exporters.stream() .collect(Collectors.toMap( DataExporter::getType, Function.identity(), (existing, replacement) -&gt; &#123; log.warn(&quot;重复的导出器类型注册: &#123;&#125;, 保留: &#123;&#125;&quot;, existing.getClass().getSimpleName(), replacement.getClass().getSimpleName()); return replacement; &#125; )); log.info(&quot;导出器工厂初始化完成，注册导出器: &#123;&#125;&quot;, exporterMap.entrySet().stream() .map(e -&gt; e.getKey() + &quot;=&quot; + e.getValue().getClass().getSimpleName()) .collect(Collectors.joining(&quot;, &quot;))); &#125; /** * 根据导出类型获取对应的导出器 */ public DataExporter getExporter(ExportType type) &#123; DataExporter exporter = exporterMap.get(type); if (exporter == null) &#123; throw new BusinessException(&quot;不支持的导出类型: &quot; + type); &#125; return exporter; &#125; /** * 获取所有支持的导出类型 */ public Set&lt;ExportType&gt; getSupportedTypes() &#123; return Collections.unmodifiableSet(exporterMap.keySet()); &#125;&#125;
工厂模式在实际项目中的使用场景智慧矿山导出场景总览：
设备台账导出 ──────┐ 巡检记录导出 ──────┤ 报警历史导出 ──────┤ ExporterFactory 人员轨迹导出 ──────┼─────► getExporter(EXCEL&#x2F;PDF&#x2F;CSV&#x2F;WORD) 通风数据导出 ──────┤ 排水数据导出 ──────┤ ▼ 安全日志导出 ──────┤ ExcelExporter &#x2F; CsvExporter &#x2F; … 产量统计导出 ──────┘ 新增导出场景: 业务侧构建 ExportData 即可，无需关心导出格式实现 新增导出格式: 新增一个 DataExporter 实现类，工厂自动注册
装饰器模式详解模式定义装饰器模式（Decorator Pattern）动态地给对象增加功能，是继承关系的一种替代方案。装饰器与被装饰的对象实现相同的接口，通过组合而非继承来扩展功能，避免了”子类爆炸”问题。 装饰器模式的核心思想：不修改原有对象，而是通过包装（Wrapper）的方式增强其功能。 核心角色架构流程： flowchart TD N1[&quot;装饰器模式结构&quot;] N2[&quot;DataExporter (组件接口)&quot;] N3[&quot;具体组件&quot;] N4[&quot;ExporterDecorator&quot;] N5[&quot;(装饰器抽象) (Excel等)&quot;] N6[&quot;delegate&quot;] N7[&quot;Encrypt Compress&quot;] N8[&quot;Watermark Decorator&quot;] N9[&quot;Decorator Decorator&quot;] N1 --&gt; N2 N2 --&gt; N3 N2 --&gt; N4 N2 --&gt; N5 N2 --&gt; N6 N3 --&gt; N4 N3 --&gt; N5 N3 --&gt; N6 N4 --&gt; N3 N4 --&gt; N5 N4 --&gt; N6 N5 --&gt; N3 N5 --&gt; N4 N5 --&gt; N6 N6 --&gt; N3 N6 --&gt; N4 N6 --&gt; N5 N3 --&gt; N7 N3 --&gt; N8 N3 --&gt; N9 N4 --&gt; N7 N4 --&gt; N8 N4 --&gt; N9 N5 --&gt; N7 N5 --&gt; N8 N5 --&gt; N9 N6 --&gt; N7 N6 --&gt; N8 N6 --&gt; N9 N7 --&gt; N8 N7 --&gt; N9 N8 --&gt; N7 N8 --&gt; N9 N9 --&gt; N7 N9 --&gt; N8
装饰器抽象基类/** * 导出器装饰器抽象基类 * 实现DataExporter接口，持有一个被装饰的导出器引用 * 所有具体装饰器继承此类，只需重写export方法 */public abstract class ExporterDecorator implements DataExporter &#123; protected DataExporter delegate; public ExporterDecorator(DataExporter delegate) &#123; Assert.notNull(delegate, &quot;被装饰的导出器不能为null&quot;); this.delegate = delegate; &#125; @Override public ExportType getType() &#123; return delegate.getType(); &#125; @Override public byte[] export(ExportData data) &#123; return delegate.export(data); &#125; /** * 获取被装饰链的描述（调试用） */ public String getDecoratorChain() &#123; StringBuilder sb = new StringBuilder(); sb.append(this.getClass().getSimpleName()); DataExporter current = this.delegate; while (current instanceof ExporterDecorator) &#123; sb.append(&quot; -&gt; &quot;).append(current.getClass().getSimpleName()); current = ((ExporterDecorator) current).delegate; &#125; sb.append(&quot; -&gt; &quot;).append(current.getClass().getSimpleName()); return sb.toString(); &#125;&#125;
加密装饰器实际场景中，安全日志和人员轨迹数据导出必须加密，采用AES-256加密后打包为ZIP格式。 @Slf4jpublic class EncryptExporterDecorator extends ExporterDecorator &#123; private final String password; private final EncryptAlgorithm algorithm; public EncryptExporterDecorator(DataExporter delegate, String password) &#123; this(delegate, password, EncryptAlgorithm.AES_256); &#125; public EncryptExporterDecorator(DataExporter delegate, String password, EncryptAlgorithm algorithm) &#123; super(delegate); Assert.hasText(password, &quot;加密密码不能为空&quot;); Assert.isTrue(password.length() &gt;= 6, &quot;密码长度不能少于6位&quot;); this.password = password; this.algorithm = algorithm; &#125; @Override public byte[] export(ExportData data) &#123; // 先执行内层导出，获取原始字节数组 byte[] rawBytes = delegate.export(data); log.info(&quot;对导出文件进行加密: 算法=&#123;&#125;, 原始大小=&#123;&#125;KB&quot;, algorithm, rawBytes.length / 1024); // 加密后打包为ZIP（带密码保护的ZIP） byte[] encrypted = Zip4jUtil.encrypt( rawBytes, password, getType().getExtension(), algorithm); log.info(&quot;加密完成: 加密后大小=&#123;&#125;KB&quot;, encrypted.length / 1024); return encrypted; &#125;&#125;/** * 加密算法枚举 */@Getter@AllArgsConstructorpublic enum EncryptAlgorithm &#123; AES_256(&quot;AES-256&quot;), ZIP_STANDARD(&quot;ZipStandard&quot;); private final String description;&#125;
压缩装饰器@Slf4jpublic class CompressExporterDecorator extends ExporterDecorator &#123; private static final int BUFFER_SIZE = 4096; private static final int COMPRESSION_LEVEL = Deflater.BEST_SPEED; // 兼顾速度和压缩率 private final String entryName; public CompressExporterDecorator(DataExporter delegate) &#123; this(delegate, null); &#125; public CompressExporterDecorator(DataExporter delegate, String entryName) &#123; super(delegate); this.entryName = entryName; &#125; @Override public byte[] export(ExportData data) &#123; byte[] rawBytes = delegate.export(data); log.info(&quot;对导出文件进行压缩: 原始大小=&#123;&#125;KB&quot;, rawBytes.length / 1024); // 小于1KB的文件不值得压缩 if (rawBytes.length &lt; 1024) &#123; log.info(&quot;文件过小，跳过压缩&quot;); return rawBytes; &#125; try (ByteArrayOutputStream out = new ByteArrayOutputStream()) &#123; ZipOutputStream zipOut = new ZipOutputStream(out); zipOut.setLevel(COMPRESSION_LEVEL); String fileName = entryName != null ? entryName : &quot;export.&quot; + getType().getExtension(); ZipEntry entry = new ZipEntry(fileName); zipOut.putNextEntry(entry); zipOut.write(rawBytes, 0, rawBytes.length); zipOut.closeEntry(); zipOut.finish(); byte[] compressed = out.toByteArray(); double ratio = (1 - (double) compressed.length / rawBytes.length) * 100; log.info(&quot;压缩完成: 压缩后=&#123;&#125;KB, 压缩率=&#123;:.1f&#125;%&quot;, compressed.length / 1024, ratio); return compressed; &#125; catch (IOException e) &#123; throw new BusinessException(&quot;导出文件压缩失败&quot;, e); &#125; &#125;&#125;
水印装饰器实际项目的水印需求分两类：
PDF&#x2F;Word：在文件内容中嵌入文字水印（如”内部资料 禁止外传”） Excel&#x2F;CSV：在数据中添加水印标记列
@Slf4jpublic class WatermarkExporterDecorator extends ExporterDecorator &#123; private final String watermarkText; private final WatermarkPosition position; private final float fontSize; private final int opacity; // 0-255 public WatermarkExporterDecorator(DataExporter delegate, String watermarkText) &#123; this(delegate, watermarkText, WatermarkPosition.CENTER, 48, 60); &#125; public WatermarkExporterDecorator(DataExporter delegate, String watermarkText, WatermarkPosition position, float fontSize, int opacity) &#123; super(delegate); Assert.hasText(watermarkText, &quot;水印文本不能为空&quot;); this.watermarkText = watermarkText; this.position = position; this.fontSize = fontSize; this.opacity = opacity; &#125; @Override public byte[] export(ExportData data) &#123; log.info(&quot;添加水印: text=&#123;&#125;, position=&#123;&#125;&quot;, watermarkText, position); // 根据导出类型选择水印实现方式 switch (getType()) &#123; case PDF: data.setWatermark(watermarkText); byte[] pdfBytes = delegate.export(data); return addPdfWatermark(pdfBytes); case EXCEL: data.setWatermark(watermarkText); return delegate.export(data); default: // CSV/Word等格式，在元数据中标记水印 data.getMetadata().put(&quot;watermark&quot;, watermarkText); return delegate.export(data); &#125; &#125; /** * PDF水印：使用iText在已有PDF上叠加水印文字 */ private byte[] addPdfWatermark(byte[] pdfBytes) &#123; try (ByteArrayOutputStream out = new ByteArrayOutputStream(); PdfReader reader = new PdfReader(pdfBytes); PdfStamper stamper = new PdfStamper(reader, out)) &#123; BaseFont baseFont = BaseFont.createFont( &quot;/usr/share/fonts/simhei.ttf&quot;, BaseFont.IDENTITY_H, BaseFont.NOT_EMBEDDED); int pageCount = reader.getNumberOfPages(); for (int i = 1; i &lt;= pageCount; i++) &#123; PdfContentByte canvas = stamper.getOverContent(i); Rectangle pageSize = reader.getPageSize(i); float x = pageSize.getWidth() / 2; float y = pageSize.getHeight() / 2; canvas.beginText(); canvas.setFontAndSize(baseFont, fontSize); canvas.setColorFill(new BaseColor(200, 200, 200, opacity)); canvas.showTextAligned(Element.ALIGN_CENTER, watermarkText, x, y, 45); canvas.endText(); &#125; stamper.close(); return out.toByteArray(); &#125; catch (Exception e) &#123; log.warn(&quot;PDF水印添加失败，返回原始文件&quot;, e); return pdfBytes; // 水印失败不影响导出 &#125; &#125;&#125;@Getter@AllArgsConstructorpublic enum WatermarkPosition &#123; CENTER(&quot;居中&quot;), DIAGONAL(&quot;对角线&quot;), HEADER(&quot;页眉&quot;), FOOTER(&quot;页脚&quot;); private final String description;&#125;
分页装饰器实际项目导出的设备台账动辄上万条，单文件打开极慢。分页装饰器将大数据集拆分为多个子文件，然后打包为ZIP。 @Slf4jpublic class PaginationExporterDecorator extends ExporterDecorator &#123; private final int pageSize; public PaginationExporterDecorator(DataExporter delegate, int pageSize) &#123; super(delegate); Assert.isTrue(pageSize &gt; 0, &quot;每页数据量必须大于0&quot;); this.pageSize = pageSize; &#125; @Override public byte[] export(ExportData data) &#123; int totalRows = data.getRows().size(); log.info(&quot;分页导出: 总数据=&#123;&#125;条, 每页=&#123;&#125;条&quot;, totalRows, pageSize); // 数据量不足一页，不需要分页 if (totalRows &lt;= pageSize) &#123; return delegate.export(data); &#125; int totalPages = (totalRows + pageSize - 1) / pageSize; List&lt;byte[]&gt; pageFiles = new ArrayList&lt;&gt;(); for (int page = 0; page &lt; totalPages; page++) &#123; int fromIndex = page * pageSize; int toIndex = Math.min(fromIndex + pageSize, totalRows); // 构建当前页的导出数据 ExportData pageData = ExportData.builder() .sheetName(data.getSheetName() + &quot;_&quot; + (page + 1)) .headers(data.getHeaders()) .rows(data.getRows().subList(fromIndex, toIndex)) .metadata(data.getMetadata()) .build(); byte[] pageBytes = delegate.export(pageData); pageFiles.add(pageBytes); log.info(&quot;第&#123;&#125;/&#123;&#125;页导出完成: &#123;&#125;条数据&quot;, page + 1, totalPages, toIndex - fromIndex); &#125; // 多个文件打包为ZIP return packToZip(pageFiles, data.getSheetName()); &#125; private byte[] packToZip(List&lt;byte[]&gt; files, String baseName) &#123; try (ByteArrayOutputStream out = new ByteArrayOutputStream()) &#123; ZipOutputStream zipOut = new ZipOutputStream(out); for (int i = 0; i &lt; files.size(); i++) &#123; String entryName = String.format(&quot;%s_%03d.%s&quot;, baseName, i + 1, getType().getExtension()); zipOut.putNextEntry(new ZipEntry(entryName)); zipOut.write(files.get(i)); zipOut.closeEntry(); &#125; zipOut.finish(); byte[] result = out.toByteArray(); log.info(&quot;分页ZIP打包完成: &#123;&#125;个文件, 总大小=&#123;&#125;KB&quot;, files.size(), result.length / 1024); return result; &#125; catch (IOException e) &#123; throw new BusinessException(&quot;分页文件打包失败&quot;, e); &#125; &#125;&#125;
审计日志装饰器安全合规要求：所有导出操作必须记录审计日志，包括操作人、导出内容、导出时间、数据范围等。 @Slf4jpublic class AuditLogExporterDecorator extends ExporterDecorator &#123; private final String operator; private final String operationDesc; private final ExportAuditLogService auditLogService; public AuditLogExporterDecorator(DataExporter delegate, String operator, String operationDesc, ExportAuditLogService auditLogService) &#123; super(delegate); Assert.hasText(operator, &quot;操作人不能为空&quot;); this.operator = operator; this.operationDesc = operationDesc; this.auditLogService = auditLogService; &#125; @Override public byte[] export(ExportData data) &#123; long startTime = System.currentTimeMillis(); ExportAuditLog auditLog = new ExportAuditLog(); auditLog.setOperator(operator); auditLog.setExportType(getType().name()); auditLog.setSheetName(data.getSheetName()); auditLog.setRowCount(data.getRows().size()); auditLog.setOperationDesc(operationDesc); auditLog.setExportTime(LocalDateTime.now()); try &#123; byte[] result = delegate.export(data); long duration = System.currentTimeMillis() - startTime; auditLog.setStatus(&quot;SUCCESS&quot;); auditLog.setFileSize(result.length); auditLog.setDurationMs(duration); log.info(&quot;导出审计: operator=&#123;&#125;, type=&#123;&#125;, rows=&#123;&#125;, size=&#123;&#125;KB, duration=&#123;&#125;ms&quot;, operator, getType(), data.getRows().size(), result.length / 1024, duration); return result; &#125; catch (Exception e) &#123; long duration = System.currentTimeMillis() - startTime; auditLog.setStatus(&quot;FAILED&quot;); auditLog.setErrorMessage(e.getMessage()); auditLog.setDurationMs(duration); log.error(&quot;导出审计(失败): operator=&#123;&#125;, type=&#123;&#125;, error=&#123;&#125;&quot;, operator, getType(), e.getMessage()); throw e; &#125; finally &#123; // 无论成功失败都记录审计日志 auditLogService.saveAuditLog(auditLog); &#125; &#125;&#125;
工厂与装饰器的组合策略导出请求模型@Getter@Setter@Builderpublic class ExportRequest &#123; /** 导出格式 */ private ExportType exportType; /** 业务数据类型（设备台账/巡检记录/报警历史等） */ private String businessType; /** 查询参数 */ private Map&lt;String, Object&gt; queryParams; // ---- 装饰器开关 ---- /** 是否需要水印 */ private boolean needWatermark; /** 水印文本 */ private String watermarkText; /** 是否需要加密 */ private boolean needEncrypt; /** 加密密码 */ private String password; /** 是否需要压缩 */ private boolean needCompress; /** 是否需要分页 */ private needPagination; /** 每页数据量 */ private int pageSize; /** 是否需要审计日志 */ private boolean needAuditLog; /** 操作人 */ private String operator; /** 操作描述 */ private String operationDesc;&#125;
导出服务——灵活组合@Service@Slf4jpublic class ExportService &#123; @Autowired private ExporterFactory exporterFactory; @Autowired private ExportAuditLogService auditLogService; /** * 核心导出方法：工厂创建基础导出器 → 装饰器叠加功能 → 执行导出 */ public byte[] export(ExportRequest request) &#123; log.info(&quot;导出请求: type=&#123;&#125;, business=&#123;&#125;, watermark=&#123;&#125;, encrypt=&#123;&#125;, compress=&#123;&#125;, pagination=&#123;&#125;&quot;, request.getExportType(), request.getBusinessType(), request.isNeedWatermark(), request.isNeedEncrypt(), request.isNeedCompress(), request.isNeedPagination()); // 1. 工厂创建基础导出器 DataExporter exporter = exporterFactory.getExporter(request.getExportType()); // 2. 按顺序叠加装饰器 // 装饰顺序很重要：最外层最后执行，最内层最先执行 // 推荐顺序：审计(最外层) → 分页 → 压缩 → 加密 → 水印 → 基础导出器 // 水印（最先包裹，最内层装饰器，最先对数据做处理） if (request.isNeedWatermark()) &#123; exporter = new WatermarkExporterDecorator( exporter, request.getWatermarkText()); &#125; // 加密 if (request.isNeedEncrypt()) &#123; exporter = new EncryptExporterDecorator( exporter, request.getPassword()); &#125; // 压缩 if (request.isNeedCompress()) &#123; exporter = new CompressExporterDecorator(exporter); &#125; // 分页 if (request.isNeedPagination()) &#123; exporter = new PaginationExporterDecorator( exporter, request.getPageSize()); &#125; // 审计日志（最外层，包裹整个装饰链） if (request.isNeedAuditLog()) &#123; exporter = new AuditLogExporterDecorator( exporter, request.getOperator(), request.getOperationDesc(), auditLogService); &#125; log.info(&quot;装饰链: &#123;&#125;&quot;, ((ExporterDecorator) exporter).getDecoratorChain()); // 3. 构建导出数据 ExportData data = buildExportData(request); // 4. 执行导出 return exporter.export(data); &#125; /** * 根据业务类型构建导出数据 */ private ExportData buildExportData(ExportRequest request) &#123; switch (request.getBusinessType()) &#123; case &quot;DEVICE_LEDGER&quot;: return buildDeviceLedgerData(request); case &quot;INSPECTION_RECORD&quot;: return buildInspectionRecordData(request); case &quot;ALARM_HISTORY&quot;: return buildAlarmHistoryData(request); case &quot;PERSONNEL_TRACK&quot;: return buildPersonnelTrackData(request); default: throw new BusinessException(&quot;不支持的业务类型: &quot; + request.getBusinessType()); &#125; &#125; // ... 各业务类型的ExportData构建方法省略&#125;
装饰器叠加顺序装饰器的叠加顺序至关重要，不同顺序产生不同效果： 装饰器执行顺序（洋葱模型）─────────────────────────────────────────────────────────────请求 → [审计日志 → [分页 → [压缩 → [加密 → [水印 → [基础导出器]]]]]]] │ │ │ │ │ │ │ │ │ │ │ └── 生成原始文件 │ │ │ │ └── 在数据/文件上添加水印 │ │ │ └── 对文件内容加密 │ │ └── 对加密后文件压缩 │ └── 对压缩后数据分页打包 └── 记录整个过程的审计日志为什么是这个顺序？─────────────────────────────────────────────────────────────1. 水印最内层：先处理数据，再生成文件，水印应在文件生成之前或同时2. 加密在压缩之前：先加密再压缩（压缩加密后的数据效果差，但安全性更高） → 实际项目中也可以先压缩再加密（压缩效果更好），根据需求选择3. 分页在压缩之前：先分页生成多个文件，再统一压缩为一个ZIP4. 审计最外层：记录整个导出过程的耗时和结果
两种装饰顺序对比
装饰顺序 优点 缺点 适用场景
加密 → 压缩 安全性更高，压缩包内是加密文件 压缩率低（加密数据难以压缩） 安全优先级高（安全日志、人员轨迹）
压缩 → 加密 压缩率高，压缩后再加密更节省空间 需要解密后才能验证压缩完整性 带宽优先级高（大数据量导出）
在实际场景中，我们统一采用”先加密再压缩”的顺序，因为安全优先于空间。
使用示例Controller层@RestController@RequestMapping(&quot;/api/export&quot;)@Slf4jpublic class ExportController &#123; @Autowired private ExportService exportService; /** * 通用导出接口 */ @PostMapping public void export(@RequestBody ExportRequest request, HttpServletResponse response) &#123; byte[] bytes = exportService.export(request); String fileName = buildFileName(request); writeResponse(response, bytes, fileName, request.getExportType().getContentType()); &#125; /** * 设备台账Excel导出（带水印） */ @GetMapping(&quot;/device/excel&quot;) public void exportDeviceExcel( @RequestParam String mineAreaCode, @RequestParam(required = false, defaultValue = &quot;false&quot;) boolean watermark, HttpServletResponse response) &#123; ExportRequest request = ExportRequest.builder() .exportType(ExportType.EXCEL) .businessType(&quot;DEVICE_LEDGER&quot;) .needWatermark(watermark) .watermarkText(&quot;智慧矿山 内部资料&quot;) .needAuditLog(true) .operator(SecurityUtils.getCurrentUserName()) .operationDesc(&quot;设备台账Excel导出&quot;) .queryParams(Map.of(&quot;mineAreaCode&quot;, mineAreaCode)) .build(); byte[] bytes = exportService.export(request); writeResponse(response, bytes, &quot;设备台账.xlsx&quot;, ExportType.EXCEL.getContentType()); &#125; /** * 安全日志加密PDF导出 */ @GetMapping(&quot;/safety/pdf/secure&quot;) public void exportSecureSafetyPdf( @RequestParam String startDate, @RequestParam String endDate, HttpServletResponse response) &#123; ExportRequest request = ExportRequest.builder() .exportType(ExportType.PDF) .businessType(&quot;ALARM_HISTORY&quot;) .needWatermark(true) .watermarkText(&quot;机密 禁止外传&quot;) .needEncrypt(true) .password(SecurityUtils.getCurrentPassword()) .needCompress(true) .needAuditLog(true) .operator(SecurityUtils.getCurrentUserName()) .operationDesc(&quot;安全日志加密PDF导出&quot;) .queryParams(Map.of(&quot;startDate&quot;, startDate, &quot;endDate&quot;, endDate)) .build(); byte[] bytes = exportService.export(request); writeResponse(response, bytes, &quot;安全日志.zip&quot;, &quot;application/zip&quot;); &#125; /** * 巡检记录分页CSV导出 */ @GetMapping(&quot;/inspection/csv/paged&quot;) public void exportPagedInspectionCsv( @RequestParam String mineAreaCode, @RequestParam(defaultValue = &quot;5000&quot;) int pageSize, HttpServletResponse response) &#123; ExportRequest request = ExportRequest.builder() .exportType(ExportType.CSV) .businessType(&quot;INSPECTION_RECORD&quot;) .needPagination(true) .pageSize(pageSize) .needAuditLog(true) .operator(SecurityUtils.getCurrentUserName()) .operationDesc(&quot;巡检记录分页CSV导出&quot;) .queryParams(Map.of(&quot;mineAreaCode&quot;, mineAreaCode)) .build(); byte[] bytes = exportService.export(request); writeResponse(response, bytes, &quot;巡检记录.zip&quot;, &quot;application/zip&quot;); &#125; /** * 人员轨迹加密Word导出 */ @GetMapping(&quot;/personnel/word/secure&quot;) public void exportSecurePersonnelWord( @RequestParam String personnelId, @RequestParam String date, HttpServletResponse response) &#123; ExportRequest request = ExportRequest.builder() .exportType(ExportType.WORD) .businessType(&quot;PERSONNEL_TRACK&quot;) .needWatermark(true) .watermarkText(&quot;机密 &quot; + SecurityUtils.getCurrentUserName()) .needEncrypt(true) .password(&quot;mine_secure_2024&quot;) .needAuditLog(true) .operator(SecurityUtils.getCurrentUserName()) .operationDesc(&quot;人员轨迹加密Word导出&quot;) .queryParams(Map.of(&quot;personnelId&quot;, personnelId, &quot;date&quot;, date)) .build(); byte[] bytes = exportService.export(request); writeResponse(response, bytes, &quot;人员轨迹.zip&quot;, &quot;application/zip&quot;); &#125; private void writeResponse(HttpServletResponse response, byte[] bytes, String fileName, String contentType) &#123; try &#123; response.setContentType(contentType); response.setHeader(&quot;Content-Disposition&quot;, &quot;attachment; filename=&quot; + URLEncoder.encode(fileName, &quot;UTF-8&quot;)); response.setContentLength(bytes.length); response.getOutputStream().write(bytes); response.getOutputStream().flush(); &#125; catch (IOException e) &#123; throw new BusinessException(&quot;写入响应流失败&quot;, e); &#125; &#125;&#125;
两种模式深度对比功能对比
维度 工厂模式 装饰器模式
解决的问题 创建什么对象 如何组合功能
核心思想 将对象创建与使用分离 动态组合替代静态继承
变化维度 对象类型变化（格式维度） 对象功能变化（功能维度）
扩展方式 新增实现类 新增装饰器类
设计原则 开闭原则（对扩展开放） 单一职责 + 开闭原则
客户端感知 只需知道类型，无需知道实现类 无需知道装饰了多少层
典型场景 根据条件创建不同策略 功能叠加、增强
类数量对比操作 不使用模式 工厂+装饰器 缩减比例：
───────────────────────────────────────────────────────── 新增1种格式 +2^5&#x3D;32个类 +1个类 97% 新增1种功能 +4个类 +1个类 75% 新增1格式+1功能 +64个类 +2个类 97%
结构对比不使用模式（继承爆炸）：───────────────────────────────────────────────────────── DataExporter / | \ ExcelExporter CSVExporter PdfExporter / \ | \ ExcelEncrypted ExcelCompressed ... （128个类）工厂 + 装饰器（组合替代继承）：─────────────────────────────────────────────────────────DataExporter ◄── ExporterDecorator ◄── EncryptDecorator ▲ ▲ ├── CompressDecorator │ │ ├── WatermarkDecoratorExcelExporter │ ├── PaginationDecoratorCsvExporter │ └── AuditLogDecoratorPdfExporter │WordExporter │ └── delegate 持有内层 DataExporter 引用类数量：4 + 5 = 9个组合能力：4 × 2^5 = 128种
其他设计模式的横向对比结构型模式对比工厂模式和装饰器模式分别属于创建型模式和结构型模式，在导出功能场景中，还有其他模式可供选择，但各有局限。 导出功能可选设计模式对比：
模式 类型 解决的问题 导出场景适用性 ──────────────────────────────────────────────────────────── 简单工厂 创建型 创建单一类型对象 ★★☆ 格式少时可用 工厂方法 创建型 创建多类型对象 ★★★ 格式多时推荐 抽象工厂 创建型 创建产品族 ★☆☆ 过度设计 策略模式 行为型 算法切换 ★★☆ 类似工厂但侧重行为 装饰器 结构型 功能叠加 ★★★ 功能组合推荐 代理模式 结构型 访问控制 ★★☆ 类似装饰器但侧重控制 责任链 行为型 请求处理链 ★★☆ 可替代装饰器 组合模式 结构型 树形结构 ☆☆☆ 不适用 桥接模式 结构型 多维度独立变化 ★★☆ 格式+功能可桥接
装饰器 vs 代理 vs 责任链这三种模式在结构上有相似之处，都通过包装对象来扩展功能，但意图和实现方式不同：
维度 装饰器模式 代理模式 责任链模式
意图 动态添加功能 控制对象访问 请求沿链传递
对象数量 多个装饰器可叠加 一个代理控制一个对象 多个处理器组成链
接口关系 装饰器与组件同接口 代理与被代理同接口 处理器各自独立接口
调用方式 委托给内层对象 可能不调用被代理对象 沿链传递，可能中断
典型场景 功能叠加 延迟加载、权限控制 审批流、过滤器
导出场景适用 ★★★ 功能组合 ★★☆ 权限校验 ★★☆ 导出前校验链
装饰器 vs 桥接两者都能解决多维度变化问题，但解决思路不同： 装饰器思路（动态组合）：─────────────────────────────────────────────────────────格式维度: Excel / CSV / PDF功能维度: 加密 / 压缩 / 水印运行时动态组合:new CompressDecorator(new EncryptDecorator(new ExcelExporter()))优点: 运行时灵活组合，无需预定义所有组合缺点: 装饰顺序影响结果，调试链路不直观桥接思路（静态分离）：─────────────────────────────────────────────────────────抽象层: DataExporter (含功能扩展点)实现层: ExcelImpl / CsvImpl / PdfImpl功能通过组合注入:ExcelExporter(FunctionExecutor functionExecutor)优点: 两个维度独立变化，结构清晰缺点: 功能扩展点需预先设计，不够灵活
在实际项目中我们选择装饰器而非桥接，原因：
功能数量和组合在项目初期无法完全预定义 装饰器允许运行时按需组合，更贴合业务需求 新增功能完全不需要修改已有代码
与其他语言的实现对比Go语言实现Go没有继承，使用接口组合和函数式选项模式实现类似效果： // 导出器接口type DataExporter interface &#123; GetType() ExportType Export(data ExportData) ([]byte, error)&#125;// 工厂函数func NewExporterFactory(exporters []DataExporter) *ExporterFactory &#123; m := make(map[ExportType]DataExporter) for _, e := range exporters &#123; m[e.GetType()] = e &#125; return &amp;ExporterFactory&#123;exporters: m&#125;&#125;// 装饰器（函数类型）type ExportDecorator func(DataExporter) DataExporter// 加密装饰器func WithEncrypt(password string) ExportDecorator &#123; return func(next DataExporter) DataExporter &#123; return &amp;encryptExporter&#123;delegate: next, password: password&#125; &#125;&#125;// 链式组合func Chain(base DataExporter, decorators ...ExportDecorator) DataExporter &#123; for _, d := range decorators &#123; base = d(base) &#125; return base&#125;// 使用exporter := Chain( excelExporter, WithWatermark(&quot;内部资料&quot;), WithEncrypt(&quot;password123&quot;), WithCompress(),)result, _ := exporter.Export(data)
Python实现Python使用装饰器语法糖更加简洁： from functools import wraps# 导出器接口（抽象基类）class DataExporter(ABC): @abstractmethod def get_type(self) -&gt; ExportType: ... @abstractmethod def export(self, data: ExportData) -&gt; bytes: ...# 装饰器函数def with_watermark(text: str): def decorator(cls): original_export = cls.export @wraps(original_export) def wrapped_export(self, data: ExportData) -&gt; bytes: data.watermark = text return original_export(self, data) cls.export = wrapped_export return cls return decorator# 类装饰器@with_watermark(&quot;内部资料&quot;)class ExcelExporter(DataExporter): ...
三种语言对比
维度 Java Go Python
装饰器实现 继承抽象类 函数组合 函数装饰器&#x2F;类装饰器
类型安全 编译期检查 编译期检查 运行期检查
组合方式 构造器嵌套 函数链 函数链&#x2F;注解
代码量 多（需要抽象类） 少 最少
可读性 中 高 高
IDE支持 好 好 一般
常见项目问题与解决方案以下是实际项目中导出功能遇到的真实问题及解决方案：
序号 问题 现象 原因分析 解决方案
1 类爆炸 导出类从4个暴增到20+ 每种格式×功能组合写一个类 引入工厂+装饰器，N+M替代N×2^M
2 导出器注册冲突 两个类返回相同ExportType，启动报错 多人开发时重复实现同一导出类型 工厂构造时检测重复注册，启动阶段即暴露问题
3 装饰器顺序错误 加密后压缩率极低，或水印未生效 装饰器叠加顺序不当，功能语义被覆盖 定义标准装饰顺序（水印→加密→压缩→分页→审计），代码注释明确
4 大数据量OOM 导出10万条数据时内存溢出 XSSFWorkbook将全部数据加载到内存 数据量&gt;1000时切换为SXSSFWorkbook流式写入
5 CSV中文乱码 Excel打开CSV文件中文乱码 缺少BOM头，Excel无法识别UTF-8编码 CSV文件开头写入BOM头：0xEF 0xBB 0xBF
6 PDF中文字体缺失 Linux服务器导出PDF中文显示为方块 服务器未安装中文字体 部署时预装SimHei字体，代码中指定字体路径
7 导出过程无审计 安全日志被非法导出但无记录 导出功能未接入审计系统 使用审计日志装饰器，无论成功失败都记录
8 加密后无法打开 用户收到加密ZIP但无法解压 加密算法不兼容，或密码错误 统一使用AES-256加密，提供解密工具和说明文档
9 水印只在PDF生效 Excel&#x2F;CSV导出后看不到水印 水印装饰器只实现了PDF分支 Excel通过背景图&#x2F;页眉实现水印，CSV在元数据中标记
10 分页导出文件名混乱 分页ZIP中文件名为export_1.xlsx 文件名未使用业务含义 分页装饰器使用sheetName作为文件名前缀
11 导出超时 大数据量导出超过30s网关超时 同步导出，线程阻塞等待 大数据量导出改为异步：提交任务→MQ通知→下载链接
12 装饰器链调试困难 出错时不知道是哪层装饰器的问题 多层装饰器嵌套，异常栈深 每层装饰器打印日志，getDecoratorChain()输出完整链路
13 重复导出相同数据 用户频繁点击导出按钮 前端未防抖，后端未缓存 前端按钮防抖+loading，后端相同参数5分钟内返回缓存
14 导出文件Content-Type错误 浏览器下载后无法正确打开 硬编码Content-Type为application&#x2F;octet-stream 使用ExportType枚举中的contentType，根据格式返回正确的MIME
15 并发导出导致数据不一致 导出过程中数据被修改，导出结果部分新部分旧 导出查询与业务操作并发执行 导出查询使用快照读（MySQL MVCC），或使用导出时间点的数据版本
高级主题：异步导出与流式导出异步导出方案当数据量超过一定阈值时，同步导出会导致HTTP请求超时。实际场景中，超过5000条数据自动切换为异步导出模式。 @Service@Slf4jpublic class AsyncExportService &#123; @Autowired private ExportService exportService; @Autowired private ExportTaskRepository taskRepository; @Autowired private RocketMQTemplate mqTemplate; @Autowired private OssClient ossClient; private static final int SYNC_THRESHOLD = 5000; /** * 智能导出：数据量小同步返回，数据量大异步处理 */ public ExportResult smartExport(ExportRequest request, int totalRows) &#123; if (totalRows &lt;= SYNC_THRESHOLD) &#123; // 同步导出 byte[] bytes = exportService.export(request); return ExportResult.sync(bytes); &#125; else &#123; // 异步导出：创建任务、发MQ、返回任务ID ExportTask task = createTask(request, totalRows); mqTemplate.asyncSend(&quot;export-task&quot;, toMessage(task), new SendCallback() &#123; @Override public void onSuccess(SendResult result) &#123; log.info(&quot;异步导出任务已提交: taskId=&#123;&#125;&quot;, task.getTaskId()); &#125; @Override public void onException(Throwable e) &#123; log.error(&quot;异步导出任务提交失败: taskId=&#123;&#125;&quot;, task.getTaskId(), e); taskRepository.updateStatus(task.getTaskId(), TaskStatus.FAILED); &#125; &#125;); return ExportResult.async(task.getTaskId()); &#125; &#125; /** * 异步导出消费者 */ @RocketMQMessageListener(topic = &quot;export-task&quot;, consumerGroup = &quot;export-consumer&quot;) @Service @Slf4j static class ExportTaskConsumer implements RocketMQListener&lt;String&gt; &#123; @Autowired private ExportService exportService; @Autowired private ExportTaskRepository taskRepository; @Autowired private OssClient ossClient; @Override public void onMessage(String message) &#123; ExportTask task = JsonUtils.fromJson(message, ExportTask.class); try &#123; taskRepository.updateStatus(task.getTaskId(), TaskStatus.PROCESSING); byte[] bytes = exportService.export(task.getRequest()); String fileUrl = ossClient.upload( bytes, task.getFileName(), task.getRequest().getExportType().getContentType()); taskRepository.updateStatus(task.getTaskId(), TaskStatus.COMPLETED, fileUrl); log.info(&quot;异步导出完成: taskId=&#123;&#125;, fileUrl=&#123;&#125;&quot;, task.getTaskId(), fileUrl); &#125; catch (Exception e) &#123; taskRepository.updateStatus(task.getTaskId(), TaskStatus.FAILED, e.getMessage()); log.error(&quot;异步导出失败: taskId=&#123;&#125;&quot;, task.getTaskId(), e); &#125; &#125; &#125;&#125;
异步导出流程Client ExportService RocketMQ Consumer：
POST &#x2F;export ─────────────────&gt; 判断数据量
5000?
──────┐ YES &lt;─────┘ 创建Task 发送MQ消息 ─────────────────&gt; 返回taskId &lt;───────────────── 消费消息 ───────────────&gt; 执行导出 上传OSS 更新Task GET &#x2F;export&#x2F;task&#x2F;{id} ─────────────────&gt; 返回下载链接 &lt;─────────────────
单元测试工厂模式测试@SpringBootTestclass ExporterFactoryTest &#123; @Autowired private ExporterFactory exporterFactory; @Test void should_get_excel_exporter() &#123; DataExporter exporter = exporterFactory.getExporter(ExportType.EXCEL); assertThat(exporter).isInstanceOf(ExcelExporter.class); &#125; @Test void should_get_csv_exporter() &#123; DataExporter exporter = exporterFactory.getExporter(ExportType.CSV); assertThat(exporter).isInstanceOf(CsvExporter.class); &#125; @Test void should_get_pdf_exporter() &#123; DataExporter exporter = exporterFactory.getExporter(ExportType.PDF); assertThat(exporter).isInstanceOf(PdfExporter.class); &#125; @Test void should_get_word_exporter() &#123; DataExporter exporter = exporterFactory.getExporter(ExportType.WORD); assertThat(exporter).isInstanceOf(WordExporter.class); &#125; @Test void should_throw_for_unsupported_type() &#123; assertThatThrownBy(() -&gt; exporterFactory.getExporter(null)) .isInstanceOf(BusinessException.class) .hasMessageContaining(&quot;不支持的导出类型&quot;); &#125; @Test void should_support_all_registered_types() &#123; Set&lt;ExportType&gt; types = exporterFactory.getSupportedTypes(); assertThat(types).containsExactlyInAnyOrder( ExportType.EXCEL, ExportType.CSV, ExportType.PDF, ExportType.WORD); &#125;&#125;
装饰器模式测试class ExporterDecoratorTest &#123; private ExportData testData; @BeforeEach void setUp() &#123; testData = ExportData.of(&quot;测试数据&quot;, List.of(&quot;姓名&quot;, &quot;年龄&quot;, &quot;部门&quot;), List.of( List.of(&quot;张三&quot;, &quot;30&quot;, &quot;安全部&quot;), List.of(&quot;李四&quot;, &quot;25&quot;, &quot;设备部&quot;), List.of(&quot;王五&quot;, &quot;35&quot;, &quot;通风部&quot;) )); &#125; @Test void should_encrypt_exported_file() &#123; // given DataExporter excelExporter = new ExcelExporter(); DataExporter encrypted = new EncryptExporterDecorator(excelExporter, &quot;test123&quot;); // when byte[] result = encrypted.export(testData); // then assertThat(result).isNotNull(); assertThat(result.length).isGreaterThan(0); // 加密后的文件应该是ZIP格式 assertThat(isValidZip(result)).isTrue(); &#125; @Test void should_compress_exported_file() &#123; // given DataExporter csvExporter = new CsvExporter(); DataExporter compressed = new CompressExporterDecorator(csvExporter); // when byte[] result = compressed.export(testData); // then assertThat(result).isNotNull(); assertThat(isValidZip(result)).isTrue(); &#125; @Test void should_add_watermark() &#123; // given DataExporter pdfExporter = new PdfExporter(); DataExporter watermarked = new WatermarkExporterDecorator( pdfExporter, &quot;内部资料 禁止外传&quot;); // when byte[] result = watermarked.export(testData); // then assertThat(result).isNotNull(); assertThat(result.length).isGreaterThan(0); &#125; @Test void should_chain_multiple_decorators() &#123; // given DataExporter exporter = new ExcelExporter(); exporter = new WatermarkExporterDecorator(exporter, &quot;机密&quot;); exporter = new EncryptExporterDecorator(exporter, &quot;password&quot;); exporter = new CompressExporterDecorator(exporter); // when byte[] result = exporter.export(testData); // then assertThat(result).isNotNull(); assertThat(isValidZip(result)).isTrue(); &#125; @Test void should_paginate_large_data() &#123; // given List&lt;List&lt;String&gt;&gt; largeRows = IntStream.range(0, 150) .mapToObj(i -&gt; List.of(&quot;Name&quot; + i, String.valueOf(20 + i % 30), &quot;Dept&quot; + i % 5)) .collect(Collectors.toList()); ExportData largeData = ExportData.of(&quot;大数据&quot;, List.of(&quot;姓名&quot;, &quot;年龄&quot;, &quot;部门&quot;), largeRows); DataExporter csvExporter = new CsvExporter(); DataExporter paginated = new PaginationExporterDecorator(csvExporter, 50); // when byte[] result = paginated.export(largeData); // then assertThat(result).isNotNull(); // 分页后应该是ZIP格式（包含3个CSV文件） assertThat(isValidZip(result)).isTrue(); &#125; @Test void should_record_audit_log() &#123; // given ExportAuditLogService mockAuditService = mock(ExportAuditLogService.class); DataExporter exporter = new ExcelExporter(); exporter = new AuditLogExporterDecorator( exporter, &quot;admin&quot;, &quot;测试导出&quot;, mockAuditService); // when byte[] result = exporter.export(testData); // then assertThat(result).isNotNull(); verify(mockAuditService, times(1)).saveAuditLog(any(ExportAuditLog.class)); &#125; @Test void should_record_audit_log_even_on_failure() &#123; // given ExportAuditLogService mockAuditService = mock(ExportAuditLogService.class); DataExporter failingExporter = mock(DataExporter.class); when(failingExporter.getType()).thenReturn(ExportType.EXCEL); when(failingExporter.export(any())).thenThrow(new BusinessException(&quot;导出失败&quot;)); DataExporter exporter = new AuditLogExporterDecorator( failingExporter, &quot;admin&quot;, &quot;测试导出&quot;, mockAuditService); // when &amp; then assertThatThrownBy(() -&gt; exporter.export(testData)) .isInstanceOf(BusinessException.class); verify(mockAuditService, times(1)).saveAuditLog( argThat(log -&gt; &quot;FAILED&quot;.equals(log.getStatus()))); &#125; private boolean isValidZip(byte[] data) &#123; try (ZipInputStream zis = new ZipInputStream(new ByteArrayInputStream(data))) &#123; return zis.getNextEntry() != null; &#125; catch (IOException e) &#123; return false; &#125; &#125;&#125;
设计模式选择的决策树流程步骤：
需要扩展导出功能？ ┌────────┴────────┐ YES NO ▼ ▼ 扩展的维度？ 当前方案足够 ┌──────────┼──────────┐ ▼ ▼ ▼ 对象类型 功能叠加 两者都有 变化 变化 ▼ ▼ ▼ 工厂模式 装饰器模式 工厂+装饰器 ┌──────────┼──────────┐ ▼ ▼ ▼ 格式不多 格式多 需要更多 用简单工厂 用工厂方法 控制权？ ┌──────────┤──────────┐ ▼ ▼ ▼ 代理模式 桥接模式 责任链模式 (访问控制) (维度分离) (处理链)
总结工厂模式和装饰器模式是解决”创建”与”组合”两个正交变化维度的经典方案。在实际项目的导出功能实践中，两者配合实现了从128个类到9个类的数量级缩减，核心收益总结如下：
工厂模式解决”创建什么”：Spring自动注册工厂让新增导出格式只需一个实现类加 @Service 注解，工厂自动感知，零修改代码。启动时即校验注册冲突，问题前置暴露。
装饰器模式解决”功能组合”：5个装饰器（水印、加密、压缩、分页、审计）可自由组合出32种功能搭配，洋葱模型层层包裹，每层只做一件事，职责单一。
装饰顺序是关键：水印→加密→压缩→分页→审计的顺序保证了语义正确性和性能最优。顺序错误会导致压缩率极低或水印未生效。
优雅降级：装饰器中的非核心操作（如水印）失败时不影响主流程，保证导出功能的可用性。
可观测性：装饰链调试方法 getDecoratorChain() 和审计日志装饰器为排查问题提供了完整链路信息。
异步导出：大数据量场景下，同步导出→异步任务+MQ+OSS的平滑切换，让导出功能在大数据量下依然可靠。
**核心思想：用组合替代继承，用动态叠加替代静态排列。*新增格式只需一个实现类，新增功能只需一个装饰器，系统可扩展性从O(NM)降低到O(N+M)。

前言2022年学过基础的接口幂等方案，2024年在实际项目中遇到了远比教科书复杂的幂等问题。井下矿车调度指令被MQ重复消费导致同一车辆被调度到两条路线、安全告警接口被Feign重试触发两次告警让值班人员疲于奔命、设备巡检提交按钮被工人的防爆终端双击导致两条巡检记录、瓦斯浓度超限告警因重复提交触发了三次紧急停机流程——每一件都是真金白银的生产事故。 幂等性远不是”加个Token”就能解决的。它需要根据业务场景的语义特性选择不同方案：查询类接口天然幂等、状态类操作靠状态机保证、写入类操作靠唯一键去重、并发修改靠乐观锁防护。这篇文章将从幂等性理论出发，系统梳理幂等性设计的完整方案，覆盖幂等性定义与数学语义、幂等场景分类与识别、Token机制防前端重复提交、唯一业务键防MQ重复消费、状态机防业务重复流转、乐观锁防并发修改、去重表通用兜底、分布式幂等（Redis+Lua）、幂等与分布式事务的关系、幂等框架设计、实际项目15个真实问题、方案选型决策树、踩坑记录与最佳实践等核心主题，并结合实际项目的实战经验，给出落地方案和踩坑记录。
幂等性定义与数学语义什么是幂等性幂等性（Idempotency）一词来源于数学，原意是”多次运算产生相同结果”。在HTTP协议中，PUT和DELETE被定义为幂等方法，而POST不是。在分布式系统中，幂等性意味着：同一操作执行一次和执行多次所产生的效果相同，系统状态一致。 幂等性的数学语义： f(x) = f(f(x)) = f(f(f(x))) = ... 即：对同一输入，无论调用多少次，系统状态等价 举例： SET balance = 100 -&gt; 幂等（无论执行多少次，余额都是100） SET balance = balance + 100 -&gt; 非幂等（每执行一次，余额增加100） SET balance = balance - 100 -&gt; 非幂等（每执行一次，余额减少100） 但如果改为： UPDATE account SET balance = balance - 100 WHERE user_id = 1 AND balance &gt;= 100 AND version = 5 -&gt; 乐观锁 + 条件判断 = 幂等（第二次执行时version已变，影响行数为0） 关键认知： 1. 幂等性是接口的属性，不是协议的属性 2. GET请求不一定是幂等的（如果查询有副作用） 3. POST请求可以设计为幂等的（通过业务保证） 4. 幂等 != 不执行，而是&quot;多次执行效果等价于一次&quot;
幂等性分类光谱幂等性分类光谱（由天然幂等到需要强保证）：天然幂等 (Natural Idempotent) | 操作本身多次执行结果一致 | 举例：SET x = 1, DELETE WHERE id = 1 | 不需要任何额外机制 | v业务幂等 (Business Idempotent) | 通过业务语义保证幂等 | 举例：状态机（CREATED-&gt;PAID，重复支付时跳过） | 举例：唯一业务键（orderId唯一，重复插入被数据库拒绝） | 成本最低，应优先使用 | v协议幂等 (Protocol Idempotent) | 通过协议机制保证幂等 | 举例：Token机制（请求前获取Token，服务端消费Token） | 举例：去重表（请求唯一ID写入去重表，重复请求被拦截） | 引入额外组件，成本中等 | v强制幂等 (Forced Idempotent) 需要多层机制联合保证 举例：分布式锁 + 乐观锁 + 唯一键 举例：分布式事务 + 去重表 + 状态机 成本最高，只在极端场景使用
幂等性对比表 幂等类型 | 核心保证 | 实现成本 | 性能影响 | 智慧矿山应用场景 天然幂等 | 操作语义本身保证 | 无 | 无 | 删除过期告警记录 业务幂等 | 业务规则保证 | 低 | 极低 | 矿车调度状态流转 协议幂等 | 协议机制保证 | 中 | 低~中 | 巡检表单防重复提交 强制幂等 | 多层机制联合保证 | 高 | 中~高 | 瓦斯超限紧急停机
幂等场景分类与识别需要幂等的场景需要幂等的场景全景图：
幂等场景分类 | 用户侧 | +————-+ +————–+ (前端) | | 重复点击 | | 网络超时重试 | | | 双击提交 | | 前端自动重试 | | +————-+ +————–+ | | 服务侧 | +————-+ +————–+ (后端) | | Feign重试 | | Sentinel重试 | | | 网关重试 | | 负载均衡重试 | | +————-+ +————–+ | | 消息侧 | +————-+ +————–+ (MQ) | | 重复消费 | | 消息重投递 | | | 消费失败重试 | | Rebalance | | +————-+ +————–+ | | 基础设施侧 | +————-+ +————–+ | | 定时任务重复 | | 数据库主从切换| | | 网络闪断 | | 容器重启 | | +————-+ +————–+ |
不需要幂等的场景不需要幂等的场景：1. 纯查询接口 -&gt; GET /api/device/&#123;id&#125; -&gt; 查询不改变状态，天然幂等2. 天然幂等的操作 -&gt; SET x = 1（无论执行多少次结果一样） -&gt; DELETE WHERE id = 1（删一次和删多次效果一样）3. 允许重复的业务 -&gt; 日志采集（重复一条日志影响不大） -&gt; 指标上报（覆盖写入，无副作用）4. 已有天然去重机制的接口 -&gt; 数据库唯一键约束（重复插入直接报错） -&gt; 主键生成使用UUID（不会碰撞）
Token机制——防前端重复提交原理Token机制是防止前端重复提交最常用的方案。核心思想是：请求前先获取一个一次性Token，提交时携带Token，服务端验证并消费Token，重复请求因Token已消费而被拒绝。 Token机制执行流程：步骤一：获取Token 浏览器 服务端 Redis | | | |-- GET /api/token ------&gt;| | | |-- SET token:uuid ------&gt;| | | EX 600 (10分钟过期) | | |&lt;-- OK ------------------| |&lt;-- &#123;token: &quot;uuid&quot;&#125; ----| |步骤二：提交业务（携带Token） 浏览器 服务端 Redis | | | |-- POST /api/order ----&gt;| | | Header: X-Idempotent-Token: uuid | | |-- Lua脚本原子操作 -----&gt;| | | GET token:uuid | | | 如果存在则DEL | | | 如果不存在则拒绝 | | |&lt;-- result: 1/0 ---------| | | | | | result=1: 首次请求 | | | -&gt; 执行业务逻辑 | | | | | | result=0: 重复请求 | | | -&gt; 返回&quot;请勿重复提交&quot; | |&lt;-- Result -------------| |关键：Lua脚本保证&quot;判断Token存在 + 删除Token&quot;的原子性 如果不用Lua脚本： 线程A: GET token -&gt; 存在 线程B: GET token -&gt; 存在（A还没来得及DEL） 线程A: DEL token 线程B: DEL token -&gt; 两个请求都通过了！
Token生成接口/** * Token生成接口 * 智慧矿山-设备巡检防重复提交 */@RestController@RequestMapping(&quot;/api/token&quot;)@Slf4jpublic class TokenController &#123; @Autowired private StringRedisTemplate redisTemplate; /** * 生成幂等Token * Token有效期10分钟，10分钟内未使用自动过期 */ @GetMapping(&quot;/generate&quot;) public Result&lt;String&gt; generate() &#123; String token = IdUtil.fastSimpleUUID(); String key = &quot;idempotent:token:&quot; + token; redisTemplate.opsForValue().set(key, &quot;1&quot;, 10, TimeUnit.MINUTES); log.debug(&quot;生成幂等Token: &#123;&#125;&quot;, token); return Result.success(token); &#125; /** * 批量生成Token（防爆终端弱网场景） * 智慧矿山场景：井下防爆终端网络不稳定 * 一次获取多个Token缓存到本地，避免反复请求 */ @GetMapping(&quot;/generate/batch&quot;) public Result&lt;List&lt;String&gt;&gt; generateBatch(@RequestParam(defaultValue = &quot;5&quot;) int count) &#123; if (count &gt; 20) &#123; throw new BusinessException(&quot;单次最多生成20个Token&quot;); &#125; List&lt;String&gt; tokens = new ArrayList&lt;&gt;(); for (int i = 0; i &lt; count; i++) &#123; String token = IdUtil.fastSimpleUUID(); String key = &quot;idempotent:token:&quot; + token; redisTemplate.opsForValue().set(key, &quot;1&quot;, 10, TimeUnit.MINUTES); tokens.add(token); &#125; log.debug(&quot;批量生成幂等Token: count=&#123;&#125;&quot;, count); return Result.success(tokens); &#125;&#125;
幂等注解定义/** * 幂等注解 * 标注在需要幂等控制的Controller方法上 */@Target(ElementType.METHOD)@Retention(RetentionPolicy.RUNTIME)@Documentedpublic @interface Idempotent &#123; /** * 幂等类型 */ IdempotentType type() default IdempotentType.TOKEN; /** * Token来源 */ TokenSource source() default TokenSource.HEADER; /** * Token请求头名称 */ String headerName() default &quot;X-Idempotent-Token&quot;; /** * Token请求参数名称（source=PARAM时生效） */ String paramName() default &quot;idempotentToken&quot;; /** * 幂等过期时间（秒），用于去重表方案 */ int expireSeconds() default 3600; /** * 提示信息 */ String message() default &quot;请勿重复提交&quot;; /** * 幂等类型枚举 */ enum IdempotentType &#123; TOKEN, // Token机制 DEDUP, // 去重表 PARAM // 参数去重 &#125; /** * Token来源枚举 */ enum TokenSource &#123; HEADER, // 从请求头获取 PARAM, // 从请求参数获取 BODY // 从请求体获取 &#125;&#125;
幂等切面实现/** * 幂等切面——Token机制核心实现 * 通过AOP拦截@Idempotent注解的方法 * 使用Redis Lua脚本保证&quot;判断+删除&quot;的原子性 */@Component@Aspect@Slf4jpublic class IdempotentAspect &#123; @Autowired private StringRedisTemplate redisTemplate; /** * Lua脚本：原子性判断Token是否存在并删除 * 返回1表示Token存在且已删除（首次请求） * 返回0表示Token不存在（重复请求） */ private static final String TOKEN_LUA_SCRIPT = &quot;if redis.call(&#x27;get&#x27;, KEYS[1]) == ARGV[1] then &quot; + &quot; return redis.call(&#x27;del&#x27;, KEYS[1]) &quot; + &quot;else &quot; + &quot; return 0 &quot; + &quot;end&quot;; @Around(&quot;@annotation(idempotent)&quot;) public Object around(ProceedingJoinPoint joinPoint, Idempotent idempotent) throws Throwable &#123; if (idempotent.type() != Idempotent.IdempotentType.TOKEN) &#123; return joinPoint.proceed(); &#125; String token = extractToken(idempotent); if (StringUtils.isBlank(token)) &#123; log.warn(&quot;幂等Token为空, method=&#123;&#125;&quot;, joinPoint.getSignature().getName()); throw new BusinessException(&quot;缺少幂等Token&quot;); &#125; String key = &quot;idempotent:token:&quot; + token; Long result = redisTemplate.execute( new DefaultRedisScript&lt;&gt;(TOKEN_LUA_SCRIPT, Long.class), Collections.singletonList(key), &quot;1&quot; ); if (result == null || result == 0L) &#123; log.warn(&quot;幂等Token已失效或已使用, token=&#123;&#125;, method=&#123;&#125;&quot;, token, joinPoint.getSignature().getName()); throw new BusinessException(idempotent.message()); &#125; log.debug(&quot;幂等Token验证通过, token=&#123;&#125;&quot;, token); return joinPoint.proceed(); &#125; private String extractToken(Idempotent idempotent) &#123; HttpServletRequest request = ((ServletRequestAttributes) RequestContextHolder.currentRequestAttributes()).getRequest(); switch (idempotent.source()) &#123; case HEADER: return request.getHeader(idempotent.headerName()); case PARAM: return request.getParameter(idempotent.paramName()); case BODY: return extractFromBody(request, idempotent.paramName()); default: return null; &#125; &#125; private String extractFromBody(HttpServletRequest request, String paramName) &#123; return request.getParameter(paramName); &#125;&#125;
前端集成/** * 智慧矿山-防爆终端前端Token集成 * 使用Vue3 + Axios拦截器 */// 1. Token管理器class IdempotentTokenManager &#123; constructor() &#123; this.tokenPool = [] this.minPoolSize = 2 this.fetching = false &#125; async getToken() &#123; if (this.tokenPool.length === 0) &#123; await this.refill() &#125; return this.tokenPool.shift() &#125; async refill() &#123; if (this.fetching) return this.fetching = true try &#123; const res = await axios.get(&#x27;/api/token/generate/batch?count=5&#x27;) this.tokenPool.push(...res.data.data) &#125; finally &#123; this.fetching = false &#125; &#125; checkAndRefill() &#123; if (this.tokenPool.length &lt; this.minPoolSize) &#123; this.refill() &#125; &#125;&#125;const tokenManager = new IdempotentTokenManager()// 2. Axios请求拦截器axios.interceptors.request.use(async (config) =&gt; &#123; if ([&#x27;post&#x27;, &#x27;put&#x27;, &#x27;delete&#x27;].includes(config.method)) &#123; const token = await tokenManager.getToken() if (token) &#123; config.headers[&#x27;X-Idempotent-Token&#x27;] = token &#125; &#125; return config&#125;)// 3. Axios响应拦截器axios.interceptors.response.use( (response) =&gt; &#123; tokenManager.checkAndRefill() return response &#125;, (error) =&gt; &#123; if (error.response?.data?.code === &#x27;IDEMPOTENT_REJECTED&#x27;) &#123; Message.warning(&#x27;请勿重复提交&#x27;) tokenManager.checkAndRefill() return Promise.reject(error) &#125; return Promise.reject(error) &#125;)
Token机制注意事项Token机制注意事项：1. Token的原子性 -&gt; 必须使用Lua脚本保证&quot;判断+删除&quot;原子性 -&gt; 先GET再DEL是错误的，存在并发窗口 -&gt; 智慧矿山踩坑：早期未用Lua脚本，并发下Token被消费两次2. Token的生命周期 -&gt; 生成后10分钟过期（避免无限占用Redis内存） -&gt; 消费后立即失效（一次性Token） -&gt; 业务执行失败后Token已消费 -&gt; 前端需要重新获取Token3. Token与业务失败的关系 -&gt; Token先消费，再执行业务 -&gt; 业务失败 -&gt; Token已消费 -&gt; 前端获取新Token重试 -&gt; 这是正确行为：业务失败!=重复提交4. Token池设计（防爆终端场景） -&gt; 井下网络不稳定，频繁获取Token会失败 -&gt; 一次获取多个Token缓存到本地 -&gt; 池大小动态补充，避免浪费5. Token安全性 -&gt; Token应该是不可预测的（UUID / 雪花ID） -&gt; 不要用自增ID或时间戳 -&gt; 防止攻击者猜测Token绕过幂等校验
唯一业务键——防MQ重复消费原理唯一业务键是利用业务自身的数据唯一性约束来实现幂等。比如订单号唯一、设备编号唯一。当重复消费消息时，数据库唯一键约束会拦截重复插入。 唯一业务键幂等原理： 消息1（首次消费） 消息2（重复消费） | | v v INSERT INTO order INSERT INTO order (order_id=1001, ...) (order_id=1001, ...) | | v v 成功插入 唯一键冲突！ 返回OK DuplicateKeyException | v 捕获异常 -&gt; 跳过 log.info(&quot;订单已存在，跳过&quot;) 关键：数据库唯一键 = 天然的分布式去重器 -&gt; 无需引入额外组件 -&gt; 原子性由数据库ACID保证 -&gt; 性能开销极低（索引查找）
RocketMQ消费者幂等/** * 智慧矿山-矿车调度指令消费者 * 场景：调度中心下发调度指令到MQ，矿车端消费执行 * 幂等：通过调度单号唯一键保证 */@Component@RocketMQMessageListener( topic = &quot;mine_dispatch_topic&quot;, consumerGroup = &quot;mine-dispatch-consumer&quot;, messageModel = MessageModel.CLUSTERING)@Slf4jpublic class DispatchConsumer implements RocketMQListener&lt;String&gt; &#123; @Autowired private DispatchOrderMapper dispatchOrderMapper; @Autowired private VehicleMapper vehicleMapper; @Override public void onMessage(String message) &#123; DispatchMessage msg = JsonUtils.fromJson(message, DispatchMessage.class); log.info(&quot;收到矿车调度指令: dispatchNo=&#123;&#125;, vehicleId=&#123;&#125;&quot;, msg.getDispatchNo(), msg.getVehicleId()); try &#123; DispatchOrder order = new DispatchOrder(); order.setDispatchNo(msg.getDispatchNo()); order.setVehicleId(msg.getVehicleId()); order.setRouteId(msg.getRouteId()); order.setStatus(DispatchStatus.PENDING); dispatchOrderMapper.insert(order); log.info(&quot;调度单创建成功: dispatchNo=&#123;&#125;&quot;, msg.getDispatchNo()); &#125; catch (DuplicateKeyException e) &#123; log.info(&quot;调度单已存在，跳过重复消费: dispatchNo=&#123;&#125;&quot;, msg.getDispatchNo()); return; &#125; vehicleMapper.updateStatus(msg.getVehicleId(), VehicleStatus.DISPATCHED); log.info(&quot;车辆状态已更新: vehicleId=&#123;&#125;&quot;, msg.getVehicleId()); &#125;&#125;
Kafka消费者幂等/** * 智慧矿山-瓦斯监测数据消费者 * 场景：传感器数据通过Kafka上报，可能重复投递 * 幂等：通过（设备ID + 采集时间戳）联合唯一键 */@Component@Slf4jpublic class GasMonitorConsumer &#123; @Autowired private GasDataMapper gasDataMapper; @Autowired private StringRedisTemplate redisTemplate; /** * 方案一：唯一键插入（数据库层面保证） */ @KafkaListener(topics = &quot;gas-monitor-data&quot;, groupId = &quot;gas-monitor-group&quot;) public void consume(ConsumerRecord&lt;String, String&gt; record) &#123; GasDataMessage msg = JsonUtils.fromJson(record.value(), GasDataMessage.class); log.debug(&quot;收到瓦斯监测数据: deviceId=&#123;&#125;, timestamp=&#123;&#125;&quot;, msg.getDeviceId(), msg.getCollectTime()); try &#123; GasData data = new GasData(); data.setDeviceId(msg.getDeviceId()); data.setCollectTime(msg.getCollectTime()); data.setCh4Concentration(msg.getCh4Concentration()); data.setCoConcentration(msg.getCoConcentration()); gasDataMapper.insert(data); &#125; catch (DuplicateKeyException e) &#123; log.debug(&quot;瓦斯数据已存在，跳过: deviceId=&#123;&#125;, collectTime=&#123;&#125;&quot;, msg.getDeviceId(), msg.getCollectTime()); &#125; &#125; /** * 方案二：Redis去重（性能更高） */ @KafkaListener(topics = &quot;gas-monitor-data-v2&quot;, groupId = &quot;gas-monitor-group-v2&quot;) public void consumeWithRedis(ConsumerRecord&lt;String, String&gt; record) &#123; GasDataMessage msg = JsonUtils.fromJson(record.value(), GasDataMessage.class); String dedupKey = String.format(&quot;idempotent:gas:%s:%d&quot;, msg.getDeviceId(), msg.getCollectTime().getTime()); Boolean isFirst = redisTemplate.opsForValue() .setIfAbsent(dedupKey, &quot;1&quot;, 5, TimeUnit.MINUTES); if (Boolean.FALSE.equals(isFirst)) &#123; log.debug(&quot;瓦斯数据已处理，跳过: deviceId=&#123;&#125;, collectTime=&#123;&#125;&quot;, msg.getDeviceId(), msg.getCollectTime()); return; &#125; GasData data = new GasData(); data.setDeviceId(msg.getDeviceId()); data.setCollectTime(msg.getCollectTime()); data.setCh4Concentration(msg.getCh4Concentration()); gasDataMapper.insert(data); &#125;&#125;
唯一业务键设计原则唯一业务键设计原则：1. 键的选择 -&gt; 优先使用业务自然唯一键：订单号、设备编号、调度单号 -&gt; 没有自然唯一键时：组合键（设备ID + 时间窗口） -&gt; 键必须全局唯一、不可变、不可重用2. 键的粒度 -&gt; 太粗：无法区分不同操作 -&gt; 太细：无法识别重复 -&gt; 智慧矿山经验： - 矿车调度：dispatchNo（调度单号） - 瓦斯告警：deviceId + alertTime（精确到秒） - 人员入井：personId + entryTime（精确到分钟）3. 唯一键的索引 -&gt; 必须建立唯一索引，不能只建普通索引 -&gt; 普通索引不保证唯一性，无法拦截重复插入 -&gt; 联合唯一索引：UNIQUE KEY uk_device_time (device_id, collect_time)4. 重复消费的处理策略 -&gt; 静默跳过：直接return（最常用） -&gt; 返回成功：让MQ确认消费，避免进入重试队列 -&gt; 记录日志：log.info记录，便于排查 -&gt; 更新操作：如果是覆盖写入，直接执行即可5. 注意事项 -&gt; 唯一键方案只适用于INSERT场景 -&gt; UPDATE场景需要配合乐观锁或状态机 -&gt; 物理删除后重新插入不会触发唯一键冲突 -&gt; 软删除（逻辑删除）需要把delete_flag加入联合唯一键
状态机——防业务状态重复流转原理状态机幂等是最优雅的方案——它不需要引入任何额外组件，而是利用业务自身的状态流转规则来保证幂等。核心思想是：只有特定状态才能执行特定操作，重复请求时状态已变更，操作自然被拒绝。 状态机幂等原理：
创建操作：PENDING -&gt; DISPATCHED（只有PENDING状态才能调度） 重复调度：当前状态已经是DISPATCHED，不满足条件，直接跳过 取消操作：PENDING&#x2F;DISPATCHED -&gt; CANCELED（只有这两个状态才能取消） 重复取消：当前状态已经是CANCELED，不满足条件，直接跳过
矿车调度状态机实现/** * 调度单状态枚举 */public enum DispatchStatus &#123; PENDING(0, &quot;待调度&quot;), DISPATCHED(1, &quot;已调度&quot;), COMPLETED(2, &quot;已完成&quot;), CANCELED(3, &quot;已取消&quot;), TIMEOUT(4, &quot;已超时&quot;); private final int code; private final String desc; DispatchStatus(int code, String desc) &#123; this.code = code; this.desc = desc; &#125; public int getCode() &#123; return code; &#125; public String getDesc() &#123; return desc; &#125;&#125;/** * 状态机幂等核心实现 * 使用CAS方式更新，只有状态匹配才能变更 */@Service@Slf4jpublic class DispatchStatusService &#123; @Autowired private DispatchOrderMapper dispatchOrderMapper; @Autowired private VehicleMapper vehicleMapper; /** * 调度操作：PENDING -&gt; DISPATCHED */ @Transactional(rollbackFor = Exception.class) public boolean dispatch(Long dispatchId) &#123; int rows = dispatchOrderMapper.updateStatus( dispatchId, DispatchStatus.DISPATCHED, DispatchStatus.PENDING); if (rows == 0) &#123; DispatchOrder order = dispatchOrderMapper.selectById(dispatchId); if (order.getStatus() == DispatchStatus.DISPATCHED) &#123; log.info(&quot;调度单已调度，跳过重复操作: dispatchId=&#123;&#125;&quot;, dispatchId); return true; &#125; log.warn(&quot;调度单状态不允许调度: dispatchId=&#123;&#125;, status=&#123;&#125;&quot;, dispatchId, order.getStatus().getDesc()); return false; &#125; DispatchOrder order = dispatchOrderMapper.selectById(dispatchId); vehicleMapper.updateStatus(order.getVehicleId(), VehicleStatus.DISPATCHED); log.info(&quot;调度成功: dispatchId=&#123;&#125;, vehicleId=&#123;&#125;&quot;, dispatchId, order.getVehicleId()); return true; &#125; /** * 完成操作：DISPATCHED -&gt; COMPLETED */ @Transactional(rollbackFor = Exception.class) public boolean complete(Long dispatchId) &#123; int rows = dispatchOrderMapper.updateStatus( dispatchId, DispatchStatus.COMPLETED, DispatchStatus.DISPATCHED); if (rows == 0) &#123; DispatchOrder order = dispatchOrderMapper.selectById(dispatchId); if (order.getStatus() == DispatchStatus.COMPLETED) &#123; log.info(&quot;调度单已完成，跳过重复操作: dispatchId=&#123;&#125;&quot;, dispatchId); return true; &#125; log.warn(&quot;调度单状态不允许完成: dispatchId=&#123;&#125;, status=&#123;&#125;&quot;, dispatchId, order.getStatus().getDesc()); return false; &#125; DispatchOrder order = dispatchOrderMapper.selectById(dispatchId); vehicleMapper.updateStatus(order.getVehicleId(), VehicleStatus.IDLE); log.info(&quot;调度完成: dispatchId=&#123;&#125;&quot;, dispatchId); return true; &#125; /** * 取消操作：PENDING/DISPATCHED -&gt; CANCELED */ @Transactional(rollbackFor = Exception.class) public boolean cancel(Long dispatchId, String reason) &#123; int rows = dispatchOrderMapper.updateStatusFromAny( dispatchId, DispatchStatus.CANCELED, Arrays.asList(DispatchStatus.PENDING, DispatchStatus.DISPATCHED)); if (rows == 0) &#123; DispatchOrder order = dispatchOrderMapper.selectById(dispatchId); if (order.getStatus() == DispatchStatus.CANCELED) &#123; log.info(&quot;调度单已取消，跳过重复操作: dispatchId=&#123;&#125;&quot;, dispatchId); return true; &#125; log.warn(&quot;调度单状态不允许取消: dispatchId=&#123;&#125;, status=&#123;&#125;&quot;, dispatchId, order.getStatus().getDesc()); return false; &#125; DispatchOrder order = dispatchOrderMapper.selectById(dispatchId); if (order.getVehicleId() != null) &#123; vehicleMapper.updateStatus(order.getVehicleId(), VehicleStatus.IDLE); &#125; log.info(&quot;调度取消: dispatchId=&#123;&#125;, reason=&#123;&#125;&quot;, dispatchId, reason); return true; &#125;&#125;
Mapper实现/** * 调度单Mapper——状态机CAS更新 */@Mapperpublic interface DispatchOrderMapper extends BaseMapper&lt;DispatchOrder&gt; &#123; @Update(&quot;UPDATE dispatch_order SET status = #&#123;newStatus&#125;, &quot; + &quot;update_time = NOW() &quot; + &quot;WHERE id = #&#123;id&#125; AND status = #&#123;expectedStatus&#125;&quot;) int updateStatus(@Param(&quot;id&quot;) Long id, @Param(&quot;newStatus&quot;) DispatchStatus newStatus, @Param(&quot;expectedStatus&quot;) DispatchStatus expectedStatus); @Update(&quot;&lt;script&gt;&quot; + &quot;UPDATE dispatch_order SET status = #&#123;newStatus&#125;, &quot; + &quot;update_time = NOW() &quot; + &quot;WHERE id = #&#123;id&#125; AND status IN &quot; + &quot;&lt;foreach collection=&#x27;expectedStatuses&#x27; item=&#x27;s&#x27; open=&#x27;(&#x27; separator=&#x27;,&#x27; close=&#x27;)&#x27;&gt;&quot; + &quot; #&#123;s&#125;&quot; + &quot;&lt;/foreach&gt;&quot; + &quot;&lt;/script&gt;&quot;) int updateStatusFromAny(@Param(&quot;id&quot;) Long id, @Param(&quot;newStatus&quot;) DispatchStatus newStatus, @Param(&quot;expectedStatuses&quot;) List&lt;DispatchStatus&gt; expectedStatuses);&#125;
瓦斯告警状态机/** * 智慧矿山-瓦斯告警状态机 * 重复告警不能重复触发紧急停机 */@Service@Slf4jpublic class GasAlertStatusService &#123; @Autowired private GasAlertMapper gasAlertMapper; @Autowired private EmergencyService emergencyService; public enum AlertStatus &#123; TRIGGERED(0, &quot;已触发&quot;), CONFIRMED(1, &quot;已确认&quot;), HANDLING(2, &quot;处理中&quot;), RESOLVED(3, &quot;已解除&quot;), FALSE_ALARM(4, &quot;误报&quot;); private final int code; private final String desc; AlertStatus(int code, String desc) &#123; this.code = code; this.desc = desc; &#125; &#125; /** * 触发告警：-&gt; TRIGGERED * 幂等保证：同一设备的告警未解除前不重复触发 */ @Transactional(rollbackFor = Exception.class) public boolean triggerAlert(GasAlert alert) &#123; GasAlert existingAlert = gasAlertMapper.selectActiveByDevice(alert.getDeviceId()); if (existingAlert != null) &#123; log.info(&quot;设备存在未解除告警，跳过重复触发: deviceId=&#123;&#125;, alertId=&#123;&#125;&quot;, alert.getDeviceId(), existingAlert.getId()); return true; &#125; alert.setStatus(AlertStatus.TRIGGERED); gasAlertMapper.insert(alert); emergencyService.triggerEmergencyStop(alert.getDeviceId()); log.warn(&quot;瓦斯超限告警已触发，紧急停机: deviceId=&#123;&#125;, ch4=&#123;&#125;&quot;, alert.getDeviceId(), alert.getCh4Concentration()); return true; &#125; public boolean confirmAlert(Long alertId, Long operatorId) &#123; int rows = gasAlertMapper.updateStatus(alertId, AlertStatus.CONFIRMED, AlertStatus.TRIGGERED); if (rows == 0) &#123; GasAlert alert = gasAlertMapper.selectById(alertId); if (alert.getStatus() == AlertStatus.CONFIRMED) &#123; log.info(&quot;告警已确认，跳过: alertId=&#123;&#125;&quot;, alertId); return true; &#125; return false; &#125; log.info(&quot;告警已确认: alertId=&#123;&#125;, operator=&#123;&#125;&quot;, alertId, operatorId); return true; &#125; public boolean resolveAlert(Long alertId, String resolveNote) &#123; int rows = gasAlertMapper.updateStatus(alertId, AlertStatus.RESOLVED, AlertStatus.HANDLING); if (rows == 0) &#123; GasAlert alert = gasAlertMapper.selectById(alertId); if (alert.getStatus() == AlertStatus.RESOLVED) &#123; log.info(&quot;告警已解除，跳过: alertId=&#123;&#125;&quot;, alertId); return true; &#125; return false; &#125; emergencyService.cancelEmergencyStop(alertId); log.info(&quot;告警已解除: alertId=&#123;&#125;&quot;, alertId); return true; &#125;&#125;
状态机设计注意事项状态机设计注意事项：1. 状态定义要完备 -&gt; 状态必须有明确的语义 -&gt; 不能有模糊状态（如&quot;处理中&quot;和&quot;审核中&quot;不能重叠） -&gt; 状态变更只能通过服务方法，不能直接UPDATE2. 状态流转要单向 -&gt; 正向流转：PENDING -&gt; DISPATCHED -&gt; COMPLETED -&gt; 反向流转只能走取消：PENDING -&gt; CANCELED -&gt; 不能从CANCELED恢复到PENDING（语义不一致）3. CAS更新必须检查影响行数 -&gt; UPDATE ... WHERE status = #&#123;expected&#125; 返回0 -&gt; 0的含义：状态已变更（并发或重复请求） -&gt; 需要二次查询判断是重复请求还是其他状态4. 状态机的幂等语义 -&gt; 如果当前状态 = 目标状态 -&gt; 幂等成功（已执行过） -&gt; 如果当前状态 != 期望前置状态 -&gt; 业务拒绝（非法操作） -&gt; 区分这两种情况是关键5. 分布式环境下的状态机 -&gt; CAS更新在数据库层面保证原子性 -&gt; 不需要分布式锁（数据库行锁足够） -&gt; 但要避免长事务持有行锁太久
乐观锁——防并发修改原理乐观锁通过版本号（version）机制防止并发修改冲突。每次更新时检查版本号是否匹配，匹配则更新并将版本号+1，不匹配则说明已被其他请求修改。 乐观锁幂等原理： 请求A（首次执行） 请求B（重复/并发执行） | | v v SELECT balance, version SELECT balance, version FROM account FROM account WHERE user_id = 1 WHERE user_id = 1 | | v v balance=1000, version=5 balance=1000, version=5 | | v | UPDATE account | (尚未执行UPDATE) SET balance = 900, | version = 6 | WHERE user_id = 1 | AND version = 5 | | | v v 影响行数: 1 UPDATE account 成功！ SET balance = 900, version = 6 WHERE user_id = 1 AND version = 5 | v 影响行数: 0 version已变为6 != 5 失败！-&gt; 幂等拒绝或重试
乐观锁实现/** * 智慧矿山-车辆里程统计乐观锁实现 * 场景：多个传感器同时上报同一车辆的里程数据 */@Service@Slf4jpublic class VehicleMileageService &#123; @Autowired private VehicleMapper vehicleMapper; public boolean updateMileage(Long vehicleId, BigDecimal addedMileage, Integer expectedVersion) &#123; int rows = vehicleMapper.updateMileageWithVersion( vehicleId, addedMileage, expectedVersion); if (rows == 0) &#123; log.info(&quot;车辆里程更新失败（版本不匹配）: vehicleId=&#123;&#125;, expectedVersion=&#123;&#125;&quot;, vehicleId, expectedVersion); return false; &#125; log.info(&quot;车辆里程更新成功: vehicleId=&#123;&#125;, addedMileage=&#123;&#125;&quot;, vehicleId, addedMileage); return true; &#125; /** * 带重试的乐观锁更新 */ public boolean updateMileageWithRetry(Long vehicleId, BigDecimal addedMileage, int maxRetry) &#123; for (int i = 0; i &lt; maxRetry; i++) &#123; Vehicle vehicle = vehicleMapper.selectById(vehicleId); int currentVersion = vehicle.getVersion(); int rows = vehicleMapper.updateMileageWithVersion( vehicleId, addedMileage, currentVersion); if (rows &gt; 0) &#123; log.info(&quot;车辆里程更新成功（第&#123;&#125;次尝试）: vehicleId=&#123;&#125;&quot;, i + 1, vehicleId); return true; &#125; log.debug(&quot;乐观锁冲突，重试: vehicleId=&#123;&#125;, retry=&#123;&#125;&quot;, vehicleId, i + 1); &#125; log.error(&quot;车辆里程更新失败（超过最大重试次数）: vehicleId=&#123;&#125;&quot;, vehicleId); return false; &#125;&#125;
@Mapperpublic interface VehicleMapper extends BaseMapper&lt;Vehicle&gt; &#123; @Update(&quot;UPDATE vehicle &quot; + &quot;SET total_mileage = total_mileage + #&#123;addedMileage&#125;, &quot; + &quot; version = version + 1, &quot; + &quot; update_time = NOW() &quot; + &quot;WHERE id = #&#123;id&#125; AND version = #&#123;expectedVersion&#125;&quot;) int updateMileageWithVersion(@Param(&quot;id&quot;) Long id, @Param(&quot;addedMileage&quot;) BigDecimal addedMileage, @Param(&quot;expectedVersion&quot;) Integer expectedVersion);&#125;
乐观锁 vs 悲观锁锁机制 | 无锁，冲突时重试 | 数据库行锁
维度 | 乐观锁 | 悲观锁 实现方式 | version字段 + CAS | SELECT … FOR UPDATE 并发性能 | 高（无锁等待） | 低（锁等待） 冲突处理 | 失败重试 &#x2F; 返回错误 | 串行执行 适用场景 | 读多写少，冲突概率低 | 写多，冲突概率高 死锁风险 | 无 | 有 数据库依赖 | 通用（MySQL&#x2F;PG&#x2F;Oracle） | 依赖数据库行锁实现 智慧矿山场景 | 设备里程累加、状态更新 | 库存扣减、资源分配 代码侵入性 | 低（加version字段） | 中（需要手动加锁） 事务持有时间 | 短 | 长（锁持有期间）
去重表——通用兜底方案原理当业务自身没有合适的幂等机制时，去重表是最通用的兜底方案。核心思想是：将每个请求的唯一标识记录到去重表中，重复请求因为唯一约束被拦截。 去重表原理： 请求1（首次请求） 请求2（重复请求） | | v v 开启事务 开启事务 | | v v INSERT INTO INSERT INTO idempotent_record idempotent_record (request_id=&#x27;REQ-001&#x27;) (request_id=&#x27;REQ-001&#x27;) | | v v 成功插入 唯一键冲突！ | | v v 执行业务逻辑 回滚事务 | 捕获DuplicateKeyException v 返回&quot;请勿重复提交&quot; 提交事务 去重表 vs Token机制： -&gt; Token机制：需要先获取Token，前端配合 -&gt; 去重表：不需要前端配合，后端自行判断 -&gt; 去重表更通用，但需要设计请求唯一ID
去重表DDLCREATE TABLE `idempotent_record` ( `id` BIGINT(20) NOT NULL AUTO_INCREMENT COMMENT &#x27;主键&#x27;, `request_id` VARCHAR(64) NOT NULL COMMENT &#x27;请求唯一ID&#x27;, `biz_type` VARCHAR(32) NOT NULL COMMENT &#x27;业务类型&#x27;, `request_body` TEXT DEFAULT NULL COMMENT &#x27;请求体摘要&#x27;, `response_body` TEXT DEFAULT NULL COMMENT &#x27;响应体（缓存首次响应）&#x27;, `status` TINYINT NOT NULL DEFAULT 0 COMMENT &#x27;0-处理中 1-成功 2-失败&#x27;, `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `expire_time` DATETIME NOT NULL COMMENT &#x27;过期时间&#x27;, PRIMARY KEY (`id`), UNIQUE KEY `uk_request_id_biz` (`request_id`, `biz_type`), KEY `idx_expire_time` (`expire_time`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=&#x27;幂等去重记录表&#x27;;
去重表完整实现@Service@Slf4jpublic class IdempotentRecordService &#123; @Autowired private IdempotentRecordMapper mapper; public CheckResult checkAndRecord(String requestId, String bizType, String requestDigest) &#123; try &#123; IdempotentRecord record = new IdempotentRecord(); record.setRequestId(requestId); record.setBizType(bizType); record.setRequestBody(requestDigest); record.setStatus(0); record.setExpireTime(LocalDateTime.now().plusHours(24)); mapper.insert(record); return CheckResult.firstRequest(); &#125; catch (DuplicateKeyException e) &#123; IdempotentRecord existing = mapper.selectByRequestIdAndBizType(requestId, bizType); if (existing == null) &#123; return CheckResult.firstRequest(); &#125; if (existing.getStatus() == 1) &#123; return CheckResult.duplicateSuccess(existing.getResponseBody()); &#125; else if (existing.getStatus() == 2) &#123; mapper.deleteByRequestIdAndBizType(requestId, bizType); return CheckResult.firstRequest(); &#125; else &#123; return CheckResult.duplicateProcessing(); &#125; &#125; &#125; public void updateResult(String requestId, String bizType, boolean success, String response) &#123; IdempotentRecord record = new IdempotentRecord(); record.setRequestId(requestId); record.setBizType(bizType); record.setStatus(success ? 1 : 2); record.setResponseBody(response); mapper.updateResultByRequestIdAndBizType(record); &#125; @Scheduled(cron = &quot;0 0 3 * * ?&quot;) public void cleanExpiredRecords() &#123; int deleted = mapper.deleteExpired(LocalDateTime.now()); log.info(&quot;清理过期幂等记录: deleted=&#123;&#125;&quot;, deleted); &#125; @Data @AllArgsConstructor @NoArgsConstructor public static class CheckResult &#123; private boolean firstRequest; private String cachedResponse; private boolean allowRetry; public static CheckResult firstRequest() &#123; return new CheckResult(true, null, false); &#125; public static CheckResult duplicateSuccess(String response) &#123; return new CheckResult(false, response, false); &#125; public static CheckResult duplicateProcessing() &#123; return new CheckResult(false, null, false); &#125; &#125;&#125;
分布式幂等——Redis + Lua为什么需要分布式幂等在微服务架构中，多个服务实例同时运行，传统的本地幂等机制可能不够。Redis + Lua方案提供了跨实例的分布式幂等能力。 分布式幂等架构：
所有实例共享同一个Redis Lua脚本在Redis中原子执行 不会出现两个实例同时通过幂等检查的情况 性能远优于数据库去重表
Redis + Lua幂等实现/** * 智慧矿山-分布式幂等服务 */@Service@Slf4jpublic class RedisIdempotentService &#123; @Autowired private StringRedisTemplate redisTemplate; private static final String IDEMPOTENT_LUA_SCRIPT = &quot;local key = KEYS[1] &quot; + &quot;local lockKey = KEYS[2] &quot; + &quot;local resultKey = KEYS[3] &quot; + &quot;local expireMs = tonumber(ARGV[1]) &quot; + &quot;local value = redis.call(&#x27;GET&#x27;, key) &quot; + &quot;if value then &quot; + &quot; if value == &#x27;1&#x27; then &quot; + &quot; local result = redis.call(&#x27;GET&#x27;, resultKey) &quot; + &quot; return &#123;2, result or &#x27;&#x27;&#125; &quot; + &quot; elseif value == &#x27;0&#x27; then &quot; + &quot; return &#123;0, &#x27;&#x27;&#125; &quot; + &quot; end &quot; + &quot;end &quot; + &quot;redis.call(&#x27;SET&#x27;, key, &#x27;0&#x27;, &#x27;PX&#x27;, expireMs) &quot; + &quot;redis.call(&#x27;SET&#x27;, lockKey, &#x27;1&#x27;, &#x27;PX&#x27;, expireMs) &quot; + &quot;return &#123;1, &#x27;&#x27;&#125; &quot;; private static final String IDEMPOTENT_COMPLETE_SCRIPT = &quot;local key = KEYS[1] &quot; + &quot;local resultKey = KEYS[2] &quot; + &quot;local result = ARGV[1] &quot; + &quot;redis.call(&#x27;SET&#x27;, key, &#x27;1&#x27;) &quot; + &quot;redis.call(&#x27;SET&#x27;, resultKey, result, &#x27;EX&#x27;, 3600) &quot; + &quot;return 1&quot;; public IdempotentResult check(String requestId, long expireMs) &#123; String key = &quot;idempotent:req:&quot; + requestId; String lockKey = &quot;idempotent:lock:&quot; + requestId; String resultKey = &quot;idempotent:result:&quot; + requestId; DefaultRedisScript&lt;List&gt; script = new DefaultRedisScript&lt;&gt;(IDEMPOTENT_LUA_SCRIPT, List.class); List result = redisTemplate.execute(script, Arrays.asList(key, lockKey, resultKey), String.valueOf(expireMs)); long status = (Long) result.get(0); String cachedResult = result.size() &gt; 1 ? result.get(1).toString() : &quot;&quot;; return new IdempotentResult(status, cachedResult); &#125; public void complete(String requestId, String result) &#123; String key = &quot;idempotent:req:&quot; + requestId; String resultKey = &quot;idempotent:result:&quot; + requestId; DefaultRedisScript&lt;Long&gt; script = new DefaultRedisScript&lt;&gt;(IDEMPOTENT_COMPLETE_SCRIPT, Long.class); redisTemplate.execute(script, Arrays.asList(key, resultKey), result); &#125; public void fail(String requestId) &#123; redisTemplate.delete(&quot;idempotent:req:&quot; + requestId); redisTemplate.delete(&quot;idempotent:lock:&quot; + requestId); redisTemplate.delete(&quot;idempotent:result:&quot; + requestId); &#125; @Data @AllArgsConstructor public static class IdempotentResult &#123; private long status; // 0=处理中 1=首次请求 2=已完成 private String cachedResult; public boolean isFirstRequest() &#123; return status == 1; &#125; public boolean isProcessing() &#123; return status == 0; &#125; public boolean isCompleted() &#123; return status == 2; &#125; &#125;&#125;
幂等与分布式事务的关系幂等是分布式事务的前提幂等与分布式事务的关系：
分布式事务协议（TCC &#x2F; Saga &#x2F; Seata AT） 都依赖幂等性： TCC模式： Try -&gt; Confirm&#x2F;Cancel -&gt; Confirm&#x2F;Cancel可能被重试 -&gt; 必须幂等 -&gt; 否则：Confirm执行两次 &#x3D; 资源被扣两次 Saga模式： T1 -&gt; T2 -&gt; T3 -&gt; … -&gt; Tn -&gt; 任一Ti失败 -&gt; 执行补偿Ci -&gt; Ci可能被重试 -&gt; 必须幂等 -&gt; 否则：补偿执行两次 &#x3D; 资源被加两次 Seata AT模式： -&gt; 全局事务提交&#x2F;回滚时，各RM可能重复收到指令 -&gt; undo_log的分支事务ID唯一 -&gt; 天然幂等 -&gt; 但业务层面的补偿操作仍需幂等 结论： -&gt; 幂等性是分布式事务的必要条件 -&gt; 不实现幂等 &#x3D; 分布式事务无法正确运行 -&gt; 先实现幂等，再上分布式事务
TCC模式下的幂等实现/** * 智慧矿山-TCC模式矿车调度 * Confirm和Cancel操作必须幂等 */@Service@Slf4jpublic class DispatchTccService &#123; @Autowired private DispatchOrderMapper dispatchOrderMapper; @Autowired private VehicleMapper vehicleMapper; /** * Try阶段：预留资源 */ public boolean tryDispatch(Long dispatchId, Long vehicleId, Long routeId) &#123; DispatchOrder existing = dispatchOrderMapper.selectById(dispatchId); if (existing != null &amp;&amp; existing.getStatus() == DispatchStatus.TRYING) &#123; log.info(&quot;Try阶段已执行，跳过: dispatchId=&#123;&#125;&quot;, dispatchId); return true; &#125; if (existing != null &amp;&amp; existing.getStatus() == DispatchStatus.CONFIRMED) &#123; log.info(&quot;Confirm阶段已执行，跳过Try: dispatchId=&#123;&#125;&quot;, dispatchId); return true; &#125; DispatchOrder order = new DispatchOrder(); order.setId(dispatchId); order.setVehicleId(vehicleId); order.setRouteId(routeId); order.setStatus(DispatchStatus.TRYING); dispatchOrderMapper.insertOrUpdate(order); vehicleMapper.updateStatus(vehicleId, VehicleStatus.LOCKED); return true; &#125; /** * Confirm阶段：确认调度（必须幂等） */ public boolean confirmDispatch(Long dispatchId) &#123; int rows = dispatchOrderMapper.updateStatus( dispatchId, DispatchStatus.CONFIRMED, DispatchStatus.TRYING); if (rows == 0) &#123; DispatchOrder order = dispatchOrderMapper.selectById(dispatchId); if (order.getStatus() == DispatchStatus.CONFIRMED) &#123; log.info(&quot;Confirm已执行，跳过: dispatchId=&#123;&#125;&quot;, dispatchId); return true; &#125; return false; &#125; DispatchOrder order = dispatchOrderMapper.selectById(dispatchId); vehicleMapper.updateStatus(order.getVehicleId(), VehicleStatus.DISPATCHED); log.info(&quot;Confirm成功: dispatchId=&#123;&#125;&quot;, dispatchId); return true; &#125; /** * Cancel阶段：取消调度（必须幂等） */ public boolean cancelDispatch(Long dispatchId) &#123; int rows = dispatchOrderMapper.updateStatus( dispatchId, DispatchStatus.CANCELED, DispatchStatus.TRYING); if (rows == 0) &#123; DispatchOrder order = dispatchOrderMapper.selectById(dispatchId); if (order.getStatus() == DispatchStatus.CANCELED) &#123; log.info(&quot;Cancel已执行，跳过: dispatchId=&#123;&#125;&quot;, dispatchId); return true; &#125; if (order.getStatus() == DispatchStatus.CONFIRMED) &#123; log.warn(&quot;已Confirm，不能Cancel: dispatchId=&#123;&#125;&quot;, dispatchId); return true; &#125; return false; &#125; DispatchOrder order = dispatchOrderMapper.selectById(dispatchId); if (order.getVehicleId() != null) &#123; vehicleMapper.updateStatus(order.getVehicleId(), VehicleStatus.IDLE); &#125; log.info(&quot;Cancel成功: dispatchId=&#123;&#125;&quot;, dispatchId); return true; &#125;&#125;
幂等框架设计框架架构幂等框架整体架构：
幂等框架 | | | 注解层 | 切面层 | 存储层 | 扩展层 | | | @Idempotent | Aspect | Redis | SPI扩展
type | - Token | - Lua | - 自定义存储
source | - Dedup | - SETNX | - 自定义ID生成
expire | - Param | MySQL | - 自定义结果缓存
message | - Distrib | - 去重表 |
| | - 唯一键 | 核心抽象 IdempotentStorage（存储抽象） RequestIdGenerator（ID生成抽象） ResultCache（结果缓存抽象）
核心抽象/** * 幂等存储抽象 */public interface IdempotentStorage &#123; boolean tryRecord(String key, long expireMillis); void recordResult(String key, String result, long expireMillis); String getResult(String key); void remove(String key);&#125;/** * Redis存储实现 */@Component@Slf4jpublic class RedisIdempotentStorage implements IdempotentStorage &#123; @Autowired private StringRedisTemplate redisTemplate; private static final String RECORD_SCRIPT = &quot;if redis.call(&#x27;SETNX&#x27;, KEYS[1], &#x27;0&#x27;) == 1 then &quot; + &quot; redis.call(&#x27;PEXPIRE&#x27;, KEYS[1], ARGV[1]) &quot; + &quot; return 1 &quot; + &quot;else &quot; + &quot; return 0 &quot; + &quot;end&quot;; @Override public boolean tryRecord(String key, long expireMillis) &#123; DefaultRedisScript&lt;Long&gt; script = new DefaultRedisScript&lt;&gt;(RECORD_SCRIPT, Long.class); Long result = redisTemplate.execute(script, Collections.singletonList(&quot;idempotent:&quot; + key), String.valueOf(expireMillis)); return result != null &amp;&amp; result == 1L; &#125; @Override public void recordResult(String key, String result, long expireMillis) &#123; redisTemplate.opsForValue().set(&quot;idempotent:result:&quot; + key, result, expireMillis, TimeUnit.MILLISECONDS); redisTemplate.opsForValue().set(&quot;idempotent:&quot; + key, &quot;1&quot;, expireMillis, TimeUnit.MILLISECONDS); &#125; @Override public String getResult(String key) &#123; return redisTemplate.opsForValue().get(&quot;idempotent:result:&quot; + key); &#125; @Override public void remove(String key) &#123; redisTemplate.delete(&quot;idempotent:&quot; + key); redisTemplate.delete(&quot;idempotent:result:&quot; + key); &#125;&#125;/** * MySQL存储实现 */@Component@Slf4jpublic class MySQLIdempotentStorage implements IdempotentStorage &#123; @Autowired private IdempotentRecordMapper mapper; @Override @Transactional(rollbackFor = Exception.class) public boolean tryRecord(String key, long expireMillis) &#123; try &#123; IdempotentRecord record = new IdempotentRecord(); record.setRequestId(key); record.setBizType(&quot;DEFAULT&quot;); record.setStatus(0); record.setExpireTime(LocalDateTime.now().plusNanos(expireMillis * 1_000_000)); mapper.insert(record); return true; &#125; catch (DuplicateKeyException e) &#123; return false; &#125; &#125; @Override public void recordResult(String key, String result, long expireMillis) &#123; mapper.updateResultByRequestIdAndBizType2(key, &quot;DEFAULT&quot;, 1, result); &#125; @Override public String getResult(String key) &#123; IdempotentRecord record = mapper.selectByRequestIdAndBizType(key, &quot;DEFAULT&quot;); return record != null ? record.getResponseBody() : null; &#125; @Override public void remove(String key) &#123; mapper.deleteByRequestIdAndBizType(key, &quot;DEFAULT&quot;); &#125;&#125;
请求ID生成器/** * 请求ID生成器抽象 */public interface RequestIdGenerator &#123; String generate(ProceedingJoinPoint joinPoint);&#125;/** * 默认生成器：方法签名 + 参数摘要 */@Componentpublic class DefaultRequestIdGenerator implements RequestIdGenerator &#123; @Override public String generate(ProceedingJoinPoint joinPoint) &#123; String signature = joinPoint.getSignature().toLongString(); String args = Arrays.stream(joinPoint.getArgs()) .map(arg -&gt; arg == null ? &quot;null&quot; : arg.toString()) .collect(Collectors.joining(&quot;|&quot;)); return DigestUtils.md5Hex(signature + &quot;:&quot; + args); &#125;&#125;/** * 智慧矿山-设备ID生成器 */@Component(&quot;deviceRequestIdGenerator&quot;)public class DeviceRequestIdGenerator implements RequestIdGenerator &#123; @Override public String generate(ProceedingJoinPoint joinPoint) &#123; Object[] args = joinPoint.getArgs(); String deviceId = &quot;&quot;; for (Object arg : args) &#123; if (arg instanceof DeviceRequest) &#123; deviceId = ((DeviceRequest) arg).getDeviceId(); break; &#125; &#125; return &quot;device:&quot; + deviceId + &quot;:&quot; + joinPoint.getSignature().getName(); &#125;&#125;/** * 智慧矿山-人员ID生成器（按人员ID + 时间窗口） */@Component(&quot;personRequestIdGenerator&quot;)public class PersonRequestIdGenerator implements RequestIdGenerator &#123; @Override public String generate(ProceedingJoinPoint joinPoint) &#123; Object[] args = joinPoint.getArgs(); String personId = &quot;&quot;; for (Object arg : args) &#123; if (arg instanceof PersonRequest) &#123; personId = ((PersonRequest) arg).getPersonId(); break; &#125; &#125; String timeWindow = LocalDateTime.now().format( DateTimeFormatter.ofPattern(&quot;yyyyMMddHHmm&quot;)); return &quot;person:&quot; + personId + &quot;:&quot; + timeWindow + &quot;:&quot; + joinPoint.getSignature().getName(); &#125;&#125;
方案选型决策树幂等方案选型决策树：
接口需要幂等？ | v v +———–+ +———–+ 是 | | 否 +—–+—–+ +———–+ | v 操作类型是什么？ | | | v v v v +———+ +———-+ +———-+ +———-+ INSERT | | UPDATE | | DELETE | | 业务流转 +—-+—-+ +—-+—–+ +—-+—–+ +—-+—–+ | | v v v v +———+ +———-+ +———-+ +———-+ 有唯一键？| |更新字段？ | |天然幂等？ | |有状态机？ +—-+—-+ +—-+—–+ +—-+—–+ +—-+—–+ | | +–+–+ +–+–+ +–+–+ +–+–+ | | | | | | v v v v v v v v 是 否 SET 累加 是 否 是 否 | | | | | | v v v v v v v v 唯一键 去重 天然 乐观锁 不需 去重 状态机 去重表 表 幂等 要幂等 表
方案选型对比总表 方案 | 适用场景 | 实现复杂度 | 性能影响 | 一致性保证 | 智慧矿山应用 Token机制 | 前端防重复提交 | 低 | 低 | 最终一致 | 设备巡检、安全检查 唯一业务键 | MQ消费幂等 | 低 | 极低 | 强一致 | 矿车调度、考勤打卡 状态机 | 业务状态流转 | 低 | 无 | 强一致 | 调度状态变更、告警处理 乐观锁 | 并发修改 | 低 | 低 | 强一致 | 设备里程、物资扣减 悲观锁 | 高冲突并发修改 | 中 | 中 | 强一致 | 物资出库、资源分配 去重表 | 通用幂等兜底 | 中 | 中 | 强一致 | 网关重试、安全检查 Redis+Lua | 分布式幂等 | 中 | 低 | 最终一致 | 分布式定时任务、配置更新 分布式锁 | 互斥操作 | 中 | 中 | 强一致 | 定时任务防重复执行 多层联合 | 极端高安全场景 | 高 | 高 | 强一致 | 瓦斯超限紧急停机
踩坑记录与最佳实践踩坑1：Token不是原子消费踩坑：Token非原子消费导致幂等失效错误代码： String token = redisTemplate.opsForValue().get(&quot;idempotent:token:&quot; + token); if (token != null) &#123; redisTemplate.delete(&quot;idempotent:token:&quot; + token); // 执行业务 &#125;并发问题： 时间线 线程A 线程B T1 GET token -&gt; &quot;1&quot;（存在） T2 GET token -&gt; &quot;1&quot;（存在，A还没DELETE） T3 DELETE token -&gt; 成功 T4 DELETE token -&gt; 成功（已被A删除，但仍返回1） T5 执行业务 执行业务 &lt;- 两个请求都通过了！正确做法： 使用Lua脚本原子操作： if redis.call(&#x27;get&#x27;, KEYS[1]) == ARGV[1] then return redis.call(&#x27;del&#x27;, KEYS[1]) else return 0 end教训： -&gt; Redis的GET + DEL不是原子操作 -&gt; 任何需要&quot;判断+操作&quot;的逻辑都要用Lua脚本 -&gt; 这是最常见的幂等实现错误
踩坑2：唯一键包含逻辑删除字段踩坑：唯一键未考虑逻辑删除错误DDL： CREATE TABLE dispatch_order ( id BIGINT PRIMARY KEY, dispatch_no VARCHAR(64) NOT NULL, deleted TINYINT DEFAULT 0, UNIQUE KEY uk_dispatch_no (dispatch_no) &lt;- 问题！ );场景： 1. 创建调度单 DISPATCH-001（deleted=0）-&gt; 成功 2. 逻辑删除调度单 DISPATCH-001（deleted=1） 3. 重新创建调度单 DISPATCH-001（deleted=0）-&gt; 唯一键冲突！ 但这应该是合法操作（旧的已删除）正确DDL： 方案1：联合唯一键包含deleted字段 UNIQUE KEY uk_dispatch_no_deleted (dispatch_no, deleted) 方案2：deleted用0和id值区分（更优雅） CREATE TABLE dispatch_order ( id BIGINT PRIMARY KEY, dispatch_no VARCHAR(64) NOT NULL, deleted BIGINT DEFAULT 0, -- 0=未删除, 删除时设为id值 UNIQUE KEY uk_dispatch_no (dispatch_no, deleted) ); 未删除时：(DISPATCH-001, 0) -&gt; 唯一 删除后： (DISPATCH-001, 123) -&gt; 不与新的(DISPATCH-001, 0)冲突教训： -&gt; 唯一键必须考虑逻辑删除 -&gt; 逻辑删除的值不能只用0/1，要用0/id -&gt; 否则删除后无法重新创建相同唯一键的记录
踩坑3：去重表与业务表不在同一事务踩坑：去重表与业务表不在同一事务错误代码： @Transactional public void createOrder(OrderDTO dto) &#123; idempotentRecordService.checkAndRecord(dto.getRequestId(), &quot;ORDER&quot;); orderMapper.insert(dto.toOrder()); &#125; 去重表在独立的数据源中（不同的DataSource） -&gt; 业务事务回滚了，但去重记录已提交 -&gt; 下次重试被去重表拦截，但业务数据没有正确做法1：去重表和业务表在同一个数据源 @Transactional public void createOrder(OrderDTO dto) &#123; idempotentRecordService.checkAndRecord(...); // 同一数据源 orderMapper.insert(dto.toOrder()); // 同一数据源 &#125;正确做法2：失败时删除去重记录 try &#123; idempotentRecordService.checkAndRecord(...); orderMapper.insert(...); &#125; catch (Exception e) &#123; idempotentRecordService.remove(...); // 删除去重记录，允许重试 throw e; &#125;教训： -&gt; 去重表必须和业务表在同一事务中 -&gt; 如果不能同一事务，失败时必须清理去重记录 -&gt; 否则业务失败但去重生效 = 请求永远无法成功
踩坑4：幂等粒度过粗踩坑：幂等粒度过粗导致正常请求被拦截错误实现： // 按userId去重 String requestId = &quot;user:&quot; + userId; idempotentService.check(requestId);问题： 用户提交了订单A -&gt; 成功 用户再提交订单B -&gt; 被拦截！（userId相同） -&gt; 用户同一时间只能提交一个请求？不合理正确实现： // 按userId + 操作类型 + 业务参数 去重 String requestId = &quot;user:&quot; + userId + &quot;:order:&quot; + orderDTO.hashCode(); 或者更精确： String requestId = &quot;order:&quot; + orderDTO.getOrderNo();教训： -&gt; 幂等粒度必须精确到&quot;同一操作&quot; -&gt; 不能按用户维度去重（一个用户可以有多个不同操作） -&gt; 不能按接口维度去重（同一接口的不同参数是不同请求） -&gt; 去重的key应该是&quot;操作+参数&quot;的组合
踩坑5：忽略MQ消费顺序与幂等的关系踩坑：MQ消费顺序与幂等冲突场景： Topic: device_status_change 消息1: device-001 -&gt; IDLE -&gt; RUNNING 消息2: device-001 -&gt; RUNNING -&gt; FAULT 如果消息2先被消费（乱序）： 消费者2处理消息2：IDLE -&gt; FAULT （前置状态不匹配） -&gt; 状态机拒绝 -&gt; 消息2进入重试队列 -&gt; 消费者1处理消息1：IDLE -&gt; RUNNING -&gt; 消息2重试：RUNNING -&gt; FAULT 这看起来没问题？但实际上： -&gt; 乱序导致FAULT状态延迟生效 -&gt; 在延迟窗口内，设备显示RUNNING但实际已FAULT -&gt; 安全风险！解决方案： 1. MQ顺序消息：同一设备的消息路由到同一Queue 2. 消费者单线程消费：避免多线程乱序 3. 状态机 + 版本号：每条消息携带版本号 UPDATE device SET status = #&#123;newStatus&#125;, version = #&#123;version&#125; WHERE id = #&#123;id&#125; AND version = #&#123;version&#125; - 1教训： -&gt; 状态机幂等与消息顺序密切相关 -&gt; 乱序消费可能导致状态跳变或延迟 -&gt; 高安全场景必须保证消息顺序
方案全流程对比 | Token | 前端获取Token -&gt; 提交携带Token -&gt; Lua原子消费 -&gt; 执行业务 -&gt; 返回结果 | | 唯一键 | MQ消费 -&gt; INSERT业务表 -&gt; 唯一键冲突 -&gt; 跳过 -&gt; 返回ACK | | 状态机 | 请求到达 -&gt; CAS更新状态 -&gt; 影响行数0 -&gt; 查状态 -&gt; 幂等成功&#x2F;拒绝 | | 乐观锁 | 读取version -&gt; UPDATE WHERE version&#x3D;x -&gt; 影响行数0 -&gt; 重试或拒绝 | | 去重表 | 请求到达 -&gt; INSERT去重表 -&gt; 唯一键冲突 -&gt; 查结果 -&gt; 返回缓存&#x2F;拒绝 | | Redis+Lua| 请求到达 -&gt; Lua原子检查+记录 -&gt; 首次-&gt;执行-&gt;记录结果 &#x2F; 重复-&gt;返回缓存 | | 多层联合 | Redis快速去重 -&gt; 状态机CAS -&gt; 唯一键兜底 -&gt; 全部通过才执行 |
总结幂等性设计是分布式系统的基本功。在实际场景中，我们从一次次生产事故中认识到：幂等性不是锦上添花，而是系统可靠性的底线。 核心认知：能用业务自身特性保证幂等（状态机、唯一键）就不要引入额外组件；幂等判断要在业务逻辑之前；幂等操作要保证原子性。Token机制防前端重复提交，唯一业务ID防MQ重复消费，状态机防业务重复流转，乐观锁防并发修改，去重表是通用兜底方案，Redis+Lua是分布式幂等的高性能选择，多层联合是极端高安全场景的最后防线。 实际项目的15个真实问题告诉我们：每一个幂等缺陷背后，都是真实的生产事故。矿车调度重复导致安全风险、瓦斯告警重复触发停机影响生产、物资出库并发扣减导致库存为负——这些问题不是假设，而是教训。关键是根据业务场景选择最合适的方案，在安全与性能之间找到平衡点。

前言实际项目建设期间，我们遭遇了一次刻骨铭心的线上OOM事故。井下综采工作面的传感器数据采集服务在业务高峰期突然内存溢出，导致整个数据采集链路中断长达15分钟，矿井安全监控出现盲区。事后排查发现，根因竟是一个看似人畜无害的线程池配置：核心线程数50、最大线程数200、无界队列 LinkedBlockingQueue。高峰期200个线程全部活跃，同时无界队列中堆积了数十万个任务对象，每个任务携带传感器数据、设备元信息、追踪链路等上下文，直接将堆内存撑爆。 这次事故让我重新审视线程池：线程池参数不是拍脑袋定的，需要根据业务类型、任务特性、系统资源来计算和压测。从那以后，我对实际项目中所有线程池进行了系统化调优，涵盖了数据采集、告警推送、报表导出、设备控制等核心场景。本文将结合实际项目的真实踩坑经历，从线程池底层原理到源码分析、从参数计算到监控告警、从拒绝策略到动态调参，全面剖析线程池深度调优的完整方法论。
线程池核心原理为什么需要线程池每个线程的创建和销毁都涉及JVM栈内存分配、操作系统内核态切换、线程上下文初始化等步骤，创建一个线程的开销通常在10ms~50ms之间。在高并发场景下，如果每个任务都新建线程，系统将大量时间浪费在线程生命周期管理上，而非业务处理。 无线程池的任务处理流程： 任务到来 → 创建线程(10~50ms) → 初始化上下文(1~5ms) → 执行任务(1~100ms) → 销毁线程(1~5ms) → 总耗时：13~160ms，其中任务执行仅占1~100ms有线程池的任务处理流程： 任务到来 → 提交到队列(0.01ms) → 线程取出任务(0.01ms) → 执行任务(1~100ms) → 总耗时：1~100ms，几乎零额外开销无线程池的典型问题： ① 线程创建开销大：每次请求都创建销毁，CPU浪费在内核态切换上 ② 线程数不可控：并发突增时线程数暴增，可能导致OOM ③ 缺乏统一管理：无法监控线程状态、无法拒绝过载请求 ④ 上下文切换频繁：线程数远超CPU核心数，CPU在切换而非执行
