Worker 线程生命周期状态机架构流程： flowchart TD N1[&quot;NEW Worker对象创建&quot;] N2[&quot;RUNNING&quot;] N3[&quot;从队列取任务执行&quot;] N4[&quot;SHUTDOWN 正在执行最后一个任务&quot;] N5[&quot;TERMINATED&quot;] N6[&quot;Worker线程退出&quot;] N7[&quot;核心线程&quot;] N8[&quot;队列.take()阻塞等待&quot;] N9[&quot;永不过期 非核心线程&quot;] N10[&quot;队列.poll(keepAliveTime)&quot;] N11[&quot;超时返回null&quot;] N12[&quot;Worker退出&quot;] N13[&quot;线程池SHUTDOWN&quot;] N14[&quot;队列.poll()非阻塞取&quot;] N15[&quot;取完所有任务后返回null&quot;] N1 --&gt; N2 N1 --&gt; N3 N2 --&gt; N4 N3 --&gt; N4 N4 --&gt; N5 N4 --&gt; N6 N5 --&gt; N7 N6 --&gt; N7 N7 --&gt; N8 N7 --&gt; N9 N8 --&gt; N10 N8 --&gt; N11 N9 --&gt; N10 N9 --&gt; N11 N10 --&gt; N12 N10 --&gt; N13 N11 --&gt; N12 N11 --&gt; N13 N12 --&gt; N14 N12 --&gt; N15 N13 --&gt; N14 N13 --&gt; N15
ThreadPoolExecutor 源码分析execute() 方法——任务提交的核心入口// JDK ThreadPoolExecutor.execute() 源码（带注释）public void execute(Runnable command) &#123; if (command == null) throw new NullPointerException(); int c = ctl.get(); // 第一步：当前线程数 &lt; corePoolSize，直接创建核心线程 if (workerCountOf(c) &lt; corePoolSize) &#123; if (addWorker(command, true)) // true表示核心线程 return; c = ctl.get(); // 创建失败，重新获取状态 &#125; // 第二步：线程数 &gt;= corePoolSize，任务入队 if (isRunning(c) &amp;&amp; workQueue.offer(command)) &#123; int recheck = ctl.get(); // 双重检查：入队后线程池可能已关闭 if (!isRunning(recheck) &amp;&amp; remove(command)) reject(command); // 入队成功但无线程可用（如核心线程刚好全部退出），创建一个空Worker else if (workerCountOf(recheck) == 0) addWorker(null, false); &#125; // 第三步：队列已满，尝试创建非核心线程 else if (!addWorker(command, false)) // false表示非核心线程 // 线程数已达maximumPoolSize，执行拒绝策略 reject(command);&#125;
execute() 三步走策略的精妙设计： Step 1: 创建核心线程（快速路径） │ 条件：workerCount &lt; corePoolSize │ 特点：无锁CAS操作，快速创建 │ 意义：保证常驻线程数，避免队列中任务等待 │ ▼ Step 2: 任务入队（缓冲路径） │ 条件：workerCount &gt;= corePoolSize &amp;&amp; 队列未满 │ 特点：生产者-消费者模式，队列做缓冲 │ 意义：线程复用，避免频繁创建销毁 │ 风险：无界队列时永远不会走到Step 3！ │ ▼ Step 3: 创建非核心线程（扩容路径） │ 条件：队列已满 &amp;&amp; workerCount &lt; maximumPoolSize │ 特点：临时扩容应对突发流量 │ 意义：弹性伸缩，高峰期临时增加处理能力 │ ▼ Reject: 拒绝策略（兜底路径） 条件：队列已满 &amp;&amp; workerCount &gt;= maximumPoolSize 意义：保护系统不过载 关键认知：只有使用有界队列，Step 3 才可能触发！ → 无界队列：任务永远不会被拒绝，但会无限堆积导致OOM → 这正是实际项目OOM事故的根因
addWorker() 方法——线程创建的核心逻辑// ThreadPoolExecutor.addWorker() 源码简化版private boolean addWorker(Runnable firstTask, boolean core) &#123; // 外层循环：CAS更新线程数（ctl） retry: for (;;) &#123; int c = ctl.get(); int rs = runStateOf(c); // 线程池状态检查：SHUTDOWN及以后状态只处理队列中的任务 if (rs &gt;= SHUTDOWN &amp;&amp; !(rs == SHUTDOWN &amp;&amp; firstTask == null &amp;&amp; !workQueue.isEmpty())) return false; // 内层循环：CAS自增workerCount for (;;) &#123; int wc = workerCountOf(c); // 线程数上限检查 if (wc &gt;= CAPACITY || wc &gt;= (core ? corePoolSize : maximumPoolSize)) return false; if (compareAndIncrementWorkerCount(c)) break retry; // CAS成功，跳出外层循环 c = ctl.get(); if (runStateOf(c) != rs) continue retry; // 状态变化，重试外层 // CAS失败（竞争），重试内层 &#125; &#125; // 线程数CAS成功后，创建Worker并启动 boolean workerStarted = false; boolean workerAdded = false; Worker w = null; try &#123; w = new Worker(firstTask); // Worker内部创建Thread final Thread t = w.thread; if (t != null) &#123; final ReentrantLock mainLock = this.mainLock; mainLock.lock(); try &#123; // 再次检查线程池状态（持锁期间状态可能变化） int rs = runStateOf(ctl.get()); if (rs &lt; SHUTDOWN || (rs == SHUTDOWN &amp;&amp; firstTask == null)) &#123; if (t.isAlive()) throw new IllegalThreadStateException(); workers.add(w); // 加入Worker集合 workerAdded = true; &#125; &#125; finally &#123; mainLock.unlock(); &#125; if (workerAdded) &#123; t.start(); // 启动Worker线程 workerStarted = true; &#125; &#125; &#125; finally &#123; if (!workerStarted) addWorkerFailed(w); // 回滚：移除Worker + 减少线程数 &#125; return workerStarted;&#125;
Worker 内部类——线程与任务的桥梁// ThreadPoolExecutor.Worker 源码简化版private final class Worker extends AbstractQueuedSynchronizer implements Runnable &#123; final Thread thread; // Worker持有的线程 Runnable firstTask; // 第一个任务（可能为null） volatile long completedTasks; // 已完成任务计数 Worker(Runnable firstTask) &#123; // 设置AQS state=-1，阻止在runWorker前被中断 setState(-1); this.firstTask = firstTask; this.thread = getThreadFactory().newThread(this); &#125; public void run() &#123; runWorker(this); &#125; // AQS实现：不可重入的互斥锁 // 0=未锁定 1=锁定 -1=初始状态 protected boolean tryAcquire(int unused) &#123; if (compareAndSetState(0, 1)) &#123; setExclusiveOwnerThread(Thread.currentThread()); return true; &#125; return false; &#125; protected boolean tryRelease(int unused) &#123; setExclusiveOwnerThread(null); setState(0); return true; &#125;&#125;
Worker 设计的关键细节： ① 继承 AQS 实现不可重入锁 → 锁定表示线程正在执行任务 → 不可重入：shutdown()可以检测线程是否空闲 → 空闲线程可以被安全中断，忙碌线程等待任务完成后中断 ② 初始 state=-1 的精妙之处 → 防止在runWorker()执行前线程被中断 → runWorker()启动后会unlock()将state设为0 → 此后中断检查才能生效 ③ firstTask 机制 → 新建Worker时可以直接分配一个任务 → 避免新线程还要去队列取第一个任务（减少延迟） → 后续任务从队列中获取
runWorker() 方法——任务执行的核心循环// ThreadPoolExecutor.runWorker() 源码简化版final void runWorker(Worker w) &#123; Thread wt = Thread.currentThread(); Runnable task = w.firstTask; w.firstTask = null; w.unlock(); // 将state从-1设为0，允许中断 boolean completedAbruptly = true; try &#123; // 核心循环：不断获取任务并执行 while (task != null || (task = getTask()) != null) &#123; w.lock(); // 标记线程正在执行任务 // 线程池状态检查 + 中断处理 if ((runStateAtLeast(ctl.get(), STOP) || (Thread.interrupted() &amp;&amp; runStateAtLeast(ctl.get(), STOP))) &amp;&amp; !wt.isInterrupted()) wt.interrupt(); try &#123; beforeExecute(wt, task); // 前置钩子 try &#123; task.run(); // 执行任务 afterExecute(task, null); // 后置钩子 &#125; catch (Throwable ex) &#123; afterExecute(task, ex); throw ex; &#125; &#125; finally &#123; task = null; w.completedTasks++; w.unlock(); &#125; &#125; completedAbruptly = false; &#125; finally &#123; processWorkerExit(w, completedAbruptly); // Worker退出清理 &#125;&#125;
架构流程： flowchart TD N1[&quot;while (task null&quot;] N2[&quot;getTask() 逻辑&quot;] N3[&quot;core线程&quot;] N4[&quot;(task getTask()) null)&quot;] N5[&quot;queue.take()阻塞&quot;] N6[&quot;非core线程&quot;] N7[&quot;queue.poll(keepAliveTime)超时退出&quot;] N8[&quot;池子SHUTDOWN&quot;] N9[&quot;取完队列任务后退出&quot;] N1 --&gt; N2 N1 --&gt; N3 N4 --&gt; N2 N4 --&gt; N3 N2 --&gt; N5 N2 --&gt; N6 N3 --&gt; N5 N3 --&gt; N6 N5 --&gt; N7 N5 --&gt; N8 N6 --&gt; N7 N6 --&gt; N8 N7 --&gt; N9 N8 --&gt; N9
getTask() 方法——线程获取与退出的关键// ThreadPoolExecutor.getTask() 源码简化版private Runnable getTask() &#123; boolean timedOut = false; for (;;) &#123; int c = ctl.get(); int rs = runStateOf(c); // 线程池SHUTDOWN且队列为空，返回null让Worker退出 if (rs &gt;= SHUTDOWN &amp;&amp; (rs &gt;= STOP || workQueue.isEmpty())) &#123; decrementWorkerCount(); return null; &#125; int wc = workerCountOf(c); // 是否需要超时控制 boolean timed = allowCoreThreadTimeOut || wc &gt; corePoolSize; // 退出条件： // 1. 线程数超过maximumPoolSize（被动态调小了） // 2. 超时且（允许核心线程超时 或 当前线程数 &gt; corePoolSize） // 3. 队列为空 或 线程数 &gt; 1（保留至少一个线程处理任务） if ((wc &gt; maximumPoolSize || (timed &amp;&amp; timedOut)) &amp;&amp; (wc &gt; 1 || workQueue.isEmpty())) &#123; if (compareAndDecrementWorkerCount(c)) return null; // CAS减少线程数成功，Worker退出 continue; &#125; try &#123; // 关键分支：阻塞获取 vs 超时获取 Runnable r = timed ? workQueue.poll(keepAliveTime, TimeUnit.NANOSECONDS) : workQueue.take(); // 核心线程永远阻塞等待 if (r != null) return r; timedOut = true; // poll超时 &#125; catch (InterruptedException retry) &#123; timedOut = false; // 被中断，重试 &#125; &#125;&#125;
核心线程 非核心线程
线程池参数计算核心计算公式线程池参数的计算不是凭直觉，而是有经典理论支撑。Brian Goetz 在《Java并发编程实战》中给出了业界公认的计算公式。 线程数计算公式： CPU密集型任务： 线程数 = CPU核数 + 1 → 大部分时间在计算，线程多了反而增加上下文切换 → +1 是为了在某个线程偶尔因为页缺失故障等原因暂停时，额外的线程仍能利用CPU IO密集型任务： 线程数 = CPU核数 × (1 + 等待时间/计算时间) → 大部分时间在等待IO，需要更多线程来提高并发 → 等待时间/计算时间 的比值决定了需要多少额外线程 混合型任务： 根据IO等待比例调整，一般 CPU核数 × 2 ~ CPU核数 × 4 → 先按IO密集型估算，再通过压测调整 公式推导过程： 设 CPU计算时间 = C，IO等待时间 = W CPU利用率 = 线程数 × C / (C + W) = 1（目标：CPU利用率100%） ∴ 线程数 = (C + W) / C = 1 + W/C = 1 + 等待时间/计算时间 多核场景：线程数 = CPU核数 × (1 + W/C)
线程池配置实战1. 实际项目线程池配置类@Configuration@Slf4jpublic class ThreadPoolConfig &#123; /** * 传感器数据采集线程池（IO密集型） * 8核CPU → 核心24，最大48，队列1000 * 场景：井下传感器数据写入MQ + 持久化到时序数据库 */ @Bean(&quot;sensorDataExecutor&quot;) public ThreadPoolExecutor sensorDataExecutor() &#123; return new ThreadPoolExecutor( 24, // 核心线程：IO密集型，需要多线程 48, // 最大线程：突发时扩容到48 60, TimeUnit.SECONDS, // 非核心线程空闲60秒回收 new LinkedBlockingQueue&lt;&gt;(1000), // 有界队列1000，防止OOM new CustomThreadFactory(&quot;sensor-data&quot;), // 自定义线程工厂 new ThreadPoolExecutor.CallerRunsPolicy() // 队列满时由调用线程执行，降速不丢数据 ); &#125; /** * 告警推送线程池（IO密集型，允许丢弃） * 8核CPU → 核心16，最大32，队列200 * 场景：推送告警消息到短信/邮件/企业微信 */ @Bean(&quot;alertNotifyExecutor&quot;) public ThreadPoolExecutor alertNotifyExecutor() &#123; return new ThreadPoolExecutor( 16, 32, 120, TimeUnit.SECONDS, new LinkedBlockingQueue&lt;&gt;(200), new CustomThreadFactory(&quot;alert-notify&quot;), new PersistAndRejectPolicy() // 自定义拒绝策略：持久化失败任务 ); &#125; /** * 报表数据导出线程池（CPU密集型） * 8核CPU → 核心8，最大16，队列50 * 场景：内存聚合计算 + Excel/PDF生成下载 */ @Bean(&quot;reportExportExecutor&quot;) public ThreadPoolExecutor reportExportExecutor() &#123; return new ThreadPoolExecutor( 8, 16, 300, TimeUnit.SECONDS, // 导出任务可能较长，延长回收时间 new LinkedBlockingQueue&lt;&gt;(50), new CustomThreadFactory(&quot;report-export&quot;), new ThreadPoolExecutor.AbortPolicy() // 拒绝时抛异常，前端提示用户稍后重试 ); &#125; /** * 设备指令下发线程池（IO密集型） * 8核CPU → 核心20，最大40，队列500 * 场景：向PLC下发控制指令，等待PLC响应 */ @Bean(&quot;deviceCommandExecutor&quot;) public ThreadPoolExecutor deviceCommandExecutor() &#123; return new ThreadPoolExecutor( 20, 40, 60, TimeUnit.SECONDS, new LinkedBlockingQueue&lt;&gt;(500), new CustomThreadFactory(&quot;device-cmd&quot;), new ThreadPoolExecutor.CallerRunsPolicy() // 设备指令不能丢失，调用者执行 ); &#125; /** * 历史数据同步线程池（IO密集型，受数据库连接池限制） * 8核CPU → 核心12，最大15，队列200 * 场景：大批量历史数据迁移（受数据库连接池15个连接的限制） */ @Bean(&quot;dataSyncExecutor&quot;) public ThreadPoolExecutor dataSyncExecutor() &#123; return new ThreadPoolExecutor( 12, 15, // 最大线程数不能超过数据库连接池大小 300, TimeUnit.SECONDS, new LinkedBlockingQueue&lt;&gt;(200), new CustomThreadFactory(&quot;data-sync&quot;), new ThreadPoolExecutor.AbortPolicy() ); &#125; /** * 实时数据分析线程池（CPU密集型） * 8核CPU → 核心10，最大20，队列100 * 场景：流式计算 + 规则引擎实时匹配 */ @Bean(&quot;realTimeAnalysisExecutor&quot;) public ThreadPoolExecutor realTimeAnalysisExecutor() &#123; return new ThreadPoolExecutor( 10, 20, 60, TimeUnit.SECONDS, new LinkedBlockingQueue&lt;&gt;(100), new CustomThreadFactory(&quot;rt-analysis&quot;), new ThreadPoolExecutor.CallerRunsPolicy() ); &#125;&#125;
2. 自定义线程工厂public class CustomThreadFactory implements ThreadFactory &#123; private final AtomicInteger threadNumber = new AtomicInteger(1); private final String namePrefix; private final boolean daemon; private final int priority; public CustomThreadFactory(String namePrefix) &#123; this(namePrefix, false, Thread.NORM_PRIORITY); &#125; public CustomThreadFactory(String namePrefix, boolean daemon, int priority) &#123; this.namePrefix = namePrefix; this.daemon = daemon; this.priority = priority; &#125; @Override public Thread newThread(Runnable r) &#123; Thread t = new Thread(r, namePrefix + &quot;-&quot; + threadNumber.getAndIncrement()); t.setDaemon(daemon); t.setPriority(priority); // 设置未捕获异常处理器——防止任务异常导致线程静默退出 t.setUncaughtExceptionHandler((thread, ex) -&gt; log.error(&quot;线程异常退出: thread=&#123;&#125;, error=&#123;&#125;&quot;, thread.getName(), ex.getMessage(), ex)); return t; &#125;&#125;
自定义线程工厂的必要性： 默认线程工厂的问题： ① 线程命名：pool-N-thread-M，无法区分业务 ② 守护线程：默认非守护，JVM无法正常退出 ③ 优先级：默认NORM_PRIORITY，无法按业务调整 ④ 异常处理：默认无UncaughtExceptionHandler，异常导致线程静默退出 命名规范（实际项目实践）： sensor-data-1, sensor-data-2, ... → 传感器数据采集 alert-notify-1, alert-notify-2, ... → 告警推送 report-export-1, ... → 报表导出 device-cmd-1, ... → 设备指令 data-sync-1, ... → 数据同步 rt-analysis-1, ... → 实时分析 命名的好处： → jstack排查时一眼定位业务线程 → 监控面板按线程名分组统计 → 日志中线程名直接关联业务 → CPU飙高时快速定位是哪个业务池
3. 自定义拒绝策略——持久化失败任务/** * 持久化拒绝策略：任务被拒绝时记录日志并持久化到数据库 * 后台补偿任务定期扫描并重新提交 * * 适用场景：告警推送、数据同步等不能丢失的任务 */@Slf4jpublic class PersistAndRejectPolicy implements RejectedExecutionHandler &#123; @Override public void rejectedExecution(Runnable r, ThreadPoolExecutor executor) &#123; // 记录详细拒绝信息 log.warn(&quot;任务被拒绝: pool=&#123;&#125;, active=&#123;&#125;/&#123;&#125;, queue=&#123;&#125;/&#123;&#125;&quot;, executor instanceof ThreadPoolExecutor ? ((ThreadPoolExecutor) executor).getThreadFactory().toString() : &quot;unknown&quot;, executor.getActiveCount(), executor.getMaximumPoolSize(), executor.getQueue().size(), executor.getQueue().size() + executor.getQueue().remainingCapacity() ); // 持久化失败任务 if (r instanceof PersistableTask) &#123; PersistableTask task = (PersistableTask) r; try &#123; // 获取Spring上下文中的Bean（线程池拒绝策略不在Spring容器中） FailedTaskService failedTaskService = SpringContextHolder.getBean(FailedTaskService.class); failedTaskService.save(task.toFailedTask()); log.info(&quot;失败任务已持久化: taskId=&#123;&#125;, taskType=&#123;&#125;&quot;, task.getTaskId(), task.getTaskType()); &#125; catch (Exception e) &#123; log.error(&quot;失败任务持久化异常，任务可能丢失: taskId=&#123;&#125;&quot;, task.getTaskId(), e); // 兜底：降级为CallerRunsPolicy，由调用线程执行 if (!executor.isShutdown()) &#123; r.run(); &#125; &#125; &#125; else &#123; // 非PersistableTask，降级为调用者执行 if (!executor.isShutdown()) &#123; log.warn(&quot;非持久化任务被拒绝，降级为调用者执行&quot;); r.run(); &#125; &#125; &#125;&#125;
/** * 失败任务补偿调度器 * 定期扫描failed_task表，重新提交到线程池 */@Component@Slf4jpublic class FailedTaskCompensator &#123; @Autowired private FailedTaskMapper failedTaskMapper; @Autowired @Qualifier(&quot;alertNotifyExecutor&quot;) private ThreadPoolExecutor alertNotifyExecutor; @Scheduled(fixedDelay = 60000) // 每分钟扫描一次 public void compensate() &#123; List&lt;FailedTask&gt; tasks = failedTaskMapper.selectPendingTasks(100); for (FailedTask task : tasks) &#123; try &#123; // 重建任务对象并提交 Runnable runnable = task.toRunnable(); alertNotifyExecutor.execute(runnable); // 标记为已补偿 failedTaskMapper.updateStatus(task.getId(), &quot;COMPENSATED&quot;); log.info(&quot;失败任务已补偿: taskId=&#123;&#125;&quot;, task.getTaskId()); &#125; catch (RejectedExecutionException e) &#123; // 线程池仍然拒绝，等待下次补偿 log.warn(&quot;补偿任务再次被拒绝，等待下次: taskId=&#123;&#125;&quot;, task.getTaskId()); break; // 队列又满了，停止本轮补偿 &#125; &#125; &#125;&#125;
策略 行为 适用场景
AbortPolicy 抛出RejectedExecution 不能丢失但可以反馈错误的场景
(默认) Exception 如：报表导出（前端提示用户稍后重试）
CallerRunsPolicy 调用者线程执行任务 不能丢失且可以降速的场景
DiscardOldestPolicy 丢弃队列最老任务 实时性要求高的场景
DiscardPolicy 静默丢弃当前任务 可丢弃且无需感知的场景
自定义策略 持久化 + 补偿 不能丢失且不能降速的场景
线程池监控体系监控指标采集@Component@Slf4jpublic class ThreadPoolMonitor &#123; @Autowired @Qualifier(&quot;sensorDataExecutor&quot;) private ThreadPoolExecutor sensorDataExecutor; @Autowired @Qualifier(&quot;alertNotifyExecutor&quot;) private ThreadPoolExecutor alertNotifyExecutor; @Autowired @Qualifier(&quot;reportExportExecutor&quot;) private ThreadPoolExecutor reportExportExecutor; @Autowired @Qualifier(&quot;deviceCommandExecutor&quot;) private ThreadPoolExecutor deviceCommandExecutor; @Autowired @Qualifier(&quot;dataSyncExecutor&quot;) private ThreadPoolExecutor dataSyncExecutor; @Autowired @Qualifier(&quot;realTimeAnalysisExecutor&quot;) private ThreadPoolExecutor realTimeAnalysisExecutor; @Scheduled(fixedDelay = 30000) // 每30秒采集一次 public void monitorAllPools() &#123; monitorPool(&quot;传感器数据采集&quot;, sensorDataExecutor); monitorPool(&quot;告警推送&quot;, alertNotifyExecutor); monitorPool(&quot;报表导出&quot;, reportExportExecutor); monitorPool(&quot;设备指令下发&quot;, deviceCommandExecutor); monitorPool(&quot;数据同步&quot;, dataSyncExecutor); monitorPool(&quot;实时分析&quot;, realTimeAnalysisExecutor); &#125; private void monitorPool(String name, ThreadPoolExecutor pool) &#123; int activeCount = pool.getActiveCount(); int corePoolSize = pool.getCorePoolSize(); int maximumPoolSize = pool.getMaximumPoolSize(); int poolSize = pool.getPoolSize(); long completedTaskCount = pool.getCompletedTaskCount(); int queueSize = pool.getQueue().size(); int queueCapacity = queueSize + pool.getQueue().remainingCapacity(); double queueUsage = queueCapacity &gt; 0 ? (double) queueSize / queueCapacity : 0; double threadUsage = (double) activeCount / maximumPoolSize; log.info(&quot;[线程池监控] &#123;&#125; - 核心线程: &#123;&#125;, 当前线程: &#123;&#125;, 活跃: &#123;&#125;, 最大: &#123;&#125;, &quot; + &quot;队列: &#123;&#125;/&#123;&#125;, 队列使用率: &#123;:.1f&#125;%, 已完成: &#123;&#125;&quot;, name, corePoolSize, poolSize, activeCount, maximumPoolSize, queueSize, queueCapacity, queueUsage * 100, completedTaskCount); // 告警1：队列使用率超过80% if (queueUsage &gt; 0.8) &#123; log.warn(&quot;[线程池告警] &#123;&#125; 队列使用率超过80%: &#123;:.1f&#125;% (&#123;&#125;/&#123;&#125;)&quot;, name, queueUsage * 100, queueSize, queueCapacity); &#125; // 告警2：活跃线程数持续接近最大线程数 if (activeCount &gt;= maximumPoolSize * 0.9) &#123; log.warn(&quot;[线程池告警] &#123;&#125; 活跃线程接近最大值: &#123;&#125;/&#123;&#125;&quot;, name, activeCount, maximumPoolSize); &#125; // 告警3：线程池活跃线程持续超过核心线程数 if (activeCount &gt; corePoolSize &amp;&amp; queueUsage &gt; 0.5) &#123; log.warn(&quot;[线程池告警] &#123;&#125; 非核心线程已激活，且队列过半: 活跃=&#123;&#125;, 核心=&#123;&#125;, 队列=&#123;:.1f&#125;%&quot;, name, activeCount, corePoolSize, queueUsage * 100); &#125; &#125;&#125;
Prometheus + Grafana 监控集成/** * 线程池指标导出到Prometheus */@Componentpublic class ThreadPoolMetricsExporter &#123; private final AtomicInteger sensorDataActiveGauge = new AtomicInteger(); private final AtomicInteger sensorDataQueueGauge = new AtomicInteger(); private final AtomicInteger alertNotifyActiveGauge = new AtomicInteger(); private final AtomicInteger alertNotifyQueueGauge = new AtomicInteger(); @Autowired @Qualifier(&quot;sensorDataExecutor&quot;) private ThreadPoolExecutor sensorDataExecutor; @Autowired @Qualifier(&quot;alertNotifyExecutor&quot;) private ThreadPoolExecutor alertNotifyExecutor; @Scheduled(fixedDelay = 10000) // 每10秒刷新指标 public void exportMetrics() &#123; sensorDataActiveGauge.set(sensorDataExecutor.getActiveCount()); sensorDataQueueGauge.set(sensorDataExecutor.getQueue().size()); alertNotifyActiveGauge.set(alertNotifyExecutor.getActiveCount()); alertNotifyQueueGauge.set(alertNotifyExecutor.getQueue().size()); &#125; @Bean MeterRegistryCustomizer&lt;MeterRegistry&gt; threadPoolMetrics() &#123; return registry -&gt; &#123; // 传感器数据采集线程池指标 Gauge.builder(&quot;threadpool.sensor.active&quot;, sensorDataActiveGauge, AtomicInteger::get) .description(&quot;传感器数据采集线程池活跃线程数&quot;) .register(registry); Gauge.builder(&quot;threadpool.sensor.queue&quot;, sensorDataQueueGauge, AtomicInteger::get) .description(&quot;传感器数据采集线程池队列大小&quot;) .register(registry); // 告警推送线程池指标 Gauge.builder(&quot;threadpool.alert.active&quot;, alertNotifyActiveGauge, AtomicInteger::get) .description(&quot;告警推送线程池活跃线程数&quot;) .register(registry); Gauge.builder(&quot;threadpool.alert.queue&quot;, alertNotifyQueueGauge, AtomicInteger::get) .description(&quot;告警推送线程池队列大小&quot;) .register(registry); &#125;; &#125;&#125;
# Grafana Dashboard 关键指标（PromQL）# 1. 线程池活跃线程数threadpool_sensor_active&#123;&#125;# 2. 队列大小threadpool_sensor_queue&#123;&#125;# 3. 队列使用率threadpool_sensor_queue&#123;&#125; / 1000 * 100# 4. 线程利用率threadpool_sensor_active&#123;&#125; / 48 * 100# 报警规则（AlertManager）# - 队列使用率 &gt; 80% 持续3分钟 → WARN# - 活跃线程数 = 最大线程数 持续5分钟 → CRITICAL# - 队列大小持续增长（斜率 &gt; 0）5分钟 → CRITICAL
线程池健康检查接口@RestController@RequestMapping(&quot;/api/monitor&quot;)@Slf4jpublic class ThreadPoolHealthController &#123; @Autowired private Map&lt;String, ThreadPoolExecutor&gt; executors; @GetMapping(&quot;/thread-pools&quot;) public List&lt;ThreadPoolStatus&gt; getThreadPoolStatus() &#123; List&lt;ThreadPoolStatus&gt; statusList = new ArrayList&lt;&gt;(); for (Map.Entry&lt;String, ThreadPoolExecutor&gt; entry : executors.entrySet()) &#123; ThreadPoolExecutor pool = entry.getValue(); int queueSize = pool.getQueue().size(); int queueCapacity = queueSize + pool.getQueue().remainingCapacity(); ThreadPoolStatus status = ThreadPoolStatus.builder() .name(entry.getKey()) .corePoolSize(pool.getCorePoolSize()) .maximumPoolSize(pool.getMaximumPoolSize()) .activeCount(pool.getActiveCount()) .poolSize(pool.getPoolSize()) .queueSize(queueSize) .queueCapacity(queueCapacity) .queueUsageRate(queueCapacity &gt; 0 ? (double) queueSize / queueCapacity : 0) .completedTaskCount(pool.getCompletedTaskCount()) .build(); statusList.add(status); &#125; return statusList; &#125;&#125;
监控大盘架构架构流程： flowchart TD N1[&quot;sensor-data&quot;] N2[&quot;ThreadPoolMonitor定时采集 每30秒采集各池指标&quot;] N3[&quot;判断告警条件 每10秒刷新Prometheus Gauge指标&quot;] N4[&quot;alert-notify&quot;] N5[&quot;report-export&quot;] N6[&quot;...更多线程池 Executor&quot;] N7[&quot;Executor Executor&quot;] N8[&quot;日志告警 Prometheus 健康检查接口 (WARN)&quot;] N9[&quot;Grafana (apimonitor)&quot;] N10[&quot;企业微信 Dashboard K8s探针&quot;] N11[&quot;告警群 可视化 liveness&quot;] N1 --&gt; N2 N1 --&gt; N3 N4 --&gt; N2 N4 --&gt; N3 N5 --&gt; N2 N5 --&gt; N3 N6 --&gt; N2 N6 --&gt; N3 N7 --&gt; N2 N7 --&gt; N3 N2 --&gt; N8 N2 --&gt; N9 N3 --&gt; N8 N3 --&gt; N9 N8 --&gt; N9 N9 --&gt; N8 N8 --&gt; N10 N8 --&gt; N11 N9 --&gt; N10 N9 --&gt; N11
动态线程池基于Nacos的动态配置@Configuration@RefreshScope // 支持Nacos动态刷新@Slf4jpublic class DynamicThreadPoolConfig &#123; @Value(&quot;$&#123;thread-pool.sensor-data.core-size:24&#125;&quot;) private int sensorDataCoreSize; @Value(&quot;$&#123;thread-pool.sensor-data.max-size:48&#125;&quot;) private int sensorDataMaxSize; @Value(&quot;$&#123;thread-pool.sensor-data.queue-capacity:1000&#125;&quot;) private int sensorDataQueueCapacity; @Value(&quot;$&#123;thread-pool.alert-notify.core-size:16&#125;&quot;) private int alertNotifyCoreSize; @Value(&quot;$&#123;thread-pool.alert-notify.max-size:32&#125;&quot;) private int alertNotifyMaxSize; @Value(&quot;$&#123;thread-pool.alert-notify.queue-capacity:200&#125;&quot;) private int alertNotifyQueueCapacity; @Bean(&quot;sensorDataExecutor&quot;) public ThreadPoolExecutor sensorDataExecutor() &#123; return new ThreadPoolExecutor( sensorDataCoreSize, sensorDataMaxSize, 60, TimeUnit.SECONDS, new ResizableCapacityLinkedBlockingQueue&lt;&gt;(sensorDataQueueCapacity), new CustomThreadFactory(&quot;sensor-data&quot;), new ThreadPoolExecutor.CallerRunsPolicy() ); &#125; @Bean(&quot;alertNotifyExecutor&quot;) public ThreadPoolExecutor alertNotifyExecutor() &#123; return new ThreadPoolExecutor( alertNotifyCoreSize, alertNotifyMaxSize, 120, TimeUnit.SECONDS, new ResizableCapacityLinkedBlockingQueue&lt;&gt;(alertNotifyQueueCapacity), new CustomThreadFactory(&quot;alert-notify&quot;), new PersistAndRejectPolicy() ); &#125;&#125;
# Nacos配置（thread-pool.yaml）thread-pool: sensor-data: core-size: 24 max-size: 48 queue-capacity: 1000 alert-notify: core-size: 16 max-size: 32 queue-capacity: 200 report-export: core-size: 8 max-size: 16 queue-capacity: 50 device-command: core-size: 20 max-size: 40 queue-capacity: 500 data-sync: core-size: 12 max-size: 15 queue-capacity: 200 rt-analysis: core-size: 10 max-size: 20 queue-capacity: 100
运行时动态调整@Service@Slf4jpublic class ThreadPoolAdjustService &#123; @Autowired @Qualifier(&quot;sensorDataExecutor&quot;) private ThreadPoolExecutor sensorDataExecutor; /** * 动态调整线程池参数（无需重启） * * 关键调整顺序： * 1. 调大时：先调大maxPoolSize，再调大corePoolSize * → 否则 corePoolSize &gt; maxPoolSize 时会报IllegalArgumentException * * 2. 调小时：先调小corePoolSize，再调小maxPoolSize * → 否则同样会校验失败 */ public void adjustPool(ThreadPoolExecutor executor, String poolName, int coreSize, int maxSize) &#123; int oldCore = executor.getCorePoolSize(); int oldMax = executor.getMaximumPoolSize(); log.info(&quot;调整线程池 &#123;&#125;: coreSize &#123;&#125; → &#123;&#125;, maxSize &#123;&#125; → &#123;&#125;&quot;, poolName, oldCore, coreSize, oldMax, maxSize); if (maxSize &gt; executor.getMaximumPoolSize()) &#123; // 调大：先max后core executor.setMaximumPoolSize(maxSize); executor.setCorePoolSize(coreSize); &#125; else &#123; // 调小：先core后max executor.setCorePoolSize(coreSize); executor.setMaximumPoolSize(maxSize); &#125; log.info(&quot;线程池 &#123;&#125; 调整完成: coreSize=&#123;&#125;, maxSize=&#123;&#125;, currentPoolSize=&#123;&#125;&quot;, poolName, executor.getCorePoolSize(), executor.getMaximumPoolSize(), executor.getPoolSize()); &#125; /** * 动态调整队列容量（需要ResizableCapacityLinkedBlockingQueue） */ public void adjustQueueCapacity(ThreadPoolExecutor executor, String poolName, int capacity) &#123; if (executor.getQueue() instanceof ResizableCapacityLinkedBlockingQueue) &#123; ResizableCapacityLinkedBlockingQueue&lt;Runnable&gt; queue = (ResizableCapacityLinkedBlockingQueue&lt;Runnable&gt;) executor.getQueue(); int oldCapacity = queue.size() + queue.remainingCapacity(); queue.setCapacity(capacity); log.info(&quot;线程池 &#123;&#125; 队列容量调整: &#123;&#125; → &#123;&#125;&quot;, poolName, oldCapacity, capacity); &#125; else &#123; log.warn(&quot;线程池 &#123;&#125; 队列类型不支持动态调整容量&quot;, poolName); &#125; &#125;&#125;
场景 调整方式 说明
业务高峰来临 增大core + max + queue 提前扩容，避免拒绝
业务低峰期 减小core + max 释放线程资源
压测验证 逐步增大观察指标 找到最优参数
应急降级 减小max + queue 限制线程池处理能力
任务积压告警 增大core + queue 加速消费积压任务
基于指标的自适应调参/** * 线程池自适应调参器 * 根据监控指标自动调整线程池参数 */@Component@Slf4jpublic class ThreadPoolAutoTuner &#123; @Autowired @Qualifier(&quot;sensorDataExecutor&quot;) private ThreadPoolExecutor sensorDataExecutor; @Autowired private ThreadPoolAdjustService adjustService; // 最近N次采集的队列使用率 private final Queue&lt;Double&gt; queueUsageHistory = new LinkedList&lt;&gt;(); private static final int HISTORY_SIZE = 10; // 5分钟历史（30秒采集一次） @Scheduled(fixedDelay = 30000) public void autoTune() &#123; int queueSize = sensorDataExecutor.getQueue().size(); int queueCapacity = queueSize + sensorDataExecutor.getQueue().remainingCapacity(); double queueUsage = queueCapacity &gt; 0 ? (double) queueSize / queueCapacity : 0; queueUsageHistory.offer(queueUsage); if (queueUsageHistory.size() &gt; HISTORY_SIZE) &#123; queueUsageHistory.poll(); &#125; // 至少5个数据点才开始自适应 if (queueUsageHistory.size() &lt; 5) &#123; return; &#125; double avgUsage = queueUsageHistory.stream() .mapToDouble(Double::doubleValue).average().orElse(0); int coreSize = sensorDataExecutor.getCorePoolSize(); int maxSize = sensorDataExecutor.getMaximumPoolSize(); // 自适应策略： // 1. 平均队列使用率 &gt; 70% 且 当前核心线程 &lt; 最大线程 → 扩容核心线程 if (avgUsage &gt; 0.7 &amp;&amp; coreSize &lt; maxSize) &#123; int newCoreSize = Math.min(coreSize + 4, maxSize); adjustService.adjustPool(sensorDataExecutor, &quot;sensor-data&quot;, newCoreSize, maxSize); log.info(&quot;自适应扩容: coreSize &#123;&#125; → &#123;&#125;, 原因: 平均队列使用率 &#123;:.1f&#125;%&quot;, coreSize, newCoreSize, avgUsage * 100); &#125; // 2. 平均队列使用率 &lt; 20% 且 当前核心线程 &gt; 初始值 → 缩容核心线程 if (avgUsage &lt; 0.2 &amp;&amp; coreSize &gt; 24) &#123; // 24是初始核心线程数 int newCoreSize = Math.max(coreSize - 4, 24); adjustService.adjustPool(sensorDataExecutor, &quot;sensor-data&quot;, newCoreSize, maxSize); log.info(&quot;自适应缩容: coreSize &#123;&#125; → &#123;&#125;, 原因: 平均队列使用率 &#123;:.1f&#125;%&quot;, coreSize, newCoreSize, avgUsage * 100); &#125; &#125;&#125;
Spring @Async 线程池配置@Async 默认线程池的问题Spring @Async 默认行为： ① 未自定义AsyncConfigurer时： → 使用 SimpleAsyncTaskExecutor → 每次调用 @Async 方法都创建新线程！ → 无线程复用、无队列、无上限 → 并发高时OOM ② Spring Boot 2.1+ 默认行为： → 使用 ThreadPoolTaskExecutor → 默认配置：core=1, max=Integer.MAX_VALUE, queue=Integer.MAX_VALUE → 虽然有线程复用，但队列是无界的 → 同样有OOM风险 ③ 所有@Async方法共享同一个线程池： → 一个慢任务阻塞线程，影响其他异步方法 → 无法按业务隔离
自定义AsyncConfigurer@Configuration@Slf4jpublic class AsyncConfig implements AsyncConfigurer &#123; @Override public Executor getAsyncExecutor() &#123; ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor(); executor.setCorePoolSize(10); executor.setMaxPoolSize(50); executor.setQueueCapacity(500); executor.setKeepAliveSeconds(60); executor.setThreadNamePrefix(&quot;async-task-&quot;); executor.setRejectedExecutionHandler(new ThreadPoolExecutor.CallerRunsPolicy()); executor.setWaitForTasksToCompleteOnShutdown(true); // 优雅关闭 executor.setAwaitTerminationSeconds(60); executor.initialize(); return executor; &#125; @Override public AsyncUncaughtExceptionHandler getAsyncUncaughtExceptionHandler() &#123; return (throwable, method, params) -&gt; log.error(&quot;@Async异常: method=&#123;&#125;, params=&#123;&#125;, error=&#123;&#125;&quot;, method.getName(), Arrays.toString(params), throwable.getMessage(), throwable); &#125;&#125;
按业务隔离的@Async线程池@Configurationpublic class AsyncExecutorConfig &#123; /** * 告警推送异步线程池 */ @Bean(&quot;alertAsyncExecutor&quot;) public Executor alertAsyncExecutor() &#123; ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor(); executor.setCorePoolSize(8); executor.setMaxPoolSize(20); executor.setQueueCapacity(200); executor.setKeepAliveSeconds(60); executor.setThreadNamePrefix(&quot;alert-async-&quot;); executor.setRejectedExecutionHandler(new PersistAndRejectPolicy()); executor.setWaitForTasksToCompleteOnShutdown(true); executor.setAwaitTerminationSeconds(60); executor.initialize(); return executor; &#125; /** * 数据同步异步线程池 */ @Bean(&quot;syncAsyncExecutor&quot;) public Executor syncAsyncExecutor() &#123; ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor(); executor.setCorePoolSize(4); executor.setMaxPoolSize(10); executor.setQueueCapacity(100); executor.setKeepAliveSeconds(120); executor.setThreadNamePrefix(&quot;sync-async-&quot;); executor.setRejectedExecutionHandler(new ThreadPoolExecutor.AbortPolicy()); executor.setWaitForTasksToCompleteOnShutdown(true); executor.setAwaitTerminationSeconds(120); executor.initialize(); return executor; &#125;&#125;// 使用时指定线程池@Servicepublic class AlertService &#123; @Async(&quot;alertAsyncExecutor&quot;) // 指定使用告警推送线程池 public void sendAlertAsync(AlertMessage message) &#123; // 异步推送告警 &#125;&#125;@Servicepublic class DataSyncService &#123; @Async(&quot;syncAsyncExecutor&quot;) // 指定使用数据同步线程池 public void syncDataAsync(SyncTask task) &#123; // 异步同步数据 &#125;&#125;
优雅关闭完整的优雅关闭方案@Component@Slf4jpublic class GracefulShutdown implements DisposableBean, Ordered &#123; @Autowired @Qualifier(&quot;sensorDataExecutor&quot;) private ThreadPoolExecutor sensorDataExecutor; @Autowired @Qualifier(&quot;alertNotifyExecutor&quot;) private ThreadPoolExecutor alertNotifyExecutor; @Autowired @Qualifier(&quot;reportExportExecutor&quot;) private ThreadPoolExecutor reportExportExecutor; @Autowired @Qualifier(&quot;deviceCommandExecutor&quot;) private ThreadPoolExecutor deviceCommandExecutor; @Override public int getOrder() &#123; return Ordered.LOWEST_PRECEDENCE - 1; // 确保在其他销毁方法之后执行 &#125; @Override public void destroy() throws Exception &#123; log.info(&quot;开始优雅关闭线程池...&quot;); long startTime = System.currentTimeMillis(); Map&lt;String, ThreadPoolExecutor&gt; pools = new LinkedHashMap&lt;&gt;(); pools.put(&quot;传感器数据采集&quot;, sensorDataExecutor); pools.put(&quot;告警推送&quot;, alertNotifyExecutor); pools.put(&quot;报表导出&quot;, reportExportExecutor); pools.put(&quot;设备指令下发&quot;, deviceCommandExecutor); // 第一步：停止接受新任务 pools.forEach((name, pool) -&gt; &#123; pool.shutdown(); log.info(&quot;线程池 [&#123;&#125;] 已停止接受新任务, 剩余任务: &#123;&#125;&quot;, name, pool.getQueue().size()); &#125;); // 第二步：等待已提交的任务完成 for (Map.Entry&lt;String, ThreadPoolExecutor&gt; entry : pools.entrySet()) &#123; String name = entry.getKey(); ThreadPoolExecutor pool = entry.getValue(); try &#123; if (!pool.awaitTermination(60, TimeUnit.SECONDS)) &#123; log.warn(&quot;线程池 [&#123;&#125;] 未在60秒内关闭, 剩余任务: &#123;&#125;, 强制关闭&quot;, name, pool.getQueue().size()); List&lt;Runnable&gt; droppedTasks = pool.shutdownNow(); log.warn(&quot;线程池 [&#123;&#125;] 强制关闭, 丢弃任务数: &#123;&#125;&quot;, name, droppedTasks.size()); // 持久化被丢弃的任务 for (Runnable task : droppedTasks) &#123; if (task instanceof PersistableTask) &#123; try &#123; FailedTaskService service = SpringContextHolder.getBean(FailedTaskService.class); service.save(((PersistableTask) task).toFailedTask()); &#125; catch (Exception e) &#123; log.error(&quot;持久化丢弃任务失败&quot;, e); &#125; &#125; &#125; // 再等待10秒 if (!pool.awaitTermination(10, TimeUnit.SECONDS)) &#123; log.error(&quot;线程池 [&#123;&#125;] 无法关闭!&quot;, name); &#125; &#125; &#125; catch (InterruptedException e) &#123; pool.shutdownNow(); Thread.currentThread().interrupt(); &#125; &#125; long elapsed = System.currentTimeMillis() - startTime; log.info(&quot;所有线程池已关闭, 耗时: &#123;&#125;ms&quot;, elapsed); &#125;&#125;
Spring Boot 优雅关闭配置# application.ymlserver: shutdown: graceful # Spring Boot 2.3+ 优雅关闭spring: lifecycle: timeout-per-shutdown-phase: 60s # 优雅关闭超时时间
架构流程： flowchart TD N1[&quot;K8s发送 SIGTERM 信号到Pod&quot;] N2[&quot;Spring Boot 开始优雅关闭&quot;] N3[&quot;Web容器停止接受新请求&quot;] N4[&quot;等待已有请求处理完毕最多60s&quot;] N5[&quot;DisposableBean.destroy() 被调用 线程池shutdown()&quot;] N6[&quot;强制关闭 持久化被丢弃的任务&quot;] N7[&quot;JVM 退出&quot;] N1 --&gt; N2 N1 --&gt; N3 N1 --&gt; N4 N2 --&gt; N3 N2 --&gt; N4 N3 --&gt; N2 N3 --&gt; N4 N4 --&gt; N2 N4 --&gt; N3 N2 --&gt; N5 N2 --&gt; N6 N3 --&gt; N5 N3 --&gt; N6 N4 --&gt; N5 N4 --&gt; N6 N5 --&gt; N7 N6 --&gt; N7
线程池常见问题与解决方案以下是实际项目及同类项目中实际遇到的问题，以表格形式汇总，供快速查阅。 核心配置问题
# 问题 现象 根因 解决方案
1 无界队列导致OOM 堆内存持续增长，最终OOM，实际项目传感器数据采集服务因无界队列堆积数十万任务对象导致内存溢出 使用LinkedBlockingQueue无参构造（默认Integer.MAX_VALUE容量），高峰期任务堆积无法触发拒绝策略 1. 必须使用有界队列，指定容量；2. 队列容量 &#x3D; 任务耗时 x 峰值QPS x 缓冲系数；3. 压测验证队列不会无限增长
2 核心线程数&#x3D;最大线程数 队列满之前不会创建新线程，突发流量时队列先满再拒绝，响应延迟高 corePoolSize &#x3D; maximumPoolSize 时，线程数不会弹性伸缩，队列满直接拒绝 1. 核心 &lt; 最大，一般最大&#x3D;核心x2；2. 允许突发时短暂扩容；3. 配合keepAliveTime回收非核心线程
3 使用Executors创建线程池 newFixedThreadPool无界队列OOM；newCachedThreadPool最大线程Integer.MAX_VALUE导致OOM Executors工厂方法隐藏了危险配置，阿里巴巴规范强制禁止使用 1. 手动创建ThreadPoolExecutor；2. 明确指定每个参数；3. 代码审查&#x2F;静态扫描拦截Executors使用
4 Spring @Async默认线程池 SimpleAsyncTaskExecutor每次新建线程，并发高时线程数暴增 未自定义AsyncConfigurer，Spring使用默认的SimpleAsyncTaskExecutor 1. 实现AsyncConfigurer自定义线程池；2. 使用ThreadPoolTaskExecutor；3. 按业务隔离指定不同线程池
5 keepAliveTime设置过小 非核心线程频繁创建销毁，CPU出现周期性尖刺 keepAliveTime过短（如1秒），线程刚空闲就被回收，下次任务又需创建 1. IO密集型建议60秒以上；2. CPU密集型建议30秒以上；3. 监控线程创建速率，频繁创建则调大
任务处理问题
# 问题 现象 根因 解决方案
6 任务拒绝导致数据丢失 告警推送任务被AbortPolicy拒绝，安全告警丢失 使用了AbortPolicy但没有兜底机制，告警是安全关键数据不能丢失 1. 告警场景使用自定义PersistAndRejectPolicy；2. 持久化失败任务+定时补偿；3. 或使用CallerRunsPolicy降速不丢数据
7 任务执行异常线程静默退出 线程池线程数逐渐减少，最终只剩1个线程处理所有任务 任务抛出异常未被捕获，Worker.runWorker()中异常导致Worker退出，线程池自动补充但可能不够快 1. 任务内部try-catch捕获所有异常；2. 自定义ThreadFactory设置UncaughtExceptionHandler；3. 重写afterExecute钩子记录异常
8 任务超时无法取消 线程池中的某个任务执行时间过长，阻塞线程 ThreadPoolExecutor不直接支持任务超时，execute()提交的任务无法cancel 1. 使用Future + timeout：executor.submit().get(timeout)；2. 任务内部自行超时检测；3. ScheduledExecutor定期扫描超时任务
9 任务优先级无法控制 紧急告警任务排在普通采集任务后面，延迟处理 LinkedBlockingQueue是FIFO队列，无法按优先级出队 1. 使用PriorityBlockingQueue + Comparable任务；2. 紧急任务直接创建核心线程；3. 分离线程池：紧急任务独占池
线程泄漏与死锁问题
# 问题 现象 根因 解决方案
10 CallerRunsPolicy导致死锁 线程池A的拒绝策略是CallerRunsPolicy，调用线程恰好是线程池B的Worker，线程池B也被阻塞 两个线程池互相依赖，CallerRunsPolicy导致调用线程被阻塞，形成死锁 1. 避免线程池嵌套调用；2. 嵌套调用时内层使用DiscardPolicy或独立线程池；3. 线程池间不要用CallerRunsPolicy
11 ThreadLocal内存泄漏 线程池线程复用，ThreadLocal值不清理，导致内存泄漏和数据串用 线程池线程长期存活，ThreadLocal.set()后未remove()，值一直积累 1. 任务结束前必须调用ThreadLocal.remove()；2. 使用try-finally确保清理；3. 使用TransmittableThreadLocal替代
12 线程池关闭时任务丢失 直接kill进程，队列中未执行的任务丢失 kill -9不会触发shutdown钩子，JVM直接退出，队列任务丢失 1. 使用kill -15（SIGTERM）；2. 实现优雅关闭（shutdown + awaitTermination）；3. 持久化关键任务，重启后补偿
运维与环境问题
# 问题 现象 根因 解决方案
13 线程上下文切换过高 CPU利用率高但吞吐量低，vmstat显示cs超过100万&#x2F;秒 线程数远超CPU核心数，大量时间花在上下文切换而非任务执行 1. 减少线程数至公式计算值；2. 区分CPU&#x2F;IO密集型；3. 使用vmstat&#x2F;pidstat监控cs指标；4. 减少锁竞争
14 线程池参数无法动态调整 需要修改线程池参数时必须重启应用 使用硬编码配置，未接入配置中心 1. 接入Nacos配置中心+@RefreshScope；2. 使用ResizableCapacityLinkedBlockingQueue；3. 实现动态调参接口
15 多实例线程池总线程数不可控 10个实例每个maxPoolSize&#x3D;50，总线程数可达500，超过数据库连接池 只考虑单实例线程数，忽略集群总线程数对下游的影响 1. 线程数 &lt;&#x3D; 数据库连接池&#x2F;实例数；2. 使用Nacos按实例数动态分配；3. 全局限流保护下游
线程池参数对比与选型不同队列类型对比
队列类型 特点 优点 缺点
LinkedBlockingQueue 链表实现 吞吐量高 默认无界！OOM风险
(有界) FIFO 无固定容量限制 需手动指定容量
ArrayBlockingQueue 数组实现 有界（必须指定） 吞吐量略低于链表
SynchronousQueue 容量为0 直接提交，无缓冲 无缓冲能力
PriorityBlockingQueue 优先级排序 支持优先级出队 任务需实现Comparable
DelayedWorkQueue 延迟出队 支持定时&#x2F;延迟执行 仅ScheduledPool用
不同线程池类型对比
Executors工厂方法 核心参数 适用场景 风险
newFixedThreadPool core&#x3D;max&#x3D;指定值 负载较重的场景 无界队列！任务堆积OOM
newCachedThreadPool core&#x3D;0 短期异步任务 max&#x3D;MAX_VALUE！线程爆炸OOM
newSingleThreadPool core&#x3D;max&#x3D;1 顺序执行任务 无界队列！任务堆积OOM
newScheduledThreadPool core&#x3D;指定值 定时&#x2F;周期任务 DelayedWorkQueue无界
线程池压测方法JMH 微基准测试@BenchmarkMode(Mode.Throughput)@OutputTimeUnit(TimeUnit.SECONDS)@State(Scope.Benchmark)public class ThreadPoolBenchmark &#123; private ThreadPoolExecutor ioIntensivePool; private ThreadPoolExecutor cpuIntensivePool; @Setup public void setup() &#123; // IO密集型线程池：8核 × (1+3) = 32 ioIntensivePool = new ThreadPoolExecutor( 32, 64, 60, TimeUnit.SECONDS, new LinkedBlockingQueue&lt;&gt;(1000), new CustomThreadFactory(&quot;bench-io&quot;), new ThreadPoolExecutor.CallerRunsPolicy() ); // CPU密集型线程池：8 + 1 = 9 cpuIntensivePool = new ThreadPoolExecutor( 9, 18, 60, TimeUnit.SECONDS, new LinkedBlockingQueue&lt;&gt;(500), new CustomThreadFactory(&quot;bench-cpu&quot;), new ThreadPoolExecutor.CallerRunsPolicy() ); &#125; @Benchmark public void ioIntensiveTask() throws Exception &#123; ioIntensivePool.submit(() -&gt; &#123; try &#123; Thread.sleep(50); // 模拟IO等待50ms &#125; catch (InterruptedException e) &#123; Thread.currentThread().interrupt(); &#125; &#125;).get(); &#125; @Benchmark public void cpuIntensiveTask() throws Exception &#123; cpuIntensivePool.submit(() -&gt; &#123; // 模拟CPU计算：计算斐波那契数列 long result = 0; for (int i = 0; i &lt; 10000; i++) &#123; result += i * i; &#125; &#125;).get(); &#125; @TearDown public void teardown() &#123; ioIntensivePool.shutdown(); cpuIntensivePool.shutdown(); &#125;&#125;
